            if (HasArg(args, "--migrate-character-profiles") || HasArg(args, "--regenerate-character-personalities"))
            {
                Dictionary<string, object> result = MigrateCharacterProfilesToCurrentModels(args ?? new string[0]);
                result["operation"] = HasArg(args, "--regenerate-character-personalities") ? "regenerate_character_personalities" : "migrate_character_profiles";
                Console.WriteLine(Json.Serialize(result));
                Environment.ExitCode = ReadBool(result, "ok", false) ? 0 : 1;
                return;
            }

            if (HasArg(args, "--run-tests"))
            {
                Dictionary<string, object> cliResult = RunTestsCli(args ?? new string[0]);
                Console.WriteLine(HasArg(args, "--json") ? Json.Serialize(cliResult) : FormatTestCliResult(cliResult));
                return;
            }

            Dictionary<string, object> settings = LoadSettings();
            int port = ReadPort(args, settings);
            ReignPostgreSqlStorage.EnsureInfrastructure();
            Console.WriteLine("ReignServer database versioning check completed. Schema version "
                + ReignPostgreSqlStorage.DatabaseSchemaVersion + ".");
            InitializeCharacterProfileLibrary();
            Directory.CreateDirectory(DataDir);
            ActiveServerPort = port;

            TcpListener listener = new TcpListener(IPAddress.Loopback, port);
            try
            {
                listener.Start();
            }
            catch (SocketException ex) when (ex.SocketErrorCode == SocketError.AddressAlreadyInUse)
            {
                HandlePortAlreadyInUse(port, args, ex);
                return;
            }

            InitializeReignTelemetry(settings);
            StartPriorityBackgroundScheduler();
            StartContinuousRelationshipWorker();
            StartWorldTestRollupWorker();
            ResumePendingMemoryBackgroundJobs();
            ResumePendingReputationReasonJobs();
            StartSemanticMemorySubsystem(settings);
            ProcessPendingCampaignRetirementsAtStartup();
            ResumePendingSaveSyncOptimizations();

            Console.WriteLine("Bannerlord Reign Server is running.");
            Console.WriteLine("Listening on http://127.0.0.1:" + port);
            Console.WriteLine("Managed by ReignServer.");
            Console.WriteLine();

            LogOperational("server.start", new Dictionary<string, object>
            {
                ["port"] = port,
                ["dataDir"] = DataDir,
                ["settingsPath"] = SettingsPath
            });

            ShutdownRequested = false;
            StartCampaignRetirementMonitor();
            ActiveListener = listener;
            using var terminate = System.Runtime.InteropServices.PosixSignalRegistration.Create(
                System.Runtime.InteropServices.PosixSignal.SIGTERM,
                context => { context.Cancel = true; RequestServerShutdown("dwemerdistro"); });
            using var interrupt = System.Runtime.InteropServices.PosixSignalRegistration.Create(
                System.Runtime.InteropServices.PosixSignal.SIGINT,
                context => { context.Cancel = true; RequestServerShutdown("dwemerdistro"); });

            try
            {
                while (!ShutdownRequested)
                {
                    try
                    {
                        TcpClient client = listener.AcceptTcpClient();
                        Task.Run(() => HandleClient(client));
                    }
                    catch (SocketException) when (ShutdownRequested)
                    {
                        break;
                    }
                    catch (ObjectDisposedException) when (ShutdownRequested)
                    {
                        break;
                    }
                }
            }
            finally
            {
                ActiveListener = null;
                try { listener.Stop(); } catch { }
                if (DeleteAllCampaignDataPending) DeleteAllCampaignResponseSent.Wait(5000);
                StopSemanticMemorySubsystem();
                if (DeleteAllCampaignDataPending)
                {
                    CampaignDataGate.EnterWriteLock();
                    try
                    {
                        CompleteDeleteAllCampaignData();
                    }
                    finally
                    {
                        DeleteAllCampaignDataPending = false;
                        DeleteAllCampaignResponseSent.Set();
                        CampaignDataGate.ExitWriteLock();
                    }
                }
                LogOperational("server.stop", new Dictionary<string, object> { ["port"] = port, ["requestedFromUi"] = ShutdownRequested });
                ActiveServerPort = 0;
            }
        }

        private static Dictionary<string, object> RequestServerShutdown(string source = "control_center")
        {
            if (ShutdownRequested)
            {
                return new Dictionary<string, object> { ["ok"] = true, ["status"] = "stopping" };
            }

            ShutdownRequested = true;
            StopCodexAppServer();
            LogOperational("server.shutdown_requested", new Dictionary<string, object> { ["source"] = source ?? "control_center" });
            TcpListener listener = ActiveListener;
            IPEndPoint endpoint = listener?.LocalEndpoint as IPEndPoint;
            Thread shutdownThread = new Thread(() =>
            {
                Thread.Sleep(100);
                if (endpoint != null)
                {
                    try
                    {
                        using (TcpClient wake = new TcpClient()) wake.Connect(IPAddress.Loopback, endpoint.Port);
                    }
                    catch { }
                }
                try { listener?.Server?.Close(); } catch { }
                try { listener?.Stop(); } catch { }
            }) { IsBackground = true, Name = "ReignServerShutdown" };
            shutdownThread.Start();
            return new Dictionary<string, object> { ["ok"] = true, ["status"] = "stopping" };
        }

        private static void HandlePortAlreadyInUse(int port, string[] args, SocketException ex)
        {
            string url = "http://127.0.0.1:" + port + "/";
            bool healthy = IsExistingServerHealthy(port);
            bool activated = TryActivateExistingServer(port, args, healthy);
            Console.WriteLine("Bannerlord Reign Server did not start a second copy.");
            Console.WriteLine("Port " + port + " is already in use.");
            if (healthy)
            {
                Console.WriteLine("An existing Bannerlord Reign server is already running.");
                Console.WriteLine("Opened the existing control center and brought its server window forward:");
                Console.WriteLine(url);
                LogOperational("server.already_running", new Dictionary<string, object>
                {
                    ["port"] = port,
                    ["url"] = url,
                    ["activated"] = activated
                });
                return;
            }

            if (activated)
            {
                Console.WriteLine("The existing Reign server is not answering health checks.");
                Console.WriteLine("Its terminal window was brought forward so it can be inspected or closed.");
                Console.WriteLine("The Control Center address is:");
                Console.WriteLine(url);
                LogOperational("server.unresponsive_instance_activated", new Dictionary<string, object>
                {
                    ["port"] = port,
                    ["url"] = url
                });
                return;
            }

            Console.WriteLine("Something else is using this port, or the existing server is not responding.");
            Console.WriteLine("Close the other process or change the server port in settings.");
            Console.WriteLine("Socket error: " + ex.Message);
            LogOperational("server.port_in_use", new Dictionary<string, object>
            {
                ["port"] = port,
                ["error"] = ex.Message
            });
        }

        private static bool IsExistingServerHealthy(int port)
        {
            for (int attempt = 0; attempt < 3; attempt++)
            {
                try
                {
                    HttpWebRequest request = (HttpWebRequest)WebRequest.Create("http://127.0.0.1:" + port + "/health");
                    request.Method = "GET";
                    request.Timeout = 1200;
                    request.ReadWriteTimeout = 1200;
                    using (HttpWebResponse response = (HttpWebResponse)request.GetResponse())
                    using (Stream stream = response.GetResponseStream())
                    using (StreamReader reader = new StreamReader(stream ?? Stream.Null, Encoding.UTF8))
                    {
                        string body = reader.ReadToEnd();
                        return response.StatusCode == HttpStatusCode.OK
                            && body.IndexOf("BannerlordReignServer", StringComparison.OrdinalIgnoreCase) >= 0;
                    }
                }
                catch
                {
                    if (attempt < 2) Thread.Sleep(150);
                }
            }

            return false;
        }

        private static int ReadPort(string[] args, Dictionary<string, object> settings)
        {
            for (int i = 0; i < args.Length - 1; i++)
            {
                if (args[i].Equals("--port", StringComparison.OrdinalIgnoreCase) && int.TryParse(args[i + 1], out int port))
                {
                    return port;
                }
            }

            return ReadInt(settings, "port", 5101);
        }

        private static bool HasArg(string[] args, string value)
        {
            return args.Any(x => x.Equals(value, StringComparison.OrdinalIgnoreCase));
        }

        private static void HandleClient(TcpClient client)
        {
            CampaignRequestAccess campaignAccess = CampaignRequestAccess.None;
            bool deleteAllResponsePending = false;
            using (client)
            using (NetworkStream stream = client.GetStream())
            {
                HttpRequest request = null;
                ConversationDiagnosticRequest diagnosticRequest = null;
                try
                {
                    request = ReadRequest(stream);
                    if (request == null)
                    {
                        return;
                    }

                    if (!string.IsNullOrEmpty(request.ReignProtocol)
                        && request.ReignProtocol != Reign.Core.Contracts.Platform.ReignInstallation.SupportedProtocol.ToString(CultureInfo.InvariantCulture))
                        throw new InvalidDataException("Reign and ReignServer use different protocols. Install the matching Reign package.");
                    campaignAccess = EnterCampaignRequestAccess(request.Path);
                    diagnosticRequest = new ConversationDiagnosticRequest(request.Path, request.JsonBody);

                    object response;
                    int status = 200;

                    if (request.Method == "GET" && (request.Path == "/" || request.Path == "/index.html"))
                    {
                        WriteHtml(stream, ControlCenterHtml());
                        LogRequest(request, 200);
                        return;
                    }
                    else if (request.Method == "GET" && request.Path == "/assets/reign-icon.webp")
                    {
                        WriteFile(stream, Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "ui", "assets", "reign-icon.webp"), "image/webp");
                        LogRequest(request, 200);
                        return;
                    }
                    else if (request.Method == "GET" && request.Path == "/assets/ReignLogo.png")
                    {
                        WriteFile(stream, Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "ui", "assets", "ReignLogo.png"), "image/png");
                        LogRequest(request, 200);
                        return;
                    }
                    else if (request.Method == "GET" && request.Path == "/character-editor/portrait")
                    {
                        string campaignId = request.Query.ContainsKey("campaignId") ? request.Query["campaignId"] : LatestCampaignId();
                        string heroId = request.Query.ContainsKey("heroStringId") ? request.Query["heroStringId"] : "";
                        string variant = request.Query.ContainsKey("variant") ? SafePathSegment(request.Query["variant"], "active") : "active";
                        WriteFile(stream, ResolveCharacterEditorPortraitPath(campaignId, heroId, variant), "image/png");
                        LogRequest(request, 200);
                        return;
                    }
                    else if (request.Method == "GET" && request.Path == "/health")
                    {
                        response = new Dictionary<string, object>
                        {
                            ["ok"] = true,
                            ["service"] = "BannerlordReignServer",
                            ["databaseName"] = ReignPostgreSqlOptions.FromEnvironment().Database,
                            ["databaseSchemaVersion"] = ReignPostgreSqlStorage.DatabaseSchemaVersion,
                            ["requiredDatabaseSchemaVersion"] = ReignPostgreSqlStorage.RequiredDatabaseSchemaVersion,
                            ["databaseSchemaUpToDate"] = ReignPostgreSqlStorage.DatabaseSchemaVersion == ReignPostgreSqlStorage.RequiredDatabaseSchemaVersion,
                            ["protocolVersion"] = Reign.Core.Contracts.Platform.ReignInstallation.SupportedProtocol,
                            ["serverVersion"] = Reign.Core.Contracts.Platform.ReignInstallation.TryLoadCurrent()?.Version ?? typeof(Program).Assembly.GetName().Version.ToString(3),
                            ["contentVersion"] = Reign.Core.Contracts.Platform.ReignInstallation.TryLoadCurrent()?.ContentVersion ?? "development",
