                    }
                    else if (request.Method == "POST" && request.Path == "/llm/chat")
                    {
                        response = ChatWithLlm(request.JsonBody);
                    }
                    else
                    {
                        status = 404;
                        response = new Dictionary<string, object> { ["ok"] = false, ["error"] = "Unknown route." };
                    }

                    WriteJson(stream, status, response);
                    diagnosticRequest?.Delivered(status);
                    LogRequest(request, status);
                    if (deleteAllResponsePending) DeleteAllCampaignResponseSent.Set();
                }
                catch (DirectoryNotFoundException ex)
                {
                    // DirectoryNotFoundException derives from IOException, but it
                    // represents a server-side storage fault rather than a client
                    // disconnect. Preserve the full diagnostic and return a normal
                    // failure response so callers do not see a misleading socket
                    // reset with no actionable cause.
                    LogOperational("server.error", new Dictionary<string, object>
                    {
                        ["method"] = request?.Method ?? string.Empty,
                        ["path"] = request?.Path ?? string.Empty,
                        ["exceptionType"] = ex.GetType().Name,
                        ["error"] = ex.ToString()
                    });
                    try
                    {
                        WriteJson(stream, 500, new Dictionary<string, object>
                        {
                            ["ok"] = false,
                            ["error"] = ex.Message
                        });
                    }
                    catch (IOException writeException)
                    {
                        LogOperational("server.client_disconnect", new Dictionary<string, object>
                        {
                            ["method"] = request?.Method ?? string.Empty,
                            ["path"] = request?.Path ?? string.Empty,
                            ["exceptionType"] = writeException.GetType().Name,
                            ["duringErrorResponse"] = true
                        });
                    }
                    if (deleteAllResponsePending) DeleteAllCampaignResponseSent.Set();
                }
                catch (IOException ex)
                {
                    LogOperational("server.client_disconnect", new Dictionary<string, object>
                    {
                        ["method"] = request?.Method ?? string.Empty,
                        ["path"] = request?.Path ?? string.Empty,
                        ["exceptionType"] = ex.GetType().Name
                    });
                    if (deleteAllResponsePending) DeleteAllCampaignResponseSent.Set();
                }
                catch (SocketException ex)
                {
                    LogOperational("server.client_disconnect", new Dictionary<string, object>
                    {
                        ["method"] = request?.Method ?? string.Empty,
                        ["path"] = request?.Path ?? string.Empty,
                        ["exceptionType"] = ex.GetType().Name
                    });
                    if (deleteAllResponsePending) DeleteAllCampaignResponseSent.Set();
                }
                catch (Exception ex)
                {
                    LogOperational("server.error", new Dictionary<string, object> { ["error"] = ex.ToString() });
                    try
                    {
                        WriteJson(stream, 500, new Dictionary<string, object> { ["ok"] = false, ["error"] = ex.Message });
                    }
                    catch (IOException writeException)
                    {
                        LogOperational("server.client_disconnect", new Dictionary<string, object>
                        {
                            ["method"] = request?.Method ?? string.Empty,
                            ["path"] = request?.Path ?? string.Empty,
                            ["exceptionType"] = writeException.GetType().Name,
                            ["duringErrorResponse"] = true
                        });
                    }
                    if (deleteAllResponsePending) DeleteAllCampaignResponseSent.Set();
                }
                finally
                {
                    diagnosticRequest?.Dispose();
                    ExitCampaignRequestAccess(campaignAccess);
                }
            }
        }

        private static CampaignRequestAccess EnterCampaignRequestAccess(string path)
        {
            path = path ?? string.Empty;
            bool isLiveTestPath = path.Equals("/tests/live", StringComparison.OrdinalIgnoreCase)
                || path.StartsWith("/tests/live/", StringComparison.OrdinalIgnoreCase);
            if (path.StartsWith("/save-sync/", StringComparison.OrdinalIgnoreCase)
                || path.StartsWith("/api/save-sync/", StringComparison.OrdinalIgnoreCase)
                || path == "/api/campaigns/export"
                || path == "/api/campaigns/import"
                || path == "/api/campaigns/delete"
                || path == "/api/campaigns/delete-all"
                || path == "/api/campaigns/cleanup-zero-save"
                || (path.StartsWith("/tests/", StringComparison.OrdinalIgnoreCase)
                    && !isLiveTestPath)
                || path.StartsWith("/verification/", StringComparison.OrdinalIgnoreCase))
                return CampaignRequestAccess.None;

            CampaignDataGate.EnterReadLock();
            CurrentCampaignRequestLease = new CampaignRequestLease
            {
                Generation = Interlocked.Read(ref CampaignReplacementGeneration)
            };
            return CampaignRequestAccess.Read;
        }

        private static void ExitCampaignRequestAccess(CampaignRequestAccess access)
        {
            if (access == CampaignRequestAccess.Write) CampaignDataGate.ExitWriteLock();
            else if (access == CampaignRequestAccess.Read) CampaignDataGate.ExitReadLock();
            CurrentCampaignRequestLease = null;
        }

        private static Dictionary<string, object> IngestEvent(Dictionary<string, object> payload)
        {
            string campaignId = ReadString(payload, "campaignId", "default");
            string eventType = ReadString(payload, "eventType", "unknown");
            List<string> actorIds = ReadStringList(payload, "actorIds");
            string locationId = ReadString(payload, "locationId", "");
            string summary = ReadString(payload, "summary", ReadString(payload, "text", ""));
            List<string> tags = SimpleTags(summary);
            long id = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();

            Dictionary<string, object> row = new Dictionary<string, object>
            {
                ["id"] = id,
                ["ts"] = DateTimeOffset.UtcNow.ToUnixTimeSeconds(),
                ["campaignId"] = campaignId,
                ["eventType"] = eventType,
                ["actorIds"] = actorIds,
                ["locationId"] = locationId,
                ["payload"] = payload
            };

            AppendJsonLineToPath(CampaignFile(campaignId, "world", "events.jsonl"), row);
            bool volatileCurrentState =
                ReadBool(payload, "volatileCurrentState", false)
                || eventType.Equals(
                    "daily_world_snapshot",
                    StringComparison.OrdinalIgnoreCase);
            Dictionary<string, object> memoryPayload = new Dictionary<string, object>(payload ?? new Dictionary<string, object>(), StringComparer.OrdinalIgnoreCase)
            {
                ["campaignId"] = campaignId,
                ["eventId"] = Convert.ToString(id, CultureInfo.InvariantCulture),
                ["ts"] = ReadLong(row, "ts", DateTimeOffset.UtcNow.ToUnixTimeSeconds()),
                ["eventType"] = eventType,
                ["participants"] = actorIds,
                ["known_by"] = actorIds,
                ["locationId"] = locationId,
                ["summary"] = summary,
                ["tags"] = tags
            };
            Dictionary<string, object> memoryStore;
            if (volatileCurrentState)
            {
                WriteJsonObject(
                    CampaignFile(
                        campaignId, "world",
                        "current_native_world_state.json"),
                    memoryPayload);
                memoryStore = new Dictionary<string, object>
                {
                    ["ok"] = true,
                    ["stored"] = false,
                    ["reason"] =
                        "volatile_current_state_not_durable_memory"
                };
            }
            else
            {
                memoryStore = StoreWorldMemoryEvent(
                    memoryPayload, "events_ingest");
            }

            foreach (string ownerId in volatileCurrentState
                ? new List<string>()
                : actorIds)
            {
                if (!string.IsNullOrWhiteSpace(summary))
                {
                    Dictionary<string, object> memoryRow = new Dictionary<string, object>
                    {
                        ["id"] = Guid.NewGuid().ToString("N"),
                        ["ts"] = DateTimeOffset.UtcNow.ToUnixTimeSeconds(),
                        ["campaignId"] = campaignId,
                        ["ownerId"] = ownerId,
                        ["tags"] = tags,
                        ["text"] = summary,
                        ["sourceEventId"] = id
                    };
                    AppendJsonLineToPath(CampaignFile(campaignId, "world", "memories.jsonl"), memoryRow);
                    if (!string.IsNullOrWhiteSpace(ownerId))
                    {
                        AppendJsonLineToPath(CharacterFile(campaignId, ownerId, "memory", "memories.jsonl"), memoryRow);
                    }
                }
            }

            Console.WriteLine("Ingested event " + eventType + " campaign=" + campaignId + " tags=" + string.Join(",", tags));
            LogOperational("event.ingest", new Dictionary<string, object>
            {
                ["eventId"] = id,
                ["campaignId"] = campaignId,
                ["eventType"] = eventType,
                ["actorIds"] = actorIds,
                ["locationId"] = locationId,
                ["tags"] = tags
            });
            return new Dictionary<string, object> { ["ok"] = true, ["eventId"] = id, ["tags"] = tags, ["memoryStore"] = memoryStore };
        }

        private static Dictionary<string, object> BuildContext(Dictionary<string, object> payload)
        {
            string campaignId = ReadString(payload, "campaignId", "default");
            List<string> actorIds = ReadStringList(payload, "actorIds");
            string query = ReadString(payload, "query", "");
            int limit = ReadInt(payload, "limit", 12);
            List<string> queryTags = SimpleTags(query);

            List<Dictionary<string, object>> memories = ReadCampaignMemoryLines(campaignId, actorIds)
                .Where(x => actorIds.Count == 0 || actorIds.Contains(ReadString(x, "ownerId", "")))
                .Where(x => queryTags.Count == 0 || ReadStringList(x, "tags").Any(queryTags.Contains))
                .OrderByDescending(x => ReadLong(x, "ts", 0))
                .Take(limit)
                .ToList();

            LogOperational("context.build", new Dictionary<string, object>
            {
                ["campaignId"] = campaignId,
                ["actorIds"] = actorIds,
                ["queryTags"] = queryTags,
                ["resultCount"] = memories.Count
            });

            return new Dictionary<string, object>
            {
                ["ok"] = true,
                ["queryTags"] = queryTags,
                ["memories"] = memories
            };
        }

        private static Dictionary<string, object> MemoryEventApi(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            Dictionary<string, object> stored = StoreWorldMemoryEvent(payload, "memory_event_api");
            string campaignId = ReadString(payload, "campaignId", "default");
            LogOperational("memory.event", new Dictionary<string, object>
            {
                ["campaignId"] = campaignId,
                ["eventId"] = ReadString(stored, "eventId", ""),
                ["eventType"] = ReadFirstString(payload, "eventType", "event_type", "type"),
                ["memoryCount"] = ReadInt(stored, "memoryCount", 0)
            });
            return stored;
        }

        private static Dictionary<string, object> MemoryConversationFinishedApi(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", "default");
            string npcId = ReadFirstString(payload, "npcId", "heroStringId", "heroId", "speakerHeroStringId");
            string playerId = ReadFirstString(payload, "playerId", "mainHeroStringId");
            string text = ReadFirstString(payload, "conversationText", "conversation_text", "summary", "text");
            Dictionary<string, object> evt = new Dictionary<string, object>(payload, StringComparer.OrdinalIgnoreCase)
            {
                ["campaignId"] = campaignId,
                ["eventType"] = ReadFirstString(payload, "eventType", "event_type", "type")
            };
            if (string.IsNullOrWhiteSpace(ReadString(evt, "eventType", "")))
            {
                evt["eventType"] = "conversation_finished";
            }

            evt["summary"] = string.IsNullOrWhiteSpace(text) ? "Conversation finished." : LimitText(text, 1200);
            evt["participants"] = MergeStringLists(ReadStringList(payload, "participants"), new[] { npcId, playerId });
            evt["known_by"] = MergeStringLists(ReadStringList(payload, "known_by"), new[] { npcId, playerId });
            evt["visibility"] = ReadString(payload, "visibility", "private");
            evt["importance"] = ReadDouble(payload, "importance", 0.5d);
            long ts = ReadLong(payload, "ts", DateTimeOffset.UtcNow.ToUnixTimeSeconds());
            string groupKey = BuildMemoryGroupKey(payload, npcId, playerId, ReadFirstString(payload, "locationId", "currentSettlementId", "settlementId"), "conversation", ts);
            evt["memoryGroupKey"] = groupKey;
            Dictionary<string, object> stored = StoreWorldMemoryEvent(evt, "memory_conversation_finished");
            stored["consolidation"] = ConsolidateNpcMemory(campaignId, npcId, true, groupKey);
            return stored;
        }

        private static Dictionary<string, object> MemoryActionResultApi(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            return StoreActionResultMemory(payload, "memory_action_result_api");
        }

        private static Dictionary<string, object> MemoryBuildContextApi(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", "default");
            string npcId = ReadFirstString(payload, "npcId", "heroStringId", "heroId", "speakerHeroStringId", "characterId");
            string playerId = ReadFirstString(payload, "playerId", "mainHeroStringId");
            string locationId = ReadFirstString(payload, "locationId", "currentSettlementId", "settlementId");
            string topic = ReadFirstString(payload, "currentTopic", "current_topic", "query", "playerText", "text", "message");
            int tokenBudget = Math.Max(400, Math.Min(8000, ReadInt(payload, "tokenBudget", ReadInt(payload, "token_budget", 2500))));

            Dictionary<string, object> packet = BuildNpcMemoryPacket(campaignId, npcId, playerId, locationId, topic, tokenBudget, payload);
            packet["ok"] = true;
            packet["campaignId"] = campaignId;
            packet["npcId"] = npcId;
            packet["playerId"] = playerId;
            return packet;
        }

        private static Dictionary<string, object> MemoryConsolidateApi(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", "default");
            string npcId = ReadFirstString(payload, "npcId", "heroStringId", "heroId", "speakerHeroStringId", "characterId");
            if (string.IsNullOrWhiteSpace(npcId))
            {
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "npcId or heroStringId is required." };
            }

            string groupKey = ReadFirstString(payload, "memoryGroupKey", "groupKey", "conversationId", "sceneId", "eventId");
            return ConsolidateNpcMemory(campaignId, npcId, ReadBool(payload, "force", true), groupKey);
        }

        private static string CampaignMemoryDbPath(string campaignId)
        {
            return "postgresql://"
                + ReignPostgreSqlOptions.RequiredDatabaseName + "/"
                + ReignPostgreSqlStorage.CampaignSchemaName(campaignId);
        }

        private static bool HasCampaignPostgreSqlStorage(string campaignId)
        {
            try
            {
                return ReignPostgreSqlStorage.CampaignExists(campaignId);
            }
            catch
            {
                return false;
            }
        }

        private static ReignDbConnection OpenCampaignConnection(string campaignId)
        {
            Directory.CreateDirectory(CampaignDirectory(campaignId));
            ReignDbConnection connection = ReignPostgreSqlStorage.OpenCampaignConnection(campaignId);
            lock (CampaignSchemaLock)
            {
                string schemaKey = ReignPostgreSqlStorage.CampaignSchemaName(campaignId);
                bool cachedReady = CampaignSchemaReady.Contains(schemaKey);
                if (cachedReady && !IsMemorySchemaRevisionCurrent(connection))
                {
                    // Save Sync can replace the schema beneath a pooled
                    // connection. Keep the normal checkout guard to one
                    // indexed metadata read, but force the complete migration
                    // path whenever the restored schema revision is stale.
                    CampaignSchemaReady.Remove(schemaKey);
                    InvalidateCampaignSchemaCaches(campaignId);
                    cachedReady = false;
                }
                if (!cachedReady)
                {
                    EnsureMemorySchema(connection);
                    EnsureCategorizedMemorySchema(connection);
                    EnsureWorldHistorySchema(connection);
                    EnsureSemanticMemorySchema(connection);
                    RunCategorizedMemoryMigration(connection, campaignId);
                    // Older malformed provider responses could turn scalar
                    // collection entries into dialogue memories such as "0".
                    // Repair an affected save once when this process validates
                    // the campaign schema; normal foreground reads remain free
                    // of an extra write transaction.
                    ExecuteSql(connection, @"DELETE FROM memories
WHERE source='dialogue_llm'
  AND lower(trim(summary)) IN ('0','1','true','false','null','undefined');");
                    ReignPostgreSqlStorage.DeduplicateCampaignIndexes(
                        campaignId);
                    CampaignSchemaReady.Add(schemaKey);
                }
            }
            return connection;
        }

        private static bool IsMemorySchemaRevisionCurrent(
            ReignDbConnection connection)
        {
            try
            {
                Dictionary<string, object> version = QuerySql(connection,
                    "SELECT value FROM schema_meta WHERE key='version' LIMIT 1;")
                    .FirstOrDefault();
                return string.Equals(ReadString(version, "value", ""), "5",
                    StringComparison.Ordinal) && QuerySql(connection,"SELECT value FROM schema_meta WHERE key='memory_precision_v1' AND value='complete';").Count==1;
            }
            catch
            {
                return false;
            }
        }

        private static bool IsPostgreSqlComponentSchemaReady(
            ReignDbConnection connection, string markerKey, int revision)
        {
            if (!ReignPostgreSqlDialect.IsPostgreSql(connection))
                return false;
            string campaignId =
                ReignPostgreSqlStorage.CampaignIdForConnection(connection);
            string fastPathKey = campaignId + "|" + markerKey + "|"
                + revision.ToString(CultureInfo.InvariantCulture);
            if (!string.IsNullOrWhiteSpace(campaignId)
                && PostgreSqlComponentSchemaFastPaths.ContainsKey(
                    fastPathKey))
                return true;
            string persisted = ReadString(QuerySql(connection, @"
SELECT value FROM schema_meta WHERE key=$key LIMIT 1;",
                new Dictionary<string, object>
                {
                    ["key"] = markerKey
                }).FirstOrDefault(), "value", "");
            bool ready = persisted.Equals(
                revision.ToString(CultureInfo.InvariantCulture),
                StringComparison.Ordinal);
            if (ready && !string.IsNullOrWhiteSpace(campaignId))
                PostgreSqlComponentSchemaFastPaths[fastPathKey] = 0;
            return ready;
        }

        private static void MarkPostgreSqlComponentSchemaReady(
            ReignDbConnection connection, string markerKey, int revision)
        {
            if (!ReignPostgreSqlDialect.IsPostgreSql(connection))
                return;
            string campaignId =
                ReignPostgreSqlStorage.CampaignIdForConnection(connection);
            if (string.IsNullOrWhiteSpace(campaignId))
                return;
            PostgreSqlComponentSchemaFastPaths[campaignId + "|"
                + markerKey + "|"
                + revision.ToString(CultureInfo.InvariantCulture)] = 0;
        }

        internal static void InvalidateCampaignSchemaCaches(
            string campaignId)
        {
            if (string.IsNullOrWhiteSpace(campaignId))
                return;
            string schemaKey =
                ReignPostgreSqlStorage.CampaignSchemaName(campaignId);
            lock (CampaignSchemaLock)
                CampaignSchemaReady.Remove(schemaKey);
            string prefix = campaignId + "|";
            foreach (string key in PostgreSqlComponentSchemaFastPaths.Keys
                .Where(value => value.StartsWith(prefix,
                    StringComparison.OrdinalIgnoreCase)))
                PostgreSqlComponentSchemaFastPaths.TryRemove(key,
                    out byte ignored);
            InvalidateRelationshipPairStateCache(campaignId);
            InvalidateRelationshipPermanentMbtiCache(campaignId);
        }

        private static bool IsMemorySchemaCurrent(ReignDbConnection connection)
        {
            try
            {
                Dictionary<string, object> version = QuerySql(connection,
                    "SELECT value FROM schema_meta WHERE key='version' LIMIT 1;").FirstOrDefault();
                if (!string.Equals(ReadString(version, "value", ""), "5", StringComparison.Ordinal))
                    return false;

                int requiredTables = ReadInt(QuerySql(connection, @"SELECT COUNT(*) AS count
FROM information_schema.tables
WHERE table_schema=current_schema() AND table_name IN (
'group_conversation_state',
'group_conversation_contributions',
'temporal_knowledge_assertions',
'memory_background_jobs',
'dynamic_characteristics',
'rebellion_movements',
'rebellion_memberships',
'rebellion_transitions',
'negotiated_action_drafts',
'negotiated_action_approvals');").FirstOrDefault(), "count", 0);
                bool compactTurnPayloads = string.Equals(ReadString(QuerySql(connection,
                    "SELECT value FROM schema_meta WHERE key='conversation_turn_payload_v2' LIMIT 1;")
                    .FirstOrDefault(), "value", ""), "complete", StringComparison.OrdinalIgnoreCase);
                bool precision = string.Equals(ReadString(QuerySql(connection,
                    "SELECT value FROM schema_meta WHERE key='memory_precision_v1';").FirstOrDefault(), "value", ""), "complete", StringComparison.Ordinal);
                return requiredTables == 10 && compactTurnPayloads && precision;
            }
            catch
            {
                return false;
            }
        }

