        private static void EnsureDatabaseColumn(ReignDbConnection connection, string table, string column, string definition)
        {
            if (!Regex.IsMatch(table ?? string.Empty, @"^[A-Za-z_][A-Za-z0-9_]*$")
                || !Regex.IsMatch(column ?? string.Empty, @"^[A-Za-z_][A-Za-z0-9_]*$"))
            {
                throw new InvalidOperationException("Unsafe database schema identifier.");
            }

            List<Dictionary<string, object>> columns = QuerySql(
                connection,
                @"SELECT column_name AS name
FROM information_schema.columns
WHERE table_schema=current_schema()
  AND table_name=$table
  AND column_name=$column;",
                new Dictionary<string, object>
                {
                    ["table"] = table,
                    ["column"] = column
                });
            if (columns.Count > 0)
            {
                return;
            }

            try
            {
                ExecuteSql(connection, "ALTER TABLE " + table + " ADD COLUMN " + column + " " + definition + ";");
            }
            catch (Exception ex) when (
                ex.Message.IndexOf("duplicate column", StringComparison.OrdinalIgnoreCase) >= 0
                || ex.Message.IndexOf("already exists", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                // Another writer completed the same idempotent schema migration
                // after the information-schema check.
            }
        }

        private static void ExecuteSql(
            ReignDbConnection connection,
            string sql,
            Dictionary<string, object> parameters = null,
            ReignDbTransaction transaction = null)
        {
            ThrowIfCampaignRequestReplaced();
            bool serializePostgreSqlSchemaMutation =
                ReignPostgreSqlDialect.IsPostgreSql(connection)
                && IsPostgreSqlSchemaMutation(sql);
            for (int attempt = 0; ; attempt++)
            {
                ReignDbTransaction ownedSchemaTransaction = null;
                try
                {
                    ReignDbTransaction commandTransaction = transaction;
                    if (serializePostgreSqlSchemaMutation)
                    {
                        if (commandTransaction == null)
                        {
                            try
                            {
                                ownedSchemaTransaction =
                                    connection.BeginTransaction();
                                commandTransaction =
                                    ownedSchemaTransaction;
                            }
                            catch (InvalidOperationException ex) when (
                                ex.Message.IndexOf(
                                    "transaction",
                                    StringComparison.OrdinalIgnoreCase) >= 0)
                            {
                                // Legacy callers can start a transaction with
                                // ExecuteSql("BEGIN;"). In that case the
                                // command automatically enlists in the active
                                // PostgreSQL transaction.
                            }
                        }
                        AcquirePostgreSqlTransactionMutationLock(
                            connection, commandTransaction);
                    }
                    string normalizedSql =
                        ReignPostgreSqlDialect.Normalize(connection, sql);
                    using (ReignDbCommand command = connection.CreateCommand())
                    {
                        command.CommandText = normalizedSql;
                        command.CommandTimeout = 60;
                        // Leaving Transaction untouched preserves implicit enlistment
                        // for callers that begin a local
                        // transaction around shared helpers. Assign only when a caller
                        // passes an explicit transaction object.
                        if (commandTransaction != null)
                            command.Transaction = commandTransaction;
                        AddSqlParameters(command, parameters);
                        command.ExecuteNonQuery();
                    }
                    InvalidateRelationshipPairCacheForMutation(
                        connection, sql, parameters);
                    if (ownedSchemaTransaction != null)
                        ownedSchemaTransaction.Commit();
                    if (ReignPostgreSqlDialect.IsPostgreSql(connection)
                        && normalizedSql.StartsWith(
                            "BEGIN;", StringComparison.OrdinalIgnoreCase))
                    {
                        AcquirePostgreSqlTransactionMutationLock(connection);
                    }
                    if (ReignPostgreSqlDialect.IsPostgreSql(connection))
                    {
                        string campaignId =
                            ReignPostgreSqlStorage.CampaignIdForConnection(connection);
                        if (!string.IsNullOrWhiteSpace(campaignId))
                        {
                            try { MarkSaveSyncActiveStateDirty(campaignId); }
                            catch { }
                        }
                    }
                    return;
                }
                catch (Exception ex) when (IsStalePostgreSqlPreparedPlan(ex)
                    && attempt < 2)
                {
                    ResetPostgreSqlPreparedPlans(connection);
                }
                catch (Exception ex) when (IsTransientDatabaseContention(ex) && attempt < 240)
                {
                    Thread.Sleep(Math.Min(250, 10 + (attempt * 5)));
                }
                finally
                {
                    ownedSchemaTransaction?.Dispose();
                }
            }
        }

        private static bool IsPostgreSqlSchemaMutation(string sql)
        {
            string value = (sql ?? string.Empty).TrimStart();
            return value.StartsWith("CREATE ", StringComparison.OrdinalIgnoreCase)
                || value.StartsWith("ALTER ", StringComparison.OrdinalIgnoreCase)
                || value.StartsWith("DROP ", StringComparison.OrdinalIgnoreCase)
                || value.StartsWith("TRUNCATE ", StringComparison.OrdinalIgnoreCase);
        }

        private static void AcquirePostgreSqlTransactionMutationLock(
            ReignDbConnection connection,
            ReignDbTransaction transaction = null)
        {
            using (ReignDbCommand command = connection.CreateCommand())
            {
                command.CommandText =
                    "SELECT pg_advisory_xact_lock(hashtextextended(current_schema(), 9137));";
                command.CommandTimeout = 180;
                if (transaction != null)
                    command.Transaction = transaction;
                command.ExecuteNonQuery();
            }
        }

        [ThreadStatic] private static SqlReadTimingContext CurrentSqlReadTiming;

        private sealed class SqlReadTimingContext : IDisposable
        {
            private readonly SqlReadTimingContext previous;
            public long SetupTicks, ExecuteTicks, MaterializeTicks, Rows;
            public int Queries;
            private readonly Dictionary<string, Dictionary<string, object>> queryProfiles =
                new Dictionary<string, Dictionary<string, object>>(StringComparer.Ordinal);
            public readonly bool CaptureQueryProfiles = HasArg(Environment.GetCommandLineArgs(), "--run-verification") && ActiveServerPort <= 0;
            public List<Dictionary<string, object>> QueryProfiles => queryProfiles.Values.ToList();
            public double SetupMs => SetupTicks * 1000d / Stopwatch.Frequency;
            public double ExecuteMs => ExecuteTicks * 1000d / Stopwatch.Frequency;
            public double MaterializeMs => MaterializeTicks * 1000d / Stopwatch.Frequency;
            public SqlReadTimingContext() { previous = CurrentSqlReadTiming; CurrentSqlReadTiming = this; }
            public void RecordQuery(string sql, long setup, long execute, long materialize, int rows)
            {
                if (!CaptureQueryProfiles) return;
                // Only statement identity/table names, never parameter values or raw SQL.
                string hash = Sha256Hex(sql);
                if (!queryProfiles.TryGetValue(hash, out var profile))
                {
                    string tables = string.Join(",", System.Text.RegularExpressions.Regex.Matches(sql,
                        @"\b(?:FROM|JOIN)\s+([A-Za-z_][A-Za-z0-9_]*)",
                        System.Text.RegularExpressions.RegexOptions.IgnoreCase)
                        .Cast<System.Text.RegularExpressions.Match>().Select(match => match.Groups[1].Value)
                        .Distinct(StringComparer.OrdinalIgnoreCase).Take(6));
                    queryProfiles[hash] = profile = new Dictionary<string, object>
                    { ["queryHash"] = hash, ["tables"] = tables, ["calls"] = 0, ["rows"] = 0L,
                        ["setupMs"] = 0d, ["executeMs"] = 0d, ["materializeMs"] = 0d };
                }
                profile["calls"] = ReadInt(profile, "calls", 0) + 1;
                profile["rows"] = ReadLong(profile, "rows", 0) + rows;
                profile["setupMs"] = ReadDouble(profile, "setupMs", 0) + setup * 1000d / Stopwatch.Frequency;
                profile["executeMs"] = ReadDouble(profile, "executeMs", 0) + execute * 1000d / Stopwatch.Frequency;
                profile["materializeMs"] = ReadDouble(profile, "materializeMs", 0) + materialize * 1000d / Stopwatch.Frequency;
            }
            public void Dispose() { CurrentSqlReadTiming = previous; }
        }

        private static List<Dictionary<string, object>> QuerySql(
            ReignDbConnection connection,
            string sql,
            Dictionary<string, object> parameters = null,
            ReignDbTransaction transaction = null)
        {
            ThrowIfCampaignRequestReplaced();
            for (int attempt = 0; ; attempt++)
            {
                try
                {
                    List<Dictionary<string, object>> rows = new List<Dictionary<string, object>>();
                    SqlReadTimingContext timing = CurrentSqlReadTiming;
                    long setupStarted = timing == null ? 0 : Stopwatch.GetTimestamp();
                    using (ReignDbCommand command = connection.CreateCommand())
                    {
                        command.CommandText = ReignPostgreSqlDialect.Normalize(connection, sql);
                        command.CommandTimeout = 60;
                        if (transaction != null) command.Transaction = transaction;
                        AddSqlParameters(command, parameters);
                        long executeStarted = timing == null ? 0 : Stopwatch.GetTimestamp();
                        using (ReignDbDataReader reader = command.ExecuteReader())
                        {
                            long materializeStarted = timing == null ? 0 : Stopwatch.GetTimestamp();
                            int fieldCount = reader.FieldCount;
                            string[] columnNames = new string[fieldCount];
                            for (int index = 0; index < fieldCount; index++) columnNames[index] = reader.GetName(index);
                            while (reader.Read())
                            {
                                Dictionary<string, object> row = new Dictionary<string, object>(fieldCount, StringComparer.OrdinalIgnoreCase);
                                for (int index = 0; index < fieldCount; index++)
                                {
                                    row[columnNames[index]] = reader.IsDBNull(index) ? null : reader.GetValue(index);
                                }

                                rows.Add(row);
                            }
                            if (timing != null)
                            {
                                long materializeTicks = Stopwatch.GetTimestamp() - materializeStarted;
                                timing.SetupTicks += executeStarted - setupStarted;
                                timing.ExecuteTicks += materializeStarted - executeStarted;
                                timing.MaterializeTicks += materializeTicks;
                                timing.Queries++;
                                timing.Rows += rows.Count;
                                timing.RecordQuery(sql, executeStarted - setupStarted,
                                    materializeStarted - executeStarted, materializeTicks, rows.Count);
                            }
                        }
                    }
                    return rows;
                }
                catch (Exception ex) when (IsStalePostgreSqlPreparedPlan(ex)
                    && attempt < 2)
                {
                    ResetPostgreSqlPreparedPlans(connection);
                }
                catch (Exception ex) when (IsTransientDatabaseContention(ex) && attempt < 240)
                {
                    Thread.Sleep(Math.Min(250, 10 + (attempt * 5)));
                }
            }
        }

        private static bool IsStalePostgreSqlPreparedPlan(Exception exception)
        {
            Npgsql.PostgresException postgres = exception as Npgsql.PostgresException;
            return postgres != null
                && postgres.SqlState == "0A000"
                && postgres.MessageText.IndexOf("cached plan",
                    StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static void ResetPostgreSqlPreparedPlans(
            ReignDbConnection connection)
        {
            Npgsql.NpgsqlConnection postgres = connection as Npgsql.NpgsqlConnection;
            if (postgres != null) postgres.UnprepareAll();
        }

        private static bool IsTransientDatabaseContention(Exception exception)
        {
            Npgsql.PostgresException postgres = exception as Npgsql.PostgresException;
            return postgres != null
                && (postgres.SqlState == Npgsql.PostgresErrorCodes.SerializationFailure
                    || postgres.SqlState == Npgsql.PostgresErrorCodes.DeadlockDetected
                    || postgres.SqlState == Npgsql.PostgresErrorCodes.LockNotAvailable);
        }

        private static void AddSqlParameters(ReignDbCommand command, Dictionary<string, object> parameters)
        {
            foreach (KeyValuePair<string, object> pair in parameters ?? new Dictionary<string, object>())
            {
                System.Data.Common.DbParameter parameter = command.CreateParameter();
                parameter.ParameterName = ReignPostgreSqlDialect.ParameterName(command.Connection, pair.Key);
                parameter.Value = pair.Value ?? DBNull.Value;
                command.Parameters.Add(parameter);
            }
        }

        private static Dictionary<string, object> StoreWorldMemoryEvent(Dictionary<string, object> payload, string source, ReignDbConnection existingConnection = null)
        {
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", "default");
            long ts = ReadLong(payload, "ts", DateTimeOffset.UtcNow.ToUnixTimeSeconds());
            string eventId = FirstNonEmpty(ReadFirstString(payload, "event_id", "eventId", "id"), "evt_" + DateTimeOffset.UtcNow.ToUnixTimeMilliseconds().ToString(CultureInfo.InvariantCulture) + "_" + Guid.NewGuid().ToString("N").Substring(0, 8));
            string eventType = FirstNonEmpty(ReadFirstString(payload, "eventType", "event_type", "type"), "unknown");
            string summary = FirstNonEmpty(ReadFirstString(payload, "summary", "text", "conversation_text", "conversationText", "message"), eventType);
            string locationId = ReadFirstString(payload, "location_id", "locationId", "settlementId", "currentSettlementId");
            double worldDay = ReadDouble(payload, "world_day", ReadDouble(payload, "worldDay", 0d));
            double importance = ClampDouble(ReadDouble(payload, "importance", 0.5d), 0d, 1d);
            double reliability = ClampDouble(ReadDouble(payload, "source_reliability", ReadDouble(payload, "sourceReliability", 1d)), 0d, 1d);
            double confidence = ClampDouble(ReadDouble(payload, "confidence", 1d), 0d, 1d);
            string visibility = FirstNonEmpty(ReadString(payload, "visibility", ""), IsPrivateEventType(eventType) ? "private" : "public");
            List<string> participants = MergeStringLists(ReadStringList(payload, "participants"), ReadStringList(payload, "actorIds"));
            List<string> witnesses = ReadStringList(payload, "witnesses");
            List<string> knownBy = MergeStringLists(ReadStringList(payload, "known_by"), ReadStringList(payload, "knownBy"));
            if (knownBy.Count == 0 && string.Equals(visibility, "private", StringComparison.OrdinalIgnoreCase))
            {
                knownBy = MergeStringLists(participants, witnesses);
            }

            List<string> heardAsRumorBy = MergeStringLists(ReadStringList(payload, "heard_as_rumor_by"), ReadStringList(payload, "heardAsRumorBy"));
            List<string> hiddenFrom = MergeStringLists(ReadStringList(payload, "hidden_from"), ReadStringList(payload, "hiddenFrom"));
            object aboutEntitiesValue = payload.ContainsKey("about_entities") ? payload["about_entities"] : payload.ContainsKey("aboutEntities") ? payload["aboutEntities"] : null;
            List<string> aboutEntityIds = ExtractEntityIds(aboutEntitiesValue);
            if (aboutEntityIds.Count == 0)
            {
                aboutEntityIds = MergeStringLists(ReadStringList(payload, "aboutEntityIds"), ReadStringList(payload, "about_entities"));
            }

            List<string> tags = MergeStringLists(ReadStringList(payload, "tags"), SimpleTags(summary + " " + eventType));
            string aboutEntitiesJson = aboutEntitiesValue == null || aboutEntityIds.Count > 0 && !(aboutEntitiesValue is ArrayList) ? Json.Serialize(aboutEntityIds) : Json.Serialize(aboutEntitiesValue);
            string eventCategory = ClassifyEventCategory(eventType, payload, summary);
            string eventSubtype = ClassifyEventSubtype(eventType, summary);
            bool indexEventForRetrieval = ReadBool(payload, "indexEventForRetrieval", true);
            bool projectParticipantMemories = ReadBool(payload, "projectParticipantMemories", true);
            payload["eventCategory"] = eventCategory;
            payload["eventSubtype"] = eventSubtype;
            payload["indexEventForRetrieval"] = indexEventForRetrieval;
            payload["projectParticipantMemories"] = projectParticipantMemories;
            string payloadJson = Json.Serialize(payload);
            List<string> memoryIds = new List<string>();

            using (ReignDbConnection ownedConnection = existingConnection == null ? OpenCampaignConnection(campaignId) : null)
            {
                var connection = existingConnection ?? ownedConnection;
                using var publication = existingConnection == null ? connection.BeginTransaction() : null;
                DeleteWorldMemoryEventProjection(connection, eventId);
                ExecuteSql(connection, @"INSERT OR REPLACE INTO events(
    event_id,campaign_id,ts,world_day,event_type,event_category,event_subtype,location_id,summary,participants_json,witnesses_json,about_entities_json,
    known_by_json,heard_as_rumor_by_json,hidden_from_json,visibility,importance,source_reliability,confidence,payload_json,vector_id,embedding_status,created_utc)
VALUES(
    $event_id,$campaign_id,$ts,$world_day,$event_type,$event_category,$event_subtype,$location_id,$summary,$participants_json,$witnesses_json,$about_entities_json,
    $known_by_json,$heard_as_rumor_by_json,$hidden_from_json,$visibility,$importance,$source_reliability,$confidence,$payload_json,$vector_id,$embedding_status,$created_utc);",
                    new Dictionary<string, object>
                    {
                        ["event_id"] = eventId,
                        ["campaign_id"] = campaignId,
                        ["ts"] = ts,
                        ["world_day"] = worldDay,
                        ["event_type"] = eventType,
                        ["event_category"] = eventCategory,
                        ["event_subtype"] = eventSubtype,
                        ["location_id"] = locationId,
                        ["summary"] = summary,
                        ["participants_json"] = Json.Serialize(participants),
                        ["witnesses_json"] = Json.Serialize(witnesses),
                        ["about_entities_json"] = aboutEntitiesJson,
                        ["known_by_json"] = Json.Serialize(knownBy),
                        ["heard_as_rumor_by_json"] = Json.Serialize(heardAsRumorBy),
                        ["hidden_from_json"] = Json.Serialize(hiddenFrom),
                        ["visibility"] = visibility,
                        ["importance"] = importance,
                        ["source_reliability"] = reliability,
                        ["confidence"] = confidence,
                        ["payload_json"] = payloadJson,
                        ["vector_id"] = ReadString(payload, "vector_id", ReadString(payload, "vectorId", "")),
                        ["embedding_status"] = indexEventForRetrieval
                            ? ReadString(payload, "embedding_status", ReadString(payload, "embeddingStatus", "not_indexed"))
                            : "skipped",
                        ["created_utc"] = DateTime.UtcNow.ToString("o")
                    });
                if (indexEventForRetrieval)
                {
                    InsertEventFts(connection, eventId, summary, tags, aboutEntityIds.Concat(participants).Concat(witnesses).Distinct(StringComparer.OrdinalIgnoreCase).ToList());
                }

                if (projectParticipantMemories && !string.IsNullOrWhiteSpace(summary))
                {
                    bool canonicalPublic = visibility.StartsWith("public", StringComparison.OrdinalIgnoreCase)
                        || visibility.Equals("world", StringComparison.OrdinalIgnoreCase)
                        || visibility.Equals("global", StringComparison.OrdinalIgnoreCase);
                    if (canonicalPublic)
                    {
                        string memoryId = "mem_world_" + Guid.NewGuid().ToString("N");
                        string memoryType = eventCategory == "local_observation" ? "local_observation" : "world_knowledge";
                        InsertMemoryRow(connection, memoryId, eventId, "", memoryType, ts, worldDay, locationId, summary,
                            participants, witnesses, aboutEntitiesJson, new List<string>(), heardAsRumorBy, hiddenFrom, visibility,
                            importance, 0d, confidence, tags, "active", source, payloadJson, "", "not_indexed");
                        ExecuteSql(connection, "UPDATE memories SET memory_domain=$domain WHERE memory_id=$id;",
                            new Dictionary<string, object>
                            {
                                ["domain"] = MemoryDomainForWorldEventProjection(eventCategory, eventType, memoryType, summary, tags, source),
                                ["id"] = memoryId
                            });
                        memoryIds.Add(memoryId);
                    }

                    List<string> directOwners = MergeStringLists(participants, witnesses);
                    if (!canonicalPublic && directOwners.Count == 0)
                    {
                        directOwners = knownBy;
                    }
                    foreach (string ownerId in directOwners.Where(id => !string.IsNullOrWhiteSpace(id)).Distinct(StringComparer.OrdinalIgnoreCase))
                    {
                        string acquisition = witnesses.Contains(ownerId, StringComparer.OrdinalIgnoreCase) ? "witness" : "participant";
                        UpsertKnowledgeReceipt(connection, eventId, ownerId, acquisition, confidence, reliability, worldDay, source, ts);
                        string memoryId = "mem_" + Guid.NewGuid().ToString("N");
                        string memoryType = eventCategory == "conversation" || eventCategory == "correspondence"
                            ? "interpersonal_experience"
                            : eventCategory == "local_observation" ? "local_observation" : "personal_experience";
                        InsertMemoryRow(connection, memoryId, eventId, ownerId, memoryType, ts, worldDay, locationId, summary,
                            participants, witnesses, aboutEntitiesJson, new List<string> { ownerId }, new List<string>(), hiddenFrom,
                            "private", importance, 0d, confidence, tags, "active", source, payloadJson, "", "not_indexed");
                        ExecuteSql(connection, "UPDATE memories SET memory_domain=$domain WHERE memory_id=$id;",
                            new Dictionary<string, object>
                            {
                                ["domain"] = MemoryDomainForWorldEventProjection(eventCategory, eventType, memoryType, summary, tags, source),
                                ["id"] = memoryId
                            });
                        memoryIds.Add(memoryId);
                    }

                    foreach (string ownerId in knownBy.Where(id => !string.IsNullOrWhiteSpace(id)).Except(directOwners, StringComparer.OrdinalIgnoreCase))
                    {
                        UpsertKnowledgeReceipt(connection, eventId, ownerId, "known", confidence, reliability, worldDay, source, ts);
                    }
                }

                StoreStructuredWrites(connection, campaignId, eventId, payload, ts, source);
                publication?.Commit();
            }

            return new Dictionary<string, object>
            {
                ["ok"] = true,
                ["campaignId"] = campaignId,
                ["eventId"] = eventId,
                ["memoryIds"] = memoryIds,
                ["memoryCount"] = memoryIds.Count,
                ["indexEventForRetrieval"] = indexEventForRetrieval,
                ["projectParticipantMemories"] = projectParticipantMemories,
                ["dbPath"] = CampaignMemoryDbPath(campaignId)
            };
        }

        private static string MemoryDomainForWorldEventProjection(string eventCategory, string eventType, string memoryType, string summary, List<string> tags, string source)
        {
            if (string.Equals(eventCategory, "conversation", StringComparison.OrdinalIgnoreCase)
                || string.Equals(eventCategory, "correspondence", StringComparison.OrdinalIgnoreCase))
            {
                return "interpersonal_history";
            }
            if (string.Equals(eventCategory, "local_observation", StringComparison.OrdinalIgnoreCase))
            {
                return "local_awareness";
            }

            string classified = ClassifyMemoryDomain(new Dictionary<string, object>
            {
                ["memory_type"] = memoryType ?? "",
                ["summary"] = summary ?? "",
                ["source"] = (source ?? "") + " " + (eventType ?? ""),
                ["tags_json"] = Json.Serialize(tags ?? new List<string>())
            });
            // Generic native events remain world knowledge, while promises,
            // beliefs, conversations, and personal state keep their specific lane.
            if (string.Equals(classified, "personal_state", StringComparison.OrdinalIgnoreCase)
                && string.Equals(eventCategory, "world_event", StringComparison.OrdinalIgnoreCase))
            {
                return "world_affairs";
            }
            return classified;
        }

        private static void DeleteWorldMemoryEventProjection(ReignDbConnection connection, string eventId)
        {
            if (connection == null || string.IsNullOrWhiteSpace(eventId))
            {
                return;
            }

            Dictionary<string, object> parameters = new Dictionary<string, object> { ["event_id"] = eventId };
            ExecuteSql(connection, "DELETE FROM memory_fts WHERE memory_id IN (SELECT memory_id FROM memories WHERE event_id=$event_id);", parameters);
            ExecuteSql(connection, "DELETE FROM event_fts WHERE event_id=$event_id;", parameters);
            ExecuteSql(connection, "DELETE FROM memories WHERE event_id=$event_id;", parameters);
            ExecuteSql(connection, "DELETE FROM knowledge_receipts WHERE event_id=$event_id;", parameters);
            ExecuteSql(connection, "DELETE FROM beliefs WHERE event_id=$event_id;", parameters);
            ExecuteSql(connection, "DELETE FROM obligations WHERE event_id=$event_id;", parameters);
            ExecuteSql(connection, "DELETE FROM comprehension WHERE event_id=$event_id;", parameters);
        }

        private static void InsertMemoryRow(
            ReignDbConnection connection,
            string memoryId,
            string eventId,
            string ownerId,
            string memoryType,
            long ts,
            double worldDay,
            string locationId,
            string summary,
            List<string> participants,
            List<string> witnesses,
            string aboutEntitiesJson,
            List<string> knownBy,
            List<string> heardAsRumorBy,
            List<string> hiddenFrom,
            string visibility,
            double importance,
            double emotionalWeight,
            double confidence,
            List<string> tags,
            string status,
            string source,
            string payloadJson,
            string vectorId,
            string embeddingStatus)
        {
            ExecuteSql(connection, @"INSERT OR REPLACE INTO memories(
    memory_id,event_id,owner_id,memory_type,ts,world_day,location_id,summary,participants_json,witnesses_json,about_entities_json,
    known_by_json,heard_as_rumor_by_json,hidden_from_json,visibility,importance,emotional_weight,confidence,tags_json,status,source,vector_id,embedding_status,payload_json)
VALUES(
    $memory_id,$event_id,$owner_id,$memory_type,$ts,$world_day,$location_id,$summary,$participants_json,$witnesses_json,$about_entities_json,
    $known_by_json,$heard_as_rumor_by_json,$hidden_from_json,$visibility,$importance,$emotional_weight,$confidence,$tags_json,$status,$source,$vector_id,$embedding_status,$payload_json);",
                new Dictionary<string, object>
                {
                    ["memory_id"] = memoryId,
                    ["event_id"] = eventId,
                    ["owner_id"] = ownerId ?? "",
                    ["memory_type"] = memoryType ?? "event",
                    ["ts"] = ts,
                    ["world_day"] = worldDay,
                    ["location_id"] = locationId ?? "",
                    ["summary"] = summary ?? "",
                    ["participants_json"] = Json.Serialize(participants ?? new List<string>()),
                    ["witnesses_json"] = Json.Serialize(witnesses ?? new List<string>()),
                    ["about_entities_json"] = string.IsNullOrWhiteSpace(aboutEntitiesJson) ? "[]" : aboutEntitiesJson,
                    ["known_by_json"] = Json.Serialize(knownBy ?? new List<string>()),
                    ["heard_as_rumor_by_json"] = Json.Serialize(heardAsRumorBy ?? new List<string>()),
                    ["hidden_from_json"] = Json.Serialize(hiddenFrom ?? new List<string>()),
                    ["visibility"] = visibility ?? "private",
                    ["importance"] = importance,
                    ["emotional_weight"] = emotionalWeight,
                    ["confidence"] = confidence,
                    ["tags_json"] = Json.Serialize(tags ?? new List<string>()),
                    ["status"] = status ?? "active",
                    ["source"] = source ?? "",
                    ["vector_id"] = vectorId ?? "",
                    ["embedding_status"] = string.IsNullOrWhiteSpace(embeddingStatus) ? "not_indexed" : embeddingStatus,
                    ["payload_json"] = payloadJson ?? "{}"
                });
            InsertMemoryFts(connection, memoryId, summary, tags, ExtractEntityIdsFromJson(aboutEntitiesJson).Concat(participants ?? new List<string>()).Concat(witnesses ?? new List<string>()).Distinct(StringComparer.OrdinalIgnoreCase).ToList());
        }

        private static void InsertMemoryFts(ReignDbConnection connection, string memoryId, string text, List<string> tags, List<string> entities)
        {
            ExecuteSql(connection, "INSERT INTO memory_fts(memory_id, text, tags, entities) VALUES($memory_id, $text, $tags, $entities);",
                new Dictionary<string, object>
                {
                    ["memory_id"] = memoryId,
                    ["text"] = text ?? "",
                    ["tags"] = string.Join(" ", tags ?? new List<string>()),
                    ["entities"] = string.Join(" ", entities ?? new List<string>())
                });
        }

        private static void InsertEventFts(ReignDbConnection connection, string eventId, string text, List<string> tags, List<string> entities)
        {
            ExecuteSql(connection, "INSERT INTO event_fts(event_id, text, tags, entities) VALUES($event_id, $text, $tags, $entities);",
                new Dictionary<string, object>
                {
                    ["event_id"] = eventId,
                    ["text"] = text ?? "",
                    ["tags"] = string.Join(" ", tags ?? new List<string>()),
                    ["entities"] = string.Join(" ", entities ?? new List<string>())
                });
        }

        private static void StoreStructuredWrites(ReignDbConnection connection, string campaignId, string eventId, Dictionary<string, object> payload, long ts, string source)
        {
            foreach (Dictionary<string, object> item in ReadDictionaryList(payload, "beliefWrites").Concat(ReadDictionaryList(payload, "belief_writes")))
            {
                item["campaignId"] = campaignId;
                InsertBelief(connection, eventId, item, ts, source);
            }

            // Native Bannerlord relationship values remain the authority for character-to-character relation.
            // Reign does not maintain a second relationship score layer yet.

            foreach (Dictionary<string, object> item in ReadDictionaryList(payload, "obligationWrites").Concat(ReadDictionaryList(payload, "obligation_writes")))
            {
                item["campaignId"] = campaignId;
                InsertObligation(connection, eventId, item, ts, source);
            }

            foreach (Dictionary<string, object> item in ReadDictionaryList(payload, "comprehensionWrites").Concat(ReadDictionaryList(payload, "comprehension_writes")))
            {
                item["campaignId"] = campaignId;
                InsertComprehension(connection, eventId, item, ts, source);
            }
        }

        private static void InsertBelief(ReignDbConnection connection, string eventId, Dictionary<string, object> item, long ts, string source)
        {
            string claim = ReadFirstString(item, "claim", "text", "belief", "summary");
            if (string.IsNullOrWhiteSpace(claim))
            {
                return;
            }

            string believer = ReadFirstString(item, "believer", "believer_id", "believerId", "ownerId", "heroStringId");
            List<string> knownBy = MergeStringLists(ReadStringList(item, "known_by"), ReadStringList(item, "knownBy"));
            if (knownBy.Count == 0 && !string.IsNullOrWhiteSpace(believer))
            {
                knownBy.Add(believer);
            }

            string beliefId = FirstNonEmpty(ReadFirstString(item, "belief_id", "beliefId", "id"), "belief_" + Guid.NewGuid().ToString("N"));
            ExecuteSql(connection, @"INSERT OR REPLACE INTO beliefs(belief_id,event_id,believer_id,claim,confidence,source,known_by_json,about_entities_json,hidden_from_json,visibility,ts,payload_json)
VALUES($belief_id,$event_id,$believer_id,$claim,$confidence,$source,$known_by_json,$about_entities_json,$hidden_from_json,$visibility,$ts,$payload_json);",
                new Dictionary<string, object>
                {
                    ["belief_id"] = beliefId,
                    ["event_id"] = eventId ?? "",
                    ["believer_id"] = believer,
                    ["claim"] = claim.Trim(),
                    ["confidence"] = ClampDouble(ReadDouble(item, "confidence", 0.5d), 0d, 1d),
                    ["source"] = FirstNonEmpty(ReadFirstString(item, "source"), source),
                    ["known_by_json"] = Json.Serialize(knownBy),
                    ["about_entities_json"] = Json.Serialize(ExtractEntityIds(item.ContainsKey("about_entities") ? item["about_entities"] : item.ContainsKey("aboutEntities") ? item["aboutEntities"] : null)),
                    ["hidden_from_json"] = Json.Serialize(MergeStringLists(ReadStringList(item, "hidden_from"), ReadStringList(item, "hiddenFrom"))),
                    ["visibility"] = ReadString(item, "visibility", "private"),
                    ["ts"] = ts,
                    ["payload_json"] = Json.Serialize(item)
                });
            UpsertTemporalAssertion(connection, ReadString(item, "campaignId", ""), eventId, beliefId, "belief", item, ts);
        }

        private static void UpsertRelationship(ReignDbConnection connection, Dictionary<string, object> item, string eventId, long ts)
        {
            string subject = ReadFirstString(item, "subject", "subject_id", "subjectId", "ownerId", "heroStringId");
            string target = ReadFirstString(item, "target", "target_id", "targetId", "playerId");
            if (string.IsNullOrWhiteSpace(subject) || string.IsNullOrWhiteSpace(target))
            {
                return;
            }

            Dictionary<string, object> existing = QuerySql(connection, "SELECT * FROM relationships WHERE subject_id=$subject AND target_id=$target LIMIT 1;",
                new Dictionary<string, object> { ["subject"] = subject, ["target"] = target }).FirstOrDefault() ?? new Dictionary<string, object>();
            List<string> sources = TextListFromJson(ReadString(existing, "last_updated_from_json", "[]"));
            if (!string.IsNullOrWhiteSpace(eventId))
            {
                sources.Add(eventId);
            }

            ExecuteSql(connection, @"INSERT OR REPLACE INTO relationships(subject_id,target_id,trust,fear,respect,resentment,loyalty,debt,affection,rivalry,last_updated_from_json,updated_ts,payload_json)
VALUES($subject_id,$target_id,$trust,$fear,$respect,$resentment,$loyalty,$debt,$affection,$rivalry,$last_updated_from_json,$updated_ts,$payload_json);",
                new Dictionary<string, object>
                {
                    ["subject_id"] = subject,
                    ["target_id"] = target,
                    ["trust"] = RelationshipScore(item, existing, "trust"),
                    ["fear"] = RelationshipScore(item, existing, "fear"),
                    ["respect"] = RelationshipScore(item, existing, "respect"),
                    ["resentment"] = RelationshipScore(item, existing, "resentment"),
                    ["loyalty"] = RelationshipScore(item, existing, "loyalty"),
                    ["debt"] = RelationshipScore(item, existing, "debt"),
                    ["affection"] = RelationshipScore(item, existing, "affection"),
                    ["rivalry"] = RelationshipScore(item, existing, "rivalry"),
                    ["last_updated_from_json"] = Json.Serialize(sources.Distinct(StringComparer.OrdinalIgnoreCase).Take(20).ToList()),
                    ["updated_ts"] = ts,
                    ["payload_json"] = Json.Serialize(item)
                });
        }

        private static double RelationshipScore(Dictionary<string, object> item, Dictionary<string, object> existing, string key)
        {
            if (item == null)
            {
                return ReadDouble(existing, key, 0d);
            }

            if (item.ContainsKey(key + "Delta"))
            {
                return ClampDouble(ReadDouble(existing, key, 0d) + ReadDouble(item, key + "Delta", 0d), -1d, 1d);
            }

            if (item.ContainsKey(key))
            {
                return ClampDouble(ReadDouble(item, key, ReadDouble(existing, key, 0d)), -1d, 1d);
            }

            return ReadDouble(existing, key, 0d);
        }

        private static void InsertObligation(ReignDbConnection connection, string eventId, Dictionary<string, object> item, long ts, string source)
        {
            string description = ReadFirstString(item, "description", "text", "promise", "threat", "summary");
            if (string.IsNullOrWhiteSpace(description))
            {
                return;
            }

            string obligationId = FirstNonEmpty(ReadFirstString(item, "obligation_id", "obligationId", "id"), "obl_" + Guid.NewGuid().ToString("N"));
            ExecuteSql(connection, @"INSERT OR REPLACE INTO obligations(obligation_id,event_id,owed_by,owed_to,description,status,created_day,importance,participants_json,about_entities_json,known_by_json,hidden_from_json,visibility,ts,payload_json)
VALUES($obligation_id,$event_id,$owed_by,$owed_to,$description,$status,$created_day,$importance,$participants_json,$about_entities_json,$known_by_json,$hidden_from_json,$visibility,$ts,$payload_json);",
                new Dictionary<string, object>
                {
                    ["obligation_id"] = obligationId,
                    ["event_id"] = eventId ?? "",
                    ["owed_by"] = ReadFirstString(item, "owed_by", "owedBy", "actorId", "subject"),
                    ["owed_to"] = ReadFirstString(item, "owed_to", "owedTo", "targetId", "target"),
                    ["description"] = description.Trim(),
                    ["status"] = ReadString(item, "status", "unresolved"),
                    ["created_day"] = ReadDouble(item, "created_day", ReadDouble(item, "createdDay", 0d)),
                    ["importance"] = ClampDouble(ReadDouble(item, "importance", 0.7d), 0d, 1d),
                    ["participants_json"] = Json.Serialize(ReadStringList(item, "participants")),
                    ["about_entities_json"] = Json.Serialize(ExtractEntityIds(item.ContainsKey("about_entities") ? item["about_entities"] : item.ContainsKey("aboutEntities") ? item["aboutEntities"] : null)),
                    ["known_by_json"] = Json.Serialize(MergeStringLists(ReadStringList(item, "known_by"), ReadStringList(item, "knownBy"))),
                    ["hidden_from_json"] = Json.Serialize(MergeStringLists(ReadStringList(item, "hidden_from"), ReadStringList(item, "hiddenFrom"))),
                    ["visibility"] = ReadString(item, "visibility", "private"),
                    ["ts"] = ts,
                    ["payload_json"] = Json.Serialize(item)
                });
            UpsertTemporalAssertion(connection, ReadString(item, "campaignId", ""), eventId, obligationId, "obligation", item, ts);
        }

        private static void InsertComprehension(ReignDbConnection connection, string eventId, Dictionary<string, object> item, long ts, string source)
        {
            string text = ReadFirstString(item, "text", "comprehension", "interpretation", "summary");
            string owner = ReadFirstString(item, "ownerId", "owner_id", "heroStringId", "npcId");
            if (string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(owner))
            {
                return;
            }

            List<string> knownBy = MergeStringLists(ReadStringList(item, "known_by"), ReadStringList(item, "knownBy"));
            if (knownBy.Count == 0)
            {
                knownBy.Add(owner);
            }

            string comprehensionId = FirstNonEmpty(ReadFirstString(item, "comprehension_id", "comprehensionId", "id"), "comp_" + Guid.NewGuid().ToString("N"));
            ExecuteSql(connection, @"INSERT OR REPLACE INTO comprehension(comprehension_id,event_id,owner_id,text,stance,confidence,known_by_json,about_entities_json,hidden_from_json,ts,payload_json)
VALUES($comprehension_id,$event_id,$owner_id,$text,$stance,$confidence,$known_by_json,$about_entities_json,$hidden_from_json,$ts,$payload_json);",
                new Dictionary<string, object>
                {
                    ["comprehension_id"] = comprehensionId,
                    ["event_id"] = eventId ?? "",
                    ["owner_id"] = owner,
                    ["text"] = text.Trim(),
                    ["stance"] = ReadFirstString(item, "stance", "tone"),
                    ["confidence"] = ClampDouble(ReadDouble(item, "confidence", 0.6d), 0d, 1d),
                    ["known_by_json"] = Json.Serialize(knownBy),
                    ["about_entities_json"] = Json.Serialize(ExtractEntityIds(item.ContainsKey("about_entities") ? item["about_entities"] : item.ContainsKey("aboutEntities") ? item["aboutEntities"] : null)),
                    ["hidden_from_json"] = Json.Serialize(MergeStringLists(ReadStringList(item, "hidden_from"), ReadStringList(item, "hiddenFrom"))),
                    ["ts"] = ts,
                    ["payload_json"] = Json.Serialize(item)
                });
            UpsertTemporalAssertion(connection, ReadString(item, "campaignId", ""), eventId, comprehensionId, "interpretation", item, ts);
        }

        private static Dictionary<string, object> StoreActionResultMemory(Dictionary<string, object> payload, string source)
        {
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", "default");
            Dictionary<string, object> result = ReadDictionary(payload, "result") ?? new Dictionary<string, object>();
            string actionId = ReadFirstString(payload, "serverActionId", "actionId", "id");
            string type = ReadFirstString(payload, "type", "command");
            string status = ReadString(payload, "status", ReadString(result, "status", "reported"));
            string message = FirstNonEmpty(ReadFirstString(payload, "message"), ReadFirstString(result, "message", "debugMessage"));
            List<string> participants = MergeStringLists(new List<string>
            {
                ReadFirstString(payload, "actorHeroStringId", "actorHeroId"),
                ReadFirstString(payload, "targetHeroStringId", "targetHeroId")
            }, new List<string>());
            Dictionary<string, object> evt = new Dictionary<string, object>
            {
                ["campaignId"] = campaignId,
                ["eventId"] = string.IsNullOrWhiteSpace(actionId) ? "" : "action_" + actionId,
                ["eventType"] = "action_result",
                ["summary"] = FirstNonEmpty(message, type + " " + status),
                ["participants"] = participants,
                ["known_by"] = participants,
                ["visibility"] = participants.Count > 0 ? "private" : "public",
                ["importance"] = status.Equals("completed", StringComparison.OrdinalIgnoreCase) ? 0.75d : 0.55d,
                ["payload"] = payload
            };
            return StoreWorldMemoryEvent(evt, source);
        }

        private static Dictionary<string, object> StoreTurnMemoryLayers(
            string campaignId,
            string eventId,
            string eventType,
            string heroId,
            string playerId,
            string locationId,
            string playerText,
            string reply,
            List<Dictionary<string, object>> memoryWrites,
            List<Dictionary<string, object>> beliefWrites,
            List<Dictionary<string, object>> relationshipUpdates,
            List<Dictionary<string, object>> obligationWrites,
            List<Dictionary<string, object>> comprehensionWrites,
            string memoryGroupKey,
            long ts,
            List<string> sharedParticipants = null,
            bool retrievalEligible = true,
            Dictionary<string, object> continuityPayload = null,
            List<Dictionary<string, object>> continuityWrites = null)
        {
            List<string> participants = MergeStringLists(sharedParticipants, new[] { heroId, playerId });
            string summary = LimitText("Player: " + (playerText ?? "") + "\nNPC: " + (reply ?? ""), 1200);
            if (string.IsNullOrWhiteSpace(summary))
            {
                summary = eventType ?? "conversation turn";
            }

            // A recall answer is evidence about an existing conversation, not a new
            // fact source. The canonical conversation rows and decision audit still
            // retain the exchange, but projecting the answer back into events,
            // memories, FTS, or vectors creates a self-reinforcing recall loop.
            if (!retrievalEligible)
            {
                return new Dictionary<string, object>
                {
                    ["ok"] = true,
                    ["campaignId"] = campaignId,
                    ["eventId"] = eventId,
                    ["memoryIds"] = new List<string>(),
                    ["memoryCount"] = 0,
                    ["episodicMemoryWriteIds"] = new List<string>(),
                    ["retrievalEligible"] = false,
                    ["auditOnly"] = true,
                    ["reason"] = "recall_response_audit_only",
                    ["dbPath"] = CampaignMemoryDbPath(campaignId),
                    ["structuredWriteCounts"] = new Dictionary<string, object>
                    {
                        ["memoryWrites"] = 0,
                        ["beliefWrites"] = 0,
                        ["relationshipUpdatesSkipped"] = relationshipUpdates == null ? 0 : relationshipUpdates.Count,
                        ["obligationWrites"] = 0,
                        ["comprehensionWrites"] = 0
                    },
                    ["suppressedWriteCounts"] = new Dictionary<string, object>
                    {
                        ["memoryWrites"] = memoryWrites == null ? 0 : memoryWrites.Count,
                        ["beliefWrites"] = beliefWrites == null ? 0 : beliefWrites.Count,
                        ["obligationWrites"] = obligationWrites == null ? 0 : obligationWrites.Count,
                        ["comprehensionWrites"] = comprehensionWrites == null ? 0 : comprehensionWrites.Count
                    }
                };
            }

            List<Dictionary<string, object>> preparedBeliefs = PrepareStructuredWrites(beliefWrites, heroId, playerId, locationId, eventType, "belief", participants);
            List<Dictionary<string, object>> preparedObligations = PrepareStructuredWrites(obligationWrites, heroId, playerId, locationId, eventType, "obligation", participants);
            List<Dictionary<string, object>> preparedComprehension = PrepareStructuredWrites(comprehensionWrites, heroId, playerId, locationId, eventType, "comprehension", participants);
            foreach (var write in preparedBeliefs.Concat(preparedObligations).Concat(preparedComprehension))
            {
                write["timelineId"] = ContinuityTimeline(continuityPayload);
                write["worldDay"] = ReadDouble(continuityPayload, "worldDay", 0d);
                write["sourceSpeakerId"] = heroId;
                write["sourceAcceptedText"] = reply ?? "";
            }

            Dictionary<string, object> eventPayload = new Dictionary<string, object>
            {
                ["campaignId"] = campaignId,
                ["eventId"] = eventId,
                ["ts"] = ts,
                ["eventType"] = eventType,
                ["summary"] = summary,
                ["participants"] = participants,
                ["known_by"] = participants,
                ["locationId"] = locationId ?? "",
                ["memoryGroupKey"] = memoryGroupKey ?? "",
                ["visibility"] = "private",
                ["importance"] = CalculateTurnImportance(memoryWrites, preparedBeliefs, preparedObligations, preparedComprehension),
                ["tags"] = MergeStringLists(SimpleTags(summary + " " + eventType), new[] { "conversation" }),
                // Canonical conversation_turns plus their FTS window preserve the
                // recent raw exchange. Do not duplicate every low-salience line as
                // an event-FTS hit and two durable participant memories; explicit
                // model/structured writes below are the long-term layer.
                ["indexEventForRetrieval"] = false,
                ["projectParticipantMemories"] = false,
                ["beliefWrites"] = preparedBeliefs,
                ["obligationWrites"] = preparedObligations,
                ["comprehensionWrites"] = preparedComprehension,
                ["payload"] = new Dictionary<string, object>
                {
                    ["playerText"] = playerText ?? "",
                    ["reply"] = reply ?? "",
                    ["memoryGroupKey"] = memoryGroupKey ?? "",
                    ["relationshipUpdatesSkipped"] = relationshipUpdates == null ? 0 : relationshipUpdates.Count
                }
            };

            Dictionary<string, object> stored;
            List<string> episodicMemoryIds = new List<string>();
            using (ReignDbConnection connection = OpenCampaignConnection(campaignId))
            using (var publication = connection.BeginTransaction())
            {
                stored = StoreWorldMemoryEvent(eventPayload, eventType, connection);
                foreach (Dictionary<string, object> memory in memoryWrites ?? new List<Dictionary<string, object>>())
                {
                    string text = ReadFirstString(memory, "text", "memory", "summary", "content");
                    if (string.IsNullOrWhiteSpace(text))
                    {
                        continue;
                    }

                    Dictionary<string, object> copy = new Dictionary<string, object>(memory, StringComparer.OrdinalIgnoreCase);
                    copy["timelineId"] = ContinuityTimeline(continuityPayload);
                    copy["sourceEventId"] = eventId;
                    copy["sourceHash"] = PromptHash(reply ?? "");
                    copy["evidenceClass"] = "reported";
                    if (!copy.ContainsKey("memoryGroupKey"))
                    {
                        copy["memoryGroupKey"] = memoryGroupKey ?? "";
                    }
                    List<string> knownBy = MergeStringLists(MergeStringLists(ReadStringList(copy, "known_by"), ReadStringList(copy, "knownBy")), participants);
                    List<string> witnesses = MergeStringLists(ReadStringList(copy, "witnesses"), new List<string>());
                    List<string> tags = MergeStringLists(ReadStringList(copy, "tags"), new[] { "conversation" });
                    if (tags.Count == 0)
                    {
                        tags = SimpleTags(text);
                    }

                    object aboutRaw = copy.ContainsKey("about_entities") ? copy["about_entities"] : copy.ContainsKey("aboutEntities") ? copy["aboutEntities"] : null;
                    string memoryId = FirstNonEmpty(ReadFirstString(copy, "memory_id", "memoryId", "id"), "mem_" + Guid.NewGuid().ToString("N"));
                    string ownerId = FirstNonEmpty(ReadFirstString(copy, "ownerId", "owner_id", "heroStringId"), heroId);
                    InsertMemoryRow(
                        connection,
                        memoryId,
                        eventId,
                        ownerId,
                        FirstNonEmpty(ReadFirstString(copy, "memoryType", "memory_type", "type"), "episodic"),
                        ts,
                        ReadDouble(copy, "world_day", ReadDouble(copy, "worldDay", 0d)),
                        FirstNonEmpty(ReadFirstString(copy, "location_id", "locationId", "settlementId"), locationId),
                        text.Trim(),
                        participants,
                        witnesses,
                        Json.Serialize(ExtractEntityIds(aboutRaw)),
                        knownBy,
                        MergeStringLists(ReadStringList(copy, "heard_as_rumor_by"), ReadStringList(copy, "heardAsRumorBy")),
                        MergeStringLists(ReadStringList(copy, "hidden_from"), ReadStringList(copy, "hiddenFrom")),
                        ReadString(copy, "visibility", "private"),
                        MemoryImportance01(copy, 0.55d),
                        ClampDouble(ReadDouble(copy, "emotionalWeight", ReadDouble(copy, "emotional_weight", 0d)), 0d, 1d),
                        ClampDouble(ReadDouble(copy, "confidence", 0.75d), 0d, 1d),
                        tags,
                        ReadString(copy, "status", "active"),
                        FirstNonEmpty(ReadFirstString(copy, "source"), eventType),
                        Json.Serialize(copy),
                        ReadString(copy, "vector_id", ReadString(copy, "vectorId", "")),
                        ReadString(copy, "embedding_status", ReadString(copy, "embeddingStatus", "not_indexed")));
                    ExecuteSql(connection, "UPDATE memories SET memory_domain=$domain WHERE memory_id=$id;",
                        new Dictionary<string, object>
                        {
                            ["domain"] = ClassifyMemoryDomain(new Dictionary<string, object>(copy, StringComparer.OrdinalIgnoreCase)
                            {
                                ["memory_type"] = FirstNonEmpty(ReadFirstString(copy, "memoryType", "memory_type", "type"), "episodic"),
                                ["summary"] = text,
                                ["source"] = FirstNonEmpty(ReadFirstString(copy, "source"), eventType)
                            }),
                            ["id"] = memoryId
                        });
                    episodicMemoryIds.Add(memoryId);
                }
                if (continuityPayload != null && continuityWrites != null && continuityWrites.Count > 0)
                {
                    stored["continuity"] = StoreAcceptedConversationContinuity(connection, continuityPayload,
                        heroId, playerId, eventId, reply, continuityWrites, ts);
                }
                ExecuteSql(connection, "DELETE FROM memory_projections WHERE owner_id=$owner;", new Dictionary<string, object> { ["owner"] = heroId });
                publication.Commit();
            }
            List<string> projectedMemoryIds = ReadStringList(stored, "memoryIds");
            stored["projectedMemoryIds"] = projectedMemoryIds;
            stored["projectedMemoryCount"] = projectedMemoryIds.Count;
            stored["episodicMemoryWriteIds"] = episodicMemoryIds;
            stored["memoryIds"] = MergeStringLists(projectedMemoryIds, episodicMemoryIds);
            stored["memoryCount"] = projectedMemoryIds.Count + episodicMemoryIds.Count;
            stored["structuredWriteCounts"] = new Dictionary<string, object>
            {
                ["memoryWrites"] = memoryWrites == null ? 0 : memoryWrites.Count,
                ["beliefWrites"] = preparedBeliefs.Count,
                ["relationshipUpdatesSkipped"] = relationshipUpdates == null ? 0 : relationshipUpdates.Count,
                ["obligationWrites"] = preparedObligations.Count,
                ["comprehensionWrites"] = preparedComprehension.Count
            };
            return stored;
        }

        private static List<Dictionary<string, object>> PrepareStructuredWrites(
            List<Dictionary<string, object>> writes,
            string heroId,
            string playerId,
            string locationId,
            string source,
            string layer,
            List<string> sharedParticipants = null)
        {
            List<Dictionary<string, object>> prepared = new List<Dictionary<string, object>>();
            List<string> participants = MergeStringLists(sharedParticipants, new[] { heroId, playerId });
            foreach (Dictionary<string, object> write in writes ?? new List<Dictionary<string, object>>())
            {
                Dictionary<string, object> copy = new Dictionary<string, object>(write ?? new Dictionary<string, object>(), StringComparer.OrdinalIgnoreCase);
                if (!copy.ContainsKey("source") || string.IsNullOrWhiteSpace(Convert.ToString(copy["source"])))
                {
                    copy["source"] = source ?? "dialogue";
                }

                if (!copy.ContainsKey("locationId") && !copy.ContainsKey("location_id") && !string.IsNullOrWhiteSpace(locationId))
                {
                    copy["locationId"] = locationId;
                }

                // A response may author only its speaker's internal state. Other
                // people hearing the reply does not disclose its hidden metadata.
                if (layer.Equals("belief", StringComparison.OrdinalIgnoreCase))
                {
                    copy["believer"] = heroId;
                    copy["believer_id"] = heroId;
                    copy["believerId"] = heroId;
                }

                if (layer.Equals("comprehension", StringComparison.OrdinalIgnoreCase))
                {
                    copy["ownerId"] = heroId;
                    copy["owner_id"] = heroId;
                }

                if (IsPrivateMentalLayer(layer))
                {
                    copy["believer"] = heroId;
                    copy["believer_id"] = heroId;
                    copy["believerId"] = heroId;
                    copy["ownerId"] = heroId;
                    copy["owner_id"] = heroId;
                    copy["heroStringId"] = heroId;
                    copy["npcId"] = heroId;
                    copy["known_by"] = new List<string> { heroId };
                    copy["knownBy"] = new List<string> { heroId };
                    copy["visibility"] = "private";
                    copy["truthStatus"] = layer.Equals("belief", StringComparison.OrdinalIgnoreCase)
                        ? "believed" : "interpretation";
                }

                if (ReadStringList(copy, "known_by").Count == 0 && ReadStringList(copy, "knownBy").Count == 0)
                {
                    copy["known_by"] = layer.Equals("court", StringComparison.OrdinalIgnoreCase) && ReadString(copy, "visibility", "rumor").Equals("public", StringComparison.OrdinalIgnoreCase)
                        ? new List<string>()
                        : participants;
                }

                if (layer.Equals("obligation", StringComparison.OrdinalIgnoreCase) && ReadStringList(copy, "participants").Count == 0)
                {
                    copy["participants"] = participants;
                }

                if (!copy.ContainsKey("visibility") || string.IsNullOrWhiteSpace(Convert.ToString(copy["visibility"])))
                {
                    copy["visibility"] = layer.Equals("court", StringComparison.OrdinalIgnoreCase) ? "rumor" : "private";
                }

                prepared.Add(copy);
            }

            return prepared;
        }

        private static double CalculateTurnImportance(
            List<Dictionary<string, object>> memoryWrites,
            List<Dictionary<string, object>> beliefWrites,
            List<Dictionary<string, object>> obligationWrites,
            List<Dictionary<string, object>> comprehensionWrites)
        {
            if ((obligationWrites != null && obligationWrites.Count > 0) || (beliefWrites != null && beliefWrites.Count > 0))
            {
                return 0.78d;
            }

            if ((memoryWrites != null && memoryWrites.Count > 0) || (comprehensionWrites != null && comprehensionWrites.Count > 0))
            {
                return 0.62d;
            }

            return 0.35d;
        }

        private static double MemoryImportance01(Dictionary<string, object> memory, double fallback)
        {
            double value = ReadDouble(memory, "importance", fallback);
            if (value > 1d)
            {
                value = value / 5d;
            }

            return ClampDouble(value, 0d, 1d);
        }

        private static string BuildMemoryGroupKey(Dictionary<string, object> payload, string npcId, string playerId, string locationId, string prefix, long ts)
        {
            payload = payload ?? new Dictionary<string, object>();
            string existing = ReadFirstString(payload, "memoryGroupKey", "memory_group_key");
            if (!string.IsNullOrWhiteSpace(existing))
            {
                return existing.Trim();
            }

            string explicitId = ReadFirstString(payload, "conversationId", "conversation_id", "sceneId", "scene_id", "socialEventId", "eventId", "templateId");
            if (!string.IsNullOrWhiteSpace(explicitId))
            {
                return FirstNonEmpty(prefix, "memory") + ":" + explicitId.Trim();
            }

            Dictionary<string, object> settings = LoadSettings();
            int windowMinutes = Math.Max(5, Math.Min(240, ReadInt(settings, "memoryConsolidationWindowMinutes", 30)));
            long bucket = Math.Max(0, ts) / (windowMinutes * 60L);
            List<string> actors = MergeStringLists(new[] { npcId, playerId }, new List<string>())
                .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                .ToList();
            return FirstNonEmpty(prefix, "memory") + ":" + string.Join("+", actors.ToArray()) + ":" + (locationId ?? "") + ":" + bucket.ToString(CultureInfo.InvariantCulture);
        }

        private static string MemoryGroupKeyFromRow(Dictionary<string, object> row, string ownerId)
        {
            Dictionary<string, object> payload = TryParseJsonObject(ReadString(row, "payload_json", "")) ?? new Dictionary<string, object>();
            string existing = ReadFirstString(payload, "memoryGroupKey", "memory_group_key");
            if (string.IsNullOrWhiteSpace(existing))
            {
                existing = ReadFirstString(ReadDictionary(payload, "payload"), "memoryGroupKey", "memory_group_key");
            }

            if (!string.IsNullOrWhiteSpace(existing))
            {
                return existing;
            }

            List<string> participants = TextListFromJson(ReadString(row, "participants_json", "[]"));
            string other = participants.FirstOrDefault(x => !string.Equals(x, ownerId, StringComparison.OrdinalIgnoreCase)) ?? "";
            string source = ReadString(row, "source", "");
            string prefix = source.IndexOf("social", StringComparison.OrdinalIgnoreCase) >= 0 || source.IndexOf("event", StringComparison.OrdinalIgnoreCase) >= 0
                ? "social_event"
                : "conversation";
            return BuildMemoryGroupKey(new Dictionary<string, object>(), ownerId, other, ReadString(row, "location_id", ""), prefix, ReadLong(row, "ts", 0));
        }

        private static string StoredConversationArtifactCorrelationId(
            Dictionary<string, object> row)
        {
            row = row ?? new Dictionary<string, object>();
            string direct = ReadFirstString(
                row,
                "correlationId",
                "correlation_id",
                "liveTestCorrelationId");
            if (!string.IsNullOrWhiteSpace(direct)) return direct;
            Dictionary<string, object> payload = TryParseJsonObject(
                    ReadString(row, "payload_json", ""))
                ?? new Dictionary<string, object>();
            return FirstNonEmpty(
                ReadFirstString(
                    payload,
                    "correlationId",
                    "correlation_id",
                    "liveTestCorrelationId"),
                ReadFirstString(
                    ReadDictionary(payload, "payload"),
                    "correlationId",
                    "correlation_id",
                    "liveTestCorrelationId"),
                ReadFirstString(
                    ReadDictionary(payload, "source"),
                    "correlationId",
                    "correlation_id",
                    "liveTestCorrelationId"));
        }

        private static Dictionary<string, object> ConsolidateNpcMemory(string campaignId, string npcId, bool force, string requestedGroupKey)
        {
            Dictionary<string, object> settings = LoadSettings();
            if (!force && !ReadBool(settings, "enableMemoryConsolidation", true))
            {
                return new Dictionary<string, object> { ["ok"] = true, ["enabled"] = false, ["summaryCount"] = 0 };
            }

            int minEvents = Math.Max(2, Math.Min(20, ReadInt(settings, "memoryConsolidationMinItems", 4)));
            int maxGroups = Math.Max(1, Math.Min(10, ReadInt(settings, "memoryConsolidationMaxGroups", 3)));
            int maxSourceItems = Math.Max(4, Math.Min(80, ReadInt(settings, "memoryConsolidationMaxSourceItems", 24)));
            List<Dictionary<string, object>> candidates;
            using (ReignDbConnection connection = OpenCampaignConnection(campaignId))
            {
                candidates = QuerySql(connection, @"SELECT * FROM memories
WHERE owner_id=$owner_id AND status='active'
ORDER BY ts DESC LIMIT 400;",
                    new Dictionary<string, object> { ["owner_id"] = npcId });
            }

            candidates = candidates
                .Where(row =>
                {
                    List<string> tags = TextListFromJson(ReadString(row, "tags_json", "[]"));
                    string source = ReadString(row, "source", "");
                    return tags.Any(tag => tag.Equals("conversation", StringComparison.OrdinalIgnoreCase) || tag.Equals("event", StringComparison.OrdinalIgnoreCase))
                        || source.IndexOf("dialogue", StringComparison.OrdinalIgnoreCase) >= 0
                        || source.IndexOf("conversation", StringComparison.OrdinalIgnoreCase) >= 0
                        || source.IndexOf("social_event", StringComparison.OrdinalIgnoreCase) >= 0;
                })
                .ToList();

            List<IGrouping<string, Dictionary<string, object>>> groups = candidates
                .GroupBy(row => MemoryGroupKeyFromRow(row, npcId), StringComparer.OrdinalIgnoreCase)
                .Where(group => string.IsNullOrWhiteSpace(requestedGroupKey) || string.Equals(group.Key, requestedGroupKey, StringComparison.OrdinalIgnoreCase))
                .OrderByDescending(group => group.Max(row => ReadLong(row, "ts", 0)))
                .ToList();

            List<Dictionary<string, object>> created = new List<Dictionary<string, object>>();
            foreach (IGrouping<string, Dictionary<string, object>> group in groups)
            {
                List<Dictionary<string, object>> rows = group
                    .OrderBy(row => ReadLong(row, "ts", 0))
                    .GroupBy(MemoryPacketDedupeKey, StringComparer.OrdinalIgnoreCase)
                    .Select(items => items.First())
                    .Take(maxSourceItems)
                    .ToList();
                int distinctEvents = rows.Select(row => ReadString(row, "event_id", "")).Where(id => !string.IsNullOrWhiteSpace(id)).Distinct(StringComparer.OrdinalIgnoreCase).Count();
                int requiredEvents = force ? 2 : minEvents;
                if (distinctEvents < requiredEvents)
                {
                    continue;
                }

                string summaryCorrelationId = rows
                    .Select(StoredConversationArtifactCorrelationId)
                    .LastOrDefault(value =>
                        !string.IsNullOrWhiteSpace(value)) ?? string.Empty;
                Dictionary<string, object> compact = BuildMiddleTermSummary(
                    settings,
                    npcId,
                    group.Key,
                    rows,
                    60000,
                    string.Empty,
                    summaryCorrelationId);
                string summaryText = ReadString(compact, "summary", "");
                if (string.IsNullOrWhiteSpace(summaryText))
                {
                    continue;
                }

                string summaryId = "sum_" + PromptHash(npcId + "|" + group.Key + "|" + MemorySourceHash(rows) + "|" + MemoryPrecisionVersion).Substring(0, 32);
                long startTs = rows.Min(row => ReadLong(row, "ts", 0));
                long endTs = rows.Max(row => ReadLong(row, "ts", 0));
                List<string> sourceEvents = rows.Select(row => ReadString(row, "event_id", "")).Where(id => !string.IsNullOrWhiteSpace(id)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
                List<string> sourceMemoryIds = rows.Select(row => ReadString(row, "memory_id", "")).Where(id => !string.IsNullOrWhiteSpace(id)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
                List<string> participants = rows.SelectMany(row => TextListFromJson(ReadString(row, "participants_json", "[]"))).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
                List<string> entities = rows.SelectMany(row => TextListFromJson(ReadString(row, "about_entities_json", "[]"))).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
                List<string> tags = MergeStringLists(ReadStringList(compact, "tags"), new[] { "middle_term", "conversation" });
                string locationId = rows.Select(row => ReadString(row, "location_id", "")).FirstOrDefault(value => !string.IsNullOrWhiteSpace(value)) ?? "";
                double importance = rows.Count == 0 ? 0.5d : rows.Max(row => ReadDouble(row, "importance", 0.5d));
                long now = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
                Dictionary<string, object> summaryPayload = new Dictionary<string, object>
                {
                    ["memoryGroupKey"] = group.Key,
                    ["sourceMemoryIds"] = sourceMemoryIds,
                    ["sourceEventIds"] = sourceEvents,
                    ["method"] = ReadString(compact, "method", "deterministic"),
                    ["coverageComplete"] = ReadBool(compact, "coverageComplete", false),
                    ["compactionStatus"] = ReadString(compact, "compactionStatus", "incomplete"),
                    ["sourceHash"] = MemorySourceHash(rows), ["processingVersion"] = MemoryPrecisionVersion,
                    ["sourceItemCount"] = rows.Count,
                    ["correlationId"] = summaryCorrelationId
                };

                using (ReignDbConnection connection = OpenCampaignConnection(campaignId))
                using (var publication = connection.BeginTransaction())
                {
                    VerifyMemoryPublicationFence(connection);
                    VerifyMemorySourceRows(connection, "memories", "memory_id", rows);
                    ExecuteSql(connection, @"INSERT INTO summaries(
summary_id,scope,owner_id,summary_type,summary,source_events_json,start_ts,end_ts,event_count,location_id,
participants_json,about_entities_json,known_by_json,hidden_from_json,visibility,importance,confidence,tags_json,
status,source,vector_id,embedding_status,updated_ts,payload_json)
VALUES($summary_id,$scope,$owner_id,'middle_term',$summary,$source_events_json,$start_ts,$end_ts,$event_count,$location_id,
$participants_json,$about_entities_json,$known_by_json,'[]','private',$importance,$confidence,$tags_json,
'active',$source,'','not_indexed',$updated_ts,$payload_json)
ON CONFLICT(summary_id) DO UPDATE SET summary=$summary,payload_json=$payload_json,updated_ts=$updated_ts;",
                        new Dictionary<string, object>
                        {
                            ["summary_id"] = summaryId,
                            ["scope"] = group.Key,
                            ["owner_id"] = npcId,
                            ["summary"] = summaryText,
                            ["source_events_json"] = Json.Serialize(sourceEvents),
                            ["start_ts"] = startTs,
                            ["end_ts"] = endTs,
                            ["event_count"] = distinctEvents,
                            ["location_id"] = locationId,
                            ["participants_json"] = Json.Serialize(participants),
                            ["about_entities_json"] = Json.Serialize(entities),
                            ["known_by_json"] = Json.Serialize(new List<string> { npcId }),
                            ["importance"] = importance,
                            ["confidence"] = ReadDouble(compact, "confidence", 0.75d),
                            ["tags_json"] = Json.Serialize(tags),
                            ["source"] = "memory_consolidation",
                            ["updated_ts"] = now,
                            ["payload_json"] = Json.Serialize(summaryPayload)
                        });
                    InsertSummaryFts(connection, summaryId, summaryText, tags, entities.Concat(participants).Distinct(StringComparer.OrdinalIgnoreCase).ToList());
                    int sourceOrdinal = 0;
                    foreach (string memoryId in sourceMemoryIds)
                    {
                        LinkMemorySource(connection, "summary", summaryId, "memory", memoryId, sourceOrdinal++);
                    }
                    int eventOrdinal = 0;
                    foreach (string eventId in sourceEvents)
                    {
                        LinkMemorySource(connection, "summary", summaryId, "event", eventId, eventOrdinal++);
                    }
                    foreach (string memoryId in MemorySummaryCoversSources(summaryText, rows)
                        && ReadString(compact, "compactionStatus", "") == "complete" ? sourceMemoryIds : new List<string>())
                    {
                        ExecuteSql(connection, "UPDATE memories SET status='consolidated' WHERE memory_id=$memory_id;",
                            new Dictionary<string, object> { ["memory_id"] = memoryId });
                    }
                    publication.Commit();
                }

                WriteJsonObject(CharacterFile(campaignId, npcId, "memory", "summary.json"), new Dictionary<string, object>
                {
                    ["version"] = 2,
                    ["summaryId"] = summaryId,
                    ["summary"] = summaryText,
                    ["sourceEventIds"] = sourceEvents,
                    ["memoryGroupKey"] = group.Key,
                    ["updatedUtc"] = DateTime.UtcNow.ToString("o")
                });
                created.Add(new Dictionary<string, object>
                {
                    ["summaryId"] = summaryId,
                    ["memoryGroupKey"] = group.Key,
                    ["summary"] = summaryText,
                    ["sourceEventIds"] = sourceEvents,
                    ["sourceMemoryCount"] = sourceMemoryIds.Count,
                    ["method"] = ReadString(compact, "method", "deterministic"),
                    ["compactionStatus"] = ReadString(compact, "compactionStatus", "incomplete")
                });
                if (created.Count >= maxGroups)
                {
                    break;
                }
            }

            return new Dictionary<string, object>
            {
                ["ok"] = true,
                ["enabled"] = ReadBool(settings, "enableMemoryConsolidation", true),
                ["campaignId"] = campaignId,
                ["npcId"] = npcId,
                ["summaryCount"] = created.Count,
                ["compactionStatus"] = created.Any(r => ReadString(r, "compactionStatus", "") == "incomplete") ? "incomplete" : "complete",
                ["summaries"] = created
            };
        }

        private static Dictionary<string, object> BuildMiddleTermSummary(Dictionary<string, object> settings, string npcId, string groupKey,
            List<Dictionary<string, object>> rows, int sourceCharacterLimit = 60000, string sourceInstructions = "",
            string correlationId = "")
        {
            int maxChars = Math.Max(500, Math.Min(5000, ReadInt(settings, "memoryConsolidationMaxSummaryChars", 1800)));
            bool dialogueDerived = (groupKey ?? "").StartsWith("conversation:", StringComparison.OrdinalIgnoreCase)
                || (groupKey ?? "").StartsWith("scene:", StringComparison.OrdinalIgnoreCase);
            List<string> sourceText = rows
                .OrderBy(row => ReadLong(row, "ts", 0))
                .Select(row =>
                {
                    string value = ReadString(row, "summary", "").Trim();
                    bool independentlyVerified = ReadString(row, "memory_type", "")
                        .Equals("verified_system_evidence", StringComparison.OrdinalIgnoreCase);
                    return dialogueDerived && !independentlyVerified && !string.IsNullOrWhiteSpace(value)
                        ? "[DIALOGUE-DERIVED REPORTED SPEECH; NOT INDEPENDENT WORLD-FACT EVIDENCE] " + value
                        : value;
                })
                .Where(value => !string.IsNullOrWhiteSpace(value))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            sourceCharacterLimit = Math.Max(10000, Math.Min(120000, sourceCharacterLimit));
            string joined = BuildBalancedSummarySource(sourceText, sourceCharacterLimit);
            List<string> topics = TryExtractMinimeTopics(settings, joined, ReadInt(settings, "minimeMaxTopics", 5));
            bool useLlm = ReadBool(settings, "useMemoryLlmForConsolidation", true);
            if (useLlm && joined == string.Join("\n---\n", sourceText) && LlmProviderConfigured(settings))
            {
                Dictionary<string, object> llm = ChatWithLlm(new Dictionary<string, object>
                {
                    ["requestType"] = "memory",
                    ["correlationId"] = correlationId ?? string.Empty,
                    ["heroStringId"] = npcId,
                    ["temperature"] = 0.1d,
                    ["maxTokens"] = 1200,
                    ["messages"] = new List<Dictionary<string, object>>
                    {
                        new Dictionary<string, object>
                        {
                            ["role"] = "system",
                            ["content"] = "You are Bannerlord Reign's private memory consolidation worker. Return strict JSON only. Preserve uncertainty, promises, threats, names, outcomes, chronology, and the NPC's point of view. Do not invent facts. Dialogue proves what a speaker said or believed; it does not by itself prove that the speaker's factual claim was true. NPC autobiography, alibis, claimed work, claimed sales, claimed location, claimed eyewitness activity, and claimed world facts must remain explicitly attributed to that speaker unless a separate non-dialogue evidence record verifies them. Never convert vivid first-person dialogue into direct-witness evidence. Conversation participation proves only that a person heard or spoke in that conversation, not that they witnessed an older event described inside it. If one NPC denies witnessing an older event while another speaker says 'we', 'everyone', or 'all three', preserve the contradiction and never silently promote the collective wording into firsthand evidence. Consider every supplied record, including the final record, before describing who did or did not respond. Use neutral terms such as participant or speaker unless the supplied evidence explicitly establishes a person's title or social role; never generalize one participant's title to the entire group."
                        },
                        new Dictionary<string, object>
                        {
                            ["role"] = "user",
                            ["content"] = "Compress these related memory records into one searchable middle-term memory under " + maxChars + " characters. Return {\"summary\":\"...\",\"tags\":[\"...\"],\"confidence\":0.0}.\nGroup: " + groupKey
                                + "\nRecord count: " + sourceText.Count.ToString(CultureInfo.InvariantCulture)
                                + (string.IsNullOrWhiteSpace(sourceInstructions) ? "" : "\nSource rules: " + sourceInstructions.Trim())
                                + "\nRecords (chronological):\n" + joined
                        }
                    },
                    ["response_format"] = new Dictionary<string, object> { ["type"] = "json_object" }
                });
                Dictionary<string, object> parsed = ReadBool(llm, "ok", false) ? TryParseJsonObject(ReadString(llm, "content", "")) : null;
                string summary = ReadString(parsed, "summary", "");
                if (!string.IsNullOrWhiteSpace(summary) && summary.Trim().Length <= maxChars
                    && joined == string.Join("\n---\n", sourceText))
                {
                    return new Dictionary<string, object>
                    {
                        ["summary"] = dialogueDerived
                            ? EnsureConversationSummaryProvenance(summary.Trim(), maxChars)
                            : summary.Trim(),
                        ["tags"] = MergeStringLists(ReadStringList(parsed, "tags"), topics),
                        ["confidence"] = ClampDouble(ReadDouble(parsed, "confidence", 0.8d), 0d, 1d),
                        ["method"] = "memory_llm",
                        ["coverageComplete"] = MemorySummaryCoversSources(summary, rows),
                        ["compactionStatus"] = "complete",
                        ["sourceHash"] = MemorySourceHash(rows),
                        ["processingVersion"] = MemoryPrecisionVersion
                    };
                }
            }

            List<string> preferred = rows
                .Where(row => !ReadString(row, "memory_type", "").Equals("event", StringComparison.OrdinalIgnoreCase))
                .Select(row => ReadString(row, "summary", "").Trim())
                .Where(value => !string.IsNullOrWhiteSpace(value))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            if (preferred.Count == 0)
            {
                preferred = sourceText;
            }

            return ExtractiveMemoryFallback(sourceText, topics);
        }

        private static string EnsureConversationSummaryProvenance(string summary, int maxChars)
        {
            const string prefix = "Conversation record (reported speech; not independent proof of world facts): ";
            string value = (summary ?? "").Trim();
            if (!value.StartsWith(prefix, StringComparison.OrdinalIgnoreCase)) value = prefix + value;
            return value;
        }

        private static string BuildBalancedSummarySource(List<string> sourceText, int maxChars)
        {
            sourceText = (sourceText ?? new List<string>())
                .Where(value => !string.IsNullOrWhiteSpace(value))
                .Select(value => value.Trim())
                .ToList();
            if (sourceText.Count == 0) return "";
            maxChars = Math.Max(1000, maxChars);
            const string separator = "\n---\n";
            string complete = string.Join(separator, sourceText.ToArray());
            if (complete.Length <= maxChars) return complete;

            // A worker that cannot fit all source records must retain an
            // extractive fallback, rather than summarize clipped evidence.
            return string.Join(separator, SelectCompleteMemoryRecords(sourceText, maxChars));
        }

        private static void InsertSummaryFts(ReignDbConnection connection, string summaryId, string text, List<string> tags, List<string> entities)
        {
            ExecuteSql(connection, "DELETE FROM summary_fts WHERE summary_id=$summary_id;",
                new Dictionary<string, object> { ["summary_id"] = summaryId });
            ExecuteSql(connection, "INSERT INTO summary_fts(summary_id,text,tags,entities) VALUES($summary_id,$text,$tags,$entities);",
                new Dictionary<string, object>
                {
                    ["summary_id"] = summaryId,
                    ["text"] = text ?? "",
                    ["tags"] = string.Join(" ", tags ?? new List<string>()),
                    ["entities"] = string.Join(" ", entities ?? new List<string>())
                });
        }

        private static Dictionary<string, object> BuildNpcMemoryPacket(string campaignId, string npcId, string playerId, string locationId, string topic, int tokenBudget, Dictionary<string, object> npcContext = null, Dictionary<string, object> settingsOverride = null)
        {
            ReignTraceScope retrievalTrace = BeginReignSpan("memory.retrieve", new Dictionary<string, object>
            { ["campaignId"] = campaignId, ["npcId"] = npcId, ["playerId"] = playerId, ["tokenBudget"] = tokenBudget });
            Stopwatch timer = Stopwatch.StartNew();
            Stopwatch phaseTimer = Stopwatch.StartNew();
            Dictionary<string, object> timingPhases =
                new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
            List<Dictionary<string, object>> memories = new List<Dictionary<string, object>>();
            List<Dictionary<string, object>> relationships = new List<Dictionary<string, object>>();
            List<Dictionary<string, object>> obligations = new List<Dictionary<string, object>>();
            List<Dictionary<string, object>> beliefs = new List<Dictionary<string, object>>();
            List<Dictionary<string, object>> comprehension = new List<Dictionary<string, object>>();
            List<Dictionary<string, object>> summaries = new List<Dictionary<string, object>>();
            List<Dictionary<string, object>> temporalKnowledge = new List<Dictionary<string, object>>();
            List<Dictionary<string, object>> nativeWorldHistory = new List<Dictionary<string, object>>();
            List<string> warnings = new List<string>();
            List<string> sourceEventIds = new List<string>();
            Dictionary<string, object> settings = settingsOverride ?? LoadSettings();
            Dictionary<string, object> routeContext = npcContext == null
                ? new Dictionary<string, object>()
                : new Dictionary<string, object>(npcContext, StringComparer.OrdinalIgnoreCase);
            if (!routeContext.ContainsKey("worldDay"))
            {
                routeContext["worldDay"] = ReadDouble(routeContext, "currentWorldDay", 0d);
            }
            string precisionMode;
            using (var connection = OpenCampaignConnection(campaignId)) precisionMode = MemoryPrecisionMode(connection, settings);
            string precisionQuery = ReadString(routeContext, "memoryQueryText", topic);
            if (precisionMode == "precision")
            {
                var precise = BuildPrecisionMemoryPacket(campaignId, npcId, playerId, locationId, precisionQuery, routeContext, settings, false);
                retrievalTrace.Dispose();
                return precise;
            }
            Dictionary<string, object> retrievalRoute = BuildMemoryRetrievalRoute(settings, topic, routeContext);
            Dictionary<string, object> semanticRetrieval = TrySemanticMemorySearch(campaignId, precisionQuery, retrievalRoute, settings,
                null, ReadString(routeContext, "timelineId", ""), npcId);
            timingPhases["routeAndSemanticMs"] = phaseTimer.ElapsedMilliseconds;
            phaseTimer.Restart();
            Dictionary<string, object> exactHistory = new Dictionary<string, object>
            {
                ["text"] = "", ["matchedTurnIds"] = new List<string>(), ["expandedTurnIds"] = new List<string>()
            };
            List<string> minimeTopics = TryExtractMinimeTopics(settings, topic, ReadInt(settings, "minimeMaxTopics", 5));
            string topicWithHints = AppendMinimeTopics(topic, minimeTopics);
            List<string> queryTerms = MemoryQueryTerms(topicWithHints);
            HashSet<string> ftsMemoryIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            HashSet<string> ftsSummaryIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            HashSet<string> volatileSnapshotEventIds =
                new HashSet<string>(
                    StringComparer.OrdinalIgnoreCase);
            KnowledgeAccessContext knowledge = BuildKnowledgeAccessContext(npcId, playerId, locationId, npcContext);
            Dictionary<string, object> minimeRerank = MinimeRerankStatus(settings, "not_attempted");
            timingPhases["queryPreparationMs"] = phaseTimer.ElapsedMilliseconds;
            phaseTimer.Restart();

            using (ReignDbConnection connection = OpenCampaignConnection(campaignId))
            {
                timingPhases["connectionOpenMs"] = phaseTimer.ElapsedMilliseconds;
                phaseTimer.Restart();
                ftsMemoryIds = SearchMemoryFts(connection, queryTerms, 80, knowledge);
                ftsSummaryIds = SearchSummaryFts(connection, queryTerms, 40, knowledge);
                volatileSnapshotEventIds = new HashSet<string>(
                    QuerySql(connection,
                            @"SELECT event_id FROM events
WHERE event_type='daily_world_snapshot';")
                        .Select(row => ReadString(
                            row, "event_id", ""))
                        .Where(id =>
                            !string.IsNullOrWhiteSpace(id)),
                    StringComparer.OrdinalIgnoreCase);
                if (!string.IsNullOrWhiteSpace(playerId) || RouteHasLane(retrievalRoute, "interpersonal_history") || RouteHasLane(retrievalRoute, "commitments_and_plots"))
                {
                    List<string> relationshipTargets = string.IsNullOrWhiteSpace(playerId)
                        ? QuerySql(connection, @"SELECT hero_a_id,hero_b_id FROM relationship_pair_chemistry
WHERE hero_a_id=$npc OR hero_b_id=$npc ORDER BY last_day DESC LIMIT 8;",
                            new Dictionary<string, object> { ["npc"] = npcId })
                            .Select(row => ReadString(row, "hero_a_id", "").Equals(npcId, StringComparison.OrdinalIgnoreCase)
                                ? ReadString(row, "hero_b_id", "") : ReadString(row, "hero_a_id", ""))
                            .Where(id => !string.IsNullOrWhiteSpace(id)).Distinct(StringComparer.OrdinalIgnoreCase).ToList()
                        : new List<string> { playerId };
                    foreach (string target in relationshipTargets)
                    {
                        Dictionary<string, object> relationshipRequest = new Dictionary<string, object>
                        {
                            ["campaignId"] = campaignId, ["subjectId"] = npcId, ["targetId"] = target,
                            ["worldDay"] = ReadDouble(routeContext, "worldDay", 0d)
                        };
                        if (!string.IsNullOrWhiteSpace(playerId) && target.Equals(playerId, StringComparison.OrdinalIgnoreCase))
                            relationshipRequest["nativeRelation"] = ReadInt(npcContext, "relationToPlayer", 0);
                        Dictionary<string, object> relationship = RelationshipContextApi(relationshipRequest);
                        relationship["target_id"] = target;
                        relationships.Add(relationship);
                    }
                }
                timingPhases["ftsAndRelationshipsMs"] = phaseTimer.ElapsedMilliseconds;
                phaseTimer.Restart();
                obligations = QueryKnownRows(connection, "obligations", knowledge, "status IN ('unresolved','active','open','pending')", 12);
                beliefs = RouteHasLane(retrievalRoute, "beliefs_and_rumors")
                    ? FilterStructuredMemoryRows(MergeSemanticRows(
                        QueryKnownRows(connection, "beliefs", knowledge, "", 30),
                        LoadSemanticRows(connection, "beliefs", "belief_id", "belief", semanticRetrieval, knowledge), "belief_id"), queryTerms, 30)
                    : new List<Dictionary<string, object>>();
                if (RouteHasLane(retrievalRoute, "beliefs_and_rumors"))
                    beliefs.AddRange(LoadKnownSocialContextCandidates(connection, campaignId,
                        ReadString(routeContext, "timelineId", "main"), npcId,
                        ReadDouble(routeContext, "worldDay", 0d), topic));
                comprehension = RouteHasLane(retrievalRoute, "personal_state") || RouteHasLane(retrievalRoute, "interpersonal_history")
                    ? FilterStructuredMemoryRows(MergeSemanticRows(
                        QueryKnownRows(connection, "comprehension", knowledge, "", 24),
                        LoadSemanticRows(connection, "comprehension", "comprehension_id", "comprehension", semanticRetrieval, knowledge), "comprehension_id"), queryTerms, 24)
                    : new List<Dictionary<string, object>>();
                temporalKnowledge = LoadTemporalKnowledgeForPrompt(connection, campaignId, knowledge, queryTerms, 10);
                timingPhases["structuredMemoryMs"] = phaseTimer.ElapsedMilliseconds;
                phaseTimer.Restart();
                summaries = MergeSemanticRows(
                        QueryKnownRows(connection, "summaries", knowledge, "status='active'", 40)
                            .Concat(LoadFtsRows(connection, "summaries", "summary_id", ftsSummaryIds, knowledge)),
                        LoadSemanticRows(connection, "summaries", "summary_id", "summary", semanticRetrieval, knowledge), "summary_id")
                    .Where(row => SummaryRowAllowedByRoute(row, retrievalRoute))
                    .Where(row => !TextListFromJson(
                            ReadString(
                                row,
                                "source_events_json", "[]"))
                        .Any(id =>
                            volatileSnapshotEventIds.Contains(id)))
                    .Where(row => SummaryRowRelevant(row, queryTerms, ftsSummaryIds) || ReadDouble(row, "vectorSemanticScore", 0d) > 0d || RouteRecentFallback(row, retrievalRoute, "updated_ts"))
                    .Select(row =>
                    {
                        row["packetScore"] = AddSemanticScore(row, SummaryPacketScore(row, queryTerms, ftsSummaryIds, npcId, playerId, locationId), settings);
                        return row;
                    })
                    .ToList();
                timingPhases["summarySelectionMs"] = phaseTimer.ElapsedMilliseconds;
                phaseTimer.Restart();
                memories = MergeSemanticRows(
                        QueryKnownRows(connection, "memories", knowledge, "status='active'", 80)
                            .Concat(LoadFtsRows(connection, "memories", "memory_id", ftsMemoryIds, knowledge)),
                        LoadSemanticRows(connection, "memories", "memory_id", "memory", semanticRetrieval, knowledge), "memory_id")
                    .Where(row => MemoryRowAllowedByRoute(row, retrievalRoute) || ftsMemoryIds.Contains(ReadString(row, "memory_id", ""))
                        || ReadDouble(row, "vectorSemanticScore", 0d) > 0d)
                    .Where(row => !volatileSnapshotEventIds.Contains(
                        ReadString(row, "event_id", "")))
                    .Where(row => MemoryRowRelevant(row, queryTerms, ftsMemoryIds) || ReadDouble(row, "vectorSemanticScore", 0d) > 0d || RouteRecentFallback(row, retrievalRoute, "ts"))
                    .Select(row =>
                    {
                        row["packetScore"] = AddSemanticScore(row, MemoryPacketScore(row, queryTerms, ftsMemoryIds, npcId, playerId, locationId), settings);
                        return row;
                    })
                    .OrderByDescending(row => ReadDouble(row, "packetScore", 0d))
                    .ThenByDescending(row => ReadLong(row, "ts", 0))
                    .GroupBy(MemoryPacketDedupeKey, StringComparer.OrdinalIgnoreCase)
                    .Select(group => group.First())
                    .ToList();
                timingPhases["memorySelectionMs"] = phaseTimer.ElapsedMilliseconds;
                phaseTimer.Restart();
                string currentConversationSessionId = ReadFirstString(routeContext, "conversationSessionId", "sessionId", "conversationId");
                int rawTurnLimit = Math.Max(2, Math.Min(100, ReadInt(settings, "recentRawConversationTurns", 30)));
                int rawCharBudget = Math.Max(1200, Math.Min(50000, ReadInt(settings, "recentRawConversationCharBudget", 48000)));
                // Recent attributed dialogue is the continuity floor, not an optional
                // exact-recall lane. The player-facing setting promises that the latest
                // NPC-specific raw window remains available before summarized memory takes
                // priority, including complete group sessions in which this NPC participated.
                // Exclude the active session because its canonical transcript is assembled
                // separately by the production conversation controller.
                exactHistory = LoadMostRecentClosedConversation(connection, npcId, currentConversationSessionId,
                    rawCharBudget, rawTurnLimit, knowledge);
                if ((ReadBool(retrievalRoute, "needsExactTranscript", false) || queryTerms.Count > 0)
                    && !LooksLikeMostRecentConversationRecall(topic))
                {
                    Dictionary<string, object> targetedHistory = SearchExactConversationHistory(connection, npcId, topic,
                        retrievalRoute, ReadBool(routeContext, "deferContinuityAllocation", false) ? 24000 : 2400,
                        semanticRetrieval, currentConversationSessionId, rawTurnLimit, knowledge);
                    string targetedText = ReadString(targetedHistory, "text", "");
                    if (!string.IsNullOrWhiteSpace(targetedText))
                    {
                        string recentText = ReadString(exactHistory, "text", "");
                        List<string> recentIds = ReadStringList(exactHistory, "expandedTurnIds");
                        List<string> targetedIds = ReadStringList(targetedHistory, "expandedTurnIds");
                        bool addsOlderEvidence = targetedIds.Any(id => !recentIds.Contains(id, StringComparer.OrdinalIgnoreCase));
                        if (string.IsNullOrWhiteSpace(recentText))
                        {
                            exactHistory = targetedHistory;
                        }
                        else if (addsOlderEvidence)
                        {
                            exactHistory = new Dictionary<string, object>
                            {
                                ["text"] = recentText + "\n\nTargeted older exact-history evidence:\n" + targetedText,
                                ["matchedTurnIds"] = ReadStringList(exactHistory, "matchedTurnIds")
                                    .Concat(ReadStringList(targetedHistory, "matchedTurnIds"))
                                    .Distinct(StringComparer.OrdinalIgnoreCase).ToList(),
                                ["expandedTurnIds"] = recentIds.Concat(targetedIds)
                                    .Distinct(StringComparer.OrdinalIgnoreCase).ToList(),
                                ["sessionId"] = ReadString(targetedHistory, "sessionId", ReadString(exactHistory, "sessionId", "")),
                                ["selectionMode"] = "recent_plus_targeted_exact_history",
                                ["rawTurnLimit"] = ReadInt(exactHistory, "rawTurnLimit", rawTurnLimit),
                                ["rawTurnCount"] = ReadInt(exactHistory, "rawTurnCount", recentIds.Count)
                            };
                        }
                    }
                }
                timingPhases["exactHistoryMs"] = phaseTimer.ElapsedMilliseconds;
                phaseTimer.Restart();
                nativeWorldHistory = LoadKnownWorldHistoryForDialogue(connection,
                    ReadString(routeContext, "timelineId", ""), ReadDouble(routeContext, "worldDay", 0d),
                    knowledge, topic, retrievalRoute, semanticRetrieval,
                    ReadBool(ReadDictionary(routeContext, "identityView"), "knowsIdentity", false));
                timingPhases["nativeWorldHistoryMs"] = phaseTimer.ElapsedMilliseconds;
            }
            phaseTimer.Restart();

            // Candidate vectors are already persisted and scored by TrySemanticMemorySearch.
            // Re-embedding every selected row synchronously duplicated that work and was the
            // largest non-dialogue latency source. FTS, indexed semantic score, recency,
            // importance, lane, participant, and visibility scores remain fully active.
            minimeRerank = MinimeRerankStatus(settings, "indexed_semantic_scores_used");
            minimeRerank["attempted"] = false;
            minimeRerank["applied"] = ReadBool(semanticRetrieval, "applied", false);
            minimeRerank["method"] = "persistent_vector_index_plus_deterministic_rank";
            minimeRerank["candidateCount"] = summaries.Count + memories.Count + beliefs.Count + comprehension.Count;
            summaries = OrderRerankedRows(summaries, "updated_ts").Take(8).ToList();
            memories = OrderRerankedRows(memories, "ts").Take(16).ToList();
            beliefs = OrderRerankedRows(beliefs, "ts").Take(8).ToList();
            comprehension = OrderRerankedRows(comprehension, "ts").Take(6).ToList();

            string currentNpcName = ReadFirstString(routeContext, "name", "heroName", "speakerName");
            string currentPlayerName = ReadFirstString(routeContext, "mainHeroName", "playerName");
            string currentPlayerId = ReadFirstString(routeContext, "mainHeroStringId", "playerHeroStringId", "playerId");
            List<string> interactionNpcNames = MergedInteractionParticipantProfiles(routeContext)
                .Where(profile => !CharacterIdFrom(profile).Equals(currentPlayerId, StringComparison.OrdinalIgnoreCase)
                    && !ReadString(profile, "role", "npc").Equals("player", StringComparison.OrdinalIgnoreCase))
                .Select(profile => ReadString(profile, "name", ""))
                .Concat(new[] { currentNpcName })
                .Where(name => !string.IsNullOrWhiteSpace(name))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            int legacyRoleCollisions = summaries.Count(row => IsLegacyPlayerNpcRoleCollision(row, interactionNpcNames, currentPlayerName))
                + memories.Count(row => IsLegacyPlayerNpcRoleCollision(row, interactionNpcNames, currentPlayerName))
                + beliefs.Count(row => IsLegacyPlayerNpcRoleCollision(row, interactionNpcNames, currentPlayerName))
                + comprehension.Count(row => IsLegacyPlayerNpcRoleCollision(row, interactionNpcNames, currentPlayerName))
                + temporalKnowledge.Count(row => IsLegacyPlayerNpcRoleCollision(row, interactionNpcNames, currentPlayerName));
            if (legacyRoleCollisions > 0)
            {
                summaries = summaries.Where(row => !IsLegacyPlayerNpcRoleCollision(row, interactionNpcNames, currentPlayerName)).ToList();
                memories = memories.Where(row => !IsLegacyPlayerNpcRoleCollision(row, interactionNpcNames, currentPlayerName)).ToList();
                beliefs = beliefs.Where(row => !IsLegacyPlayerNpcRoleCollision(row, interactionNpcNames, currentPlayerName)).ToList();
                comprehension = comprehension.Where(row => !IsLegacyPlayerNpcRoleCollision(row, interactionNpcNames, currentPlayerName)).ToList();
                temporalKnowledge = temporalKnowledge.Where(row => !IsLegacyPlayerNpcRoleCollision(row, interactionNpcNames, currentPlayerName)).ToList();
                warnings.Add("Quarantined " + legacyRoleCollisions.ToString(CultureInfo.InvariantCulture)
                    + " legacy memory record(s) that assigned a current NPC participant's name to the player despite the authoritative role map.");
            }

            int feedbackLoopRecords = 0;
            Func<List<Dictionary<string, object>>, string, List<Dictionary<string, object>>> quarantineRoleplayFeedback =
                (rows, textKey) =>
                {
                    List<Dictionary<string, object>> safe = new List<Dictionary<string, object>>();
                    foreach (Dictionary<string, object> row in rows ?? new List<Dictionary<string, object>>())
                    {
                        if (IsRoleplayFeedbackLoopEvidence(row, ReadString(row, textKey, "")))
                        {
                            feedbackLoopRecords++;
                            continue;
                        }
                        safe.Add(row);
                    }
                    return safe;
                };
            summaries = quarantineRoleplayFeedback(summaries, "summary");
            memories = quarantineRoleplayFeedback(memories, "summary");
            obligations = quarantineRoleplayFeedback(obligations, "description");
            beliefs = quarantineRoleplayFeedback(beliefs, "claim");
            comprehension = quarantineRoleplayFeedback(comprehension, "text");
            temporalKnowledge = quarantineRoleplayFeedback(temporalKnowledge, "claim");
            exactHistory = QuarantineRoleplayFeedbackExactHistory(
                exactHistory, out int quarantinedExactLines);
            feedbackLoopRecords += quarantinedExactLines;
            if (feedbackLoopRecords > 0)
            {
                warnings.Add("Quarantined " + feedbackLoopRecords.ToString(CultureInfo.InvariantCulture)
                    + " conversation-derived record(s) that would recursively turn role-play refusal, fictional absence, or absolute future prediction into current fact. Canonical audit history was preserved.");
            }

            if (knowledge.PlayerIdentityUnknown)
            {
                int identityRejected = 0;
                Func<List<Dictionary<string, object>>, string, List<Dictionary<string, object>>> protect =
                    (rows, textKey) =>
                    {
                        List<Dictionary<string, object>> safe = new List<Dictionary<string, object>>();
                        foreach (Dictionary<string, object> row in rows ?? new List<Dictionary<string, object>>())
                        {
                            string evidence = ReadString(row, textKey, "");
                            if (!UnknownIdentityMemoryEvidenceAllowed(row, knowledge, evidence))
                            {
                                identityRejected++;
                                continue;
                            }
                            safe.Add(SanitizeUnknownIdentityMemoryRow(row, knowledge));
                        }
                        return safe;
                    };
                summaries = protect(summaries, "summary");
                memories = protect(memories, "summary");
                obligations = protect(obligations, "description");
                beliefs = protect(beliefs, "claim");
                comprehension = protect(comprehension, "text");
                temporalKnowledge = protect(temporalKnowledge, "claim");
                relationships = relationships.Select(row => SanitizeUnknownIdentityMemoryRow(row, knowledge)).ToList();
                exactHistory = SanitizeUnknownIdentityExactHistory(exactHistory, knowledge);
                if (identityRejected > 0)
                {
                    warnings.Add("Withheld " + identityRejected.ToString(CultureInfo.InvariantCulture)
                        + " retrieved record(s) whose canonical identity or private player status was unavailable to this observer.");
                }
            }

            foreach (Dictionary<string, object> row in memories.Concat(obligations).Concat(beliefs).Concat(comprehension))
            {
                string eventId = ReadString(row, "event_id", "");
                if (!string.IsNullOrWhiteSpace(eventId))
                {
                    sourceEventIds.Add(eventId);
                }
            }
            foreach (Dictionary<string, object> row in summaries)
            {
                sourceEventIds.AddRange(TextListFromJson(ReadString(row, "source_events_json", "[]")));
            }

            if (string.IsNullOrWhiteSpace(knowledge.NpcId))
            {
                warnings.Add("No npc_id/heroStringId was supplied; private knowledge filtering is limited.");
            }

            int exactReserve = string.IsNullOrWhiteSpace(ReadString(exactHistory, "text", "")) ? 0
                : ReadInt(exactHistory, "rawTurnCount", 0) > 0
                    ? Math.Max(1200, Math.Min(Math.Max(1200, tokenBudget - 400), (int)Math.Ceiling(ReadString(exactHistory, "text", "").Length / 4d))) : 600;
            bool deferAllocation = ReadBool(routeContext, "deferContinuityAllocation", false);
            string nativeHistoryText = FormatKnownWorldHistoryForDialogue(nativeWorldHistory,
                deferAllocation ? 24000 : Math.Min(2400, Math.Max(800, tokenBudget * 4 / 3)));
            int nativeReserve = (int)Math.Ceiling(nativeHistoryText.Length / 4d);
            string packet = BuildMemoryPacketText(npcId, playerId, summaries, memories, relationships, obligations, beliefs, comprehension,
                warnings, retrievalRoute, Math.Max(400, tokenBudget - exactReserve - nativeReserve), deferAllocation);
            if (!string.IsNullOrWhiteSpace(nativeHistoryText)) packet = nativeHistoryText + "\n\n" + packet;
            sourceEventIds.AddRange(nativeWorldHistory.Select(row => ReadString(row, "event_id", "")));
            string temporalText = FormatTemporalKnowledgeForPrompt(temporalKnowledge);
            if (!string.IsNullOrWhiteSpace(temporalText))
                packet = packet.TrimEnd() + "\n\n" + temporalText;
            string exactText = ReadString(exactHistory, "text", "");
            if (!string.IsNullOrWhiteSpace(exactText))
            {
                packet = packet.TrimEnd() + "\n\nExact conversation source (use for precise continuity; do not invent omitted lines):\n" + exactText;
            }
            timingPhases["rankingAndFormattingMs"] = phaseTimer.ElapsedMilliseconds;
            timer.Stop();
            Dictionary<string, object> memoryPacketResult = new Dictionary<string, object>
            {
                ["memoryPacket"] = packet,
                ["retrievalRoute"] = retrievalRoute,
                ["semanticRetrieval"] = new Dictionary<string, object>
                {
                    ["enabled"] = ReadBool(semanticRetrieval, "enabled", false), ["attempted"] = ReadBool(semanticRetrieval, "attempted", false),
                    ["applied"] = ReadBool(semanticRetrieval, "applied", false), ["reason"] = ReadString(semanticRetrieval, "reason", ""),
                    ["resultCount"] = ReadInt(semanticRetrieval, "resultCount", 0), ["durationMs"] = ReadLong(semanticRetrieval, "durationMs", 0),
                    ["error"] = ReadString(semanticRetrieval, "error", ""),
                    ["workerTiming"] = ReadDictionary(semanticRetrieval, "workerTiming") ?? new Dictionary<string, object>()
                },
                ["minimeTopics"] = minimeTopics,
                ["minimeRerank"] = minimeRerank,
                ["sourceSummaryIds"] = summaries.Select(row => ReadString(row, "summary_id", "")).Where(id => !string.IsNullOrWhiteSpace(id)).ToList(),
                ["matchedTurnIds"] = ReadStringList(exactHistory, "matchedTurnIds"),
                ["expandedTurnIds"] = ReadStringList(exactHistory, "expandedTurnIds"),
                ["exactHistorySessionId"] = ReadString(exactHistory, "sessionId", ""),
                ["exactHistorySelectionMode"] = ReadString(exactHistory, "selectionMode", ""),
                ["recentRawTurnLimit"] = ReadInt(exactHistory, "rawTurnLimit", 0),
                ["recentRawTurnCount"] = ReadInt(exactHistory, "rawTurnCount", 0),
                ["exactHistoryChars"] = ReadString(exactHistory, "text", "").Length,
                ["sourceEventIds"] = sourceEventIds.Distinct(StringComparer.OrdinalIgnoreCase).Take(40).ToList(),
                ["warnings"] = warnings,
                ["counts"] = new Dictionary<string, object>
                {
                    ["memories"] = memories.Count,
                    ["middleTermSummaries"] = summaries.Count,
                    ["relationships"] = relationships.Count,
                    ["obligations"] = obligations.Count,
                    ["beliefs"] = beliefs.Count,
                    ["comprehension"] = comprehension.Count,
                    ["temporalKnowledge"] = temporalKnowledge.Count,
                    ["nativeWorldHistory"] = nativeWorldHistory.Count,
                    ["exactTranscriptTurns"] = ReadStringList(exactHistory, "expandedTurnIds").Count
                },
                ["timingMs"] = timer.ElapsedMilliseconds
            };
            memoryPacketResult["timingPhases"] = timingPhases;
            if (precisionMode == "shadow")
            {
                var shadow = BuildPrecisionMemoryPacket(campaignId, npcId, playerId, locationId, precisionQuery, routeContext, settings, true);
                memoryPacketResult["precisionEvidence"] = ReadDictionary(shadow, "precisionEvidence");
                memoryPacketResult["precisionShadowCharacters"] = ReadString(shadow, "memoryPacket", "").Length;
                memoryPacketResult["legacyMemoryCharacters"] = packet.Length;
            }
            retrievalTrace.Set("durationMs", timer.ElapsedMilliseconds);
            retrievalTrace.Set("memoryCount", memories.Count);
            retrievalTrace.Set("summaryCount", summaries.Count);
            retrievalTrace.Set("temporalKnowledgeCount", temporalKnowledge.Count);
            retrievalTrace.Set("semanticApplied", ReadBool(semanticRetrieval, "applied", false));
            retrievalTrace.Dispose();
            return memoryPacketResult;
        }

        private static List<Dictionary<string, object>> QueryKnownRows(ReignDbConnection connection, string table, KnowledgeAccessContext knowledge, string extraWhere, int limit, List<string> queryTerms = null)
        {
            if (!new[] { "events", "memories", "summaries", "beliefs", "comprehension", "obligations" }.Contains(table))
                throw new InvalidOperationException("Unknown memory candidate table.");
            string where = string.IsNullOrWhiteSpace(extraWhere) ? "1=1" : "(" + extraWhere + ")";
            where += " AND COALESCE(payload_json,'{}') NOT LIKE '%\"continuityQuarantined\":true%'";
            where += " AND " + MemoryEligibilitySql(table);
            string order = table == "summaries" ? "updated_ts" : "ts";
            if(queryTerms != null && queryTerms.Count>0)
            {
                if(table != "beliefs" && table != "comprehension") throw new InvalidOperationException("Mental recall query requires an owned mental layer.");
                string field=table=="beliefs" ? "claim" : "text";
                where+=" AND to_tsvector('simple',"+field+") @@ websearch_to_tsquery('simple',$query)";
                order="ts_rank(to_tsvector('simple',"+field+"),websearch_to_tsquery('simple',$query)) DESC,"+order;
            }
            string key = table == "events" ? "event_id" : table == "memories" ? "memory_id" : table == "summaries" ? "summary_id"
                : table == "beliefs" ? "belief_id" : table == "obligations" ? "obligation_id" : "comprehension_id";
            var result = new List<Dictionary<string, object>>();
            int offset = 0, batch = Math.Max(64, Math.Min(256, limit * 4));
            // Regional scope and identity rules are rechecked before counting
            // toward the candidate limit; unrelated rows cannot exhaust it.
            while (result.Count < Math.Max(1, limit))
            {
                var rows = QuerySql(connection, "SELECT * FROM " + table + " WHERE " + where
                    + " ORDER BY " + order + " DESC," + key + " LIMIT $batch OFFSET $offset;",
                    new Dictionary<string, object> { ["observer"] = knowledge?.NpcId ?? "", ["batch"] = batch, ["offset"] = offset,
                        ["query"] = BuildFtsQuery(queryTerms ?? new List<string>()) });
                result.AddRange(rows.Where(row => KnowledgeRowVisibleToNpc(table, row, knowledge)).Take(Math.Max(1, limit) - result.Count));
                if (rows.Count < batch) break;
                offset += batch;
            }
            return result;
        }

        private static List<Dictionary<string, object>> LoadFtsRows(ReignDbConnection connection, string table, string idColumn,
            IEnumerable<string> ids, KnowledgeAccessContext knowledge)
        {
            if (!string.Equals(table, "memories", StringComparison.OrdinalIgnoreCase)
                && !string.Equals(table, "summaries", StringComparison.OrdinalIgnoreCase))
            {
                return new List<Dictionary<string, object>>();
            }
            if (!string.Equals(idColumn, "memory_id", StringComparison.OrdinalIgnoreCase)
                && !string.Equals(idColumn, "summary_id", StringComparison.OrdinalIgnoreCase))
            {
                return new List<Dictionary<string, object>>();
            }

            List<string> selectedIds = (ids ?? Enumerable.Empty<string>())
                .Where(id => !string.IsNullOrWhiteSpace(id))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(120)
                .ToList();
            if (selectedIds.Count == 0)
            {
                return new List<Dictionary<string, object>>();
            }

            Dictionary<string, object> parameters = new Dictionary<string, object>();
            List<string> placeholders = new List<string>();
            for (int index = 0; index < selectedIds.Count; index++)
            {
                string key = "fts_id_" + index.ToString(CultureInfo.InvariantCulture);
                placeholders.Add("$" + key);
                parameters[key] = selectedIds[index];
            }

            return QuerySql(connection, "SELECT * FROM " + table + " WHERE status='active' AND " + idColumn
                    + " IN (" + string.Join(",", placeholders.ToArray()) + ");", parameters)
                .Where(row => KnowledgeRowVisibleToNpc(table, row, knowledge))
                .ToList();
        }

        private static bool KnowledgeRowVisibleToNpc(string table, Dictionary<string, object> row, KnowledgeAccessContext knowledge)
        {
            if (row == null)
            {
                return false;
            }
            if (ReadBool(TryParseJsonObject(ReadString(row, "payload_json", "{}")), "continuityQuarantined", false)) return false;

            knowledge = knowledge ?? new KnowledgeAccessContext();
            if (!MemoryTimeVisible(row, knowledge)) return false;
            string id = knowledge.NpcId;
            if (!knowledge.HasNpc)
            {
                if (table == "beliefs" || table == "comprehension") return false;
                return KnowledgeVisibilityAllows(row, knowledge);
            }

            if (KnowledgeListContains(row, "hidden_from_json", id))
            {
                return false;
            }

            string tableName = table ?? "";
            if (tableName.Equals("beliefs", StringComparison.OrdinalIgnoreCase))
            {
                return KnowledgeIdEquals(ReadString(row, "believer_id", ""), id);
            }

            if (tableName.Equals("obligations", StringComparison.OrdinalIgnoreCase))
            {
                return KnowledgeVisibilityAllows(row, knowledge)
                    || KnowledgeIdEquals(ReadString(row, "owed_by", ""), id)
                    || KnowledgeIdEquals(ReadString(row, "owed_to", ""), id)
                    || KnowledgeListContains(row, "known_by_json", id)
                    || KnowledgeListContains(row, "participants_json", id);
            }

            if (tableName.Equals("comprehension", StringComparison.OrdinalIgnoreCase))
            {
                return KnowledgeIdEquals(ReadString(row, "owner_id", ""), id);
            }

            if (tableName.Equals("summaries", StringComparison.OrdinalIgnoreCase))
            {
                return KnowledgeIdEquals(ReadString(row, "owner_id", ""), id)
                    || KnowledgeListContains(row, "known_by_json", id)
                    || KnowledgeVisibilityAllows(row, knowledge);
            }

            return KnowledgeVisibilityAllows(row, knowledge)
                || KnowledgeIdEquals(ReadString(row, "owner_id", ""), id)
                || KnowledgeListContains(row, "known_by_json", id)
                || KnowledgeListContains(row, "participants_json", id)
                || KnowledgeListContains(row, "witnesses_json", id)
                || KnowledgeListContains(row, "heard_as_rumor_by_json", id)
                || KnowledgePayloadListContains(row, id, "attendees", "attendeeIds", "nearbyHeroIds", "nearbyHeroes");
        }

        private sealed class KnowledgeAccessContext
        {
            public string NpcId = "";
            public string TimelineId = "";
            public double WorldDay = double.MaxValue;
            public string PlayerId = "";
            public string PlayerName = "";
            public string PlayerClanId = "";
            public string PlayerClanName = "";
            public string PlayerKingdomId = "";
            public string PlayerKingdomName = "";
            public string LocationId = "";
            public string KingdomId = "";
            public string ClanId = "";
            public string SettlementId = "";
            public string PartyId = "";
            public bool PlayerIdentityUnknown;
            public readonly HashSet<string> AllScopeIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            public readonly HashSet<string> KingdomIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            public readonly HashSet<string> ClanIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            public readonly HashSet<string> SettlementIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            public readonly HashSet<string> PartyIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            public readonly HashSet<string> ArmyIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            public bool HasNpc
            {
                get { return !string.IsNullOrWhiteSpace(NpcId); }
            }
        }

        private static KnowledgeAccessContext BuildKnowledgeAccessContext(string npcId, string playerId, string locationId, Dictionary<string, object> source)
        {
            source = source ?? new Dictionary<string, object>();
            Dictionary<string, object> profile = ReadDictionary(source, "hero")
                ?? ReadDictionary(source, "profile")
                ?? ReadDictionary(source, "speaker")
                ?? ReadDictionary(source, "npc")
                ?? source;

            KnowledgeAccessContext context = new KnowledgeAccessContext
            {
                TimelineId = ReadString(source, "timelineId", ""),
                WorldDay = ReadDouble(source, "worldDay", ReadDouble(source, "currentWorldDay", double.MaxValue)),
                NpcId = NormalizeKnowledgeId(FirstNonEmpty(npcId, ReadFirstString(source, "npcId", "heroStringId", "heroId", "speakerHeroStringId", "characterId"), ReadFirstString(profile, "npcId", "heroStringId", "heroId"))),
                PlayerId = NormalizeKnowledgeId(FirstNonEmpty(playerId, ReadFirstString(source, "playerId", "mainHeroStringId", "playerHeroStringId"), ReadFirstString(profile, "mainHeroStringId", "playerHeroStringId"))),
                PlayerName = FirstNonEmpty(ReadFirstString(source, "mainHeroName", "playerName"), ReadFirstString(profile, "mainHeroName", "playerName")),
                PlayerClanId = NormalizeKnowledgeId(FirstNonEmpty(ReadFirstString(source, "playerClanId", "playerClanStringId", "mainHeroClanId"), ReadFirstString(profile, "playerClanId", "playerClanStringId", "mainHeroClanId"))),
                PlayerClanName = FirstNonEmpty(ReadFirstString(source, "playerClanName", "mainHeroClanName"), ReadFirstString(profile, "playerClanName", "mainHeroClanName")),
                PlayerKingdomId = NormalizeKnowledgeId(FirstNonEmpty(ReadFirstString(source, "playerKingdomId", "playerKingdomStringId", "mainHeroKingdomId"), ReadFirstString(profile, "playerKingdomId", "playerKingdomStringId", "mainHeroKingdomId"))),
                PlayerKingdomName = FirstNonEmpty(ReadFirstString(source, "playerKingdomName", "mainHeroKingdomName"), ReadFirstString(profile, "playerKingdomName", "mainHeroKingdomName")),
                LocationId = NormalizeKnowledgeId(FirstNonEmpty(locationId, ReadFirstString(source, "locationId", "currentSettlementId", "settlementId"), ReadFirstString(profile, "currentSettlementId", "settlementId", "lastKnownSettlementId"))),
                KingdomId = NormalizeKnowledgeId(FirstNonEmpty(ReadFirstString(source, "npcKingdomId", "speakerKingdomId", "kingdomId"), ReadFirstString(profile, "kingdomId", "kingdomStringId", "mapFactionId"))),
                ClanId = NormalizeKnowledgeId(FirstNonEmpty(ReadFirstString(source, "npcClanId", "speakerClanId", "clanId"), ReadFirstString(profile, "clanId", "clanStringId"))),
                SettlementId = NormalizeKnowledgeId(FirstNonEmpty(ReadFirstString(source, "npcSettlementId", "currentSettlementId", "settlementId", "homeSettlementId", "governedSettlementId"), ReadFirstString(profile, "currentSettlementId", "settlementId", "homeSettlementId", "governedSettlementId"), locationId)),
                PartyId = NormalizeKnowledgeId(FirstNonEmpty(ReadFirstString(source, "npcPartyId", "speakerPartyId", "partyId"), ReadFirstString(profile, "partyId", "currentPartyId")))
            };
            Dictionary<string, object> identityView = ReadDictionary(source, "identityView");
            context.PlayerIdentityUnknown = identityView != null && !ReadBool(identityView, "knowsIdentity", false);

            AddKnowledgeContextId(context.AllScopeIds, context.NpcId);
            AddKnowledgeContextId(context.AllScopeIds, context.KingdomId);
            AddKnowledgeContextId(context.AllScopeIds, context.ClanId);
            AddKnowledgeContextId(context.AllScopeIds, context.LocationId);
            AddKnowledgeContextId(context.AllScopeIds, context.SettlementId);
            AddKnowledgeContextId(context.AllScopeIds, context.PartyId);

            AddKnowledgeContextId(context.KingdomIds, context.KingdomId);
            AddKnowledgeContextId(context.ClanIds, context.ClanId);
            AddKnowledgeContextId(context.SettlementIds, context.LocationId);
            AddKnowledgeContextId(context.SettlementIds, context.SettlementId);
            AddKnowledgeContextId(context.PartyIds, context.PartyId);

            AddKnowledgeContextIds(context.KingdomIds, KnowledgeValuesFromDictionary(source, "kingdomIds", "npcKingdomIds", "nearbyKingdomIds"));
            AddKnowledgeContextIds(context.KingdomIds, KnowledgeValuesFromDictionary(profile, "kingdomIds", "npcKingdomIds", "nearbyKingdomIds"));
            AddKnowledgeContextIds(context.ClanIds, KnowledgeValuesFromDictionary(source, "clanIds", "npcClanIds", "nearbyClanIds"));
            AddKnowledgeContextIds(context.ClanIds, KnowledgeValuesFromDictionary(profile, "clanIds", "npcClanIds", "nearbyClanIds"));
            AddKnowledgeContextIds(context.SettlementIds, KnowledgeValuesFromDictionary(source, "settlementIds", "nearbySettlementIds", "visibleSettlementIds"));
            AddKnowledgeContextIds(context.SettlementIds, KnowledgeValuesFromDictionary(profile, "settlementIds", "nearbySettlementIds", "visibleSettlementIds"));
            AddKnowledgeContextIds(context.PartyIds, KnowledgeValuesFromDictionary(source, "partyIds", "nearbyPartyIds", "visiblePartyIds"));
            AddKnowledgeContextIds(context.PartyIds, KnowledgeValuesFromDictionary(profile, "partyIds", "nearbyPartyIds", "visiblePartyIds"));
            AddKnowledgeContextIds(context.ArmyIds, KnowledgeValuesFromDictionary(source, "armyIds", "nearbyArmyIds", "visibleArmyIds"));
            AddKnowledgeContextIds(context.ArmyIds, KnowledgeValuesFromDictionary(profile, "armyIds", "nearbyArmyIds", "visibleArmyIds"));

            AddKnowledgeContextIds(context.AllScopeIds, context.KingdomIds);
            AddKnowledgeContextIds(context.AllScopeIds, context.ClanIds);
            AddKnowledgeContextIds(context.AllScopeIds, context.SettlementIds);
            AddKnowledgeContextIds(context.AllScopeIds, context.PartyIds);
            AddKnowledgeContextIds(context.AllScopeIds, context.ArmyIds);
            return context;
        }

        private static bool KnowledgeVisibilityAllows(Dictionary<string, object> row, KnowledgeAccessContext context)
        {
            Dictionary<string, object> payload = KnowledgePayload(row);
            string visibility = ReadString(row, "visibility", "").Trim();
            string visibilityKey = NormalizeKnowledgeScopeKey(visibility);
            string scope = KnowledgeScopeText(row, payload);

            if (visibilityKey.Equals("world", StringComparison.OrdinalIgnoreCase)
                || visibilityKey.Equals("global", StringComparison.OrdinalIgnoreCase)
                || visibilityKey.Equals("common", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            if (visibilityKey.StartsWith("public", StringComparison.OrdinalIgnoreCase))
            {
                if (KnowledgeIsCommonWorldEvent(row, payload))
                {
                    return true;
                }

                string inlineScope = "";
                if (visibility.Length > 6 && visibility[6] == '_')
                {
                    inlineScope = visibility.Substring(7);
                }

                scope = FirstNonEmpty(scope, inlineScope);
                if (string.IsNullOrWhiteSpace(scope) && !KnowledgeHasExplicitScope(row, payload))
                {
                    return true;
                }

                return KnowledgeScopeMatches(scope, row, payload, context);
            }

            if (visibilityKey.Equals("local", StringComparison.OrdinalIgnoreCase)
                || visibilityKey.Equals("nearby", StringComparison.OrdinalIgnoreCase)
                || visibilityKey.Equals("kingdom", StringComparison.OrdinalIgnoreCase)
                || visibilityKey.Equals("clan", StringComparison.OrdinalIgnoreCase)
                || visibilityKey.Equals("settlement", StringComparison.OrdinalIgnoreCase)
                || visibilityKey.Equals("party", StringComparison.OrdinalIgnoreCase)
                || visibilityKey.Equals("army", StringComparison.OrdinalIgnoreCase))
            {
                return KnowledgeScopeMatches(visibility, row, payload, context);
            }

            return false;
        }

        private static bool KnowledgeIsCommonWorldEvent(Dictionary<string, object> row, Dictionary<string, object> payload)
        {
            string eventType = NormalizeKnowledgeScopeKey(FirstNonEmpty(
                ReadFirstString(payload, "eventType", "event_type", "type", "worldEventType", "world_event_type"),
                ReadString(row, "event_type", ""),
                ReadString(row, "memory_type", "")));
            if (string.IsNullOrWhiteSpace(eventType))
            {
                return false;
            }

            if (eventType.Contains("private")
                || eventType.Contains("nearby")
                || eventType.Contains("scout")
                || eventType.Contains("conversation")
                || eventType.Contains("trade")
                || eventType.Contains("bargain")
                || eventType.Contains("secret")
                || eventType.Contains("promise")
                || eventType.Contains("threat")
                || eventType.Contains("blackmail"))
            {
                return false;
            }

            return eventType.Contains("war")
                || eventType.Contains("peace")
                || eventType.Contains("alliance")
                || eventType.Contains("treaty")
                || eventType.Contains("pact")
                || eventType.Contains("marriage")
                || eventType.Contains("kingdom")
                || eventType.Contains("rebellion")
                || eventType.Contains("settlement_captured")
                || eventType.Contains("settlement_owner")
                || eventType.Contains("fief_granted")
                || eventType.Contains("siege_result");
        }

        private static bool KnowledgeScopeMatches(string scope, Dictionary<string, object> row, Dictionary<string, object> payload, KnowledgeAccessContext context)
        {
            context = context ?? new KnowledgeAccessContext();
            string scopeKey = NormalizeKnowledgeScopeKey(scope);
            List<string> scopeIds = KnowledgeScopedIds(row, payload);

            if (string.IsNullOrWhiteSpace(scopeKey))
            {
                return scopeIds.Count > 0 && KnowledgeContainsAny(context.AllScopeIds, scopeIds);
            }

            if (scopeKey.Equals("world", StringComparison.OrdinalIgnoreCase)
                || scopeKey.Equals("global", StringComparison.OrdinalIgnoreCase)
                || scopeKey.Equals("common", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            if (scopeKey.Contains("kingdom") || scopeKey.Contains("faction"))
            {
                List<string> ids = MergeStringLists(scopeIds, KnowledgeValuesFromDictionary(payload, "scopeKingdomIds", "scope_kingdom_ids", "kingdomIds", "kingdomId", "actorKingdomId", "actorKingdomStringId", "targetKingdomId", "targetKingdomStringId", "ownerKingdomId"));
                return KnowledgeContainsAny(context.KingdomIds, ids);
            }

            if (scopeKey.Contains("clan"))
            {
                List<string> ids = MergeStringLists(scopeIds, KnowledgeValuesFromDictionary(payload, "scopeClanIds", "scope_clan_ids", "clanIds", "clanId", "actorClanId", "actorClanStringId", "targetClanId", "targetClanStringId", "ownerClanId"));
                return KnowledgeContainsAny(context.ClanIds, ids);
            }

            if (scopeKey.Contains("settlement") || scopeKey.Contains("local") || scopeKey.Contains("town") || scopeKey.Contains("castle") || scopeKey.Contains("village"))
            {
                List<string> ids = MergeStringLists(scopeIds, KnowledgeValuesFromDictionary(payload, "scopeSettlementIds", "scope_settlement_ids", "settlementIds", "settlementId", "locationId", "currentSettlementId", "targetSettlementId", "boundSettlementId"));
                ids = MergeStringLists(ids, new[] { ReadString(row, "location_id", "") });
                return KnowledgeContainsAny(context.SettlementIds, ids);
            }

            if (scopeKey.Contains("party") || scopeKey.Contains("nearby"))
            {
                List<string> ids = MergeStringLists(scopeIds, KnowledgeValuesFromDictionary(payload, "scopePartyIds", "scope_party_ids", "partyIds", "partyId", "nearbyPartyIds", "visiblePartyIds", "actorPartyId", "targetPartyId"));
                return KnowledgeContainsAny(context.PartyIds, ids)
                    || KnowledgePayloadListContains(row, context.NpcId, "nearbyHeroIds", "nearbyHeroes", "visibleHeroIds", "visibleHeroes")
                    || KnowledgeContainsAny(context.SettlementIds, MergeStringLists(KnowledgeValuesFromDictionary(payload, "locationId", "settlementId", "currentSettlementId"), new[] { ReadString(row, "location_id", "") }));
            }

            if (scopeKey.Contains("army") || scopeKey.Contains("danger") || scopeKey.Contains("siege") || scopeKey.Contains("raid"))
            {
                List<string> ids = MergeStringLists(scopeIds, KnowledgeValuesFromDictionary(payload, "scopeArmyIds", "scope_army_ids", "armyIds", "armyId", "nearbyArmyIds", "visibleArmyIds", "attackingArmyId", "defendingArmyId"));
                return KnowledgeContainsAny(context.ArmyIds, ids)
                    || KnowledgeContainsAny(context.PartyIds, KnowledgeValuesFromDictionary(payload, "nearbyPartyIds", "visiblePartyIds", "partyIds"))
                    || KnowledgeContainsAny(context.SettlementIds, MergeStringLists(KnowledgeValuesFromDictionary(payload, "locationId", "settlementId", "currentSettlementId", "targetSettlementId"), new[] { ReadString(row, "location_id", "") }));
            }

            if (scopeKey.Contains("attendee") || scopeKey.Contains("witness"))
            {
                return KnowledgeListContains(row, "witnesses_json", context.NpcId)
                    || KnowledgePayloadListContains(row, context.NpcId, "attendees", "attendeeIds", "witnesses", "witnessIds");
            }

            return KnowledgeContainsAny(context.AllScopeIds, scopeIds);
        }

        private static bool KnowledgeHasExplicitScope(Dictionary<string, object> row, Dictionary<string, object> payload)
        {
            return !string.IsNullOrWhiteSpace(KnowledgeScopeText(row, payload))
                || KnowledgeScopedIds(row, payload).Count > 0;
        }

        private static string KnowledgeScopeText(Dictionary<string, object> row, Dictionary<string, object> payload)
        {
            return FirstNonEmpty(
                ReadString(row, "scope", ""),
                ReadFirstString(payload, "knowledgeScope", "knowledge_scope", "visibilityScope", "visibility_scope", "awarenessScope", "awareness_scope", "scope"));
        }

        private static List<string> KnowledgeScopedIds(Dictionary<string, object> row, Dictionary<string, object> payload)
        {
            return KnowledgeValuesFromDictionary(payload,
                "scopeIds", "scope_ids", "audienceIds", "audience_ids",
                "scopeKingdomIds", "scope_kingdom_ids", "scopeClanIds", "scope_clan_ids",
                "scopeSettlementIds", "scope_settlement_ids", "scopePartyIds", "scope_party_ids",
                "scopeArmyIds", "scope_army_ids");
        }

        private static bool KnowledgePayloadListContains(Dictionary<string, object> row, string normalizedNeedle, params string[] keys)
        {
            if (string.IsNullOrWhiteSpace(normalizedNeedle))
            {
                return false;
            }

            return KnowledgeValuesFromDictionary(KnowledgePayload(row), keys).Any(value => KnowledgeIdEquals(value, normalizedNeedle));
        }

        private static Dictionary<string, object> KnowledgePayload(Dictionary<string, object> row)
        {
            return TryParseJsonObject(ReadString(row, "payload_json", "")) ?? new Dictionary<string, object>();
        }

        private static bool UnknownIdentityMemoryEvidenceAllowed(Dictionary<string, object> row,
            KnowledgeAccessContext knowledge, string evidenceText = "")
        {
            if (row == null || knowledge == null || !knowledge.PlayerIdentityUnknown)
            {
                return true;
            }

            string text = FirstNonEmpty(evidenceText,
                ReadFirstString(row, "summary", "claim", "text", "description", "belief"));
            bool referencesPlayer = UnknownIdentityRowReferencesPlayer(row, knowledge);
            bool namesCanonicalIdentity = UnknownIdentityContainsCanonicalIdentity(text, knowledge);
            bool exposesPrivateStatus = referencesPlayer && UnknownIdentityContainsPrivateStatus(text);

            // A stranger's harmless preferences, promises, and directly witnessed conduct
            // may remain useful before formal identification. Canonical identity and native
            // clan/wealth/political state may not cross that boundary simply because a
            // world snapshot or an earlier faulty reconstruction stored them in memory.
            return !namesCanonicalIdentity && !exposesPrivateStatus;
        }

        private static bool UnknownIdentityRowReferencesPlayer(Dictionary<string, object> row,
            KnowledgeAccessContext knowledge)
        {
            if (row == null || knowledge == null)
            {
                return false;
            }

            List<string> protectedIds = new[]
                {
                    knowledge.PlayerId, knowledge.PlayerClanId, knowledge.PlayerKingdomId,
                    "main_hero", "player_hero", "player_faction", "player_clan", "player_kingdom"
                }
                .Where(value => !string.IsNullOrWhiteSpace(value))
                .Select(NormalizeKnowledgeId)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            string[] scalarKeys =
            {
                "subject_id", "object_id", "owner_id", "target_id", "believer_id",
                "owed_by", "owed_to", "player_id", "hero_id", "character_id"
            };
            foreach (string key in scalarKeys)
            {
                string value = NormalizeKnowledgeId(ReadString(row, key, ""));
                if (protectedIds.Contains(value, StringComparer.OrdinalIgnoreCase))
                {
                    return true;
                }
            }

            string[] listKeys =
            {
                "about_entities_json", "participants_json", "known_by_json", "witnesses_json"
            };
            foreach (string key in listKeys)
            {
                if (protectedIds.Any(id => KnowledgeListContains(row, key, id)))
                {
                    return true;
                }
            }

            Dictionary<string, object> payload = KnowledgePayload(row);
            string[] payloadKeys =
            {
                "playerId", "mainHeroStringId", "playerHeroStringId", "subjectId", "objectId",
                "targetId", "aboutEntities", "aboutEntityIds", "participants", "participantIds",
                "playerClanId", "playerClanStringId", "playerKingdomId", "playerKingdomStringId"
            };
            return protectedIds.Any(id => KnowledgeValuesFromDictionary(payload, payloadKeys)
                .Contains(id, StringComparer.OrdinalIgnoreCase));
        }

        private static bool UnknownIdentityContainsCanonicalIdentity(string text, KnowledgeAccessContext knowledge)
        {
            string value = text ?? "";
            if (knowledge == null || string.IsNullOrWhiteSpace(value))
            {
                return false;
            }

            return new[]
                {
                    knowledge.PlayerName, knowledge.PlayerClanName, knowledge.PlayerKingdomName,
                    knowledge.PlayerId, knowledge.PlayerClanId, knowledge.PlayerKingdomId
                }
                .Where(item => !string.IsNullOrWhiteSpace(item) && item.Length >= 3)
                .Any(item => value.IndexOf(item, StringComparison.OrdinalIgnoreCase) >= 0);
        }

        private static bool UnknownIdentityContainsPrivateStatus(string text)
        {
            string normalized = NormalizeLookup(text ?? "");
            if (string.IsNullOrWhiteSpace(normalized))
            {
                return false;
            }

            return Regex.IsMatch(normalized,
                @"\b(clan(?:\s+tier|\s+leader|\s+standing|\s+renown|\s+influence|\s+wealth|\s+is\s+independent)?|"
                + @"fiefs?|landless|no\s+lands?|gold|denars?|wealth|destitute|rich|poor|renown|influence|"
                + @"kingdom(?:\s+leader|\s+standing)?|ruler|vassal|mercenary|noble\s+rank|title|rank|"
                + @"workshops?|caravans?|party\s+inventory|inventory\s+value|troop\s+count|party\s+size|"
                + @"owns?\s+(?:a\s+)?(?:town|castle|village|settlement))\b",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        }

        private static Dictionary<string, object> SanitizeUnknownIdentityMemoryRow(
            Dictionary<string, object> row, KnowledgeAccessContext knowledge)
        {
            if (row == null || knowledge == null || !knowledge.PlayerIdentityUnknown)
            {
                return row;
            }

            Dictionary<string, object> copy =
                new Dictionary<string, object>(row, StringComparer.OrdinalIgnoreCase);
            foreach (string key in new[] { "summary", "claim", "text", "description", "belief", "payload_json" })
            {
                if (copy.TryGetValue(key, out object raw) && raw != null)
                {
                    copy[key] = SanitizeUnknownIdentityEvidenceText(Convert.ToString(raw, CultureInfo.InvariantCulture), knowledge);
                }
            }
            foreach (string key in new[] { "participants_json", "about_entities_json" })
            {
                if (copy.TryGetValue(key, out object raw) && raw != null)
                {
                    copy[key] = SanitizeUnknownIdentityEvidenceText(Convert.ToString(raw, CultureInfo.InvariantCulture), knowledge);
                }
            }
            if (NormalizeKnowledgeId(ReadString(copy, "target_id", "")).Equals(
                NormalizeKnowledgeId(knowledge.PlayerId), StringComparison.OrdinalIgnoreCase))
            {
                copy["target_id"] = "current unidentified interlocutor";
            }
            List<Dictionary<string, object>> incidents = ReadDictionaryList(copy, "incidents");
            if (incidents.Count > 0)
            {
                copy["incidents"] = incidents
                    .Where(item => UnknownIdentityMemoryEvidenceAllowed(item, knowledge,
                        ReadString(item, "summary", "")))
                    .Select(item => SanitizeUnknownIdentityMemoryRow(item, knowledge))
                    .ToList();
            }
            return copy;
        }

        private static string SanitizeUnknownIdentityEvidenceText(string text, KnowledgeAccessContext knowledge)
        {
            string result = text ?? "";
            if (knowledge == null || !knowledge.PlayerIdentityUnknown || string.IsNullOrWhiteSpace(result))
            {
                return result;
            }

            foreach (string value in new[]
                {
                    knowledge.PlayerName, knowledge.PlayerId, "main_hero", "player_hero",
                    knowledge.PlayerClanName, knowledge.PlayerClanId, "player_faction", "player_clan",
                    knowledge.PlayerKingdomName, knowledge.PlayerKingdomId, "player_kingdom"
                }.Where(value => !string.IsNullOrWhiteSpace(value))
                 .Distinct(StringComparer.OrdinalIgnoreCase)
                 .OrderByDescending(value => value.Length))
            {
                string replacement = value.Equals(knowledge.PlayerClanName, StringComparison.OrdinalIgnoreCase)
                    || value.Equals(knowledge.PlayerClanId, StringComparison.OrdinalIgnoreCase)
                    || value.Equals("player_faction", StringComparison.OrdinalIgnoreCase)
                    || value.Equals("player_clan", StringComparison.OrdinalIgnoreCase)
                        ? "unidentified_clan"
                        : value.Equals(knowledge.PlayerKingdomName, StringComparison.OrdinalIgnoreCase)
                          || value.Equals(knowledge.PlayerKingdomId, StringComparison.OrdinalIgnoreCase)
                          || value.Equals("player_kingdom", StringComparison.OrdinalIgnoreCase)
                            ? "unidentified_realm"
                            : "unidentified_interlocutor";
                result = Regex.Replace(result, Regex.Escape(value), replacement,
                    RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
            }
            result = Regex.Replace(result, @"\bthe\s+armed\s+stranger\b",
                "the player (not yet identified by this NPC)",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
            result = Regex.Replace(result, @"\barmed\s+stranger\b",
                "the player (not yet identified by this NPC)",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
            return result;
        }

        private static List<string> KnowledgeValuesFromDictionary(Dictionary<string, object> source, params string[] keys)
        {
            List<string> values = new List<string>();
            if (source == null || keys == null)
            {
                return values;
            }

            foreach (string key in keys)
            {
                if (source.TryGetValue(key, out object raw) && raw != null)
                {
                    values.AddRange(ExtractEntityIds(raw));
                }
            }

            return values.Where(x => !string.IsNullOrWhiteSpace(x)).Select(NormalizeKnowledgeId).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
        }

        private static bool KnowledgeContainsAny(HashSet<string> haystack, IEnumerable<string> needles)
        {
            if (haystack == null || needles == null)
            {
                return false;
            }

            foreach (string needle in needles)
            {
                string normalized = NormalizeKnowledgeId(needle);
                if (!string.IsNullOrWhiteSpace(normalized) && haystack.Contains(normalized))
                {
                    return true;
                }
            }

            return false;
        }

        private static void AddKnowledgeContextIds(HashSet<string> target, IEnumerable<string> values)
        {
            foreach (string value in values ?? Enumerable.Empty<string>())
            {
                AddKnowledgeContextId(target, value);
            }
        }

        private static void AddKnowledgeContextId(HashSet<string> target, string value)
        {
            string normalized = NormalizeKnowledgeId(value);
            if (target != null && !string.IsNullOrWhiteSpace(normalized))
            {
                target.Add(normalized);
            }
        }

        private static string NormalizeKnowledgeScopeKey(string value)
        {
            return Regex.Replace((value ?? "").Trim().ToLowerInvariant(), @"[^a-z0-9]+", "_").Trim('_');
        }

        private static bool KnowledgeListContains(Dictionary<string, object> row, string key, string normalizedNeedle)
        {
            if (string.IsNullOrWhiteSpace(normalizedNeedle))
            {
                return false;
            }

            foreach (string value in TextListFromJson(ReadString(row, key, "[]")))
            {
                if (KnowledgeIdEquals(value, normalizedNeedle))
                {
                    return true;
                }
            }

            return false;
        }

        private static bool KnowledgeIdEquals(string value, string normalizedNeedle)
        {
            return !string.IsNullOrWhiteSpace(normalizedNeedle)
                && string.Equals(NormalizeKnowledgeId(value), normalizedNeedle, StringComparison.OrdinalIgnoreCase);
        }

        private static string NormalizeKnowledgeId(string value)
        {
            return (value ?? "").Trim();
        }

        private static HashSet<string> SearchMemoryFts(ReignDbConnection connection, List<string> terms, int limit, KnowledgeAccessContext knowledge = null) =>
            SearchEligibleMemoryFts(connection, "memories", "memory_id", "memory_fts", terms, limit, knowledge);

        private static HashSet<string> SearchSummaryFts(ReignDbConnection connection, List<string> terms, int limit, KnowledgeAccessContext knowledge = null) =>
            SearchEligibleMemoryFts(connection, "summaries", "summary_id", "summary_fts", terms, limit, knowledge);

        private static HashSet<string> SearchEligibleMemoryFts(ReignDbConnection connection, string table, string key, string ftsTable,
            List<string> terms, int limit, KnowledgeAccessContext knowledge)
        {
            var result = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            string query = BuildFtsQuery(terms);
            if (string.IsNullOrWhiteSpace(query)) return result;
            int offset = 0;
            do
            {
                var rows = QuerySql(connection, "SELECT m.*,ts_rank(to_tsvector('simple',COALESCE(f.text,'') || ' ' || COALESCE(f.tags,'') || ' ' || COALESCE(f.entities,'')),websearch_to_tsquery('simple',$query)) AS lexical_rank"
                    + " FROM " + ftsTable + " f JOIN " + table + " m ON m." + key + "=f." + key
                    + " WHERE m.status='active' AND to_tsvector('simple',COALESCE(f.text,'') || ' ' || COALESCE(f.tags,'') || ' ' || COALESCE(f.entities,'')) @@ websearch_to_tsquery('simple',$query)"
                    + (knowledge == null ? "" : " AND " + MemoryEligibilitySql(table, "m"))
                    + " ORDER BY lexical_rank DESC,m." + key + " LIMIT 128 OFFSET $offset;",
                    new Dictionary<string, object> { ["query"] = query, ["observer"] = knowledge?.NpcId ?? "", ["offset"] = offset });
                foreach (var row in rows)
                {
                    if (knowledge != null && !KnowledgeRowVisibleToNpc(table, row, knowledge)) continue;
                    result.Add(ReadString(row, key, ""));
                    if (result.Count >= Math.Max(1, limit)) return result;
                }
                if (rows.Count < 128) return result;
                offset += 128;
            } while (true);
        }

        private static double MemoryPacketScore(Dictionary<string, object> row, List<string> queryTerms, HashSet<string> ftsMemoryIds, string npcId, string playerId, string locationId)
        {
            double score = ReadDouble(row, "importance", 0.5d) * 20d + ReadDouble(row, "emotional_weight", 0d) * 8d;
            string memoryId = ReadString(row, "memory_id", "");
            if (!string.IsNullOrWhiteSpace(memoryId) && ftsMemoryIds.Contains(memoryId))
            {
                score += 20d;
            }

            string text = ReadString(row, "summary", "").ToLowerInvariant();
            foreach (string term in queryTerms ?? new List<string>())
            {
                if (!string.IsNullOrWhiteSpace(term) && text.Contains(term.ToLowerInvariant()))
                {
                    score += 4d;
                }
            }

            string blob = (ReadString(row, "participants_json", "") + " " + ReadString(row, "about_entities_json", "") + " " + ReadString(row, "known_by_json", "")).ToLowerInvariant();
            if (!string.IsNullOrWhiteSpace(playerId) && blob.Contains(playerId.ToLowerInvariant()))
            {
                score += 12d;
            }

            if (!string.IsNullOrWhiteSpace(npcId) && blob.Contains(npcId.ToLowerInvariant()))
            {
                score += 8d;
            }

            if (!string.IsNullOrWhiteSpace(locationId) && string.Equals(ReadString(row, "location_id", ""), locationId, StringComparison.OrdinalIgnoreCase))
            {
                score += 8d;
            }

            long ageSeconds = Math.Max(0, DateTimeOffset.UtcNow.ToUnixTimeSeconds() - ReadLong(row, "ts", 0));
            score += Math.Max(0d, 8d - ageSeconds / 86400d);
            return score;
        }

        private static double SummaryPacketScore(Dictionary<string, object> row, List<string> queryTerms, HashSet<string> ftsSummaryIds, string npcId, string playerId, string locationId)
        {
            double score = ReadDouble(row, "importance", 0.5d) * 22d;
            string summaryId = ReadString(row, "summary_id", "");
            if (!string.IsNullOrWhiteSpace(summaryId) && ftsSummaryIds.Contains(summaryId))
            {
                score += 24d;
            }

            string text = ReadString(row, "summary", "").ToLowerInvariant();
            foreach (string term in queryTerms ?? new List<string>())
            {
                if (!string.IsNullOrWhiteSpace(term) && text.Contains(term.ToLowerInvariant()))
                {
                    score += 5d;
                }
            }

            string blob = (ReadString(row, "participants_json", "") + " " + ReadString(row, "about_entities_json", "")).ToLowerInvariant();
            if (!string.IsNullOrWhiteSpace(playerId) && blob.Contains(playerId.ToLowerInvariant()))
            {
                score += 12d;
            }

            if (!string.IsNullOrWhiteSpace(npcId) && (blob.Contains(npcId.ToLowerInvariant()) || string.Equals(ReadString(row, "owner_id", ""), npcId, StringComparison.OrdinalIgnoreCase)))
            {
                score += 10d;
            }

            if (!string.IsNullOrWhiteSpace(locationId) && string.Equals(ReadString(row, "location_id", ""), locationId, StringComparison.OrdinalIgnoreCase))
            {
                score += 8d;
            }

            long ageSeconds = Math.Max(0, DateTimeOffset.UtcNow.ToUnixTimeSeconds() - ReadLong(row, "updated_ts", 0));
            score += Math.Max(0d, 6d - ageSeconds / 172800d);
            return score;
        }

        private static bool MemoryRowRelevant(Dictionary<string, object> row, List<string> queryTerms, HashSet<string> ftsMemoryIds)
        {
            if (queryTerms == null || queryTerms.Count == 0)
            {
                return true;
            }

            string memoryId = ReadString(row, "memory_id", "");
            if (!string.IsNullOrWhiteSpace(memoryId) && ftsMemoryIds.Contains(memoryId))
            {
                return true;
            }

            string blob = MemorySearchBlob(row);
            return queryTerms.Any(term => !string.IsNullOrWhiteSpace(term) && blob.Contains(term.ToLowerInvariant()))
                || ReadDouble(row, "importance", 0d) >= 0.9d;
        }

        private static bool SummaryRowRelevant(Dictionary<string, object> row, List<string> queryTerms, HashSet<string> ftsSummaryIds)
        {
            if (queryTerms == null || queryTerms.Count == 0)
            {
                return true;
            }

            string summaryId = ReadString(row, "summary_id", "");
            if (!string.IsNullOrWhiteSpace(summaryId) && ftsSummaryIds.Contains(summaryId))
            {
                return true;
            }

            string blob = MemorySearchBlob(row);
            return queryTerms.Any(term => !string.IsNullOrWhiteSpace(term) && blob.Contains(term.ToLowerInvariant()))
                || ReadDouble(row, "importance", 0d) >= 0.9d;
        }

        private static List<Dictionary<string, object>> FilterStructuredMemoryRows(List<Dictionary<string, object>> rows, List<string> queryTerms, int limit)
        {
            rows = rows ?? new List<Dictionary<string, object>>();
            if (queryTerms == null || queryTerms.Count == 0)
            {
                return rows.Take(Math.Max(1, limit)).ToList();
            }

            return rows
                .Select(row =>
                {
                    string blob = MemorySearchBlob(row);
                    int matches = queryTerms.Count(term => !string.IsNullOrWhiteSpace(term) && blob.Contains(term.ToLowerInvariant()));
                    row["relevanceScore"] = matches * 10d + ReadDouble(row, "confidence", 0.5d) * 2d
                        + Math.Max(0d, ReadDouble(row, "vectorSemanticScore", 0d)) * 30d;
                    return row;
                })
                .Where(row => ReadDouble(row, "relevanceScore", 0d) >= 10d || ReadDouble(row, "confidence", 0d) >= 0.9d
                    || ReadDouble(row, "vectorSemanticScore", 0d) > 0d)
                .OrderByDescending(row => ReadDouble(row, "relevanceScore", 0d))
                .ThenByDescending(row => ReadLong(row, "ts", 0))
                .Take(Math.Max(1, limit))
                .ToList();
        }

        private static string MemorySearchBlob(Dictionary<string, object> row)
        {
            return (ReadFirstString(row, "summary", "claim", "text", "description")
                + " " + ReadString(row, "tags_json", "")
                + " " + ReadString(row, "about_entities_json", "")
                + " " + ReadString(row, "participants_json", "")
                + " " + ReadString(row, "payload_json", "")).ToLowerInvariant();
        }

        private static bool IsLegacyPlayerNpcRoleCollision(Dictionary<string, object> row, string npcName, string playerName)
        {
            return IsLegacyPlayerNpcRoleCollision(row, new[] { npcName }, playerName);
        }

        private static bool IsLegacyPlayerNpcRoleCollision(Dictionary<string, object> row, IEnumerable<string> npcNames, string playerName)
        {
            string text = ReadFirstString(row ?? new Dictionary<string, object>(), "summary", "claim", "text", "description");
            if (string.IsNullOrWhiteSpace(text)) return false;
            List<string> fullNames = (npcNames ?? new string[0])
                .Select(name => (name ?? string.Empty).Trim())
                .Where(name => !string.IsNullOrWhiteSpace(name)
                    && !NormalizeIdentityName(name).Equals(NormalizeIdentityName(playerName), StringComparison.OrdinalIgnoreCase))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            Dictionary<string, int> firstNameCounts = fullNames.Select(FirstName).Where(name => name.Length >= 3)
                .GroupBy(name => name, StringComparer.OrdinalIgnoreCase)
                .ToDictionary(group => group.Key, group => group.Count(), StringComparer.OrdinalIgnoreCase);
            List<string> protectedNames = fullNames
                .Concat(fullNames.Select(FirstName).Where(name => name.Length >= 3
                    && firstNameCounts.TryGetValue(name, out int count) && count == 1))
                .Where(name => !string.IsNullOrWhiteSpace(name) && name.Length >= 3)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            return protectedNames.Any(name =>
            {
                string n = Regex.Escape(name);
                return Regex.IsMatch(text,
                    @"\b(?:player|stranger)\s+(?:(?:is|was)\s+)?(?:named\s+|whose\s+name\s+(?:is|was)\s+|(?:claiming|claimed|calling|called)\s+(?:(?:himself|herself|themself)\s+)?(?:to\s+be\s+|as\s+)?)" + n + @"\b",
                    RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
            });
        }

        private static string MemoryPacketDedupeKey(Dictionary<string, object> row)
        {
            string eventId = ReadString(row, "event_id", "");
            string summary = NormalizeLookup(ReadString(row, "summary", ""));
            if (!string.IsNullOrWhiteSpace(eventId))
            {
                return eventId + "|" + summary;
            }

            return FirstNonEmpty(ReadString(row, "memory_id", ""), summary, Guid.NewGuid().ToString("N"));
        }

        private static string BuildMemoryPacketText(
            string npcId,
            string playerId,
            List<Dictionary<string, object>> summaries,
            List<Dictionary<string, object>> memories,
            List<Dictionary<string, object>> relationships,
            List<Dictionary<string, object>> obligations,
            List<Dictionary<string, object>> beliefs,
            List<Dictionary<string, object>> comprehension,
            List<string> warnings,
            Dictionary<string, object> retrievalRoute,
            int tokenBudget, bool deferContinuityAllocation = false)
        {
            int charBudget = Math.Max(1200, tokenBudget * 4);
            StringBuilder header = new StringBuilder();
            header.AppendLine("NPC WORLD MEMORY PACKET");
            header.AppendLine("Knowledge rule: this packet is filtered for what this NPC can know, believe, witness, hear as rumor, or reasonably infer. Provenance labels are authoritative; preserve uncertainty and distinguish firsthand knowledge from reports and rumors.");
            header.AppendLine("Historical deictic rule: words inside a recalled source such as 'we', 'us', 'here', 'present', 'everyone', or 'all three' refer only to that source scene and may never be mapped onto the current group. Source-conversation participant metadata proves only who heard or spoke in the recording conversation; it does NOT prove that those people witnessed an older event described inside that conversation. An older event is firsthand for this NPC only when an explicit source-event witness link or this NPC's own attributed first-person line establishes it. Another NPC's 'we/all three' claim cannot grant firsthand knowledge or override this NPC's own denial. If the underlying witnesses are not identified, say they are unknown.");

            List<string> laneOrder = MemoryPacketLaneOrder(retrievalRoute);
            Dictionary<string, StringBuilder> laneBuilders = laneOrder.ToDictionary(lane => lane, lane => new StringBuilder(), StringComparer.OrdinalIgnoreCase);
            foreach (string lane in laneOrder)
            {
                laneBuilders[lane].AppendLine();
                laneBuilders[lane].AppendLine("MEMORY LANE: " + HumanizeKey(lane));
            }

            string interpersonalLane = laneOrder.Contains("interpersonal_history", StringComparer.OrdinalIgnoreCase)
                ? "interpersonal_history" : laneOrder[0];
            string commitmentLane = laneOrder.Contains("commitments_and_plots", StringComparer.OrdinalIgnoreCase)
                ? "commitments_and_plots" : laneOrder[0];
            string beliefLane = laneOrder.Contains("beliefs_and_rumors", StringComparer.OrdinalIgnoreCase)
                ? "beliefs_and_rumors" : laneOrder[0];
            string personalLane = laneOrder.Contains("personal_state", StringComparer.OrdinalIgnoreCase)
                ? "personal_state" : laneOrder[0];

            AppendMemoryPacketRows(laneBuilders[interpersonalLane], "Relationship state", relationships, row =>
            {
                string other = ReadString(row, "target_id", "");
                Dictionary<string, object> lifecycle = ReadDictionary(row, "lifecycle") ?? new Dictionary<string, object>();
                List<string> tags = ReadStringList(lifecycle, "tags");
                List<string> incidents = ReadDictionaryList(row, "incidents")
                    .Select(item => ReadString(item, "summary", "")).Where(value => !string.IsNullOrWhiteSpace(value)).Take(3).ToList();
                return other + ": native standing " + RelationshipDescriptor(ReadInt(row, "nativeRelation", 0))
                    + "; directional affinity " + ReadInt(row, "directionalAffinity", 0).ToString(CultureInfo.InvariantCulture)
                    + "; perception " + ReadString(row, "perceptionTag", "neutral")
                    + (tags.Count == 0 ? "" : "; tags: " + string.Join(", ", tags.ToArray()))
                    + (incidents.Count == 0 ? "" : "; known incidents: " + string.Join("; ", incidents.ToArray()));
            }, 8);

            AppendMemoryPacketRows(laneBuilders[commitmentLane], "Active plots and obligations", obligations,
                row => FormatMemoryPacketFact(row, ReadString(row, "description", ""), npcId, "obligation"), 8);
            AppendMemoryPacketRows(laneBuilders[personalLane], "Character comprehension", comprehension,
                row => FormatMemoryPacketFact(row, ReadString(row, "text", ""), npcId, "comprehension"), 6);
            AppendMemoryPacketRows(laneBuilders[beliefLane], "Beliefs", beliefs,
                row => FormatMemoryPacketFact(row, ReadString(row, "claim", ""), npcId, "belief"), 8);

            foreach (string lane in laneOrder)
            {
                List<Dictionary<string, object>> laneSummaries = summaries
                    .Where(row => EffectiveMemoryPacketLane(row, laneOrder) == lane).ToList();
                List<Dictionary<string, object>> laneMemories = memories
                    .Where(row => EffectiveMemoryPacketLane(row, laneOrder) == lane).ToList();
                AppendMemoryPacketRows(laneBuilders[lane], "Middle-term memory", laneSummaries,
                    row => FormatMemoryPacketFact(row, ReadString(row, "summary", ""), npcId, "summary"), 8);
                AppendMemoryPacketRows(laneBuilders[lane], "Relevant known events", laneMemories,
                    row => FormatMemoryPacketFact(row, ReadString(row, "summary", ""), npcId, "memory"), 16);
            }

            StringBuilder warningBuilder = new StringBuilder();
            if (warnings != null && warnings.Count > 0)
            {
                warningBuilder.AppendLine();
                warningBuilder.AppendLine("Knowledge warnings:");
                foreach (string warning in warnings.Take(5))
                {
                    warningBuilder.AppendLine("- " + warning);
                }
            }

            string warningText = warningBuilder.ToString();
            int laneCharBudget = Math.Max(400, charBudget - header.Length - warningText.Length);
            Dictionary<string, int> allocatedCharacters = AllocateMemoryLaneCharacters(
                laneOrder, laneBuilders.ToDictionary(pair => pair.Key, pair => pair.Value.ToString(), StringComparer.OrdinalIgnoreCase),
                retrievalRoute, laneCharBudget);
            StringBuilder builder = new StringBuilder(header.ToString());
            foreach (string lane in laneOrder)
            {
                string block = laneBuilders[lane].ToString();
                int allocation = allocatedCharacters.ContainsKey(lane) ? allocatedCharacters[lane] : 0;
                if ((deferContinuityAllocation || allocation > 0) && !string.IsNullOrWhiteSpace(block))
                {
                    builder.Append(deferContinuityAllocation ? block : LimitMemoryPacketBlock(block, allocation));
                }
            }
            builder.Append(warningText);
            // Final prompt allocation selects complete evidence records. Cutting
            // this string here used to remove the source of retained conclusions.
            return builder.ToString().TrimEnd();
        }

        private static List<string> MemoryPacketLaneOrder(Dictionary<string, object> retrievalRoute)
        {
            List<string> lanes = ReadStringList(retrievalRoute, "selectedLanes")
                .Select(lane => string.Equals(lane, "exact_history", StringComparison.OrdinalIgnoreCase) ? "interpersonal_history" : NormalizeMemoryCategory(lane))
                .Where(lane => !string.IsNullOrWhiteSpace(lane))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            if (lanes.Count == 0)
            {
                lanes.Add("personal_state");
            }
            return lanes;
        }

        private static string EffectiveMemoryPacketLane(Dictionary<string, object> row, List<string> laneOrder)
        {
            string lane = NormalizeMemoryCategory(ReadFirstString(row, "memory_lane", "memory_domain"));
            if (string.IsNullOrWhiteSpace(lane))
            {
                lane = ClassifyMemoryDomain(row);
            }
            if (laneOrder.Contains(lane, StringComparer.OrdinalIgnoreCase))
            {
                return lane;
            }
            if (string.Equals(lane, "personal_state", StringComparison.OrdinalIgnoreCase)
                && laneOrder.Contains("interpersonal_history", StringComparer.OrdinalIgnoreCase))
            {
                return "interpersonal_history";
            }
            if (string.Equals(lane, "interpersonal_history", StringComparison.OrdinalIgnoreCase)
                && laneOrder.Contains("personal_state", StringComparer.OrdinalIgnoreCase))
            {
                return "personal_state";
            }
            return laneOrder[0];
        }

        private static Dictionary<string, int> AllocateMemoryLaneCharacters(List<string> laneOrder,
            Dictionary<string, string> laneBlocks, Dictionary<string, object> retrievalRoute, int totalCharacters)
        {
            Dictionary<string, double> weights = laneOrder.ToDictionary(lane => lane, lane => 1d, StringComparer.OrdinalIgnoreCase);
            Dictionary<string, object> configured = ReadDictionary(retrievalRoute, "tokenAllocationPercent") ?? new Dictionary<string, object>();
            foreach (KeyValuePair<string, object> pair in configured)
            {
                string lane = string.Equals(pair.Key, "exact_history", StringComparison.OrdinalIgnoreCase)
                    ? "interpersonal_history" : NormalizeMemoryCategory(pair.Key);
                if (!weights.ContainsKey(lane)) continue;
                double value;
                try { value = Convert.ToDouble(pair.Value, CultureInfo.InvariantCulture); }
                catch { value = 0d; }
                weights[lane] += Math.Max(0d, value);
            }

            double totalWeight = Math.Max(1d, weights.Values.Sum());
            Dictionary<string, int> allocations = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            int assigned = 0;
            foreach (string lane in laneOrder)
            {
                int desired = (int)Math.Floor(totalCharacters * weights[lane] / totalWeight);
                int available = laneBlocks.ContainsKey(lane) ? laneBlocks[lane].Length : 0;
                allocations[lane] = Math.Min(available, Math.Max(0, desired));
                assigned += allocations[lane];
            }

            int remaining = Math.Max(0, totalCharacters - assigned);
            foreach (string lane in laneOrder)
            {
                if (remaining <= 0) break;
                int available = laneBlocks.ContainsKey(lane) ? laneBlocks[lane].Length : 0;
                int extra = Math.Min(remaining, Math.Max(0, available - allocations[lane]));
                allocations[lane] += extra;
                remaining -= extra;
            }
            return allocations;
        }

        private static string LimitMemoryPacketBlock(string block, int maximum)
        {
            if (string.IsNullOrEmpty(block) || maximum <= 0) return "";
            if (block.Length <= maximum) return block;
            StringBuilder builder = new StringBuilder();
            foreach (string line in block.Replace("\r\n", "\n").Split('\n'))
            {
                string addition = line + "\n";
                if (builder.Length + addition.Length > maximum) break;
                builder.Append(addition);
            }
            return builder.Length > 0 ? builder.ToString() : LimitText(block, maximum);
        }

        private static string FormatMemoryPacketFact(Dictionary<string, object> row, string text, string npcId, string kind)
        {
            if (string.IsNullOrWhiteSpace(text)) return "";
            row = row ?? new Dictionary<string, object>();
            Dictionary<string, object> payload = TryParseJsonObject(ReadString(row, "payload_json", "")) ?? new Dictionary<string, object>();
            List<string> provenance = new List<string>();
            double worldDay = ReadDouble(row, "world_day", ReadDouble(row, "created_day", ReadDouble(payload, "worldDay", ReadDouble(payload, "world_day", 0d))));
            if (worldDay > 0d)
            {
                provenance.Add("day " + worldDay.ToString("0.##", CultureInfo.InvariantCulture));
            }
            provenance.Add(MemoryAcquisitionLabel(row, npcId, kind));
            if (row.ContainsKey("confidence"))
            {
                provenance.Add("confidence " + ClampDouble(ReadDouble(row, "confidence", 0.5d), 0d, 1d).ToString("0.00", CultureInfo.InvariantCulture));
            }
            if (row.ContainsKey("importance"))
            {
                provenance.Add("importance " + ClampDouble(ReadDouble(row, "importance", 0.5d), 0d, 1d).ToString("0.00", CultureInfo.InvariantCulture));
            }
            string source = ReadFirstString(row, "source");
            if (!string.IsNullOrWhiteSpace(source))
            {
                provenance.Add("source " + source.Replace('_', ' '));
            }
            List<string> sourceParticipants = TextListFromJson(ReadString(row, "participants_json", "[]"));
            if (sourceParticipants.Count == 0)
            {
                sourceParticipants = ReadStringList(payload, "participants")
                    .Concat(ReadStringList(payload, "participantIds"))
                    .Where(value => !string.IsNullOrWhiteSpace(value))
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToList();
            }
            if (sourceParticipants.Count > 0)
            {
                provenance.Add("source-conversation participants (hearing only) " + string.Join(", ", sourceParticipants.Take(8).ToArray()));
            }
            string sourceSessionId = ReadFirstString(row, "session_id", "source_session_id");
            if (!string.IsNullOrWhiteSpace(sourceSessionId))
            {
                provenance.Add("historical session " + sourceSessionId);
            }
            string body = "[" + string.Join("; ", provenance.Where(value => !string.IsNullOrWhiteSpace(value)).ToArray()) + "] " + text.Trim();
            string sourceId = ReadFirstString(row, "memory_id", "summary_id", "belief_id", "comprehension_id", "obligation_id", "event_id");
            return RenderContinuityRecord(FirstNonEmpty(sourceId, PromptHash(body).Substring(0, 20)), kind,
                npcId, sourceSessionId, worldDay, kind == "obligation" ? 70 : kind == "memory" ? 60 : 40, false, body);
        }

        private static string MemoryAcquisitionLabel(Dictionary<string, object> row, string npcId, string kind)
        {
            if (string.Equals(kind, "belief", StringComparison.OrdinalIgnoreCase)) return "private belief";
            if (string.Equals(kind, "obligation", StringComparison.OrdinalIgnoreCase)) return "known commitment";
            if (string.Equals(kind, "comprehension", StringComparison.OrdinalIgnoreCase)) return "private interpretation";
            if (string.Equals(kind, "summary", StringComparison.OrdinalIgnoreCase)) return "consolidated personal memory";
            if (KnowledgeListContains(row, "witnesses_json", npcId)) return "firsthand witness";
            if (KnowledgeListContains(row, "participants_json", npcId)) return "firsthand participant";
            if (KnowledgeListContains(row, "heard_as_rumor_by_json", npcId)) return "secondhand rumor";
            if (KnowledgeIdEquals(ReadString(row, "owner_id", ""), npcId)) return "personal recollection";
            if (KnowledgeListContains(row, "known_by_json", npcId)) return "known report";
            string visibility = ReadString(row, "visibility", "");
            if (visibility.StartsWith("public", StringComparison.OrdinalIgnoreCase)
                || visibility.Equals("world", StringComparison.OrdinalIgnoreCase)
                || visibility.Equals("global", StringComparison.OrdinalIgnoreCase))
            {
                return "public knowledge";
            }
            return "knowledge source unspecified";
        }

        private static void AppendMemoryPacketRows(StringBuilder builder, string title, List<Dictionary<string, object>> rows, Func<Dictionary<string, object>, string> formatter, int limit)
        {
            if (rows == null || rows.Count == 0)
            {
                return;
            }

            builder.AppendLine();
            builder.AppendLine(title + ":");
            foreach (Dictionary<string, object> row in rows.Take(Math.Max(1, limit)))
            {
                string text = formatter(row);
                if (!string.IsNullOrWhiteSpace(text))
                {
                    builder.AppendLine(text.StartsWith("[[continuity ", StringComparison.Ordinal) ? text.Trim() : "- " + text.Trim());
                }
            }
        }

        private static string ScoreText(double value)
        {
            if (value >= 0.66d) return "high";
            if (value >= 0.25d) return "moderate";
            if (value <= -0.66d) return "strongly negative";
            if (value <= -0.25d) return "low";
            return "neutral";
        }

        private static string BuildFtsQuery(List<string> terms)
        {
            List<string> clean = (terms ?? new List<string>())
                .Select(x => Regex.Replace(x ?? "", @"[^\p{L}\p{Nd}_-]+", " ").Trim())
                .Where(x => x.Length >= 3)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(64)
                .Select(x => "\"" + x.Replace("\"", "\"\"") + "\"")
                .ToList();
            return clean.Count == 0 ? "" : string.Join(" OR ", clean.ToArray());
        }

        private static List<string> MemoryQueryTerms(string text)
        {
            var stop = new HashSet<string> { "the", "and", "you", "your", "for", "with", "that", "this", "from", "have", "will", "what", "when", "where", "then", "there", "just", "would", "could", "should", "them", "they", "been", "into", "about" };
            var terms = Regex.Split((text ?? "").ToLowerInvariant(), @"[^\p{L}\p{Nd}_-]+")
                .Where(x => x.Length >= 3)
                .Where(x => !stop.Contains(x))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            // Traverse the whole message and reserve both ends. Named entities and
            // a substantive question at the end must survive a long opening action.
            var names = Regex.Matches(text ?? "", @"\b\p{Lu}[\p{L}'-]{2,}\b").Cast<Match>()
                .Select(m => m.Value.ToLowerInvariant()).Where(x => !stop.Contains(x)).Distinct().ToList();
            var titles = Regex.Matches(text ?? "", @"\b(?:khans?|kings?|queens?|emperors?|empress(?:es)?|sovereigns?|fathers?|mothers?|tournaments?)\b", RegexOptions.IgnoreCase)
                .Cast<Match>().Select(m => m.Value.ToLowerInvariant()).Distinct().ToList();
            var selected = titles.Concat(names.Take(12)).Concat(terms.AsEnumerable().Reverse().Take(20)).Concat(terms.Take(20))
                .Distinct(StringComparer.OrdinalIgnoreCase).Take(48).ToList();
            // Preserve the original term too: a plural or title must not become a
            // hard lane barrier for the same topic's singular form.
            return selected.Concat(selected.Where(t => t.Length > 4 && t.EndsWith("s", StringComparison.Ordinal)
                && !t.EndsWith("ss", StringComparison.Ordinal)).Select(t => t.Substring(0, t.Length - 1)))
                .Distinct(StringComparer.OrdinalIgnoreCase).Take(64).ToList();
        }

        private static string AppendMinimeTopics(string text, List<string> topics)
        {
            List<string> clean = NormalizeMinimeTopics(topics, 8);
            if (clean.Count == 0)
            {
                return text ?? "";
            }

            return (text ?? "") + "\nMinime topic hints: " + string.Join(", ", clean.ToArray());
        }

        private static List<string> TryExtractMinimeTopics(Dictionary<string, object> settings, string text, int maxTopics)
        {
            int safeMaxTopics = Math.Max(1, Math.Min(12, maxTopics <= 0 ? 5 : maxTopics));
            // Topic hints are lexical routing metadata, not a semantic inference task.
            // Keeping this local prevents a worker round trip from serializing the foreground path.
            return MemoryQueryTerms(LimitText(text, 1800)).Take(safeMaxTopics).ToList();
        }

        private static Dictionary<string, object> TryRerankMemoryCandidates(
            Dictionary<string, object> settings,
            string query,
            List<Dictionary<string, object>> summaries,
            List<Dictionary<string, object>> memories,
            List<Dictionary<string, object>> beliefs,
            List<Dictionary<string, object>> comprehension,
            List<Dictionary<string, object>> rumorHistory)
        {
            settings = settings ?? LoadSettings();
            Dictionary<string, object> status = MinimeRerankStatus(settings, "disabled");
            if (!ReadBool(settings, "enableMinimeMemoryWorker", true) || !ReadBool(settings, "enableMinimeMemoryReranking", true))
            {
                return status;
            }

            string cleanQuery = LimitText((query ?? "").Trim(), 1800);
            if (string.IsNullOrWhiteSpace(cleanQuery))
            {
                status["reason"] = "empty_query";
                return status;
            }

            DateTime now = DateTime.UtcNow;
            lock (MinimeAvailabilityLock)
            {
                if (now < MinimeUnavailableUntilUtc)
                {
                    status["reason"] = "helper_cooldown";
                    return status;
                }
            }

            lock (MinimeRerankAvailabilityLock)
            {
                if (now < MinimeRerankUnavailableUntilUtc)
                {
                    status["reason"] = "rerank_cooldown";
                    return status;
                }
            }

            int maxCandidates = Math.Max(4, Math.Min(64, ReadInt(settings, "minimeRerankCandidateCount", 32)));
            List<Dictionary<string, object>> candidatePool = new List<Dictionary<string, object>>();
            Dictionary<string, Dictionary<string, object>> rowsByCandidateId = new Dictionary<string, Dictionary<string, object>>(StringComparer.OrdinalIgnoreCase);
            AddMinimeRerankCandidates(candidatePool, rowsByCandidateId, "summary", summaries);
            AddMinimeRerankCandidates(candidatePool, rowsByCandidateId, "memory", memories);
            AddMinimeRerankCandidates(candidatePool, rowsByCandidateId, "belief", beliefs);
            AddMinimeRerankCandidates(candidatePool, rowsByCandidateId, "comprehension", comprehension);
            AddMinimeRerankCandidates(candidatePool, rowsByCandidateId, "rumor_history", rumorHistory);
            candidatePool = candidatePool
                .OrderByDescending(candidate => ReadDouble(candidate, "deterministicScore", 0d))
                .Take(maxCandidates)
                .ToList();

            status["candidateCount"] = candidatePool.Count;
            if (candidatePool.Count < 2)
            {
                status["reason"] = "insufficient_candidates";
                return status;
            }

            string endpoint = ReadString(settings, "minimeRerankUrl", "http://127.0.0.1:8082/rerank");
            if (string.IsNullOrWhiteSpace(endpoint))
            {
                status["reason"] = "missing_endpoint";
                return status;
            }

            List<Dictionary<string, object>> outboundCandidates = candidatePool
                .Select(candidate => new Dictionary<string, object>
                {
                    ["id"] = ReadString(candidate, "id", ""),
                    ["text"] = ReadString(candidate, "text", "")
                })
                .ToList();
            Dictionary<string, object> requestBody = new Dictionary<string, object>
            {
                ["query"] = cleanQuery,
                ["candidates"] = outboundCandidates,
                ["top_k"] = outboundCandidates.Count
            };

            int timeoutMs = Math.Max(250, Math.Min(60000, ReadInt(settings, "minimeRerankTimeoutMs", 15000)));
            double semanticWeight = ClampDouble(ReadDouble(settings, "minimeRerankWeight", 35d), 0d, 100d);
            Stopwatch timer = Stopwatch.StartNew();
            status["attempted"] = true;
            try
            {
                string raw = PostJsonToUrl(endpoint, Json.Serialize(requestBody), timeoutMs);
                Dictionary<string, object> decoded = TryParseJsonObject(raw);
                List<Dictionary<string, object>> results = ReadDictionaryList(decoded, "results")
                    .Concat(ReadDictionaryList(decoded, "ranked"))
                    .Concat(ReadDictionaryList(decoded, "items"))
                    .GroupBy(item => ReadFirstString(item, "id", "candidate_id", "candidateId"), StringComparer.OrdinalIgnoreCase)
                    .Where(group => !string.IsNullOrWhiteSpace(group.Key))
                    .Select(group => group.First())
                    .ToList();
                Dictionary<string, double> acceptedScores = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
                foreach (Dictionary<string, object> result in results)
                {
                    string candidateId = ReadFirstString(result, "id", "candidate_id", "candidateId");
                    if (string.IsNullOrWhiteSpace(candidateId) || !rowsByCandidateId.ContainsKey(candidateId))
                    {
                        continue;
                    }

                    bool hasScore = result.ContainsKey("score") || result.ContainsKey("similarity");
                    if (!hasScore)
                    {
                        continue;
                    }

                    double semanticScore = ClampDouble(ReadDouble(result, "score", ReadDouble(result, "similarity", 0d)), -1d, 1d);
                    acceptedScores[candidateId] = semanticScore;
                }

                timer.Stop();
                if (acceptedScores.Count != candidatePool.Count)
                {
                    throw new InvalidOperationException("Minime returned " + acceptedScores.Count.ToString(CultureInfo.InvariantCulture)
                        + " recognized scores for " + candidatePool.Count.ToString(CultureInfo.InvariantCulture) + " candidates.");
                }

                foreach (Dictionary<string, object> candidate in candidatePool)
                {
                    string candidateId = ReadString(candidate, "id", "");
                    Dictionary<string, object> row = rowsByCandidateId[candidateId];
                    double semanticScore = acceptedScores[candidateId];
                    double deterministicScore = ReadDouble(row, "packetScore", ReadDouble(row, "relevanceScore", 0d));
                    row["minimeSemanticScore"] = semanticScore;
                    row["finalPacketScore"] = deterministicScore + Math.Max(0d, semanticScore) * semanticWeight;
                }

                lock (MinimeRerankAvailabilityLock)
                {
                    MinimeRerankUnavailableUntilUtc = DateTime.MinValue;
                }

                status["applied"] = true;
                status["reason"] = "semantic_scores_applied";
                status["method"] = "minime_sentence_transformer";
                status["scoredCount"] = acceptedScores.Count;
                status["durationMs"] = timer.ElapsedMilliseconds;
                status["topCandidates"] = acceptedScores
                    .OrderByDescending(pair => pair.Value)
                    .Take(8)
                    .Select(pair => new Dictionary<string, object> { ["id"] = pair.Key, ["score"] = pair.Value })
                    .ToList();
                LogOperational("minime.memory_rerank", new Dictionary<string, object>
                {
                    ["candidateCount"] = candidatePool.Count,
                    ["scoredCount"] = acceptedScores.Count,
                    ["durationMs"] = timer.ElapsedMilliseconds
                });
                return status;
            }
            catch (Exception ex)
            {
                timer.Stop();
                int cooldownSeconds = Math.Max(1, Math.Min(600, ReadInt(settings, "minimeRetryCooldownSeconds", 30)));
                lock (MinimeRerankAvailabilityLock)
                {
                    MinimeRerankUnavailableUntilUtc = DateTime.UtcNow.AddSeconds(cooldownSeconds);
                }

                status["reason"] = "deterministic_fallback";
                status["durationMs"] = timer.ElapsedMilliseconds;
                status["error"] = LimitText(ex.Message, 500);
                LogOperational("minime.memory_rerank_failed", new Dictionary<string, object>
                {
                    ["endpoint"] = endpoint,
                    ["candidateCount"] = candidatePool.Count,
                    ["cooldownSeconds"] = cooldownSeconds,
                    ["error"] = ex.Message
                });
                return status;
            }
        }

        private static Dictionary<string, object> MinimeRerankStatus(Dictionary<string, object> settings, string reason)
        {
            settings = settings ?? new Dictionary<string, object>();
            return new Dictionary<string, object>
            {
                ["enabled"] = ReadBool(settings, "enableMinimeMemoryWorker", true) && ReadBool(settings, "enableMinimeMemoryReranking", true),
                ["attempted"] = false,
                ["applied"] = false,
                ["method"] = "deterministic",
                ["reason"] = reason ?? "",
                ["candidateCount"] = 0,
                ["scoredCount"] = 0,
                ["durationMs"] = 0
            };
        }

        private static void AddMinimeRerankCandidates(
            List<Dictionary<string, object>> candidates,
            Dictionary<string, Dictionary<string, object>> rowsByCandidateId,
            string kind,
            IEnumerable<Dictionary<string, object>> rows)
        {
            int ordinal = 0;
            foreach (Dictionary<string, object> row in rows ?? Enumerable.Empty<Dictionary<string, object>>())
            {
                string text = BuildMinimeRerankText(kind, row);
                if (string.IsNullOrWhiteSpace(text))
                {
                    continue;
                }

                string rowId = ReadFirstString(row, "summary_id", "memory_id", "belief_id", "knowledge_id", "comprehension_id", "turn_id", "event_id");
                string candidateId = (kind ?? "memory") + ":" + FirstNonEmpty(rowId, ordinal.ToString(CultureInfo.InvariantCulture));
                while (rowsByCandidateId.ContainsKey(candidateId))
                {
                    ordinal++;
                    candidateId = (kind ?? "memory") + ":" + FirstNonEmpty(rowId, "row") + ":" + ordinal.ToString(CultureInfo.InvariantCulture);
                }

                double deterministicScore = ReadDouble(row, "packetScore", ReadDouble(row, "relevanceScore", 0d));
                row["packetScore"] = deterministicScore;
                row["finalPacketScore"] = deterministicScore;
                rowsByCandidateId[candidateId] = row;
                candidates.Add(new Dictionary<string, object>
                {
                    ["id"] = candidateId,
                    ["text"] = text,
                    ["deterministicScore"] = deterministicScore
                });
                ordinal++;
            }
        }

        private static string BuildMinimeRerankText(string kind, Dictionary<string, object> row)
        {
            string text = ReadFirstString(row, "summary", "claim", "text", "description");
            if (string.IsNullOrWhiteSpace(text))
            {
                return "";
            }

            string metadata = string.Join(" ", new[]
            {
                ReadString(row, "tags_json", ""),
                ReadString(row, "about_entities_json", ""),
                ReadString(row, "participants_json", ""),
                ReadString(row, "location_id", ""),
                ReadString(row, "stance", "")
            }.Where(value => !string.IsNullOrWhiteSpace(value)).ToArray());
            return LimitText((kind ?? "memory") + ": " + text.Trim() + (string.IsNullOrWhiteSpace(metadata) ? "" : "\nContext: " + metadata), 1600);
        }

        private static IEnumerable<Dictionary<string, object>> OrderRerankedRows(IEnumerable<Dictionary<string, object>> rows, string timestampColumn)
        {
            return (rows ?? Enumerable.Empty<Dictionary<string, object>>())
                .OrderByDescending(row => ReadDouble(row, "finalPacketScore", ReadDouble(row, "packetScore", ReadDouble(row, "relevanceScore", 0d))))
                .ThenByDescending(row => ReadLong(row, timestampColumn, 0));
        }

        private static string BuildMinimeTopicRequestUrl(string endpoint, string text)
        {
            string url = (endpoint ?? "").Trim();
            if (url.EndsWith("/", StringComparison.Ordinal))
            {
                url += "topic";
            }

            string encoded = Uri.EscapeDataString(text ?? "");
            if (url.IndexOf("{text}", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return Regex.Replace(url, "\\{text\\}", encoded, RegexOptions.IgnoreCase);
            }

            return url + (url.Contains("?") ? "&" : "?") + "text=" + encoded;
        }

        private static string GetTextFromUrl(string url, int timeoutMs)
        {
            HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);
            request.Method = "GET";
            request.Accept = "application/json, text/plain, */*";
            request.Timeout = timeoutMs;
            request.ReadWriteTimeout = timeoutMs;
            using (HttpWebResponse response = (HttpWebResponse)request.GetResponse())
            using (Stream responseStream = response.GetResponseStream())
            using (StreamReader reader = new StreamReader(responseStream ?? Stream.Null, Encoding.UTF8))
            {
                return reader.ReadToEnd();
            }
        }

        private static string PostJsonToUrl(string url, string requestJson, int timeoutMs)
        {
            HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);
            request.Method = "POST";
            request.ContentType = "application/json";
            request.Accept = "application/json";
            request.Timeout = timeoutMs;
            request.ReadWriteTimeout = timeoutMs;
            byte[] bytes = Encoding.UTF8.GetBytes(requestJson ?? "{}");
            request.ContentLength = bytes.Length;
            using (Stream requestStream = request.GetRequestStream())
            {
                requestStream.Write(bytes, 0, bytes.Length);
            }

            try
            {
                using (HttpWebResponse response = (HttpWebResponse)request.GetResponse())
                using (Stream responseStream = response.GetResponseStream())
                using (StreamReader reader = new StreamReader(responseStream ?? Stream.Null, Encoding.UTF8))
                {
                    return reader.ReadToEnd();
                }
            }
            catch (WebException ex)
            {
                string body = "";
                if (ex.Response != null)
                {
                    using (Stream responseStream = ex.Response.GetResponseStream())
                    using (StreamReader reader = new StreamReader(responseStream ?? Stream.Null, Encoding.UTF8))
                    {
                        body = reader.ReadToEnd();
                    }
                }

                throw new InvalidOperationException(string.IsNullOrWhiteSpace(body) ? ex.Message : body, ex);
            }
        }

        private static List<string> ParseMinimeTopicResponse(string raw, int maxTopics)
        {
            if (string.IsNullOrWhiteSpace(raw))
            {
                return new List<string>();
            }

            List<string> topics = new List<string>();
            Dictionary<string, object> decoded = TryParseJsonObject(raw);
            if (decoded != null && decoded.Count > 0)
            {
                AddMinimeTopicCandidates(topics, decoded.ContainsKey("generated_tags") ? decoded["generated_tags"] : null);
                AddMinimeTopicCandidates(topics, decoded.ContainsKey("generatedTags") ? decoded["generatedTags"] : null);
                AddMinimeTopicCandidates(topics, decoded.ContainsKey("topics") ? decoded["topics"] : null);
                AddMinimeTopicCandidates(topics, decoded.ContainsKey("tags") ? decoded["tags"] : null);
                AddMinimeTopicCandidates(topics, decoded.ContainsKey("topic") ? decoded["topic"] : null);
            }

            if (topics.Count == 0)
            {
                AddMinimeTopicCandidates(topics, raw);
            }

            return NormalizeMinimeTopics(topics, maxTopics);
        }

        private static void AddMinimeTopicCandidates(List<string> topics, object raw)
        {
            if (raw == null)
            {
                return;
            }

            if (raw is string text)
            {
                foreach (string part in Regex.Split(text, @"[,;\r\n]+"))
                {
                    if (!string.IsNullOrWhiteSpace(part))
                    {
                        topics.Add(part);
                    }
                }

                return;
            }

            foreach (object item in ObjectsFromValue(raw))
            {
                if (item == null)
                {
                    continue;
                }

                if (item is Dictionary<string, object> dict)
                {
                    string value = ReadFirstString(dict, "topic", "tag", "text", "name", "value");
                    if (!string.IsNullOrWhiteSpace(value))
                    {
                        topics.Add(value);
                    }
                }
                else
                {
                    string value = Convert.ToString(item);
                    if (!string.IsNullOrWhiteSpace(value))
                    {
                        topics.Add(value);
                    }
                }
            }
        }

        private static List<string> NormalizeMinimeTopics(IEnumerable<string> topics, int maxTopics)
        {
            List<string> results = new List<string>();
            HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (string topic in topics ?? Enumerable.Empty<string>())
            {
                string clean = Regex.Replace(topic ?? "", @"[^\p{L}\p{Nd}_\-\s]+", " ").Trim();
                clean = Regex.Replace(clean, @"\s+", " ");
                if (clean.Length < 2 || clean.Length > 80)
                {
                    continue;
                }

                string key = NormalizeLookup(clean);
                if (string.IsNullOrWhiteSpace(key) || seen.Contains(key))
                {
                    continue;
                }

                seen.Add(key);
                results.Add(clean);
                if (results.Count >= Math.Max(1, maxTopics))
                {
                    break;
                }
            }

            return results;
        }

        private static List<string> ExtractEntityIds(object raw)
        {
            List<string> ids = new List<string>();
            foreach (object item in ObjectsFromValue(raw))
            {
                if (item is Dictionary<string, object> dict)
                {
                    string id = ReadFirstString(dict, "entity_id", "entityId", "id", "heroStringId", "clanId", "kingdomId", "settlementId", "partyId", "armyId", "warId", "marriageId", "actionId", "courtEventId");
                    if (!string.IsNullOrWhiteSpace(id))
                    {
                        ids.Add(id);
                    }
                }
                else
                {
                    string text = Convert.ToString(item);
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        ids.Add(text.Trim());
                    }
                }
            }

            return ids.Distinct(StringComparer.OrdinalIgnoreCase).ToList();
        }

        private static List<string> ExtractEntityIdsFromJson(string json)
        {
            if (string.IsNullOrWhiteSpace(json))
            {
                return new List<string>();
            }

            try
            {
                object parsed = Json.DeserializeObject(json);
                return ExtractEntityIds(parsed);
            }
            catch
            {
                return new List<string>();
            }
        }

        private static List<string> TextListFromJson(string json)
        {
            if (string.IsNullOrWhiteSpace(json))
            {
                return new List<string>();
            }

            try
            {
                object parsed = Json.DeserializeObject(json);
                return ObjectsFromValue(parsed).Select(Convert.ToString).Where(x => !string.IsNullOrWhiteSpace(x)).ToList();
            }
            catch
            {
                return new List<string>();
            }
        }

        private static List<string> MergeStringLists(IEnumerable<string> left, IEnumerable<string> right)
        {
            return (left ?? new List<string>())
                .Concat(right ?? new List<string>())
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Select(x => x.Trim())
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static bool IsPrivateEventType(string eventType)
        {
            return ContainsAny(eventType ?? "", "private", "conversation", "trade", "bargain", "secret", "promise", "threat", "blackmail", "oath");
        }

        private static double ClampDouble(double value, double min, double max)
        {
            if (double.IsNaN(value) || double.IsInfinity(value))
            {
                return min;
            }

            return Math.Max(min, Math.Min(max, value));
        }

        private static Dictionary<string, object> SelectContextPulls(Dictionary<string, object> payload)
        {
            Stopwatch total = Stopwatch.StartNew();
            payload = payload ?? new Dictionary<string, object>();
            string mode = ReadString(payload, "mode", "dialogue");
            string campaignId = ReadString(payload, "campaignId", "default");
            string correlationId = EnsureCorrelationId(payload);
            string heroId = ReadFirstString(payload, "heroStringId", "heroId", "speakerHeroStringId", "characterId");
            string playerText = ReadFirstString(payload, "playerText", "text", "message", "query");
            string sceneContext = ReadString(payload, "sceneContext", "");
            List<string> available = NormalizeContextPullIds(ReadStringList(payload, "availablePullIds"));
            if (available.Count == 0)
            {
                available = ContextPullIds.ToList();
            }

            Dictionary<string, object> settings = LoadSettings();
            List<string> minimeTopics = TryExtractMinimeTopics(settings, playerText + "\n" + sceneContext, ReadInt(settings, "minimeMaxTopics", 5));
            string selectorText = AppendMinimeTopics(playerText, minimeTopics);
            Dictionary<string, object> selector = new Dictionary<string, object>
            {
                ["ok"] = true, ["method"] = "deterministic_foreground_router", ["modelCallAvoided"] = true
            };
            bool fallbackUsed = false;
            string fallbackReason = "";
            List<Dictionary<string, object>> selected = DeterministicContextPullSelection(mode, selectorText, sceneContext, available);
            selected = PruneContextPullSelection(selectorText, selected);

            total.Stop();
            Dictionary<string, object> response = new Dictionary<string, object>
            {
                ["ok"] = true,
                ["mode"] = mode,
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["heroStringId"] = heroId,
                ["selectedPulls"] = selected,
                ["minimeTopics"] = minimeTopics,
                ["fallbackUsed"] = fallbackUsed,
                ["fallbackReason"] = fallbackUsed ? fallbackReason : "",
                ["selector"] = selector ?? new Dictionary<string, object>(),
                ["timing"] = new Dictionary<string, object>
                {
                    ["totalMs"] = total.ElapsedMilliseconds,
                    ["selectedCount"] = selected.Count,
                    ["availableCount"] = available.Count
                }
            };

            LogOperational("context.select", new Dictionary<string, object>
            {
                ["mode"] = mode,
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["heroStringId"] = heroId,
                ["playerText"] = LimitText(playerText, 180),
                ["minimeTopics"] = minimeTopics,
                ["selectedPulls"] = selected.Select(x => ReadString(x, "id", "")).ToList(),
                ["selectedReasons"] = selected.Select(x => ReadString(x, "reason", "")).Where(x => !string.IsNullOrWhiteSpace(x)).ToList(),
                ["fallbackUsed"] = fallbackUsed,
                ["fallbackReason"] = fallbackUsed ? fallbackReason : "",
                ["timing"] = response["timing"]
            });
            WriteAudit(campaignId, correlationId, "server", mode, "context.select", heroId, "", "", "completed", total.ElapsedMilliseconds, "Selected context pulls for " + mode + ".", new Dictionary<string, object>
            {
                ["playerText"] = playerText,
                ["sceneContext"] = sceneContext,
                ["minimeTopics"] = minimeTopics,
                ["selectedPulls"] = selected,
                ["fallbackUsed"] = fallbackUsed,
                ["fallbackReason"] = fallbackUsed ? fallbackReason : "",
                ["selector"] = selector ?? new Dictionary<string, object>(),
                ["timing"] = response["timing"]
            });
            return response;
        }

        private static Dictionary<string, object> TrySelectContextPullsWithLlm(
            Dictionary<string, object> settings,
            string mode,
            string campaignId,
            string heroId,
            string playerText,
            string sceneContext,
            List<string> available,
            string correlationId)
        {
            string selectorModel = ReadString(settings, "selectorModel", "");
            if (string.IsNullOrWhiteSpace(selectorModel))
            {
                return null;
            }

            if (!LlmProviderConfigured(settings))
            {
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "selector_api_not_configured" };
            }

            List<Dictionary<string, object>> availablePulls = ContextPullCatalog(available);
            string prompt = "Mode: " + mode
                + "\nCampaign: " + campaignId
                + "\nHero id: " + heroId
                + "\nScene context:\n" + (string.IsNullOrWhiteSpace(sceneContext) ? "none" : sceneContext)
                + "\n\nPlayer message:\n" + (playerText ?? "")
                + "\n\nAvailable context pull prompts:\n" + Json.Serialize(availablePulls)
                + "\n\nReturn JSON exactly like {\"selectedPulls\":[{\"id\":\"nearby_settlements\",\"reason\":\"player asked about nearby towns\",\"arguments\":{\"radius\":80,\"maxCount\":8}}]}. Return an empty selectedPulls array for greetings or when no extra pull is needed.";

            Dictionary<string, object> selectorLlmRequest = new Dictionary<string, object>
            {
                ["requestType"] = "context_selector",
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["heroStringId"] = heroId,
                ["model"] = selectorModel,
                ["temperature"] = 0d,
                ["maxTokens"] = 900,
                ["messages"] = new List<Dictionary<string, object>>
                {
                    new Dictionary<string, object> { ["role"] = "system", ["content"] = LoadPromptTemplate("context_selector_system.txt") },
                    new Dictionary<string, object> { ["role"] = "user", ["content"] = prompt }
                },
                ["response_format"] = new Dictionary<string, object> { ["type"] = "json_object" }
            };
            Dictionary<string, object> llm = ChatWithLlm(selectorLlmRequest);
            llm = WithDiagnosticTransformation("Answer structure and format repair", llm, () => RetryMalformedStructuredResponse(llm, selectorLlmRequest, campaignId, correlationId, "context_selector", heroId, ""));

            if (!ReadBool(llm, "ok", false))
            {
                return new Dictionary<string, object>
                {
                    ["ok"] = false,
                    ["error"] = "selector_llm_failed",
                    ["llm"] = llm
                };
            }

            Dictionary<string, object> parsed = TryParseJsonObject(ReadString(llm, "content", "")) ?? new Dictionary<string, object>();
            List<Dictionary<string, object>> selected = NormalizeSelectedContextPulls(ReadDictionaryList(parsed, "selectedPulls"), available);
            if (selected.Count == 0)
            {
                selected = NormalizeSelectedContextPulls(ReadDictionaryList(parsed, "pulls"), available);
            }

            return new Dictionary<string, object>
            {
                ["ok"] = true,
                ["model"] = selectorModel,
                ["selectedPulls"] = selected,
                ["durationMs"] = ReadLong(llm, "durationMs", 0),
                ["requestChars"] = ReadLong(llm, "requestChars", 0),
                ["responseChars"] = ReadLong(llm, "responseChars", 0)
            };
        }

        private static List<Dictionary<string, object>> DeterministicContextPullSelection(string mode, string playerText, string sceneContext, List<string> available)
        {
            string query = (playerText ?? "").ToLowerInvariant();
            bool worldHistoryLookup = IsWorldHistoryLookupRequest(query);
            bool recallFocused = LooksLikeMostRecentConversationRecall(query) || ContainsAny(query,
                "do you remember", "can you remember", "what do you remember", "can you recall", "what can you recall",
                "remind me", "remind us",
                "what did i tell", "earlier i told", "i told this group", "i told you before", "reconstruct our prior",
                "recall the preceding", "recall our earlier", "remember our earlier", "immediately preceding conversation",
                "immediately preceding group", "previous conversation", "prior conversation", "last conversation",
                "raw conversation", "raw transcript", "stored summary conflicts")
                || ContainsAnyTerm(query, "reconstruct", "reconstruction");
            List<Dictionary<string, object>> selected = new List<Dictionary<string, object>>();
            Action<string, string, int, int> add = (id, reason, radius, maxCount) =>
            {
                if (!available.Contains(id) || selected.Any(x => string.Equals(ReadString(x, "id", ""), id, StringComparison.OrdinalIgnoreCase)))
                {
                    return;
                }

                Dictionary<string, object> args = new Dictionary<string, object>();
                if (radius > 0) args["radius"] = radius;
                if (maxCount > 0) args["maxCount"] = maxCount;
                selected.Add(new Dictionary<string, object>
                {
                    ["id"] = id,
                    ["reason"] = reason,
                    ["arguments"] = args
                });
            };

            if (!recallFocused && (ContainsAnyTerm(query, "look", "appearance", "appear", "seem", "wear", "wearing", "clothes", "clothing", "armor", "robe", "dress", "rags", "poor", "rich", "status", "rank", "disguise")
                || ContainsAny(query, "am i a lord", "am i a lady", "am i noble", "do i look noble", "do i seem noble")))
            {
                add("check_player_appearance_status", "player asked or implied how they appear socially", 0, 0);
                add("check_inventory_appearance", "appearance/status reading may depend on the speaker's material eye", 0, 0);
            }

            bool negatesTradeOffer = NegatesMaterialTradeOffer(query);
            bool materialGiftOffer = HasExplicitMaterialGiftOffer(query);
            bool occupationalTradeUsage = IsOccupationalTradeUsage(query);
            bool conversationalTradeUsage = IsConversationalTradeUsage(query);
            bool materialSuppliesQuestion = ContainsAnyTerm(query, "supplies", "supply")
                && ContainsAnyTerm(query, "inventory", "food", "goods", "grain", "caravan", "wares", "travel", "journey", "army", "party", "stock", "stocks", "provisions", "equipment", "horses", "mounts");
            bool materialInventoryRequest = materialSuppliesQuestion
                || ContainsAnyTerm(query, "inventory", "food", "goods", "grain", "caravan", "wares", "sell", "buy", "price", "coin", "money", "wealth", "horses", "mounts")
                || (!negatesTradeOffer && !occupationalTradeUsage && !conversationalTradeUsage && ContainsAnyTerm(query, "trade", "trading"));
            if (!worldHistoryLookup && !recallFocused && materialInventoryRequest)
            {
                add("check_inventory_appearance", "player asked about supplies, goods, wealth, or material presentation", 0, 0);
                add("clan_wealth_and_influence", "material questions may depend on clan credit and influence", 0, 0);
            }

            bool pricedAssetWorthQuestion = ContainsAnyTerm(query, "worth")
                && ContainsAnyTerm(query, "item", "cup", "weapon", "sword", "armor", "horse", "mount", "prisoner", "workshop", "ship", "fleet", "settlement", "town", "castle", "village", "gold", "denar", "goods", "wares");
            bool howMuchMaterialQuestion = ContainsAny(query, "how much")
                && ContainsAnyTerm(query, "item", "cup", "weapon", "sword", "armor", "horse", "mount",
                    "prisoner", "workshop", "ship", "fleet", "settlement", "town", "castle", "village",
                    "gold", "denar", "coin", "goods", "wares", "food", "grain", "price", "value", "worth");
            if (!worldHistoryLookup && (materialGiftOffer || pricedAssetWorthQuestion || howMuchMaterialQuestion
                || (!negatesTradeOffer && (ContainsAnyTerm(query, "sell", "buy", "price", "purchase", "barter", "ransom", "ships", "fleet", "workshop")
                    || ContainsAny(query, "trade for", "in exchange", "denars for", "gold for", "pay you", "pay me", "item value", "trade value", "market value")))))
            {
                add("appraise_trade_offer", "player proposed or asked about a priced asset exchange", 0, 0);
            }

            if (IsNearbySettlementRequest(query))
            {
                add("nearby_settlements", "player asked about nearby settlements or routes", 90, 8);
            }

            if (ContainsAny(query, "bandit", "bandits", "looter", "looters", "raider", "raiders", "outlaw", "outlaws", "hideout", "ambush", "safe road", "danger nearby", "danger on the road"))
            {
                add("nearby_bandit_parties", "player asked about bandits or road danger", 90, 10);
            }

            bool nearbyNamedForceQuestion = ContainsAnyTerm(query, "lord", "lords", "army", "armies", "party", "parties", "force", "forces", "troop", "troops", "patrol", "patrols")
                && ContainsAnyTerm(query, "near", "nearby", "around", "close", "closest", "local", "locally");
            if (nearbyNamedForceQuestion || ContainsAny(query, "lord nearby", "lords nearby", "nearby lord", "nearby lords", "army nearby", "armies nearby", "nearby army", "nearby armies",
                "party nearby", "parties nearby", "nearby party", "nearby parties", "nearby force", "nearby forces", "troops nearby", "nearby troops",
                "named forces", "troop groups", "patrol", "enemy party", "allied party", "who is near"))
            {
                add("nearby_lord_parties", "player asked about nearby lord parties or armies", 120, 10);
            }

            string sceneLocationName = SceneContextLocationName(sceneContext);
            bool namedCurrentSettlementMentioned = !string.IsNullOrWhiteSpace(sceneLocationName)
                && query.IndexOf(sceneLocationName.ToLowerInvariant(), StringComparison.OrdinalIgnoreCase) >= 0;
            bool namedCurrentSettlementQuestion = namedCurrentSettlementMentioned
                && ContainsAnyTerm(query, "concern", "concerns", "condition", "conditions", "situation", "problem", "problems", "issue", "issues", "market", "economy", "prosperity", "security", "loyalty", "garrison", "militia");
            bool generalCurrentSettlementQuestion = namedCurrentSettlementMentioned
                && (ContainsAny(query, "right now", "currently", "current local", "local facts", "facts about", "conditions in", "situation in", "weather in", "weather and")
                    || ContainsAnyTerm(query, "today", "verify", "verified"))
                && ContainsAnyTerm(query, "what", "tell", "know", "fact", "facts", "condition", "conditions", "situation", "weather", "verify", "verified");
            bool namedCurrentSettlementOwnershipClaim = namedCurrentSettlementMentioned
                && (ContainsAnyTerm(query, "own", "owns", "owned", "owner", "ownership", "belong", "belongs", "belonged", "capture", "captured", "conquer", "conquered", "take", "took", "banner", "kingdom", "empire")
                    || ContainsAny(query, "who holds", "who controls", "which realm", "which kingdom"));
            bool localGovernanceOrSiegeQuestion = (namedCurrentSettlementMentioned
                    || ContainsAny(query, "this town", "this city", "this village", "this castle", "this settlement", "current settlement"))
                && (ContainsAnyTerm(query, "governor", "governs", "governance", "siege", "besieged")
                    || ContainsAny(query, "under siege", "siege status"));
            bool localOwnershipFactsRequested = namedCurrentSettlementOwnershipClaim
                || ContainsAny(query, "current settlement ownership", "who owns this", "who holds this", "who controls this");
            bool localFacts = namedCurrentSettlementQuestion || generalCurrentSettlementQuestion || localOwnershipFactsRequested || localGovernanceOrSiegeQuestion
                || ContainsAny(query, "current settlement ownership", "this town", "this city", "this village", "this castle", "this settlement", "current town", "current city", "current village", "current castle", "market", "walls", "garrison", "militia", "prosperity", "security", "loyalty")
                || (ContainsAny(query, "here", "local", "place") && ContainsAny(query, "market", "walls", "garrison", "militia", "prosperity", "security", "loyalty", "town", "city", "village", "castle", "settlement"));
            if (localFacts)
            {
                add("current_settlement_facts", "player asked about the current settlement or local conditions", 0, 0);
            }

            bool explicitDiplomacyQuestion = ContainsAnyTerm(query, "war", "peace", "tribute", "truce", "enemy", "enemies", "ally", "allies", "diplomacy", "surrender", "reparations");
            bool nonLocalKingdomQuestion = ContainsAnyTerm(query, "kingdom", "realm") && !localOwnershipFactsRequested;
            if ((!worldHistoryLookup && (explicitDiplomacyQuestion || nonLocalKingdomQuestion))
                || ContainsAny(query, "settlement demand", "currently at war", "at war now", "current diplomacy", "current war"))
            {
                add("kingdom_diplomacy_status", "player asked about diplomacy, war, peace, or surrender terms", 0, 0);
            }

            bool explicitClanResourcesQuestion = ContainsAnyTerm(query,
                    "influence", "renown", "supporters", "backing", "fief", "fiefs", "wealth", "money", "house")
                || ContainsAny(query, "clan support", "political support", "family power");
            if (explicitClanResourcesQuestion || (ContainsAnyTerm(query, "clan") && !localOwnershipFactsRequested))
            {
                add("clan_wealth_and_influence", "player asked about clan resources, standing, or influence", 0, 0);
            }

            bool personalMemoryRequested = ContainsAny(query,
                "memory", "remember", "last time", "earlier conversation", "earlier conversations", "first scene", "promise", "vow", "favor", "debt", "insult", "betray", "secret", "father", "mother", "husband", "wife", "child", "family",
                "we spoke before", "we met before", "said before", "mentioned before", "told you before", "asked you before", "earlier you", "earlier we")
                || (!worldHistoryLookup && ContainsAny(query, "history", "past"));
            if (recallFocused || personalMemoryRequested)
            {
                add("relevant_memory", "player invoked memory, backstory, promises, secrets, or past events", 0, 0);
            }

            if (worldHistoryLookup || ContainsHistoricalWorldAssertion(query))
            {
                add("verify_world_history", "the message makes a verifiable factual claim, disputes one, or explicitly admits deceptive intent", 0, 0);
            }

            if (ContainsAnyTerm(query, "relationship", "trust", "friend", "friends", "friendship", "enemy", "enemies", "hate", "love", "marry", "married", "marriage", "court", "courting", "jealous", "jealousy", "respect", "opinion", "flirt", "flirting", "kiss", "attract", "attracted", "attraction", "desire", "seduce", "seduction", "affair", "lover", "lovers", "intimate", "intimacy", "beautiful", "handsome"))
            {
                add("relationship_history", "player asked about relationship standing or social history", 0, 0);
            }

            return selected;
        }

        private static string SceneContextLocationName(string sceneContext)
        {
            Match match = Regex.Match(sceneContext ?? "", @"(?im)^\s*(?:(?:current|active)\s+)?(?:location|settlement)\s*:\s*([^\r\n]+)");
            if (!match.Success) return "";
            string value = match.Groups[1].Value.Trim();
            int separator = value.IndexOfAny(new[] { '|', ';', '[', '(', '`' });
            return (separator >= 0 ? value.Substring(0, separator) : value).Trim();
        }

        private static bool IsNearbySettlementRequest(string query)
        {
            string q = (query ?? "").Trim().ToLowerInvariant();
            bool namedPlaceKind = ContainsAnyTerm(q,
                "town", "towns", "village", "villages", "castle", "castles",
                "city", "cities", "settlement", "settlements", "place", "places");
            bool spatialOrRouteIntent = ContainsAnyTerm(q,
                "near", "nearby", "around", "closest", "nearest", "road", "roads",
                "route", "routes", "path", "paths");
            return (namedPlaceKind && spatialOrRouteIntent)
                || ContainsAny(q,
                    "what towns", "which towns", "what villages", "which villages",
                    "where is", "road to", "route to");
        }

        private static bool HasExplicitMaterialGiftOffer(string query)
        {
            string q = (query ?? "").Trim().ToLowerInvariant();
            if (string.IsNullOrWhiteSpace(q)
                || NegatesMaterialGiftOffer(q))
            {
                return false;
            }

            const string asset = @"(?:item|cup|silver|gold|coin|denars?|weapon|sword|armor|horse|mount|ring|necklace|jewel|gem|clothes|robe|food|grain|goods|wares|workshop|house|home|land|estate|property)";
            bool explicitlyNamedGift = Regex.IsMatch(q,
                @"\b(?:as\s+(?:a\s+)?(?:(?:genuine|sincere|free|freely\s+given|personal|valuable)\s+)?gift|personal\s+gift|gift\s+(?:for|to)\s+you|gift\s+you|present\s+(?:for|to)\s+you)\b",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
            bool directRecipientBeforeAsset = Regex.IsMatch(q,
                @"\b(?:i|we)\s+(?:(?:am|are|'m|'re)\s+)?(?:(?:will|would|want\s+to|mean\s+to)\s+)?(?:give|gave|giving|offer|offering|hand|handing)\s+(?:you|him|her|them)\b[^\r\n\.;:!?]{0,60}\b" + asset + @"\b",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
            bool namedRecipientBeforeAsset = Regex.IsMatch(q,
                @"\b(?:i|we)\s+(?:(?:am|are|'m|'re)\s+)?(?:(?:will|would|want\s+to|mean\s+to)\s+)?(?:give|giving|offer|offering|hand|handing)\s+(?!out\b|away\b|over\b|back\b)[\p{L}][\p{L}'-]*(?:\s+[\p{L}][\p{L}'-]*){0,2}\s+(?:this|that|a|an|the|my)\s+" + asset + @"\b",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
            bool assetBeforeRecipient = Regex.IsMatch(q,
                @"\b(?:i|we)\s+(?:(?:am|are|'m|'re)\s+)?(?:(?:will|would|want\s+to|mean\s+to)\s+)?(?:give|giving|offer|offering|hand|handing)\b[^\r\n\.;:!?]{0,60}\b" + asset + @"\b[^\r\n\.;:!?]{0,30}\b(?:to|for)\s+(?:you|him|her|them)\b",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
            return explicitlyNamedGift || directRecipientBeforeAsset || namedRecipientBeforeAsset || assetBeforeRecipient;
        }

        private static bool NegatesMaterialTradeOffer(string query)
        {
            string q = (query ?? "").Trim().ToLowerInvariant();
            return ContainsAny(q, "not a trade", "not trade", "no trade offer", "not for sale", "not an exchange", "no exchange")
                || Regex.IsMatch(q, @"\bnot\s+(?:a\s+)?(?:gift\s+or\s+)?(?:a\s+)?trade(?:\s+offer)?\b",
                    RegexOptions.IgnoreCase | RegexOptions.CultureInvariant)
                || Regex.IsMatch(q, @"\b(?:do\s+not|don't|not\s+to)\s+(?:treat|regard|read|interpret|take)\b[^\r\n\.;:!?]{0,80}\b(?:as\s+)?(?:a\s+)?(?:trade|sale|exchange)\b",
                    RegexOptions.IgnoreCase | RegexOptions.CultureInvariant)
                || Regex.IsMatch(q, @"\bnot\s+(?:currently\s+)?(?:offering|proposing|trading|selling)\b[^\r\n\.;:!?]{0,80}\b(?:trade|sale|exchange)\b",
                    RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        }

        private static bool NegatesMaterialGiftOffer(string query)
        {
            string q = (query ?? "").Trim().ToLowerInvariant();
            return ContainsAny(q, "not a gift", "no gift", "not gifting", "not giving this", "not giving it")
                || Regex.IsMatch(q, @"\b(?:do\s+not|don't|not\s+to)\s+(?:treat|regard|read|interpret|take)\b[^\r\n\.;:!?]{0,80}\b(?:as\s+)?(?:a\s+)?(?:gift|present)\b",
                    RegexOptions.IgnoreCase | RegexOptions.CultureInvariant)
                || Regex.IsMatch(q, @"\bnot\s+(?:currently\s+)?(?:offering|proposing|giving|gifting|presenting)\b[^\r\n\.;:!?]{0,80}\b(?:gift|present)\b",
                    RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        }

        private static bool IsOccupationalTradeUsage(string query)
        {
            string q = (query ?? "").Trim().ToLowerInvariant();
            return Regex.IsMatch(q,
                @"\b(?:my|your|his|her|their|our)\s+(?:own\s+)?trades?\b|\btrades?\s+(?:lead|leads|led|teach|teaches|taught)\b",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        }

        private static bool IsConversationalTradeUsage(string query)
        {
            string q = (query ?? "").Trim().ToLowerInvariant();
            return Regex.IsMatch(q,
                @"\btrad(?:e|ing)\s+(?:(?:one|some|something|a\s+few)\s+)?(?:small\s+and\s+)?(?:personal\s+)?(?:stories|story|details|detail|answers|answer|questions|question|memories|memory|thoughts|thought|information|secrets|secret|experiences|experience|words|word|jokes|joke|insults|insult)\b"
                + @"|\btrad(?:e|ing)\s+something\b[^\r\n\.;:!?]{0,60}\bpersonal\b"
                + @"|\btrad(?:e|ing)\s+(?:places|names|ideas|opinions)\b",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        }

        private static bool ContainsHistoricalWorldAssertion(string query)
        {
            string raw = (query ?? "").Trim();
            string q = raw.ToLowerInvariant().Replace('-', ' ').Replace('_', ' ');
            if (string.IsNullOrWhiteSpace(q)) return false;
            bool namedCurrentLocationAssertion = Regex.IsMatch(raw,
                @"\b(?:I|we)\s+(?:am|are|'m|'re)\s+(?:(?:currently|presently)\s+)?(?:in|at)\s+(?:the\s+)?\p{Lu}[\p{L}'-]{2,}",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
            bool namedForceStrengthAssertion = Regex.IsMatch(raw,
                @"\b\p{Lu}[\p{L}'-]{2,}\s+(?:has|commands|leads|fields)\s+(?:(?:exactly|about|roughly|nearly|only)\s+)?\d+\s+(?:troops|men|soldiers)\b",
                RegexOptions.CultureInvariant);
            if (namedCurrentLocationAssertion || namedForceStrengthAssertion)
            {
                return true;
            }
            if (ContainsExplicitDeceptionAdmission(q) || ContainsAny(q,
                "i know that account is false",
                "i know this account is false", "i know that claim is false", "i know this claim is false",
                "what i just said is false", "what i said is false", "that account is false", "this account is false",
                "prove it", "that is a lie", "you are lying", "he is lying", "she is lying", "he claims", "she claims",
                "they claim", "traveler claims", "traveller claims"))
            {
                return true;
            }

            return Regex.IsMatch(q,
                @"\b(?:i|we)\s+(?:(?:personally|deliberately|actually|supposedly|reportedly)\s+){0,3}(?:was\s+at|was\s+not\s+at|were\s+at|fought|led|commanded|won|defeated|rescued|freed|released|captured|killed|wounded|raided|besieged|conquered|defended|paid|bought|sold|traded|married|met|entered|arrived|never\s+entered|never\s+went\s+to|have\s+never\s+been\s+to|am\s+not\s+presently\s+in|am\s+not\s+currently\s+in)\b",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        }

        private static bool ContainsExplicitDeceptionAdmission(string query)
        {
            string q = (query ?? "").Trim().ToLowerInvariant().Replace('\u2019', '\'');
            if (string.IsNullOrWhiteSpace(q)) return false;
            if (ContainsAny(q,
                "i admit i lied", "i admit that i lied", "i admit i am lying", "i admit i'm lying",
                "we admit we lied", "we admit that we lied", "this is an admitted deception",
                "i deliberately lied", "i knowingly lied", "i intentionally lied",
                "we deliberately lied", "we knowingly lied", "we intentionally lied",
                "i intended to deceive", "we intended to deceive",
                "i meant to deceive", "we meant to deceive"))
            {
                return true;
            }

            // Bare "I am lying" is grammatically ambiguous: in roleplay it very
            // often describes posture (lying here/down/beneath/on a bed) rather
            // than deceptive speech. Require either an unambiguous past-tense
            // admission, an intent modifier, or an explicit communicative object.
            if (Regex.IsMatch(q,
                @"\b(?:i|we)\s+(?:lied|deceived|misled)\s+(?:to\s+)?(?:you|him|her|them|everyone|the\s+(?:court|king|queen|lord|lady))\b|\b(?:i|we)\s+(?:was|were)\s+lying\s+(?:to\s+)?(?:you|him|her|them|everyone)\b",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant))
                return true;
            return Regex.IsMatch(q,
                @"\b(?:i|we)\s+(?:(?:am|are|'m|'re)\s+)?(?:openly|deliberately|knowingly|intentionally)\s+(?:(?:trying|attempting|intending|meant)\s+to\s+)?(?:lie|lied|lying|deceive|deceived|deceiving|mislead|misled|misleading)\b|\b(?:i|we)\s+(?:(?:am|are|'m|'re)\s+)?(?:trying|attempting|intending|meant)\s+to\s+(?:lie|deceive|mislead)\b",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        }

        private static bool IsWorldHistoryLookupRequest(string query)
        {
            string q = (query ?? "").Trim().ToLowerInvariant();
            if (string.IsNullOrWhiteSpace(q)) return false;
            // Player prose and generated tests commonly hyphenate labels such as
            // "canonical-history". Normalize separators before phrase routing so
            // punctuation cannot silently suppress the authoritative history pull.
            q = q.Replace('-', ' ').Replace('_', ' ');
            bool explicitHistory = ContainsAny(q, "world history", "campaign history", "campaign record", "canonical history", "canonical campaign", "historical record", "according to the record", "the record says");
            bool historicalContext = ContainsAny(q,
                    "established history", "verified history", "known history",
                    "recorded history", "historical context", "history about", "history of")
                && ContainsAnyTerm(q,
                    "empire", "kingdom", "realm", "settlement", "town", "city",
                    "village", "castle", "clan", "war", "siege", "campaign");
            bool pastEventQuestion = ContainsAny(q, "what happened to", "who was responsible", "whose party was responsible", "who destroyed", "who defeated", "who captured", "who killed", "who conquered", "who besieged", "who rescued", "who led", "who fought");
            bool reportedClaim = ContainsAny(q, "traveler claims", "traveller claims", "he claims", "she claims", "they claim", "reportedly", "was said to have");
            return explicitHistory || historicalContext || pastEventQuestion || reportedClaim;
        }

        private static List<Dictionary<string, object>> PruneContextPullSelection(string playerText, List<Dictionary<string, object>> selected)
        {
            string query = (playerText ?? "").Trim().ToLowerInvariant();
            if (selected == null || selected.Count == 0)
            {
                return new List<Dictionary<string, object>>();
            }

            if (IsNoPullGreeting(query))
            {
                return new List<Dictionary<string, object>>();
            }

            if (IsPureConversationRecallRequest(query))
            {
                // A reconstruction probe must be answered from the canonical transcript and
                // stored memory evidence. Re-fetching live map or campaign state can silently
                // supply the answer again, masking a broken recall path and changing historical
                // answers when the world has moved on.
                return selected
                    .Where(x => string.Equals(ReadString(x, "id", ""), "relevant_memory", StringComparison.OrdinalIgnoreCase)
                        || string.Equals(ReadString(x, "id", ""), "relationship_history", StringComparison.OrdinalIgnoreCase))
                    .ToList();
            }

            return selected
                .Where(x => ContextPullSupportedByText(ReadString(x, "id", ""), query))
                .ToList();
        }

        private static bool IsNoPullGreeting(string query)
        {
            if (string.IsNullOrWhiteSpace(query))
            {
                return true;
            }

            string compact = query.Trim(' ', '.', '!', '?', ',', ';', ':', '"', '\'');
            if (compact.Length > 80)
            {
                return false;
            }

            // Greeting suppression must match the whole short utterance. Substring
            // matching classified words such as "anything" as the greeting "hi"
            // and could discard legitimate relationship or memory pulls.
            string[] greetings =
            {
                "hello", "hello there", "hi", "hi there", "hail", "greetings",
                "good day", "good morning", "good evening", "how are you",
                "how do you fare", "well met", "peace to you", "just passing through",
                "there is something i'd like to discuss", "i want to speak", "i would speak with you"
            };
            return greetings.Any(greeting => compact.Equals(greeting, StringComparison.OrdinalIgnoreCase));
        }

        private static bool ContextPullSupportedByText(string id, string query)
        {
            bool worldHistoryLookup = IsWorldHistoryLookupRequest(query);
            bool materialGiftOffer = HasExplicitMaterialGiftOffer(query);
            bool negatesTradeOffer = NegatesMaterialTradeOffer(query);
            bool occupationalTradeUsage = IsOccupationalTradeUsage(query);
            bool conversationalTradeUsage = IsConversationalTradeUsage(query);
            switch (id)
            {
                case "check_player_appearance_status":
                    return ContainsAny(query, "look", "appearance", "appear", "seem", "wear", "wearing", "clothes", "clothing", "armor", "robe", "dress", "rags", "poor", "rich", "status", "rank", "disguise",
                        "am i a lord", "am i a lady", "am i noble", "do i look noble", "do i seem noble");
                case "check_inventory_appearance":
                    return !worldHistoryLookup && (ContainsAnyTerm(query, "look", "appearance", "wear", "wearing", "clothes", "clothing", "armor", "inventory", "supplies", "supply", "food", "goods", "grain", "caravan", "wares", "sell", "buy", "price", "coin", "money", "wealth", "horses", "mounts", "poor", "rich")
                        || (!negatesTradeOffer && !occupationalTradeUsage && !conversationalTradeUsage && ContainsAnyTerm(query, "trade", "trading")));
                case "nearby_settlements":
                    return IsNearbySettlementRequest(query);
                case "nearby_bandit_parties":
                    return ContainsAny(query, "bandit", "bandits", "looter", "looters", "raider", "raiders", "outlaw", "outlaws", "hideout", "ambush", "safe road", "danger nearby", "danger on the road");
                case "nearby_lord_parties":
                    return (ContainsAnyTerm(query, "lord", "lords", "army", "armies", "party", "parties", "force", "forces", "troop", "troops", "patrol", "patrols")
                            && ContainsAnyTerm(query, "near", "nearby", "around", "close", "closest", "local", "locally"))
                        || ContainsAny(query, "lord nearby", "lords nearby", "nearby lord", "nearby lords", "army nearby", "armies nearby", "nearby army", "nearby armies",
                        "party nearby", "parties nearby", "nearby party", "nearby parties", "nearby force", "nearby forces", "troops nearby", "nearby troops",
                        "named forces", "troop groups", "patrol", "enemy party", "allied party", "who is near");
                case "current_settlement_facts":
                    return ContainsAny(query, "current settlement ownership", "current native settlement facts", "current settlement facts", "this town", "this city", "this village", "this castle", "this settlement", "current town", "current city", "current village", "current castle", "current governor", "who is governor", "under siege", "siege status", "market", "walls", "garrison", "militia", "prosperity", "security", "loyalty")
                        || ContainsAny(query, "current local", "local facts", "facts about", "conditions in", "situation in", "weather in", "weather and")
                        || ((ContainsAny(query, "right now", "currently") || ContainsAnyTerm(query, "today", "verify", "verified"))
                            && ContainsAnyTerm(query, "what", "tell", "know", "fact", "facts", "condition", "conditions", "situation", "weather", "verify", "verified"))
                        || ContainsAnyTerm(query, "governor", "governs", "governance", "besieged")
                        || (ContainsAnyTerm(query, "capture", "captured", "conquer", "conquered", "own", "owns", "owned", "owner", "ownership", "belong", "belongs", "belonged", "control", "controls", "controlled", "banner")
                            && ContainsAnyTerm(query, "town", "city", "village", "castle", "settlement", "empire", "kingdom", "realm"))
                        || (ContainsAny(query, "here", "local", "place") && ContainsAny(query, "market", "walls", "garrison", "militia", "prosperity", "security", "loyalty", "town", "city", "village", "castle", "settlement"));
                case "kingdom_diplomacy_status":
                    return (!worldHistoryLookup && ContainsAnyTerm(query, "war", "peace", "tribute", "truce", "kingdom", "realm", "enemy", "enemies", "ally", "allies", "diplomacy", "surrender", "reparations", "demands", "demand"))
                        || ContainsAny(query, "settlement demand", "campaign situation", "war situation", "currently at war", "at war now", "current diplomacy", "current war");
                case "clan_wealth_and_influence":
                    return ContainsAnyTerm(query,
                            "clan", "influence", "renown", "supporters", "backing", "fief", "fiefs",
                            "wealth", "money", "house", "rich", "poor")
                        || ContainsAny(query, "clan support", "political support", "family power");
                case "appraise_trade_offer":
                    return !worldHistoryLookup && (materialGiftOffer
                        || ContainsAnyTerm(query, "worth")
                        || (!negatesTradeOffer && (ContainsAnyTerm(query, "sell", "buy", "price", "purchase", "barter", "ransom", "ships", "fleet", "workshop")
                            || ContainsAny(query, "trade for", "in exchange", "denars for", "gold for", "how much", "pay you", "pay me", "item value", "trade value", "market value", "settlement for", "town for", "castle for"))));
                case "verify_world_history":
                    return worldHistoryLookup || ContainsHistoricalWorldAssertion(query);
                case "relevant_memory":
                    return LooksLikeMostRecentConversationRecall(query)
                        || ContainsAny(query, "memory", "remember", "remind me", "remind us", "last time", "earlier conversation", "earlier conversations", "first conversation", "first scene", "before", "again", "repeat", "trail-name", "trail name", "promise", "vow", "favor", "debt", "insult", "betray", "secret", "history", "past", "father", "mother", "husband", "wife", "child", "family");
                case "relationship_history":
                    return ContainsAny(query, "relationship", "trust", "friend", "enemy", "hate", "love", "marry", "marriage", "court", "jealous", "jealousy", "respect", "opinion", "flirt", "kiss", "attract", "desire", "seduc", "affair", "lover", "intimate", "beautiful", "handsome");
                default:
                    return false;
            }
        }

        private static List<Dictionary<string, object>> NormalizeSelectedContextPulls(List<Dictionary<string, object>> raw, List<string> available)
        {
            List<Dictionary<string, object>> selected = new List<Dictionary<string, object>>();
            foreach (Dictionary<string, object> item in raw ?? new List<Dictionary<string, object>>())
            {
                string id = ReadFirstString(item, "id", "pullId", "contextPullId");
                if (string.IsNullOrWhiteSpace(id) || !available.Contains(id) || selected.Any(x => string.Equals(ReadString(x, "id", ""), id, StringComparison.OrdinalIgnoreCase)))
                {
                    continue;
                }

                selected.Add(new Dictionary<string, object>
                {
                    ["id"] = id,
                    ["reason"] = LimitText(ReadString(item, "reason", ""), 240),
                    ["arguments"] = ReadDictionary(item, "arguments") ?? new Dictionary<string, object>()
                });
            }

            return selected;
        }

        private static List<string> NormalizeContextPullIds(List<string> ids)
        {
            HashSet<string> allowed = new HashSet<string>(ContextPullIds, StringComparer.OrdinalIgnoreCase);
            return (ids ?? new List<string>())
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Select(x => x.Trim())
                .Where(x => allowed.Contains(x))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static List<Dictionary<string, object>> ContextPullCatalog(List<string> ids)
        {
            List<Dictionary<string, object>> result = new List<Dictionary<string, object>>();
            foreach (string id in NormalizeContextPullIds(ids))
            {
                string file = ContextPullPromptFileName(id);
                result.Add(new Dictionary<string, object>
                {
                    ["id"] = id,
                    ["label"] = HumanizeKey(id),
                    ["prompt"] = LoadPromptTemplate(file)
                });
            }

            return result;
        }

        private static string ContextPullPromptFileName(string id)
        {
            return "context_pull_" + (id ?? "").Trim().ToLowerInvariant() + ".txt";
        }

        private static Dictionary<string, object> UpsertCharacter(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            Dictionary<string, object> hero = ReadDictionary(payload, "hero")
                ?? ReadDictionary(payload, "profile")
                ?? payload;
            string campaignId = ReadString(payload, "campaignId", ReadString(hero, "campaignId", "default"));
            string heroId = CharacterIdFrom(hero);
            if (string.IsNullOrWhiteSpace(heroId))
            {
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "heroStringId is required." };
            }

            Dictionary<string, object> result = UpsertCharacterProfile(campaignId, hero);
            LogOperational("characters.upsert", new Dictionary<string, object>
            {
                ["campaignId"] = campaignId,
                ["heroStringId"] = heroId,
                ["created"] = ReadBool(result, "created", false)
            });
            return result;
        }

        private static Dictionary<string, object> UpsertCharacterBatch(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", "default");
            List<Dictionary<string, object>> heroes = ReadDictionaryList(payload, "heroes");
            if (heroes.Count == 0)
            {
                heroes = ReadDictionaryList(payload, "characters");
            }

            int created = 0;
            int updated = 0;
            int failed = 0;
            List<Dictionary<string, object>> failures = new List<Dictionary<string, object>>();
            foreach (Dictionary<string, object> hero in heroes)
            {
                try
                {
                    if (hero != null && !hero.ContainsKey("campaignId"))
                    {
                        hero["campaignId"] = campaignId;
                    }

                    Dictionary<string, object> result = UpsertCharacterProfile(campaignId, hero);
                    if (ReadBool(result, "created", false))
                    {
                        created++;
                    }
                    else
                    {
                        updated++;
                    }
                }
                catch (Exception ex)
                {
                    failed++;
                    failures.Add(new Dictionary<string, object>
                    {
                        ["heroStringId"] = CharacterIdFrom(hero),
                        ["error"] = ex.Message
                    });
                }
            }

            Dictionary<string, object> response = new Dictionary<string, object>
            {
                ["ok"] = failed == 0,
                ["campaignId"] = campaignId,
                ["created"] = created,
                ["updated"] = updated,
                ["failed"] = failed,
                ["total"] = heroes.Count,
                ["failures"] = failures
            };
            LogOperational("characters.upsert_batch", response);
            return response;
        }

        private static Dictionary<string, object> IdentitySynchronizeWithPortraitRosterUpgradeApi(Dictionary<string, object> payload)
        {
            Dictionary<string, object> response = IdentitySynchronizeApi(payload);
            string campaignId = ReadString(payload, "campaignId", "default");
            string expectedFingerprint = ReadString(payload, "portraitRosterFingerprint", "");
            Dictionary<string, object> savedRoster = ReadJsonObject(CampaignFile(campaignId, "portrait_roster.json"));
            if (!string.IsNullOrWhiteSpace(expectedFingerprint)
                && ReadInt(savedRoster, "version", 0) < 3)
            {
                response["portraitRosterSyncRequired"] = true;
            }
            return response;
        }

        private static Dictionary<string, object> UpsertPortraitRoster(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", "default");
            string rosterFingerprint = ReadString(payload, "rosterFingerprint", "");
            List<Dictionary<string, object>> characters = ReadDictionaryList(payload, "characters");
            if (characters.Count == 0)
            {
                characters = ReadDictionaryList(payload, "heroes");
            }

            characters = characters
                .Where(character => !string.IsNullOrWhiteSpace(CharacterIdFrom(character)))
                .GroupBy(CharacterIdFrom, StringComparer.OrdinalIgnoreCase)
                .Select(group => group.Last())
                .Select(CompactPortraitRosterEntry)
                .OrderBy(character => ReadString(character, "name", CharacterIdFrom(character)), StringComparer.OrdinalIgnoreCase)
                .ToList();
            string path = CampaignFile(campaignId, "portrait_roster.json");
            Dictionary<string, object> existing = ReadJsonObject(path);
            if (ReadInt(existing, "version", 0) >= 3
                && !string.IsNullOrWhiteSpace(rosterFingerprint)
                && string.Equals(ReadString(existing, "rosterFingerprint", ""), rosterFingerprint, StringComparison.Ordinal))
            {
                Dictionary<string, object> unchangedResponse = new Dictionary<string, object>
                {
                    ["ok"] = true,
                    ["unchanged"] = true,
                    ["campaignId"] = campaignId,
                    ["characterCount"] = characters.Count,
                    ["rosterFingerprint"] = rosterFingerprint,
                    ["path"] = path
                };
                LogOperational("portrait_roster.unchanged", unchangedResponse);
                return unchangedResponse;
            }

            Dictionary<string, object> document = new Dictionary<string, object>
            {
                ["version"] = 3,
                ["campaignId"] = campaignId,
                ["campaignLabel"] = ReadString(payload, "campaignLabel", ""),
                ["updatedUtc"] = DateTime.UtcNow.ToString("o"),
                ["characterCount"] = characters.Count,
                ["rosterFingerprint"] = rosterFingerprint,
                ["characters"] = characters
            };
            WriteJsonObject(path, document);
            Dictionary<string, object> response = new Dictionary<string, object>
            {
                ["ok"] = true,
                ["unchanged"] = false,
                ["campaignId"] = campaignId,
                ["characterCount"] = characters.Count,
                ["rosterFingerprint"] = rosterFingerprint,
                ["path"] = path
            };
            LogOperational("portrait_roster.upsert", response);
            return response;
        }

        private static Dictionary<string, object> CompactPortraitRosterEntry(Dictionary<string, object> character)
        {
            character = character ?? new Dictionary<string, object>();
            return new Dictionary<string, object>
            {
                ["heroStringId"] = CharacterIdFrom(character),
                ["characterObjectId"] = ReadString(character, "characterObjectId", ""),
                ["name"] = ReadString(character, "name", CharacterIdFrom(character)),
                ["cultureId"] = ReadString(character, "cultureId", ""),
                ["occupation"] = ReadString(character, "occupation", ""),
                ["isFemale"] = ReadBool(character, "isFemale", false),
                ["isLord"] = ReadBool(character, "isLord", false),
                ["isNotable"] = ReadBool(character, "isNotable", false),
                ["isWanderer"] = ReadBool(character, "isWanderer", false),
                ["bodyKey"] = ReadString(character, "bodyKey", ""),
                ["civilianEquipment"] = CompactPortraitEquipment(character),
                ["portraitCacheKey"] = ReadString(character, "portraitCacheKey", "")
            };
        }

        private static List<Dictionary<string, object>> CompactPortraitEquipment(Dictionary<string, object> character)
        {
            return ReadDictionaryList(character, "civilianEquipment")
                .Select(item => new Dictionary<string, object>
                {
                    ["slot"] = ReadString(item, "slot", ""),
                    ["itemId"] = ReadString(item, "itemId", "")
                })
                .Where(item => !string.IsNullOrWhiteSpace(ReadString(item, "slot", ""))
                    && !string.IsNullOrWhiteSpace(ReadString(item, "itemId", "")))
                .GroupBy(item => ReadString(item, "slot", ""), StringComparer.OrdinalIgnoreCase)
                .Select(group => group.First())
                .ToList();
        }

        private static Dictionary<string, object> ConstructCharacter(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            Dictionary<string, object> hero = ReadDictionary(payload, "hero")
                ?? ReadDictionary(payload, "profile")
                ?? payload;
            string campaignId = ReadString(payload, "campaignId", ReadString(hero, "campaignId", "default"));
            if (hero != null && !hero.ContainsKey("campaignId"))
            {
                hero["campaignId"] = campaignId;
            }

            if (hero != null && !string.IsNullOrWhiteSpace(CharacterIdFrom(hero)))
            {
                UpsertCharacterProfile(campaignId, hero);
            }

            string heroId = CharacterIdFrom(hero);
            if (string.IsNullOrWhiteSpace(heroId))
            {
                heroId = ReadString(payload, "heroStringId", ReadString(payload, "characterId", ""));
            }

            if (string.IsNullOrWhiteSpace(heroId))
            {
                throw new InvalidOperationException("heroStringId is required.");
            }

            bool force = ReadBool(payload, "force", false);
            bool useLlm = ReadBool(payload, "useLlm", ReadBool(LoadSettings(), "constructCharactersWithLlm", true));
            Dictionary<string, object> result = ConstructCharacterFiles(campaignId, heroId, hero, force, useLlm);
            LogOperational("characters.construct", result);
            return result;
        }

        private static Dictionary<string, object> ConstructCharacterBatch(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", "default");
            List<Dictionary<string, object>> heroes = ReadDictionaryList(payload, "heroes");
            if (heroes.Count == 0)
            {
                heroes = ReadDictionaryList(payload, "characters");
            }

            bool force = ReadBool(payload, "force", false);
            bool useLlm = ReadBool(payload, "useLlm", ReadBool(LoadSettings(), "constructCharactersWithLlm", true));
            int constructed = 0;
            int failed = 0;
            int llmUsed = 0;
            List<Dictionary<string, object>> failures = new List<Dictionary<string, object>>();
            foreach (Dictionary<string, object> hero in heroes)
            {
                WaitForInteractiveRequests();
                try
                {
                    if (hero != null && !hero.ContainsKey("campaignId"))
                    {
                        hero["campaignId"] = campaignId;
                    }

                    UpsertCharacterProfile(campaignId, hero);
                    Dictionary<string, object> result = ConstructCharacterFiles(campaignId, CharacterIdFrom(hero), hero, force, useLlm);
                    if (ReadBool(result, "ok", false))
                    {
                        constructed++;
                        if (ReadBool(result, "llmUsed", false))
                        {
                            llmUsed++;
                        }
                    }
                    else
                    {
                        failed++;
                        failures.Add(new Dictionary<string, object>
                        {
                            ["heroStringId"] = CharacterIdFrom(hero),
                            ["error"] = ReadString(result, "diagnostic", ReadString(result, "error", "Character generation failed.")),
                            ["result"] = result
                        });
                    }
                }
                catch (Exception ex)
                {
                    failed++;
                    failures.Add(new Dictionary<string, object>
                    {
                        ["heroStringId"] = CharacterIdFrom(hero),
                        ["error"] = ex.Message
                    });
                }
            }

            Dictionary<string, object> response = new Dictionary<string, object>
            {
                ["ok"] = failed == 0,
                ["campaignId"] = campaignId,
                ["constructed"] = constructed,
                ["failed"] = failed,
                ["total"] = heroes.Count,
                ["llmUsed"] = llmUsed,
                ["failures"] = failures
            };
            LogOperational("characters.construct_batch", response);
            return response;
        }

        private static Dictionary<string, object> RunInteractiveRequest(Func<Dictionary<string, object>> request)
        {
            Interlocked.Increment(ref InteractiveRequestCount);
            ReignTraceScope trace = BeginReignSpan("interaction.production", new Dictionary<string, object>
            { ["activeRequests"] = Volatile.Read(ref InteractiveRequestCount) });
            try
            {
                return request();
            }
            catch (Exception ex)
            {
                trace.Fail(ex);
                throw;
            }
            finally
            {
                trace.Dispose();
                Interlocked.Exchange(ref LastInteractiveRequestCompletedUtcTicks, DateTime.UtcNow.Ticks);
                Interlocked.Decrement(ref InteractiveRequestCount);
            }
        }

        private static bool InteractiveRequestActiveOrRecent(int quietPeriodMilliseconds = 2000)
        {
            if (Volatile.Read(ref InteractiveRequestCount) > 0)
            {
                return true;
            }

            long completedTicks = Interlocked.Read(ref LastInteractiveRequestCompletedUtcTicks);
            if (completedTicks <= 0)
            {
                return false;
            }

            long elapsedTicks = DateTime.UtcNow.Ticks - completedTicks;
            return elapsedTicks >= 0 && elapsedTicks < TimeSpan.FromMilliseconds(Math.Max(0, quietPeriodMilliseconds)).Ticks;
        }

        private static void WaitForInteractiveRequests()
        {
            bool announced = false;
            while (Volatile.Read(ref InteractiveRequestCount) > 0)
            {
                if (!announced)
                {
                    announced = true;
                    LogOperational("characters.construct_batch_paused", new Dictionary<string, object>
                    {
                        ["reason"] = "interactive_request_active",
                        ["activeInteractiveRequests"] = Volatile.Read(ref InteractiveRequestCount)
                    });
                }

                Thread.Sleep(250);
            }
        }

        private static Dictionary<string, object> RetryFailedCharacters(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", LatestCampaignId());
            string heroId = ReadFirstString(payload, "heroStringId", "heroId", "characterId");
            int retried = 0;
            int recovered = 0;
            int failed = 0;
            List<Dictionary<string, object>> results = new List<Dictionary<string, object>>();

            List<string> characterDirs = new List<string>();
            if (!string.IsNullOrWhiteSpace(heroId))
            {
                characterDirs.Add(CharacterDirectory(campaignId, heroId));
            }
            else
            {
                string charactersDir = Path.Combine(CampaignDirectory(campaignId), "characters");
                if (Directory.Exists(charactersDir))
                {
                    characterDirs.AddRange(Directory.GetDirectories(charactersDir));
                }
            }

            foreach (string dir in characterDirs)
            {
                Dictionary<string, object> constructed = ReadJsonObject(Path.Combine(dir, "constructed.json"));
                if (!string.Equals(ReadString(constructed, "status", ""), "failed", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                string id = Path.GetFileName(dir);
                Dictionary<string, object> profile = ReadJsonObject(Path.Combine(dir, "profile.json"));
                if (!profile.ContainsKey("heroStringId"))
                {
                    profile["heroStringId"] = id;
                }

                retried++;
                Dictionary<string, object> result = ConstructCharacterFiles(campaignId, id, profile, force: true, useLlm: true, source: "retry_failed");
                if (IsCharacterConstructionReady(result))
                {
                    recovered++;
                }
                else
                {
                    failed++;
                }

                results.Add(new Dictionary<string, object>
                {
                    ["heroStringId"] = id,
                    ["ok"] = ReadBool(result, "ok", false),
                    ["status"] = ReadString(result, "status", ""),
                    ["diagnostic"] = ReadString(result, "diagnostic", ReadString(result, "error", ""))
                });
            }

            Dictionary<string, object> response = new Dictionary<string, object>
            {
                ["ok"] = failed == 0,
                ["campaignId"] = campaignId,
                ["retried"] = retried,
                ["recovered"] = recovered,
                ["failed"] = failed,
                ["results"] = results
            };
            LogOperational("characters.retry_failed", response);
            return response;
        }

        private static Dictionary<string, object> EnsureCharacterConstructed(string campaignId, string heroId, Dictionary<string, object> hero, string source)
        {
            hero = MergeProfileForConstruction(campaignId, heroId, hero);
            if (IsEncounteredResidentProfile(hero))
                return EnsureEncounteredResidentConstructed(campaignId, heroId, hero, source);
            if (ReadBool(hero, "isNotable", false))
            {
                using (ReignDbConnection mbtiConnection = OpenCampaignConnection(campaignId))
                {
                    EnsureNotableMbtiProfile(mbtiConnection, campaignId, ReadDouble(hero, "worldDay", 0d), hero, true);
                }
            }
            if (ReadInt(hero, "narrativeVersion", 0) >= 5)
                return EnsureNarrativeCharacterConstructed(campaignId, heroId, hero, source);
            Dictionary<string, object> status = ReadJsonObject(CharacterFile(campaignId, heroId, "constructed.json"));
            string currentStatus = ReadString(status, "status", "");
            Dictionary<string, object> traits = ReadJsonObject(CharacterFile(campaignId, heroId, "traits.json"));
            if (traits.Count > 0 && EnsureTraitPercentageData(traits, heroId))
            {
                WriteJsonObject(CharacterFile(campaignId, heroId, "traits.json"), traits);
            }
            bool traitModelReady = TraitDocumentReady(traits);
            bool requiresFirstContactConstruction = RequiresFirstContactConstruction(campaignId, heroId, status);
            if (traitModelReady && IsCharacterEnrichmentPending(campaignId, heroId))
            {
                status["ok"] = true;
                status["status"] = "fallback_ready";
                status["backgroundEnrichmentPending"] = true;
                return status;
            }
            if (IsUsableCharacterStatus(currentStatus) && traitModelReady && !requiresFirstContactConstruction)
            {
                status["ok"] = true;
                status["alreadyReady"] = true;
                return status;
            }

            if (IsUsableCharacterStatus(currentStatus) && !traitModelReady && !requiresFirstContactConstruction)
            {
                Dictionary<string, object> migrated = ConstructCharacterFiles(campaignId, heroId, hero, force: true, useLlm: true, source: "trait_model_v2_migration");
                if (IsCharacterConstructionReady(migrated))
                {
                    return migrated;
                }

                Dictionary<string, object> migratedTraits = ReadJsonObject(CharacterFile(campaignId, heroId, "traits.json"));
                if (TraitDocumentReady(migratedTraits))
                {
                    status["ok"] = true;
                    status["status"] = "ready";
                    status["schemaVersion"] = CharacterSchemaVersion;
                    status["traitMigrationFallback"] = true;
                    status["traitMigrationError"] = ReadString(migrated, "diagnostic", ReadString(migrated, "error", ""));
                    status["updatedUtc"] = DateTime.UtcNow.ToString("o");
                    WriteJsonObject(CharacterFile(campaignId, heroId, "constructed.json"), status);
                    return status;
                }

                return migrated;
            }

            if (string.Equals(currentStatus, "failed", StringComparison.OrdinalIgnoreCase))
            {
                Dictionary<string, object> settings = LoadSettings();
                if (ShouldRetryFailedConstruction(status, settings))
                {
                    status["autoRetryAfterSettingsChange"] = true;
                    LogOperational("character_construction.retry_after_settings_change", new Dictionary<string, object>
                    {
                        ["campaignId"] = campaignId,
                        ["heroStringId"] = heroId,
                        ["failedRevision"] = ReadString(status, "settingsRevision", ""),
                        ["currentRevision"] = ReadString(settings, "settingsRevision", "")
                    });
                    return ConstructCharacterFiles(campaignId, heroId, hero, force: true, useLlm: true, source: source + "_settings_retry");
                }

                status["ok"] = false;
                status["alreadyFailed"] = true;
                return status;
            }

            LogOperational("character_construction.first_contact_started", new Dictionary<string, object>
            {
                ["campaignId"] = campaignId,
                ["heroStringId"] = heroId,
                ["source"] = source ?? "interactive",
                ["previousStatus"] = currentStatus,
                ["requiresFirstContactConstruction"] = requiresFirstContactConstruction
            });
            Dictionary<string, object> result = ConstructCharacterFiles(campaignId, heroId, hero,
                force: requiresFirstContactConstruction, useLlm: false, source: source + "_first_contact_scaffold");
            if (IsCharacterConstructionReady(result))
            {
                bool needsEnrichment = !LoadCharacterProfileLibrary().ContainsKey(heroId)
                    && !CharacterHasEditorCorrections(campaignId, heroId)
                    && !ReadBool(result, "llmUsed", false);
                if (needsEnrichment)
                {
                    ScheduleCharacterEnrichment(campaignId, heroId, hero, source);
                    result["backgroundEnrichmentPending"] = true;
                }
                LogOperational("character_construction.first_contact_completed", new Dictionary<string, object>
                {
                    ["campaignId"] = campaignId,
                    ["heroStringId"] = heroId,
                    ["source"] = source ?? "interactive",
                    ["llmUsed"] = ReadBool(result, "llmUsed", false),
                    ["durationMs"] = ReadLong(result, "durationMs", 0)
                });
            }
            else
            {
                LogOperational("character_construction.first_contact_failed", new Dictionary<string, object>
                {
                    ["campaignId"] = campaignId,
                    ["heroStringId"] = heroId,
                    ["source"] = source ?? "interactive",
                    ["status"] = ReadString(result, "status", ""),
                    ["diagnostic"] = LimitText(ReadString(result, "diagnostic", ReadString(result, "error", "")), 1000)
                });
            }
            return result;
        }

        private static bool IsCharacterEnrichmentPending(string campaignId, string heroId)
        {
            string key = (campaignId ?? "default") + "|" + (heroId ?? "");
            lock (CharacterEnrichmentLock) return PendingCharacterEnrichments.Contains(key);
        }

        private static int PendingCharacterEnrichmentCount()
        {
            lock (CharacterEnrichmentLock) return PendingCharacterEnrichments.Count;
        }

        private static void ScheduleCharacterEnrichment(string campaignId, string heroId,
            Dictionary<string, object> hero, string interactionSource)
        {
            string key = (campaignId ?? "default") + "|" + (heroId ?? "");
            lock (CharacterEnrichmentLock)
            {
                if (!PendingCharacterEnrichments.Add(key)) return;
            }
            Dictionary<string, object> capturedHero = new Dictionary<string, object>(
                hero ?? new Dictionary<string, object>(), StringComparer.OrdinalIgnoreCase);
            EnqueuePriorityBackgroundWork("character.enrichment", "maintenance", () =>
            {
                try
                {
                    Dictionary<string, object> enriched = ConstructCharacterFiles(campaignId, heroId,
                        capturedHero, force: true, useLlm: true, source: "background_enrichment");
                    if (IsCharacterConstructionReady(enriched) && ReadBool(enriched, "llmUsed", false))
                        MarkCharacterConstructionCompletedOnInteraction(campaignId, heroId,
                            FirstNonEmpty(interactionSource, "background_enrichment"));
                }
                finally
                {
                    lock (CharacterEnrichmentLock) PendingCharacterEnrichments.Remove(key);
                }
            });
        }

        private static Dictionary<string, object> ConstructCharacterFiles(string campaignId, string heroId, Dictionary<string, object> hero, bool force, bool useLlm)
        {
            return ConstructCharacterFiles(campaignId, heroId, hero, force, useLlm, "manual");
        }

        private static Dictionary<string, object> ConstructCharacterFiles(string campaignId, string heroId, Dictionary<string, object> hero, bool force, bool useLlm, string source)
        {
            if (string.IsNullOrWhiteSpace(heroId))
            {
                throw new InvalidOperationException("heroStringId is required.");
            }

            hero = MergeProfileForConstruction(campaignId, heroId, hero);
            if (ReadInt(hero, "narrativeVersion", 0) >= 5)
            {
                if (LoadCharacterProfileLibrary().ContainsKey(heroId))
                    return MaterializeCharacterProfile(campaignId, heroId, hero, force, false);
                if (useLlm) return ConstructNarrativeCharacter(campaignId, heroId, hero, force, source);
            }
            string constructedPath = CharacterFile(campaignId, heroId, "constructed.json");
            Dictionary<string, object> existing = ReadJsonObject(constructedPath);
            string existingStatus = ReadString(existing, "status", "");
            if (!force && IsUsableCharacterStatus(existingStatus)
                && TraitDocumentReady(ReadJsonObject(CharacterFile(campaignId, heroId, "traits.json"))))
            {
                existing["ok"] = true;
                existing["alreadyReady"] = true;
                return existing;
            }

            if (!force && string.Equals(existingStatus, "failed", StringComparison.OrdinalIgnoreCase))
            {
                Dictionary<string, object> settings = LoadSettings();
                if (!ShouldRetryFailedConstruction(existing, settings))
                {
                    existing["ok"] = false;
                    existing["alreadyFailed"] = true;
                    return existing;
                }
            }

            Stopwatch timer = Stopwatch.StartNew();
            Dictionary<string, object> constructionSettings = LoadSettings();
            WriteJsonObject(constructedPath, new Dictionary<string, object>
            {
                ["version"] = 1,
                ["constructionEngineVersion"] = CharacterConstructionEngineVersion,
                ["status"] = "constructing",
                ["source"] = source ?? "unknown",
                ["settingsRevision"] = ReadString(constructionSettings, "settingsRevision", ""),
                ["settingsFingerprint"] = SettingsFingerprint(constructionSettings),
                ["startedUtc"] = DateTime.UtcNow.ToString("o")
            });

            Dictionary<string, object> traits;
            if (ReadBool(hero, "isNotable", false))
            {
                using (ReignDbConnection mbtiConnection = OpenCampaignConnection(campaignId))
                {
                    Dictionary<string, object> mbti = EnsureNotableMbtiProfile(
                        mbtiConnection, campaignId, ReadDouble(hero, "worldDay", 0d), hero, false);
                    traits = ReadJsonObject(CharacterFile(campaignId, heroId, "traits.json"));
                    if (traits.Count == 0)
                    {
                        traits = BuildNotableMbtiTraitDocument(
                            campaignId, heroId, ReadString(hero, "name", heroId), ReadString(mbti, "type", "INTJ"));
                    }
                }
            }
            else
            {
                traits = BuildTraitDocument(hero);
            }
            WriteJsonObject(CharacterFile(campaignId, heroId, "traits.json"), traits);

            Dictionary<string, object> generated = null;
            Dictionary<string, object> llm = null;
            List<Dictionary<string, object>> attempts = new List<Dictionary<string, object>>();
            bool llmUsed = false;
            if (useLlm)
            {
                for (int attempt = 1; attempt <= 2 && generated == null; attempt++)
                {
                    int attemptMaxTokens = CharacterConstructionMaxTokensForAttempt(
                        ReadInt(constructionSettings, "characterConstructionMaxTokens", CharacterConstructionTokenCeiling),
                        attempt);
                    llm = ChatWithLlm(new Dictionary<string, object>
                    {
                        ["requestType"] = "character_construction",
                        ["maxTokens"] = attemptMaxTokens,
                        ["temperature"] = attempt == 1 ? 0.75d : 0.25d,
                        ["messages"] = new List<Dictionary<string, object>>
                        {
                            new Dictionary<string, object>
                            {
                                ["role"] = "system",
                                ["content"] = "You are Bannerlord Reign's character construction engine. Return strict JSON only. Do not wrap it in markdown. Build a grounded Mount & Blade II: Bannerlord character from authoritative game facts. Native character descriptions outrank inferred Reign traits. You may correct non-locked trait assignments only when the native description clearly supports the correction. Do not contradict canon/game facts."
                            },
                            new Dictionary<string, object>
                            {
                                ["role"] = "user",
                                ["content"] = BuildCharacterConstructionPromptForAttempt(campaignId, heroId, hero, traits, attempt)
                            }
                        },
                        ["response_format"] = new Dictionary<string, object> { ["type"] = "json_object" }
                    });

                    Dictionary<string, object> attemptRecord = CharacterConstructionAttemptRecord(attempt, llm);
                    attemptRecord["maxTokens"] = attemptMaxTokens;
                    attemptRecord["adaptiveRetry"] = attempt > 1;
                    if (ReadBool(llm, "ok", false))
                    {
                        string content = ReadString(llm, "content", "");
                        generated = TryParseJsonObject(content);
                        attemptRecord["contentChars"] = content.Length;
                        attemptRecord["parsed"] = generated != null;
                        if (generated == null)
                        {
                            string finishReason = ReadString(llm, "finishReason", "");
                            attemptRecord["error"] = string.Equals(finishReason, "length", StringComparison.OrdinalIgnoreCase)
                                ? "Character construction response hit the max token limit before valid JSON completed."
                                : "Character construction response was not valid JSON.";
                        }
                    }

                    attempts.Add(attemptRecord);
                }

                llmUsed = generated != null;
            }

            if (generated == null)
            {
                if (useLlm && !string.Equals(source, "background_enrichment", StringComparison.OrdinalIgnoreCase))
                {
                    string diagnostic = BuildCharacterConstructionDiagnostic(heroId, hero, attempts, llm);
                    Dictionary<string, object> failed = new Dictionary<string, object>
                    {
                        ["ok"] = false,
                        ["version"] = 1,
                        ["constructionEngineVersion"] = CharacterConstructionEngineVersion,
                        ["status"] = "failed",
                        ["schemaVersion"] = CharacterSchemaVersion,
                        ["campaignId"] = campaignId,
                        ["heroStringId"] = heroId,
                        ["source"] = source ?? "unknown",
                        ["llmUsed"] = false,
                        ["attempts"] = attempts,
                        ["settingsRevision"] = ReadString(constructionSettings, "settingsRevision", ""),
                        ["settingsFingerprint"] = SettingsFingerprint(constructionSettings),
                        ["failureKind"] = CharacterConstructionFailureKind(attempts, llm),
                        ["diagnostic"] = diagnostic,
                        ["error"] = diagnostic,
                        ["failedUtc"] = DateTime.UtcNow.ToString("o"),
                        ["durationMs"] = timer.ElapsedMilliseconds
                    };
                    WriteJsonObject(constructedPath, failed);
                    AppendJsonLineToPath(CharacterFile(campaignId, heroId, "history", "decisions.jsonl"), new Dictionary<string, object>
                    {
                        ["id"] = Guid.NewGuid().ToString("N"),
                        ["ts"] = DateTimeOffset.UtcNow.ToUnixTimeSeconds(),
                        ["type"] = "character_construction",
                        ["status"] = "failed",
                        ["source"] = source ?? "unknown",
                        ["attempts"] = attempts,
                        ["diagnostic"] = diagnostic,
                        ["durationMs"] = timer.ElapsedMilliseconds
                    });
                    LogOperational("character_construction.failed", failed);
                    return failed;
                }

                generated = DefaultGeneratedCharacter(hero, traits);
            }

            if (ReadBool(hero, "isNotable", false))
            {
                if (!CharacterHasEditorCorrections(campaignId, heroId))
                {
                    traits["assignmentOverrides"] = new ArrayList();
                    EnsureTraitPercentageData(traits, heroId);
                    ApplyGeneratedPersonalityPortrait(traits, generated, ReadString(hero, "name", heroId));
                }
            }
            else
            {
                ApplyGeneratedTraitConstruction(traits, generated, hero);
            }
            EnsureCourtCharacterData(traits, hero, heroId);
            WriteJsonObject(CharacterFile(campaignId, heroId, "traits.json"), traits);

            Dictionary<string, object> background = DictionaryOrDefault(generated, "background", DefaultBackground(hero, traits));
            EnsureEncyclopediaText(background, hero, traits);
            WriteJsonObject(CharacterFile(campaignId, heroId, "background.json"), background);
            WriteJsonObject(CharacterFile(campaignId, heroId, "voice.json"), DictionaryOrDefault(generated, "voice", DefaultVoice(hero, traits)));
            WriteJsonObject(CharacterFile(campaignId, heroId, "motivations.json"), DictionaryOrDefault(generated, "motivations", DefaultMotivations(hero)));
            WriteJsonObject(CharacterFile(campaignId, heroId, "save_quirks.json"), DictionaryOrDefault(generated, "saveQuirks", DictionaryOrDefault(generated, "save_quirks", DefaultSaveQuirks(hero, traits))));
            WriteJsonObject(CharacterFile(campaignId, heroId, "hidden_history.json"), DictionaryOrDefault(generated, "hiddenHistory", DictionaryOrDefault(generated, "hidden_history", DefaultHiddenHistory(hero))));
            WriteJsonObject(CharacterFile(campaignId, heroId, "secrets.json"), DictionaryOrDefault(generated, "secrets", DefaultSecrets(hero)));
            WriteJsonObject(CharacterFile(campaignId, heroId, "pressure.json"), DictionaryOrDefault(generated, "pressure", DefaultPressure(hero)));

            string status = llmUsed ? "ready" : "fallback_ready";
            Dictionary<string, object> constructed = new Dictionary<string, object>
            {
                ["ok"] = true,
                ["version"] = 1,
                ["constructionEngineVersion"] = CharacterConstructionEngineVersion,
                ["status"] = status,
                ["schemaVersion"] = CharacterSchemaVersion,
                ["campaignId"] = campaignId,
                ["heroStringId"] = heroId,
                ["source"] = source ?? "unknown",
                ["llmUsed"] = llmUsed,
                ["llmError"] = llm == null ? "" : ReadString(llm, "error", ""),
                ["attempts"] = attempts,
                ["settingsRevision"] = ReadString(constructionSettings, "settingsRevision", ""),
                ["settingsFingerprint"] = SettingsFingerprint(constructionSettings),
                ["constructedUtc"] = DateTime.UtcNow.ToString("o"),
                ["durationMs"] = timer.ElapsedMilliseconds
            };
            WriteJsonObject(constructedPath, constructed);
            AppendJsonLineToPath(CharacterFile(campaignId, heroId, "history", "decisions.jsonl"), new Dictionary<string, object>
            {
                ["id"] = Guid.NewGuid().ToString("N"),
                ["ts"] = DateTimeOffset.UtcNow.ToUnixTimeSeconds(),
                ["type"] = "character_construction",
                ["status"] = status,
                ["source"] = source ?? "unknown",
                ["llmUsed"] = llmUsed,
                ["durationMs"] = timer.ElapsedMilliseconds
            });

            return constructed;
        }

        private static Dictionary<string, object> CharacterConstructionAttemptRecord(int attempt, Dictionary<string, object> llm)
        {
            llm = llm ?? new Dictionary<string, object>();
            Dictionary<string, object> record = new Dictionary<string, object>
            {
                ["attempt"] = attempt,
                ["ok"] = ReadBool(llm, "ok", false),
                ["requestType"] = ReadString(llm, "requestType", "character_construction"),
                ["model"] = ReadString(llm, "model", ""),
                ["durationMs"] = ReadLong(llm, "durationMs", 0),
                ["requestChars"] = ReadLong(llm, "requestChars", 0),
                ["responseChars"] = ReadLong(llm, "responseChars", 0)
            };

            string error = ReadString(llm, "error", "");
            if (!string.IsNullOrWhiteSpace(error))
            {
                record["error"] = error;
            }
            else if (!ReadBool(llm, "ok", false))
            {
                record["error"] = "LLM call failed without a provider error message.";
            }

            string finishReason = ReadString(llm, "finishReason", "");
            if (!string.IsNullOrWhiteSpace(finishReason))
            {
                record["finishReason"] = finishReason;
            }

            return record;
        }

        private static int CharacterConstructionMaxTokensForAttempt(int configuredMaxTokens, int attempt)
        {
            int configured = Math.Max(1200, Math.Min(CharacterConstructionTokenCeiling, configuredMaxTokens));
            if (attempt <= 1)
            {
                return configured;
            }

            return Math.Min(CharacterConstructionTokenCeiling, Math.Max(configured + 1200, configured * 2));
        }

        private static string BuildCharacterConstructionPromptForAttempt(
            string campaignId,
            string heroId,
            Dictionary<string, object> hero,
            Dictionary<string, object> traits,
            int attempt)
        {
            string prompt = BuildCharacterConstructionPrompt(campaignId, heroId, hero, traits);
            if (attempt <= 1)
            {
                return prompt;
            }

            return prompt + @"

CRITICAL RETRY COMPACTION:
The previous attempt did not complete a JSON object within its output budget.
- Return the complete JSON object in no more than 12,000 characters total.
- Preserve the required 1,200-1,600 character basePersonalitySummary.
- Use exactly one concise sentence for every other scalar string.
- Use at most two short entries in every array.
- Do not repeat trait definitions, source data, instructions, or schema descriptions.
- Close every object and array. A complete compact object is more important than decorative detail.";
        }

        private static bool IsCharacterConstructionReady(Dictionary<string, object> construction)
        {
            return ReadBool(construction, "ok", false)
                && IsUsableCharacterStatus(ReadString(construction, "status", ""));
        }

        private static bool IsUsableCharacterStatus(string status)
        {
            return string.Equals(status, "canonical_ready", StringComparison.OrdinalIgnoreCase)
                || string.Equals(status, "baseline_ready", StringComparison.OrdinalIgnoreCase)
                || string.Equals(status, "enriched", StringComparison.OrdinalIgnoreCase)
                || string.Equals(status, "ready", StringComparison.OrdinalIgnoreCase)
                || string.Equals(status, "fallback_ready", StringComparison.OrdinalIgnoreCase);
        }

        private static Dictionary<string, object> CharacterConstructionFailureResponse(string kind, string campaignId, string heroId, string heroName, Dictionary<string, object> construction, Dictionary<string, object> timing, Dictionary<string, object> extra)
        {
            string diagnostic = ReadString(construction, "diagnostic", ReadString(construction, "error", ""));
            if (string.IsNullOrWhiteSpace(diagnostic))
            {
                diagnostic = "Character generation has failed for " + FirstNonEmpty(heroName, heroId) + ". No dialogue response was generated. Check the character_construction entries in the LLM log.";
            }

            Dictionary<string, object> response = new Dictionary<string, object>
            {
                ["ok"] = false,
                ["stage"] = "character_construction",
                ["kind"] = kind,
                ["campaignId"] = campaignId,
                ["heroStringId"] = heroId,
                ["heroName"] = FirstNonEmpty(heroName, heroId),
                ["error"] = diagnostic,
                ["diagnostic"] = diagnostic,
                ["construction"] = construction ?? new Dictionary<string, object>(),
                ["timing"] = timing ?? new Dictionary<string, object>()
            };

            if (extra != null)
            {
                foreach (KeyValuePair<string, object> pair in extra)
                {
                    response[pair.Key] = pair.Value;
                }
            }

            return response;
        }

        private static string BuildCharacterConstructionDiagnostic(string heroId, Dictionary<string, object> hero, List<Dictionary<string, object>> attempts, Dictionary<string, object> lastLlm)
        {
            string heroName = ReadString(hero, "name", heroId);
            string lastError = LastConstructionError(attempts, lastLlm);
            string likelyIssue = LikelyCharacterConstructionIssue(lastError, attempts);
            string errorText = string.IsNullOrWhiteSpace(lastError) ? "No provider error text was returned." : " Last error: " + lastError;
            return "Character generation has failed for " + FirstNonEmpty(heroName, heroId) + " after two attempts. Likely issue: " + likelyIssue + errorText + " No dialogue or event response was generated.";
        }

        private static string LastConstructionError(List<Dictionary<string, object>> attempts, Dictionary<string, object> lastLlm)
        {
            if (attempts != null)
            {
                for (int index = attempts.Count - 1; index >= 0; index--)
                {
                    string error = ReadString(attempts[index], "error", "");
                    if (!string.IsNullOrWhiteSpace(error))
                    {
                        return error;
                    }
                }
            }

            return ReadString(lastLlm, "error", "");
        }

        private static string LikelyCharacterConstructionIssue(string lastError, List<Dictionary<string, object>> attempts)
        {
            string lowered = (lastError ?? string.Empty).ToLowerInvariant();
            bool parseFailure = attempts != null && attempts.Any(x => x.ContainsKey("parsed") && !ReadBool(x, "parsed", true));
            bool lengthFinish = attempts != null && attempts.Any(x => string.Equals(ReadString(x, "finishReason", ""), "length", StringComparison.OrdinalIgnoreCase));

            if (parseFailure && (lengthFinish || lowered.Contains("max token") || lowered.Contains("token limit")))
            {
                return "the model response was cut off by the character construction token limit before valid JSON completed.";
            }

            if (lowered.Contains("api url is empty") || lowered.Contains("invalid uri") || lowered.Contains("uri format"))
            {
                return "the LLM API URL is missing or malformed in the server settings.";
            }

            if (lowered.Contains("unauthorized") || lowered.Contains("401") || lowered.Contains("api key") || lowered.Contains("invalid key"))
            {
                return "the API key is missing, expired, or rejected by the provider.";
            }

            if (lowered.Contains("forbidden") || lowered.Contains("403"))
            {
                return "the provider rejected this key, endpoint, or model permission.";
            }

            if (lowered.Contains("not found") || lowered.Contains("404") || lowered.Contains("model"))
            {
                return "the configured character construction model or endpoint may be wrong.";
            }

            if (lowered.Contains("rate") || lowered.Contains("quota") || lowered.Contains("429") || lowered.Contains("limit"))
            {
                return "the provider is rate-limiting requests or the account quota is exhausted.";
            }

            if (lowered.Contains("timeout") || lowered.Contains("timed out") || lowered.Contains("task canceled"))
            {
                return "the provider call timed out before character construction finished.";
            }

            if (lowered.Contains("connection") || lowered.Contains("refused") || lowered.Contains("dns") || lowered.Contains("name resolution") || lowered.Contains("ssl") || lowered.Contains("certificate"))
            {
                return "the server could not reach the configured LLM endpoint.";
            }

            if (parseFailure || lowered.Contains("json") || lowered.Contains("parse"))
            {
                return "the model answered, but did not return the strict JSON object required for character construction.";
            }

            return "the character construction LLM call failed. Check the server LLM log for requestType character_construction, plus the API URL, key, and model.";
        }

        private static string CharacterConstructionFailureKind(List<Dictionary<string, object>> attempts, Dictionary<string, object> lastLlm)
        {
            string error = LastConstructionError(attempts, lastLlm).ToLowerInvariant();
            if (error.Contains("api url is empty") || error.Contains("invalid uri") || error.Contains("uri format")
                || error.Contains("unauthorized") || error.Contains("401") || error.Contains("api key")
                || error.Contains("invalid key") || error.Contains("missing_api_key") || error.Contains("forbidden")
                || error.Contains("403") || error.Contains("not found") || error.Contains("404") || error.Contains("model"))
            {
                return "configuration";
            }

            if (error.Contains("rate") || error.Contains("quota") || error.Contains("429"))
            {
                return "provider_limit";
            }

            if (error.Contains("timeout") || error.Contains("timed out") || error.Contains("task canceled")
                || error.Contains("connection") || error.Contains("refused") || error.Contains("dns")
                || error.Contains("name resolution") || error.Contains("ssl") || error.Contains("certificate"))
            {
                return "connection";
            }

            bool parseFailure = attempts != null && attempts.Any(x => x.ContainsKey("parsed") && !ReadBool(x, "parsed", true));
            return parseFailure ? "parse" : "unknown";
        }

        private static bool ShouldRetryFailedConstruction(Dictionary<string, object> failedStatus, Dictionary<string, object> settings)
        {
            if (failedStatus == null || !string.Equals(ReadString(failedStatus, "status", ""), "failed", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            string failureKind = ReadString(failedStatus, "failureKind", "");
            if (string.IsNullOrWhiteSpace(failureKind))
            {
                failureKind = CharacterFailureKindFromText(ReadString(failedStatus, "error", ReadString(failedStatus, "diagnostic", "")));
            }
            bool retryableAfterSettingsChange =
                string.Equals(failureKind, "configuration", StringComparison.OrdinalIgnoreCase)
                || string.Equals(failureKind, "connection", StringComparison.OrdinalIgnoreCase)
                || string.Equals(failureKind, "parse", StringComparison.OrdinalIgnoreCase)
                || string.Equals(failureKind, "output_limit", StringComparison.OrdinalIgnoreCase)
                || string.Equals(failureKind, "provider_limit", StringComparison.OrdinalIgnoreCase);
            if (!retryableAfterSettingsChange)
            {
                return false;
            }

            if (string.Equals(failureKind, "parse", StringComparison.OrdinalIgnoreCase)
                && ReadInt(failedStatus, "constructionEngineVersion", 0) < CharacterConstructionEngineVersion)
            {
                return true;
            }

            string failedRevision = ReadString(failedStatus, "settingsRevision", "");
            string currentRevision = ReadString(settings, "settingsRevision", "");
            string failedFingerprint = ReadString(failedStatus, "settingsFingerprint", "");
            string currentFingerprint = SettingsFingerprint(settings);
            bool settingsChanged = (!string.IsNullOrWhiteSpace(currentRevision) && !string.Equals(failedRevision, currentRevision, StringComparison.OrdinalIgnoreCase))
                || (!string.IsNullOrWhiteSpace(currentFingerprint) && !string.Equals(failedFingerprint, currentFingerprint, StringComparison.OrdinalIgnoreCase));
            if (settingsChanged)
            {
                return true;
            }

            if (DateTime.TryParse(ReadString(failedStatus, "failedUtc", ""), out DateTime failedUtc) && File.Exists(SettingsPath))
            {
                return File.GetLastWriteTimeUtc(SettingsPath) > failedUtc.ToUniversalTime();
            }

            return false;
        }

        private static string CharacterFailureKindFromText(string text)
        {
            string lowered = (text ?? string.Empty).ToLowerInvariant();
            if (lowered.Contains("api key") || lowered.Contains("missing_api_key") || lowered.Contains("invalid authentication")
                || lowered.Contains("unauthorized") || lowered.Contains("401") || lowered.Contains("forbidden")
                || lowered.Contains("403") || lowered.Contains("api url") || lowered.Contains("model") || lowered.Contains("404"))
            {
                return "configuration";
            }

            if (lowered.Contains("timeout") || lowered.Contains("connection") || lowered.Contains("dns") || lowered.Contains("ssl"))
            {
                return "connection";
            }

            if (lowered.Contains("json") || lowered.Contains("parse") || lowered.Contains("token limit") || lowered.Contains("max token"))
            {
                return "parse";
            }

            return "unknown";
        }

        private static Dictionary<string, object> DialogueHistory(Dictionary<string, object> payload)
        {
            if (ReadBool(payload, "wandererContactOnly", false)) return WandererContactHistory(payload);
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", "default");
            string heroId = ReadFirstString(payload, "heroStringId", "heroId", "characterId");
            int limit = Math.Max(1, ReadInt(payload, "limit", 60));
            if (string.IsNullOrWhiteSpace(heroId))
            {
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "heroStringId is required." };
            }

            string path = CharacterFile(campaignId, heroId, "history", "dialogue.jsonl");
            List<Dictionary<string, object>> all = ReadJsonLinesFromPath(path);
            bool officialMode = string.Equals(ReadString(payload, "conversationMode", ""), "ambassador_official", StringComparison.OrdinalIgnoreCase);
            if (officialMode)
            {
                string postingId = ReadString(payload, "postingId", "");
                all = all.Where(x => string.Equals(ReadString(x, "channel", ""), "ambassador_official", StringComparison.OrdinalIgnoreCase)
                    && (string.IsNullOrWhiteSpace(postingId) || string.Equals(ReadString(x, "postingId", ""), postingId, StringComparison.OrdinalIgnoreCase))).ToList();
            }
            int start = Math.Max(0, all.Count - limit);
            List<Dictionary<string, object>> lines = all.Skip(start).ToList();
            foreach (Dictionary<string, object> line in lines)
            {
                if (string.Equals(ReadString(line, "role", ""), "npc", StringComparison.OrdinalIgnoreCase))
                {
                    line["text"] = SanitizeVisibleReply(ReadString(line, "text", ""));
                }
            }

            return new Dictionary<string, object>
            {
                ["ok"] = true,
                ["campaignId"] = campaignId,
                ["heroStringId"] = heroId,
                ["lines"] = lines
            };
        }

        private static Dictionary<string, object> DialogueRespond(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            return RunCodexConversationScope(payload, () => DialogueRespondCore(payload));
        }

        private static Dictionary<string, object> DialogueRespondCore(Dictionary<string, object> payload)
        {
            Stopwatch totalTimer = Stopwatch.StartNew();
            Stopwatch phaseTimer = new Stopwatch();
            long upsertMs = 0;
            long contextLoadMs = 0;
            long promptBuildMs = 0;
            long llmMs = 0;
            long parseMs = 0;
            long storageMs = 0;
            long constructionMs = 0;
            long npcRelationshipContextMs = 0;
            Dictionary<string, object> npcRelationshipPrompt =
                new Dictionary<string, object>();
            Dictionary<string, object> construction = new Dictionary<string, object>();
            payload = payload ?? new Dictionary<string, object>();
            string correlationId = EnsureCorrelationId(payload);
            Dictionary<string, object> hero = ReadDictionary(payload, "hero") ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", ReadString(hero, "campaignId", "default"));
            bool officialAmbassador = string.Equals(ReadString(payload, "conversationMode", ""), "ambassador_official", StringComparison.OrdinalIgnoreCase)
                || string.Equals(ReadString(payload, "channel", ""), "ambassador_official", StringComparison.OrdinalIgnoreCase);
            bool rulerPetitionAudience = string.Equals(
                ReadString(payload, "conversationMode", ""),
                "ruler_petition", StringComparison.OrdinalIgnoreCase)
                || string.Equals(ReadString(payload, "channel", ""),
                    "ruler_petition", StringComparison.OrdinalIgnoreCase);
            bool nobleDocketAudience = string.Equals(
                ReadString(payload, "conversationMode", ""),
                "noble_docket", StringComparison.OrdinalIgnoreCase)
                || string.Equals(ReadString(payload, "channel", ""),
                    "noble_docket", StringComparison.OrdinalIgnoreCase);
            bool courtLifeAudience = string.Equals(ReadString(payload, "conversationMode", ""), "court_life", StringComparison.OrdinalIgnoreCase);
            bool privateGovernmentChannel = string.Equals(ReadString(payload, "channel", ""), "in_person", StringComparison.OrdinalIgnoreCase)
                && !officialAmbassador && !rulerPetitionAudience && !nobleDocketAudience && !courtLifeAudience;
            if (privateGovernmentChannel)
                payload["sceneContext"] = ReadString(payload, "sceneContext", "") + "\n" + BuildGovernmentPrivateConversationPrompt(payload);
            string dialogueAuditRunId = ReadString(payload, "dialogueAuditRunId", "");
            if (!string.IsNullOrWhiteSpace(dialogueAuditRunId))
            {
                Dictionary<string, object> replay = ReadNpcDialogueAuditResponse(campaignId, correlationId);
                if (replay != null)
                {
                    replay["idempotentReplay"] = true;
                    return replay;
                }
            }
            string heroId = ReadFirstString(payload, "heroStringId", "heroId", "characterId");
            if (string.IsNullOrWhiteSpace(heroId))
            {
                heroId = CharacterIdFrom(hero);
            }

            string playerText = ReadFirstString(payload, "playerText", "text", "message");
            Dictionary<string, object> visitorPromptContext = ReadDictionary(payload, "nobleVisitorContext");
            if (visitorPromptContext != null)
                payload["sceneContext"] = ReadString(payload, "sceneContext", "") + "\n" + BuildNobleVisitorPrompt(campaignId, heroId, visitorPromptContext);
            string playerPromptLabel = NormalizePregnancyChoiceToken(ReadFirstString(payload, "playerPromptLabel", "player_prompt_label"));
            if (string.IsNullOrWhiteSpace(heroId))
            {
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "heroStringId is required." };
            }

            if (string.IsNullOrWhiteSpace(playerText))
            {
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "playerText is required." };
            }
            if (officialAmbassador)
            {
                Dictionary<string, object> officialContextError = ValidateOfficialAmbassadorContext(campaignId, payload);
                if (officialContextError != null) return officialContextError;
                payload["officialMemoryFirewall"] = true;
                payload["suppressConceptionGate"] = true;
            }
            if (!string.IsNullOrWhiteSpace(playerPromptLabel) && playerPromptLabel != "pull_out")
            {
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "Unknown playerPromptLabel." };
            }

            Dictionary<string, object> guardedPromptOverrideEvidence;
            string testDirectiveText;
            bool isTestDirective = TryAuthorizeGuardedPromptOverride(
                campaignId, payload, out testDirectiveText,
                out guardedPromptOverrideEvidence);
            bool governmentCertificationMemoryIsolation = isTestDirective
                && string.Equals(ReadString(guardedPromptOverrideEvidence, "profile", ""),
                    "government_certification_memory_isolation",
                    StringComparison.OrdinalIgnoreCase);
            bool actionAcceptanceCooperation = isTestDirective
                && string.Equals(ReadString(guardedPromptOverrideEvidence, "profile", ""),
                    "action_acceptance_cooperation",
                    StringComparison.OrdinalIgnoreCase);
            SaveTestSnapshotFromPayload(campaignId, correlationId, "dialogue", "dialogue.request", payload);
            WriteAudit(campaignId, correlationId, "game_client", "dialogue", "dialogue.request", heroId, "", "", "started", 0, "Dialogue request received.", new Dictionary<string, object>
            {
                ["hero"] = hero,
                ["playerText"] = playerText,
                ["sceneContext"] = ReadString(payload, "sceneContext", ""),
                ["selectedContextPulls"] = ReadDictionaryList(payload, "selectedContextPulls"),
                ["contextBundles"] = ReadDictionaryList(payload, "contextBundles"),
                ["actionResolutionIndex"] = ReadDictionary(payload, "actionResolutionIndex"),
                ["guardedPromptOverride"] = guardedPromptOverrideEvidence
            });

            string promptPlayerText = playerPromptLabel == "pull_out"
                ? LoadPromptTemplate("pull_out.txt")
                : playerText;
            payload["playerPromptLabel"] = playerPromptLabel;

            phaseTimer.Restart();
            if (hero.Count > 0)
            {
                if (!hero.ContainsKey("heroStringId"))
                {
                    hero["heroStringId"] = heroId;
                }

                UpsertCharacterProfile(campaignId, hero);
            }
            upsertMs = phaseTimer.ElapsedMilliseconds;

            phaseTimer.Restart();
            construction = EnsureCharacterConstructed(campaignId, heroId, hero, "dialogue");
            constructionMs = phaseTimer.ElapsedMilliseconds;
            if (!IsCharacterConstructionReady(construction))
            {
                totalTimer.Stop();
                Dictionary<string, object> failedTiming = DialogueTiming(totalTimer.ElapsedMilliseconds, upsertMs, constructionMs, contextLoadMs, promptBuildMs, llmMs, 0, parseMs, storageMs);
                Dictionary<string, object> failed = CharacterConstructionFailureResponse("dialogue", campaignId, heroId, ReadString(hero, "name", heroId), construction, failedTiming, null);
                LogOperational("dialogue.character_construction_failed", failed);
                WriteAudit(campaignId, correlationId, "server", "dialogue", "character.construction", heroId, "", "", "failed", constructionMs, "Character construction failed before dialogue response.", new Dictionary<string, object>
                {
                    ["construction"] = construction,
                    ["timing"] = failedTiming
                });
                return failed;
            }

            phaseTimer.Restart();
            string heroName = ReadString(hero, "name", heroId);
            string playerName = ReadString(payload, "playerName", "Player");
            string sceneContext = ReadString(payload, "sceneContext", "");
            if (governmentCertificationMemoryIsolation)
            {
                sceneContext = AppendGovernmentCertificationMemoryIsolationContext(
                    sceneContext, testDirectiveText);
            }
            else if (actionAcceptanceCooperation)
            {
                sceneContext = AppendActionAcceptanceCooperationContext(sceneContext);
            }
            else if (isTestDirective)
            {
                sceneContext = AppendTestDirectiveContext(sceneContext, testDirectiveText);
            }

            Dictionary<string, object> settings = LoadSettings();
            string requestedConversationSessionId = ReadFirstString(payload, "conversationSessionId", "sessionId", "conversationId");
            int liveHistoryLimit = Math.Max(2, Math.Min(100, ReadInt(payload, "historyLimit", ReadInt(settings, "recentRawConversationTurns", 30))));
            List<Dictionary<string, object>> priorLines = CanonicalizePromptTranscript(
                ReadCurrentSessionDialogueLines(campaignId, requestedConversationSessionId, liveHistoryLimit), liveHistoryLimit);
            if (governmentCertificationMemoryIsolation)
            {
                priorLines = IsolateGovernmentCertificationTranscript(priorLines,
                    ReadInt(payload, "dialogueAuditTurnIndex", -1));
            }
            if (officialAmbassador)
            {
                List<Dictionary<string, object>> officialHistory = ReadOfficialAmbassadorArchiveLines(campaignId, payload, Math.Max(8, liveHistoryLimit));
                priorLines = CanonicalizePromptTranscript(officialHistory.Concat(priorLines).ToList(), liveHistoryLimit);
            }
            else if (priorLines.Count == 0 && string.IsNullOrWhiteSpace(requestedConversationSessionId))
            {
                priorLines = ReadDialogueLines(campaignId, heroId, Math.Min(8, ReadInt(payload, "historyLimit", 24)));
            }
            Dictionary<string, object> identityView = ResolvePromptIdentity(payload, heroId, "dialogue",
                ReadFirstString(payload, "conversationSessionId", "sessionId", "conversationId"), priorLines);
            string promptPlayerName = ReadString(identityView, "usableName", "the stranger");
            payload["identityView"] = identityView;
            Dictionary<string, object> profile = ReadJsonObject(CharacterFile(campaignId, heroId, "profile.json"));
            Dictionary<string, object> characteristics = LoadCharacterStack(campaignId, heroId);
            Dictionary<string, object> state = ReadJsonObject(CharacterFile(campaignId, heroId, "state.json"));
            Dictionary<string, object> relationships = ReadJsonObject(CharacterFile(campaignId, heroId, "memory", "relationships.json"));
            Dictionary<string, object> summary = ReadJsonObject(CharacterFile(campaignId, heroId, "memory", "summary.json"));
            List<Dictionary<string, object>> memories = ReadJsonLinesFromPath(CharacterFile(campaignId, heroId, "memory", "memories.jsonl"))
                .Where(DurableDialogueMemoryRowIsUsable)
                .OrderByDescending(x => ReadLong(x, "ts", 0))
                .Take(ReadInt(settings, "maxContextMemories", 12))
                .Reverse()
                .ToList();
            List<Dictionary<string, object>> selectedContextPulls = NormalizeSelectedContextPulls(ReadDictionaryList(payload, "selectedContextPulls"), ContextPullIds.ToList());
            List<Dictionary<string, object>> contextBundles = ReadDictionaryList(payload, "contextBundles");
            if (officialAmbassador)
            {
                relationships = new Dictionary<string, object>();
                summary = new Dictionary<string, object>();
                memories.Clear();
                selectedContextPulls = selectedContextPulls.Where(x => !ContainsAny(ReadFirstString(x, "id", "pullId"), "relevant_memory", "relationship_history")).ToList();
                contextBundles = contextBundles.Where(x => !ContainsAny(ReadFirstString(x, "id", "pullId", "type"), "relevant_memory", "relationship_history", "private_conversation")).ToList();
            }
            else if (governmentCertificationMemoryIsolation)
            {
                // The requested conversation session remains intact so a natural
                // follow-up can respond to the immediately preceding turn. Only
                // recalled out-of-session certification material is excluded.
                state = new Dictionary<string, object>();
                relationships = new Dictionary<string, object>();
                summary = new Dictionary<string, object>();
                memories.Clear();
                selectedContextPulls = selectedContextPulls.Where(x =>
                    !ContainsAny(ReadFirstString(x, "id", "pullId"),
                        "relevant_memory", "relationship_history",
                        "private_conversation", "conversation_scene")).ToList();
                contextBundles = contextBundles.Where(x =>
                    !ContainsAny(ReadFirstString(x, "id", "pullId", "type"),
                        "relevant_memory", "relationship_history",
                        "private_conversation", "conversation_scene")).ToList();
            }
            else
            {
                AppendSpymasterRelevantMemoryBundle(campaignId,
                    ReadString(payload, "timelineId", "main"), heroId,
                    selectedContextPulls, contextBundles);
            }
            Dictionary<string, object> catalog = ActionCatalog();
            List<Dictionary<string, object>> compactActionCatalog = CompactActionCatalog(catalog);
            contextLoadMs = phaseTimer.ElapsedMilliseconds;
            WriteAudit(campaignId, correlationId, "server", "dialogue", "context.loaded", heroId, "", "", "completed", contextLoadMs, "Loaded character stack, memory, context bundles, and action catalog.", new Dictionary<string, object>
            {
                ["profile"] = profile,
                ["characteristics"] = characteristics,
                ["state"] = state,
                ["relationships"] = relationships,
                ["memorySummary"] = summary,
                ["memories"] = memories,
                ["priorLines"] = priorLines,
                ["selectedContextPulls"] = selectedContextPulls,
                ["contextBundles"] = contextBundles,
                ["actionCatalog"] = compactActionCatalog,
                ["identityView"] = identityView
            });

            phaseTimer.Restart();
            using (ReignTraceScope relationshipTrace = BeginReignSpan(
                "relationship.history.resolve",
                new Dictionary<string, object>
                {
                    ["campaignId"] = campaignId,
                    ["correlationId"] = correlationId,
                    ["mode"] = "dialogue",
                    ["heroId"] = heroId
                }))
            {
                npcRelationshipPrompt = officialAmbassador
                    || governmentCertificationMemoryIsolation
                    ? new Dictionary<string, object>{{"block",""},{"targets",new List<Dictionary<string,object>>()}}
                    : BuildNpcRelationshipPromptContext(campaignId, heroId, payload);
                relationshipTrace.Set("targetCount",
                    ReadDictionaryList(npcRelationshipPrompt, "targets").Count);
            }
            npcRelationshipContextMs = phaseTimer.ElapsedMilliseconds;
            payload["precomputedNpcRelationshipPrompt"] = npcRelationshipPrompt;
            WriteAudit(campaignId, correlationId, "server", "dialogue",
                "relationship_history.loaded", heroId, "", "", "completed",
                npcRelationshipContextMs,
                "Resolved reusable NPC relationship history before local prompt assembly.",
                new Dictionary<string, object>
                {
                    ["npcRelationshipPrompt"] = npcRelationshipPrompt,
                    ["timing"] = NpcRelationshipTiming(
                        npcRelationshipContextMs, npcRelationshipPrompt)
                });

            phaseTimer.Restart();
            Dictionary<string, object> conversationSceneState = PrepareConversationSceneState(
                campaignId, payload, heroId, promptPlayerText, priorLines, ReadString(payload, "mode", "dialogue"));
            PromptEnvelope promptEnvelope;
            using (ReignTraceScope promptTrace = BeginReignSpan("prompt.build", new Dictionary<string, object>
            { ["campaignId"] = campaignId, ["correlationId"] = correlationId, ["mode"] = "dialogue", ["heroId"] = heroId }))
            {
                if (ActiveCodexConversationScope.Value != null) payload["codexParallelPreparation"] = new Dictionary<string, object>
                { ["consistentSnapshot"] = true, ["characterInitialized"] = true, ["requiredStateUpdatesComplete"] = true };
                promptEnvelope = BuildDialoguePromptEnvelope(campaignId, heroId, heroName, promptPlayerName, playerName, promptPlayerText, sceneContext, profile, characteristics, state, relationships, summary, priorLines, selectedContextPulls, contextBundles, compactActionCatalog, identityView, payload);
                promptTrace.Set("promptChars", promptEnvelope.TotalChars);
            }
            Dictionary<string, object> motiveDecision = ReadDictionary(promptEnvelope.Diagnostics, "motiveDecision") ?? new Dictionary<string, object>();
            List<Dictionary<string, object>> messages = promptEnvelope.Messages;
            promptBuildMs = phaseTimer.ElapsedMilliseconds;
            WriteAudit(campaignId, correlationId, "server", "dialogue", "prompt.built", heroId, "", "", "completed", promptBuildMs, "Dialogue prompt assembled.", new Dictionary<string, object>
            {
                ["messages"] = messages,
                ["promptChars"] = promptEnvelope.TotalChars,
                ["promptEnvelope"] = promptEnvelope.Diagnostics,
                ["promptEvidence"] = BuildNpcDialoguePromptAuditEvidence(campaignId, payload, messages, selectedContextPulls),
                ["contextBundleCount"] = contextBundles.Count,
                ["selectedContextPullCount"] = selectedContextPulls.Count
            });

            phaseTimer.Restart();
            Dictionary<string, object> dialogueLlmRequest = new Dictionary<string, object>
            {
                ["requestType"] = "dialogue",
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["heroStringId"] = heroId,
                ["playerText"] = playerText,
                ["messages"] = messages,
                ["promptEnvelope"] = promptEnvelope.Diagnostics,
                ["promptCacheEligible"] = true,
                ["temperature"] = Math.Min(0.5d, ReadDouble(settings, "temperature", 0.7d)),
                // Dialogue JSON carries the visible reply plus private decision,
                // relationship, memory, identity, and action metadata. A 2,000
                // token ceiling repeatedly truncated otherwise valid first calls
                // and forced a complete prompt resend solely to close the JSON.
                ["maxTokens"] = StructuredDialogueResponseMaxTokens(settings),
                ["response_format"] = new Dictionary<string, object> { ["type"] = "json_object" }
            };
            AttachCodexAuthoritativeConversationMetadata(dialogueLlmRequest, payload, campaignId, heroId, "dialogue", requestedConversationSessionId,
                identityView, profile, state, relationships, summary, conversationSceneState, memories, contextBundles, priorLines, promptPlayerText);
            Dictionary<string, object> llm = ChatWithLlm(dialogueLlmRequest);
            llm = WithDiagnosticTransformation("Answer structure and format repair", llm, () => RetryMalformedStructuredResponse(llm, dialogueLlmRequest, campaignId, correlationId, "dialogue", heroId, ""));
            if (!ReadBool(llm, "visibleRepairFailure", false))
                llm = WithDiagnosticTransformation("Character motives", llm, () => RetryMotiveContradictoryResponse(llm, dialogueLlmRequest, motiveDecision, campaignId, correlationId, "dialogue", heroId, ""));
            if (!ReadBool(llm, "visibleRepairFailure", false))
                llm = WithDiagnosticTransformation("Political conduct", llm, () => EnforcePoliticalConductResponse(llm,
                dialogueLlmRequest, motiveDecision, campaignId,
                correlationId, "dialogue", heroId, ""));
            if (!ReadBool(llm, "visibleRepairFailure", false))
                llm = WithDiagnosticTransformation("Family and kinship facts", llm, () => RetryKinshipContradictoryResponse(llm, dialogueLlmRequest, payload, campaignId, correlationId, "dialogue", heroId, ""));
            if (!ReadBool(llm, "visibleRepairFailure", false))
                llm = WithDiagnosticTransformation("Dialogue integrity", llm, () => RetryDialogueIntegrityViolation(llm, dialogueLlmRequest, payload, priorLines,
                campaignId, correlationId, "dialogue", heroId, ""));
            if (!ReadBool(llm, "visibleRepairFailure", false))
                llm = WithDiagnosticTransformation("Continuity and repeated narration", llm, () => RetryRoleplayContinuityViolation(llm, dialogueLlmRequest, payload, identityView, priorLines,
                campaignId, correlationId, "dialogue", heroId, heroName, playerName, ""));
            if (!actionAcceptanceCooperation && !ReadBool(llm, "visibleRepairFailure", false))
                llm = WithDiagnosticTransformation("Negotiation and NPC agency", llm, () => EnforceConversationAgencyResponse(llm, dialogueLlmRequest, motiveDecision, payload,
                    campaignId, correlationId, "dialogue", heroId, persist: !governmentCertificationMemoryIsolation,
                    validateRepair: candidate => ValidateAgencyRepairedResponse(candidate, motiveDecision, payload, identityView, priorLines, heroId, heroName, playerName)));
            if (ReadBool(ReadDictionary(llm, "conversationAgency"), "replayed", false)) return ConversationAgencyReplayResponse(llm, heroId);
            RecordCodexFinalRepairEvidence(llm);
            llmMs = phaseTimer.ElapsedMilliseconds;
            if (!ReadBool(llm, "ok", false))
            {
                totalTimer.Stop();
                Dictionary<string, object> failedTiming = WithNpcRelationshipTiming(
                    DialogueTiming(totalTimer.ElapsedMilliseconds, upsertMs,
                        constructionMs, contextLoadMs, promptBuildMs, llmMs,
                        ReadLong(llm, "durationMs", 0), parseMs, storageMs),
                    npcRelationshipContextMs, npcRelationshipPrompt);
                LogOperational("dialogue.respond_failed", new Dictionary<string, object>
                {
                    ["campaignId"] = campaignId,
                    ["heroStringId"] = heroId,
                    ["stage"] = "llm",
                    ["timing"] = failedTiming,
                    ["llm"] = llm
                });
                WriteAudit(campaignId, correlationId, "server", "dialogue", "dialogue.response", heroId, "", "", "failed", totalTimer.ElapsedMilliseconds, "Dialogue response failed during LLM call.", new Dictionary<string, object>
                {
                    ["stage"] = "llm",
                    ["timing"] = failedTiming,
                    ["llm"] = llm
                });
                return new Dictionary<string, object>
                {
                    ["ok"] = false,
                    ["stage"] = "llm",
                    ["error"] = LlmFailureForDisplay(llm),
                    ["llm"] = llm,
                    ["timing"] = failedTiming
                };
            }

            phaseTimer.Restart();
            string content = ReadString(llm, "content", "");
            Dictionary<string, object> parsed = TryParseJsonObject(content);
            bool agencyVisibleFailure = ReadBool(ReadDictionary(llm, "conversationAgency"), "visibleFailure", false)
                || ReadBool(llm, "visibleRepairFailure", false);
            string reply = ReadFirstString(parsed, "reply", "response", "text", "content");
            if (string.IsNullOrWhiteSpace(reply))
            {
                reply = ExtractVisibleReply(content);
            }

            if (string.IsNullOrWhiteSpace(reply))
            {
                reply = "[Bannerlord Reign: the model returned malformed JSON, so the visible reply was hidden. Please try again.]";
            }
            if (courtLifeAudience && (reply.StartsWith("[Bannerlord Reign:", StringComparison.Ordinal)
                || ReignRulerDocketRules.ContainsForbiddenNobleDocketStatistics(reply)))
                return new Dictionary<string, object> { ["ok"] = false,
                    ["error"] = "The court guest returned an invalid response. The audience can be retried.",
                    ["courtLifeInvalidReply"] = true };
            reply = SanitizeVisibleReply(reply);
            reply = RemoveSpokenNumericSkillLevels(reply, out bool skillNumericRepairApplied);
            bool nobleDocketMechanicalRepairApplied = false;
            if (string.Equals(ReadString(payload, "conversationMode", ""),
                    "noble_docket", StringComparison.OrdinalIgnoreCase)
                && ReignRulerDocketRules.ContainsForbiddenNobleDocketStatistics(reply))
            {
                reply = "I will speak only to the merits of this dispute and to what honor requires.";
                nobleDocketMechanicalRepairApplied = true;
            }
            reply = SanitizePromptForIdentity(reply, "", playerName, identityView);
            reply = NormalizeUnknownIdentityVisibleAddress(reply, identityView);
            List<Dictionary<string, object>> recallConsistencyRepairs;
            reply = RepairVisibleExactRecallIdentifiers(playerText, reply, parsed, messages, out recallConsistencyRepairs);
            if (!governmentCertificationMemoryIsolation && !agencyVisibleFailure)
                reply = ApplyConversationDrinking(campaignId, heroId, payload, profile, characteristics, parsed, reply);
            Dictionary<string, object> conversationSceneResolution = FinalizeConversationSceneState(
                campaignId, payload, heroId, playerText, reply, ReadString(payload, "mode", "dialogue"), parsed);

            long ts = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
            string decisionId = Guid.NewGuid().ToString("N");
            string emotion = parsed == null ? "" : ReadString(parsed, "emotion", "");
            string intent = parsed == null ? "" : ReadString(parsed, "intent", "");
            string relationshipSignal = parsed == null ? "" : ReadFirstString(parsed, "relationshipSignal", "relationship_signal");
            List<Dictionary<string, object>> relationshipAssessments = NormalizeConversationRelationshipAssessments(
                parsed, payload, heroId, relationshipSignal,
                FirstNonEmpty(ReadFirstString(payload, "playerHeroStringId", "playerId", "mainHeroStringId"), ReadFirstString(profile, "mainHeroStringId", "playerHeroStringId")),
                ReadString(payload, "sceneTurnId", ""));
            if (agencyVisibleFailure) relationshipAssessments.Clear();
            Dictionary<string, object> actionGate = NormalizeActionGate(parsed == null ? null : ReadDictionary(parsed, "actionGate") ?? ReadDictionary(parsed, "action_gate"), playerText, reply);
            bool actionAcceptanceGateRepaired = EnforceActionAcceptanceCooperationGate(
                actionAcceptanceCooperation, actionGate, playerText, ref reply);
            Dictionary<string, object> chancellorDecision = NormalizeChancellorDecision(
                parsed, payload, playerText, reply, correlationId);
            Dictionary<string, object> nobleDocketTurn = NormalizeNobleDocketTurn(
                parsed, payload, reply);
            Dictionary<string, object> conceptionGate = NormalizeConceptionGate(
                parsed == null ? null : ReadDictionary(parsed, "conceptionGate") ?? ReadDictionary(parsed, "conception_gate"),
                reply,
                playerPromptLabel == "pull_out" || ReadBool(payload, "suppressConceptionGate", false));
            string socialPlayerId = FirstNonEmpty(ReadFirstString(payload, "playerHeroStringId", "playerId", "mainHeroStringId"),
                ReadFirstString(profile, "mainHeroStringId", "playerHeroStringId"));
            double socialWorldDay = ReadDouble(payload, "worldDay", 0d);
            Dictionary<string, object> socialSignalValidation =
                ShouldPersistGovernmentCertificationConversationSideEffects(
                    governmentCertificationMemoryIsolation)
                    && !actionAcceptanceCooperation
                    ? NormalizeAndPersistConversationSocialSignals(
                        campaignId, parsed, payload, heroId, socialPlayerId,
                        playerText, reply, conceptionGate, decisionId,
                        socialWorldDay)
                    : new Dictionary<string, object>
                    {
                        ["ok"] = true,
                        ["timelineId"] = ReadString(payload, "timelineId", "main"),
                        ["signals"] = new List<Dictionary<string, object>>(),
                        ["rejected"] = new List<Dictionary<string, object>>(),
                        ["suppressed"] = true,
                        ["reason"] = actionAcceptanceCooperation
                            ? "action_acceptance_cooperation"
                            : "government_certification_memory_isolation"
                    };
            Dictionary<string, object> decisionBrief = AugmentDecisionBriefWithMotiveEvidence(NormalizeDecisionBrief(parsed, intent, actionGate), motiveDecision);
            RemovePrivateReasoningFields(parsed);
            List<Dictionary<string, object>> memoryWrites = parsed == null ? new List<Dictionary<string, object>>() : NormalizeMemoryWrites(parsed.ContainsKey("memoryWrites") ? parsed["memoryWrites"] : null, campaignId, heroId, ts);
            List<Dictionary<string, object>> beliefWrites = parsed == null ? new List<Dictionary<string, object>>() : ReadDictionaryList(parsed, "beliefWrites").Concat(ReadDictionaryList(parsed, "belief_writes")).ToList();
            List<Dictionary<string, object>> relationshipUpdates = parsed == null ? new List<Dictionary<string, object>>() : ReadDictionaryList(parsed, "relationshipUpdates").Concat(ReadDictionaryList(parsed, "relationship_updates")).ToList();
            List<Dictionary<string, object>> obligationWrites = parsed == null ? new List<Dictionary<string, object>>() : ReadDictionaryList(parsed, "obligationWrites").Concat(ReadDictionaryList(parsed, "obligation_writes")).ToList();
            List<Dictionary<string, object>> comprehensionWrites = parsed == null ? new List<Dictionary<string, object>>() : ReadDictionaryList(parsed, "comprehensionWrites").Concat(ReadDictionaryList(parsed, "comprehension_writes")).ToList();
            List<Dictionary<string, object>> dynamicCharacteristicWrites = NormalizeDynamicCharacteristicWrites(parsed, heroId, profile, payload, reply);
            if (agencyVisibleFailure) dynamicCharacteristicWrites.Clear();
            List<Dictionary<string, object>> roleWriteRejections = new List<Dictionary<string, object>>();
            memoryWrites = FilterConversationRoleMisattributions(memoryWrites, payload, playerText, "memory", roleWriteRejections);
            beliefWrites = FilterConversationRoleMisattributions(beliefWrites, payload, playerText, "belief", roleWriteRejections);
            obligationWrites = FilterConversationRoleMisattributions(obligationWrites, payload, playerText, "obligation", roleWriteRejections);
            comprehensionWrites = FilterConversationRoleMisattributions(comprehensionWrites, payload, playerText, "comprehension", roleWriteRejections);
            memoryWrites = FilterRoleplayFeedbackWrites(memoryWrites, "memory", roleWriteRejections);
            beliefWrites = FilterRoleplayFeedbackWrites(beliefWrites, "belief", roleWriteRejections);
            obligationWrites = FilterRoleplayFeedbackWrites(obligationWrites, "obligation", roleWriteRejections);
            comprehensionWrites = FilterRoleplayFeedbackWrites(comprehensionWrites, "comprehension", roleWriteRejections);
            Dictionary<string, object> stateUpdates = parsed == null
                ? new Dictionary<string, object>()
                : NormalizeSafeConversationStateUpdates(
                    ReadDictionary(parsed, "stateUpdates") ?? ReadDictionary(parsed, "state_updates"),
                    roleWriteRejections);
            Dictionary<string, object> politicalRiskPosture =
                ReadDictionary(motiveDecision, "politicalRiskPosture")
                ?? new Dictionary<string, object>();
            Dictionary<string, object> pendingAddressConvention =
                ReadDictionary(politicalRiskPosture,
                    "pendingAddressConvention");
            if (pendingAddressConvention != null
                && pendingAddressConvention.Count > 0)
                stateUpdates["politicalAddressConvention"] =
                    CloneDictionary(pendingAddressConvention);
            Dictionary<string, object> politicalConduct =
                ReadDictionary(parsed, "politicalConduct")
                ?? new Dictionary<string, object>();
            bool recallOnlyTurn = IsPureConversationRecallRequest(playerText);
            if (recallOnlyTurn)
            {
                // A recall answer is a reconstruction, not a new source of world facts. Keep the
                // verbatim turn, but do not let a mistaken reconstruction recursively become a
                // durable memory, belief, rumor, obligation, or comprehension record.
                memoryWrites.Clear();
                beliefWrites.Clear();
                obligationWrites.Clear();
                comprehensionWrites.Clear();
                dynamicCharacteristicWrites.Clear();
            }
            if (!ShouldPersistGovernmentCertificationConversationSideEffects(
                    governmentCertificationMemoryIsolation)
                || actionAcceptanceCooperation)
            {
                // Certification conversations must behave like ordinary dialogue
                // for visible prose and accepted native actions, but one case must
                // never teach a later case that this NPC already promised, refused,
                // bargained, or adopted a new personal plan.
                memoryWrites.Clear();
                beliefWrites.Clear();
                relationshipUpdates.Clear();
                relationshipAssessments.Clear();
                obligationWrites.Clear();
                comprehensionWrites.Clear();
                dynamicCharacteristicWrites.Clear();
                stateUpdates.Clear();
            }
            List<Dictionary<string, object>> suggestedActions = parsed == null ? new List<Dictionary<string, object>>() : NormalizeSuggestedActions(parsed.ContainsKey("suggestedActions") ? parsed["suggestedActions"] : null, compactActionCatalog);
            List<Dictionary<string, object>> identityIntroductionResults = ApplyIdentityIntroductionWrites(campaignId, payload, parsed, ReadFirstString(payload, "conversationSessionId", "sessionId", "conversationId"));
            WriteAudit(campaignId, correlationId, "server", "dialogue", "model.parsed", heroId, "", "", parsed == null ? "warning" : "completed", phaseTimer.ElapsedMilliseconds, parsed == null ? "Model response was not valid JSON; visible reply fallback was used." : "Dialogue model JSON parsed.", new Dictionary<string, object>
            {
                ["rawContent"] = content,
                ["parsed"] = parsed ?? new Dictionary<string, object>(),
                ["reply"] = reply,
                ["skillNumericRepairApplied"] = skillNumericRepairApplied,
                ["decisionBrief"] = decisionBrief,
                ["emotion"] = emotion,
                ["intent"] = intent,
                ["relationshipSignal"] = relationshipSignal,
                ["relationshipAssessments"] = relationshipAssessments,
                ["actionGate"] = actionGate,
                ["actionAcceptanceGateRepaired"] = actionAcceptanceGateRepaired,
                ["chancellorDecision"] = chancellorDecision,
                ["nobleDocketTurn"] = nobleDocketTurn,
                ["nobleDocketMechanicalRepairApplied"] = nobleDocketMechanicalRepairApplied,
                ["conceptionGate"] = conceptionGate,
                ["socialSignalValidation"] = socialSignalValidation,
                ["identityView"] = identityView,
                ["memoryWrites"] = memoryWrites,
                ["beliefWrites"] = beliefWrites,
                ["relationshipUpdates"] = relationshipUpdates,
                ["obligationWrites"] = obligationWrites,
                ["comprehensionWrites"] = comprehensionWrites,
                ["dynamicCharacteristicWrites"] = dynamicCharacteristicWrites,
                ["roleWriteRejections"] = roleWriteRejections,
                ["recallWriteSuppressed"] = recallOnlyTurn,
                ["recallConsistencyRepairs"] = recallConsistencyRepairs,
                ["stateUpdates"] = stateUpdates,
                ["politicalRiskPosture"] = politicalRiskPosture,
                ["politicalConduct"] = politicalConduct,
                ["politicalConductEnforcement"] = ReadDictionary(
                    llm, "politicalConductEnforcement")
                    ?? new Dictionary<string, object>(),
                ["suggestedActions"] = suggestedActions,
                ["identityIntroductionResults"] = identityIntroductionResults
                ,["conversationSceneState"] = conversationSceneState
                ,["conversationSceneResolution"] = conversationSceneResolution
            });
            List<string> testDirectiveErrors = new List<string>();
            List<Dictionary<string, object>> queuedTestDirectiveActions = new List<Dictionary<string, object>>();
            List<string> dialogueActionErrors = new List<string>();
            List<Dictionary<string, object>> queuedDialogueActions = new List<Dictionary<string, object>>();
            string actionShadowPreview = "";
            ApplyAgencyRelationshipAssessment(relationshipAssessments, payload, heroId, socialPlayerId);
            if (ShouldRouteGuardedPromptOverrideActions(isTestDirective,
                    governmentCertificationMemoryIsolation,
                    actionAcceptanceCooperation))
            {
                memoryWrites.Clear();
                beliefWrites.Clear();
                relationshipUpdates.Clear();
                relationshipAssessments.Clear();
                obligationWrites.Clear();
                comprehensionWrites.Clear();
                dynamicCharacteristicWrites.Clear();
                stateUpdates.Clear();
                queuedTestDirectiveActions = QueueTestDirectiveActions(campaignId, payload, hero, testDirectiveText, suggestedActions, out testDirectiveErrors);
                string statusLine = queuedTestDirectiveActions.Count > 0
                    ? "[Bannerlord Reign prompt override queued: " + string.Join(", ", queuedTestDirectiveActions.Select(x => ReadString(x, "command", "")).Where(x => !string.IsNullOrWhiteSpace(x))) + ".]"
                    : "[Bannerlord Reign prompt override did not queue an action: " + string.Join("; ", testDirectiveErrors.DefaultIfEmpty("No matching action command was found.")) + "]";
                reply = string.IsNullOrWhiteSpace(reply) || reply == "..." ? statusLine : reply + "\n\n" + statusLine;
            }
            else if (!rulerPetitionAudience && !nobleDocketAudience && !courtLifeAudience)
            {
                if (!agencyVisibleFailure)
                {
                    using (ReserveGovernmentPaymentOwnership(payload, parsed, playerText, reply))
                    {
                        queuedDialogueActions = QueueAcceptedDialogueActions(campaignId, payload, hero, playerText, reply, actionGate, suggestedActions, out dialogueActionErrors);
                    }
                    if (IsTemporaryPartyGuestLifecycleConversation(actionGate, playerText,
                            queuedDialogueActions))
                    {
                        // Temporary guest negotiations are deliberately relationship-neutral.
                        // This covers the conditional consent turns that precede the final
                        // accepted action as well as the action-queuing turn itself.
                        relationshipAssessments.Clear();
                        relationshipUpdates.Clear();
                        ApplyAgencyRelationshipAssessment(relationshipAssessments, payload, heroId, socialPlayerId);
                    }
                    string campaignCommandDraftReply = ReadString(payload, "campaignCommandDraftReply", "");
                    if (!string.IsNullOrWhiteSpace(campaignCommandDraftReply))
                        reply = campaignCommandDraftReply;
                    if (queuedDialogueActions.Count > 0)
                    {
                        string statusLine = "[Bannerlord Reign action queued: " + string.Join(", ", queuedDialogueActions.Select(x => ReadString(x, "command", "")).Where(x => !string.IsNullOrWhiteSpace(x))) + ".]";
                        reply = string.IsNullOrWhiteSpace(reply) || reply == "..." ? statusLine : reply + "\n\n" + statusLine;
                    }
                }
            }

            if (HasUnconfirmedMarriageClaim(reply, payload, hero))
            {
                memoryWrites.Clear();
                beliefWrites.Clear();
                comprehensionWrites.Clear();
                relationshipAssessments.Clear();
                relationshipUpdates.Clear();
                obligationWrites.Clear();
                dynamicCharacteristicWrites.Clear();
                stateUpdates.Clear();
            }
            reply = FinalizeDialogueActionOutcome(reply, payload, hero, queuedDialogueActions, dialogueActionErrors);
            actionShadowPreview = BuildActionShadowPreview(queuedTestDirectiveActions, queuedDialogueActions, testDirectiveErrors, dialogueActionErrors);
            Dictionary<string, object> playerLine = DialogueLine(ts, "player", playerName, playerText);
            Dictionary<string, object> npcLine = DialogueLine(ts, "npc", heroName, reply);
            if (officialAmbassador)
            {
                Dictionary<string, object> officialContext = ReadDictionary(payload, "ambassadorContext") ?? new Dictionary<string, object>();
                foreach (Dictionary<string, object> line in new[] { playerLine, npcLine })
                {
                    line["channel"] = "ambassador_official";
                    line["postingId"] = ReadString(officialContext, "postingId", "");
                    line["representedKingdomId"] = ReadString(officialContext, "representedKingdomId", "");
                    line["representedRulerId"] = ReadString(officialContext, "representedRulerId", "");
                    line["officialRelay"] = true;
                }
            }
            parseMs = phaseTimer.ElapsedMilliseconds;

            phaseTimer.Restart();
            string dialoguePlayerId = socialPlayerId;
            Dictionary<string, object> socialExchangePayload = new Dictionary<string, object>(payload, StringComparer.OrdinalIgnoreCase)
            {
                ["socialSignals"] = ReadDictionaryList(socialSignalValidation, "signals")
            };
            Dictionary<string, object> conversationExchange = StoreConversationExchange(campaignId, socialExchangePayload, heroId, dialoguePlayerId,
                playerName, heroName, playerText, reply, decisionId, ts);
            string conversationSessionId = ReadString(conversationExchange, "sessionId", "");
            double dialogueWorldDay = ReadDouble(payload, "worldDay", 0d);
            Dictionary<string, object> immediateSocialIncidents = ProcessImmediatePlayerIntimacySignals(
                campaignId, ReadString(socialSignalValidation, "timelineId", "main"),
                conversationSessionId, ReadDictionaryList(socialSignalValidation, "signals"), dialogueWorldDay);
            string dialogueLocationId = FirstNonEmpty(ReadFirstString(payload, "locationId", "currentSettlementId", "settlementId"), ReadFirstString(profile, "currentSettlementId", "settlementId"));
            playerLine["sessionId"] = conversationSessionId;
            playerLine["exchangeId"] = decisionId;
            playerLine["worldDay"] = dialogueWorldDay;
            playerLine["locationId"] = dialogueLocationId;
            npcLine["sessionId"] = conversationSessionId;
            npcLine["exchangeId"] = decisionId;
            npcLine["worldDay"] = dialogueWorldDay;
            npcLine["locationId"] = dialogueLocationId;
            Dictionary<string, object> ambassadorDecision = officialAmbassador
                ? PersistOfficialAmbassadorDecision(campaignId, payload, conversationExchange, ts)
                : new Dictionary<string, object>();
            if (officialAmbassador)
                RecordOfficialAmbassadorExchange(campaignId, payload, heroId, dialoguePlayerId, playerLine, npcLine, conversationExchange, ts);
            AppendJsonLineToPath(CharacterFile(campaignId, heroId, "history", "dialogue.jsonl"), playerLine);
            AppendJsonLineToPath(CharacterFile(campaignId, heroId, "history", "dialogue.jsonl"), npcLine);
            foreach (Dictionary<string, object> memoryWrite in memoryWrites)
            {
                AppendJsonLineToPath(CharacterFile(campaignId, heroId, "memory", "memories.jsonl"), memoryWrite);
            }

            Dictionary<string, object> dynamicCharacteristicsStore = StoreDynamicCharacteristicWrites(
                campaignId, heroId, dynamicCharacteristicWrites, payload, conversationExchange,
                decisionId, "dialogue", dialogueLocationId, ts, new[] { heroId, dialoguePlayerId });

            string memoryGroupKey = BuildMemoryGroupKey(new Dictionary<string, object>(payload, StringComparer.OrdinalIgnoreCase)
            {
                ["memoryGroupKey"] = string.IsNullOrWhiteSpace(conversationSessionId) ? ReadFirstString(payload, "memoryGroupKey", "memory_group_key") : "conversation:" + conversationSessionId
            }, heroId, dialoguePlayerId, dialogueLocationId, "conversation", ts);
            Dictionary<string, object> memoryLayerStore = StoreTurnMemoryLayers(
                campaignId, decisionId, "dialogue_turn", heroId, dialoguePlayerId, dialogueLocationId,
                playerText, reply, memoryWrites, beliefWrites, relationshipUpdates,
                obligationWrites, comprehensionWrites, memoryGroupKey, ts,
                sharedParticipants: null,
                retrievalEligible: !recallOnlyTurn
                    && ShouldPersistGovernmentCertificationConversationSideEffects(
                        governmentCertificationMemoryIsolation),
                continuityPayload: payload,
                continuityWrites: actionAcceptanceCooperation ? null : ReadDictionaryList(parsed, "continuityWrites"));
            if (ShouldPersistGovernmentCertificationConversationSideEffects(
                    governmentCertificationMemoryIsolation))
                UpdateSharedGroupConversationState(campaignId, payload, heroId,
                    heroName, reply, conversationSessionId, ts);
            Dictionary<string, object> motiveOutcome =
                ShouldPersistGovernmentCertificationConversationSideEffects(
                    governmentCertificationMemoryIsolation)
                    ? ApplyConversationMotiveOutcome(campaignId, motiveDecision,
                        payload, reply, intent, decisionId, decisionBrief)
                    : new Dictionary<string, object>
                    {
                        ["suppressed"] = true,
                        ["reason"] = "government_certification_memory_isolation"
                    };

            if (stateUpdates.Count > 0)
            {
                MergeCharacterState(campaignId, heroId, stateUpdates);
            }

            AppendJsonLineToPath(CharacterFile(campaignId, heroId, "history", "decisions.jsonl"), new Dictionary<string, object>
            {
                ["id"] = decisionId,
                ["ts"] = ts,
                ["campaignId"] = campaignId,
                ["heroStringId"] = heroId,
                ["playerName"] = playerName,
                ["heroName"] = heroName,
                ["playerText"] = playerText,
                ["reply"] = reply,
                ["decisionBrief"] = decisionBrief,
                ["motiveDecision"] = motiveDecision,
                ["motiveOutcome"] = motiveOutcome,
                ["emotion"] = emotion,
                ["intent"] = intent,
                ["relationshipSignal"] = relationshipSignal,
                ["relationshipAssessments"] = relationshipAssessments,
                ["actionGate"] = actionGate,
                ["chancellorDecision"] = chancellorDecision,
                ["nobleDocketTurn"] = nobleDocketTurn,
                ["nobleDocketMechanicalRepairApplied"] = nobleDocketMechanicalRepairApplied,
                ["conceptionGate"] = conceptionGate,
                ["identityView"] = identityView,
                ["memoryWrites"] = memoryWrites,
                ["beliefWrites"] = beliefWrites,
                ["relationshipUpdates"] = relationshipUpdates,
                ["obligationWrites"] = obligationWrites,
                ["comprehensionWrites"] = comprehensionWrites,
                ["dynamicCharacteristicWrites"] = dynamicCharacteristicWrites,
                ["dynamicCharacteristicsStore"] = dynamicCharacteristicsStore,
                ["recallConsistencyRepairs"] = recallConsistencyRepairs,
                ["stateUpdates"] = stateUpdates,
                ["suggestedActions"] = suggestedActions,
                ["memoryLayerStore"] = memoryLayerStore,
                ["conversationExchange"] = conversationExchange,
                ["socialSignals"] = ReadDictionaryList(socialSignalValidation, "signals"),
                ["rejectedSocialSignals"] = ReadDictionaryList(socialSignalValidation, "rejected"),
                ["immediateSocialIncidents"] = immediateSocialIncidents,
                ["ambassadorDecision"] = ambassadorDecision,
                ["testDirective"] = isTestDirective,
                ["testDirectiveText"] = isTestDirective ? testDirectiveText : "",
                ["guardedPromptOverride"] = guardedPromptOverrideEvidence,
                ["actionAcceptanceGateRepaired"] = actionAcceptanceGateRepaired,
                ["queuedTestDirectiveActions"] = queuedTestDirectiveActions,
                ["queuedDialogueActions"] = queuedDialogueActions,
                ["testDirectiveErrors"] = testDirectiveErrors,
                ["dialogueActionErrors"] = dialogueActionErrors,
                ["identityIntroductionResults"] = identityIntroductionResults
                ,["conversationSceneState"] = conversationSceneState
                ,["conversationSceneResolution"] = conversationSceneResolution
            });
            storageMs = phaseTimer.ElapsedMilliseconds;
            totalTimer.Stop();
            Dictionary<string, object> timing = WithNpcRelationshipTiming(
                DialogueTiming(totalTimer.ElapsedMilliseconds, upsertMs,
                    constructionMs, contextLoadMs, promptBuildMs, llmMs,
                    ReadLong(llm, "durationMs", 0), parseMs, storageMs),
                npcRelationshipContextMs, npcRelationshipPrompt);
            timing["promptChars"] = promptEnvelope.TotalChars;
            timing["contextBundleCount"] = contextBundles.Count;
            timing["contextBundleChars"] = Json.Serialize(contextBundles).Length;
            timing["selectedContextPullCount"] = selectedContextPulls.Count;
            string encyclopediaText = BuildEncyclopediaBackstoryText(campaignId, heroId);

            List<Dictionary<string, object>> lines = new List<Dictionary<string, object>>(priorLines);
            lines.Add(playerLine);
            lines.Add(npcLine);
            Dictionary<string, object> response = new Dictionary<string, object>
            {
                ["ok"] = true,
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["heroStringId"] = heroId,
                ["reply"] = reply,
                ["identityView"] = identityView,
                ["emotion"] = emotion,
                ["intent"] = intent,
                ["relationshipSignal"] = relationshipSignal,
                ["relationshipAssessments"] = relationshipAssessments,
                ["decisionBrief"] = decisionBrief,
                ["motiveDecision"] = motiveDecision,
                ["motiveOutcome"] = motiveOutcome,
                ["actionGate"] = actionGate,
                ["chancellorDecision"] = chancellorDecision,
                ["nobleDocketTurn"] = nobleDocketTurn,
                ["conceptionGate"] = conceptionGate,
                ["memoryWrites"] = memoryWrites,
                ["beliefWrites"] = beliefWrites,
                ["relationshipUpdates"] = relationshipUpdates,
                ["obligationWrites"] = obligationWrites,
                ["comprehensionWrites"] = comprehensionWrites,
                ["dynamicCharacteristicWrites"] = dynamicCharacteristicWrites,
                ["dynamicCharacteristicsStore"] = dynamicCharacteristicsStore,
                ["recallConsistencyRepairs"] = recallConsistencyRepairs,
                ["stateUpdates"] = stateUpdates,
                ["conversationSceneState"] = conversationSceneState,
                ["conversationSceneResolution"] = conversationSceneResolution,
                ["suggestedActions"] = suggestedActions,
                ["testDirective"] = isTestDirective,
                ["testDirectiveText"] = isTestDirective ? testDirectiveText : "",
                ["guardedPromptOverride"] = guardedPromptOverrideEvidence,
                ["queuedTestDirectiveActions"] = queuedTestDirectiveActions,
                ["queuedDialogueActions"] = queuedDialogueActions,
                ["testDirectiveErrors"] = testDirectiveErrors,
                ["dialogueActionErrors"] = dialogueActionErrors,
                ["identityIntroductionResults"] = identityIntroductionResults,
                ["actionShadowPreview"] = actionShadowPreview,
                ["selectedContextPulls"] = selectedContextPulls,
                ["contextBundles"] = contextBundles,
                ["conversationExchange"] = conversationExchange,
                ["socialSignals"] = ReadDictionaryList(socialSignalValidation, "signals"),
                ["rejectedSocialSignals"] = ReadDictionaryList(socialSignalValidation, "rejected"),
                ["immediateSocialIncidents"] = immediateSocialIncidents,
                ["ambassadorDecision"] = ambassadorDecision,
                ["memoryLayerStore"] = memoryLayerStore,
                ["lines"] = lines,
                ["construction"] = construction,
                ["encyclopediaText"] = encyclopediaText,
                ["timing"] = timing
            };
            if (privateGovernmentChannel && ReadBool(ReadDictionary(payload, "governmentPrivateContext"), "enabled", false)
                && ReadDictionary(parsed, "governmentCommitment") != null)
                response["governmentCommitment"] = CloneDictionary(ReadDictionary(parsed, "governmentCommitment"));
            LogOperational("dialogue.respond", new Dictionary<string, object>
            {
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["heroStringId"] = heroId,
                ["decisionId"] = decisionId,
                ["playerChars"] = playerText.Length,
                ["replyChars"] = reply.Length,
                ["decisionBrief"] = decisionBrief,
                ["emotion"] = emotion,
                ["intent"] = intent,
                ["relationshipSignal"] = relationshipSignal,
                ["actionGate"] = actionGate,
                ["conceptionGate"] = conceptionGate,
                ["memoryWriteCount"] = memoryWrites.Count,
                ["dynamicCharacteristicWriteCount"] = dynamicCharacteristicWrites.Count,
                ["dynamicCharacteristicStoredCount"] = ReadInt(dynamicCharacteristicsStore, "storedCount", 0),
                ["recallConsistencyRepairCount"] = recallConsistencyRepairs.Count,
                ["stateUpdateCount"] = stateUpdates.Count,
                ["suggestedActionCount"] = suggestedActions.Count,
                ["testDirective"] = isTestDirective,
                ["guardedPromptOverride"] = guardedPromptOverrideEvidence,
                ["testDirectiveQueuedActionCount"] = queuedTestDirectiveActions.Count,
                ["testDirectiveErrors"] = testDirectiveErrors,
                ["dialogueQueuedActionCount"] = queuedDialogueActions.Count,
                ["dialogueActionErrors"] = dialogueActionErrors,
                ["actionShadowPreview"] = actionShadowPreview,
                ["selectedContextPulls"] = selectedContextPulls.Select(x => ReadString(x, "id", "")).ToList(),
                ["contextBundleCount"] = contextBundles.Count,
                ["contextBundleChars"] = Json.Serialize(contextBundles).Length,
                ["timing"] = timing
            });
            WriteAudit(campaignId, correlationId, "server", "dialogue", "dialogue.response", heroId, "", "", "completed", totalTimer.ElapsedMilliseconds, "Dialogue response completed.", new Dictionary<string, object>
            {
                ["decisionId"] = decisionId,
                ["playerLine"] = playerLine,
                ["npcLine"] = npcLine,
                ["reply"] = reply,
                ["identityView"] = identityView,
                ["decisionBrief"] = decisionBrief,
                ["actionGate"] = actionGate,
                ["conceptionGate"] = conceptionGate,
                ["memoryWrites"] = memoryWrites,
                ["beliefWrites"] = beliefWrites,
                ["relationshipUpdates"] = relationshipUpdates,
                ["obligationWrites"] = obligationWrites,
                ["comprehensionWrites"] = comprehensionWrites,
                ["dynamicCharacteristicWrites"] = dynamicCharacteristicWrites,
                ["dynamicCharacteristicsStore"] = dynamicCharacteristicsStore,
                ["recallConsistencyRepairs"] = recallConsistencyRepairs,
                ["stateUpdates"] = stateUpdates,
                ["suggestedActions"] = suggestedActions,
                ["guardedPromptOverride"] = guardedPromptOverrideEvidence,
                ["queuedTestDirectiveActions"] = queuedTestDirectiveActions,
                ["queuedDialogueActions"] = queuedDialogueActions,
                ["testDirectiveErrors"] = testDirectiveErrors,
                ["dialogueActionErrors"] = dialogueActionErrors,
                ["actionShadowPreview"] = actionShadowPreview,
                ["timing"] = timing
            });
            ScheduleReplayCorpusCapture(campaignId, correlationId);
            if (!string.IsNullOrWhiteSpace(dialogueAuditRunId))
            {
                SaveNpcDialogueAuditResponse(campaignId, correlationId, response);
            }
            RecordCodexFinalizedContract(parsed, response);
            return response;
        }

        private static Dictionary<string, object> DialogueTiming(long totalMs, long upsertMs, long constructionMs, long contextLoadMs, long promptBuildMs, long llmMs, long llmProviderMs, long parseMs, long storageMs)
        {
            return new Dictionary<string, object>
            {
                ["totalMs"] = totalMs,
                ["characterUpsertMs"] = upsertMs,
                ["characterConstructionMs"] = constructionMs,
                ["contextLoadMs"] = contextLoadMs,
                ["promptBuildMs"] = promptBuildMs,
                ["llmCallMs"] = llmMs,
                ["llmProviderMs"] = llmProviderMs,
                ["parseMs"] = parseMs,
                ["storageMs"] = storageMs
            };
        }

        private static Dictionary<string, object> WithNpcRelationshipTiming(
            Dictionary<string, object> timing,
            long totalMs,
            Dictionary<string, object> npcRelationshipPrompt)
        {
            timing = timing ?? new Dictionary<string, object>();
            Dictionary<string, object> relationshipTiming =
                NpcRelationshipTiming(totalMs, npcRelationshipPrompt);
            timing["npcRelationshipContextMs"] = totalMs;
            timing["npcRelationshipProviderMs"] =
                ReadLong(relationshipTiming, "providerMs", 0);
            timing["npcRelationshipProviderCallCount"] =
                ReadInt(relationshipTiming, "providerCallCount", 0);
            timing["npcRelationshipGeneratedCount"] =
                ReadInt(relationshipTiming, "generatedCount", 0);
            timing["npcRelationshipReusedCount"] =
                ReadInt(relationshipTiming, "reusedCount", 0);
            return timing;
        }

        private static Dictionary<string, object> NpcRelationshipTiming(
            long totalMs,
            Dictionary<string, object> npcRelationshipPrompt)
        {
            Dictionary<string, object> generation =
                ReadDictionary(npcRelationshipPrompt, "historyGeneration")
                ?? new Dictionary<string, object>();
            return new Dictionary<string, object>
            {
                ["totalMs"] = totalMs,
                ["providerMs"] = ReadLong(generation, "providerDurationMs", 0),
                ["providerCallCount"] = ReadInt(generation, "providerCallCount", 0),
                ["generatedCount"] = ReadInt(generation, "generatedCount", 0),
                ["reusedCount"] = ReadInt(generation, "reusedCount", 0),
                ["fallbackCount"] = ReadInt(generation, "fallbackCount", 0)
            };
        }

        private static Dictionary<string, object> SocialEventStart(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            string correlationId = EnsureCorrelationId(payload);
            string campaignId = ReadString(payload, "campaignId", "default");
            string eventId = ReadFirstString(payload, "eventId", "socialEventId");
            if (string.IsNullOrWhiteSpace(eventId))
            {
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "eventId is required." };
            }

            List<Dictionary<string, object>> attendees = ReadDictionaryList(payload, "attendees");
            SaveTestSnapshotFromPayload(campaignId, correlationId, "social_event", "event.start", payload);
            foreach (Dictionary<string, object> attendee in attendees)
            {
                if (attendee != null)
                {
                    UpsertCharacterProfile(campaignId, attendee);
                }
            }

            Dictionary<string, object> row = EventTranscriptLine("system", "Event", "Started " + ReadString(payload, "displayName", "social event") + ".", payload);
            AppendJsonLineToPath(SocialEventTranscriptFile(campaignId, eventId), row);
            AppendEventLineForAttendees(campaignId, attendees, row);
            WriteAudit(campaignId, correlationId, "game_client", "social_event", "event.start", "", "", eventId, "completed", 0, "Social event started.", new Dictionary<string, object>
            {
                ["event"] = payload,
                ["attendeeCount"] = attendees.Count,
                ["transcriptLine"] = row
            });
            LogOperational("social_event.start", new Dictionary<string, object>
            {
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["eventId"] = eventId,
                ["templateId"] = ReadString(payload, "templateId", ""),
                ["attendeeCount"] = attendees.Count
            });

            return new Dictionary<string, object> { ["ok"] = true, ["campaignId"] = campaignId, ["correlationId"] = correlationId, ["eventId"] = eventId, ["attendeeCount"] = attendees.Count };
        }

        private static Dictionary<string, object> SocialEventResolve(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            string correlationId = EnsureCorrelationId(payload);
            string campaignId = ReadString(payload, "campaignId", "default");
            string eventId = ReadFirstString(payload, "eventId", "socialEventId");
            if (string.IsNullOrWhiteSpace(eventId))
            {
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "eventId is required." };
            }

            Dictionary<string, object> row = EventTranscriptLine("system", "Event", "Resolved " + ReadString(payload, "displayName", "social event") + ".", payload);
            SaveTestSnapshotFromPayload(campaignId, correlationId, "social_event", "event.resolve", payload);
            AppendJsonLineToPath(SocialEventTranscriptFile(campaignId, eventId), row);
            AppendEventLineForAttendees(campaignId, ReadDictionaryList(payload, "attendees"), row);
            string conversationSessionId = "social_event_" + SafeMemoryKey(eventId);
            Dictionary<string, object> conversationFinish = FinishConversationSession(campaignId, conversationSessionId,
                "social_event_resolved", false, ReadDouble(payload, "worldDay", 0d), DateTimeOffset.UtcNow.ToUnixTimeSeconds());
            WriteAudit(campaignId, correlationId, "game_client", "social_event", "event.resolve", "", "", eventId, "completed", 0, "Social event resolved.", new Dictionary<string, object>
            {
                ["event"] = payload,
                ["transcriptLine"] = row
            });
            LogOperational("social_event.resolve", new Dictionary<string, object>
            {
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["eventId"] = eventId,
                ["templateId"] = ReadString(payload, "templateId", "")
            });

            return new Dictionary<string, object>
            {
                ["ok"] = true, ["campaignId"] = campaignId, ["correlationId"] = correlationId, ["eventId"] = eventId,
                ["conversationSessionId"] = conversationSessionId, ["conversationFinish"] = conversationFinish
            };
        }

        private static Dictionary<string, object> SocialEventHistory(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", "default");
            string eventId = ReadFirstString(payload, "eventId", "socialEventId");
            int limit = Math.Max(1, ReadInt(payload, "limit", 80));
            if (string.IsNullOrWhiteSpace(eventId))
            {
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "eventId is required." };
            }

            List<Dictionary<string, object>> all = ReadJsonLinesFromPath(SocialEventTranscriptFile(campaignId, eventId));
            int start = Math.Max(0, all.Count - limit);
            return new Dictionary<string, object>
            {
                ["ok"] = true,
                ["campaignId"] = campaignId,
                ["eventId"] = eventId,
                ["lines"] = all.Skip(start).ToList()
            };
        }

        private static Dictionary<string, object> PartyChatHistory(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", "default");
            string sessionId = ReadFirstString(payload, "conversationSessionId", "sessionId");
            int limit = Math.Max(1, Math.Min(100, ReadInt(payload, "limit", 36)));
            if (string.IsNullOrWhiteSpace(sessionId))
            {
                return new Dictionary<string, object>
                {
                    ["ok"] = false,
                    ["error"] = "conversationSessionId is required."
                };
            }

            List<Dictionary<string, object>> all = ReadJsonLinesFromPath(
                PartyChatSessionTranscriptFile(campaignId, payload));
            int start = Math.Max(0, all.Count - limit);
            List<Dictionary<string, object>> lines = all.Skip(start).ToList();
            for (int index = 0; index < lines.Count; index++)
            {
                Dictionary<string, object> line = lines[index];
                line["sequence"] = index + 1;
                if (string.Equals(ReadString(line, "role", ""), "npc", StringComparison.OrdinalIgnoreCase))
                {
                    line["text"] = SanitizeVisibleReply(ReadString(line, "text", ""));
                }
            }

            return new Dictionary<string, object>
            {
                ["ok"] = true,
                ["campaignId"] = campaignId,
                ["conversationSessionId"] = sessionId,
                ["lines"] = lines
            };
        }

        private static Dictionary<string, object> SocialEventRespond(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            return RunCodexConversationScope(payload, () => SocialEventRespondCore(payload));
        }

        private static Dictionary<string, object> SocialEventRespondCore(Dictionary<string, object> payload)
        {
            Stopwatch totalTimer = Stopwatch.StartNew();
            Stopwatch phaseTimer = new Stopwatch();
            long upsertMs = 0;
            long contextLoadMs = 0;
            long promptBuildMs = 0;
            long llmMs = 0;
            long parseMs = 0;
            long storageMs = 0;
            long constructionMs = 0;
            long npcRelationshipContextMs = 0;
            Dictionary<string, object> npcRelationshipPrompt =
                new Dictionary<string, object>();
            Dictionary<string, object> construction = new Dictionary<string, object>();
            payload = payload ?? new Dictionary<string, object>();
            string correlationId = EnsureCorrelationId(payload);
            Dictionary<string, object> speaker = ReadDictionary(payload, "speaker") ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", ReadString(speaker, "campaignId", "default"));
            string eventId = ReadFirstString(payload, "eventId", "socialEventId");
            string auditMode = ReadString(payload, "mode", string.Equals(ReadString(payload, "templateId", ""), "party_chat", StringComparison.OrdinalIgnoreCase) ? "party_chat" : "social_event");
            bool partyChatRequest = string.Equals(auditMode, "party_chat", StringComparison.OrdinalIgnoreCase)
                || string.Equals(eventId, "party_chat", StringComparison.OrdinalIgnoreCase);
            string heroId = ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId", "characterId");
            if (string.IsNullOrWhiteSpace(heroId))
            {
                heroId = CharacterIdFrom(speaker);
            }

            ApplyPlayerInputAudienceToPayload(payload, heroId);

            string playerText = ReadFirstString(payload, "playerText", "text", "message");
            bool approachOpening = ReadBool(payload, "approachOpening", false)
                || string.Equals(ReadString(payload, "turnType", ""), "npc_approach_opening", StringComparison.OrdinalIgnoreCase);
            string promptTurnText = approachOpening
                ? "[EVENT CUE: You have just chosen to approach the player during this social-event phase. Speak first in character. Open naturally from your current motive, relationship, knowledge, and the supplied setting. Do not claim that the player said anything and do not invent a completed action.]"
                : playerText;
            if (string.IsNullOrWhiteSpace(eventId))
            {
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "eventId is required." };
            }

            if (string.IsNullOrWhiteSpace(heroId))
            {
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "speakerHeroStringId is required." };
            }

            if (string.IsNullOrWhiteSpace(playerText) && !approachOpening)
            {
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "playerText is required." };
            }

            SaveTestSnapshotFromPayload(campaignId, correlationId, auditMode, auditMode + ".request", payload);
            WriteAudit(campaignId, correlationId, "game_client", auditMode, auditMode + ".request", heroId, "", eventId, "started", 0, "Event response request received.", new Dictionary<string, object>
            {
                ["speaker"] = speaker,
                ["playerText"] = playerText,
                ["turnType"] = approachOpening ? "npc_approach_opening" : "player_reply",
                ["sceneContext"] = ReadString(payload, "sceneContext", ""),
                ["eventId"] = eventId,
                ["templateId"] = ReadString(payload, "templateId", ""),
                ["attendees"] = ReadDictionaryList(payload, "attendees"),
                ["selectedContextPulls"] = ReadDictionaryList(payload, "selectedContextPulls"),
                ["contextBundles"] = ReadDictionaryList(payload, "contextBundles"),
                ["actionResolutionIndex"] = ReadDictionary(payload, "actionResolutionIndex")
            });

            phaseTimer.Restart();
            List<Dictionary<string, object>> attendees = ReadDictionaryList(payload, "attendees");
            foreach (Dictionary<string, object> attendee in attendees)
            {
                if (attendee != null)
                {
                    UpsertCharacterProfile(campaignId, attendee);
                }
            }

            if (speaker.Count > 0)
            {
                if (!speaker.ContainsKey("heroStringId"))
                {
                    speaker["heroStringId"] = heroId;
                }

                UpsertCharacterProfile(campaignId, speaker);
            }
            upsertMs = phaseTimer.ElapsedMilliseconds;

            phaseTimer.Restart();
            construction = EnsureCharacterConstructed(campaignId, heroId, speaker, "social_event");
            constructionMs = phaseTimer.ElapsedMilliseconds;
            if (!IsCharacterConstructionReady(construction))
            {
                totalTimer.Stop();
                Dictionary<string, object> failedTiming = DialogueTiming(totalTimer.ElapsedMilliseconds, upsertMs, constructionMs, contextLoadMs, promptBuildMs, llmMs, 0, parseMs, storageMs);
                Dictionary<string, object> failed = CharacterConstructionFailureResponse("social_event", campaignId, heroId, ReadString(speaker, "name", heroId), construction, failedTiming, new Dictionary<string, object>
                {
                    ["eventId"] = eventId
                });
                LogOperational("social_event.character_construction_failed", failed);
                WriteAudit(campaignId, correlationId, "server", auditMode, "character.construction", heroId, "", eventId, "failed", constructionMs, "Character construction failed before event response.", new Dictionary<string, object>
                {
                    ["construction"] = construction,
                    ["timing"] = failedTiming
                });
                return failed;
            }

            phaseTimer.Restart();
            string heroName = ReadString(speaker, "name", heroId);
            string playerName = ReadString(payload, "playerName", "Player");
            string sceneContext = ReadString(payload, "sceneContext", "");
            Dictionary<string, object> settings = LoadSettings();
            int canonicalTranscriptLimit = Math.Max(2, Math.Min(100, ReadInt(settings, "recentRawConversationTurns", 30)));
            List<Dictionary<string, object>> eventLines = partyChatRequest
                ? BuildPartyChatPromptTranscript(payload, playerText)
                : BuildSocialEventPromptTranscript(
                    ReadJsonLinesFromPath(SocialEventTranscriptFile(campaignId, eventId)),
                    canonicalTranscriptLimit);
            eventLines = CanonicalizePromptTranscript(eventLines, canonicalTranscriptLimit);
            Dictionary<string, object> identityView = ResolvePromptIdentity(payload, heroId, auditMode, eventId, eventLines);
            string promptPlayerName = ReadString(identityView, "usableName", "the stranger");
            payload["identityView"] = identityView;
            Dictionary<string, object> profile = ReadJsonObject(CharacterFile(campaignId, heroId, "profile.json"));
            Dictionary<string, object> characteristics = LoadCharacterStack(campaignId, heroId);
            Dictionary<string, object> state = ReadJsonObject(CharacterFile(campaignId, heroId, "state.json"));
            Dictionary<string, object> relationships = ReadJsonObject(CharacterFile(campaignId, heroId, "memory", "relationships.json"));
            Dictionary<string, object> summary = ReadJsonObject(CharacterFile(campaignId, heroId, "memory", "summary.json"));
            List<Dictionary<string, object>> memories = ReadJsonLinesFromPath(CharacterFile(campaignId, heroId, "memory", "memories.jsonl"))
                .Where(DurableDialogueMemoryRowIsUsable)
                .OrderByDescending(x => ReadLong(x, "ts", 0))
                .Take(ReadInt(settings, "maxContextMemories", 12))
                .Reverse()
                .ToList();
            List<Dictionary<string, object>> selectedContextPulls = NormalizeSelectedContextPulls(ReadDictionaryList(payload, "selectedContextPulls"), ContextPullIds.ToList());
            List<Dictionary<string, object>> contextBundles = ReadDictionaryList(payload, "contextBundles");
            List<Dictionary<string, object>> compactActionCatalog = CompactActionCatalog(ActionCatalog());
            contextLoadMs = phaseTimer.ElapsedMilliseconds;
            WriteAudit(campaignId, correlationId, "server", auditMode, "context.loaded", heroId, "", eventId, "completed", contextLoadMs, "Loaded event character stack, transcript, context bundles, and action catalog.", new Dictionary<string, object>
            {
                ["profile"] = profile,
                ["characteristics"] = characteristics,
                ["state"] = state,
                ["relationships"] = relationships,
                ["memorySummary"] = summary,
                ["memories"] = memories,
                ["eventLines"] = eventLines,
                ["selectedContextPulls"] = selectedContextPulls,
                ["contextBundles"] = contextBundles,
                ["actionCatalog"] = compactActionCatalog,
                ["identityView"] = identityView
            });

            phaseTimer.Restart();
            using (ReignTraceScope relationshipTrace = BeginReignSpan(
                "relationship.history.resolve",
                new Dictionary<string, object>
                {
                    ["campaignId"] = campaignId,
                    ["correlationId"] = correlationId,
                    ["mode"] = auditMode,
                    ["heroId"] = heroId,
                    ["eventId"] = eventId
                }))
            {
                npcRelationshipPrompt =
                    BuildNpcRelationshipPromptContext(campaignId, heroId, payload);
                relationshipTrace.Set("targetCount",
                    ReadDictionaryList(npcRelationshipPrompt, "targets").Count);
            }
            npcRelationshipContextMs = phaseTimer.ElapsedMilliseconds;
            payload["precomputedNpcRelationshipPrompt"] = npcRelationshipPrompt;
            WriteAudit(campaignId, correlationId, "server", auditMode,
                "relationship_history.loaded", heroId, "", eventId, "completed",
                npcRelationshipContextMs,
                "Resolved reusable NPC relationship history before local prompt assembly.",
                new Dictionary<string, object>
                {
                    ["npcRelationshipPrompt"] = npcRelationshipPrompt,
                    ["timing"] = NpcRelationshipTiming(
                        npcRelationshipContextMs, npcRelationshipPrompt)
                });

            phaseTimer.Restart();
            Dictionary<string, object> conversationSceneState = PrepareConversationSceneState(
                campaignId, payload, heroId, promptTurnText, eventLines, ReadString(payload, "mode", "social_event"));
            PromptEnvelope promptEnvelope;
            using (ReignTraceScope promptTrace = BeginReignSpan("prompt.build", new Dictionary<string, object>
            { ["campaignId"] = campaignId, ["correlationId"] = correlationId, ["mode"] = auditMode, ["heroId"] = heroId, ["eventId"] = eventId }))
            {
                if (ActiveCodexConversationScope.Value != null) payload["codexParallelPreparation"] = new Dictionary<string, object>
                { ["consistentSnapshot"] = true, ["characterInitialized"] = true, ["requiredStateUpdatesComplete"] = true };
                promptEnvelope = BuildEventPromptEnvelope(campaignId, eventId, heroId, heroName, promptPlayerName, playerName, promptTurnText, sceneContext, payload, profile, characteristics, state, relationships, summary, eventLines, selectedContextPulls, contextBundles, compactActionCatalog, identityView);
                promptTrace.Set("promptChars", promptEnvelope.TotalChars);
            }
            Dictionary<string, object> motiveDecision = ReadDictionary(promptEnvelope.Diagnostics, "motiveDecision") ?? new Dictionary<string, object>();
            List<Dictionary<string, object>> messages = promptEnvelope.Messages;
            promptBuildMs = phaseTimer.ElapsedMilliseconds;
            WriteAudit(campaignId, correlationId, "server", auditMode, "prompt.built", heroId, "", eventId, "completed", promptBuildMs, "Event prompt assembled.", new Dictionary<string, object>
            {
                ["messages"] = messages,
                ["promptChars"] = promptEnvelope.TotalChars,
                ["promptEnvelope"] = promptEnvelope.Diagnostics,
                ["contextBundleCount"] = contextBundles.Count,
                ["selectedContextPullCount"] = selectedContextPulls.Count
            });

            phaseTimer.Restart();
            Dictionary<string, object> eventLlmRequest = new Dictionary<string, object>
            {
                ["requestType"] = "social_event",
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["heroStringId"] = heroId,
                ["eventId"] = eventId,
                ["playerText"] = playerText,
                ["messages"] = messages,
                ["promptEnvelope"] = promptEnvelope.Diagnostics,
                ["promptCacheEligible"] = true,
                // Event/party JSON includes participation, relationship evidence,
                // memory writes, and action gates. Give it enough room on the first
                // attempt instead of predictably resending the full prompt for repair.
                ["maxTokens"] = StructuredEventResponseMaxTokens(settings),
                ["response_format"] = new Dictionary<string, object> { ["type"] = "json_object" }
            };
            AttachCodexAuthoritativeConversationMetadata(eventLlmRequest, payload, campaignId, heroId, auditMode,
                ReadFirstString(payload, "conversationSessionId", "sessionId", "conversationId"), identityView, profile, state, relationships, summary,
                conversationSceneState, null, contextBundles, eventLines, promptTurnText);
            Dictionary<string, object> llm = ChatWithLlm(eventLlmRequest);
            llm = WithDiagnosticTransformation("Answer structure and format repair", llm, () => RetryMalformedStructuredResponse(llm, eventLlmRequest, campaignId, correlationId, auditMode, heroId, eventId));
            if (!ReadBool(llm, "visibleRepairFailure", false))
                llm = WithDiagnosticTransformation("Character motives", llm, () => RetryMotiveContradictoryResponse(llm, eventLlmRequest, motiveDecision, campaignId, correlationId, auditMode, heroId, eventId));
            if (!ReadBool(llm, "visibleRepairFailure", false))
                llm = WithDiagnosticTransformation("Political conduct", llm, () => EnforcePoliticalConductResponse(llm,
                eventLlmRequest, motiveDecision, campaignId,
                correlationId, auditMode, heroId, eventId));
            if (!ReadBool(llm, "visibleRepairFailure", false))
                llm = WithDiagnosticTransformation("Family and kinship facts", llm, () => RetryKinshipContradictoryResponse(llm, eventLlmRequest, payload, campaignId, correlationId, auditMode, heroId, eventId));
            if (!ReadBool(llm, "visibleRepairFailure", false))
                llm = WithDiagnosticTransformation("Dialogue integrity", llm, () => RetryDialogueIntegrityViolation(llm, eventLlmRequest, payload, eventLines,
                campaignId, correlationId, auditMode, heroId, eventId));
            if (!ReadBool(llm, "visibleRepairFailure", false))
                llm = WithDiagnosticTransformation("Continuity and repeated narration", llm, () => RetryRoleplayContinuityViolation(llm, eventLlmRequest, payload, identityView, eventLines,
                campaignId, correlationId, auditMode, heroId, heroName, playerName, eventId));
            if (!ReadBool(llm, "visibleRepairFailure", false))
                llm = WithDiagnosticTransformation("Castle opening consistency", llm, () => RetryCastleOpeningContradictoryResponse(llm, eventLlmRequest,
                ReadBool(payload, "castleOpening", false), campaignId, correlationId,
                auditMode, heroId, eventId));
            if (!ReadBool(llm, "visibleRepairFailure", false))
                llm = WithDiagnosticTransformation("Negotiation and NPC agency", llm, () => EnforceConversationAgencyResponse(llm, eventLlmRequest, motiveDecision, payload,
                campaignId, correlationId, auditMode, heroId,
                validateRepair: candidate => ValidateAgencyRepairedResponse(candidate, motiveDecision, payload, identityView, eventLines, heroId, heroName, playerName)));
            if (ReadBool(ReadDictionary(llm, "conversationAgency"), "replayed", false)) return ConversationAgencyReplayResponse(llm, heroId);
            RecordCodexFinalRepairEvidence(llm);
            llmMs = phaseTimer.ElapsedMilliseconds;
            if (!ReadBool(llm, "ok", false))
            {
                totalTimer.Stop();
                Dictionary<string, object> failedTiming = WithNpcRelationshipTiming(
                    DialogueTiming(totalTimer.ElapsedMilliseconds, upsertMs,
                        constructionMs, contextLoadMs, promptBuildMs, llmMs,
                        ReadLong(llm, "durationMs", 0), parseMs, storageMs),
                    npcRelationshipContextMs, npcRelationshipPrompt);
                LogOperational("social_event.respond_failed", new Dictionary<string, object>
                {
                    ["campaignId"] = campaignId,
                    ["eventId"] = eventId,
                    ["heroStringId"] = heroId,
                    ["stage"] = "llm",
                    ["timing"] = failedTiming,
                    ["llm"] = llm
                });
                WriteAudit(campaignId, correlationId, "server", auditMode, auditMode + ".response", heroId, "", eventId, "failed", totalTimer.ElapsedMilliseconds, "Event response failed during LLM call.", new Dictionary<string, object>
                {
                    ["stage"] = "llm",
                    ["timing"] = failedTiming,
                    ["llm"] = llm
                });
                return new Dictionary<string, object> { ["ok"] = false, ["stage"] = "llm", ["llm"] = llm, ["timing"] = failedTiming };
            }

            phaseTimer.Restart();
            string content = ReadString(llm, "content", "");
            Dictionary<string, object> parsed = TryParseJsonObject(content);
            bool agencyVisibleFailure = ReadBool(ReadDictionary(llm, "conversationAgency"), "visibleFailure", false)
                || ReadBool(llm, "visibleRepairFailure", false);
            string participation = NormalizeSocialEventParticipation(parsed);
            string reply = ReadFirstString(parsed, "reply", "response", "text", "content");
            if (string.IsNullOrWhiteSpace(reply) && participation != "quiet")
            {
                reply = ExtractVisibleReply(content);
            }

            if (string.IsNullOrWhiteSpace(reply) && participation != "quiet")
            {
                reply = "[Bannerlord Reign: the model returned malformed JSON, so the visible reply was hidden. Please try again.]";
            }
            if (participation == "quiet")
            {
                reply = string.Empty;
            }
            reply = SanitizeVisibleReply(reply);
            reply = RemoveSpokenNumericSkillLevels(reply, out bool skillNumericRepairApplied);
            reply = SanitizePromptForIdentity(reply, "", playerName, identityView);
            reply = NormalizeUnknownIdentityVisibleAddress(reply, identityView);
            List<Dictionary<string, object>> recallConsistencyRepairs;
            reply = RepairVisibleExactRecallIdentifiers(playerText, reply, parsed, messages, out recallConsistencyRepairs);
            if (!agencyVisibleFailure)
                reply = ApplyConversationDrinking(campaignId, heroId, payload, profile, characteristics, parsed, reply);
            Dictionary<string, object> conversationSceneResolution = FinalizeConversationSceneState(
                campaignId, payload, heroId, playerText, reply, ReadString(payload, "mode", "social_event"), parsed);

            long ts = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
            string decisionId = Guid.NewGuid().ToString("N");
            string emotion = parsed == null ? "" : ReadString(parsed, "emotion", "");
            string intent = parsed == null ? "" : ReadString(parsed, "intent", "");
            string relationshipSignal = parsed == null ? "" : ReadFirstString(parsed, "relationshipSignal", "relationship_signal");
            string reactionTargetHeroStringId = NormalizeSocialEventReactionTarget(parsed, payload, heroId);
            List<Dictionary<string, object>> relationshipAssessments = NormalizeConversationRelationshipAssessments(
                parsed, payload, heroId, relationshipSignal, reactionTargetHeroStringId, ReadString(payload, "sceneTurnId", ""));
            if (agencyVisibleFailure || participation == "quiet" || string.IsNullOrWhiteSpace(reply))
            {
                relationshipAssessments.Clear();
            }
            else ApplyAgencyRelationshipAssessment(relationshipAssessments, payload, heroId,
                ReadFirstString(payload, "playerHeroStringId", "mainHeroStringId", "playerId"));
            if (!ReadBool(payload, "canInvitePlayerToDance", true) && IsForbiddenDanceInvitation(intent, reply))
            {
                participation = "quiet";
                reactionTargetHeroStringId = "";
                relationshipAssessments.Clear();
                reply = string.Empty;
                intent = "ordinary_social_observation";
            }
            Dictionary<string, object> actionGate = approachOpening
                ? NormalizeActionGate(null, "", "")
                : NormalizeActionGate(parsed == null ? null : ReadDictionary(parsed, "actionGate") ?? ReadDictionary(parsed, "action_gate"), playerText, reply);
            Dictionary<string, object> decisionBrief = AugmentDecisionBriefWithMotiveEvidence(NormalizeDecisionBrief(parsed, intent, actionGate), motiveDecision);
            RemovePrivateReasoningFields(parsed);
            List<Dictionary<string, object>> memoryWrites = parsed == null ? new List<Dictionary<string, object>>() : NormalizeMemoryWrites(parsed.ContainsKey("memoryWrites") ? parsed["memoryWrites"] : null, campaignId, heroId, ts);
            List<Dictionary<string, object>> beliefWrites = parsed == null ? new List<Dictionary<string, object>>() : ReadDictionaryList(parsed, "beliefWrites").Concat(ReadDictionaryList(parsed, "belief_writes")).ToList();
            List<Dictionary<string, object>> relationshipUpdates = parsed == null ? new List<Dictionary<string, object>>() : ReadDictionaryList(parsed, "relationshipUpdates").Concat(ReadDictionaryList(parsed, "relationship_updates")).ToList();
            List<Dictionary<string, object>> obligationWrites = parsed == null ? new List<Dictionary<string, object>>() : ReadDictionaryList(parsed, "obligationWrites").Concat(ReadDictionaryList(parsed, "obligation_writes")).ToList();
            List<Dictionary<string, object>> comprehensionWrites = parsed == null ? new List<Dictionary<string, object>>() : ReadDictionaryList(parsed, "comprehensionWrites").Concat(ReadDictionaryList(parsed, "comprehension_writes")).ToList();
            List<Dictionary<string, object>> dynamicCharacteristicWrites = NormalizeDynamicCharacteristicWrites(parsed, heroId, profile, payload, reply);
            if (agencyVisibleFailure || approachOpening || participation == "quiet") dynamicCharacteristicWrites.Clear();
            List<Dictionary<string, object>> roleWriteRejections = new List<Dictionary<string, object>>();
            memoryWrites = FilterConversationRoleMisattributions(memoryWrites, payload, playerText, "memory", roleWriteRejections);
            beliefWrites = FilterConversationRoleMisattributions(beliefWrites, payload, playerText, "belief", roleWriteRejections);
            obligationWrites = FilterConversationRoleMisattributions(obligationWrites, payload, playerText, "obligation", roleWriteRejections);
            comprehensionWrites = FilterConversationRoleMisattributions(comprehensionWrites, payload, playerText, "comprehension", roleWriteRejections);
            memoryWrites = FilterRoleplayFeedbackWrites(memoryWrites, "memory", roleWriteRejections);
            beliefWrites = FilterRoleplayFeedbackWrites(beliefWrites, "belief", roleWriteRejections);
            obligationWrites = FilterRoleplayFeedbackWrites(obligationWrites, "obligation", roleWriteRejections);
            comprehensionWrites = FilterRoleplayFeedbackWrites(comprehensionWrites, "comprehension", roleWriteRejections);
            Dictionary<string, object> stateUpdates = parsed == null
                ? new Dictionary<string, object>()
                : NormalizeSafeConversationStateUpdates(
                    ReadDictionary(parsed, "stateUpdates") ?? ReadDictionary(parsed, "state_updates"),
                    roleWriteRejections);
            Dictionary<string, object> politicalRiskPosture =
                ReadDictionary(motiveDecision, "politicalRiskPosture")
                ?? new Dictionary<string, object>();
            Dictionary<string, object> pendingAddressConvention =
                ReadDictionary(politicalRiskPosture,
                    "pendingAddressConvention");
            if (pendingAddressConvention != null
                && pendingAddressConvention.Count > 0)
                stateUpdates["politicalAddressConvention"] =
                    CloneDictionary(pendingAddressConvention);
            Dictionary<string, object> politicalConduct =
                ReadDictionary(parsed, "politicalConduct")
                ?? new Dictionary<string, object>();
            bool recallOnlyTurn = IsPureConversationRecallRequest(playerText);
            if (recallOnlyTurn)
            {
                memoryWrites.Clear();
                beliefWrites.Clear();
                obligationWrites.Clear();
                comprehensionWrites.Clear();
                dynamicCharacteristicWrites.Clear();
            }
            List<Dictionary<string, object>> suggestedActions = approachOpening || parsed == null
                ? new List<Dictionary<string, object>>()
                : NormalizeSuggestedActions(parsed.ContainsKey("suggestedActions") ? parsed["suggestedActions"] : null, compactActionCatalog);
            List<Dictionary<string, object>> identityIntroductionResults = ApplyIdentityIntroductionWrites(campaignId, payload, parsed, eventId);
            WriteAudit(campaignId, correlationId, "server", auditMode, "model.parsed", heroId, "", eventId, parsed == null ? "warning" : "completed", phaseTimer.ElapsedMilliseconds, parsed == null ? "Model response was not valid JSON; visible reply fallback was used." : "Event model JSON parsed.", new Dictionary<string, object>
            {
                ["rawContent"] = content,
                ["parsed"] = parsed ?? new Dictionary<string, object>(),
                ["reply"] = reply,
                ["skillNumericRepairApplied"] = skillNumericRepairApplied,
                ["decisionBrief"] = decisionBrief,
                ["emotion"] = emotion,
                ["intent"] = intent,
                ["relationshipSignal"] = relationshipSignal,
                ["relationshipAssessments"] = relationshipAssessments,
                ["actionGate"] = actionGate,
                ["memoryWrites"] = memoryWrites,
                ["beliefWrites"] = beliefWrites,
                ["relationshipUpdates"] = relationshipUpdates,
                ["obligationWrites"] = obligationWrites,
                ["comprehensionWrites"] = comprehensionWrites,
                ["dynamicCharacteristicWrites"] = dynamicCharacteristicWrites,
                ["roleWriteRejections"] = roleWriteRejections,
                ["recallWriteSuppressed"] = recallOnlyTurn,
                ["recallConsistencyRepairs"] = recallConsistencyRepairs,
                ["stateUpdates"] = stateUpdates,
                ["politicalRiskPosture"] = politicalRiskPosture,
                ["politicalConduct"] = politicalConduct,
                ["politicalConductEnforcement"] = ReadDictionary(
                    llm, "politicalConductEnforcement")
                    ?? new Dictionary<string, object>(),
                ["suggestedActions"] = suggestedActions,
                ["identityIntroductionResults"] = identityIntroductionResults
                ,["conversationSceneState"] = conversationSceneState
                ,["conversationSceneResolution"] = conversationSceneResolution
            });
            List<string> eventActionErrors = new List<string>();
            List<Dictionary<string, object>> queuedEventActions = approachOpening || agencyVisibleFailure
                ? new List<Dictionary<string, object>>()
                : QueueAcceptedDialogueActions(campaignId, payload, profile, playerText, reply, actionGate, suggestedActions, out eventActionErrors);
            if (queuedEventActions.Count > 0)
            {
                string statusLine = "[Bannerlord Reign event action queued: " + string.Join(", ", queuedEventActions.Select(x => ReadString(x, "command", "")).Where(x => !string.IsNullOrWhiteSpace(x))) + ".]";
                reply = string.IsNullOrWhiteSpace(reply) || reply == "..." ? statusLine : reply + "\n\n" + statusLine;
            }
            if (HasUnconfirmedMarriageClaim(reply, payload, profile))
            {
                memoryWrites.Clear();
                beliefWrites.Clear();
                comprehensionWrites.Clear();
                relationshipAssessments.Clear();
                relationshipUpdates.Clear();
                obligationWrites.Clear();
                dynamicCharacteristicWrites.Clear();
                stateUpdates.Clear();
            }
            reply = FinalizeDialogueActionOutcome(reply, payload, profile, queuedEventActions, eventActionErrors);
            bool privatePlayerInputForSpeaker = ReadBool(payload, "privatePlayerInputForSpeaker", false);
            string sharedPlayerText = ReadString(payload, "publicPlayerText", playerText);
            string sharedReply = privatePlayerInputForSpeaker
                ? "*The speaker replies privately to the player.*" : reply;
            Dictionary<string, object> playerLine = approachOpening || ReadBool(payload, "suppressPlayerTranscript", false)
                || partyChatRequest && ReadInt(payload, "partySpeakerIndex", 0) > 0
                ? null
                : EventTranscriptLine("player", playerName, sharedPlayerText, payload);
            Dictionary<string, object> npcLine = participation == "quiet" || string.IsNullOrWhiteSpace(reply) ? null : EventTranscriptLine("npc", heroName, sharedReply, payload);
            parseMs = phaseTimer.ElapsedMilliseconds;

            phaseTimer.Restart();
            bool partyChatTurn = string.Equals(ReadString(payload, "mode", ""), "party_chat", StringComparison.OrdinalIgnoreCase)
                || string.Equals(eventId, "party_chat", StringComparison.OrdinalIgnoreCase);
            string eventTranscriptPath = partyChatTurn
                ? PartyChatSessionTranscriptFile(campaignId, payload)
                : SocialEventTranscriptFile(campaignId, eventId);
            string socialPlayerId = ReadFirstString(profile, "mainHeroStringId");
            string socialLocationId = FirstNonEmpty(
                ReadFirstString(payload, "locationId", "currentSettlementId", "settlementId"),
                ReadFirstString(profile, "currentSettlementId", "settlementId"));
            List<string> sharedParticipants = partyChatTurn
                ? MergeStringLists(
                    MergeStringLists(ReadStringList(payload, "participants"), ReadStringList(payload, "activeHeroIds")),
                    new[] { heroId, socialPlayerId })
                : new List<string>();
            Dictionary<string, object> conversationExchange = partyChatTurn
                ? StorePartyConversationExchange(
                    campaignId, payload, heroId, socialPlayerId, playerName, heroName, sharedPlayerText, sharedReply, decisionId, ts)
                : StoreSocialEventConversationExchange(
                    campaignId, payload, heroId, socialPlayerId, playerName, heroName, sharedPlayerText, sharedReply, decisionId, eventId, ts);
            if (privatePlayerInputForSpeaker)
            {
                Dictionary<string, object> privateRequest = new Dictionary<string, object>(payload,
                    StringComparer.OrdinalIgnoreCase);
                string privateTurnKey = SafeMemoryKey(ReadFirstString(payload,
                    "sceneTurnId", "turnId", "exchangeId"));
                privateRequest["conversationSessionId"] = ReadString(payload, "conversationSessionId", "")
                    + "_whisper_" + SafeMemoryKey(heroId) + "_" + privateTurnKey;
                privateRequest["sceneTurnId"] = ReadFirstString(payload, "sceneTurnId", "turnId", "exchangeId")
                    + "_whisper_" + SafeMemoryKey(heroId);
                privateRequest["participants"] = new List<string> { heroId, socialPlayerId };
                privateRequest["activeHeroIds"] = new List<string> { heroId };
                StoreGroupedConversationExchange(campaignId, privateRequest, heroId, socialPlayerId,
                    playerName, heroName, playerText, reply, decisionId, ts, "private_whisper", "");
            }
            if (partyChatTurn || !string.IsNullOrWhiteSpace(ReadString(conversationExchange, "sessionId", "")))
            {
                string storedSessionId = ReadString(conversationExchange, "sessionId", "");
                string storedExchangeId = ReadString(conversationExchange, "exchangeId", "");
                if (playerLine != null)
                {
                    playerLine["sessionId"] = storedSessionId;
                    playerLine["exchangeId"] = storedExchangeId;
                }
                if (npcLine != null)
                {
                    npcLine["sessionId"] = storedSessionId;
                    npcLine["exchangeId"] = storedExchangeId;
                }
            }
            if (playerLine != null)
            {
                AppendJsonLineToPath(eventTranscriptPath, playerLine);
                AppendJsonLineToPath(CharacterFile(campaignId, heroId, "history", "events.jsonl"), playerLine);
            }
            if (npcLine != null)
            {
                AppendJsonLineToPath(eventTranscriptPath, npcLine);
                AppendJsonLineToPath(CharacterFile(campaignId, heroId, "history", "events.jsonl"), npcLine);
            }
            foreach (Dictionary<string, object> memoryWrite in memoryWrites)
            {
                AppendJsonLineToPath(CharacterFile(campaignId, heroId, "memory", "memories.jsonl"), memoryWrite);
            }

            List<string> dynamicCharacteristicAudience = partyChatTurn
                ? privatePlayerInputForSpeaker ? new List<string> { heroId, socialPlayerId } : sharedParticipants
                : privatePlayerInputForSpeaker ? new List<string> { heroId, socialPlayerId } : MergeStringLists(
                    attendees.Select(CharacterIdFrom).Where(x => !string.IsNullOrWhiteSpace(x)),
                    new[] { heroId, socialPlayerId });
            Dictionary<string, object> dynamicCharacteristicsStore = StoreDynamicCharacteristicWrites(
                campaignId,
                heroId,
                dynamicCharacteristicWrites,
                payload,
                conversationExchange,
                decisionId,
                partyChatTurn ? "party_chat" : ReadString(payload, "mode", "social_event"),
                socialLocationId,
                ts,
                dynamicCharacteristicAudience);

            string partySessionId = ReadString(conversationExchange, "sessionId", "");
            string memoryGroupKey = partyChatTurn && !string.IsNullOrWhiteSpace(partySessionId)
                ? "conversation:" + partySessionId
                : BuildMemoryGroupKey(payload, heroId, socialPlayerId, socialLocationId, "social_event", ts);
            Dictionary<string, object> memoryLayerStore = StoreTurnMemoryLayers(
                campaignId,
                decisionId,
                partyChatTurn ? "party_chat_turn" : "social_event_turn",
                heroId,
                socialPlayerId,
                socialLocationId,
                playerText,
                reply,
                memoryWrites,
                beliefWrites,
                relationshipUpdates,
                obligationWrites,
                comprehensionWrites,
                memoryGroupKey,
                ts,
                partyChatTurn
                    ? privatePlayerInputForSpeaker ? new List<string> { heroId, socialPlayerId } : sharedParticipants
                    : null,
                retrievalEligible: !recallOnlyTurn,
                continuityPayload: payload, continuityWrites: ReadDictionaryList(parsed, "continuityWrites"));
            Dictionary<string, object> sharedConversationPayload = new Dictionary<string, object>(payload,
                StringComparer.OrdinalIgnoreCase) { ["playerText"] = sharedPlayerText };
            UpdateSharedGroupConversationState(campaignId, sharedConversationPayload, heroId, heroName, sharedReply,
                FirstNonEmpty(partySessionId, GroupConversationSessionId(payload), eventId), ts);
            Dictionary<string, object> motiveOutcome = ApplyConversationMotiveOutcome(
                campaignId, motiveDecision, payload, reply, intent, decisionId, decisionBrief);
            if (stateUpdates.Count > 0)
            {
                MergeCharacterState(campaignId, heroId, stateUpdates);
            }

            AppendJsonLineToPath(CharacterFile(campaignId, heroId, "history", "decisions.jsonl"), new Dictionary<string, object>
            {
                ["id"] = decisionId,
                ["ts"] = ts,
                ["campaignId"] = campaignId,
                ["eventId"] = eventId,
                ["templateId"] = ReadString(payload, "templateId", ""),
                ["phaseId"] = ReadString(payload, "phaseId", ""),
                ["heroStringId"] = heroId,
                ["playerName"] = playerName,
                ["heroName"] = heroName,
                ["playerText"] = playerText,
                ["turnType"] = approachOpening ? "npc_approach_opening" : "player_reply",
                ["turnId"] = ReadString(payload, "turnId", ""),
                ["participation"] = participation,
                ["reactionTargetHeroStringId"] = reactionTargetHeroStringId,
                ["reply"] = reply,
                ["privateAudienceHeroStringId"] = privatePlayerInputForSpeaker ? heroId : string.Empty,
                ["decisionBrief"] = decisionBrief,
                ["motiveDecision"] = motiveDecision,
                ["motiveOutcome"] = motiveOutcome,
                ["emotion"] = emotion,
                ["intent"] = intent,
                ["relationshipSignal"] = relationshipSignal,
                ["relationshipAssessments"] = relationshipAssessments,
                ["actionGate"] = actionGate,
                ["memoryWrites"] = memoryWrites,
                ["beliefWrites"] = beliefWrites,
                ["relationshipUpdates"] = relationshipUpdates,
                ["obligationWrites"] = obligationWrites,
                ["comprehensionWrites"] = comprehensionWrites,
                ["dynamicCharacteristicWrites"] = dynamicCharacteristicWrites,
                ["dynamicCharacteristicsStore"] = dynamicCharacteristicsStore,
                ["recallConsistencyRepairs"] = recallConsistencyRepairs,
                ["stateUpdates"] = stateUpdates,
                ["suggestedActions"] = suggestedActions,
                ["memoryLayerStore"] = memoryLayerStore,
                ["queuedActions"] = queuedEventActions,
                ["actionErrors"] = eventActionErrors,
                ["identityIntroductionResults"] = identityIntroductionResults,
                ["conversationExchange"] = conversationExchange
                ,["conversationSceneState"] = conversationSceneState
                ,["conversationSceneResolution"] = conversationSceneResolution
            });
            storageMs = phaseTimer.ElapsedMilliseconds;
            totalTimer.Stop();
            Dictionary<string, object> timing = WithNpcRelationshipTiming(
                DialogueTiming(totalTimer.ElapsedMilliseconds, upsertMs,
                    constructionMs, contextLoadMs, promptBuildMs, llmMs,
                    ReadLong(llm, "durationMs", 0), parseMs, storageMs),
                npcRelationshipContextMs, npcRelationshipPrompt);
            timing["promptChars"] = promptEnvelope.TotalChars;
            timing["contextBundleCount"] = contextBundles.Count;
            timing["contextBundleChars"] = Json.Serialize(contextBundles).Length;
            timing["selectedContextPullCount"] = selectedContextPulls.Count;
            string encyclopediaText = BuildEncyclopediaBackstoryText(campaignId, heroId);

            Dictionary<string, object> response = new Dictionary<string, object>
            {
                ["ok"] = true,
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["eventId"] = eventId,
                ["heroStringId"] = heroId,
                ["reply"] = reply,
                ["privateAudienceHeroStringId"] = privatePlayerInputForSpeaker ? heroId : string.Empty,
                ["participation"] = participation,
                ["reactionTargetHeroStringId"] = reactionTargetHeroStringId,
                ["identityView"] = identityView,
                ["emotion"] = emotion,
                ["intent"] = intent,
                ["relationshipSignal"] = relationshipSignal,
                ["relationshipAssessments"] = relationshipAssessments,
                ["decisionBrief"] = decisionBrief,
                ["motiveDecision"] = motiveDecision,
                ["motiveOutcome"] = motiveOutcome,
                ["actionGate"] = actionGate,
                ["memoryWrites"] = memoryWrites,
                ["beliefWrites"] = beliefWrites,
                ["relationshipUpdates"] = relationshipUpdates,
                ["obligationWrites"] = obligationWrites,
                ["comprehensionWrites"] = comprehensionWrites,
                ["dynamicCharacteristicWrites"] = dynamicCharacteristicWrites,
                ["dynamicCharacteristicsStore"] = dynamicCharacteristicsStore,
                ["recallConsistencyRepairs"] = recallConsistencyRepairs,
                ["stateUpdates"] = stateUpdates,
                ["conversationSceneState"] = conversationSceneState,
                ["conversationSceneResolution"] = conversationSceneResolution,
                ["suggestedActions"] = suggestedActions,
                ["queuedActions"] = queuedEventActions,
                ["actionErrors"] = eventActionErrors,
                ["identityIntroductionResults"] = identityIntroductionResults,
                ["conversationExchange"] = conversationExchange,
                ["selectedContextPulls"] = selectedContextPulls,
                ["contextBundles"] = contextBundles,
                ["construction"] = construction,
                ["encyclopediaText"] = encyclopediaText,
                ["timing"] = timing
            };
            LogOperational("social_event.respond", new Dictionary<string, object>
            {
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["eventId"] = eventId,
                ["heroStringId"] = heroId,
                ["decisionId"] = decisionId,
                ["playerChars"] = playerText.Length,
                ["replyChars"] = reply.Length,
                ["decisionBrief"] = decisionBrief,
                ["emotion"] = emotion,
                ["intent"] = intent,
                ["relationshipSignal"] = relationshipSignal,
                ["actionGate"] = actionGate,
                ["memoryWriteCount"] = memoryWrites.Count,
                ["dynamicCharacteristicWriteCount"] = dynamicCharacteristicWrites.Count,
                ["dynamicCharacteristicStoredCount"] = ReadInt(dynamicCharacteristicsStore, "storedCount", 0),
                ["recallConsistencyRepairCount"] = recallConsistencyRepairs.Count,
                ["stateUpdateCount"] = stateUpdates.Count,
                ["suggestedActionCount"] = suggestedActions.Count,
                ["queuedActionCount"] = queuedEventActions.Count,
                ["actionErrors"] = eventActionErrors,
                ["selectedContextPulls"] = selectedContextPulls.Select(x => ReadString(x, "id", "")).ToList(),
                ["contextBundleCount"] = contextBundles.Count,
                ["contextBundleChars"] = Json.Serialize(contextBundles).Length,
                ["timing"] = timing
            });
            WriteAudit(campaignId, correlationId, "server", auditMode, auditMode + ".response", heroId, "", eventId, "completed", totalTimer.ElapsedMilliseconds, "Event response completed.", new Dictionary<string, object>
            {
                ["decisionId"] = decisionId,
                ["playerLine"] = playerLine,
                ["npcLine"] = npcLine,
                ["reply"] = reply,
                ["decisionBrief"] = decisionBrief,
                ["memoryWrites"] = memoryWrites,
                ["beliefWrites"] = beliefWrites,
                ["relationshipUpdates"] = relationshipUpdates,
                ["obligationWrites"] = obligationWrites,
                ["comprehensionWrites"] = comprehensionWrites,
                ["dynamicCharacteristicWrites"] = dynamicCharacteristicWrites,
                ["dynamicCharacteristicsStore"] = dynamicCharacteristicsStore,
                ["recallConsistencyRepairs"] = recallConsistencyRepairs,
                ["stateUpdates"] = stateUpdates,
                ["suggestedActions"] = suggestedActions,
                ["conversationExchange"] = conversationExchange,
                ["timing"] = timing
            });
            ScheduleReplayCorpusCapture(campaignId, correlationId);

            RecordCodexFinalizedContract(parsed, response);
            return response;
        }

        private static int StructuredEventResponseMaxTokens(Dictionary<string, object> settings)
        {
            return Math.Max(8000, ReadInt(settings, "maxTokens", 900));
        }

        private static int StructuredDialogueResponseMaxTokens(Dictionary<string, object> settings)
        {
            return Math.Max(8000, ReadInt(settings, "maxTokens", 900));
        }

        private static Dictionary<string, object> PartyChatRespond(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            bool familyChambers = ReadBool(payload, "familyChambers", false);
            if (ReadBool(ReadDictionary(payload, "speaker"), "isChild", false))
            {
                return FamilyChambersChildRespond(payload);
            }
            if (familyChambers)
            {
                List<Dictionary<string, object>> familyAttendees = ReadDictionaryList(payload, "attendees");
                List<Dictionary<string, object>> children = familyAttendees.Where(item => ReadBool(item, "isChild", false)).ToList();
                List<Dictionary<string, object>> adults = familyAttendees.Where(item => !ReadBool(item, "isChild", false)).ToList();
                HashSet<string> childIds = new HashSet<string>(
                    children.Select(CharacterIdFrom).Where(id => !string.IsNullOrWhiteSpace(id)),
                    StringComparer.OrdinalIgnoreCase);
                payload["attendees"] = adults;
                payload["activeHeroIds"] = adults.Select(CharacterIdFrom).Where(id => !string.IsNullOrWhiteSpace(id)).ToList();
                payload["participants"] = adults.Select(CharacterIdFrom).Where(id => !string.IsNullOrWhiteSpace(id))
                    .Concat(new[] { ReadString(payload, "playerHeroStringId", "") }).Where(id => !string.IsNullOrWhiteSpace(id)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
                payload["sceneParticipants"] = ReadDictionaryList(payload, "sceneParticipants")
                    .Where(item => !ReadBool(item, "isChild", false) && !childIds.Contains(CharacterIdFrom(item))).ToList();
                payload["actionResolutionIndex"] = new Dictionary<string, object>();
                payload["sceneContext"] = ReadString(payload, "sceneContext", "")
                    + "\nFAMILY CHILD WITNESSES (prompt context only; never upsert, construct, assess, target, or mutate through adult systems): " + Json.Serialize(children)
                    + "\nAdult dialogue may acknowledge the listed children naturally, but must not emit relationship assessments, reputation, traits, romance, politics, punishment, combat, or actions for a child.";
            }
            payload["mode"] = "party_chat";
            if (string.IsNullOrWhiteSpace(ReadFirstString(payload, "eventId", "socialEventId")))
            {
                payload["eventId"] = "party_chat";
            }

            if (string.IsNullOrWhiteSpace(ReadString(payload, "templateId", "")))
            {
                payload["templateId"] = "party_chat";
            }

            if (string.IsNullOrWhiteSpace(ReadString(payload, "displayName", "")))
            {
                payload["displayName"] = "Party Chat";
            }

            bool castleOpening = ReadBool(payload, "castleOpening", false);
            bool npcOpening = castleOpening || ReadBool(payload, "approachOpening", false)
                || string.Equals(ReadString(payload, "turnType", ""), "npc_approach_opening", StringComparison.OrdinalIgnoreCase);
            string sceneContext = ReadString(payload, "sceneContext", "");
            if (string.IsNullOrWhiteSpace(sceneContext))
            {
                sceneContext = "Conversation mode: party chat. Multiple selected NPCs may be present and may hear the reply.";
            }

            payload["sceneContext"] = sceneContext
                + "\nServer mode: party_chat. The speaker must only speak as themselves, while staying aware this is a group conversation."
                + "\nGROUP CONVERSATION CONTRACT: The structured group transcript is authoritative. Preserve every speaker label and never claim another participant's words as your own."
                + "\nNESTED-EVENT WITNESS RULE: Being present for this conversation proves only that a participant heard this conversation. It does not make them a witness to an older event described by someone else. Only an explicit source-event witness link or that NPC's own attributed first-person record establishes firsthand participation. Another speaker saying 'we', 'everyone', or 'all three' cannot override an NPC's own denial or missing witness evidence."
                + (npcOpening
                    ? "\nCURRENT-BEAT PRIORITY: The player has entered but has not spoken. Initiate naturally; do not answer, acknowledge, quote, or infer a player message. Every prior labeled line belongs to that NPC, never to the player."
                    : "\nCURRENT-BEAT PRIORITY: Directly answer the latest player message before extending an earlier topic. Prior NPC lines are context to engage, not a replacement question. When the player asks for current or canonical facts, use only the selected live bundles; if a requested list or fact is absent, say it is unavailable instead of improvising local lore.")
                + "\nRECALL GROUNDING: A plausible story is not evidence of an already established memory. Never claim a past event was previously discussed, externally verified, or part of supplied recall evidence unless it is present in the attributed transcript, selected memory/history evidence, or character foundation. The NPC may originate a new, low-impact autobiographical detail that is compatible with native facts and their traits; present it as a new disclosure and emit the required dynamicCharacteristicWrites entry so it becomes stable soft character canon. Never invent named relatives, major offices, ownership, wars, crimes, deaths, campaign outcomes, or facts about another person. Preserve evidence granularity and clearly label hypothetical examples as hypothetical."
                + (ReadInt(payload, "partySpeakerIndex", 0) > 0
                    ? " At least one NPC has already spoken in this group beat. Address, build on, question, agree or disagree with, or deliberately brush aside a specific prior NPC contribution when it is relevant. Set reactionTargetHeroStringId to that NPC's supplied id even when participation is speak."
                    : npcOpening
                        ? " You are the first NPC initiating this room encounter; greet, introduce yourself, make an observation, or request attention without implying that the player spoke."
                        : " You are the first NPC answering this group beat; make a distinct contribution that later speakers can engage with.");

            string castlePrompt = ReadString(payload, "castleDialoguePrompt", "");
            Dictionary<string, object> partyVisitorContext = ReadDictionary(payload, "nobleVisitorContext");
            if (partyVisitorContext != null)
                payload["sceneContext"] = ReadString(payload, "sceneContext", "") + "\n" + BuildNobleVisitorPrompt(
                    ReadString(payload, "campaignId", "default"), ReadString(payload, "speakerHeroStringId", ""), partyVisitorContext);
            ApplyCastleChatMode(payload, castlePrompt);

            Dictionary<string, object> response = SocialEventRespond(payload);
            response["mode"] = string.IsNullOrWhiteSpace(castlePrompt) ? "party_chat" : "castle_chat";
            if (familyChambers && ReadBool(response, "ok", false)) ProcessFamilyReconciliationReply(payload, response);
            return response;
        }

        internal static bool ApplyCastleChatMode(
            Dictionary<string, object> payload,
            string castlePrompt)
        {
            if (payload == null || string.IsNullOrWhiteSpace(castlePrompt))
            {
                return false;
            }

            bool castleOpening = ReadBool(payload, "castleOpening", false);
            payload["mode"] = "castle_chat";
            payload["displayName"] = ReadString(payload, "castleRoomName", "Castle Chat");
            if (castleOpening)
            {
                // SocialEventRespond already has a first-speaker contract that
                // permits an empty playerText. Bridge Castle Chat onto that
                // established path instead of fabricating a player utterance.
                payload["approachOpening"] = true;
                payload["turnType"] = "npc_approach_opening";
            }
            payload["sceneContext"] = ReadString(payload, "sceneContext", "")
                + "\nCASTLE ROOM PROMPT SNAPSHOT (authoritative for this persisted room session):\n" + castlePrompt
                + "\nCASTLE OPENING CONTRACT: " + (castleOpening
                    ? "This is an NPC opening turn. There is no preceding player statement. Speak naturally on noticing the ruler enter; do not fabricate, answer, acknowledge, quote, or infer a player line. If another NPC has already spoken, their labeled words remain that NPC's contribution and are not a petition or statement from the ruler."
                    : "This is a continued Castle Chat turn using the normal party-chat transcript and action/memory rules.");
            return true;
        }

        private static Dictionary<string, object> GeneratedWildernessPlan(Dictionary<string, object> payload)
        {
            Stopwatch totalTimer = Stopwatch.StartNew();
            Stopwatch phaseTimer = Stopwatch.StartNew();
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", "default");
            string correlationId = EnsureCorrelationId(payload);
            List<Dictionary<string, object>> participants = ReadDictionaryList(payload, "participants")
                .Where(participant => !string.IsNullOrWhiteSpace(CharacterIdFrom(participant)) && CharacterIdFrom(participant).Length <= 160)
                .GroupBy(CharacterIdFrom, StringComparer.Ordinal).Select(group => group.First())
                .Take(WildernessParticipantLimit).ToList();
            if (participants.Count == 0)
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "No eligible wilderness participants." };
            string[] direction = SelectWildernessDirection(payload);
            // Passive planning cannot materialize or construct a dynamic character.
            // Their first interactive response performs construction synchronously.
            long constructionMs = 0;

            phaseTimer.Restart();
            string prompt = BuildGeneratedWildernessPrompt(campaignId, payload, participants, direction);
            PromptEnvelope promptEnvelope = BuildSimplePromptEnvelope("generated_wilderness_event", "opening", "You create grounded Mount & Blade II: Bannerlord social role-play event openings. Output only a valid JSON object.", prompt);
            List<Dictionary<string, object>> messages = promptEnvelope.Messages;
            long promptBuildMs = phaseTimer.ElapsedMilliseconds;

            phaseTimer.Restart();
            Dictionary<string, object> wildernessLlmRequest = new Dictionary<string, object>
            {
                ["requestType"] = "generated_wilderness_event",
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["messages"] = messages,
                ["promptEnvelope"] = promptEnvelope.Diagnostics,
                ["promptCacheEligible"] = true,
                ["response_format"] = new Dictionary<string, object> { ["type"] = "json_object" }
            };
            Dictionary<string, object> llm = ChatWithLlm(wildernessLlmRequest);
            llm = WithDiagnosticTransformation("Answer structure and format repair", llm, () => RetryMalformedStructuredResponse(llm, wildernessLlmRequest, campaignId, correlationId, "generated_wilderness_event", "", ""));
            long llmMs = phaseTimer.ElapsedMilliseconds;
            if (!ReadBool(llm, "ok", false))
            {
                totalTimer.Stop();
                Dictionary<string, object> failedTiming = new Dictionary<string, object>
                {
                    ["totalMs"] = totalTimer.ElapsedMilliseconds,
                    ["characterConstructionMs"] = constructionMs,
                    ["promptBuildMs"] = promptBuildMs,
                    ["llmCallMs"] = llmMs,
                    ["llmProviderMs"] = ReadLong(llm, "durationMs", 0)
                };
                LogOperational("generated_wilderness.plan_failed", new Dictionary<string, object>
                {
                    ["campaignId"] = campaignId,
                    ["correlationId"] = correlationId,
                    ["varietyKey"] = direction[0],
                    ["stage"] = "llm",
                    ["timing"] = failedTiming,
                    ["llm"] = llm
                });
                return new Dictionary<string, object> { ["ok"] = false, ["stage"] = "llm", ["error"] = ReadString(llm, "error", "LLM call failed."), ["timing"] = failedTiming };
            }

            phaseTimer.Restart();
            string content = ReadString(llm, "content", "");
            Dictionary<string, object> parsed = TryParseJsonObject(content) ?? new Dictionary<string, object>();
            string title = FirstNonEmpty(ReadFirstString(parsed, "title", "event_title"), "Something Ahead");
            string approach = ReadFirstString(parsed, "approachDescription", "approach_description", "approach");
            string opening = ReadFirstString(parsed, "openingText", "opening_text", "event_opening_text", "opening");
            string playerHook = ReadFirstString(parsed, "playerHook", "player_hook", "hook");
            string externalHeroId = ReadFirstString(parsed, "externalHeroId", "external_hero_id", "outside_hero_id", "outside_npc_id");
            string externalContext = ReadFirstString(parsed, "externalContext", "external_context", "outside_context");
            string terrainKey = ReadString(payload, "terrainKey", "plain");
            string emotionalPressure = ReadFirstString(parsed, "emotionalPressure", "emotional_pressure", "pressure");
            string surfaceClues = FirstNonEmpty(StringListText(ReadStringList(parsed, "surfaceClues")), StringListText(ReadStringList(parsed, "surface_clues")), ReadFirstString(parsed, "surfaceClues", "surface_clues"));
            string hiddenContext = ReadFirstString(parsed, "hiddenContext", "hidden_context", "private_context", "hidden_depth");
            string discoveryRoutes = FirstNonEmpty(StringListText(ReadStringList(parsed, "discoveryRoutes")), StringListText(ReadStringList(parsed, "discovery_routes")), ReadFirstString(parsed, "discoveryRoutes", "discovery_routes", "how_to_discover"));
            List<string> participantIds = ReadStringList(parsed, "participantHeroIds");
            if (participantIds.Count == 0)
            {
                participantIds = ReadStringList(parsed, "participant_ids");
            }

            if (participantIds.Count == 0)
            {
                participantIds = participants.Select(CharacterIdFrom).Where(x => !string.IsNullOrWhiteSpace(x)).Distinct().ToList();
            }
            participantIds = participantIds.Where(id => participants.Any(participant => CharacterIdFrom(participant) == id)).Distinct().ToList();
            // The client supplies authority for any outside participant; a model
            // must not add a new person to the encounter.
            externalHeroId = ReadString(payload, "externalHeroId", "");
            externalContext = ReadString(payload, "externalContext", "");

            long parseMs = phaseTimer.ElapsedMilliseconds;
            totalTimer.Stop();
            Dictionary<string, object> timing = new Dictionary<string, object>
            {
                ["totalMs"] = totalTimer.ElapsedMilliseconds,
                ["characterConstructionMs"] = constructionMs,
                ["promptBuildMs"] = promptBuildMs,
                ["llmCallMs"] = llmMs,
                ["llmProviderMs"] = ReadLong(llm, "durationMs", 0),
                ["parseMs"] = parseMs
            };

            Dictionary<string, object> response = new Dictionary<string, object>
            {
                ["ok"] = true,
                ["campaignId"] = campaignId,
                ["varietyKey"] = direction[0],
                ["title"] = LimitText(title, 120),
                ["approachDescription"] = LimitText(approach, 1200),
                ["openingText"] = LimitText(opening, 1600),
                ["playerHook"] = LimitText(playerHook, 700),
                ["participantHeroIds"] = participantIds,
                ["externalHeroId"] = LimitText(externalHeroId, 120),
                ["externalContext"] = LimitText(externalContext, 700),
                ["terrainKey"] = LimitText(terrainKey, 80),
                ["emotionalPressure"] = LimitText(emotionalPressure, 200),
                ["surfaceClues"] = LimitText(surfaceClues, 1200),
                ["hiddenContext"] = LimitText(hiddenContext, 1600),
                ["discoveryRoutes"] = LimitText(discoveryRoutes, 1200),
                ["timing"] = timing
            };
            string rejection = WildernessOpeningRejection(response, payload, participants);
            if (!string.IsNullOrEmpty(rejection))
            {
                LogOperational("generated_wilderness.plan_rejected", new Dictionary<string, object>
                {
                    ["campaignId"] = campaignId, ["correlationId"] = correlationId,
                    ["varietyKey"] = direction[0], ["reason"] = rejection, ["timing"] = timing
                });
                return new Dictionary<string, object>
                {
                    ["ok"] = false, ["error"] = "Wilderness opening rejected: " + rejection,
                    ["errorCode"] = rejection, ["timing"] = timing
                };
            }
            LogOperational("generated_wilderness.plan", new Dictionary<string, object>
            {
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["varietyKey"] = direction[0],
                ["promptCharacters"] = prompt.Length,
                ["recentEventCount"] = WildernessRecentEvents(payload).Count,
                ["participantCount"] = participants.Count,
                ["title"] = response["title"],
                ["timing"] = timing
            });
            return response;
        }

        private static string BuildGeneratedWildernessPrompt(string campaignId, Dictionary<string, object> payload,
            List<Dictionary<string, object>> participants, string[] direction = null,
            Func<string, Dictionary<string, object>, Dictionary<string, object>> loadPassiveStack = null)
        {
            StringBuilder builder = new StringBuilder();
            builder.AppendLine("Create one Bannerlord wilderness role-play event opening for the player's traveling party.");
            builder.AppendLine("Output only valid JSON. This is a social/emotional opening, not a quest.");
            builder.AppendLine("No combat, ambushes, loot, injuries, arrests, forced romance, marriage obligations, settlement effects, party movement, or campaign consequences.");
            builder.AppendLine("Do not write dialogue or feelings for the player. Do not invent extra named NPCs. Use only listed participants and the player character.");
            builder.AppendLine();
            builder.AppendLine("Player display name: " + LimitText(ReadString(payload, "playerName", "Player"), 120));
            builder.AppendLine("Terrain key: " + LimitText(ReadString(payload, "terrainKey", "plain"), 80));
            builder.AppendLine("Location text: " + LimitText(ReadString(payload, "locationText", "on the road"), 400));
            builder.AppendLine("Time of day: " + LimitText(ReadString(payload, "timeOfDayText", "unknown time of day"), 120));
            builder.AppendLine("External hero id: " + LimitText(ReadString(payload, "externalHeroId", ""), 160));
            builder.AppendLine("External context: " + LimitText(ReadString(payload, "externalContext", ""), 700));
            builder.AppendLine();
            AppendWildernessVarietyPrompt(builder, payload, direction ?? SelectWildernessDirection(payload));
            var openingParticipants = (participants ?? new List<Dictionary<string, object>>()).Take(WildernessParticipantLimit).ToList();
            if (openingParticipants.Count > 0)
                builder.AppendLine("Initiating participant id: " + LimitText(CharacterIdFrom(openingParticipants[RandomNumberGenerator.GetInt32(openingParticipants.Count)]), 160)
                    + ". Give this person the initiating action or question; other listed people may react. Adapt the direction to their established character rather than forcing a new trait.");
            builder.AppendLine("Participants:");
            foreach (Dictionary<string, object> participant in openingParticipants)
            {
                string heroId = CharacterIdFrom(participant);
                Dictionary<string, object> stack = loadPassiveStack != null
                    ? loadPassiveStack(heroId, participant)
                    : LoadPassiveCharacterStack(campaignId, heroId, participant);
                builder.AppendLine("- " + Json.Serialize(WildernessCharacterBrief(stack, participant)));
            }

            builder.AppendLine();
            builder.AppendLine("Rules:");
            builder.AppendLine("- Time of day must affect lighting, visibility, fatigue, privacy, or travel routine.");
            builder.AppendLine("- If terrain_key is water, frame the scene around travel by water.");
            builder.AppendLine("- approach_description shows the concrete incident and what makes it worth engaging with.");
            builder.AppendLine("- opening_text continues that incident and creates a specific opportunity to join in; do not assume the player has moved, spoken or acted.");
            builder.AppendLine("- player_hook gives the player room to respond without forcing their words or thoughts.");
            builder.AppendLine("- hidden_context is private GM-only depth. Do not reveal it directly in approach_description or opening_text.");
            builder.AppendLine("- Keep stakes personal and social.");
            builder.AppendLine();
            builder.AppendLine("JSON schema:");
            builder.AppendLine("{");
            builder.AppendLine("  \"title\": \"short event title\",");
            builder.AppendLine("  \"approach_description\": \"2-4 sentences showing a concrete incident\",");
            builder.AppendLine("  \"opening_text\": \"2-5 sentences continuing the distinct activity and social situation\",");
            builder.AppendLine("  \"player_hook\": \"1-2 sentences giving the player room to respond\",");
            builder.AppendLine("  \"participant_ids\": [\"hero_id_from_list\"],");
            builder.AppendLine("  \"external_hero_id\": \"outside hero id or empty string\",");
            builder.AppendLine("  \"external_context\": \"why the outside NPC is plausibly nearby, or empty string\",");
            builder.AppendLine("  \"terrain_key\": " + Json.Serialize(LimitText(ReadString(payload, "terrainKey", "plain"), 80)) + ",");
            builder.AppendLine("  \"emotional_pressure\": \"one concise pressure\",");
            builder.AppendLine("  \"surface_clues\": [\"visible clue, oddity, emotional tell, or contradiction\"],");
            builder.AppendLine("  \"hidden_context\": \"private depth explaining what is really going on\",");
            builder.AppendLine("  \"discovery_routes\": [\"how the player can uncover that depth through conversation\"]");
            builder.AppendLine("}");
            return builder.ToString();
        }

        private static string StringListText(List<string> values)
        {
            return values == null || values.Count == 0 ? string.Empty : string.Join("; ", values);
        }

        private static string LimitText(string text, int max)
        {
            text = (text ?? string.Empty).Trim();
            if (max <= 0 || text.Length <= max)
            {
                return text;
            }

            return text.Substring(0, max).TrimEnd();
        }

        private static Dictionary<string, object> PortraitRegister(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", "default");
            string heroId = ReadFirstString(payload, "heroStringId", "heroId", "characterId");
            string characterObjectId = ReadString(payload, "characterObjectId", "");
            string cacheKey = ReadString(payload, "cacheKey", "");
            string filePath = ReadString(payload, "filePath", "");
            string source = ReadString(payload, "source", "game");
            if (string.IsNullOrWhiteSpace(heroId))
            {
                heroId = ResolveHeroIdByCharacterObjectId(campaignId, characterObjectId);
            }

            if (string.IsNullOrWhiteSpace(filePath) || !File.Exists(filePath))
            {
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "portrait filePath was not found." };
            }

            string safeFileName = source == "source" ? "source.png" : "portrait.png";
            string destination;
            bool resolved = !string.IsNullOrWhiteSpace(heroId);
            if (resolved)
            {
                destination = CharacterFile(campaignId, heroId, "portraits", safeFileName);
            }
            else
            {
                destination = Path.Combine(CampaignDirectory(campaignId), "portraits", "unresolved", SafePathSegment(cacheKey, "unknown"), safeFileName);
            }

            lock (FileLock)
            {
                Directory.CreateDirectory(Path.GetDirectoryName(destination));
                File.Copy(filePath, destination, true);
            }

            Dictionary<string, object> meta = new Dictionary<string, object>
            {
                ["campaignId"] = campaignId,
                ["heroStringId"] = heroId ?? "",
                ["characterObjectId"] = characterObjectId ?? "",
                ["cacheKey"] = cacheKey ?? "",
                ["source"] = source,
                ["originalPath"] = filePath,
                ["storedPath"] = destination,
                ["updatedUtc"] = DateTime.UtcNow.ToString("o")
            };

            if (resolved)
            {
                WriteJsonObject(CharacterFile(campaignId, heroId, "portraits", "portrait.json"), meta);
            }
            else
            {
                WriteJsonObject(Path.Combine(Path.GetDirectoryName(destination), "portrait.json"), meta);
            }

            LogOperational("portrait.register", meta);
            return new Dictionary<string, object>
            {
                ["ok"] = true,
                ["campaignId"] = campaignId,
                ["heroStringId"] = heroId ?? "",
                ["resolved"] = resolved,
                ["path"] = destination
            };
        }

        private static Dictionary<string, object> PortraitStatus(Dictionary<string, object> payload, Dictionary<string, string> query)
        {
            payload = payload ?? new Dictionary<string, object>();
            query = query ?? new Dictionary<string, string>();
            string campaignId = ReadString(payload, "campaignId", query.ContainsKey("campaignId") ? query["campaignId"] : "default");
            string heroId = ReadFirstString(payload, "heroStringId", "heroId", "characterId");
            if (string.IsNullOrWhiteSpace(heroId) && query.ContainsKey("heroStringId"))
            {
                heroId = query["heroStringId"];
            }

            if (string.IsNullOrWhiteSpace(heroId))
            {
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "heroStringId is required." };
            }

            string portraitPath = CharacterFile(campaignId, heroId, "portraits", "portrait.png");
            string metaPath = CharacterFile(campaignId, heroId, "portraits", "portrait.json");
            return new Dictionary<string, object>
            {
                ["ok"] = true,
                ["campaignId"] = campaignId,
                ["heroStringId"] = heroId,
                ["exists"] = File.Exists(portraitPath),
                ["portraitPath"] = portraitPath,
                ["metadata"] = ReadJsonObject(metaPath)
            };
        }

        private static Dictionary<string, object> PortraitDiagnose(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", LatestCampaignId());
            string heroId = ReadFirstString(payload, "heroStringId", "heroId", "characterId");
            string characterObjectId = ReadString(payload, "characterObjectId", "");
            string cacheKey = ReadString(payload, "cacheKey", "");
            if (string.IsNullOrWhiteSpace(heroId))
            {
                heroId = ResolveHeroIdByCharacterObjectId(campaignId, characterObjectId);
            }

            string characterDir = string.IsNullOrWhiteSpace(heroId) ? "" : CharacterDirectory(campaignId, heroId);
            string portraitDir = string.IsNullOrWhiteSpace(characterDir) ? "" : Path.Combine(characterDir, "portraits");
            string customPath = string.IsNullOrWhiteSpace(portraitDir) ? "" : Path.Combine(portraitDir, "custom.png");
            string portraitPath = string.IsNullOrWhiteSpace(portraitDir) ? "" : Path.Combine(portraitDir, "portrait.png");
            string sourcePath = string.IsNullOrWhiteSpace(portraitDir) ? "" : Path.Combine(portraitDir, "source.png");
            string cacheCampaignDir = CampaignPortraitCacheDirectory(campaignId);
            string cacheFolder = string.IsNullOrWhiteSpace(cacheKey) || string.IsNullOrWhiteSpace(cacheCampaignDir) ? "" : Path.Combine(cacheCampaignDir, cacheKey);
            string cacheCustomPath = string.IsNullOrWhiteSpace(cacheFolder) ? "" : Path.Combine(cacheFolder, "custom.png");
            string cachePortraitPath = string.IsNullOrWhiteSpace(cacheFolder) ? "" : Path.Combine(cacheFolder, "portrait.png");
            string cacheSourcePath = string.IsNullOrWhiteSpace(cacheFolder) ? "" : Path.Combine(cacheFolder, "source.png");
            string cachePromptPath = string.IsNullOrWhiteSpace(cacheFolder) ? "" : Path.Combine(cacheFolder, "prompt.txt");
            string indexPath = string.IsNullOrWhiteSpace(cacheCampaignDir) ? "" : Path.Combine(cacheCampaignDir, "index.json");
            int indexMatchCount = 0;
            try
            {
                if (File.Exists(indexPath) && !string.IsNullOrWhiteSpace(cacheKey))
                {
                    Dictionary<string, object> index = Json.Deserialize<Dictionary<string, object>>(File.ReadAllText(indexPath, Encoding.UTF8)) ?? new Dictionary<string, object>();
                    indexMatchCount = index.Values.Count(x => string.Equals(Convert.ToString(x), cacheKey, StringComparison.OrdinalIgnoreCase));
                }
            }
            catch
            {
                indexMatchCount = -1;
            }

            string preferredPath = "";
            if (!string.IsNullOrWhiteSpace(cacheCustomPath) && File.Exists(cacheCustomPath))
            {
                preferredPath = cacheCustomPath;
            }
            else if (!string.IsNullOrWhiteSpace(cachePortraitPath) && File.Exists(cachePortraitPath))
            {
                preferredPath = cachePortraitPath;
            }
            else if (!string.IsNullOrWhiteSpace(customPath) && File.Exists(customPath))
            {
                preferredPath = customPath;
            }
            else if (!string.IsNullOrWhiteSpace(portraitPath) && File.Exists(portraitPath))
            {
                preferredPath = portraitPath;
            }

            Dictionary<string, object> response = new Dictionary<string, object>
            {
                ["ok"] = true,
                ["campaignId"] = campaignId,
                ["heroStringId"] = heroId ?? "",
                ["characterObjectId"] = characterObjectId ?? "",
                ["cacheKey"] = cacheKey ?? "",
                ["dataDir"] = DataDir,
                ["moduleDir"] = Reign.Core.Contracts.Platform.ReignInstallation.TryLoadCurrent()?.ModuleRoot ?? "",
                ["cacheCampaignDir"] = cacheCampaignDir,
                ["cacheCampaignDirExists"] = !string.IsNullOrWhiteSpace(cacheCampaignDir) && Directory.Exists(cacheCampaignDir),
                ["cacheFolder"] = cacheFolder,
                ["cacheFolderExists"] = !string.IsNullOrWhiteSpace(cacheFolder) && Directory.Exists(cacheFolder),
                ["cacheCustomPath"] = cacheCustomPath,
                ["cacheCustomExists"] = !string.IsNullOrWhiteSpace(cacheCustomPath) && File.Exists(cacheCustomPath),
                ["cachePortraitPath"] = cachePortraitPath,
                ["cachePortraitExists"] = !string.IsNullOrWhiteSpace(cachePortraitPath) && File.Exists(cachePortraitPath),
                ["cacheSourcePath"] = cacheSourcePath,
                ["cacheSourceExists"] = !string.IsNullOrWhiteSpace(cacheSourcePath) && File.Exists(cacheSourcePath),
                ["cachePromptPath"] = cachePromptPath,
                ["cachePromptExists"] = !string.IsNullOrWhiteSpace(cachePromptPath) && File.Exists(cachePromptPath),
                ["indexPath"] = indexPath,
                ["indexExists"] = !string.IsNullOrWhiteSpace(indexPath) && File.Exists(indexPath),
                ["indexMatchCount"] = indexMatchCount,
                ["preferredPath"] = preferredPath,
                ["preferredExists"] = !string.IsNullOrWhiteSpace(preferredPath) && File.Exists(preferredPath),
                ["textureFactoryReported"] = payload.ContainsKey("textureFactoryHas"),
                ["textureFactoryHas"] = ReadBool(payload, "textureFactoryHas", false),
                ["activeWidgetIds"] = ReadStringList(payload, "activeWidgetIds"),
                ["characterDir"] = characterDir,
                ["characterDirExists"] = !string.IsNullOrWhiteSpace(characterDir) && Directory.Exists(characterDir),
                ["portraitDir"] = portraitDir,
                ["portraitDirExists"] = !string.IsNullOrWhiteSpace(portraitDir) && Directory.Exists(portraitDir),
                ["customPath"] = customPath,
                ["customExists"] = !string.IsNullOrWhiteSpace(customPath) && File.Exists(customPath),
                ["portraitPath"] = portraitPath,
                ["portraitExists"] = !string.IsNullOrWhiteSpace(portraitPath) && File.Exists(portraitPath),
                ["sourcePath"] = sourcePath,
                ["sourceExists"] = !string.IsNullOrWhiteSpace(sourcePath) && File.Exists(sourcePath),
                ["profile"] = string.IsNullOrWhiteSpace(characterDir) ? new Dictionary<string, object>() : ReadJsonObject(Path.Combine(characterDir, "profile.json")),
                ["metadata"] = string.IsNullOrWhiteSpace(portraitDir) ? new Dictionary<string, object>() : ReadJsonObject(Path.Combine(portraitDir, "portrait.json"))
            };
            LogOperational("portrait.diagnose", response);
            return response;
        }

        private static Dictionary<string, object> PortraitRequest(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", "default");
            string heroId = ReadFirstString(payload, "heroStringId", "heroId", "characterId");
            string cacheKey = ReadString(payload, "cacheKey", "");
            Dictionary<string, object> row = new Dictionary<string, object>
            {
                ["id"] = Guid.NewGuid().ToString("N"),
                ["ts"] = DateTimeOffset.UtcNow.ToUnixTimeSeconds(),
                ["campaignId"] = campaignId,
                ["heroStringId"] = heroId,
                ["cacheKey"] = cacheKey,
                ["payload"] = payload
            };
            AppendJsonLineToPath(Path.Combine(CampaignDirectory(campaignId), "portraits", "requests.jsonl"), row);
            LogOperational("portrait.request", row);
            return new Dictionary<string, object> { ["ok"] = true, ["request"] = row };
        }

        private static Dictionary<string, object> UpsertCharacterProfile(string campaignId, Dictionary<string, object> hero)
        {
            if (hero == null)
            {
                throw new InvalidOperationException("Hero profile is empty.");
            }

            string heroId = CharacterIdFrom(hero);
            if (string.IsNullOrWhiteSpace(heroId))
            {
                throw new InvalidOperationException("heroStringId is required.");
            }

            string dir = CharacterDirectory(campaignId, heroId);
            Directory.CreateDirectory(dir);
            Directory.CreateDirectory(Path.Combine(dir, "memory"));
            Directory.CreateDirectory(Path.Combine(dir, "history"));
            Directory.CreateDirectory(Path.Combine(dir, "portraits"));
            string profilePath = Path.Combine(dir, "profile.json");
            bool created = !File.Exists(profilePath);
            Dictionary<string, object> existingProfile = created ? new Dictionary<string, object>() : ReadJsonObject(profilePath);
            Dictionary<string, object> profile = new Dictionary<string, object>(hero, StringComparer.OrdinalIgnoreCase)
            {
                ["campaignId"] = campaignId,
                ["heroStringId"] = heroId,
                ["updatedUtc"] = DateTime.UtcNow.ToString("o")
            };
            string preservedNativeDescription = FirstNonEmpty(
                ReadString(existingProfile, "nativeEncyclopediaText", ""),
                ReadString(hero, "nativeEncyclopediaText", ""),
                created ? ReadString(hero, "encyclopediaText", "") : "");
            if (!string.IsNullOrWhiteSpace(preservedNativeDescription))
            {
                profile["nativeEncyclopediaText"] = preservedNativeDescription;
            }
            if (created)
            {
                profile["createdUtc"] = DateTime.UtcNow.ToString("o");
            }
            else if (existingProfile.ContainsKey("createdUtc"))
            {
                profile["createdUtc"] = existingProfile["createdUtc"];
            }

            PreserveCommonerHousehold(profile, existingProfile);
            if (!profile.ContainsKey("narrativeVersion") && existingProfile.ContainsKey("narrativeVersion"))
                profile["narrativeVersion"] = existingProfile["narrativeVersion"];
            profile = WithNarrativeCampaignVersion(campaignId, profile);
            PreserveWandererIdentity(profile, existingProfile);
            WriteJsonObject(profilePath, profile);
            WriteCampaignMetadata(campaignId, profile);
            EnsureJsonObjectFile(Path.Combine(dir, "template.json"), LoadCharacterTemplate(heroId, profile));
            EnsureJsonObjectFile(Path.Combine(dir, "characteristics.json"), DefaultCharacteristics(hero));
            Dictionary<string, object> suppliedWealth = ReadDictionary(profile, "wealth");
            string wealthPath = Path.Combine(dir, "wealth.json");
            if (suppliedWealth != null && suppliedWealth.Count > 0)
            {
                WriteJsonObject(wealthPath, NormalizeObservedWealth(suppliedWealth));
            }
            else
            {
                Dictionary<string, object> existingWealth = ReadJsonObject(wealthPath);
                if (!IsObservedWealth(existingWealth))
                    WriteJsonObject(wealthPath, UnknownWealth(hero));
            }
            WriteJsonObject(Path.Combine(dir, "inventory.json"), DictionaryOrDefault(profile, "inventory", DefaultInventory(hero)));
            WriteJsonObject(Path.Combine(dir, "appearance.json"), DictionaryOrDefault(profile, "appearance", DefaultAppearance(hero)));
            EnsureJsonObjectFile(Path.Combine(dir, "motivations.json"), DefaultMotivations(hero));
            EnsureJsonObjectFile(Path.Combine(dir, "secrets.json"), DefaultSecrets(hero));
            EnsureJsonObjectFile(Path.Combine(dir, "state.json"), DefaultCharacterState(hero));
            EnsureJsonObjectFile(Path.Combine(dir, "pressure.json"), DefaultPressure(hero));
            EnsureJsonObjectFile(Path.Combine(dir, "memory", "summary.json"), new Dictionary<string, object>
            {
                ["version"] = 1,
                ["summary"] = "",
                ["updatedUtc"] = ""
            });
            EnsureJsonObjectFile(Path.Combine(dir, "portraits", "portrait_meta.json"), new Dictionary<string, object>
            {
                ["version"] = 1,
                ["status"] = "not_generated"
            });
            EnsureFile(Path.Combine(dir, "memory", "memories.jsonl"));
            EnsureJsonObjectFile(Path.Combine(dir, "memory", "relationships.json"), new Dictionary<string, object> { ["version"] = 1 });
            EnsureFile(Path.Combine(dir, "history", "dialogue.jsonl"));
            EnsureFile(Path.Combine(dir, "history", "events.jsonl"));
            EnsureFile(Path.Combine(dir, "history", "decisions.jsonl"));
            WriteJsonObject(Path.Combine(dir, "schema_manifest.json"), CharacterSchemaManifest(campaignId, heroId, profile));
            UpdateCharacterIndex(campaignId, profile);
            Dictionary<string, object> foundation = MaterializeCharacterProfile(campaignId, heroId, profile, false, false);

            return new Dictionary<string, object>
            {
                ["ok"] = true,
                ["created"] = created,
                ["campaignId"] = campaignId,
                ["heroStringId"] = heroId,
                ["path"] = dir,
                ["foundation"] = foundation
            };
        }

