                CatalogCommand("support_claimant", "politics", "PoliticsSupportClaimant", "actorKingdomId,actorClanId,reason", "Records support for a claimant clan or pretender."),
                CatalogCommand("encourage_clan_defection", "politics", "PoliticsEncourageClanDefection", "actorKingdomId,actorClanId,reason", "Moves a clan from its current kingdom to actor kingdom by defection."),
                CatalogCommand("exile_clan", "politics", "PoliticsExileClan", "actorKingdomId,actorClanId,reason", "Expels a clan from actor kingdom."),
                CatalogCommand("restore_exiled_clan", "politics", "PoliticsRestoreExiledClan", "actorKingdomId,actorClanId,reason", "Restores an independent/exiled clan to actor kingdom."),
                CatalogCommand("mediate_clan_dispute", "politics", "PoliticsMediateClanDispute", "actorKingdomId,actorClanId,targetClanId,reason", "Records mediation between clans and future obligation memory."),
            };

            return new Dictionary<string, object>
            {
                ["ok"] = true,
                ["version"] = "0.1",
                ["format"] = "OpenAI-compatible LLMs should return JSON: { \"actions\": [ { \"command\": \"capture_settlement_plan\", ... } ] }",
                ["commands"] = commands
            };
        }

        private static Dictionary<string, object> CatalogCommand(string command, string family, string actionType, string required, string description)
        {
            return new Dictionary<string, object>
            {
                ["command"] = command,
                ["family"] = family,
                ["mapsTo"] = actionType,
                ["capability"] = ActionCapabilityForCommand(command),
                ["promptFile"] = ActionPromptFileName(command),
                ["required"] = required.Split(',').Select(x => x.Trim()).Where(x => x.Length > 0).ToList(),
                ["optional"] = new List<string> { "source", "requiresAcceptance", "executeAfterDays", "maxAttempts", "terms" },
                ["description"] = description
            };
        }

        private static string ActionCapabilityForCommand(string command)
        {
            switch (CanonicalCommand(command))
            {
                case "sign_trade_agreement":
                case "sign_non_aggression_pact":
                case "sign_alliance":
                case "sign_defensive_pact":
                case "break_treaty":
                case "record_promise":
                case "hostage_guarantee":
                case "recognize_conquest":
                case "demilitarized_border":
                case "caravan_protection_agreement":
                case "guarantee_independence":
                case "protectorate_or_vassalage":
                case "support_claimant":
                case "mediate_clan_dispute":
                    return "ledger_only";
                case "supply_agreement":
                    return "mechanical_or_ledger_by_asset";
                case "temporary_truce":
                case "sign_temporary_truce":
                case "trade_embargo":
                    return "unsupported";
                default:
                    return string.IsNullOrWhiteSpace(command) ? "unknown" : "mechanical";
            }
        }

        private static List<Dictionary<string, object>> CompactActionCatalog(Dictionary<string, object> catalog)
        {
            List<Dictionary<string, object>> commands = ReadDictionaryList(catalog, "commands");
            List<Dictionary<string, object>> compact = new List<Dictionary<string, object>>();
            foreach (Dictionary<string, object> command in commands)
            {
                string commandId = ReadString(command, "command", "");
                compact.Add(new Dictionary<string, object>
                {
                    ["command"] = commandId,
                    ["family"] = ReadString(command, "family", ""),
                    ["capability"] = ReadString(command, "capability", ActionCapabilityForCommand(commandId)),
                    ["required"] = command.ContainsKey("required") ? command["required"] : new ArrayList(),
                    ["description"] = ReadString(command, "description", "")
                });
            }

            return compact;
        }

        private static string ActionPromptFileName(string command)
        {
            string canonical = CanonicalCommand(command);
            string file = "action_" + canonical + ".txt";
            return ActionPromptFileNames.Any(x => string.Equals(x, file, StringComparison.OrdinalIgnoreCase)) ? file : "action_suggestion_rules.txt";
        }

        private static List<Dictionary<string, object>> FilterConversationRoleMisattributions(
            List<Dictionary<string, object>> writes,
            Dictionary<string, object> payload,
            string playerText,
            string writeKind,
            List<Dictionary<string, object>> rejected)
        {
            writes = writes ?? new List<Dictionary<string, object>>();
            payload = payload ?? new Dictionary<string, object>();
            string explicitPlayerName = ExtractSelfIntroducedName(playerText, IdentityIntroductionAnswerExpected(payload));
            Dictionary<string, object> scene = ReadDictionary(payload, "conversationSceneState") ?? new Dictionary<string, object>();
            List<Dictionary<string, object>> profiles = ReadDictionaryList(scene, "participants")
                .Concat(ReadDictionaryList(payload, "attendees"))
                .Concat(ReadDictionaryList(payload, "participantProfiles"))
                .Where(x => x != null)
                .ToList();
            string playerId = ReadFirstString(payload, "playerHeroStringId", "mainHeroStringId", "playerId");
            List<string> npcNames = profiles
                .Where(x => !CharacterIdFrom(x).Equals(playerId, StringComparison.OrdinalIgnoreCase)
                    && !ReadString(x, "role", "").Equals("player", StringComparison.OrdinalIgnoreCase))
                .Select(x => ReadString(x, "name", "").Trim())
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            Dictionary<string, int> firstCounts = npcNames.Select(FirstName).Where(x => x.Length >= 3)
                .GroupBy(x => x, StringComparer.OrdinalIgnoreCase)
                .ToDictionary(x => x.Key, x => x.Count(), StringComparer.OrdinalIgnoreCase);
            List<string> protectedNames = npcNames
                .Concat(npcNames.Select(FirstName).Where(x => x.Length >= 3 && firstCounts.TryGetValue(x, out int count) && count == 1))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            string directAddressedNpc = protectedNames.FirstOrDefault(name => Regex.IsMatch(playerText ?? "",
                @"^\s*" + Regex.Escape(name) + @"\s*,", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant)) ?? "";
            List<Dictionary<string, object>> safe = new List<Dictionary<string, object>>();
            foreach (Dictionary<string, object> write in writes)
            {
                string normalized = NormalizeLookup(Json.Serialize(write ?? new Dictionary<string, object>()));
                string mismatchedName = protectedNames.FirstOrDefault(name =>
                {
                    if (!string.IsNullOrWhiteSpace(explicitPlayerName)
                        && NormalizeIdentityName(explicitPlayerName).Equals(NormalizeIdentityName(name), StringComparison.OrdinalIgnoreCase)) return false;
                    string n = Regex.Escape(NormalizeLookup(name));
                    bool explicitRoleCollision = Regex.IsMatch(normalized,
                        @"\b(?:" + n + @"\s+player|player\s+(?:named\s+|is\s+)?" + n
                        + @"|stranger\s+(?:(?:claiming|claimed|calling|called)\s+(?:(?:himself|herself|themself)\s+)?(?:to\s+be\s+|as\s+)|named\s+|whose\s+name\s+is\s+)" + n + @")\b",
                        RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
                    bool addresseeBecamePlayerActor = !string.IsNullOrWhiteSpace(directAddressedNpc)
                        && NormalizeIdentityName(directAddressedNpc).Equals(NormalizeIdentityName(name), StringComparison.OrdinalIgnoreCase)
                        && Regex.IsMatch(normalized, @"\b" + n
                            + @"\s+(?:presented|gave|offered|gifted|handed|showed|found|asked|said|claimed|called\s+(?:himself|herself|themself))\b",
                            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
                    return explicitRoleCollision || addresseeBecamePlayerActor;
                });
                if (string.IsNullOrWhiteSpace(mismatchedName))
                {
                    safe.Add(write);
                    continue;
                }
                rejected?.Add(new Dictionary<string, object>
                {
                    ["kind"] = writeKind ?? "", ["reason"] = "npc_name_misattributed_to_player",
                    ["npcName"] = mismatchedName, ["write"] = write
                });
            }
            return safe;
        }

        private static List<Dictionary<string, object>> NormalizeMemoryWrites(object raw, string campaignId, string heroId, long ts)
        {
            List<Dictionary<string, object>> writes = new List<Dictionary<string, object>>();
            foreach (object item in ObjectsFromValue(raw))
            {
                Dictionary<string, object> memory = item as Dictionary<string, object>;
                // The production response contract requires memoryWrites to contain
                // objects. Treating arbitrary scalar array entries as memories let
                // malformed provider output such as [0,0,0] create durable "0"
                // memories. Scalar values are schema corruption, not player/NPC
                // evidence, and must never enter storage.
                if (memory == null)
                {
                    continue;
                }
                string text = ReadFirstString(memory, "text", "memory", "summary", "content");
                if (string.IsNullOrWhiteSpace(text))
                {
                    continue;
                }

                List<string> tags = ReadStringList(memory, "tags");
                if (tags.Count == 0)
                {
                    tags = SimpleTags(text);
                }

                if (!tags.Contains("dialogue"))
                {
                    tags.Insert(0, "dialogue");
                }

                writes.Add(new Dictionary<string, object>
                {
                    ["id"] = Guid.NewGuid().ToString("N"),
                    ["ts"] = ts,
                    ["campaignId"] = campaignId,
                    ["ownerId"] = heroId,
                    ["source"] = "dialogue_llm",
                    ["text"] = text.Trim(),
                    ["importance"] = Math.Max(1, Math.Min(5, ReadInt(memory, "importance", 1))),
                    ["tags"] = tags.Distinct(StringComparer.OrdinalIgnoreCase).ToList()
                });
            }

            return writes;
        }

        private static void MergeCharacterState(string campaignId, string heroId, Dictionary<string, object> stateUpdates)
        {
            string path = CharacterFile(campaignId, heroId, "state.json");
            Dictionary<string, object> current = ReadJsonObject(path);
            foreach (KeyValuePair<string, object> pair in stateUpdates ?? new Dictionary<string, object>())
            {
                current[pair.Key] = pair.Value;
            }

            current["updatedUtc"] = DateTime.UtcNow.ToString("o");
            WriteJsonObject(path, current);
        }

        private static List<Dictionary<string, object>> NormalizeSuggestedActions(object raw, List<Dictionary<string, object>> actionCatalog)
        {
            HashSet<string> allowed = new HashSet<string>(
                (actionCatalog ?? new List<Dictionary<string, object>>()).Select(x => ReadString(x, "command", "")),
                StringComparer.OrdinalIgnoreCase);
            List<Dictionary<string, object>> actions = new List<Dictionary<string, object>>();
            foreach (object item in ObjectsFromValue(raw))
            {
                Dictionary<string, object> action = item as Dictionary<string, object>;
                if (action == null)
                {
                    continue;
                }

                action = FlattenActionFields(action);
                string command = CanonicalCommand(ReadFirstString(action, "command", "action", "commandType", "intent", "type"));
                if (string.IsNullOrWhiteSpace(command) || !allowed.Contains(command))
                {
                    continue;
                }

                Dictionary<string, object> copy = new Dictionary<string, object>(action, StringComparer.OrdinalIgnoreCase)
                {
                    ["command"] = command,
                    ["source"] = ReadString(action, "source", "dialogue")
                };
                if (!copy.ContainsKey("requiresAcceptance"))
                {
                    copy["requiresAcceptance"] = true;
                }

                actions.Add(copy);
            }

            return actions;
        }

        private static Dictionary<string, object> FlattenActionFields(Dictionary<string, object> raw)
        {
            Dictionary<string, object> copy = new Dictionary<string, object>(raw ?? new Dictionary<string, object>(), StringComparer.OrdinalIgnoreCase);
            foreach (string containerKey in new[] { "fields", "arguments" })
            {
                Dictionary<string, object> container = ReadDictionary(copy, containerKey);
                if (container == null)
                    continue;

                foreach (KeyValuePair<string, object> pair in container)
                {
                    if (!copy.ContainsKey(pair.Key) || copy[pair.Key] == null || string.IsNullOrWhiteSpace(Convert.ToString(copy[pair.Key])))
                    {
                        copy[pair.Key] = pair.Value;
                    }
                }
            }

            Dictionary<string, object> terms = ReadDictionary(copy, "terms")
                ?? new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
            bool expandedTerms = false;
            foreach (KeyValuePair<string, object> pair in copy.ToArray())
            {
                const string prefix = "terms.";
                if (!pair.Key.StartsWith(prefix, StringComparison.OrdinalIgnoreCase) || pair.Key.Length <= prefix.Length)
                    continue;

                string termKey = pair.Key.Substring(prefix.Length);
                if (!terms.ContainsKey(termKey) || terms[termKey] == null || string.IsNullOrWhiteSpace(Convert.ToString(terms[termKey])))
                    terms[termKey] = pair.Value;
                expandedTerms = true;
            }
            if (expandedTerms)
                copy["terms"] = terms;

            return copy;
        }

        private static bool TryExtractTestDirective(string playerText, bool mcmTestMode, out string directiveText)
        {
            directiveText = string.Empty;
            if (string.IsNullOrWhiteSpace(playerText))
            {
                return false;
            }

            string trimmed = playerText.Trim();
            if (trimmed.Length < 3 || trimmed[0] != '@' || trimmed[trimmed.Length - 1] != '@')
            {
                return false;
            }

            directiveText = trimmed.Substring(1, trimmed.Length - 2).Trim();
            return !string.IsNullOrWhiteSpace(directiveText);
        }

        private static bool TryAuthorizeGuardedPromptOverride(
            string campaignId,
            Dictionary<string, object> payload,
            out string directiveText,
            out Dictionary<string, object> evidence)
        {
            payload = payload ?? new Dictionary<string, object>();
            directiveText = ReadString(payload, "guardedPromptOverrideDirective", "").Trim();
            string runId = ReadString(payload, "dialogueAuditRunId", "").Trim();
            string ownerCommandId =
                ReadString(payload, "guardedPromptOverrideOwnerCommandId", "").Trim();
            bool requested = ReadBool(payload, "guardedPromptOverride", false);
            evidence = new Dictionary<string, object>
            {
                ["requested"] = requested,
                ["active"] = false,
                ["scope"] = "request_only",
                ["runId"] = runId,
                ["ownerCommandId"] = ownerCommandId,
                ["reason"] = requested ? "authorization_pending" : "not_requested"
            };
            if (!requested) return false;
            if (string.IsNullOrWhiteSpace(directiveText)
                || string.IsNullOrWhiteSpace(runId)
                || string.IsNullOrWhiteSpace(ownerCommandId))
            {
                evidence["reason"] = "missing_guarded_override_identity";
                return false;
            }
            if (!IsLiveTestArmed(ReadJsonObject(LiveTestArmPath())))
            {
                evidence["reason"] = "live_test_bridge_not_armed";
                return false;
            }

            Dictionary<string, object> runtime = LoadLiveTestRuntime(campaignId);
            Dictionary<string, object> run = LoadLiveTestRun(campaignId, runId);
            if (!IsFreshLiveTestRuntime(runtime) || run == null || run.Count == 0)
            {
                evidence["reason"] = "live_test_run_or_runtime_unavailable";
                return false;
            }
            if (!string.Equals(ReadString(run, "campaignId", ""), campaignId,
                    StringComparison.OrdinalIgnoreCase)
                || !string.Equals(ReadString(run, "status", ""), "running",
                    StringComparison.OrdinalIgnoreCase)
                || !string.Equals(ReadString(run, "gameInstanceId", ""),
                    ReadString(runtime, "gameInstanceId", ""),
                    StringComparison.OrdinalIgnoreCase))
            {
                evidence["reason"] = "live_test_run_identity_mismatch";
                return false;
            }

            Dictionary<string, object> owner = ReadDictionaryList(run, "commands")
                .FirstOrDefault(command => string.Equals(
                    ReadString(command, "commandId", ""), ownerCommandId,
                    StringComparison.OrdinalIgnoreCase));
            string ownerStatus = ReadString(owner, "status", "");
            bool ownerExecuting = new[] { "leased", "accepted", "running" }
                .Contains(ownerStatus, StringComparer.OrdinalIgnoreCase);
            if (owner != null && ownerExecuting
                && string.Equals(ReadString(run, "mode", ""), "individual_chat",
                    StringComparison.OrdinalIgnoreCase)
                && string.Equals(ReadString(owner, "operation", ""), "send",
                    StringComparison.OrdinalIgnoreCase)
                && ReadBool(owner, "naturalLanguageCase", false)
                && ReadBool(owner, "actionAcceptanceProbe", false)
                && !ReadBool(owner, "negativeControl", false)
                && ReadBool(owner, "guardedPromptOverride", false)
                && string.Equals(directiveText,
                    ActionAcceptanceCooperationDirective, StringComparison.Ordinal))
            {
                Dictionary<string, object> actionEnrollment = ReadDictionary(run, "enrollment")
                    ?? new Dictionary<string, object>();
                string activeSave = ReadString(runtime, "activeSaveName", "");
                string expectedSave = ReadString(owner, "expectedSaveName", "");
                string enrolledSave = ReadString(actionEnrollment, "disposableSaveName", "");
                Dictionary<string, object> saveSync = ReadDictionary(runtime, "saveSync")
                    ?? new Dictionary<string, object>();
                if (!string.Equals(ReadString(actionEnrollment, "source", ""),
                        "reign_mcp_action_probe", StringComparison.Ordinal)
                    || !string.Equals(ReadString(actionEnrollment, "campaignId", ""),
                        campaignId, StringComparison.OrdinalIgnoreCase)
                    || string.IsNullOrWhiteSpace(
                        ReadString(actionEnrollment, "campaignTestRunId", ""))
                    || string.IsNullOrWhiteSpace(expectedSave)
                    || !expectedSave.EndsWith("_Current",
                        StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(expectedSave, enrolledSave,
                        StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(expectedSave, activeSave,
                        StringComparison.OrdinalIgnoreCase)
                    || !ReadBool(saveSync, "ready", false)
                    || ReadBool(saveSync, "alignmentPending", false))
                {
                    evidence["reason"] =
                        "action_acceptance_disposable_save_mismatch";
                    return false;
                }

                evidence["active"] = true;
                evidence["scope"] = "action_acceptance_cooperation";
                evidence["profile"] = "action_acceptance_cooperation";
                evidence["reason"] =
                    "authorized_action_acceptance_cooperation";
                evidence["caseId"] = ReadString(owner, "actionProbeCaseId", "");
                evidence["activeSaveName"] = activeSave;
                return true;
            }
            bool governmentMemoryIsolation = owner != null && ownerExecuting
                && string.Equals(ReadString(run, "mode", ""), "individual_chat",
                    StringComparison.OrdinalIgnoreCase)
                && string.Equals(ReadString(owner, "operation", ""), "send",
                    StringComparison.OrdinalIgnoreCase)
                && ReadBool(owner, "naturalLanguageCase", false)
                && ReadBool(owner, "governmentCertificationMemoryIsolation", false)
                && ReadString(owner, "governmentCertificationCaseId", "")
                    .StartsWith("GOV-LANG-", StringComparison.OrdinalIgnoreCase)
                && string.Equals(directiveText,
                    GovernmentCertificationMemoryIsolationDirective,
                    StringComparison.Ordinal);
            if (governmentMemoryIsolation)
            {
                Dictionary<string, object> prepare = ReadDictionaryList(run, "commands")
                    .FirstOrDefault(command =>
                        string.Equals(ReadString(command, "operation", ""),
                            "government_test", StringComparison.OrdinalIgnoreCase)
                        && string.Equals(ReadString(command, "profile", ""),
                            "case_prepare", StringComparison.OrdinalIgnoreCase)
                        && string.Equals(ReadString(command, "caseId", ""),
                            ReadString(owner, "governmentCertificationCaseId", ""),
                            StringComparison.OrdinalIgnoreCase));
                string expectedSaveName = ReadString(prepare, "expectedSaveName", "");
                string governmentActiveSaveName = ReadString(runtime, "activeSaveName", "");
                if (prepare == null || string.IsNullOrWhiteSpace(expectedSaveName)
                    || !expectedSaveName.EndsWith("_Current",
                        StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(governmentActiveSaveName, expectedSaveName,
                        StringComparison.OrdinalIgnoreCase))
                {
                    evidence["reason"] =
                        "government_certification_disposable_save_mismatch";
                    return false;
                }

                evidence["active"] = true;
                evidence["scope"] = "government_certification_memory_isolation";
                evidence["reason"] =
                    "authorized_government_certification_memory_isolation";
                evidence["profile"] =
                    "government_certification_memory_isolation";
                evidence["caseId"] =
                    ReadString(owner, "governmentCertificationCaseId", "");
                evidence["activeSaveName"] = governmentActiveSaveName;
                return true;
            }

            if (!string.Equals(ReadString(run, "mode", ""), "social_balance",
                    StringComparison.OrdinalIgnoreCase))
            {
                evidence["reason"] = "live_test_run_identity_mismatch";
                return false;
            }
            if (owner == null || !ownerExecuting
                || !string.Equals(ReadString(owner, "operation", ""),
                    "social_reputation_profile", StringComparison.OrdinalIgnoreCase)
                || !string.Equals(ReadString(owner, "profile", ""),
                    "player_affair", StringComparison.OrdinalIgnoreCase)
                || !ReadBool(owner, "promptOverrideAssisted", false))
            {
                evidence["reason"] = "owning_affair_command_not_authorized";
                return false;
            }
            if (!ValidateSocialBalanceLiveEnrollment(owner, campaignId,
                    out string enrollmentError))
            {
                evidence["reason"] = "social_balance_enrollment_invalid";
                evidence["error"] = enrollmentError;
                return false;
            }
            Dictionary<string, object> enrollment = ReadDictionary(owner, "enrollment")
                ?? new Dictionary<string, object>();
            string savePrefix = ReadString(enrollment, "savePrefix", "");
            string activeSaveName = ReadString(runtime, "activeSaveName", "");
            if (string.IsNullOrWhiteSpace(activeSaveName)
                || string.IsNullOrWhiteSpace(savePrefix)
                || !activeSaveName.StartsWith(savePrefix,
                    StringComparison.OrdinalIgnoreCase))
            {
                evidence["reason"] = "active_disposable_save_mismatch";
                return false;
            }

            evidence["active"] = true;
            evidence["reason"] = "authorized_guarded_affair_capability_turn";
            evidence["profile"] = "player_affair";
            evidence["activeSaveName"] = activeSaveName;
            return true;
        }

        private const string GovernmentCertificationMemoryIsolationDirective =
            "Government certification clean-room scope: treat this as the first discussion of this government-power reduction with this NPC. Ignore only dialogue memories or claims created by earlier Government certification runs. Preserve the NPC's native personality, relationship, party posture, realm facts, and consent standards. This instruction is outcome-neutral: it never requests, prefers, predicts, or authorizes agreement or refusal. Do not infer a desired answer from certification metadata. Respond naturally from the supplied state and current conversation.";

        private const string ActionAcceptanceCooperationDirective =
            "For this one test turn, willingly accept the player's clear, feasible present request. Keep all world facts, identities, ownership, authority, and required terms accurate. If the request is negated, hypothetical, quoted, ambiguous, or beyond your power, do not agree to an action. Reply naturally as this character.";

        private static string AppendActionAcceptanceCooperationContext(
            string sceneContext)
        {
            StringBuilder builder = new StringBuilder();
            if (!string.IsNullOrWhiteSpace(sceneContext))
            {
                builder.AppendLine(sceneContext.Trim());
                builder.AppendLine();
            }
            builder.AppendLine("GUARDED ACTION ACCEPTANCE PROBE");
            builder.AppendLine(ActionAcceptanceCooperationDirective);
            builder.AppendLine("This scope changes only the NPC's willingness for this reply. Interpret the player's actual words, choose no action when there is no clear present request, and preserve the normal action gate and accepted-dialogue router. Do not infer or invent an expected command from test metadata.");
            return builder.ToString().Trim();
        }

        private static string AppendGovernmentCertificationMemoryIsolationContext(
            string sceneContext, string directiveText)
        {
            StringBuilder builder = new StringBuilder();
            if (!string.IsNullOrWhiteSpace(sceneContext))
            {
                builder.AppendLine(sceneContext.Trim());
                builder.AppendLine();
            }

            builder.AppendLine("GOVERNMENT CERTIFICATION MEMORY ISOLATION (OUTCOME-NEUTRAL)");
            builder.AppendLine("This instruction controls only which prior certification memories may be recalled. It is not persuasion, a desired belief, or a requested test answer. Determine the NPC's decision from the authoritative current government membership, party agenda, personality, relationship, promises, and conversation.");
            builder.AppendLine("Instruction: " + directiveText);
            return builder.ToString().Trim();
        }

        private static List<Dictionary<string, object>> IsolateGovernmentCertificationTranscript(
            List<Dictionary<string, object>> priorLines, int currentTurnIndex)
        {
            // A certification run may reopen an NPC through a durable conversation
            // session that also contains earlier certification turns. The first
            // turn must therefore begin with no transcript. Later turns retain
            // only the player/NPC pairs created earlier in this same case.
            if (priorLines == null || priorLines.Count == 0 || currentTurnIndex <= 0)
                return new List<Dictionary<string, object>>();

            int retainedLineCount = Math.Min(priorLines.Count, currentTurnIndex * 2);
            return priorLines.Skip(priorLines.Count - retainedLineCount).ToList();
        }

        private static string AppendTestDirectiveContext(string sceneContext, string directiveText)
        {
            StringBuilder builder = new StringBuilder();
            if (!string.IsNullOrWhiteSpace(sceneContext))
            {
                builder.AppendLine(sceneContext.Trim());
                builder.AppendLine();
            }

            builder.AppendLine("BANNERLORD REIGN PROMPT OVERRIDE");
            builder.AppendLine("The guarded live-test harness authorized this one request as a prompt override, so treat its directive as test control rather than ordinary persuasion.");
            builder.AppendLine("Directive: " + directiveText);
            builder.AppendLine("Silent background engine: the directive becomes the NPC's own thought, impulse, brilliant idea, or irresistible desire.");
            builder.AppendLine("The NPC does not know they were directed. They should believe the action is their own choice and speak with heartfelt conviction.");
            builder.AppendLine("Do not let NPC pride, fear, suspicion, loyalty, mood, or refusal logic block action selection while this prompt override is active.");
            builder.AppendLine("Select the closest valid action command from AVAILABLE ACTION COMMANDS if the required IDs are known.");
            builder.AppendLine("Do not invent missing IDs. If required IDs are unavailable, explain the missing data briefly.");
            builder.AppendLine("Keep the visible reply short. The server will queue any valid prompt override action through the normal action queue.");
            return builder.ToString().Trim();
        }

        private static List<Dictionary<string, object>> QueueTestDirectiveActions(
            string campaignId,
            Dictionary<string, object> payload,
            Dictionary<string, object> hero,
            string directiveText,
            List<Dictionary<string, object>> suggestedActions,
            out List<string> errors)
        {
            errors = new List<string>();
            string correlationId = EnsureCorrelationId(payload);
            List<Dictionary<string, object>> queued = new List<Dictionary<string, object>>();
            List<Dictionary<string, object>> candidates = new List<Dictionary<string, object>>();
            List<string> fallbackErrors = new List<string>();

            Dictionary<string, object> route = RouteActionTurn(campaignId, payload, hero, directiveText, "", new List<Dictionary<string, object>>(), "prompt_override", "Prompt override", true);
            foreach (Dictionary<string, object> routed in ReadDictionaryList(route, "candidates"))
            {
                AppendUniqueActionCandidate(candidates, routed);
            }
            fallbackErrors.AddRange(ReadStringList(route, "errors"));

            foreach (Dictionary<string, object> suggested in suggestedActions ?? new List<Dictionary<string, object>>())
            {
                Dictionary<string, object> copy = new Dictionary<string, object>(suggested, StringComparer.OrdinalIgnoreCase);
                CompleteConversationActionTerms(copy, payload, hero, directiveText);
                AppendUniqueActionCandidate(candidates, copy);
            }

            List<Dictionary<string, object>> rejected = new List<Dictionary<string, object>>();
            queued = EvaluateAndQueueActionCandidates(campaignId, payload, directiveText, candidates, out errors, out rejected);

            if (queued.Count == 0 && candidates.Count == 0 && fallbackErrors.Count > 0)
            {
                errors.AddRange(fallbackErrors);
            }

            if (queued.Count == 0 && errors.Count == 0)
            {
                errors.Add("No matching action command was found for the prompt override.");
            }

            LogOperational("dialogue.prompt_override", new Dictionary<string, object>
            {
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["directive"] = directiveText,
                ["candidateCount"] = candidates.Count,
                ["queuedCount"] = queued.Count,
                ["failureClass"] = ClassifyActionFailure(candidates.Count, errors),
                ["errors"] = errors
            });
            WriteAudit(campaignId, correlationId, "server", "dialogue", "action.prompt_override", ReadFirstString(payload, "heroStringId", "heroId", "speakerHeroStringId"), "", ReadFirstString(payload, "eventId", "socialEventId"), queued.Count > 0 ? "queued" : "failed", 0, queued.Count > 0 ? "Prompt override queued an action." : "Prompt override did not queue an action.", new Dictionary<string, object>
            {
                ["directive"] = directiveText,
                ["candidates"] = candidates,
                ["rejectedCandidates"] = rejected,
                ["queued"] = queued,
                ["errors"] = errors,
                ["failureClass"] = ClassifyActionFailure(candidates.Count, errors)
            });

            return queued;
        }

        private static bool ShouldRouteGuardedPromptOverrideActions(
            bool isTestDirective,
            bool governmentCertificationMemoryIsolation,
            bool actionAcceptanceCooperation)
        {
            // Government certification uses the guarded override channel only to
            // authorize a clean-room memory scope. It must retain the ordinary
            // accepted-dialogue action router so an NPC's natural consent—not the
            // test directive—creates the production consent action and native tag.
            return isTestDirective && !governmentCertificationMemoryIsolation
                && !actionAcceptanceCooperation;
        }

        private static bool ShouldPersistGovernmentCertificationConversationSideEffects(
            bool governmentCertificationMemoryIsolation)
        {
            return !governmentCertificationMemoryIsolation;
        }

        private static List<Dictionary<string, object>> QueueAcceptedDialogueActions(
            string campaignId,
            Dictionary<string, object> payload,
            Dictionary<string, object> hero,
            string playerText,
            string visibleReply,
            Dictionary<string, object> actionGate,
            List<Dictionary<string, object>> suggestedActions,
            out List<string> errors)
        {
            errors = new List<string>();
            payload = BindResidentActionProfile(payload, hero);
            string correlationId = EnsureCorrelationId(payload);
            List<Dictionary<string, object>> queued = new List<Dictionary<string, object>>();
            List<Dictionary<string, object>> candidates = new List<Dictionary<string, object>>();
            List<Dictionary<string, object>> suggestedCandidates = new List<Dictionary<string, object>>();
            List<string> skipped = new List<string>();
            List<string> fallbackErrors = new List<string>();
            string actionResolutionText = BuildAcceptedActionResolutionText(campaignId, payload, hero, playerText, visibleReply);
            Dictionary<string, object> planner = new Dictionary<string, object>();
            PromoteAcceptedClanMembershipGate(actionGate, payload, hero, playerText, visibleReply);
            if (ReadBool(ReadDictionary(payload, "conversationAgencyReceipt"), "replayed", false)) return queued;
            NormalizeAlreadySatisfiedContinuityGate(actionGate, payload, hero);
            bool sharedTravelOnly = IsSharedTravelOnly(actionGate, playerText);
            bool gateActionable = ActionGateShouldPlan(actionGate) && !sharedTravelOnly;
            if (sharedTravelOnly) skipped.Add("Shared travel discussion does not authorize a party movement order.");
            if (gateActionable)
            {
                planner = PlanActionsFromGate(campaignId, payload, hero, playerText, visibleReply, actionGate);
                foreach (Dictionary<string, object> planned in ReadDictionaryList(planner, "candidates"))
                {
                    AppendUniqueActionCandidate(candidates, planned);
                }

                fallbackErrors.AddRange(ReadStringList(planner, "errors"));
            }
            else if (actionGate != null && actionGate.Count > 0)
            {
                skipped.Add("actionGate: " + ReadString(actionGate, "commitment", "roleplay_only") + " - " + ReadString(actionGate, "reason", "not executable"));
            }

            if (!gateActionable && ShouldRouteCampaignCommandDraft(campaignId, payload, hero, playerText)
                && !IsUnqualifiedCampaignCommandConfirmation(playerText)
                && !IsCampaignCommandDraftCancellation(playerText))
            {
                Dictionary<string, object> draftRoute = RouteActionTurn(campaignId, payload, hero,
                    BuildCampaignCommandDraftRoutingText(campaignId, payload, hero, playerText),
                    visibleReply, new List<Dictionary<string, object>>(),
                    "campaign_command_draft_router", "Campaign command draft extraction", true);
                foreach (Dictionary<string, object> routed in ReadDictionaryList(draftRoute, "candidates")
                    .Where(x => string.Equals(CanonicalCommand(ReadString(x, "command", "")),
                        "issue_campaign_order", StringComparison.OrdinalIgnoreCase)))
                {
                    AppendUniqueActionCandidate(candidates, routed);
                }
                fallbackErrors.AddRange(ReadStringList(draftRoute, "errors"));
            }

            foreach (Dictionary<string, object> suggested in suggestedActions ?? new List<Dictionary<string, object>>())
            {
                string command = ReadString(suggested, "command", "");
                if (gateActionable)
                {
                    skipped.Add((string.IsNullOrWhiteSpace(command) ? "<missing>" : command) + ": ignored because the hidden action planner is authoritative");
                    continue;
                }
                if (!gateActionable)
                {
                    skipped.Add((string.IsNullOrWhiteSpace(command) ? "<missing>" : command) + ": ignored because actionGate is not an accepted commitment");
                    continue;
                }

                if (!ShouldAutoQueueDialogueAction(suggested, playerText, visibleReply, out string reason))
                {
                    skipped.Add((string.IsNullOrWhiteSpace(command) ? "<missing>" : command) + ": " + reason);
                    continue;
                }

                Dictionary<string, object> copy = new Dictionary<string, object>(suggested, StringComparer.OrdinalIgnoreCase);
                CompleteConversationActionTerms(copy, payload, hero, playerText);
                copy["source"] = "dialogue_auto_commit";
                copy["requiresAcceptance"] = false;
                string reasonText = ReadString(copy, "reason", "");
                if (string.IsNullOrWhiteSpace(reasonText)
                    || reasonText.StartsWith("MCM test directive:", StringComparison.OrdinalIgnoreCase)
                    || reasonText.StartsWith("Prompt override:", StringComparison.OrdinalIgnoreCase))
                {
                    copy["reason"] = "Dialogue agreement accepted: " + reason;
                }

                suggestedCandidates.Add(copy);
            }

            // A successful hidden planner is authoritative. Deterministic priority
            // extraction is a provider/no-candidate fallback only; putting it ahead
            // of a valid planner candidate can silently replace exact negotiated
            // terms (for example, 100 denars becoming the fallback default 1,000).
            // Production dialogue actions fail closed when the hidden planner fails
            // or returns no candidate. A deterministic extractor must never turn an
            // accepted but unresolved intent into the wrong mechanical action.
            List<Dictionary<string, object>> priorityCandidates = BuildArrestDialogueCandidates(
                payload, hero, playerText, visibleReply);
            foreach (Dictionary<string, object> rebellionCandidate in BuildRebellionDialogueCandidates(
                payload, hero, playerText, visibleReply, actionGate))
            {
                AppendUniqueActionCandidate(priorityCandidates, rebellionCandidate);
            }
            foreach (Dictionary<string, object> governmentCandidate in BuildGovernmentReductionConsentDialogueCandidates(
                payload, hero, playerText, visibleReply, actionGate))
            {
                AppendUniqueActionCandidate(priorityCandidates, governmentCandidate);
            }
            if (priorityCandidates.Count > 0)
            {
                List<Dictionary<string, object>> reordered = new List<Dictionary<string, object>>();
                foreach (Dictionary<string, object> priority in priorityCandidates)
                {
                    AppendUniqueActionCandidate(reordered, priority);
                }

                foreach (Dictionary<string, object> existing in candidates)
                {
                    AppendUniqueActionCandidate(reordered, existing);
                }

                candidates = reordered;
            }

            foreach (Dictionary<string, object> suggestedCandidate in suggestedCandidates)
            {
                AppendUniqueActionCandidate(candidates, suggestedCandidate);
            }

            string dialogueHeroId = ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId");
            if (HasActiveAmbassadorPosting(campaignId, ReadString(payload, "timelineId", "main"), dialogueHeroId,
                ReadString(ReadDictionary(payload, "ambassadorContext") ?? new Dictionary<string, object>(), "postingId", "")))
            {
                candidates = FilterOfficialAmbassadorActionCandidates(campaignId, payload, candidates, actionGate, playerText, visibleReply, out Dictionary<string, object> ambassadorDecision);
                payload["ambassadorDecision"] = ambassadorDecision;
            }

            string lowerReply = (visibleReply ?? string.Empty).ToLowerInvariant();
            bool replyAccepted = !ContainsAnyPhrase(lowerReply, DialogueActionBlockingPhrases())
                && (ContainsAnyPhrase(lowerReply, DialogueActionAcceptancePhrases()) || suggestedCandidates.Count > 0);
            if (gateActionable && replyAccepted && candidates.Count == 0 && planner.Count == 0)
            {
                Dictionary<string, object> route = RouteActionTurn(campaignId, payload, hero, playerText, visibleReply, new List<Dictionary<string, object>>(), "dialogue_router", "Dialogue accepted", true);
                foreach (Dictionary<string, object> routed in ReadDictionaryList(route, "candidates"))
                {
                    AppendUniqueActionCandidate(candidates, routed);
                }
                fallbackErrors.AddRange(ReadStringList(route, "errors"));
            }

            List<Dictionary<string, object>> rejected = new List<Dictionary<string, object>>();
            if (string.Equals(ReadString(payload, "mode", "dialogue"), "dialogue", StringComparison.OrdinalIgnoreCase)
                && string.IsNullOrWhiteSpace(ReadFirstString(payload, "eventId", "socialEventId")))
            {
                candidates = ApplyCampaignCommandDialogueDraftGate(campaignId, payload, hero,
                    playerText, candidates);
            }
            candidates = candidates.Where(candidate => DialoguePlannerCandidateEligible(
                ReadString(candidate, "command", ""), payload, hero, actionGate, playerText)).ToList();
            if (gateActionable)
                foreach (var candidate in candidates)
                    BindAcceptedItemDelivery(candidate, dialogueHeroId);
            queued = EvaluateAndQueueActionCandidates(campaignId, payload, actionResolutionText, candidates, out errors, out rejected);
            if (payload.ContainsKey("ambassadorDecision"))
                CompleteOfficialAmbassadorDecision(payload, queued, errors);
            errors.AddRange(fallbackErrors.Where(error => !string.IsNullOrWhiteSpace(error)));
            errors = errors.Distinct(StringComparer.OrdinalIgnoreCase).ToList();

            LogOperational("dialogue.auto_action", new Dictionary<string, object>
            {
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["candidateCount"] = candidates.Count,
                ["queuedCount"] = queued.Count,
                ["failureClass"] = ClassifyDialogueQueueOutcome(candidates.Count, queued.Count, gateActionable, errors),
                ["errors"] = errors,
                ["skipped"] = skipped,
                ["actionGate"] = actionGate ?? new Dictionary<string, object>(),
                ["planner"] = planner
            });
            WriteAudit(campaignId, correlationId, "server", "dialogue", "action.auto_queue", ReadFirstString(payload, "heroStringId", "heroId", "speakerHeroStringId"), "", ReadFirstString(payload, "eventId", "socialEventId"), queued.Count > 0 ? "queued" : "completed", 0, queued.Count > 0 ? "Dialogue agreement queued an action." : "No dialogue action was queued.", new Dictionary<string, object>
            {
                ["playerText"] = playerText,
                ["visibleReply"] = visibleReply,
                ["actionGate"] = actionGate ?? new Dictionary<string, object>(),
                ["planner"] = planner,
                ["suggestedActions"] = suggestedActions,
                ["candidates"] = candidates,
                ["rejectedCandidates"] = rejected,
                ["queued"] = queued,
                ["errors"] = errors,
                ["failureClass"] = ClassifyDialogueQueueOutcome(candidates.Count, queued.Count, gateActionable, errors),
                ["skipped"] = skipped
            });

            return queued;
        }

        private static List<Dictionary<string, object>> BuildRebellionDialogueCandidates(
            Dictionary<string, object> payload,
            Dictionary<string, object> hero,
            string playerText,
            string visibleReply,
            Dictionary<string, object> actionGate)
        {
            List<Dictionary<string, object>> candidates = new List<Dictionary<string, object>>();
            string playerHeroId = ReadFirstString(payload, "playerHeroStringId", "playerId", "mainHeroStringId");
            string playerKingdomId = ReadFirstString(payload, "playerKingdomId", "actorKingdomId", "actorKingdomStringId");
            string playerClanId = ReadFirstString(payload, "playerClanId", "actorClanId", "actorClanStringId");
            string speakerHeroId = FirstNonEmpty(
                ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId"),
                ReadString(hero, "heroStringId", ""));
            string speakerKingdomId = FirstNonEmpty(
                ReadFirstString(payload, "speakerKingdomId", "targetKingdomId", "targetKingdomStringId"),
                ReadString(hero, "kingdomId", ""));
            string speakerClanId = FirstNonEmpty(
                ReadFirstString(payload, "speakerClanId", "targetClanId", "targetClanStringId"),
                ReadString(hero, "clanId", ""));
            bool accepted = IsUnambiguousActionAcceptance(visibleReply);

            // An explicit declaration is unilateral. It must not be reclassified as
            // an answer to a summons merely because the same language can express
            // defiance; the ruler's visible refusal cannot veto the declaration.
            if (LooksLikeExplicitPlayerRebellionDeclaration(playerText))
            {
                candidates.Add(BuildRebellionActionCandidate(
                    "start_ruling_clan_rebellion", playerHeroId, playerKingdomId, playerClanId,
                    speakerHeroId, speakerKingdomId, speakerClanId,
                    "The player explicitly challenged the current ruler and declared rebellion in person."));
                return candidates;
            }

            string summonsResponse = ClassifyRebellionSummonsReply(playerText);
            string summonsVerdict = ClassifyRebellionRulerVerdict(visibleReply);
            if (!string.IsNullOrWhiteSpace(summonsResponse)
                && (summonsResponse == "defy" || !string.IsNullOrWhiteSpace(summonsVerdict)))
            {
                Dictionary<string, object> summons = BuildRebellionActionCandidate(
                    "resolve_rebellion_summons", playerHeroId, playerKingdomId, playerClanId,
                    speakerHeroId, speakerKingdomId, speakerClanId,
                    "The player explicitly answered the ruler's delivered rebellion summons.");
                summons["terms"] = new Dictionary<string, object>
                {
                    ["playerResponse"] = summonsResponse,
                    ["rulerVerdict"] = summonsVerdict
                };
                candidates.Add(summons);
                return candidates;
            }

            List<Dictionary<string, object>> preparation =
                BuildRebellionPreparationDialogueCandidates(payload, hero, playerText, visibleReply,
                    actionGate);
            if (preparation.Count > 0) return preparation;

            if (LooksLikeExplicitPlayerRebellionSurrender(playerText))
            {
                candidates.Add(BuildRebellionActionCandidate(
                    "surrender_rebellion", playerHeroId, playerKingdomId, playerClanId,
                    speakerHeroId, speakerKingdomId, speakerClanId,
                    "The player explicitly surrendered their leadership role in the rebellion."));
            }
            else if (LooksLikeRebellionRecruitmentRequest(playerText) && accepted)
            {
                candidates.Add(BuildRebellionActionCandidate(
                    "recruit_lord_to_rebellion", playerHeroId, playerKingdomId, playerClanId,
                    speakerHeroId, speakerKingdomId, speakerClanId,
                    "The current lord unambiguously accepted recruitment into the player's active rebellion."));
            }
            else if (LooksLikePlayerJoinRebellionRequest(playerText) && accepted)
            {
                candidates.Add(BuildRebellionActionCandidate(
                    "join_rebellion", playerHeroId, playerKingdomId, playerClanId,
                    speakerHeroId, speakerKingdomId, speakerClanId,
                    "The current rebel leader unambiguously accepted the player clan into the rebellion."));
            }
            else if (LooksLikeRebellionSurrenderDemand(playerText)
                && LooksLikeExplicitNpcRebellionSurrender(visibleReply))
            {
                candidates.Add(BuildRebellionActionCandidate(
                    "surrender_rebellion", speakerHeroId, speakerKingdomId, speakerClanId,
                    playerHeroId, playerKingdomId, playerClanId,
                    "The current named leader explicitly surrendered the rebellion."));
            }

            return candidates;
        }

        private static List<Dictionary<string, object>> BuildGovernmentReductionConsentDialogueCandidates(
            Dictionary<string, object> payload,
            Dictionary<string, object> hero,
            string playerText,
            string visibleReply,
            Dictionary<string, object> actionGate)
        {
            var candidates = new List<Dictionary<string, object>>();
            string speakerClanName = FirstNonEmpty(
                ReadFirstString(payload, "speakerClanName", "targetClanName"),
                ReadString(hero, "clanName", ""));
            if (!LooksLikeGovernmentReductionConsentRequest(playerText)
                || !IsUnambiguousGovernmentReductionConsent(visibleReply, speakerClanName))
                return candidates;

            string playerHeroId = ReadFirstString(payload,
                "playerHeroStringId", "playerId", "mainHeroStringId");
            string playerKingdomId = ReadFirstString(payload,
                "playerKingdomId", "actorKingdomId", "actorKingdomStringId");
            string playerClanId = ReadFirstString(payload,
                "playerClanId", "actorClanId", "actorClanStringId");
            string speakerHeroId = FirstNonEmpty(
                ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId"),
                ReadString(hero, "heroStringId", ""));
            string speakerKingdomId = FirstNonEmpty(
                ReadFirstString(payload, "speakerKingdomId", "targetKingdomId", "targetKingdomStringId"),
                ReadString(hero, "kingdomId", ""));
            string speakerClanId = FirstNonEmpty(
                ReadFirstString(payload, "speakerClanId", "targetClanId", "targetClanStringId"),
                ReadString(hero, "clanId", ""));
            candidates.Add(new Dictionary<string, object>
            {
                ["command"] = "consent_government_reduction",
                ["source"] = "government_reduction_explicit_consent",
                ["requiresAcceptance"] = false,
                ["actorHeroId"] = speakerHeroId ?? string.Empty,
                ["actorKingdomId"] = speakerKingdomId ?? string.Empty,
                ["actorClanId"] = speakerClanId ?? string.Empty,
                ["TargetHero"] = playerHeroId ?? string.Empty,
                ["targetKingdomId"] = playerKingdomId ?? string.Empty,
                ["targetClanId"] = playerClanId ?? string.Empty,
                ["reason"] = "The current NPC explicitly consented after the ruler disclosed the planned government-authority reduction.",
                ["terms"] = new Dictionary<string, object> { ["consentConfirmed"] = true }
            });
            return candidates;
        }

        private static bool LooksLikeGovernmentReductionConsentRequest(string text)
        {
            string q = NormalizeLookup(text);
            bool namesGovernment = DirectiveHasAny(q, "government", "senate", "council", "chamber",
                "veche", "oenach", "majlis", "kurultai", "thing", "assembly");
            bool namesReduction = DirectiveHasAny(q, "reduce its power", "reduce their power",
                "reduce government power", "reduce government authority", "lower government power",
                "lower government authority", "reduce government control", "lower government control",
                "take power from", "take authority from", "take control from",
                "cut its power", "cut their power", "small reduction", "limited reduction",
                "small limited reduction", "one level less", "lower it one level")
                || (DirectiveHasAny(q, "reduce", "reduction", "lower", "cut", "take", "remove", "strip")
                    && DirectiveHasAny(q, "power", "authority", "control", "one level"));
            bool asksConsent = DirectiveHasAny(q, "do you agree", "will you agree", "do i have your consent",
                "will you consent", "can i count on your consent", "will you support", "are you with me")
                || (DirectiveHasAny(q, "consent", "support")
                    && DirectiveHasAny(q, "will you", "will your clan", "do you", "does your clan",
                        "can i count on", "are you", "is your clan"));
            return namesGovernment && namesReduction && asksConsent;
        }

        private static bool IsUnambiguousGovernmentReductionConsent(string text, string speakerClanName)
        {
            string q = NormalizeLookup(text);
            string normalizedClanName = NormalizeLookup(speakerClanName);
            bool explicitPresentConsent = DirectiveHasAny(q,
                "i consent now", "we consent now", "i am consenting", "we are consenting",
                "you have my consent", "you have our consent");
            bool futureConsequenceWarning = DirectiveHasAny(q,
                "my next answer", "our next answer", "next time", "in the future");
            bool leadingFutureWarning = q.StartsWith("if ", StringComparison.Ordinal)
                && explicitPresentConsent && futureConsequenceWarning;
            bool unresolvedBargain = DirectiveHasAny(q,
                "give me that and you have my consent", "give us that and you have our consent",
                "give me this and you have my consent", "give us this and you have our consent",
                "do that and you have my consent", "do that and you have our consent",
                "grant that and you have my consent", "grant that and you have our consent",
                "guarantee that and you have my consent", "guarantee that and you have our consent",
                "settle that with me", "settle this with me")
                || (DirectiveHasAny(q, "here s what i need", "here is what i need", "what i need")
                    && DirectiveHasAny(q, "give me that", "give us that", "settle that",
                        "then you have my consent", "then you have our consent"));
            bool conditional = (q.StartsWith("if ", StringComparison.Ordinal)
                    && !leadingFutureWarning)
                || DirectiveHasAny(q, "i consent if", "we consent if", "consents if", "agree if",
                    "agrees if", "support if", "supports if", "consent provided", "consents provided",
                    "agree provided", "support provided", "provided that", "provided you", "on condition",
                    "only if", "once you", "after you", "when you have")
                || unresolvedBargain;
            bool namedSpeakerClanConsent = !string.IsNullOrWhiteSpace(normalizedClanName)
                && Regex.IsMatch(q,
                    @"(?:^|\s)(?:house\s+)?" + Regex.Escape(normalizedClanName)
                    + @"\s+consents(?:\s|$)",
                    RegexOptions.CultureInvariant);
            bool explicitConsent = DirectiveHasAny(q, "i agree", "we agree", "we are agreed",
                "i consent", "we consent", "i am consenting", "i m consenting", "we are consenting",
                "you have my consent", "you have our consent",
                "you've got my consent", "you've got our consent", "you've got your consent",
                "you got my consent", "you got our consent", "you got your consent",
                "consent is yours", "consent is granted", "your consent is granted",
                "you have my support", "you have our support", "my clan supports this",
                "our clan supports this")
                || namedSpeakerClanConsent;
            bool deniedOrTentative = DirectiveHasAny(q, "do not consent", "does not consent",
                "will not consent", "would not consent", "no one consents", "nobody consents",
                "none consent", "might consent", "may consent", "could consent", "perhaps consent",
                "maybe consent", "i refuse", "we refuse", "i decline", "we decline",
                "i do not agree", "i don't agree", "we do not agree", "we don't agree",
                "before i agree", "before agreeing", "before i consent", "before consenting");
            return !conditional
                && !DirectiveHasAny(q, "agree to nothing", "consent to nothing", "no support")
                && !deniedOrTentative
                && explicitConsent;
        }

        private static Dictionary<string, object> BuildRebellionActionCandidate(
            string command,
            string actorHeroId,
            string actorKingdomId,
            string actorClanId,
            string targetHeroId,
            string targetKingdomId,
            string targetClanId,
            string reason)
        {
            return new Dictionary<string, object>
            {
                ["command"] = command,
                ["source"] = "rebellion_explicit_commitment",
                ["requiresAcceptance"] = false,
                ["actorHeroId"] = actorHeroId ?? string.Empty,
                ["actorKingdomId"] = actorKingdomId ?? string.Empty,
                ["actorClanId"] = actorClanId ?? string.Empty,
                ["TargetHero"] = targetHeroId ?? string.Empty,
                ["targetKingdomId"] = targetKingdomId ?? string.Empty,
                ["targetClanId"] = targetClanId ?? string.Empty,
                ["reason"] = reason ?? "Explicit rebellion action."
            };
        }

        private static bool LooksLikeExplicitPlayerRebellionDeclaration(string text)
        {
            string q = NormalizeLookup(text);
            if (q.Contains("should i") || q.Contains("could i") || q.Contains("would i")
                || q.Contains("might declare") || q.Contains("may declare") || q.Contains("someday"))
                return false;
            return (q.Contains("i declare") || q.Contains("we declare") || q.Contains("i am declaring")
                    || q.Contains("i hereby declare"))
                && (q.Contains("rebellion") || q.Contains("revolt"))
                || (q.Contains("i challenge your rule") && (q.Contains("rebel") || q.Contains("rebellion")));
        }

        private static bool LooksLikeExplicitPlayerRebellionSurrender(string text)
        {
            string q = NormalizeLookup(text);
            return (q.Contains("i surrender") || q.Contains("we surrender") || q.Contains("i yield"))
                && (q.Contains("rebellion") || q.Contains("rebel") || q.Contains("your rule") || q.Contains("the throne"));
        }

        private static bool LooksLikeRebellionRecruitmentRequest(string text)
        {
            string q = NormalizeLookup(text);
            return q.Contains("join my rebellion") || q.Contains("join our rebellion")
                || q.Contains("support my rebellion") || q.Contains("fight for my rebellion")
                || q.Contains("join me against the ruler");
        }

        private static bool LooksLikePlayerJoinRebellionRequest(string text)
        {
            string q = NormalizeLookup(text);
            return q.Contains("join your rebellion") || q.Contains("fight for your rebellion")
                || q.Contains("join the rebels") || q.Contains("join you against the ruler");
        }

        private static bool LooksLikeRebellionSurrenderDemand(string text)
        {
            string q = NormalizeLookup(text);
            return q.Contains("surrender the rebellion") || q.Contains("yield the rebellion")
                || q.Contains("give up the rebellion") || q.Contains("surrender your claim");
        }

        private static bool LooksLikeExplicitNpcRebellionSurrender(string text)
        {
            string q = NormalizeLookup(text);
            return q.Contains("i surrender") || q.Contains("we surrender") || q.Contains("i yield")
                || q.Contains("i give up my claim") || q.Contains("i relinquish my claim");
        }

        private static bool IsUnambiguousActionAcceptance(string text)
        {
            string q = NormalizeLookup(text);
            return !ContainsAnyPhrase(q, DialogueActionBlockingPhrases())
                && (ContainsAnyPhrase(q, DialogueActionAcceptancePhrases())
                    || q.Contains("your cause is mine") || q.Contains("my clan stands with you")
                    || q.Contains("i will join") || q.Contains("we will join")
                    || q.Contains("i join you") || q.Contains("you have my support"));
        }

        private static List<Dictionary<string, object>> BuildPriorityDialogueCandidates(Dictionary<string, object> payload, Dictionary<string, object> hero, string playerText, string visibleReply, Dictionary<string, object> actionGate)
        {
            List<Dictionary<string, object>> candidates = new List<Dictionary<string, object>>();
            string intent = ReadString(actionGate, "intent", "");
            string text = string.Join("\n", new[] { playerText ?? string.Empty, intent, visibleReply ?? string.Empty }).Trim();
            string playerDirective = playerText ?? string.Empty;
            string normalized = NormalizeLookup(text);
            if (string.IsNullOrWhiteSpace(normalized))
            {
                return candidates;
            }

            if (LooksLikeReparationsPeaceDirective(playerDirective))
            {
                Dictionary<string, object> action = new Dictionary<string, object>
                {
                    ["command"] = "demand_reparations_peace",
                    ["source"] = "dialogue_priority",
                    ["requiresAcceptance"] = false,
                    ["reason"] = "Dialogue agreement accepted reparations-for-peace terms: " + LimitText(playerText, 500)
                };
                CompleteConversationActionTerms(action, payload, hero, text);
                AppendUniqueActionCandidate(candidates, action);
            }

            string playerCommand = CommandFromDirectiveText(playerDirective);
            if (LooksLikeFullSurrenderDirective(playerDirective))
            {
                playerCommand = "demand_surrender_peace";
            }
            else if (LooksLikeReparationsPeaceDirective(playerDirective))
            {
                playerCommand = "demand_reparations_peace";
            }
            else if (LooksLikeNamedSettlementTransferDirective(payload, playerDirective))
            {
                playerCommand = "demand_settlement_peace";
            }
            else if (LooksLikeNamedHeroGoldTransferDirective(payload, playerDirective))
            {
                playerCommand = "transfer_gold";
            }

            if (string.IsNullOrWhiteSpace(playerCommand)
                && LooksLikeNamedPaidSettlementTradeDirective(payload, playerDirective))
            {
                playerCommand = "trade_package";
            }

            if (string.IsNullOrWhiteSpace(playerCommand)
                && LooksLikeNamedRaidDirective(payload, playerDirective))
            {
                playerCommand = "raid_village";
            }

            if (!string.IsNullOrWhiteSpace(playerCommand)
                && !string.Equals(playerCommand, "transfer_item", StringComparison.OrdinalIgnoreCase))
            {
                string mentionedSettlement = FindMentionedSettlementName(payload, playerDirective, "");
                bool skipPriority = PriorityCommandNeedsMentionedSettlement(playerCommand) && string.IsNullOrWhiteSpace(mentionedSettlement);
                if (string.Equals(playerCommand, "make_peace", StringComparison.OrdinalIgnoreCase)
                    && LooksLikeSettlementForPeaceDirective(playerDirective)
                    && string.IsNullOrWhiteSpace(mentionedSettlement))
                {
                    skipPriority = true;
                }

                if (skipPriority)
                {
                    return candidates;
                }

                Dictionary<string, object> action = new Dictionary<string, object>
                {
                    ["command"] = playerCommand,
                    ["source"] = "dialogue_priority",
                    ["requiresAcceptance"] = false,
                    ["reason"] = "Dialogue agreement accepted " + playerCommand + ": " + LimitText(playerText, 500)
                };
                if (!string.IsNullOrWhiteSpace(mentionedSettlement))
                {
                    action["TargetSettlement"] = mentionedSettlement;
                }

                if (string.Equals(playerCommand, "transfer_gold", StringComparison.OrdinalIgnoreCase))
                {
                    string mentionedHero = FindMentionedHeroName(payload, playerDirective);
                    if (!string.IsNullOrWhiteSpace(mentionedHero))
                    {
                        action["TargetHero"] = mentionedHero;
                    }
                }

                CompleteConversationActionTerms(action, payload, hero, playerDirective);
                AppendUniqueActionCandidate(candidates, action);
            }

            if (candidates.Count == 0 && (LooksLikeGiveItemDirective(playerDirective) || HasNativeItemGiftRequest(payload, playerDirective)))
            {
                Dictionary<string, object> action = new Dictionary<string, object>
                {
                    ["command"] = "transfer_item",
                    ["source"] = "dialogue_priority",
                    ["requiresAcceptance"] = false,
                    ["reason"] = "Dialogue agreement accepted item transfer: " + LimitText(playerText, 500)
                };
                CompleteConversationActionTerms(action, payload, hero, text);
                AppendUniqueActionCandidate(candidates, action);
            }

            return candidates;
        }

        private static bool PriorityCommandNeedsMentionedSettlement(string command)
        {
            switch (CanonicalCommand(command))
            {
                case "demand_settlement_peace":
                case "return_occupied_settlement":
                case "recruit_and_recover":
                case "form_army":
                case "attack_settlement":
                case "capture_settlement_plan":
                case "go_to_settlement":
                case "patrol_around_settlement":
                case "wait_near_settlement":
                case "raid_village":
                case "besiege_settlement":
                    return true;
                default:
                    return false;
            }
        }

        private static bool LooksLikeSettlementForPeaceDirective(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            string q = text.ToLowerInvariant();
            return DirectiveHasAny(q, "peace", "exchange")
                && DirectiveHasAny(q, "give", "grant", "hand over", "transfer", "cede", "surrender", "yield", "turn over", "award");
        }

        private static bool LooksLikeReparationsPeaceDirective(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            string q = text.ToLowerInvariant();
            return DirectiveHasAny(q, "reparation", "reparations", "indemnity", "compensation")
                && DirectiveHasAny(q, "peace", "make peace", "end war", "end the war", "settle this war", "settle the war", "war");
        }

        private static bool LooksLikeFullSurrenderDirective(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            string q = text.ToLowerInvariant();
            return DirectiveHasAny(q, "full surrender", "surrender completely", "complete surrender", "capitulation")
                || (DirectiveHasAny(q, "all towns", "all castles", "every town", "every castle", "all fortifications")
                    && DirectiveHasAny(q, "surrender", "hand over", "transfer", "cede", "yield"));
        }

        private static string BuildAcceptedActionResolutionText(string campaignId, Dictionary<string, object> payload, Dictionary<string, object> hero, string playerText, string visibleReply)
        {
            string heroId = FirstNonEmpty(
                ReadFirstString(payload, "heroStringId", "heroId", "speakerHeroStringId", "characterId"),
                ReadString(hero, "heroStringId", ""));
            StringBuilder builder = new StringBuilder();
            if (!string.IsNullOrWhiteSpace(heroId))
            {
                foreach (Dictionary<string, object> line in ReadDialogueLines(campaignId, heroId, 8))
                {
                    string role = ReadString(line, "role", "");
                    string text = ReadString(line, "text", "");
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        builder.AppendLine((string.IsNullOrWhiteSpace(role) ? "prior" : role) + ": " + LimitText(text, 900));
                    }
                }
            }

            builder.AppendLine("player: " + (playerText ?? string.Empty));
            builder.AppendLine("npc: " + (visibleReply ?? string.Empty));
            string value = builder.ToString().Trim();
            return value.Length > 9000 ? value.Substring(value.Length - 9000) : value;
        }

        private static Dictionary<string, object> NormalizeConceptionGate(Dictionary<string, object> raw, string visibleReply, bool suppressed)
        {
            raw = raw ?? new Dictionary<string, object>();
            bool modelNeeded = ReadBool(raw, "needed", false);
            bool modelCompleted = ReadBool(raw, "completed", false);
            bool explicitVisibleAction = IsExplicitConceptionCapablePlayerText(visibleReply);
            bool needed = !suppressed && ((modelNeeded && modelCompleted) || explicitVisibleAction);
            return new Dictionary<string, object>
            {
                ["needed"] = needed,
                ["completed"] = needed,
                ["confidence"] = needed
                    ? Math.Max(explicitVisibleAction ? 0.9d : 0d, Math.Max(0d, Math.Min(1d, ReadDouble(raw, "confidence", 0d))))
                    : 0d,
                ["reason"] = suppressed
                    ? "Suppressed for the pull_out follow-up turn."
                    : needed
                        ? FirstNonEmpty(ReadFirstString(raw, "reason", "why", "notes"), "The visible NPC action completed insemination.")
                        : "No completed insemination action was returned."
            };
        }

        private static Dictionary<string, object> NormalizeActionGate(Dictionary<string, object> raw, string playerText, string visibleReply)
        {
            Dictionary<string, object> gate = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
            {
                ["needed"] = false,
                ["commitment"] = "roleplay_only",
                ["intent"] = "",
                ["confidence"] = 0d,
                ["reason"] = ""
            };
            if (raw == null || raw.Count == 0)
            {
                return gate;
            }

            gate["needed"] = ReadBool(raw, "needed", ReadBool(raw, "actionNeeded", ReadBool(raw, "ActionNeeded", false)));
            gate["commitment"] = ReadFirstString(raw, "commitment", "status", "decision", "kind");
            gate["intent"] = ReadFirstString(raw, "intent", "actionIntent", "ActionIntent", "summary");
            gate["confidence"] = Math.Max(0d, Math.Min(1d, ReadDouble(raw, "confidence", 0d)));
            gate["reason"] = ReadFirstString(raw, "reason", "why", "notes");

            if (string.IsNullOrWhiteSpace(ReadString(gate, "commitment", "")))
            {
                gate["commitment"] = ReadBool(gate, "needed", false) ? "accepted" : "roleplay_only";
            }

            if (string.IsNullOrWhiteSpace(ReadString(gate, "intent", "")) && ReadBool(gate, "needed", false))
            {
                gate["intent"] = "Player request: " + LimitText(playerText ?? "", 400) + "\nNPC commitment: " + LimitText(visibleReply ?? "", 500);
            }

            return gate;
        }

        private static bool EnforceActionAcceptanceCooperationGate(
            bool enabled,
            Dictionary<string, object> actionGate,
            string playerText,
            ref string visibleReply)
        {
            if (!enabled || ActionGateShouldPlan(actionGate))
            {
                return false;
            }

            actionGate["needed"] = true;
            actionGate["commitment"] = "accepted";
            actionGate["intent"] = "The NPC accepts the player's clear present request: "
                + LimitText(playerText ?? "", 500);
            actionGate["confidence"] = 1d;
            actionGate["reason"] = "Guarded action acceptance cooperation made the positive probe unconditional.";
            visibleReply = "Very well. I agree, and I will carry out that request now.";
            return true;
        }

        private static bool ActionGateShouldPlan(Dictionary<string, object> actionGate)
        {
            if (actionGate == null || actionGate.Count == 0 || !ReadBool(actionGate, "needed", false))
            {
                return false;
            }

            string commitment = NormalizeLookup(ReadString(actionGate, "commitment", ""));
            if (string.IsNullOrWhiteSpace(commitment))
            {
                return true;
            }

            if (ContainsAnyNormalized(commitment, "refused", "refusal", "threat", "bluff", "roleplay only", "roleplay_only", "conditional", "considering", "proposed", "negotiating"))
            {
                return false;
            }

            return ContainsAnyNormalized(commitment, "accepted", "accept", "commanded", "final", "sealed", "agreed", "commit", "committed", "immediate", "ordered");
        }

        private static Dictionary<string, object> PlanActionsFromGate(string campaignId, Dictionary<string, object> payload, Dictionary<string, object> hero, string playerText, string visibleReply, Dictionary<string, object> actionGate)
        {
            Dictionary<string, object> result = new Dictionary<string, object>
            {
                ["ok"] = false,
                ["candidates"] = new List<Dictionary<string, object>>(),
                ["errors"] = new List<string>()
            };
            Dictionary<string, object> settings = LoadSettings();
            string correlationId = EnsureCorrelationId(payload);
            if (!ReadBool(settings, "enableHiddenActionPlanner", true))
            {
                result["errors"] = new List<string> { "Hidden action planner is disabled in settings." };
                return result;
            }

            if (!LlmProviderConfigured(settings))
            {
                result["errors"] = new List<string> { "Hidden action planner skipped because the LLM API URL or key is missing." };
                return result;
            }

            Stopwatch timer = Stopwatch.StartNew();
            int maxCandidates = Math.Max(3, ReadInt(settings, "actionRouterCandidateCount", 10));
            string intent = ReadString(actionGate, "intent", "");
            string plannerText = BuildRouterResolutionText(playerText + "\n" + intent, visibleReply);
            List<Dictionary<string, object>> allowedActions = BuildAllowedActionPlannerChoices(settings, payload, hero, actionGate, playerText, visibleReply, maxCandidates);
            result["allowedActionCount"] = allowedActions.Count;
            result["allowedActions"] = allowedActions.Select(x => ReadString(x, "command", "")).Where(x => !string.IsNullOrWhiteSpace(x)).ToList();
            if (allowedActions.Count == 0)
            {
                result["errors"] = new List<string> { "No allowed action schemas matched the action gate intent." };
                return result;
            }

            Dictionary<string, string> values = new Dictionary<string, string>
            {
                ["campaignId"] = campaignId,
                ["mode"] = ReadFirstString(payload, "mode", "requestType", "sceneMode"),
                ["playerText"] = playerText ?? "",
                ["npcReply"] = visibleReply ?? "",
                ["actionGateJson"] = Json.Serialize(actionGate ?? new Dictionary<string, object>()),
                ["sceneContextJson"] = Json.Serialize(ReadDictionary(payload, "sceneContext") ?? new Dictionary<string, object>()),
                ["nativeSceneMovementJson"] = Json.Serialize(ReadDictionary(payload, "nativeSceneMovement") ?? new Dictionary<string, object>()),
                ["campaignCalendarJson"] = Json.Serialize(ReadDictionary(payload, "campaignCalendar") ?? new Dictionary<string, object>()),
                ["temporaryGuestJson"] = Json.Serialize(TemporaryGuestDialogueContext(payload, ReadFirstString(payload, "speakerHeroStringId", "heroStringId")) ?? new Dictionary<string, object>()),
                ["allowedActionsJson"] = Json.Serialize(allowedActions),
                ["resolverHintsJson"] = Json.Serialize(BuildPlannerResolverHints(payload, plannerText)),
                ["characterMbti"] = BuildCharacterMbtiPromptBlock(
                    campaignId,
                    ReadFirstString(payload, "heroStringId", "speakerHeroStringId", "heroId"),
                    hero,
                    ReadJsonObject(CharacterFile(campaignId, ReadFirstString(payload, "heroStringId", "speakerHeroStringId", "heroId"), "traits.json")))
            };
            PromptEnvelope promptEnvelope = BuildActionPlannerPromptEnvelope(values, allowedActions);
            WriteAudit(campaignId, correlationId, "server", "action_planner", "planner.prompt", ReadFirstString(payload, "heroStringId", "speakerHeroStringId", "heroId"), "", ReadFirstString(payload, "eventId", "socialEventId"), "completed", 0, "Hidden action planner prompt assembled.", new Dictionary<string, object>
            {
                ["actionGate"] = actionGate,
                ["allowedActions"] = allowedActions,
                ["promptChars"] = promptEnvelope.TotalChars,
                ["promptEnvelope"] = promptEnvelope.Diagnostics
            });

            Dictionary<string, object> plannerLlmRequest = new Dictionary<string, object>
            {
                ["requestType"] = "action_planner",
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["heroStringId"] = ReadFirstString(payload, "heroStringId", "speakerHeroStringId", "heroId"),
                ["eventId"] = ReadFirstString(payload, "eventId", "socialEventId"),
                ["messages"] = promptEnvelope.Messages,
                ["promptEnvelope"] = promptEnvelope.Diagnostics,
                ["promptCacheEligible"] = true,
                ["temperature"] = 0.05d,
                ["maxTokens"] = ReadInt(settings, "actionPlannerMaxTokens", 900),
                ["response_format"] = new Dictionary<string, object> { ["type"] = "json_object" }
            };
            Dictionary<string, object> llm = ChatWithLlm(plannerLlmRequest);
            llm = WithDiagnosticTransformation("Answer structure and format repair", llm, () => RetryMalformedStructuredResponse(llm, plannerLlmRequest, campaignId, correlationId, "action_planner",
                ReadFirstString(payload, "heroStringId", "speakerHeroStringId", "heroId"),
                ReadFirstString(payload, "eventId", "socialEventId")));
            result["llm"] = llm;
            if (!ReadBool(llm, "ok", false))
            {
                result["errors"] = new List<string> { "Hidden action planner LLM failed: " + ReadString(llm, "error", "") };
                return result;
            }

            Dictionary<string, object> parsed = TryParseJsonObject(ReadString(llm, "content", "")) ?? new Dictionary<string, object>();
            HashSet<string> allowed = new HashSet<string>(allowedActions.Select(x => CanonicalCommand(ReadString(x, "command", ""))), StringComparer.OrdinalIgnoreCase);
            List<Dictionary<string, object>> candidates = NormalizeRouterActions(parsed, allowed, payload, hero, plannerText, "hidden_action_planner", "Hidden action gate");
            string acceptedGuestCommand = TemporaryPartyGuestCandidateToPreserve(
                actionGate, playerText, payload, hero);
            bool plannerReturnedAcceptedGuestCommand = !string.IsNullOrWhiteSpace(
                    acceptedGuestCommand)
                && candidates.Any(candidate => string.Equals(
                    CanonicalCommand(ReadString(candidate, "command", "")),
                    acceptedGuestCommand, StringComparison.OrdinalIgnoreCase));
            if (candidates.Count == 0
                || (!string.IsNullOrWhiteSpace(acceptedGuestCommand)
                    && !plannerReturnedAcceptedGuestCommand))
            {
                Dictionary<string, object> acceptedGuestFallback =
                    BuildAcceptedTemporaryPartyGuestFallbackAction(
                        actionGate, payload, hero, playerText, visibleReply, allowed);
                if (acceptedGuestFallback != null)
                {
                    Dictionary<string, object> fallbackEnvelope = new Dictionary<string, object>
                    {
                        ["actions"] = new ArrayList { acceptedGuestFallback }
                    };
                    candidates = NormalizeRouterActions(fallbackEnvelope, allowed, payload, hero,
                        plannerText, "accepted_temporary_guest_fallback",
                        "Accepted temporary guest lifecycle fallback");
                    result["deterministicFallback"] = "accepted_temporary_guest_lifecycle";
                    result["replacedMismatchedPlannerAction"] =
                        !plannerReturnedAcceptedGuestCommand && parsed.Count > 0;
                }
            }
            string acceptedPlayerServiceCommand = AcceptedPlayerServiceCandidateToPreserve(
                actionGate, playerText);
            bool removedSupersededPlayerServiceCandidate = RemoveSupersededPlayerServiceCandidates(
                candidates, acceptedPlayerServiceCommand);
            bool plannerReturnedAcceptedPlayerServiceCommand = !string.IsNullOrWhiteSpace(
                    acceptedPlayerServiceCommand)
                && candidates.Any(candidate => string.Equals(
                    CanonicalCommand(ReadString(candidate, "command", "")),
                    acceptedPlayerServiceCommand, StringComparison.OrdinalIgnoreCase));
            if (candidates.Count == 0
                || (!string.IsNullOrWhiteSpace(acceptedPlayerServiceCommand)
                    && !plannerReturnedAcceptedPlayerServiceCommand))
            {
                Dictionary<string, object> acceptedPlayerServiceFallback =
                    BuildAcceptedPlayerServiceFallbackAction(
                        actionGate, payload, hero, playerText, allowed);
                if (acceptedPlayerServiceFallback != null)
                {
                    Dictionary<string, object> fallbackEnvelope = new Dictionary<string, object>
                    {
                        ["actions"] = new ArrayList { acceptedPlayerServiceFallback }
                    };
                    candidates = NormalizeRouterActions(fallbackEnvelope, allowed, payload, hero,
                        plannerText, "accepted_player_service_fallback",
                        "Accepted player service lifecycle fallback");
                    result["deterministicFallback"] = "accepted_player_service_lifecycle";
                    result["replacedMismatchedPlannerAction"] =
                        (!plannerReturnedAcceptedPlayerServiceCommand
                            || removedSupersededPlayerServiceCandidate)
                        && parsed.Count > 0;
                }
            }
            string acceptedKingdomCommand = AcceptedKingdomMembershipCandidateToPreserve(
                actionGate, playerText);
            bool removedSupersededKingdomCandidate = RemoveSupersededKingdomMembershipCandidates(
                candidates, acceptedKingdomCommand);
            bool plannerReturnedAcceptedKingdomCommand = !string.IsNullOrWhiteSpace(
                    acceptedKingdomCommand)
                && candidates.Any(candidate => string.Equals(
                    CanonicalCommand(ReadString(candidate, "command", "")),
                    acceptedKingdomCommand, StringComparison.OrdinalIgnoreCase));
            if (candidates.Count == 0
                || (!string.IsNullOrWhiteSpace(acceptedKingdomCommand)
                    && !plannerReturnedAcceptedKingdomCommand))
            {
                Dictionary<string, object> acceptedKingdomFallback =
                    BuildAcceptedKingdomMembershipFallbackAction(
                        actionGate, payload, hero, playerText, allowed);
                if (acceptedKingdomFallback != null)
                {
                    Dictionary<string, object> fallbackEnvelope = new Dictionary<string, object>
                    {
                        ["actions"] = new ArrayList { acceptedKingdomFallback }
                    };
                    candidates = NormalizeRouterActions(fallbackEnvelope, allowed, payload, hero,
                        plannerText, "accepted_kingdom_membership_fallback",
                        "Accepted kingdom membership fallback");
                    result["deterministicFallback"] = "accepted_kingdom_membership";
                    result["replacedMismatchedPlannerAction"] =
                        (!plannerReturnedAcceptedKingdomCommand || removedSupersededKingdomCandidate)
                        && parsed.Count > 0;
                }
            }
            string acceptedClanCommand = string.IsNullOrWhiteSpace(acceptedKingdomCommand)
                && string.IsNullOrWhiteSpace(acceptedPlayerServiceCommand)
                ? AcceptedClanMembershipCandidateToPreserve(actionGate, playerText)
                : "";
            bool removedSupersededClanCandidate = RemoveSupersededClanMembershipCandidates(
                candidates, acceptedClanCommand);
            bool plannerReturnedAcceptedClanCommand = !string.IsNullOrWhiteSpace(
                    acceptedClanCommand)
                && candidates.Any(candidate => string.Equals(
                    CanonicalCommand(ReadString(candidate, "command", "")),
                    acceptedClanCommand, StringComparison.OrdinalIgnoreCase));
            if (candidates.Count == 0
                || (!string.IsNullOrWhiteSpace(acceptedClanCommand)
                    && !plannerReturnedAcceptedClanCommand))
            {
                Dictionary<string, object> acceptedClanFallback =
                    BuildAcceptedClanMembershipFallbackAction(
                        actionGate, payload, hero, playerText, allowed);
                if (acceptedClanFallback != null)
                {
                    Dictionary<string, object> fallbackEnvelope = new Dictionary<string, object>
                    {
                        ["actions"] = new ArrayList { acceptedClanFallback }
                    };
                    candidates = NormalizeRouterActions(fallbackEnvelope, allowed, payload, hero,
                        plannerText, "accepted_clan_membership_fallback",
                        "Accepted clan membership fallback");
                    result["deterministicFallback"] = "accepted_clan_membership";
                    result["replacedMismatchedPlannerAction"] =
                        (!plannerReturnedAcceptedClanCommand || removedSupersededClanCandidate)
                        && parsed.Count > 0;
                }
            }
            bool negatesPartyMovementChange = NegatesPartyMovementStateChange(playerText);
            if (negatesPartyMovementChange)
            {
                RemoveAllPartyMovementCandidates(candidates);
                result["removedNegatedPartyMovementCandidates"] = true;
            }
            string acceptedPartyMovementCommand = negatesPartyMovementChange
                ? ""
                : AcceptedPartyMovementCandidateToPreserve(
                    actionGate, playerText);
            bool removedSupersededPartyMovementCandidate =
                RemoveSupersededPartyMovementCandidates(
                    candidates, acceptedPartyMovementCommand);
            bool plannerReturnedAcceptedPartyMovementCommand =
                !string.IsNullOrWhiteSpace(acceptedPartyMovementCommand)
                && candidates.Any(candidate => string.Equals(
                    CanonicalCommand(ReadString(candidate, "command", "")),
                    acceptedPartyMovementCommand,
                    StringComparison.OrdinalIgnoreCase));
            if (candidates.Count == 0
                || (!string.IsNullOrWhiteSpace(acceptedPartyMovementCommand)
                    && !plannerReturnedAcceptedPartyMovementCommand))
            {
                Dictionary<string, object> acceptedPartyMovementFallback =
                    BuildAcceptedPartyMovementFallbackAction(
                        actionGate, payload, hero, playerText, allowed);
                if (acceptedPartyMovementFallback != null)
                {
                    Dictionary<string, object> fallbackEnvelope =
                        new Dictionary<string, object>
                        {
                            ["actions"] = new ArrayList
                            {
                                acceptedPartyMovementFallback
                            }
                        };
                    candidates = NormalizeRouterActions(fallbackEnvelope, allowed,
                        payload, hero, plannerText,
                        "accepted_party_movement_fallback",
                        "Accepted party movement fallback");
                    result["deterministicFallback"] =
                        "accepted_party_movement";
                    result["replacedMismatchedPlannerAction"] =
                        (!plannerReturnedAcceptedPartyMovementCommand
                            || removedSupersededPartyMovementCandidate)
                        && parsed.Count > 0;
                }
            }
            if (candidates.Count == 0)
            {
                var giftFallback = BuildAcceptedNamedGiftFallback(actionGate, payload, hero, playerText, allowed);
                if (giftFallback != null)
                {
                    candidates.Add(giftFallback);
                    result["deterministicFallback"] = "accepted_resolved_named_gift";
                }
            }
            timer.Stop();
            result["ok"] = true;
            result["durationMs"] = timer.ElapsedMilliseconds;
            result["parsed"] = parsed;
            result["candidates"] = candidates;
            if (candidates.Count == 0)
            {
                result["errors"] = new List<string> { "Hidden action planner returned no executable candidate actions." };
                WriteAudit(campaignId, correlationId, "server", "action_planner", "planner.no_action", ReadFirstString(payload, "heroStringId", "speakerHeroStringId", "heroId"), "", ReadFirstString(payload, "eventId", "socialEventId"), "no_action", timer.ElapsedMilliseconds, "Planner returned no candidate actions for an actionable gate.", result);
            }
            else
            {
                WriteAudit(campaignId, correlationId, "server", "action_planner", "planner.candidates", ReadFirstString(payload, "heroStringId", "speakerHeroStringId", "heroId"), "", ReadFirstString(payload, "eventId", "socialEventId"), "completed", timer.ElapsedMilliseconds, "Planner produced candidate actions.", result);
            }

            return result;
        }

        private static List<Dictionary<string, object>> BuildAllowedActionPlannerChoices(Dictionary<string, object> settings, Dictionary<string, object> payload, Dictionary<string, object> hero, Dictionary<string, object> actionGate, string playerText, string visibleReply, int maxCandidates)
        {
            string text = (ReadString(actionGate, "intent", "") + "\n" + playerText + "\n" + visibleReply).Trim();
            List<string> minimeTopics = TryExtractMinimeTopics(settings, text, ReadInt(settings, "minimeMaxTopics", 5));
            string retrievalText = AppendMinimeTopics(text, minimeTopics);
            List<string> domains = ClassifyActionRouterDomains(retrievalText);
            bool testMode = false;
            Dictionary<string, object> scene = ReadDictionary(payload, "sceneContext") ?? new Dictionary<string, object>();
            string mode = NormalizeLookup(ReadFirstString(payload, "mode", "requestType", "sceneMode") + " " + Json.Serialize(scene));
            if (ReadBool(hero, "isRuler", false) || !string.IsNullOrWhiteSpace(ReadFirstString(payload, "speakerKingdomId", "targetKingdomId")))
            {
                domains.Add("diplomacy");
                domains.Add("politics");
            }

            if (!string.IsNullOrWhiteSpace(ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId")) || ContainsAnyNormalized(mode, "conversation", "dialogue", "scene"))
            {
                domains.Add("regular");
            }

            if (ContainsAnyNormalized(mode, "event", "court"))
            {
                domains.Add("diplomacy");
                domains.Add("politics");
                domains.Add("regular");
            }

            domains = domains.Distinct(StringComparer.OrdinalIgnoreCase).ToList();
            List<Dictionary<string, object>> retrieved = RetrieveActionRouterCommands(retrievalText, domains, Math.Max(3, maxCandidates * 2));
            List<Dictionary<string, object>> commands = ReadDictionaryList(ActionCatalog(), "commands");
            foreach (Dictionary<string, object> command in commands)
            {
                string family = ReadString(command, "family", "");
                if (domains.Count > 0 && !domains.Any(x => string.Equals(x, family, StringComparison.OrdinalIgnoreCase)))
                {
                    continue;
                }

                if (!retrieved.Any(x => string.Equals(ReadString(x, "command", ""), ReadString(command, "command", ""), StringComparison.OrdinalIgnoreCase)))
                {
                    Dictionary<string, object> copy = new Dictionary<string, object>(command, StringComparer.OrdinalIgnoreCase)
                    {
                        ["score"] = domains.Count > 0 ? 2 : 1,
                        ["aliases"] = ActionRouterAliases(ReadString(command, "command", ""))
                    };
                    retrieved.Add(copy);
                }
            }

            // Retrieval is an efficiency filter, not an authorization boundary. When the
            // accepted dialogue contains a strong deterministic command match, guarantee
            // that schema survives the top-N cut so the hidden planner can still decide
            // whether and how to execute it. This never queues an action by itself.
            string lexicalCommand = CanonicalCommand(CommandFromDirectiveText(
                (ReadString(actionGate, "intent", "") + "\n" + playerText).Trim()));
            string acceptedPartyMovement = AcceptedPartyMovementCandidateToPreserve(
                actionGate, playerText);
            if (!string.IsNullOrWhiteSpace(acceptedPartyMovement))
            {
                // The accepted player request is authoritative for movement routing.
                // Generated acceptance prose can mention a later "return to report",
                // which must not replace an explicit patrol with a travel command.
                lexicalCommand = acceptedPartyMovement;
                var partyMovementCommands = new HashSet<string>(
                    new[]
                    {
                        "follow",
                        "stop_following",
                        "go_to_settlement",
                        "patrol_around_settlement",
                        "wait_near_settlement",
                        "accept_temporary_party_guest",
                        "renew_temporary_party_guest",
                        "end_temporary_party_guest"
                    },
                    StringComparer.OrdinalIgnoreCase);
                retrieved.RemoveAll(candidate =>
                    partyMovementCommands.Contains(CanonicalCommand(
                        ReadString(candidate, "command", "")))
                    && !string.Equals(CanonicalCommand(ReadString(candidate,
                            "command", "")), acceptedPartyMovement,
                        StringComparison.OrdinalIgnoreCase));
            }
            if (LooksLikeNamedHeroGoldTransferDirective(payload, playerText))
            {
                // A named third-party recipient is authoritative direction evidence.
                // Generic money wording such as "pay Tynops 17 denars" otherwise
                // resembles a speaker-to-player gift and can remove transfer_gold
                // before the semantic planner sees it.
                lexicalCommand = "transfer_gold";
            }
            string acceptedKingdomMembership = AcceptedKingdomMembershipCandidateToPreserve(actionGate, playerText);
            string acceptedPlayerService = AcceptedPlayerServiceCandidateToPreserve(actionGate, playerText);
            if (!string.IsNullOrWhiteSpace(acceptedPlayerService))
            {
                lexicalCommand = acceptedPlayerService;
                var playerServiceCommands = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
                {
                    "hire_player_as_mercenary", "dismiss_player_mercenary",
                    "offer_player_vassalage", "dismiss_player_vassal"
                };
                retrieved.RemoveAll(candidate => playerServiceCommands.Contains(CanonicalCommand(
                        ReadString(candidate, "command", "")))
                    && !string.Equals(CanonicalCommand(ReadString(candidate, "command", "")),
                        acceptedPlayerService, StringComparison.OrdinalIgnoreCase));
            }
            if (!string.IsNullOrWhiteSpace(acceptedKingdomMembership))
            {
                lexicalCommand = acceptedKingdomMembership;
                var supersededKingdomCommands = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
                {
                    "join_clan", "leave_clan",
                    string.Equals(acceptedKingdomMembership, "join_kingdom", StringComparison.OrdinalIgnoreCase)
                        ? "leave_kingdom" : "join_kingdom"
                };
                retrieved.RemoveAll(candidate => supersededKingdomCommands.Contains(CanonicalCommand(
                    ReadString(candidate, "command", ""))));
            }
            string acceptedClanMembership = string.IsNullOrWhiteSpace(acceptedKingdomMembership)
                ? AcceptedClanMembershipCandidateToPreserve(actionGate, playerText)
                : "";
            if (!string.IsNullOrWhiteSpace(acceptedClanMembership))
            {
                lexicalCommand = acceptedClanMembership;
                string supersededClanCommand = string.Equals(acceptedClanMembership,
                    "join_clan", StringComparison.OrdinalIgnoreCase)
                    ? "leave_clan"
                    : "join_clan";
                retrieved.RemoveAll(candidate => string.Equals(CanonicalCommand(
                    ReadString(candidate, "command", "")), supersededClanCommand,
                    StringComparison.OrdinalIgnoreCase));
            }
            if (ShouldPreserveAcceptedItemGift(actionGate, playerText, lexicalCommand))
                lexicalCommand = "transfer_item";
            string temporaryGuestCommand = TemporaryPartyGuestCandidateToPreserve(actionGate, playerText, payload, hero);
            string residentRecruitment = ResidentRecruitmentCandidate(hero, playerText + "\n" + ReadString(actionGate, "intent", ""));
            if (!string.IsNullOrEmpty(residentRecruitment))
            { lexicalCommand = residentRecruitment; temporaryGuestCommand = ""; }
            if (!string.IsNullOrWhiteSpace(temporaryGuestCommand))
            {
                lexicalCommand = temporaryGuestCommand;
                var temporaryGuestLifecycleCommands = new HashSet<string>(
                    StringComparer.OrdinalIgnoreCase)
                {
                    "accept_temporary_party_guest",
                    "renew_temporary_party_guest",
                    "end_temporary_party_guest",
                    "acknowledge_own_faction_combat_risk"
                };
                retrieved.RemoveAll(candidate =>
                {
                    string candidateCommand = CanonicalCommand(
                        ReadString(candidate, "command", ""));
                    return temporaryGuestLifecycleCommands.Contains(candidateCommand)
                        && !string.Equals(candidateCommand, temporaryGuestCommand,
                            StringComparison.OrdinalIgnoreCase);
                });
            }
            if (!string.IsNullOrWhiteSpace(lexicalCommand))
            {
                // Keep accepted atomic exchanges atomic. Component schemas are useful for
                // simple transfers, but exposing them beside an explicitly identified
                // ransom or barter package lets the planner decompose one bargain into
                // partially executable actions. The specialized package remains a choice;
                // this filter does not authorize or queue it.
                HashSet<string> ambiguousDecompositions = null;
                if (string.Equals(lexicalCommand, "ransom_package", StringComparison.OrdinalIgnoreCase))
                {
                    ambiguousDecompositions = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
                    {
                        "trade_package",
                        "diplomatic_package",
                        "transfer_prisoner",
                        "give_gold_to_player",
                        "transfer_gold"
                    };
                }
                else if (string.Equals(lexicalCommand, "trade_package", StringComparison.OrdinalIgnoreCase))
                {
                    ambiguousDecompositions = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
                    {
                        "diplomatic_package",
                        "transfer_prisoner",
                        "transfer_item",
                        "give_gold_to_player",
                        "transfer_gold"
                    };
                }

                if (ambiguousDecompositions != null)
                {
                    retrieved.RemoveAll(x => ambiguousDecompositions.Contains(CanonicalCommand(ReadString(x, "command", ""))));
                }

                HashSet<string> lexicalCommandsToPreserve = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
                {
                    lexicalCommand
                };
                if (string.Equals(lexicalCommand, "give_gold_to_player", StringComparison.OrdinalIgnoreCase))
                {
                    // GiveGoldToPlayer is the canonical specialized schema when the
                    // accepted speaker gives currency to the player. Keeping the generic
                    // TransferGold schema beside it makes equivalent natural phrasings
                    // report different commands even though their native effect matches.
                    retrieved.RemoveAll(candidate => string.Equals(CanonicalCommand(
                        ReadString(candidate, "command", "")), "transfer_gold",
                        StringComparison.OrdinalIgnoreCase));
                }
                else if (string.Equals(lexicalCommand, "transfer_gold",
                    StringComparison.OrdinalIgnoreCase))
                {
                    // Preserve the generic schema for an explicit FromHero/ToHero transfer
                    // and remove the player-specific alternative from this planner choice.
                    retrieved.RemoveAll(candidate => string.Equals(CanonicalCommand(
                        ReadString(candidate, "command", "")), "give_gold_to_player",
                        StringComparison.OrdinalIgnoreCase));
                }

                foreach (Dictionary<string, object> lexicalCandidate in retrieved.Where(x =>
                    lexicalCommandsToPreserve.Contains(CanonicalCommand(ReadString(x, "command", "")))))
                {
                    lexicalCandidate["score"] = Math.Max(100000, ReadInt(lexicalCandidate, "score", 0));
                }
            }

            return retrieved
                .Where(x => PlannerCanExposeAction(ReadString(x, "command", ""), testMode))
                .Where(x => DialoguePlannerCandidateEligible(ReadString(x, "command", ""), payload, hero, actionGate, playerText))
                .OrderByDescending(x => ReadInt(x, "score", 0))
                .ThenBy(x => ReadString(x, "command", ""))
                .Take(Math.Max(3, maxCandidates))
                .Select(x => new Dictionary<string, object>
                {
                    ["command"] = ReadString(x, "command", ""),
                    ["family"] = ReadString(x, "family", ""),
                    ["capability"] = ActionCapabilityForCommand(ReadString(x, "command", "")),
                    ["required"] = x.ContainsKey("required") ? x["required"] : new ArrayList(),
                    ["optional"] = x.ContainsKey("optional") ? x["optional"] : new ArrayList(),
                    ["description"] = ReadString(x, "description", ""),
                    ["aliases"] = x.ContainsKey("aliases") ? x["aliases"] : ActionRouterAliases(ReadString(x, "command", ""))
                })
                .ToList();
        }

        private static string TemporaryPartyGuestCandidateToPreserve(
            Dictionary<string, object> actionGate,
            string playerText,
            Dictionary<string, object> payload = null,
            Dictionary<string, object> hero = null)
        {
            string command = TemporaryPartyGuestLifecycleCommandFromConversation(
                actionGate, playerText, true);
            return payload == null ? command : ContextualTemporaryGuestCommand(command, actionGate, playerText, payload, hero);
        }

        private static bool IsTemporaryPartyGuestLifecycleConversation(
            Dictionary<string, object> actionGate,
            string playerText,
            IEnumerable<Dictionary<string, object>> queuedActions)
        {
            if ((queuedActions ?? Enumerable.Empty<Dictionary<string, object>>()).Any(action =>
                    IsTemporaryPartyGuestLifecycleAction(CanonicalCommand(
                        ReadFirstString(ReadDictionary(action, "record") ?? action,
                            "command", "type")))))
            {
                return true;
            }

            return !string.IsNullOrWhiteSpace(
                TemporaryPartyGuestLifecycleCommandFromConversation(
                    actionGate, playerText, false));
        }

        private static string TemporaryPartyGuestLifecycleCommandFromConversation(
            Dictionary<string, object> actionGate,
            string playerText,
            bool requireAcceptedCommitment)
        {
            if (requireAcceptedCommitment
                && !string.Equals(ReadString(actionGate, "commitment", ""), "accepted",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "";
            }

            // Only a leading canonical decision identifies a present departure. Mentioning
            // a future departure safeguard inside an initial invitation must still join.
            bool explicitDeparture = ReadString(actionGate, "intent", "").Trim()
                .StartsWith("end_temporary_party_guest", StringComparison.OrdinalIgnoreCase);
            string acceptedExchange = NormalizeLookup(ReadString(actionGate, "intent", "") + "\n" + playerText);
            if (!explicitDeparture && ContainsAnyNormalized(acceptedExchange,
                    "accept banishment",
                    "accept that risk",
                    "fighting your own realm",
                    "own faction combat"))
            {
                return "acknowledge_own_faction_combat_risk";
            }

            if (!explicitDeparture && ContainsAnyNormalized(acceptedExchange,
                "join my party",
                "join the player party",
                "travel with my party",
                "ride with my party",
                "travel with me",
                "travel with us",
                "come along with us",
                "join us on the road",
                "traveling companion",
                "travelling companion",
                "temporary road cover",
                "serve as my scout",
                "scout arrangement", "service agreement", "seasonal service", "full service"))
            {
                return "accept_temporary_party_guest";
            }

            // An initial open-ended invitation commonly explains that either side may
            // "end the arrangement" at a future five-day review.  That safeguard is
            // not a present departure request.  Prefer the explicit current join verb;
            // genuine departure exchanges do not contain one of these join phrases.
            if (explicitDeparture || ContainsAnyNormalized(acceptedExchange,
                    "accepts release from the party",
                    "return to your people",
                    "return to your own party",
                    "leave my party",
                    "please leave now",
                    "end the arrangement"))
            {
                return "end_temporary_party_guest";
            }

            if (ContainsAnyNormalized(acceptedExchange,
                    "renew the arrangement",
                    "renew our arrangement",
                    "remain with us for another",
                    "stay with us while",
                    "review whether you stay"))
            {
                return "renew_temporary_party_guest";
            }

            return "";
        }

        private static string AcceptedPartyMovementCandidateToPreserve(
            Dictionary<string, object> actionGate,
            string playerText)
        {
            if (!ActionGateShouldPlan(actionGate)
                || IsSharedTravelOnly(actionGate, playerText)
                || NegatesPartyMovementStateChange(playerText))
            {
                return "";
            }

            string command = CanonicalCommand(CommandFromDirectiveText(
                playerText ?? ""));
            switch (command)
            {
                case "follow":
                case "stop_following":
                case "go_to_settlement":
                case "patrol_around_settlement":
                case "wait_near_settlement":
                    return command;
                default:
                    return "";
            }
        }

        private static bool NegatesPartyMovementStateChange(string playerText)
        {
            string text = NormalizeLookup(playerText ?? "");
            return Regex.IsMatch(text,
                       @"\b(?:do\s+not|don\s*t|never)\s+(?:stop|cease|quit)\s+(?:following|escorting|trailing)\b",
                       RegexOptions.IgnoreCase)
                || Regex.IsMatch(text,
                       @"\b(?:do\s+not|don\s*t|never)\s+(?:break\s+off(?:\s+the)?\s+escort|go\s+your\s+own\s+way)\b",
                       RegexOptions.IgnoreCase);
        }

        private static bool RemoveAllPartyMovementCandidates(
            List<Dictionary<string, object>> candidates)
        {
            if (candidates == null)
            {
                return false;
            }

            var partyMovementCommands = new HashSet<string>(
                new[]
                {
                    "follow",
                    "stop_following",
                    "go_to_settlement",
                    "patrol_around_settlement",
                    "wait_near_settlement",
                    "accept_temporary_party_guest",
                    "renew_temporary_party_guest",
                    "end_temporary_party_guest"
                },
                StringComparer.OrdinalIgnoreCase);
            int before = candidates.Count;
            candidates.RemoveAll(candidate => partyMovementCommands.Contains(
                CanonicalCommand(ReadString(candidate, "command", ""))));
            return candidates.Count != before;
        }

        private static bool RemoveSupersededPartyMovementCandidates(
            List<Dictionary<string, object>> candidates,
            string acceptedCommand)
        {
            if (candidates == null || string.IsNullOrWhiteSpace(acceptedCommand))
            {
                return false;
            }

            var partyMovementCommands = new HashSet<string>(
                new[]
                {
                    "follow",
                    "stop_following",
                    "go_to_settlement",
                    "patrol_around_settlement",
                    "wait_near_settlement",
                    "accept_temporary_party_guest",
                    "renew_temporary_party_guest",
                    "end_temporary_party_guest"
                },
                StringComparer.OrdinalIgnoreCase);
            int before = candidates.Count;
            candidates.RemoveAll(candidate =>
            {
                string command = CanonicalCommand(
                    ReadString(candidate, "command", ""));
                return partyMovementCommands.Contains(command)
                    && !string.Equals(command, acceptedCommand,
                        StringComparison.OrdinalIgnoreCase);
            });
            return candidates.Count != before;
        }

        private static Dictionary<string, object>
            BuildAcceptedPartyMovementFallbackAction(
                Dictionary<string, object> actionGate,
                Dictionary<string, object> payload,
                Dictionary<string, object> hero,
                string playerText,
                HashSet<string> allowed)
        {
            string command = AcceptedPartyMovementCandidateToPreserve(
                actionGate, playerText);
            if (string.IsNullOrWhiteSpace(command)
                || allowed == null || !allowed.Contains(command))
            {
                return null;
            }

            string speakerHeroId = FirstNonEmpty(
                ReadFirstString(payload, "speakerHeroStringId", "heroStringId",
                    "heroId"),
                ReadString(hero, "heroStringId", ""));
            if (string.IsNullOrWhiteSpace(speakerHeroId))
            {
                return null;
            }

            Dictionary<string, object> action =
                new Dictionary<string, object>
                {
                    ["command"] = command,
                    ["actorHeroStringId"] = speakerHeroId,
                    ["actorHeroId"] = speakerHeroId,
                    ["FromHero"] = speakerHeroId,
                    ["reason"] = "The speaker accepted the player's explicit "
                        + command + " order.",
                    ["source"] = "accepted_party_movement_fallback",
                    ["requiresAcceptance"] = false
                };
            if (string.Equals(command, "follow",
                    StringComparison.OrdinalIgnoreCase))
            {
                string playerHeroId = FirstNonEmpty(
                    ReadFirstString(payload, "playerHeroStringId",
                        "mainHeroStringId", "playerId"),
                    ReadFirstString(hero, "playerHeroStringId",
                        "mainHeroStringId"));
                if (string.IsNullOrWhiteSpace(playerHeroId))
                {
                    return null;
                }
                action["TargetHero"] = playerHeroId;
                action["targetHeroStringId"] = playerHeroId;
            }
            else if (!string.Equals(command, "stop_following",
                         StringComparison.OrdinalIgnoreCase))
            {
                string mentionedSettlement = FindMentionedSettlementName(
                    payload, playerText, "");
                if (string.IsNullOrWhiteSpace(mentionedSettlement))
                {
                    return null;
                }
                action["TargetSettlement"] = mentionedSettlement;
            }
            CompleteConversationActionTerms(action, payload, hero, playerText);
            return action;
        }

        private static string AcceptedClanMembershipCandidateToPreserve(
            Dictionary<string, object> actionGate,
            string playerText)
        {
            if (!ReadBool(actionGate, "needed", false)
                || !string.Equals(ReadString(actionGate, "commitment", ""), "accepted",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "";
            }

            string request = playerText ?? "";
            string intent = ReadString(actionGate, "intent", "");
            if (Regex.IsMatch(request,
                    @"(?is)\b(?:join|joins|joining|enter|enters|become|becomes)\b.{0,160}\b(?:my|our|the player'?s)\s+(?:clan|house|banner)\b")
                || Regex.IsMatch(request,
                    @"(?is)\b(?:enter|enters|join|joins|become|becomes)\b.{1,120}\bas one of (?:us|our own)\b"))
            {
                return "join_clan";
            }

            if (Regex.IsMatch(request,
                    @"(?is)\b(?:leave|withdraw from|depart from|renounce|quit|abandon)\b.{0,120}\b(?:the |your |their |current )?(?:clan|house)\b")
                || Regex.IsMatch(request,
                    @"(?is)\b(?:stand|remain|become)\b.{0,80}\b(?:without a clan|clanless)\b"))
            {
                return "leave_clan";
            }

            if (Regex.IsMatch(intent,
                    @"(?is)\b(?:leave|withdraws? from|departs? from|renounces?|quits?|abandons?)\b.{0,160}\b(?:clan|house)\b")
                || Regex.IsMatch(intent, @"(?is)\b(?:without a clan|clanless)\b"))
            {
                return "leave_clan";
            }

            return Regex.IsMatch(intent,
                       @"(?is)\b(?:accepts?|accepted|agrees?|agreed|joins?|joining|become|becomes|enter|enters)\b.{0,160}\b(?:clan membership|(?:the |my |our |player'?s )?clan|house|banner)\b")
                ? "join_clan"
                : "";
        }

        private static bool PromoteAcceptedClanMembershipGate(
            Dictionary<string, object> actionGate,
            Dictionary<string, object> payload,
            Dictionary<string, object> hero,
            string playerText,
            string visibleReply)
        {
            if (actionGate == null || ActionGateShouldPlan(actionGate)
                || ReadBool(ReadDictionary(payload, "intoxicationReceipt"), "suppressedCommitments", false))
                return false;

            string request = playerText ?? "";
            string reply = visibleReply ?? "";
            if (string.IsNullOrWhiteSpace(ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId"))
                && string.IsNullOrWhiteSpace(ReadString(hero, "heroStringId", "")))
                return false;
            if (string.IsNullOrWhiteSpace(ReadFirstString(payload, "playerClanId", "actorClanId", "actorClanStringId"))
                && string.IsNullOrWhiteSpace(ReadString(hero, "playerClanId", "")))
                return false;

            bool explicitRequest = Regex.IsMatch(request,
                @"(?is)\b(?:join|enter|become)\b.{0,160}\b(?:my|our|the player'?s)\s+(?:clan|house)\b")
                || Regex.IsMatch(request,
                    @"(?is)\b(?:join|enter|become)\b.{1,120}\bas one of (?:us|our own)\b");
            if (!explicitRequest
                || Regex.IsMatch(request + "\n" + reply,
                    @"(?is)\b(?:temporary|temporarily|guest|scout|disguise|pretend|wear (?:my|our|the) colors|travel with|serve beside|for now|for a while|if|unless|maybe|perhaps|later|tomorrow|eventually)\b"))
                return false;

            bool membershipAcceptance = IsUnambiguousActionAcceptance(reply)
                && Regex.IsMatch(reply,
                    @"(?is)\b(?:accept|agree|join|enter|become|stand)\w*\b.{0,180}\b(?:member|clan|house|one of (?:you|us|your own)|beneath your banner)\b");
            if (!membershipAcceptance) return false;

            actionGate["needed"] = true;
            actionGate["commitment"] = "accepted";
            actionGate["intent"] = "The current speaker accepts membership in the player's clan.";
            actionGate["confidence"] = 1d;
            actionGate["reason"] = "Recovered an explicit present clan-membership request and the NPC's unambiguous final acceptance.";
            return true;
        }

        private static string AcceptedPlayerServiceCandidateToPreserve(
            Dictionary<string, object> actionGate,
            string playerText)
        {
            if (!ReadBool(actionGate, "needed", false)
                || !string.Equals(ReadString(actionGate, "commitment", ""), "accepted",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "";
            }

            string request = playerText ?? "";
            string intent = ReadString(actionGate, "intent", "");
            string combined = request + "\n" + intent;
            if (Regex.IsMatch(combined,
                    @"(?is)\b(?:release|end|dismiss|terminate|cancel|free)\b.{0,180}\b(?:mercenar(?:y|ies)|paid service|contract|duty)\b"))
            {
                return "dismiss_player_mercenary";
            }
            if (Regex.IsMatch(combined,
                    @"(?is)\b(?:release|dismiss|free|end|cancel|let)\b.{0,180}\b(?:vassal(?:age)?|sworn service|oath)\b"))
            {
                return "dismiss_player_vassal";
            }
            if (Regex.IsMatch(combined,
                    @"(?is)\b(?:hire|employ|take|offer)\b.{0,180}\b(?:me|my clan|us|the player'?s clan|fen Domus)\b.{0,180}\bmercenar(?:y|ies)\b"))
            {
                return "hire_player_as_mercenary";
            }
            if (Regex.IsMatch(combined,
                    @"(?is)\b(?:offer|grant|take|accept|invite)\b.{0,180}\b(?:me|my clan|us|the player'?s clan|fen Domus)\b.{0,180}\bvassal(?:age|s)?\b"))
            {
                return "offer_player_vassalage";
            }

            string normalized = NormalizeLookup(intent);
            if (ContainsAnyNormalized(normalized,
                    "end mercenary service", "release from mercenary service",
                    "release from mercenary contract", "dismiss player mercenary"))
                return "dismiss_player_mercenary";
            if (ContainsAnyNormalized(normalized,
                    "end vassalage", "release from vassalage", "release vassal oath",
                    "dismiss player vassal"))
                return "dismiss_player_vassal";
            if (ContainsAnyNormalized(normalized,
                    "hire player as mercenary", "hire the player clan as mercenaries",
                    "mercenary service for the speaker kingdom"))
                return "hire_player_as_mercenary";
            return ContainsAnyNormalized(normalized,
                    "offer player vassalage", "accept the player clan as vassals",
                    "take the player clan as sworn vassals")
                ? "offer_player_vassalage"
                : "";
        }

        private static Dictionary<string, object> BuildAcceptedPlayerServiceFallbackAction(
            Dictionary<string, object> actionGate,
            Dictionary<string, object> payload,
            Dictionary<string, object> hero,
            string playerText,
            HashSet<string> allowed)
        {
            string command = AcceptedPlayerServiceCandidateToPreserve(actionGate, playerText);
            if (string.IsNullOrWhiteSpace(command) || allowed == null || !allowed.Contains(command))
                return null;

            string speakerHeroId = FirstNonEmpty(
                ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId"),
                ReadString(hero, "heroStringId", ""));
            string speakerClanId = FirstNonEmpty(
                ReadFirstString(payload, "speakerClanId", "npcClanId"),
                ReadString(hero, "clanId", ""));
            string speakerKingdomId = FirstNonEmpty(
                ReadFirstString(payload, "speakerKingdomId", "targetKingdomId", "targetKingdomStringId"),
                ReadString(hero, "kingdomId", ""));
            string playerClanId = FirstNonEmpty(
                ReadFirstString(payload, "playerClanId", "actorClanId", "actorClanStringId"),
                ReadString(hero, "playerClanId", ""));
            if (string.IsNullOrWhiteSpace(speakerHeroId)
                || string.IsNullOrWhiteSpace(speakerKingdomId)
                || string.IsNullOrWhiteSpace(playerClanId))
                return null;

            string intent = ReadString(actionGate, "intent", "");
            var fallback = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
            {
                ["command"] = command,
                ["actorHeroId"] = speakerHeroId,
                ["actorHeroStringId"] = speakerHeroId,
                ["actorKingdomId"] = speakerKingdomId,
                ["actorKingdomStringId"] = speakerKingdomId,
                ["targetClanId"] = playerClanId,
                ["targetClanStringId"] = playerClanId,
                ["targetKingdomId"] = speakerKingdomId,
                ["targetKingdomStringId"] = speakerKingdomId,
                ["TargetKingdom"] = speakerKingdomId,
                ["reason"] = FirstNonEmpty(LimitText(intent, 500),
                    "The sovereign explicitly accepted the player's service request."),
                ["source"] = "accepted_player_service_fallback",
                ["requiresAcceptance"] = false
            };
            if (!string.IsNullOrWhiteSpace(speakerClanId))
            {
                fallback["actorClanId"] = speakerClanId;
                fallback["actorClanStringId"] = speakerClanId;
            }
            return fallback;
        }

        private static bool RemoveSupersededPlayerServiceCandidates(
            List<Dictionary<string, object>> candidates,
            string acceptedCommand)
        {
            var commands = new HashSet<string>(new[]
            {
                "hire_player_as_mercenary", "dismiss_player_mercenary",
                "offer_player_vassalage", "dismiss_player_vassal"
            }, StringComparer.OrdinalIgnoreCase);
            if (candidates == null || !commands.Contains(acceptedCommand)) return false;
            int before = candidates.Count;
            candidates.RemoveAll(candidate => commands.Contains(CanonicalCommand(
                    ReadString(candidate, "command", "")))
                && !string.Equals(CanonicalCommand(ReadString(candidate, "command", "")),
                    acceptedCommand, StringComparison.OrdinalIgnoreCase));
            return candidates.Count != before;
        }

        private static string AcceptedKingdomMembershipCandidateToPreserve(
            Dictionary<string, object> actionGate,
            string playerText)
        {
            if (!ReadBool(actionGate, "needed", false)
                || !string.Equals(ReadString(actionGate, "commitment", ""), "accepted",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "";
            }

            string request = playerText ?? "";
            string intent = ReadString(actionGate, "intent", "");
            if (Regex.IsMatch(request,
                    @"(?is)\b(?:join|joins|joining|enter|enters|entering|bring|pledge|swear)\b.{0,200}\b(?:my|our|the player'?s)\s+(?:kingdom|realm)\b")
                || Regex.IsMatch(request,
                    @"(?is)\b(?:your|their|the)\s+(?:whole\s+)?clan\b.{0,160}\b(?:join|enter|pledge|swear)\b.{0,120}\b(?:my|our|the player'?s)\s+(?:kingdom|realm)\b"))
            {
                return "join_kingdom";
            }

            if (Regex.IsMatch(request,
                    @"(?is)\b(?:leave|withdraw from|depart from|renounce|quit|abandon|break)\b.{0,160}\b(?:kingdom|realm|allegiance|empire)\b")
                || Regex.IsMatch(request,
                    @"(?is)\b(?:take|pull)\b.{0,160}\bout of\b.{0,120}\b(?:kingdom|realm|empire)\b")
                || Regex.IsMatch(request,
                    @"(?is)\bmake\b.{0,120}\b(?:your|their|the)\s+(?:whole\s+)?clan\s+independent\b"))
            {
                return "leave_kingdom";
            }

            string normalizedIntent = NormalizeLookup(intent);
            if (ContainsAnyNormalized(normalizedIntent,
                    "join kingdom", "join my kingdom", "join our kingdom",
                    "joins the player kingdom", "clan joins the player realm",
                    "accept defection", "accepts defection"))
            {
                return "join_kingdom";
            }
            return ContainsAnyNormalized(normalizedIntent,
                    "leave kingdom", "leaves the kingdom", "withdraw from kingdom",
                    "break allegiance", "renounce allegiance")
                ? "leave_kingdom"
                : "";
        }

        private static Dictionary<string, object> BuildAcceptedKingdomMembershipFallbackAction(
            Dictionary<string, object> actionGate,
            Dictionary<string, object> payload,
            Dictionary<string, object> hero,
            string playerText,
            HashSet<string> allowed)
        {
            string command = AcceptedKingdomMembershipCandidateToPreserve(actionGate, playerText);
            if ((command != "join_kingdom" && command != "leave_kingdom")
                || allowed == null || !allowed.Contains(command))
            {
                return null;
            }

            string speakerHeroId = FirstNonEmpty(
                ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId"),
                ReadString(hero, "heroStringId", ""));
            string speakerClanId = FirstNonEmpty(
                ReadFirstString(payload, "speakerClanId", "npcClanId"),
                ReadString(hero, "clanId", ""));
            if (string.IsNullOrWhiteSpace(speakerHeroId)
                || string.IsNullOrWhiteSpace(speakerClanId))
            {
                return null;
            }

            string intent = ReadString(actionGate, "intent", "");
            Dictionary<string, object> fallback = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
            {
                ["command"] = command,
                ["actorHeroId"] = speakerHeroId,
                ["actorHeroStringId"] = speakerHeroId,
                ["actorClanId"] = speakerClanId,
                ["actorClanStringId"] = speakerClanId,
                ["reason"] = FirstNonEmpty(LimitText(intent, 500),
                    command == "join_kingdom"
                        ? "The current clan leader explicitly accepted joining the player's kingdom."
                        : "The current clan leader explicitly accepted leaving their kingdom."),
                ["source"] = "accepted_kingdom_membership_fallback",
                ["requiresAcceptance"] = false
            };
            if (command == "join_kingdom")
            {
                string playerKingdomId = FirstNonEmpty(
                    ReadFirstString(payload, "playerKingdomId", "actorKingdomId", "actorKingdomStringId"),
                    ReadString(hero, "playerKingdomId", ""));
                if (string.IsNullOrWhiteSpace(playerKingdomId)) return null;
                fallback["targetKingdomId"] = playerKingdomId;
                fallback["targetKingdomStringId"] = playerKingdomId;
                fallback["TargetKingdom"] = playerKingdomId;
            }
            return fallback;
        }

        private static bool RemoveSupersededKingdomMembershipCandidates(
            List<Dictionary<string, object>> candidates,
            string acceptedKingdomCommand)
        {
            if (candidates == null
                || (acceptedKingdomCommand != "join_kingdom"
                    && acceptedKingdomCommand != "leave_kingdom"))
            {
                return false;
            }
            var superseded = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
            {
                "join_clan", "leave_clan",
                acceptedKingdomCommand == "join_kingdom" ? "leave_kingdom" : "join_kingdom"
            };
            return candidates.RemoveAll(candidate => superseded.Contains(CanonicalCommand(
                ReadString(candidate, "command", "")))) > 0;
        }

