        private static bool RemoveSupersededClanMembershipCandidates(
            List<Dictionary<string, object>> candidates,
            string acceptedClanCommand)
        {
            if (candidates == null
                || (!string.Equals(acceptedClanCommand, "join_clan",
                        StringComparison.OrdinalIgnoreCase)
                    && !string.Equals(acceptedClanCommand, "leave_clan",
                        StringComparison.OrdinalIgnoreCase)))
            {
                return false;
            }

            string supersededCommand = string.Equals(acceptedClanCommand, "join_clan",
                StringComparison.OrdinalIgnoreCase) ? "leave_clan" : "join_clan";
            return candidates.RemoveAll(candidate => string.Equals(CanonicalCommand(
                ReadString(candidate, "command", "")), supersededCommand,
                StringComparison.OrdinalIgnoreCase)) > 0;
        }

        private static Dictionary<string, object> BuildAcceptedTemporaryPartyGuestFallbackAction(
            Dictionary<string, object> actionGate,
            Dictionary<string, object> payload,
            Dictionary<string, object> hero,
            string playerText,
            string visibleReply,
            HashSet<string> allowed)
        {
            string command = TemporaryPartyGuestCandidateToPreserve(actionGate, playerText, payload, hero);
            if (string.IsNullOrWhiteSpace(command)
                || allowed == null
                || !allowed.Contains(command)
                || !string.Equals(ReadString(actionGate, "commitment", ""), "accepted",
                    StringComparison.OrdinalIgnoreCase))
            {
                return null;
            }

            string speakerHeroId = FirstNonEmpty(
                ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId"),
                ReadString(hero, "heroStringId", ""));
            if (string.IsNullOrWhiteSpace(speakerHeroId))
            {
                return null;
            }

            string intent = ReadString(actionGate, "intent", "");
            string acceptedExchange = NormalizeLookup(intent + "\n" + playerText + "\n" + visibleReply);
            Dictionary<string, object> terms = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
            if (command == "accept_temporary_party_guest"
                || command == "renew_temporary_party_guest")
            {
                terms["purpose"] = FirstNonEmpty(LimitText(intent, 400),
                    "Temporary travel requested by the player and explicitly accepted by the current noble.");
                terms["consentConfirmed"] = true;
                if (!TryCompleteAcceptedGuestSchedule(terms, payload, acceptedExchange)) return null;
                if (command == "renew_temporary_party_guest" && ReadString(terms, "termKind", "") == "open_ended"
                    && !ContainsAnyNormalized(acceptedExchange, "open ended", "no fixed end date", "every five days"))
                    return null; // An unspecified extension must not silently replace a fixed term with open-ended service.
                var existing = TemporaryGuestDialogueContext(payload, speakerHeroId);
                if (ReadString(existing, "phase", "") == "AwaitingStart" && ReadBool(terms, "startNow", false))
                {
                    var pendingTerms = ReadDictionary(existing, "pendingTerms");
                    if (pendingTerms != null)
                    {
                        // Starting an existing agreement preserves its saved rate and
                        // duration; newly negotiated replacements belong to the planner.
                        terms = ToCaseInsensitiveDictionary(pendingTerms);
                        terms["startNow"] = true;
                        terms["deferStart"] = false;
                        terms["consentConfirmed"] = true;
                    }
                }

                if (ContainsAnyNormalized(acceptedExchange,
                        "detach from the army", "leave the present army", "disband the army",
                        "disband its formation", "army detachment"))
                {
                    terms["armyExitAccepted"] = true;
                }
            }
            else if (command == "acknowledge_own_faction_combat_risk")
            {
                terms["consentConfirmed"] = true;
            }
            else if (command == "end_temporary_party_guest")
            {
                terms["departureReason"] = FirstNonEmpty(LimitText(intent, 400),
                    "The current guest explicitly accepted departure from the player party.");
            }

            BindTemporaryGuestActionTerms(command, terms, payload, hero);
            return new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
            {
                ["command"] = command,
                ["actorHeroStringId"] = speakerHeroId,
                ["actorHeroId"] = speakerHeroId,
                ["FromHero"] = speakerHeroId,
                ["reason"] = FirstNonEmpty(LimitText(intent, 500),
                    "The accepted temporary guest lifecycle decision was recovered after an empty planner result."),
                ["terms"] = terms,
                ["source"] = "accepted_temporary_guest_fallback",
                ["requiresAcceptance"] = false
            };
        }

        private static bool PlannerCanExposeAction(string command, bool testMode)
        {
            string capability = ActionCapabilityForCommand(command);
            // Catalog membership is the production availability boundary. Commands that
            // remain registered must reach the planner; native validation and execution
            // still decide whether a selected action can run. Only explicitly retired
            // schemas are hidden. Keep testMode in the signature for existing test seams.
            _ = testMode;
            return !capability.Equals("unsupported", StringComparison.OrdinalIgnoreCase);
        }

        private static Dictionary<string, object> BuildPlannerResolverHints(Dictionary<string, object> payload, string text)
        {
            Dictionary<string, object> index = ReadDictionary(payload, "actionResolutionIndex") ?? new Dictionary<string, object>();
            Dictionary<string, object> hints = new Dictionary<string, object>
            {
                ["aliases"] = ReadDictionaryList(index, "aliases").Take(80).ToList(),
                ["mentionedSettlements"] = MentionedResolverEntries(index, "settlements", "name", text, 20),
                ["mentionedHeroes"] = MentionedResolverEntries(index, "heroes", "name", text, 20),
                ["mentionedKingdoms"] = MentionedResolverEntries(index, "kingdoms", "name", text, 20),
                ["mentionedClans"] = MentionedResolverEntries(index, "clans", "name", text, 20),
                ["mentionedItems"] = MentionedActionItems(index, text),
                ["recentContext"] = ReadDictionaryList(index, "recentContext").Take(20).ToList()
            };
            Dictionary<string, object> sceneContext = ReadDictionary(payload, "sceneContext");
            if (sceneContext != null)
            {
                hints["sceneContext"] = sceneContext;
            }

            return hints;
        }

        private static List<Dictionary<string, object>> MentionedResolverEntries(Dictionary<string, object> index, string key, string nameKey, string text, int limit)
        {
            string q = NormalizeLookup(text);
            List<Dictionary<string, object>> rows = ReadDictionaryList(index, key);
            return rows
                .Where(row =>
                {
                    string name = NormalizeLookup(ReadString(row, nameKey, ""));
                    return name.Length >= 3 && ContainsNormalizedPhrase(q, name);
                })
                .Take(Math.Max(1, limit))
                .ToList();
        }

        private static List<Dictionary<string, object>> BuildDeterministicActionCandidates(Dictionary<string, object> payload, Dictionary<string, object> hero, string text, string source, string reasonPrefix, List<string> errors)
        {
            List<Dictionary<string, object>> candidates = new List<Dictionary<string, object>>();
            string directiveText = StripDirectiveMarkers(text);
            string command = CommandFromDirectiveText(directiveText);
            if (string.IsNullOrWhiteSpace(command) && HasNativeItemGiftRequest(payload, directiveText)) command = "transfer_item";
            if (string.IsNullOrWhiteSpace(command) && LooksLikeNamedSettlementTransferDirective(payload, directiveText))
            {
                command = "demand_settlement_peace";
            }

            if (string.IsNullOrWhiteSpace(command))
            {
                errors?.Add("No deterministic action mapping matched the text.");
                return candidates;
            }

            Dictionary<string, object> action = new Dictionary<string, object>
            {
                ["command"] = command,
                ["source"] = string.IsNullOrWhiteSpace(source) ? "deterministic_action_extractor" : source,
                ["requiresAcceptance"] = false,
                ["reason"] = (string.IsNullOrWhiteSpace(reasonPrefix) ? "Detected action" : reasonPrefix) + ": " + directiveText
            };
            string mentionedSettlement = FindMentionedSettlementName(payload, directiveText, "");
            if (!string.IsNullOrWhiteSpace(mentionedSettlement) && CanInferSettlementFromText(command))
            {
                action["TargetSettlement"] = mentionedSettlement;
            }

            if (string.Equals(source, "test_lab_extractor", StringComparison.Ordinal))
            {
                CompleteTestDirectiveActionDefaults(action, payload, hero, directiveText);
                CompleteFallbackDirectiveTerms(action, payload, hero, directiveText);
            }
            else CompleteConversationActionTerms(action, payload, hero, directiveText);
            action["capability"] = ActionCapabilityForCommand(command);
            candidates.Add(action);
            return candidates;
        }

        private static List<Dictionary<string, object>> EvaluateAndQueueActionCandidates(string campaignId, Dictionary<string, object> payload, string resolutionText, List<Dictionary<string, object>> candidates, out List<string> errors, out List<Dictionary<string, object>> rejected)
        {
            errors = new List<string>();
            rejected = new List<Dictionary<string, object>>();
            List<Dictionary<string, object>> queued = new List<Dictionary<string, object>>();
            List<string> allErrors = new List<string>();

            foreach (Dictionary<string, object> candidate in candidates ?? new List<Dictionary<string, object>>())
            {
                Dictionary<string, object> candidateCopy = CloneDictionary(candidate);
                Dictionary<string, object> normalized = NormalizeActionCommand(candidateCopy, campaignId, out List<string> actionErrors, payload, resolutionText);
                if (normalized != null && actionErrors.Count == 0)
                {
                    queued.Add(QueueAction(campaignId, normalized));
                    break;
                }

                string command = ReadFirstString(candidate, "command", "action", "commandType", "intent", "type");
                Dictionary<string, object> repaired = TryRepairActionCandidate(campaignId, payload, resolutionText, candidateCopy, actionErrors);
                if (repaired != null)
                {
                    string originalSource = ReadString(candidateCopy, "source", "");
                    if (IsDialogueActionSource(originalSource))
                    {
                        repaired["source"] = originalSource;
                    }
                    BindAcceptedItemDelivery(repaired, ReadString(candidateCopy, "acceptedByHeroStringId", ""));
                    Dictionary<string, object> repairedNormalized = NormalizeActionCommand(repaired, campaignId, out List<string> repairErrors, payload, resolutionText);
                    if (repairedNormalized != null && repairErrors.Count == 0)
                    {
                        queued.Add(QueueAction(campaignId, repairedNormalized));
                        break;
                    }

                    rejected.Add(new Dictionary<string, object>
                    {
                        ["candidate"] = repaired,
                        ["command"] = ReadFirstString(repaired, "command", "action", "commandType", "intent", "type"),
                        ["capability"] = ActionCapabilityForCommand(ReadFirstString(repaired, "command", "action", "commandType", "intent", "type")),
                        ["failureClass"] = ClassifyActionFailure(1, repairErrors),
                        ["errors"] = repairErrors,
                        ["repairOf"] = candidate
                    });
                    allErrors.AddRange(repairErrors);
                }

                rejected.Add(new Dictionary<string, object>
                {
                    ["candidate"] = candidate,
                    ["command"] = command,
                    ["capability"] = ActionCapabilityForCommand(command),
                    ["failureClass"] = ClassifyActionFailure(1, actionErrors),
                    ["errors"] = actionErrors
                });
                allErrors.AddRange(actionErrors);
            }

            if (queued.Count == 0)
            {
                errors.AddRange(allErrors.Distinct(StringComparer.OrdinalIgnoreCase));
            }

            return queued;
        }

        private static Dictionary<string, object> RouteActionsApi(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            Stopwatch timer = Stopwatch.StartNew();
            string campaignId = ReadString(payload, "campaignId", "default");
            string correlationId = EnsureCorrelationId(payload);
            Dictionary<string, object> hero = ReadDictionary(payload, "hero") ?? new Dictionary<string, object>
            {
                ["heroStringId"] = ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId")
            };
            string playerText = ReadFirstString(payload, "playerText", "text", "message");
            string npcReply = ReadFirstString(payload, "npcReplyText", "visibleReply", "reply", "response");
            string source = ReadString(payload, "source", "api_action_router");
            bool allowLlm = ReadBool(payload, "useLlm", ReadBool(LoadSettings(), "enableActionRouterLlm", true));

            Dictionary<string, object> route = RouteActionTurn(campaignId, payload, hero, playerText, npcReply, new List<Dictionary<string, object>>(), source, "Action router", allowLlm);
            List<Dictionary<string, object>> candidates = ReadDictionaryList(route, "candidates");
            List<Dictionary<string, object>> normalized = new List<Dictionary<string, object>>();
            List<Dictionary<string, object>> rejected = new List<Dictionary<string, object>>();
            List<string> errors = new List<string>();
            string resolutionText = BuildRouterResolutionText(playerText, npcReply);
            foreach (Dictionary<string, object> candidate in candidates)
            {
                Dictionary<string, object> record = NormalizeActionCommand(CloneDictionary(candidate), campaignId, out List<string> actionErrors, payload, resolutionText);
                if (record != null && actionErrors.Count == 0)
                {
                    normalized.Add(record);
                }
                else
                {
                    rejected.Add(new Dictionary<string, object>
                    {
                        ["candidate"] = candidate,
                        ["command"] = ReadFirstString(candidate, "command", "action", "commandType", "intent", "type"),
                        ["failureClass"] = ClassifyActionFailure(1, actionErrors),
                        ["errors"] = actionErrors
                    });
                    errors.AddRange(actionErrors);
                }
            }

            timer.Stop();
            return new Dictionary<string, object>
            {
                ["ok"] = true,
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["durationMs"] = timer.ElapsedMilliseconds,
                ["route"] = route,
                ["candidates"] = candidates,
                ["normalizedActions"] = normalized,
                ["rejectedCandidates"] = rejected,
                ["errors"] = errors.Distinct(StringComparer.OrdinalIgnoreCase).ToList()
            };
        }

        private static Dictionary<string, object> PlanActionsApi(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            Stopwatch timer = Stopwatch.StartNew();
            string campaignId = ReadString(payload, "campaignId", "web_planner_preview");
            string correlationId = EnsureCorrelationId(payload);
            Dictionary<string, object> hero = ReadDictionary(payload, "hero") ?? new Dictionary<string, object>
            {
                ["heroStringId"] = ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId"),
                ["name"] = ReadFirstString(payload, "speakerName", "heroName")
            };
            string playerText = ReadFirstString(payload, "playerText", "text", "message");
            string npcReply = ReadFirstString(payload, "npcReplyText", "visibleReply", "reply", "response");
            Dictionary<string, object> actionGate = NormalizeActionGate(ReadDictionary(payload, "actionGate"), playerText, npcReply);
            if (!ReadBool(actionGate, "needed", false) && !string.IsNullOrWhiteSpace(ReadFirstString(payload, "actionGateIntent", "intent")))
            {
                actionGate["needed"] = true;
                string commitment = ReadFirstString(payload, "actionGateCommitment", "commitment");
                actionGate["commitment"] = string.IsNullOrWhiteSpace(commitment) ? "accepted" : commitment;
                actionGate["intent"] = ReadFirstString(payload, "actionGateIntent", "intent");
                actionGate["confidence"] = ReadDouble(payload, "actionGateConfidence", 0.9d);
                actionGate["reason"] = "Web planner preview.";
            }

            Dictionary<string, object> planner = PlanActionsFromGate(campaignId, payload, hero, playerText, npcReply, actionGate);
            List<Dictionary<string, object>> normalized = new List<Dictionary<string, object>>();
            List<Dictionary<string, object>> rejected = new List<Dictionary<string, object>>();
            List<string> errors = new List<string>();
            string resolutionText = BuildRouterResolutionText(playerText + "\n" + ReadString(actionGate, "intent", ""), npcReply);
            foreach (Dictionary<string, object> candidate in ReadDictionaryList(planner, "candidates"))
            {
                Dictionary<string, object> record = NormalizeActionCommand(CloneDictionary(candidate), campaignId, out List<string> actionErrors, payload, resolutionText);
                if (record != null && actionErrors.Count == 0)
                {
                    normalized.Add(record);
                }
                else
                {
                    rejected.Add(new Dictionary<string, object>
                    {
                        ["candidate"] = candidate,
                        ["command"] = ReadFirstString(candidate, "command", "action", "commandType", "intent", "type"),
                        ["failureClass"] = ClassifyActionFailure(1, actionErrors),
                        ["errors"] = actionErrors
                    });
                    errors.AddRange(actionErrors);
                }
            }

            timer.Stop();
            return new Dictionary<string, object>
            {
                ["ok"] = true,
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["durationMs"] = timer.ElapsedMilliseconds,
                ["actionGate"] = actionGate,
                ["planner"] = planner,
                ["normalizedActions"] = normalized,
                ["rejectedCandidates"] = rejected,
                ["errors"] = errors.Distinct(StringComparer.OrdinalIgnoreCase).ToList()
            };
        }

        private static Dictionary<string, object> RouteActionTurn(
            string campaignId,
            Dictionary<string, object> payload,
            Dictionary<string, object> hero,
            string playerText,
            string npcReply,
            List<Dictionary<string, object>> suggestedActions,
            string source,
            string reasonPrefix,
            bool allowLlm)
        {
            Stopwatch timer = Stopwatch.StartNew();
            payload = payload ?? new Dictionary<string, object>();
            hero = hero ?? new Dictionary<string, object>();
            string correlationId = EnsureCorrelationId(payload);
            string routeText = BuildRouterResolutionText(playerText, npcReply);
            Dictionary<string, object> settings = LoadSettings();
            int maxCandidates = Math.Max(3, ReadInt(settings, "actionRouterCandidateCount", 10));
            List<string> minimeTopics = TryExtractMinimeTopics(settings, routeText, ReadInt(settings, "minimeMaxTopics", 5));
            string retrievalText = AppendMinimeTopics(routeText, minimeTopics);
            List<string> domains = ClassifyActionRouterDomains(retrievalText);
            List<Dictionary<string, object>> retrieved = RetrieveActionRouterCommands(retrievalText, domains, maxCandidates);
            List<Dictionary<string, object>> candidates = new List<Dictionary<string, object>>();
            List<string> errors = new List<string>();
            List<string> deterministicErrors = new List<string>();

            foreach (Dictionary<string, object> deterministic in BuildDeterministicActionCandidates(payload, hero, routeText, string.IsNullOrWhiteSpace(source) ? "action_router_deterministic" : source + "_deterministic", reasonPrefix, deterministicErrors))
            {
                AppendUniqueActionCandidate(candidates, deterministic);
            }

            if (suggestedActions != null)
            {
                foreach (Dictionary<string, object> suggested in suggestedActions)
                {
                    Dictionary<string, object> copy = new Dictionary<string, object>(suggested ?? new Dictionary<string, object>(), StringComparer.OrdinalIgnoreCase);
                    copy["source"] = ReadString(copy, "source", "dialogue_suggested_action");
                    AppendUniqueActionCandidate(candidates, copy);
                }
            }

            Dictionary<string, object> llmRoute = new Dictionary<string, object>();
            // A command name without its required terms is only a guess. It must
            // not suppress semantic extraction or win deduplication over it.
            var executableCandidates = ExecutableRouterCandidates(candidates, campaignId, payload, routeText);
            bool shouldRunLlm = allowLlm && ShouldRunActionRouterLlm(settings, routeText, executableCandidates.Count);
            if (shouldRunLlm)
            {
                llmRoute = TryRouteActionsWithLlm(settings, campaignId, correlationId, payload, hero, routeText, retrieved, source, reasonPrefix);
                var resolvedCandidates = ReadDictionaryList(llmRoute, "candidates");
                if (resolvedCandidates.Count > 0)
                    candidates = PreferResolvedRouterCandidates(resolvedCandidates, executableCandidates);

                errors.AddRange(ReadStringList(llmRoute, "errors"));
            }

            if (candidates.Count == 0)
            {
                errors.AddRange(deterministicErrors);
            }

            timer.Stop();
            Dictionary<string, object> route = new Dictionary<string, object>
            {
                ["ok"] = true,
                ["shouldFireAction"] = candidates.Count > 0,
                ["durationMs"] = timer.ElapsedMilliseconds,
                ["domains"] = domains,
                ["minimeTopics"] = minimeTopics,
                ["retrievedCommands"] = retrieved,
                ["candidateCount"] = candidates.Count,
                ["candidates"] = candidates,
                ["deterministicErrors"] = deterministicErrors,
                ["llmRouter"] = llmRoute,
                ["errors"] = errors.Distinct(StringComparer.OrdinalIgnoreCase).ToList()
            };

            WriteAudit(campaignId, correlationId, "server", "action_router", "action.router", ReadFirstString(payload, "heroStringId", "heroId", "speakerHeroStringId"), "", ReadFirstString(payload, "eventId", "socialEventId"), candidates.Count > 0 ? "completed" : "no_action", timer.ElapsedMilliseconds, candidates.Count > 0 ? "Action router produced candidates." : "Action router found no action.", route);
            return route;
        }

        private static string BuildRouterResolutionText(string playerText, string npcReply)
        {
            StringBuilder builder = new StringBuilder();
            if (!string.IsNullOrWhiteSpace(playerText))
            {
                builder.AppendLine("player: " + playerText.Trim());
            }

            if (!string.IsNullOrWhiteSpace(npcReply))
            {
                builder.AppendLine("npc: " + npcReply.Trim());
            }

            return builder.ToString().Trim();
        }

        private static bool ShouldRunActionRouterLlm(Dictionary<string, object> settings, string routeText, int existingCandidateCount)
        {
            if (!ReadBool(settings, "enableActionRouterLlm", true))
            {
                return false;
            }

            if (string.IsNullOrWhiteSpace(routeText) || !LlmProviderConfigured(settings))
            {
                return false;
            }

            return existingCandidateCount == 0 || ReadBool(settings, "actionRouterAlwaysRun", false);
        }

        private static List<string> ClassifyActionRouterDomains(string text)
        {
            string q = NormalizeLookup(text);
            List<string> domains = new List<string>();
            if (ContainsAnyNormalized(q, "peace", "war", "tribute", "treaty", "alliance", "pact", "surrender", "reparations", "ransom", "prisoner exchange", "kingdom", "settlement for peace"))
            {
                domains.Add("diplomacy");
            }

            if (ContainsAnyNormalized(q, "raid", "besiege", "attack", "army", "recruit", "patrol", "follow", "go to", "travel", "wait near", "capture", "party"))
            {
                domains.Add("regular");
                domains.Add("strategy");
            }

            if (ContainsAnyNormalized(q, "gold", "denar", "give", "pay", "transfer", "item", "armor", "armour", "grain", "horse", "workshop", "ships", "fleet"))
            {
                domains.Add("regular");
                domains.Add("diplomacy");
            }

            if (ContainsAnyNormalized(q, "rebellion", "ruling clan", "claimant", "defect", "exile", "restore", "marriage", "mediate", "clan dispute"))
            {
                domains.Add("politics");
            }

            if (ContainsAnyNormalized(q, "duel", "kill", "execute", "surrender to me", "leave me alone", "hire me", "vassal", "mercenary"))
            {
                domains.Add("regular");
            }

            return domains.Distinct(StringComparer.OrdinalIgnoreCase).ToList();
        }

        private static List<Dictionary<string, object>> RetrieveActionRouterCommands(string text, List<string> domains, int maxCandidates)
        {
            string normalized = NormalizeLookup(text);
            List<Dictionary<string, object>> commands = ReadDictionaryList(ActionCatalog(), "commands");
            List<Dictionary<string, object>> scored = new List<Dictionary<string, object>>();
            foreach (Dictionary<string, object> command in commands)
            {
                string commandId = ReadString(command, "command", "");
                string family = ReadString(command, "family", "");
                int score = 0;
                if (domains.Any(x => string.Equals(x, family, StringComparison.OrdinalIgnoreCase)))
                {
                    score += 6;
                }

                foreach (string alias in ActionRouterAliases(commandId))
                {
                    if (ContainsAnyNormalized(normalized, alias))
                    {
                        score += 12;
                    }
                }

                string commandWords = NormalizeLookup(commandId.Replace("_", " ") + " " + ReadString(command, "description", ""));
                foreach (string token in normalized.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries).Where(x => x.Length >= 4).Distinct())
                {
                    if ((" " + commandWords + " ").Contains(" " + token + " "))
                    {
                        score += 1;
                    }
                }

                if (score > 0)
                {
                    Dictionary<string, object> copy = new Dictionary<string, object>(command, StringComparer.OrdinalIgnoreCase)
                    {
                        ["score"] = score,
                        ["aliases"] = ActionRouterAliases(commandId)
                    };
                    scored.Add(copy);
                }
            }

            return scored
                .OrderByDescending(x => ReadInt(x, "score", 0))
                .ThenBy(x => ReadString(x, "command", ""))
                .Take(Math.Max(1, maxCandidates))
                .ToList();
        }

