        private static Dictionary<string, object> TryRouteActionsWithLlm(Dictionary<string, object> settings, string campaignId, string correlationId, Dictionary<string, object> payload, Dictionary<string, object> hero, string routeText, List<Dictionary<string, object>> retrieved, string source, string reasonPrefix)
        {
            Dictionary<string, object> result = new Dictionary<string, object>
            {
                ["ok"] = false,
                ["candidates"] = new List<Dictionary<string, object>>(),
                ["errors"] = new List<string>()
            };
            if (retrieved == null || retrieved.Count == 0)
            {
                result["errors"] = new List<string> { "No router command candidates were retrieved." };
                return result;
            }

            List<Dictionary<string, object>> actionChoices = retrieved.Select(x => new Dictionary<string, object>
            {
                ["command"] = ReadString(x, "command", ""),
                ["family"] = ReadString(x, "family", ""),
                ["capability"] = ReadString(x, "capability", ""),
                ["required"] = x.ContainsKey("required") ? x["required"] : new ArrayList(),
                ["description"] = ReadString(x, "description", ""),
                ["aliases"] = x.ContainsKey("aliases") ? x["aliases"] : new ArrayList()
            }).ToList();

            string system = "You are Bannerlord Reign's silent action router. You do not roleplay. You read a conversation turn and return strict JSON only. Never invent internal game IDs. Use natural fields like TargetSettlement, TargetHero, TargetKingdom, FromHero, ToHero, GoldAmount, Item, Amount, or PrisonerHero. If no action is clearly finalized or commanded, return should_fire_action false.";
            string candidatePrefix = "CANDIDATE ACTIONS\n" + CanonicalActionCatalogJson(actionChoices)
                + "\n\nOUTPUT CONTRACT\nReturn JSON exactly like {\"should_fire_action\":true,\"action\":\"command_name\",\"confidence\":0.91,\"arguments\":{\"TargetSettlement\":\"Lycaron\"},\"missing_required_fields\":[]} or {\"should_fire_action\":false,\"reason\":\"not actionable\"}.";
            PromptEnvelope promptEnvelope = CreatePromptEnvelope("action_router", "candidate-set", system, candidatePrefix, "CONVERSATION TURN\n" + routeText);
            Dictionary<string, object> llm = ChatWithLlm(new Dictionary<string, object>
            {
                ["requestType"] = "action_router",
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["heroStringId"] = ReadFirstString(payload, "heroStringId", "speakerHeroStringId", "heroId"),
                ["messages"] = promptEnvelope.Messages,
                ["promptEnvelope"] = promptEnvelope.Diagnostics,
                ["promptCacheEligible"] = true,
                ["temperature"] = 0.05d,
                ["maxTokens"] = ReadInt(settings, "actionRouterMaxTokens", 700),
                ["response_format"] = new Dictionary<string, object> { ["type"] = "json_object" }
            });

            result["llm"] = llm;
            if (!ReadBool(llm, "ok", false))
            {
                result["errors"] = new List<string> { "Action router LLM failed: " + ReadString(llm, "error", "") };
                return result;
            }

            Dictionary<string, object> parsed = TryParseJsonObject(ReadString(llm, "content", "")) ?? new Dictionary<string, object>();
            result["parsed"] = parsed;
            HashSet<string> allowed = new HashSet<string>(retrieved.Select(x => CanonicalCommand(ReadString(x, "command", ""))), StringComparer.OrdinalIgnoreCase);
            List<Dictionary<string, object>> candidates = NormalizeRouterActions(parsed, allowed, payload, hero, routeText, string.IsNullOrWhiteSpace(source) ? "action_router_llm" : source + "_llm", reasonPrefix);
            result["ok"] = true;
            result["candidates"] = candidates;
            return result;
        }

        private static List<Dictionary<string, object>> NormalizeRouterActions(Dictionary<string, object> parsed, HashSet<string> allowedCommands, Dictionary<string, object> payload, Dictionary<string, object> hero, string routeText, string source, string reasonPrefix)
        {
            List<Dictionary<string, object>> results = new List<Dictionary<string, object>>();
            if (parsed == null || parsed.Count == 0)
            {
                return results;
            }

            List<Dictionary<string, object>> rawActions = ReadDictionaryList(parsed, "actions");
            if (rawActions.Count == 0 && (ReadBool(parsed, "should_fire_action", ReadBool(parsed, "shouldFireAction", false)) || parsed.ContainsKey("action") || parsed.ContainsKey("command")))
            {
                rawActions.Add(parsed);
            }

            foreach (Dictionary<string, object> raw in rawActions)
            {
                Dictionary<string, object> action = FlattenActionFields(raw);
                string command = CanonicalCommand(ReadFirstString(action, "command", "action", "commandType", "intent", "type"));
                if (string.IsNullOrWhiteSpace(command) || (allowedCommands != null && allowedCommands.Count > 0 && !allowedCommands.Contains(command)))
                {
                    continue;
                }

                double confidence = ReadDouble(action, "confidence", 1d);
                if (confidence < 0.25d)
                {
                    continue;
                }

                Dictionary<string, object> copy = new Dictionary<string, object>(action, StringComparer.OrdinalIgnoreCase)
                {
                    ["command"] = command,
                    ["source"] = string.IsNullOrWhiteSpace(source) ? "action_router_llm" : source,
                    ["requiresAcceptance"] = false
                };
                if (string.IsNullOrWhiteSpace(ReadString(copy, "reason", "")))
                {
                    copy["reason"] = (string.IsNullOrWhiteSpace(reasonPrefix) ? "Action router" : reasonPrefix) + ": " + LimitText(routeText, 700);
                }

                ApplyRouterArguments(copy, ReadDictionary(action, "arguments") ?? ReadDictionary(action, "args") ?? new Dictionary<string, object>(), command);
                CompleteConversationActionTerms(copy, payload, hero, routeText);
                copy["capability"] = ActionCapabilityForCommand(command);
                results.Add(copy);
            }

            return results;
        }

        private static void ApplyRouterArguments(Dictionary<string, object> action, Dictionary<string, object> arguments, string command)
        {
            foreach (KeyValuePair<string, object> pair in arguments ?? new Dictionary<string, object>())
            {
                string key = NormalizeLookup(pair.Key);
                // FlattenActionFields already retains canonical fields. Do not reinterpret
                // metadata or explicit actor/target IDs as vague natural-language aliases.
                if (IsCanonicalRouterArgument(key)) continue;
                string targetKey = RouterArgumentTargetKey(key, command);
                if (!string.IsNullOrWhiteSpace(targetKey) && (!action.ContainsKey(targetKey) || action[targetKey] == null || string.IsNullOrWhiteSpace(Convert.ToString(action[targetKey]))))
                {
                    action[targetKey] = pair.Value;
                }
            }
        }

        private static string RouterArgumentTargetKey(string normalizedKey, string command)
        {
            if (IsCanonicalRouterArgument(normalizedKey)) return "";
            if (string.IsNullOrWhiteSpace(normalizedKey))
            {
                return "";
            }

            if (normalizedKey.Contains("settlement") || normalizedKey.Contains("town") || normalizedKey.Contains("city") || normalizedKey.Contains("castle") || normalizedKey.Contains("village") || normalizedKey.Contains("fief"))
            {
                return "TargetSettlement";
            }

            if (normalizedKey.Contains("kingdom") || normalizedKey.Contains("faction"))
            {
                return "TargetKingdom";
            }

            if (normalizedKey.Contains("clan"))
            {
                return "TargetClan";
            }

            if (normalizedKey.Contains("from") || normalizedKey.Contains("giver")
                || normalizedKey == "source hero" || normalizedKey == "sourcehero")
            {
                return "FromHero";
            }

            if (normalizedKey.Contains("to") || normalizedKey.Contains("recipient") || normalizedKey.Contains("receiver"))
            {
                return CanonicalCommand(command).StartsWith("transfer_", StringComparison.OrdinalIgnoreCase) ? "ToHero" : "TargetHero";
            }

            if (normalizedKey.Contains("killer"))
            {
                return "KillerHero";
            }

            if (normalizedKey.Contains("hero") || normalizedKey.Contains("lord") || normalizedKey.Contains("character") || normalizedKey.Contains("npc") || normalizedKey == "target")
            {
                return CanInferSettlementFromText(command) ? "TargetSettlement" : "TargetHero";
            }

            if (normalizedKey.Contains("gold") || normalizedKey.Contains("denar") || normalizedKey.Contains("money") || normalizedKey.Contains("price"))
            {
                return "GoldAmount";
            }

            if (normalizedKey.Contains("item") || normalizedKey.Contains("asset") || normalizedKey.Contains("goods") || normalizedKey.Contains("armor") || normalizedKey.Contains("armour"))
            {
                return "Item";
            }

            if (normalizedKey.Contains("amount") || normalizedKey.Contains("count") || normalizedKey.Contains("quantity"))
            {
                return "Amount";
            }

            if (normalizedKey.Contains("workshop"))
            {
                return "Workshop";
            }

            if (normalizedKey.Contains("prisoner"))
            {
                return "PrisonerHero";
            }

            return "";
        }

        private static void AppendUniqueActionCandidate(List<Dictionary<string, object>> candidates, Dictionary<string, object> candidate)
        {
            if (candidate == null || candidate.Count == 0)
            {
                return;
            }

            string key = ActionCandidateKey(candidate);
            if (!candidates.Any(x => string.Equals(ActionCandidateKey(x), key, StringComparison.OrdinalIgnoreCase)))
            {
                candidates.Add(candidate);
            }
        }

        private static string ActionCandidateKey(Dictionary<string, object> candidate)
        {
            string command = CanonicalCommand(ReadFirstString(candidate, "command", "action", "commandType", "intent", "type"));
            string target = ReadFirstString(candidate, "TargetSettlement", "targetSettlementStringId", "TargetHero", "targetHeroStringId", "TargetKingdom", "targetKingdomStringId", "Item", "GoldAmount");
            return command + "|" + NormalizeLookup(target);
        }

        private static Dictionary<string, object> TryRepairActionCandidate(string campaignId, Dictionary<string, object> payload, string resolutionText, Dictionary<string, object> candidate, List<string> errors)
        {
            Dictionary<string, object> settings = LoadSettings();
            if (!ReadBool(settings, "enableActionRouterRepair", true) || !LlmProviderConfigured(settings))
            {
                return null;
            }

            string source = ReadString(candidate, "source", "");
            if (source.IndexOf("router", StringComparison.OrdinalIgnoreCase) < 0
                && source.IndexOf("planner", StringComparison.OrdinalIgnoreCase) < 0)
            {
                return null;
            }

            string command = CanonicalCommand(ReadFirstString(candidate, "command", "action", "commandType", "intent", "type"));
            if (string.IsNullOrWhiteSpace(command))
            {
                return null;
            }

            string system = "You repair one Bannerlord Reign action JSON object. Return strict JSON only. Do not invent internal IDs. Use natural fields if needed. Keep the same intended action unless the error proves it is the wrong command.";
            string definitionPrefix = "ACTION DEFINITION\n" + CanonicalJson(RetrieveActionRouterCommands(command.Replace("_", " "), new List<string>(), 5))
                + "\n\nOUTPUT CONTRACT\nReturn {\"action\":{\"command\":\"" + command + "\",\"arguments\":{...},\"reason\":\"...\"}}.";
            string liveRepair = "CONVERSATION/ACTION TEXT\n" + resolutionText
                + "\n\nORIGINAL ACTION\n" + Json.Serialize(candidate)
                + "\n\nVALIDATION ERRORS\n" + Json.Serialize(errors ?? new List<string>());
            PromptEnvelope promptEnvelope = CreatePromptEnvelope("action_repair", command, system, definitionPrefix, liveRepair);
            Dictionary<string, object> llm = ChatWithLlm(new Dictionary<string, object>
            {
                ["requestType"] = "action_repair",
                ["campaignId"] = campaignId,
                ["correlationId"] = EnsureCorrelationId(payload),
                ["heroStringId"] = ReadFirstString(payload, "heroStringId", "speakerHeroStringId", "heroId"),
                ["messages"] = promptEnvelope.Messages,
                ["promptEnvelope"] = promptEnvelope.Diagnostics,
                ["promptCacheEligible"] = true,
                ["temperature"] = 0.05d,
                ["maxTokens"] = ReadInt(settings, "actionRouterMaxTokens", 700),
                ["response_format"] = new Dictionary<string, object> { ["type"] = "json_object" }
            });

            if (!ReadBool(llm, "ok", false))
            {
                return null;
            }

            Dictionary<string, object> parsed = TryParseJsonObject(ReadString(llm, "content", "")) ?? new Dictionary<string, object>();
            Dictionary<string, object> repaired = ReadDictionary(parsed, "action") ?? parsed;
            if (repaired == null || repaired.Count == 0)
            {
                return null;
            }

            HashSet<string> allowed = new HashSet<string>(new[] { command }, StringComparer.OrdinalIgnoreCase);
            List<Dictionary<string, object>> normalized = NormalizeRouterActions(repaired, allowed, payload, ReadDictionary(payload, "hero") ?? new Dictionary<string, object>(), resolutionText, "action_router_repair", "Action router repair");
            Dictionary<string, object> first = normalized.FirstOrDefault();
            if (first != null)
            {
                first["repairOf"] = candidate;
            }

            return first;
        }

        private static string ClassifyActionFailure(int candidateCount, List<string> errors)
        {
            string joined = string.Join(" | ", errors ?? new List<string>()).ToLowerInvariant();
            if (string.IsNullOrWhiteSpace(joined))
            {
                return candidateCount <= 0 ? "no_action_detected" : "completed_no_effect";
            }

            if (joined.Contains("unsupported action command") || joined.Contains("no deterministic action mapping"))
            {
                return "bad_command_mapping";
            }

            if (joined.Contains("required") || joined.Contains("must be positive") || joined.Contains("is missing"))
            {
                return "missing_required_field";
            }

            if (joined.Contains("could not resolve") || joined.Contains("ambiguous") || joined.Contains("not_found"))
            {
                return "resolver_failed";
            }

            if (joined.Contains("validation") || joined.Contains("illegal") || joined.Contains("not allowed"))
            {
                return "validation_failed";
            }

            if (joined.Contains("executor") || joined.Contains("failed to execute"))
            {
                return "executor_failed";
            }

            return "validation_failed";
        }

        private static string BuildActionShadowPreview(List<Dictionary<string, object>> queuedTestDirectiveActions, List<Dictionary<string, object>> queuedDialogueActions, List<string> testDirectiveErrors, List<string> dialogueActionErrors)
        {
            Dictionary<string, object> queued = (queuedTestDirectiveActions ?? new List<Dictionary<string, object>>()).Concat(queuedDialogueActions ?? new List<Dictionary<string, object>>()).FirstOrDefault();
            if (queued != null)
            {
                Dictionary<string, object> record = ReadDictionary(queued, "record") ?? queued;
                string command = ReadString(record, "command", "");
                string from = ReadFirstString(record, "actorHeroStringId", "actorKingdomStringId", "actorClanStringId");
                string to = ReadFirstString(record, "targetHeroStringId", "targetKingdomStringId", "targetClanStringId", "targetSettlementStringId");
                return "Detected action: " + command + " | capability: " + ActionCapabilityForCommand(command) + " | resolved: " + (string.IsNullOrWhiteSpace(from) ? "<none>" : from) + " -> " + (string.IsNullOrWhiteSpace(to) ? "<none>" : to) + " | status: queued";
            }

            List<string> errors = new List<string>();
            errors.AddRange(testDirectiveErrors ?? new List<string>());
            errors.AddRange(dialogueActionErrors ?? new List<string>());
            if (errors.Count == 0)
            {
                return "";
            }

            return "Detected action: none | status: " + ClassifyActionFailure(1, errors) + ": " + errors.First();
        }

        private static bool ShouldAutoQueueDialogueAction(Dictionary<string, object> action, string playerText, string visibleReply, out string reason)
        {
            reason = "not enough acceptance evidence";
            string command = ReadString(action, "command", "");
            string player = (playerText ?? string.Empty).ToLowerInvariant();
            string reply = (visibleReply ?? string.Empty).ToLowerInvariant();
            bool explicitCommit = !ReadBool(action, "requiresAcceptance", true)
                || ReadBool(action, "accepted", false)
                || ReadBool(action, "committed", false)
                || ReadBool(action, "executeNow", false)
                || ReadBool(action, "npcAccepted", false);

            if (ContainsAnyPhrase(reply, DialogueActionBlockingPhrases()))
            {
                reason = "visible reply still blocks, bargains, refuses, or asks for more proof";
                return false;
            }

            if (explicitCommit)
            {
                reason = "model marked action as accepted";
                return true;
            }

            if (ContainsAnyPhrase(reply, DialogueActionAcceptancePhrases()))
            {
                reason = "NPC reply commits to the agreement";
                return true;
            }

            if (IsTreatyOrDiplomacyCommand(command) && ContainsAnyPhrase(player, PlayerCommitmentPhrases()))
            {
                reason = "player explicitly finalized a diplomatic agreement and NPC did not block it";
                return true;
            }

            return false;
        }

        private static bool IsTreatyOrDiplomacyCommand(string command)
        {
            switch (CanonicalCommand(command))
            {
                case "sign_trade_agreement":
                case "sign_non_aggression_pact":
                case "sign_alliance":
                case "sign_defensive_pact":
                case "make_peace":
                case "offer_tribute_peace":
                case "demand_reparations_peace":
                case "demand_settlement_peace":
                case "demand_surrender_peace":
                case "exchange_prisoners":
                case "ransom_package":
                case "hostage_guarantee":
                case "war_indemnity":
                case "recognize_conquest":
                case "return_occupied_settlement":
                case "demilitarized_border":
                case "supply_agreement":
                case "loan_or_subsidy":
                case "pay_to_stay_neutral":
                case "pay_to_join_war":
                case "guarantee_independence":
                case "protectorate_or_vassalage":
                case "record_promise":
                    return true;
                default:
                    return false;
            }
        }

        private static bool ContainsAnyPhrase(string text, IEnumerable<string> phrases)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            foreach (string phrase in phrases ?? Enumerable.Empty<string>())
            {
                if (!string.IsNullOrWhiteSpace(phrase) && text.IndexOf(phrase, StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    return true;
                }
            }

            return false;
        }

        private static IEnumerable<string> DialogueActionBlockingPhrases()
        {
            return new[]
            {
                "i refuse",
                "i decline",
                "i do not agree",
                "i don't agree",
                "i will not",
                "i won't",
                "not yet",
                "not agree",
                "not agreed",
                "no pact",
                "no agreement",
                "convince me",
                "prove",
                "tell me what",
                "tell me plainly",
                "before i agree",
                "before agreeing",
                "before i commit",
                "before committing",
                "i will consider",
                "i shall consider",
                "perhaps",
                "maybe",
                "what goods",
                "what tariffs",
                "what security",
                "what do you offer",
                "what flows",
                "would hear what",
                "i do not refuse"
            };
        }

        private static IEnumerable<string> DialogueActionAcceptancePhrases()
        {
            return new[]
            {
                "i agree",
                "we are agreed",
                "agreed.",
                "i accept",
                "accepted.",
                "i consent",
                "let it be done",
                "so be it",
                "done.",
                "you have my word",
                "you have my seal",
                "my seal",
                "i will sign",
                "i shall sign",
                "i sign",
                "we have a pact",
                "we have an agreement",
                "the pact stands",
                "let the pact stand",
                "let this pact stand",
                "we shall not raise arms",
                "we will not raise arms",
                "i will not raise arms",
                "i shall not raise arms",
                "we will keep peace",
                "we shall keep peace",
                "let our kingdoms be bound"
            };
        }

        private static IEnumerable<string> PlayerCommitmentPhrases()
        {
            return new[]
            {
                "i agree",
                "i accept",
                "i sign",
                "i will sign",
                "i shall sign",
                "we are agreed",
                "let us sign",
                "you have my word",
                "i swear",
                "i pledge",
                "i give my oath",
                "i seal",
                "i will ensure",
                "i consent"
            };
        }

        private static void CompleteTestDirectiveActionDefaults(Dictionary<string, object> action, Dictionary<string, object> payload, Dictionary<string, object> hero, string directiveText, bool includeTestValues = true)
        {
            string command = CanonicalCommand(ReadFirstString(action, "command", "commandType", "intent", "type"));
            if (string.IsNullOrWhiteSpace(command))
            {
                command = CommandFromDirectiveText(directiveText);
                if (string.IsNullOrWhiteSpace(command) && LooksLikeNamedSettlementTransferDirective(payload, directiveText))
                {
                    command = "demand_settlement_peace";
                }
            }

            if (!string.IsNullOrWhiteSpace(command))
            {
                action["command"] = command;
            }

            string playerKingdomId = FirstNonEmpty(
                ReadFirstString(payload, "playerKingdomId", "actorKingdomId", "actorKingdomStringId"),
                ReadString(hero, "playerKingdomId", ""));
            string speakerKingdomId = FirstNonEmpty(
                ReadFirstString(payload, "speakerKingdomId", "targetKingdomId", "targetKingdomStringId"),
                ReadString(hero, "kingdomId", ""));
            string playerClanId = FirstNonEmpty(
                ReadFirstString(payload, "playerClanId", "actorClanId", "actorClanStringId"),
                ReadString(hero, "playerClanId", ""));
            string speakerClanId = FirstNonEmpty(
                ReadFirstString(payload, "speakerClanId", "targetClanId", "targetClanStringId"),
                ReadString(hero, "clanId", ""));
            string speakerHeroId = FirstNonEmpty(
                ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId"),
                ReadString(hero, "heroStringId", ""));
            string playerHeroId = FirstNonEmpty(
                ReadFirstString(payload, "playerHeroStringId", "mainHeroStringId", "playerId"),
                ReadFirstString(hero, "playerHeroStringId", "mainHeroStringId"));

            // This command is spoken and performed by the NPC against the player.
            // The generic conversation defaults below are player-to-NPC diplomacy
            // defaults, so applying them here reverses the clans in the audit record
            // even though actorHeroId correctly names the NPC.
            bool npcJoinsPlayerClan = string.Equals(command, "join_clan", StringComparison.OrdinalIgnoreCase);
            bool npcClanJoinsPlayerKingdom = string.Equals(command, "join_kingdom", StringComparison.OrdinalIgnoreCase);
            bool npcClanLeavesKingdom = string.Equals(command, "leave_kingdom", StringComparison.OrdinalIgnoreCase);
            bool npcControlsPlayerService = string.Equals(command, "hire_player_as_mercenary", StringComparison.OrdinalIgnoreCase)
                || string.Equals(command, "dismiss_player_mercenary", StringComparison.OrdinalIgnoreCase)
                || string.Equals(command, "offer_player_vassalage", StringComparison.OrdinalIgnoreCase)
                || string.Equals(command, "dismiss_player_vassal", StringComparison.OrdinalIgnoreCase);
            bool npcTargetsPlayer = string.Equals(command, "attack_player_party", StringComparison.OrdinalIgnoreCase)
                || string.Equals(command, "duel_player", StringComparison.OrdinalIgnoreCase);
            if (npcControlsPlayerService)
            {
                if (!string.IsNullOrWhiteSpace(speakerHeroId)) action["actorHeroId"] = speakerHeroId;
                if (!string.IsNullOrWhiteSpace(speakerClanId)) action["actorClanId"] = speakerClanId;
                if (!string.IsNullOrWhiteSpace(speakerKingdomId))
                {
                    action["actorKingdomId"] = speakerKingdomId;
                    action["targetKingdomId"] = speakerKingdomId;
                }
                if (!string.IsNullOrWhiteSpace(playerClanId)) action["targetClanId"] = playerClanId;
            }
            else if (npcJoinsPlayerClan || npcClanJoinsPlayerKingdom || npcClanLeavesKingdom)
            {
                if (!string.IsNullOrWhiteSpace(speakerHeroId)) action["actorHeroId"] = speakerHeroId;
                if (!string.IsNullOrWhiteSpace(speakerClanId)) action["actorClanId"] = speakerClanId;
                if (npcJoinsPlayerClan && !string.IsNullOrWhiteSpace(playerClanId))
                    action["targetClanId"] = playerClanId;
                else if ((npcClanJoinsPlayerKingdom || npcClanLeavesKingdom) && !string.IsNullOrWhiteSpace(speakerClanId))
                    action["targetClanId"] = speakerClanId;
                if (!string.IsNullOrWhiteSpace(speakerKingdomId)) action["actorKingdomId"] = speakerKingdomId;
                else action.Remove("actorKingdomId");
                if (!npcClanLeavesKingdom && !string.IsNullOrWhiteSpace(playerKingdomId))
                    action["targetKingdomId"] = playerKingdomId;
                else
                {
                    action.Remove("targetKingdomId");
                    action.Remove("targetKingdomStringId");
                    action.Remove("TargetKingdom");
                }
            }
            else if (npcTargetsPlayer)
            {
                string requestedActor = ReadFirstString(action, "actorHeroId", "ActorHero", "FromHero");
                bool actorIsCurrentSpeaker = string.Equals(command, "duel_player", StringComparison.OrdinalIgnoreCase)
                    || string.IsNullOrWhiteSpace(requestedActor)
                    || requestedActor.Equals("speaker", StringComparison.OrdinalIgnoreCase)
                    || requestedActor.Equals("npc", StringComparison.OrdinalIgnoreCase)
                    || requestedActor.Equals(speakerHeroId, StringComparison.OrdinalIgnoreCase);
                if (actorIsCurrentSpeaker && !string.IsNullOrWhiteSpace(speakerHeroId))
                    action["actorHeroId"] = speakerHeroId;
                if (!string.IsNullOrWhiteSpace(playerHeroId)) action["TargetHero"] = playerHeroId;
                if (!string.IsNullOrWhiteSpace(playerClanId)) action["targetClanId"] = playerClanId;
                if (actorIsCurrentSpeaker)
                {
                    if (!string.IsNullOrWhiteSpace(speakerClanId)) action["actorClanId"] = speakerClanId;
                    if (!string.IsNullOrWhiteSpace(speakerKingdomId)) action["actorKingdomId"] = speakerKingdomId;
                    else action.Remove("actorKingdomId");
                }
                else
                {
                    action.Remove("actorClanId");
                    action.Remove("actorKingdomId");
                }
                if (!string.IsNullOrWhiteSpace(playerKingdomId)) action["targetKingdomId"] = playerKingdomId;
                else action.Remove("targetKingdomId");
            }
            else
            {
                AddIfMissing(action, "actorKingdomId", playerKingdomId);
                AddIfMissing(action, "targetKingdomId", speakerKingdomId);
                AddIfMissing(action, "actorClanId", command == "encourage_clan_defection" || command == "exile_clan" || command == "restore_exiled_clan" || command == "support_claimant" || command == "mediate_clan_dispute" ? speakerClanId : playerClanId);
                AddIfMissing(action, "targetClanId", speakerClanId);
            }

            if (string.Equals(command, "start_ruling_clan_rebellion", StringComparison.OrdinalIgnoreCase)
                || string.Equals(command, "recruit_lord_to_rebellion", StringComparison.OrdinalIgnoreCase)
                || string.Equals(command, "join_rebellion", StringComparison.OrdinalIgnoreCase)
                || string.Equals(command, "surrender_rebellion", StringComparison.OrdinalIgnoreCase)
                || string.Equals(command, "consent_government_reduction", StringComparison.OrdinalIgnoreCase))
            {
                AddIfMissing(action, "actorHeroId", playerHeroId);
                AddIfMissing(action, "TargetHero", speakerHeroId);
            }
            else if (string.Equals(command, "duel_player", StringComparison.OrdinalIgnoreCase))
            {
                action["actorHeroId"] = speakerHeroId;
                action["TargetHero"] = playerHeroId;
            }
            else if (ActionFamilyForId(command) == "strategy" || ActionFamilyForId(command) == "regular")
            {
                AddIfMissing(action, "actorHeroId", speakerHeroId);
            }

            bool canUseContextSettlement = CanInferSettlementFromText(command)
                && (includeTestValues || HasExplicitCurrentSettlementReference(directiveText));
            string mentionedSettlement = CanInferSettlementFromText(command)
                && (command != "trade_package"
                    || LooksLikeSettlementTransferDirective(directiveText)
                    || LooksLikeNamedPaidSettlementTradeDirective(payload, directiveText))
                ? FindMentionedSettlementName(payload, directiveText, "") : "";
            string settlementId = string.Empty;
            if (!string.IsNullOrWhiteSpace(mentionedSettlement))
            {
                AddIfMissing(action, "TargetSettlement", mentionedSettlement);
            }
            else if (canUseContextSettlement)
            {
                settlementId = FirstNonEmpty(
                    ReadFirstString(payload, "targetSettlementId", "targetSettlementStringId", "settlementId"),
                    ReadString(hero, "currentSettlementId", ""),
                    FindSettlementIdFromContextBundles(ReadDictionaryList(payload, "contextBundles"), speakerKingdomId, "current_or_target"));
            }

            if (!string.IsNullOrWhiteSpace(settlementId))
            {
                AddIfMissing(action, "targetSettlementId", settlementId);
            }

            if (command == "supply_agreement" && LooksLikeNavalAssetDirective(directiveText) && !string.IsNullOrWhiteSpace(playerKingdomId) && !string.IsNullOrWhiteSpace(speakerKingdomId))
            {
                action["actorKingdomId"] = speakerKingdomId;
                action["targetKingdomId"] = playerKingdomId;
                AddIfMissing(action, "actorHeroId", speakerHeroId);
                AddIfMissing(action, "TargetHero", playerHeroId);
            }

            Dictionary<string, object> terms = ReadDictionary(action, "terms") ?? new Dictionary<string, object>();
            if (!includeTestValues)
            {
                action["terms"] = terms;
                return;
            }
            switch (command)
            {
                case "offer_tribute_peace":
                    AddIfMissing(terms, "dailyTribute", 150);
                    AddIfMissing(terms, "durationDays", 30);
                    break;
                case "demand_reparations_peace":
                    AddIfMissing(terms, "reparationsGold", 15000);
                    AddIfMissing(terms, "dailyTribute", 200);
                    AddIfMissing(terms, "durationDays", 30);
                    break;
                case "demand_settlement_peace":
                case "demand_surrender_peace":
                    if (!string.IsNullOrWhiteSpace(settlementId) && ReadStringList(terms, "settlementIds").Count == 0)
                    {
                        terms["settlementIds"] = new ArrayList { settlementId };
                    }
                    if (command == "demand_surrender_peace")
                    {
                        AddIfMissing(terms, "reparationsGold", 25000);
                        AddIfMissing(terms, "dailyTribute", 300);
                        AddIfMissing(terms, "durationDays", 45);
                    }
                    break;
                case "pay_to_join_war":
                    AddIfMissing(terms, "enemyKingdomId", FindThirdKingdomIdFromContextBundles(ReadDictionaryList(payload, "contextBundles"), playerKingdomId, speakerKingdomId));
                    AddIfMissing(terms, "gold", 25000);
                    break;
                case "war_indemnity":
                case "loan_or_subsidy":
                case "pay_to_stay_neutral":
                    AddIfMissing(terms, "gold", 15000);
                    break;
                case "sign_trade_agreement":
                case "sign_non_aggression_pact":
                case "sign_defensive_pact":
                case "supply_agreement":
                case "demilitarized_border":
                    if (command == "supply_agreement" && LooksLikeNavalAssetDirective(directiveText))
                    {
                        AddIfMissing(terms, "asset", "ships");
                        AddIfMissing(terms, "assetClass", "naval");
                        AddIfMissing(terms, "assetName", "ships");
                        AddIfMissing(terms, "allMatchingAssets", true);
                        AddIfMissing(terms, "mechanicalEffect", "ledger_only_pending_navaldlc_adapter");
                    }

                    AddIfMissing(terms, "durationDays", 90);
                    break;
                case "sign_alliance":
                case "guarantee_independence":
                case "protectorate_or_vassalage":
                    AddIfMissing(terms, "durationDays", 180);
                    break;
                case "duel_player":
                    AddIfMissing(terms, "duelMode", InferDuelModeFromDirective(directiveText));
                    string duelMode = ReadString(terms, "duelMode", "training");
                    if (IsLethalDuelMode(duelMode))
                    {
                        terms["lethal"] = true;
                    }
                    else
                    {
                        AddIfMissing(terms, "lethal", false);
                    }
                    break;
                case "trade_package":
                    ApplyPaidAssetPackageTerms(action, terms, payload, hero, directiveText);
                    break;
                case "ransom_package":
                    ApplyRansomPackageTerms(action, terms, payload, hero, directiveText);
                    break;
                case "diplomatic_package":
                    ApplyCompoundDiplomaticPackageTerms(action, terms, payload, hero, directiveText);
                    break;
                case "marriage_alliance":
                    ApplyMarriageDirectiveTerms(terms, payload, directiveText);
                    break;
                case "consent_government_reduction":
                    AddIfMissing(terms, "consentConfirmed", true);
                    break;
                case "transfer_gold":
                case "transfer_item":
                case "give_gold_to_player":
                    ApplyTransferDirectionDefaults(action, terms, payload, hero, directiveText, command);
                    break;
            }

            if (terms.Count > 0)
            {
                action["terms"] = terms;
            }

            if (string.IsNullOrWhiteSpace(ReadString(action, "source", "")))
            {
                action["source"] = "prompt_override";
            }
            action["requiresAcceptance"] = false;
            if (string.IsNullOrWhiteSpace(ReadString(action, "reason", "")))
            {
                action["reason"] = "Prompt override: " + directiveText;
            }
        }

        private static Dictionary<string, object> BuildFallbackTestDirectiveAction(Dictionary<string, object> payload, Dictionary<string, object> hero, string directiveText, List<string> errors)
        {
            string command = CommandFromDirectiveText(directiveText);
            if (string.IsNullOrWhiteSpace(command) && LooksLikeNamedSettlementTransferDirective(payload, directiveText))
            {
                command = "demand_settlement_peace";
            }

            if (string.IsNullOrWhiteSpace(command))
            {
                errors.Add("No deterministic action mapping matched the directive text.");
                return null;
            }

            Dictionary<string, object> action = new Dictionary<string, object>
            {
                ["command"] = command,
                ["reason"] = "Prompt override: " + directiveText
            };
            CompleteTestDirectiveActionDefaults(action, payload, hero, directiveText);
            CompleteFallbackDirectiveTerms(action, payload, hero, directiveText);
            return action;
        }

        private static void CompleteFallbackDirectiveTerms(Dictionary<string, object> action, Dictionary<string, object> payload, Dictionary<string, object> hero, string directiveText, bool includeTestValues = true)
        {
            if (action == null)
            {
                return;
            }

            string command = CanonicalCommand(ReadFirstString(action, "command", "commandType", "intent", "type"));
            Dictionary<string, object> terms = ToCaseInsensitiveDictionary(ReadDictionary(action, "terms") ?? new Dictionary<string, object>());
            string speakerHeroId = FirstNonEmpty(
                ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId"),
                ReadString(hero, "heroStringId", ""));
            string playerHeroId = ReadString(payload, "playerHeroStringId", "");
            string playerKingdomId = FirstNonEmpty(
                ReadFirstString(payload, "playerKingdomId", "actorKingdomId", "actorKingdomStringId"),
                ReadString(hero, "playerKingdomId", ""));
            string speakerKingdomId = FirstNonEmpty(
                ReadFirstString(payload, "speakerKingdomId", "targetKingdomId", "targetKingdomStringId"),
                ReadString(hero, "kingdomId", ""));

            switch (command)
            {
                case "demand_reparations_peace":
                    int reparationsGold = ExtractMoneyAmount(directiveText, includeTestValues ? ExtractFirstInteger(directiveText, 0) : 0);
                    if (reparationsGold > 0)
                    {
                        AddIfMissing(terms, "reparationsGold", reparationsGold);
                    }

                    if (includeTestValues) AddIfMissing(terms, "durationDays", 30);
                    break;
                case "give_gold_to_player":
                    if (includeTestValues || TransferDirectionNeedsResolution(action, terms)) ApplyTransferDirectionDefaults(action, terms, payload, hero, directiveText, command);
                    if (!includeTestValues && (ReadFirstString(action, "GoldAmount", "gold").Length > 0
                        || ReadFirstString(terms, "GoldAmount", "gold").Length > 0)) break;
                    int giftGold = ExtractMoneyAmount(directiveText, includeTestValues ? ExtractFirstInteger(directiveText, 1000) : 0);
                    if (giftGold <= 0) break;
                    AddIfMissing(action, "GoldAmount", giftGold);
                    AddIfMissing(terms, "gold", giftGold);
                    AddIfMissing(terms, "GoldAmount", giftGold);
                    break;
                case "transfer_gold":
                    if (includeTestValues || TransferDirectionNeedsResolution(action, terms)) ApplyTransferDirectionDefaults(action, terms, payload, hero, directiveText, command);
                    if (!includeTestValues && (ReadFirstString(action, "GoldAmount", "gold").Length > 0
                        || ReadFirstString(terms, "GoldAmount", "gold").Length > 0)) break;
                    int transferGold = ExtractMoneyAmount(directiveText, includeTestValues ? ExtractFirstInteger(directiveText, 1000) : 0);
                    if (transferGold <= 0) break;
                    AddIfMissing(action, "GoldAmount", transferGold);
                    AddIfMissing(terms, "gold", transferGold);
                    AddIfMissing(terms, "GoldAmount", transferGold);
                    break;
                case "transfer_item":
                    if (includeTestValues || TransferDirectionNeedsResolution(action, terms)) ApplyTransferDirectionDefaults(action, terms, payload, hero, directiveText, command);
                    string item = FirstNonEmpty(ReadFirstString(action, "Item", "itemId"),
                        ReadFirstString(terms, "itemId", "item", "Item"), ExtractDirectiveItemName(directiveText));
                    AddIfMissing(action, "Item", item);
                    AddIfMissing(terms, "item", item);
                    int itemAmount = ReadInt(action, "Amount", 0);
                    if (itemAmount <= 0)
                    {
                        itemAmount = ExtractInventoryItemAmount(directiveText, item);
                    }
                    if (itemAmount <= 0
                        && Regex.IsMatch(item, @"^(?:armor|armour|helmet|sword|shield|cloak|boots|gloves|bow|spear|axe)$", RegexOptions.IgnoreCase)
                        && Regex.IsMatch(directiveText,
                            @"\b(?:my|your|his|her|the|this|that|a|an)\s+" + Regex.Escape(item) + @"\b",
                            RegexOptions.IgnoreCase))
                    {
                        itemAmount = 1;
                    }
                    if (itemAmount > 0 || includeTestValues)
                        AddIfMissing(terms, "amount", itemAmount > 0 ? itemAmount : ExtractFirstInteger(directiveText, 1));
                    break;
                case "follow":
                    if (DirectiveHasAny(directiveText, "follow me", "follow us", "follow my party", "escort me", "escort my party", "come with me"))
                    {
                        AddIfMissing(action, "TargetParty", "player party");
                        AddIfMissing(terms, "targetParty", "player party");
                    }
                    break;
                case "trade_package":
                    ApplyPaidAssetPackageTerms(action, terms, payload, hero, directiveText);
                    break;
                case "ransom_package":
                    ApplyRansomPackageTerms(action, terms, payload, hero, directiveText);
                    break;
                case "diplomatic_package":
                    ApplyCompoundDiplomaticPackageTerms(action, terms, payload, hero, directiveText);
                    break;
                case "marriage_alliance":
                    ApplyMarriageDirectiveTerms(terms, payload, directiveText);
                    break;
                case "supply_agreement":
                    if (LooksLikeNavalAssetDirective(directiveText))
                    {
                        if (!string.IsNullOrWhiteSpace(speakerKingdomId))
                        {
                            action["actorKingdomId"] = speakerKingdomId;
                        }

                        if (!string.IsNullOrWhiteSpace(playerKingdomId))
                        {
                            action["targetKingdomId"] = playerKingdomId;
                        }

                        AddIfMissing(action, "actorHeroId", speakerHeroId);
                        AddIfMissing(action, "TargetHero", playerHeroId);
                        AddIfMissing(terms, "asset", "ships");
                        AddIfMissing(terms, "assetClass", "naval");
                        AddIfMissing(terms, "assetName", "ships");
                        AddIfMissing(terms, "allMatchingAssets", true);
                        AddIfMissing(terms, "mechanicalEffect", "ledger_only_pending_navaldlc_adapter");
                    }
                    break;
            }

            if (terms.Count > 0)
            {
                action["terms"] = terms;
            }
        }

        private static string CommandFromDirectiveText(string text)
        {
            string q = (text ?? string.Empty).ToLowerInvariant();
            if (LooksLikeGovernmentReductionConsentRequest(q)) return "consent_government_reduction";
            if (LooksLikeFullSurrenderDirective(q)) return "demand_surrender_peace";
            if (LooksLikeReparationsPeaceDirective(q)) return "demand_reparations_peace";
            if (!LooksLikeGiveGoldDirective(q) && !DirectiveHasAny(q, "gold", "denar", "denars", "coin", "coins", "money", "silver") && LooksLikeSettlementForPeaceDirective(q)) return "demand_settlement_peace";
            if (LooksLikeCompoundPoliticalPackageDirective(q)) return "diplomatic_package";
            if (q.Contains("trade agreement")) return "sign_trade_agreement";
            if (q.Contains("non aggression") || q.Contains("non-aggression")) return "sign_non_aggression_pact";
            if (q.Contains("defensive pact")) return "sign_defensive_pact";
            if (q.Contains("marriage") || q.Contains("marry") || q.Contains("betroth")) return "marriage_alliance";
            if (q.Contains("alliance") || Regex.IsMatch(q, @"\ball(?:y|ies|ied)\b", RegexOptions.IgnoreCase)) return "sign_alliance";
            if (q.Contains("ransom")) return "ransom_package";
            if (LooksLikePaidAssetTradeDirective(q)) return "trade_package";
            if (LooksLikeNamedPaidExchangeDirective(q)) return "trade_package";
            if (q.Contains("break treaty") || q.Contains("end treaty") || q.Contains("cancel treaty")) return "break_treaty";
            if (q.Contains("exchange prisoner")) return "exchange_prisoners";
            if (q.Contains("hostage")) return "hostage_guarantee";
            if (q.Contains("indemnity")) return "war_indemnity";
            if (q.Contains("recognize") && (q.Contains("conquest") || q.Contains("claim"))) return "recognize_conquest";
            if (q.Contains("return") && q.Contains("settlement")) return "return_occupied_settlement";
            if (q.Contains("demilitarized") || q.Contains("demilitarised")) return "demilitarized_border";
            if (LooksLikeNavalAssetDirective(q)) return "trade_package";
            if (LooksLikeSettlementTransferDirective(q)) return "demand_settlement_peace";
            if (q.Contains("supply")) return "supply_agreement";
            if (q.Contains("loan") || q.Contains("subsidy")) return "loan_or_subsidy";
            if (q.Contains("stay neutral") || q.Contains("neutrality")) return "pay_to_stay_neutral";
            if (q.Contains("join war")) return "pay_to_join_war";
            if (q.Contains("guarantee") && q.Contains("independence")) return "guarantee_independence";
            if (q.Contains("hire") && q.Contains("mercenary") && q.Contains("clan")) return "hire_mercenary_clan";
            if (q.Contains("hire") && q.Contains("mercenary")) return "hire_player_as_mercenary";
            if (q.Contains("dismiss") && q.Contains("mercenary")) return "dismiss_player_mercenary";
            if (q.Contains("offer") && q.Contains("vassal")) return "offer_player_vassalage";
            if (q.Contains("dismiss") && q.Contains("vassal")) return "dismiss_player_vassal";
            if (q.Contains("join kingdom") || q.Contains("join my kingdom") || q.Contains("join our kingdom")) return "join_kingdom";
            if (q.Contains("leave kingdom")) return "leave_kingdom";
            if (q.Contains("join clan")) return "join_clan";
            if (q.Contains("leave clan")) return "leave_clan";
            if (q.Contains("protectorate") || q.Contains("vassalage arrangement")) return "protectorate_or_vassalage";
            if (q.Contains("stop following") || q.Contains("break off the escort") || q.Contains("go your own way") || q.Contains("no need to trail") || q.Contains("trail us any longer")) return "stop_following";
            if (q.Contains("follow on map") || q.Contains("follow in scene") || q.Contains("follow me on the map") || q.Contains("follow my party") || q.Contains("follow our party") || q.Contains("follow me") || q.Contains("follow us") || q.Contains("escort me") || q.Contains("escort us") || q.Contains("escort my party") || q.Contains("come with me") || q.Contains("walk with me") || q.Contains("stay by my side") || q.Contains("stay close") || q.Contains("walk after me") || q.Contains("stay behind our party") || q.Contains("keep to our route")) return "follow";
            if (DirectiveHasAny(q, "go to", "head to", "head for", "travel to", "ride to", "march to", "move to", "proceed to", "return to", "make for", "take your party to", "bring your warband to")) return "go_to_settlement";
            if (DirectiveHasAny(q, "patrol", "circle", "make a circuit", "watch the approaches", "watch its approaches")) return "patrol_around_settlement";
            if (DirectiveHasAny(q, "wait near", "wait outside", "hold near", "hold your position near", "remain near", "remain in the vicinity of")) return "wait_near_settlement";
            if (q.Contains("raid") && q.Contains("village")) return "raid_village";
            if (q.Contains("besiege")) return "besiege_settlement";
            if (q.Contains("create party") || q.Contains("make a party")) return "create_party";
            if (q.Contains("show the way")) return "show_the_way";
            if (q.Contains("attack player party") || q.Contains("attack my party")) return "attack_player_party";
            if (q.Contains("attack party")) return "attack_party";
            if (q.Contains("surrender to player") || q.Contains("surrender to me")) return "surrender_to_player";
            if (q.Contains("leave player alone") || q.Contains("leave me alone")) return "leave_player_alone";
            if (q.Contains("kill")) return "kill_character";
            if (q.Contains("duel")) return "duel_player";
            if (q.Contains("reparation")) return "demand_reparations_peace";
            if (q.Contains("transfer gold") || q.Contains("transfer denars")) return "transfer_gold";
            if (LooksLikeGiveGoldDirective(q)) return LooksLikePlayerToSpeakerTransfer(q) ? "transfer_gold" : "give_gold_to_player";
            if (q.Contains("transfer workshop") || q.Contains("give workshop")) return "transfer_workshop";
            if (q.Contains("transfer prisoner") || q.Contains("release prisoner")) return "transfer_prisoner";
            if (LooksLikeGiveItemDirective(q)) return "transfer_item";
            if (q.Contains("declare war")) return "declare_war";
            if (q.Contains("full surrender") || q.Contains("surrender terms")) return "demand_surrender_peace";
            if (q.Contains("settlement") && (q.Contains("peace") || q.Contains("surrender"))) return "demand_settlement_peace";
            if (q.Contains("tribute")) return "offer_tribute_peace";
            if (q.Contains("peace")) return "make_peace";
            if (q.Contains("promise")) return "record_promise";
            if (q.Contains("recruit") || q.Contains("recover")) return "recruit_and_recover";
            if (q.Contains("form army") || q.Contains("build an army")) return "form_army";
            if (q.Contains("capture")) return "capture_settlement_plan";
            if (q.Contains("attack") || q.Contains("besiege")) return "attack_settlement";
            if ((q.Contains("join my rebellion") || q.Contains("join our rebellion") || q.Contains("support my rebellion"))) return "recruit_lord_to_rebellion";
            if (q.Contains("join your rebellion") || q.Contains("fight for your rebellion") || q.Contains("join the rebels")) return "join_rebellion";
            if (q.Contains("surrender the rebellion") || q.Contains("yield the rebellion") || q.Contains("rebellion surrender")) return "surrender_rebellion";
            if (q.Contains("rebellion") || q.Contains("revolt")) return "start_ruling_clan_rebellion";
            if (q.Contains("install") && q.Contains("ruling")) return "install_ruling_clan";
            if (q.Contains("claimant")) return "support_claimant";
            if (q.Contains("defect") || q.Contains("defection")) return "encourage_clan_defection";
            if (q.Contains("restore") && q.Contains("exile")) return "restore_exiled_clan";
            if (q.Contains("exile")) return "exile_clan";
            if (q.Contains("mediate")) return "mediate_clan_dispute";
            return string.Empty;
        }

        private static bool LooksLikeNamedPaidExchangeDirective(string text)
        {
            string q = (text ?? string.Empty).ToLowerInvariant();
            bool hasMoney = DirectiveHasAny(q, "gold", "denar", "denars", "coin", "coins", "money", "silver");
            bool hasExchangeShape = DirectiveHasAny(q, " for ", "in exchange", "buy", "purchase", "sell", "sold", "price");
            bool treatyLike = DirectiveHasAny(q, "for peace", "peace treaty", "trade agreement", "alliance", "tribute", "reparations", "indemnity");
            return hasMoney && hasExchangeShape && !treatyLike;
        }

        private static bool LooksLikeCompoundPoliticalPackageDirective(string text)
        {
            string q = (text ?? string.Empty).ToLowerInvariant();
            bool hasPoliticalTerm = DirectiveHasAny(q,
                "marriage", "marry", "betroth", "dowry", "family member", "clan alliance",
                "alliance package", "non-aggression", "non aggression", "recognition", "treaty package",
                "diplomatic package", "public alliance", "public non-aggression", "protectorate", "neutrality");
            bool hasExchangeShape = DirectiveHasAny(q, " in exchange", "exchange for", " as dowry", "dowry", " package", " bargain", " price for", " for a public", " for the release");
            bool hasAssetTerm = DirectiveHasAny(q, "gold", "denar", "denars", "coin", "coins", "money", "grain", "horses", "horse", "supplies", "prisoner", "captive", "hostage", "settlement", "town", "castle", "fief");
            return hasPoliticalTerm && hasExchangeShape && hasAssetTerm;
        }

        private static bool DirectiveHasAny(string text, params string[] phrases)
        {
            foreach (string phrase in phrases ?? new string[0])
            {
                if (!string.IsNullOrWhiteSpace(phrase) && text.IndexOf(phrase, StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    return true;
                }
            }

            return false;
        }

        private static bool LooksLikeGiveGoldDirective(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            // Bannerlord exposes Silver as a transferable inventory good. Treat currency
            // as denars/gold/coins here so requests such as "five units of Silver" are
            // not collapsed into a gold transfer.
            bool hasMoney = DirectiveHasAny(text, "gold", "denar", "denars", "coin", "coins", "money");
            bool hasGiveVerb = DirectiveHasAny(text, "give", "pay", "hand", "transfer", "send", "grant", "gift", "offer");
            return hasMoney && hasGiveVerb;
        }

        private static bool LooksLikeGiveItemDirective(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            if (LooksLikeSettlementTransferDirective(text) || LooksLikeNavalAssetDirective(text))
            {
                return false;
            }

            bool hasGiveVerb = DirectiveHasAny(text, "give", "hand", "transfer", "send", "grant", "take", "offer", "provide", "gift", "donate");
            bool hasItemWord = DirectiveHasAny(text,
                "item", "armor", "armour", "helmet", "boots", "gloves", "cloak", "cape", "weapon", "sword", "axe", "spear", "bow", "horse", "mount", "shield",
                "grain", "food", "supplies", "supply", "goods", "tools", "hardwood", "iron", "silver", "linen", "wool", "velvet", "pottery", "leather", "fur", "jewelry",
                "beer", "wine", "oil", "dates", "fish", "meat", "butter", "cheese");
            return hasGiveVerb && hasItemWord;
        }

        private static bool LooksLikeSettlementTransferDirective(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            if (DirectiveHasAny(text, "full surrender", "capitulation", "all towns", "all castles"))
            {
                return false;
            }

            bool hasTransferVerb = DirectiveHasAny(text, "give", "grant", "hand over", "transfer", "cede", "surrender", "yield", "turn over", "award");
            bool hasSettlementWord = DirectiveHasAny(text, "settlement", "city", "town", "castle", "fortress", "keep", "fief");
            return hasTransferVerb && hasSettlementWord;
        }

        private static bool LooksLikeNavalAssetDirective(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            bool hasTransferVerb = DirectiveHasAny(text, "give", "grant", "hand over", "transfer", "cede", "surrender", "loan", "lend", "provide", "assign", "offer", "sell", "trade", "buy", "purchase", "gift");
            return hasTransferVerb && HasNavalAssetWord(text);
        }

        private static bool HasNavalAssetWord(string text)
        {
            return Regex.IsMatch(text ?? string.Empty, @"\b(?:ship|ships|fleet|flagship|vessel|vessels|boat|boats|naval|war\s+sails|warsails)\b", RegexOptions.IgnoreCase);
        }

        private static bool LooksLikePaidAssetTradeDirective(string text)
        {
            string q = (text ?? string.Empty).ToLowerInvariant();
            bool hasMoney = DirectiveHasAny(q, "gold", "denar", "denars", "coin", "coins", "money", "silver", "price");
            bool hasTradeShape = Regex.IsMatch(q, @"\bfor\b", RegexOptions.IgnoreCase) || DirectiveHasAny(q, "price", "trade", "sell", "sold", "buy", "purchase", "deal", "bargain", "in exchange", "pay", "payment", "transfer");
            bool hasAsset = HasNavalAssetWord(q) || DirectiveHasAny(q, "grain", "food", "supplies", "goods", "planks", "felt", "meat", "hides", "tools", "iron", "hardwood", "charcoal", "steel", "horses", "mount", "armor", "armour", "helmet", "shield", "weapon", "sword", "bow", "prisoner", "settlement", "town", "city", "castle", "fief", "workshop");
            return hasMoney && hasTradeShape && hasAsset;
        }

        private static bool LooksLikePlayerToSpeakerTransfer(string text)
        {
            string q = (text ?? string.Empty).ToLowerInvariant();
            return LooksLikePlayerAssetToSpeaker(q)
                || DirectiveHasAny(q, "i pay you", "from me to you");
        }

        private static bool LooksLikeSpeakerToPlayerTransfer(string text)
        {
            string q = (text ?? string.Empty).ToLowerInvariant();
            return LooksLikeSpeakerAssetToPlayer(q)
                || DirectiveHasAny(q, "give me", "give us", "hand me", "hand over to me", "transfer to me", "send me", "grant me", "provide me");
        }

        private static bool LooksLikePlayerAssetToSpeaker(string text)
        {
            string q = (text ?? string.Empty).ToLowerInvariant();
            if (DirectiveHasAny(q,
                    "here take", "here are", "here is", "here's", "they are yours", "take my", "take this", "i give you", "i'll give you", "i will give you",
                    "give them to you", "i offer you", "i send you", "i sell you", "i will sell you", "i'll sell you", "i sold you", "buy my", "purchase my", "from me to you",
                    "my grain", "my goods", "my supplies", "my ships", "my fleet"))
            {
                return true;
            }

            return Regex.IsMatch(q, @"\bi\s+want\s+\d[\d,]*\s*(denars?|gold|coins?|silver|money)\s+for\b", RegexOptions.IgnoreCase)
                || Regex.IsMatch(q, @"\bfor\s+\d[\d,]*\s*(denars?|gold|coins?|silver|money)\b", RegexOptions.IgnoreCase) && DirectiveHasAny(q, "my ships", "my fleet", "my grain", "my goods", "my supplies")
                || Regex.IsMatch(q, @"\b(?:take|receive|accept)\b.{0,160}\bfrom\s+me\b", RegexOptions.IgnoreCase);
        }

        private static bool LooksLikeSpeakerAssetToPlayer(string text)
        {
            string q = (text ?? string.Empty).ToLowerInvariant();
            return DirectiveHasAny(q,
                "sell me", "offer me", "your armor", "your armour", "your sword", "your weapon", "your horse", "your shield", "your grain", "your goods", "your ships", "your fleet")
                || Regex.IsMatch(q, @"\bi\s+(?:will\s+)?(?:pay|give)\s+you\s+\d[\d,]*\s*(denars?|gold|coins?|silver|money)\s+for\s+your\b", RegexOptions.IgnoreCase)
                || Regex.IsMatch(q, @"\bi\s+want\s+your\b", RegexOptions.IgnoreCase);
        }

        private static int ExtractMoneyAmount(string text, int fallback)
        {
            string q = text ?? string.Empty;
            Match amountThenCurrency = Regex.Match(q, @"\b(\d[\d,]*)\s*(denars?|gold|coins?|silver|money)\b", RegexOptions.IgnoreCase);
            if (amountThenCurrency.Success)
            {
                string cleaned = amountThenCurrency.Groups[1].Value.Replace(",", "");
                if (int.TryParse(cleaned, out int value) && value > 0)
                {
                    return value;
                }
            }

            Match currencyThenAmount = Regex.Match(q, @"\b(denars?|gold|coins?|silver|money)\s*(?:of|for|worth)?\s*(\d[\d,]*)\b", RegexOptions.IgnoreCase);
            if (currencyThenAmount.Success)
            {
                string cleaned = currencyThenAmount.Groups[2].Value.Replace(",", "");
                if (int.TryParse(cleaned, out int value) && value > 0)
                {
                    return value;
                }
            }

            string numberWords = @"(?:a|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety|hundred|thousand|million|and)";
            Match wordsThenCurrency = Regex.Match(q, @"\b(" + numberWords + @"(?:[\s-]+" + numberWords + @")*)\s+(?:denars?|gold|coins?|silver|money)\b", RegexOptions.IgnoreCase);
            if (wordsThenCurrency.Success && TryParseEnglishNumber(wordsThenCurrency.Groups[1].Value, out int spokenValue) && spokenValue > 0)
            {
                return spokenValue;
            }

            Match currencyThenWords = Regex.Match(q, @"\b(?:denars?|gold|coins?|silver|money)\s*(?:of|for|worth)?\s+(" + numberWords + @"(?:[\s-]+" + numberWords + @")*)\b", RegexOptions.IgnoreCase);
            if (currencyThenWords.Success && TryParseEnglishNumber(currencyThenWords.Groups[1].Value, out spokenValue) && spokenValue > 0)
            {
                return spokenValue;
            }

            return fallback;
        }

        private static bool TryParseEnglishNumber(string text, out int value)
        {
            value = 0;
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            Dictionary<string, int> small = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase)
            {
                ["a"] = 1, ["one"] = 1, ["two"] = 2, ["three"] = 3, ["four"] = 4, ["five"] = 5,
                ["six"] = 6, ["seven"] = 7, ["eight"] = 8, ["nine"] = 9, ["ten"] = 10,
                ["eleven"] = 11, ["twelve"] = 12, ["thirteen"] = 13, ["fourteen"] = 14, ["fifteen"] = 15,
                ["sixteen"] = 16, ["seventeen"] = 17, ["eighteen"] = 18, ["nineteen"] = 19,
                ["twenty"] = 20, ["thirty"] = 30, ["forty"] = 40, ["fifty"] = 50,
                ["sixty"] = 60, ["seventy"] = 70, ["eighty"] = 80, ["ninety"] = 90
            };
            long total = 0;
            long current = 0;
            bool sawNumber = false;
            foreach (string rawToken in Regex.Split(text.ToLowerInvariant().Replace('-', ' '), @"\s+"))
            {
                string token = rawToken.Trim();
                if (string.IsNullOrWhiteSpace(token) || token == "and")
                {
                    continue;
                }

                if (small.TryGetValue(token, out int smallValue))
                {
                    current += smallValue;
                    sawNumber = true;
                    continue;
                }

                if (token == "hundred")
                {
                    current = Math.Max(1, current) * 100;
                    sawNumber = true;
                    continue;
                }

                if (token == "thousand" || token == "million")
                {
                    long scale = token == "thousand" ? 1000L : 1000000L;
                    total += Math.Max(1, current) * scale;
                    current = 0;
                    sawNumber = true;
                    continue;
                }

                return false;
            }

            long parsed = total + current;
            if (!sawNumber || parsed <= 0 || parsed > int.MaxValue)
            {
                return false;
            }

            value = (int)parsed;
            return true;
        }

        private static void ApplyPaidAssetPackageTerms(Dictionary<string, object> action, Dictionary<string, object> terms, Dictionary<string, object> payload, Dictionary<string, object> hero, string directiveText)
        {
            if (action == null || terms == null)
            {
                return;
            }

            string directive = LatestPlayerDirectiveOrText(directiveText);
            bool latestHasConcreteAsset = LooksLikePaidAssetTradeDirective(directive)
                || LooksLikeNamedPaidExchangeDirective(directive)
                || LooksLikeNavalAssetDirective(directive)
                || LooksLikeSettlementTransferDirective(directive)
                || LooksLikeGiveItemDirective(directive)
                || DirectiveHasAny(directive, "ransom", "prisoner", "workshop");
            if (!latestHasConcreteAsset && !string.Equals(directive, directiveText, StringComparison.Ordinal))
            {
                directive = directiveText;
            }

            string q = directive.ToLowerInvariant();
            bool isValuableAssetPackage = LooksLikePaidAssetTradeDirective(q)
                || LooksLikeNamedPaidExchangeDirective(q)
                || LooksLikeNavalAssetDirective(q)
                || LooksLikeSettlementTransferDirective(q)
                || LooksLikeGiveItemDirective(q)
                || DirectiveHasAny(q, "ransom", "prisoner", "workshop");
            if (!isValuableAssetPackage)
            {
                return;
            }

            bool isNavalAssetPackage = HasNavalAssetWord(q)
                || DirectiveHasAny(ReadFirstString(terms, "asset", "assetClass", "assetName", "item", "Item"), "ship", "fleet", "vessel", "boat", "naval")
                || DirectiveHasAny(ReadFirstString(action, "asset", "assetClass", "assetName", "item", "Item"), "ship", "fleet", "vessel", "boat", "naval");
            bool isSettlementPackage = LooksLikeSettlementTransferDirective(q)
                || !string.IsNullOrWhiteSpace(ReadFirstString(action, "TargetSettlement", "targetSettlementId", "targetSettlementStringId"))
                || !string.IsNullOrWhiteSpace(ReadFirstString(terms, "TargetSettlement", "targetSettlementId", "targetSettlementStringId"));
            bool isPrisonerPackage = DirectiveHasAny(q, "ransom", "prisoner", "captive", "hostage")
                || !string.IsNullOrWhiteSpace(ReadFirstString(action, "PrisonerHero", "prisonerHero", "prisonerHeroStringId"))
                || !string.IsNullOrWhiteSpace(ReadFirstString(terms, "PrisonerHero", "prisonerHero", "prisonerHeroStringId"));
            bool isWorkshopPackage = DirectiveHasAny(q, "workshop")
                || !string.IsNullOrWhiteSpace(ReadFirstString(action, "Workshop", "workshop", "workshopId"))
                || !string.IsNullOrWhiteSpace(ReadFirstString(terms, "Workshop", "workshop", "workshopId"));

            string speakerHeroId = FirstNonEmpty(
                ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId"),
                ReadString(hero, "heroStringId", ""));
            string playerHeroId = ReadString(payload, "playerHeroStringId", "");
            string playerKingdomId = FirstNonEmpty(
                ReadFirstString(payload, "playerKingdomId", "actorKingdomId", "actorKingdomStringId"),
                ReadString(hero, "playerKingdomId", ""));
            string speakerKingdomId = FirstNonEmpty(
                ReadFirstString(payload, "speakerKingdomId", "targetKingdomId", "targetKingdomStringId"),
                ReadString(hero, "kingdomId", ""));
            bool playerToSpeaker = LooksLikePlayerAssetToSpeaker(q);
            bool speakerToPlayer = LooksLikeSpeakerAssetToPlayer(q);
            if (playerToSpeaker && speakerToPlayer)
            {
                speakerToPlayer = !DirectiveHasAny(q, "my ships", "my fleet", "my grain", "my goods", "my supplies", "they are yours", "give them to you");
                playerToSpeaker = !speakerToPlayer;
            }

            string assetFromHero = playerToSpeaker ? playerHeroId : speakerHeroId;
            string assetToHero = playerToSpeaker ? speakerHeroId : playerHeroId;
            string goldFromHero = playerToSpeaker ? speakerHeroId : playerHeroId;
            string goldToHero = playerToSpeaker ? playerHeroId : speakerHeroId;
            string actorKingdomId = playerToSpeaker ? playerKingdomId : speakerKingdomId;
            string targetKingdomId = playerToSpeaker ? speakerKingdomId : playerKingdomId;

            if (!string.IsNullOrWhiteSpace(actorKingdomId))
            {
                action["actorKingdomId"] = actorKingdomId;
            }

            if (!string.IsNullOrWhiteSpace(targetKingdomId))
            {
                action["targetKingdomId"] = targetKingdomId;
            }

            if (!string.IsNullOrWhiteSpace(assetFromHero))
            {
                action["actorHeroId"] = assetFromHero;
                action["FromHero"] = assetFromHero;
                terms["assetFromHeroStringId"] = assetFromHero;
                terms["itemFromHeroStringId"] = assetFromHero;
            }

            if (!string.IsNullOrWhiteSpace(assetToHero))
            {
                action["TargetHero"] = assetToHero;
                action["ToHero"] = assetToHero;
                terms["assetToHeroStringId"] = assetToHero;
                terms["itemToHeroStringId"] = assetToHero;
                terms["settlementToHeroStringId"] = assetToHero;
                terms["workshopToHeroStringId"] = assetToHero;
                terms["prisonerToHeroStringId"] = assetToHero;
            }

            if (!string.IsNullOrWhiteSpace(goldFromHero))
            {
                terms["goldFromHeroStringId"] = goldFromHero;
            }

            if (!string.IsNullOrWhiteSpace(goldToHero))
            {
                terms["goldToHeroStringId"] = goldToHero;
            }

            int gold = ExtractMoneyAmount(directive, 0);
            if (gold > 0)
            {
                AddIfMissing(action, "GoldAmount", gold);
                AddIfMissing(terms, "gold", gold);
                AddIfMissing(terms, "GoldAmount", gold);
            }

            if (HasNavalAssetWord(q))
            {
                AddIfMissing(terms, "asset", "ships");
                AddIfMissing(terms, "assetClass", "naval");
                AddIfMissing(terms, "assetName", "ships");
                AddIfMissing(terms, "allMatchingAssets", true);
            }

            if (isSettlementPackage)
            {
                string settlement = FirstNonEmpty(
                    ReadFirstString(action, "TargetSettlement", "targetSettlementStringId", "targetSettlementId"),
                    ReadFirstString(terms, "TargetSettlement", "targetSettlementStringId", "targetSettlementId"),
                    FindMentionedSettlementName(payload, directive, ""));
                if (!string.IsNullOrWhiteSpace(settlement))
                {
                    action["TargetSettlement"] = settlement;
                    terms["targetSettlementStringId"] = settlement;
                }
            }

            if (isPrisonerPackage)
            {
                string prisoner = FirstNonEmpty(
                    ReadFirstString(action, "PrisonerHero", "prisonerHero", "prisonerHeroStringId", "TargetHero"),
                    ReadFirstString(terms, "PrisonerHero", "prisonerHero", "prisonerHeroStringId"),
                    FindMentionedHeroName(payload, directive));
                if (string.IsNullOrWhiteSpace(prisoner) && DirectiveHasAny(q, "prisoner", "captive", "hostage"))
                {
                    prisoner = "prisoner";
                }

                if (!string.IsNullOrWhiteSpace(prisoner))
                {
                    action["PrisonerHero"] = prisoner;
                    terms["prisonerHeroStringId"] = prisoner;
                }
            }

            if (isWorkshopPackage)
            {
                string workshop = FirstNonEmpty(
                    ReadFirstString(action, "Workshop", "workshop", "workshopId"),
                    ReadFirstString(terms, "Workshop", "workshop", "workshopId"));
                if (!string.IsNullOrWhiteSpace(workshop))
                {
                    action["Workshop"] = workshop;
                    terms["workshop"] = workshop;
                }
            }

            if (!isNavalAssetPackage && !isSettlementPackage && !isPrisonerPackage && !isWorkshopPackage)
            {
                List<Dictionary<string, object>> itemTerms = BuildDirectiveItemTerms(directive, assetFromHero, assetToHero, payload);
                if (itemTerms.Count > 1)
                {
                    terms["items"] = itemTerms;
                }
                else
                {
                    Dictionary<string, object> itemTerm = itemTerms.FirstOrDefault();
                    string item = FirstNonEmpty(
                        ReadFirstString(action, "Item", "item", "itemId"),
                        ReadFirstString(terms, "Item", "item", "itemId"),
                        ReadString(itemTerm, "itemId", string.Empty),
                        ExtractDirectiveItemName(directive));
                    int amount = itemTerm == null ? ExtractNonMoneyAmount(directive, 1) : ReadInt(itemTerm, "amount", ExtractNonMoneyAmount(directive, 1));
                    AddIfMissing(action, "Item", item);
                    AddIfMissing(terms, "item", item);
                    AddIfMissing(terms, "amount", amount);
                }
            }

            AddIfMissing(terms, "packageText", LimitText(StripDirectiveMarkers(directive), 800));
        }

        private static void ApplyRansomPackageTerms(Dictionary<string, object> action, Dictionary<string, object> terms, Dictionary<string, object> payload, Dictionary<string, object> hero, string directiveText)
        {
            if (action == null || terms == null)
            {
                return;
            }

            string directive = LatestPlayerDirectiveOrText(directiveText);
            Dictionary<string, object> index = ReadDictionary(payload, "actionResolutionIndex") ?? new Dictionary<string, object>();
            string speakerHeroId = FirstNonEmpty(
                ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId"),
                ReadString(hero, "heroStringId", ""));
            string playerHeroId = ReadString(payload, "playerHeroStringId", "");
            string speakerKingdomId = FirstNonEmpty(
                ReadFirstString(payload, "speakerKingdomId", "targetKingdomId", "targetKingdomStringId"),
                ReadString(hero, "kingdomId", ""),
                ResolveAlias(index, "kingdom", "speaker_kingdom"));
            string playerKingdomId = FirstNonEmpty(
                ReadFirstString(payload, "playerKingdomId", "actorKingdomId", "actorKingdomStringId"),
                ReadString(hero, "playerKingdomId", ""),
                ResolveAlias(index, "kingdom", "player_kingdom"));
            string speakerClanId = FirstNonEmpty(
                ReadFirstString(payload, "speakerClanId", "targetClanId", "targetClanStringId"),
                ReadString(hero, "clanId", ""));
            string playerClanId = FirstNonEmpty(
                ReadFirstString(payload, "playerClanId", "actorClanId", "actorClanStringId"),
                ReadString(hero, "playerClanId", ""));

            // Ransom semantics are actor=captor/payee and target=payer/recipient. Preserve
            // explicit manual/test direction, but repair planner defaults so clan and gold
            // direction agree with whichever conversation participant is the actor.
            string source = ReadString(action, "source", "");
            bool conversationPlanner = string.Equals(source, "hidden_action_planner", StringComparison.OrdinalIgnoreCase)
                || string.Equals(source, "test_lab_action_gate", StringComparison.OrdinalIgnoreCase);
            bool autonomousWorldDiplomacy = string.Equals(source,
                "world_diplomacy_director", StringComparison.OrdinalIgnoreCase);
            if (conversationPlanner)
            {
                if (!string.IsNullOrWhiteSpace(speakerKingdomId)) action["actorKingdomId"] = speakerKingdomId;
                if (!string.IsNullOrWhiteSpace(playerKingdomId)) action["targetKingdomId"] = playerKingdomId;
            }

            string actorKingdomReference = ReadFirstString(action, "actorKingdomStringId", "actorKingdomId", "kingdomId");
            string targetKingdomReference = ReadFirstString(action, "targetKingdomStringId", "targetKingdomId", "TargetKingdom");
            if (string.IsNullOrWhiteSpace(actorKingdomReference) && !string.IsNullOrWhiteSpace(speakerKingdomId))
            {
                action["actorKingdomId"] = speakerKingdomId;
                actorKingdomReference = speakerKingdomId;
            }
            if (string.IsNullOrWhiteSpace(targetKingdomReference) && !string.IsNullOrWhiteSpace(playerKingdomId))
            {
                action["targetKingdomId"] = playerKingdomId;
                targetKingdomReference = playerKingdomId;
            }

            string resolvedActorKingdomId = FirstNonEmpty(
                ResolveAlias(index, "kingdom", actorKingdomReference),
                ResolveKingdomIdLenient(index, actorKingdomReference));
            string resolvedTargetKingdomId = FirstNonEmpty(
                ResolveAlias(index, "kingdom", targetKingdomReference),
                ResolveKingdomIdLenient(index, targetKingdomReference));
            bool speakerIsCaptor = string.Equals(resolvedActorKingdomId, speakerKingdomId, StringComparison.OrdinalIgnoreCase)
                && string.Equals(resolvedTargetKingdomId, playerKingdomId, StringComparison.OrdinalIgnoreCase);
            bool playerIsCaptor = string.Equals(resolvedActorKingdomId, playerKingdomId, StringComparison.OrdinalIgnoreCase)
                && string.Equals(resolvedTargetKingdomId, speakerKingdomId, StringComparison.OrdinalIgnoreCase);

            if (speakerIsCaptor)
            {
                if (!string.IsNullOrWhiteSpace(speakerClanId)) action["actorClanId"] = speakerClanId;
                if (!string.IsNullOrWhiteSpace(playerClanId)) action["targetClanId"] = playerClanId;
                if (!string.IsNullOrWhiteSpace(speakerHeroId)) action["actorHeroId"] = speakerHeroId;
            }
            else if (playerIsCaptor)
            {
                if (!string.IsNullOrWhiteSpace(playerClanId)) action["actorClanId"] = playerClanId;
                if (!string.IsNullOrWhiteSpace(speakerClanId)) action["targetClanId"] = speakerClanId;
                if (!string.IsNullOrWhiteSpace(playerHeroId)) action["actorHeroId"] = playerHeroId;
            }

            string prisoner = FirstNonEmpty(
                ReadFirstString(action, "PrisonerHero", "prisonerHero", "prisonerHeroStringId"),
                ReadFirstString(terms, "PrisonerHero", "prisonerHero", "prisonerHeroStringId"),
                autonomousWorldDiplomacy ? "" : FindMentionedHeroName(payload, directive));
            if (!string.IsNullOrWhiteSpace(prisoner))
            {
                action["PrisonerHero"] = prisoner;
                if (!autonomousWorldDiplomacy)
                    action["TargetHero"] = prisoner;
                terms["prisonerHero"] = prisoner;
                terms["prisonerHeroStringId"] = prisoner;
            }

            int gold = ExtractMoneyAmount(directive, ReadInt(terms, "gold", ReadInt(action, "GoldAmount", 0)));
            if (gold > 0)
            {
                action["GoldAmount"] = gold;
                terms["gold"] = gold;
                terms["GoldAmount"] = gold;
            }

            string payerHeroId = playerIsCaptor ? speakerHeroId : playerHeroId;
            string payeeHeroId = playerIsCaptor ? playerHeroId : speakerHeroId;
            if (!string.IsNullOrWhiteSpace(payerHeroId)) terms["goldFromHeroStringId"] = payerHeroId;
            if (!string.IsNullOrWhiteSpace(payeeHeroId)) terms["goldToHeroStringId"] = payeeHeroId;
            AddIfMissing(terms, "packageText", LimitText(StripDirectiveMarkers(directive), 800));
        }

        private static void ApplyCompoundDiplomaticPackageTerms(Dictionary<string, object> action, Dictionary<string, object> terms, Dictionary<string, object> payload, Dictionary<string, object> hero, string directiveText)
        {
            if (action == null || terms == null)
            {
                return;
            }

            string directive = LatestPlayerDirectiveOrText(directiveText);
            string q = directive.ToLowerInvariant();
            string speakerHeroId = FirstNonEmpty(
                ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId"),
                ReadString(hero, "heroStringId", ""));
            string playerHeroId = ReadString(payload, "playerHeroStringId", "");
            string playerKingdomId = FirstNonEmpty(
                ReadFirstString(payload, "playerKingdomId", "actorKingdomId", "actorKingdomStringId"),
                ReadString(hero, "playerKingdomId", ""));
            string speakerKingdomId = FirstNonEmpty(
                ReadFirstString(payload, "speakerKingdomId", "targetKingdomId", "targetKingdomStringId"),
                ReadString(hero, "kingdomId", ""));

            bool playerPays = DirectiveHasAny(q, "i will pay you", "i pay you", "i give you", "i will give you", "from my stores", "from my party", "as dowry", "my clan")
                || LooksLikePlayerToSpeakerTransfer(q);
            string fromHeroId = playerPays ? playerHeroId : speakerHeroId;
            string toHeroId = playerPays ? speakerHeroId : playerHeroId;

            AddIfMissing(action, "actorKingdomId", playerKingdomId);
            AddIfMissing(action, "targetKingdomId", speakerKingdomId);
            AddIfMissing(terms, "fromHeroStringId", fromHeroId);
            AddIfMissing(terms, "toHeroStringId", toHeroId);

            int gold = ExtractMoneyAmount(directive, 0);
            if (gold > 0)
            {
                AddIfMissing(action, "GoldAmount", gold);
                AddIfMissing(terms, "gold", gold);
                AddIfMissing(terms, "GoldAmount", gold);
            }

            List<Dictionary<string, object>> itemTerms = BuildDirectiveItemTerms(directive, fromHeroId, toHeroId, payload);
            if (itemTerms.Count > 0)
            {
                terms["items"] = itemTerms;
                Dictionary<string, object> firstItem = itemTerms[0];
                AddIfMissing(action, "Item", ReadString(firstItem, "itemId", string.Empty));
                AddIfMissing(action, "Amount", ReadInt(firstItem, "amount", 1));
                AddIfMissing(terms, "item", ReadString(firstItem, "itemId", string.Empty));
                AddIfMissing(terms, "amount", ReadInt(firstItem, "amount", 1));
            }

            if (DirectiveHasAny(q, "marriage", "marry", "betroth", "dowry"))
            {
                AddIfMissing(terms, "treatyKind", "marriage_alliance_dowry");
                AddIfMissing(terms, "promiseText", "Marriage alliance backed by the material dowry in packageText.");
                ApplyMarriageDirectiveTerms(terms, payload, directive);
            }
            else if (DirectiveHasAny(q, "alliance"))
            {
                AddIfMissing(terms, "treatyKind", "alliance_resource_package");
            }
            else if (DirectiveHasAny(q, "non-aggression", "non aggression"))
            {
                AddIfMissing(terms, "treatyKind", "non_aggression_package");
            }

            AddIfMissing(terms, "packageText", LimitText(StripDirectiveMarkers(directive), 800));
        }

        private static void ApplyMarriageDirectiveTerms(Dictionary<string, object> terms, Dictionary<string, object> payload, string directiveText)
        {
            if (terms == null)
            {
                return;
            }

            string directive = LatestPlayerDirectiveOrText(directiveText);
            AddIfMissing(terms, "marriageRequestText", LimitText(StripDirectiveMarkers(directive), 800));
            AddIfMissing(terms, "packageText", LimitText(StripDirectiveMarkers(directive), 800));
            Dictionary<string, object> namedHero = FindMentionedMarriageHero(payload, directiveText);
            if (namedHero.Count > 0)
            {
                AddIfMissing(terms, "requestedMarriageHeroStringId", ReadString(namedHero, "heroStringId", string.Empty));
                AddIfMissing(terms, "requestedMarriageHero", ReadString(namedHero, "name", ReadString(namedHero, "heroStringId", string.Empty)));
            }
        }

        private static int ExtractNonMoneyAmount(string text, int fallback)
        {
            foreach (Match match in Regex.Matches(text ?? string.Empty, @"\b(\d[\d,]*)\s+([A-Za-z]+)\b", RegexOptions.IgnoreCase))
            {
                string unit = match.Groups[2].Value.ToLowerInvariant();
                if (DirectiveHasAny(unit, "denar", "denars", "gold", "coin", "coins", "silver", "money"))
                {
                    continue;
                }

                string cleaned = match.Groups[1].Value.Replace(",", "");
                if (int.TryParse(cleaned, out int value) && value > 0)
                {
                    return value;
                }
            }

            return fallback;
        }

        private static List<Dictionary<string, object>> BuildDirectiveItemTerms(string text, string fromHeroId, string toHeroId, Dictionary<string, object> payload)
        {
            List<Dictionary<string, object>> items = new List<Dictionary<string, object>>();
            AddInventoryMentionedItemTerms(items, text, fromHeroId, toHeroId, payload);
            if (items.Count > 0)
            {
                return items;
            }

            AddDirectiveItemTerm(items, text, "grain", "grain|food|supplies|supply", fromHeroId, toHeroId);
            AddDirectiveItemTerm(items, text, "horse", "horse|horses|mount|mounts", fromHeroId, toHeroId);
            AddDirectiveItemTerm(items, text, "tools", "tools?", fromHeroId, toHeroId);
            AddDirectiveItemTerm(items, text, "hardwood", "hardwood", fromHeroId, toHeroId);
            AddDirectiveItemTerm(items, text, "iron", "iron", fromHeroId, toHeroId);
            AddDirectiveItemTerm(items, text, "silver", "silver", fromHeroId, toHeroId);
            AddDirectiveItemTerm(items, text, "linen", "linen", fromHeroId, toHeroId);
            AddDirectiveItemTerm(items, text, "wool", "wool", fromHeroId, toHeroId);
            AddDirectiveItemTerm(items, text, "velvet", "velvet", fromHeroId, toHeroId);
            AddDirectiveItemTerm(items, text, "pottery", "pottery", fromHeroId, toHeroId);
            AddDirectiveItemTerm(items, text, "leather", "leather", fromHeroId, toHeroId);
            AddDirectiveItemTerm(items, text, "fur", "fur|furs", fromHeroId, toHeroId);
            return items;
        }

        private static void AddInventoryMentionedItemTerms(List<Dictionary<string, object>> items, string text, string fromHeroId, string toHeroId, Dictionary<string, object> payload)
        {
            if (items == null || string.IsNullOrWhiteSpace(text) || payload == null)
            {
                return;
            }

            Dictionary<string, object> index = ReadDictionary(payload, "actionResolutionIndex") ?? new Dictionary<string, object>();
            Dictionary<string, object> assets = ReadDictionary(index, "assets") ?? new Dictionary<string, object>();
            string playerHeroId = ReadFirstString(payload, "playerHeroStringId", "mainHeroStringId");
            string speakerHeroId = ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId");
            List<Dictionary<string, object>> inventories = new List<Dictionary<string, object>>();
            if (string.Equals(fromHeroId, playerHeroId, StringComparison.OrdinalIgnoreCase))
            {
                inventories.Add(ReadDictionary(ReadDictionary(assets, "player"), "inventory"));
            }
            else if (string.Equals(fromHeroId, speakerHeroId, StringComparison.OrdinalIgnoreCase))
            {
                inventories.Add(ReadDictionary(ReadDictionary(assets, "speaker"), "inventory"));
            }
            else
            {
                inventories.Add(ReadDictionary(ReadDictionary(assets, "player"), "inventory"));
                inventories.Add(ReadDictionary(ReadDictionary(assets, "speaker"), "inventory"));
            }

            foreach (Dictionary<string, object> inventory in inventories.Where(x => x != null))
            {
                foreach (Dictionary<string, object> candidate in ActionInventoryItems(inventory)
                    .OrderByDescending(x => ReadString(x, "name", string.Empty).Length))
                {
                    string itemId = ReadFirstString(candidate, "itemId", "item");
                    string name = ReadFirstString(candidate, "name", "itemId", "item");
                    int amount = ExtractInventoryItemAmount(text, name);
                    if (string.IsNullOrWhiteSpace(itemId) || amount <= 0 || items.Any(x => string.Equals(ReadString(x, "itemId", string.Empty), itemId, StringComparison.OrdinalIgnoreCase)))
                    {
                        continue;
                    }

                    Dictionary<string, object> item = new Dictionary<string, object>
                    {
                        ["itemId"] = itemId,
                        ["item"] = itemId,
                        ["amount"] = amount
                    };
                    if (!string.IsNullOrWhiteSpace(fromHeroId))
                    {
                        item["fromHeroStringId"] = fromHeroId;
                        item["itemFromHeroStringId"] = fromHeroId;
                    }

                    if (!string.IsNullOrWhiteSpace(toHeroId))
                    {
                        item["toHeroStringId"] = toHeroId;
                        item["itemToHeroStringId"] = toHeroId;
                    }

                    items.Add(item);
                }
            }
        }

        private static int ExtractInventoryItemAmount(string text, string itemName)
        {
            if (string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(itemName))
            {
                return 0;
            }

            Match match = Regex.Match(text, @"\b(\d[\d,]*)\s+" + Regex.Escape(itemName) + @"(?:s|es)?\b", RegexOptions.IgnoreCase);
            if (match.Success)
            {
                string cleaned = match.Groups[1].Value.Replace(",", string.Empty);
                if (int.TryParse(cleaned, NumberStyles.Integer, CultureInfo.InvariantCulture, out int numericAmount) && numericAmount > 0)
                {
                    return numericAmount;
                }
            }

            Match noun = Regex.Match(text, @"\b" + Regex.Escape(itemName) + @"(?:s|es)?\b", RegexOptions.IgnoreCase);
            return noun.Success ? ExtractEnglishNumberBefore(text, noun.Index) : 0;
        }

        private static void AddDirectiveItemTerm(List<Dictionary<string, object>> items, string text, string itemId, string nounPattern, string fromHeroId, string toHeroId)
        {
            if (items == null || string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(itemId) || string.IsNullOrWhiteSpace(nounPattern))
            {
                return;
            }

            int amount = ExtractItemAmount(text, nounPattern);
            if (amount <= 0)
            {
                return;
            }

            if (items.Any(x => string.Equals(ReadString(x, "itemId", string.Empty), itemId, StringComparison.OrdinalIgnoreCase)))
            {
                return;
            }

            Dictionary<string, object> item = new Dictionary<string, object>
            {
                ["itemId"] = itemId,
                ["item"] = itemId,
                ["amount"] = amount
            };
            if (!string.IsNullOrWhiteSpace(fromHeroId))
            {
                item["fromHeroStringId"] = fromHeroId;
                item["itemFromHeroStringId"] = fromHeroId;
            }

            if (!string.IsNullOrWhiteSpace(toHeroId))
            {
                item["toHeroStringId"] = toHeroId;
                item["itemToHeroStringId"] = toHeroId;
            }

            items.Add(item);
        }

        private static int ExtractItemAmount(string text, string nounPattern)
        {
            string q = text ?? string.Empty;
            foreach (Match match in Regex.Matches(q, @"\b(\d[\d,]*)\s+(?:" + nounPattern + @")\b", RegexOptions.IgnoreCase))
            {
                string cleaned = match.Groups[1].Value.Replace(",", "");
                if (int.TryParse(cleaned, NumberStyles.Integer, CultureInfo.InvariantCulture, out int value) && value > 0)
                {
                    return value;
                }
            }

            Match noun = Regex.Match(q, @"\b(?:" + nounPattern + @")\b", RegexOptions.IgnoreCase);
            if (noun.Success)
            {
                int spoken = ExtractEnglishNumberBefore(q, noun.Index);
                if (spoken > 0)
                {
                    return spoken;
                }
            }

            return 0;
        }

        private static int ExtractEnglishNumberBefore(string text, int endIndex)
        {
            if (string.IsNullOrWhiteSpace(text) || endIndex <= 0)
            {
                return 0;
            }

            string prefix = text.Substring(0, Math.Min(endIndex, text.Length));
            List<string> words = Regex.Matches(prefix, @"[A-Za-z]+")
                .Cast<Match>()
                .Select(match => match.Value)
                .ToList();
            int maxWords = Math.Min(7, words.Count);
            for (int count = maxWords; count >= 1; count--)
            {
                string candidate = string.Join(" ", words.Skip(words.Count - count));
                if (TryParseEnglishNumber(candidate, out int value) && value > 0)
                {
                    return value;
                }
            }

            return 0;
        }

        private static int ExtractFirstInteger(string text, int fallback)
        {
            Match match = Regex.Match(text ?? string.Empty, @"\b\d[\d,]*\b");
            if (!match.Success)
            {
                return fallback;
            }

            string cleaned = match.Value.Replace(",", "");
            return int.TryParse(cleaned, out int value) && value > 0 ? value : fallback;
        }

        private static string ExtractDirectiveItemName(string text)
        {
            string q = (text ?? string.Empty).ToLowerInvariant();
            if (q.Contains("grain")) return "grain";
            if (q.Contains("food") || q.Contains("supplies") || q.Contains("supply")) return "grain";
            if (q.Contains("tools")) return "tools";
            if (q.Contains("hardwood")) return "hardwood";
            if (q.Contains("iron")) return "iron";
            if (q.Contains("silver")) return "silver";
            if (q.Contains("linen")) return "linen";
            if (q.Contains("wool")) return "wool";
            if (q.Contains("velvet")) return "velvet";
            if (q.Contains("pottery")) return "pottery";
            if (q.Contains("leather")) return "leather";
            if (q.Contains("fur")) return "fur";
            if (q.Contains("jewelry") || q.Contains("jewellery")) return "jewelry";
            if (q.Contains("beer")) return "beer";
            if (q.Contains("wine")) return "wine";
            if (q.Contains("oil")) return "oil";
            if (q.Contains("dates")) return "dates";
            if (q.Contains("fish")) return "fish";
            if (q.Contains("meat")) return "meat";
            if (q.Contains("butter")) return "butter";
            if (q.Contains("cheese")) return "cheese";
            if (DirectiveHasAny(q, "armor", "armour")) return "armor";
            if (q.Contains("helmet")) return "helmet";
            if (q.Contains("boots")) return "boots";
            if (q.Contains("gloves")) return "gloves";
            if (q.Contains("cloak")) return "cloak";
            if (q.Contains("cape")) return "cape";
            if (q.Contains("shield")) return "shield";
            if (q.Contains("horse") || q.Contains("mount")) return "horse";
            if (q.Contains("sword")) return "sword";
            if (q.Contains("axe")) return "axe";
            if (q.Contains("spear")) return "spear";
            if (q.Contains("bow")) return "bow";
            if (q.Contains("weapon")) return "weapon";
            return "item";
        }

        private static void ApplyTransferDirectionDefaults(Dictionary<string, object> action, Dictionary<string, object> terms, Dictionary<string, object> payload, Dictionary<string, object> hero, string directiveText, string command)
        {
            if (action == null || terms == null)
            {
                return;
            }

            string speakerHeroId = FirstNonEmpty(
                ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId"),
                ReadString(hero, "heroStringId", ""),
                "speaker");
            string playerHeroId = FirstNonEmpty(ReadString(payload, "playerHeroStringId", ""), "player");
            string playerSegment = ExtractConversationSegment(directiveText, "player");
            string npcSegment = ExtractConversationSegment(directiveText, "npc");
            bool hasSpeakerSegments = !string.IsNullOrWhiteSpace(playerSegment) || !string.IsNullOrWhiteSpace(npcSegment);
            bool playerToSpeaker = hasSpeakerSegments
                ? LooksLikePlayerToSpeakerTransfer(playerSegment) || LooksLikeSpeakerToPlayerTransfer(npcSegment)
                : LooksLikePlayerToSpeakerTransfer(directiveText);
            bool speakerToPlayer = hasSpeakerSegments
                ? LooksLikeSpeakerToPlayerTransfer(playerSegment) || LooksLikePlayerToSpeakerTransfer(npcSegment)
                : LooksLikeSpeakerToPlayerTransfer(directiveText);
            if (playerToSpeaker && speakerToPlayer)
            {
                string q = (directiveText ?? string.Empty).ToLowerInvariant();
                speakerToPlayer = !DirectiveHasAny(q, "my ships", "my fleet", "my grain", "my goods", "my supplies", "they are yours", "give them to you", "take my");
                playerToSpeaker = !speakerToPlayer;
            }
            bool textGivesDirection = playerToSpeaker || speakerToPlayer;

            string fromHero = speakerHeroId;
            string toHero = playerHeroId;
            if (playerToSpeaker && !speakerToPlayer)
            {
                fromHero = playerHeroId;
                toHero = speakerHeroId;
            }

            if (string.Equals(command, "give_gold_to_player", StringComparison.OrdinalIgnoreCase))
            {
                fromHero = speakerHeroId;
                toHero = playerHeroId;
            }

            if (!string.Equals(command, "give_gold_to_player", StringComparison.OrdinalIgnoreCase))
            {
                string explicitFrom = FirstNonEmpty(ReadFirstString(action, "FromHero", "fromHero"), ReadFirstString(terms, "FromHero", "fromHero", "fromHeroStringId"));
                string explicitTo = FirstNonEmpty(ReadFirstString(action, "ToHero", "toHero"), ReadFirstString(terms, "ToHero", "toHero", "toHeroStringId"));
                if (!textGivesDirection && !string.IsNullOrWhiteSpace(explicitFrom))
                {
                    fromHero = explicitFrom;
                }
                else if (!textGivesDirection)
                {
                    fromHero = FirstNonEmpty(ReadFirstString(action, "actorHeroStringId", "actorHeroId"), ReadFirstString(terms, "actorHeroStringId", "actorHeroId"), fromHero);
                }

                if (!textGivesDirection && !string.IsNullOrWhiteSpace(explicitTo))
                {
                    toHero = explicitTo;
                }
                else if (!textGivesDirection)
                {
                    toHero = FirstNonEmpty(ReadFirstString(action, "targetHeroStringId", "targetHeroId", "TargetHero"), ReadFirstString(terms, "targetHeroStringId", "targetHeroId", "TargetHero"), toHero);
                }
            }

            action["actorHeroId"] = fromHero;
            action["FromHero"] = fromHero;
            action["ToHero"] = toHero;
            action["TargetHero"] = toHero;
            terms["fromHeroStringId"] = fromHero;
            terms["toHeroStringId"] = toHero;
            terms["targetHeroStringId"] = toHero;
        }

        private static void ApplyTemporaryPartyGuestActorBinding(
            Dictionary<string, object> action,
            Dictionary<string, object> terms,
            Dictionary<string, object> payload,
            Dictionary<string, object> hero,
            string command)
        {
            string canonical = CanonicalCommand(command);
            if (canonical != "accept_temporary_party_guest"
                && canonical != "renew_temporary_party_guest"
                && canonical != "end_temporary_party_guest"
                && canonical != "acknowledge_own_faction_combat_risk")
            {
                return;
            }

            string speakerHeroId = FirstNonEmpty(
                ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId"),
                ReadString(hero, "heroStringId", ""));
            if (string.IsNullOrWhiteSpace(speakerHeroId))
            {
                return;
            }

            // Temporary-guest lifecycle actions always operate on the consenting/current NPC.
            // The planner may describe the player's request with the player as actor, but the
            // native executor resolves the guest record from ActorHeroStringId.
            action["actorHeroStringId"] = speakerHeroId;
            action["actorHeroId"] = speakerHeroId;
            action["FromHero"] = speakerHeroId;
            terms["fromHeroStringId"] = speakerHeroId;
            BindTemporaryGuestActionTerms(canonical, terms, payload, hero);
        }

        private static string ExtractConversationSegment(string text, string label)
        {
            if (string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(label))
            {
                return string.Empty;
            }

            string wanted = label.Trim().TrimEnd(':').ToLowerInvariant() + ":";
            StringBuilder builder = new StringBuilder();
            foreach (string rawLine in (text ?? string.Empty).Split(new[] { "\r\n", "\n" }, StringSplitOptions.None))
            {
                string line = rawLine.Trim();
                int colon = line.IndexOf(':');
                if (colon <= 0)
                {
                    continue;
                }

                string prefix = line.Substring(0, colon + 1).ToLowerInvariant();
                if (prefix == wanted)
                {
                    builder.AppendLine(line.Substring(colon + 1).Trim());
                }
            }

            return builder.ToString().Trim();
        }

        private static string StripDirectiveMarkers(string text)
        {
            string value = (text ?? string.Empty).Trim();
            if (value.Length >= 2 && value.StartsWith("@", StringComparison.Ordinal) && value.EndsWith("@", StringComparison.Ordinal))
            {
                return value.Substring(1, value.Length - 2).Trim();
            }

            return value.Replace("@", "").Trim();
        }

        private static string LatestPlayerDirectiveOrText(string text)
        {
            string value = (text ?? string.Empty).Trim();
            if (string.IsNullOrWhiteSpace(value))
            {
                return string.Empty;
            }

            string latestPlayerLine = string.Empty;
            foreach (string rawLine in value.Replace("\r\n", "\n").Split('\n'))
            {
                string line = rawLine.Trim();
                if (line.StartsWith("player:", StringComparison.OrdinalIgnoreCase))
                {
                    latestPlayerLine = line.Substring("player:".Length).Trim();
                }
            }

            return string.IsNullOrWhiteSpace(latestPlayerLine) ? value : latestPlayerLine;
        }

        private static bool LooksLikeNamedSettlementTransferDirective(Dictionary<string, object> payload, string text)
        {
            if (string.IsNullOrWhiteSpace(text) || LooksLikeNavalAssetDirective(text))
            {
                return false;
            }

            if (DirectiveHasAny(text.ToLowerInvariant(), "full surrender", "capitulation", "all towns", "all castles"))
            {
                return false;
            }

            bool hasTransferVerb = DirectiveHasAny(text.ToLowerInvariant(), "give", "grant", "hand over", "transfer", "cede", "surrender", "yield", "turn over", "award");
            return hasTransferVerb && !string.IsNullOrWhiteSpace(FindMentionedSettlementName(payload, text, ""));
        }

        private static bool LooksLikeNamedPaidSettlementTradeDirective(Dictionary<string, object> payload, string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            string q = text.ToLowerInvariant();
            bool hasMoney = DirectiveHasAny(q, "gold", "denar", "denars", "coin", "coins", "money", "silver", "price");
            bool hasExchangeShape = DirectiveHasAny(q, " for ", "price", "trade", "sell", "sold", "buy", "purchase", "deal", "bargain", "in exchange", "pay", "payment");
            return hasMoney && hasExchangeShape && !string.IsNullOrWhiteSpace(FindMentionedSettlementName(payload, text, ""));
        }

        private static bool LooksLikeNamedHeroGoldTransferDirective(Dictionary<string, object> payload, string text)
        {
            if (string.IsNullOrWhiteSpace(text) || !LooksLikeGiveGoldDirective(text))
            {
                return false;
            }

            string q = text.ToLowerInvariant();
            if (LooksLikePaidAssetTradeDirective(q)
                || LooksLikeNamedPaidExchangeDirective(q)
                || DirectiveHasAny(q, "prisoner", "ransom", "captive", "hostage", " for ", "in exchange", "buy", "purchase", "sell", "sold", "price"))
            {
                return false;
            }

            return !string.IsNullOrWhiteSpace(FindMentionedHeroName(payload, text))
                || !string.IsNullOrWhiteSpace(FindMentionedRelatedHeroName(payload, text));
        }

        private static string FindMentionedRelatedHeroName(Dictionary<string, object> payload, string text)
        {
            Dictionary<string, object> hero = ReadDictionary(payload, "hero") ?? new Dictionary<string, object>();
            string normalizedText = NormalizeLookup(text);
            if (hero.Count == 0 || string.IsNullOrWhiteSpace(normalizedText))
            {
                return string.Empty;
            }

            var names = new List<string>();
            foreach (string key in new[] { "spouseName", "fatherName", "motherName", "sovereignName" })
            {
                string name = ReadString(hero, key, "").Trim();
                if (!string.IsNullOrWhiteSpace(name))
                {
                    names.Add(name);
                }
            }
            names.AddRange(ReadStringList(hero, "childrenNames"));

            string playerName = ReadString(hero, "mainHeroName", "");
            List<string> matches = names
                .Where(name => !string.IsNullOrWhiteSpace(name)
                    && !string.Equals(name, playerName, StringComparison.OrdinalIgnoreCase))
                .Where(name =>
                {
                    string normalizedName = NormalizeLookup(name);
                    return normalizedName.Length >= 3 && ContainsNormalizedPhrase(normalizedText, normalizedName);
                })
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderByDescending(name => NormalizeLookup(name).Length)
                .ToList();

            return matches.Count == 1 ? matches[0] : string.Empty;
        }

        private static bool LooksLikeNamedRaidDirective(Dictionary<string, object> payload, string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            string q = text.ToLowerInvariant();
            return q.Contains("raid") && !string.IsNullOrWhiteSpace(FindMentionedSettlementName(payload, text, ""));
        }

        private static string FindMentionedSettlementName(Dictionary<string, object> payload, string text, string targetKingdomId)
        {
            Dictionary<string, object> index = ReadDictionary(payload, "actionResolutionIndex") ?? new Dictionary<string, object>();
            string normalizedText = NormalizeLookup(text);
            if (index.Count == 0 || string.IsNullOrWhiteSpace(normalizedText))
            {
                return string.Empty;
            }

            List<Dictionary<string, object>> matches = ReadDictionaryList(index, "settlements")
                .Where(x => string.IsNullOrWhiteSpace(targetKingdomId) || string.Equals(ReadString(x, "kingdomId", ""), targetKingdomId, StringComparison.OrdinalIgnoreCase))
                .Where(x =>
                {
                    string name = NormalizeLookup(ReadString(x, "name", ""));
                    return name.Length >= 3 && ContainsNormalizedPhrase(normalizedText, name);
                })
                .OrderByDescending(x => NormalizeLookup(ReadString(x, "name", "")).Length)
                .ToList();

            return matches.Count == 1 ? ReadString(matches[0], "name", ReadString(matches[0], "settlementId", "")) : string.Empty;
        }

        private static string FindMentionedHeroName(Dictionary<string, object> payload, string text)
        {
            Dictionary<string, object> index = ReadDictionary(payload, "actionResolutionIndex") ?? new Dictionary<string, object>();
            string normalizedText = NormalizeLookup(text);
            if (index.Count == 0 || string.IsNullOrWhiteSpace(normalizedText))
            {
                return string.Empty;
            }

            string speakerHeroId = ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId");
            string playerHeroId = ReadString(payload, "playerHeroStringId", "");
            List<Dictionary<string, object>> matches = ReadDictionaryList(index, "heroes")
                .Where(x =>
                {
                    string heroId = ReadString(x, "heroStringId", "");
                    if (string.Equals(heroId, speakerHeroId, StringComparison.OrdinalIgnoreCase)
                        || string.Equals(heroId, playerHeroId, StringComparison.OrdinalIgnoreCase))
                    {
                        return false;
                    }

                    string name = NormalizeLookup(ReadString(x, "name", ""));
                    return name.Length >= 3 && ContainsNormalizedPhrase(normalizedText, name);
                })
                .OrderByDescending(x => NormalizeLookup(ReadString(x, "name", "")).Length)
                .ToList();

            return matches.Count == 1 ? ReadString(matches[0], "name", ReadString(matches[0], "heroStringId", "")) : string.Empty;
        }

        private static Dictionary<string, object> FindMentionedMarriageHero(Dictionary<string, object> payload, string text)
        {
            Dictionary<string, object> index = ReadDictionary(payload, "actionResolutionIndex") ?? new Dictionary<string, object>();
            string normalizedText = NormalizeLookup(text);
            if (index.Count == 0 || string.IsNullOrWhiteSpace(normalizedText))
            {
                return new Dictionary<string, object>();
            }

            List<Dictionary<string, object>> matches = ReadDictionaryList(index, "heroes")
                .Where(x =>
                {
                    string name = NormalizeLookup(ReadString(x, "name", ""));
                    return name.Length >= 3 && ContainsNormalizedPhrase(normalizedText, name);
                })
                .OrderByDescending(x => NormalizeLookup(ReadString(x, "name", "")).Length)
                .ToList();
            return matches.Count == 1 ? matches[0] : new Dictionary<string, object>();
        }

        private static bool ContainsNormalizedPhrase(string normalizedText, string normalizedPhrase)
        {
            if (string.IsNullOrWhiteSpace(normalizedText) || string.IsNullOrWhiteSpace(normalizedPhrase))
            {
                return false;
            }

            return (" " + normalizedText.Trim() + " ").IndexOf(
                " " + normalizedPhrase.Trim() + " ",
                StringComparison.Ordinal) >= 0;
        }

        private static string InferDuelModeFromDirective(string text)
        {
            string q = (text ?? string.Empty).ToLowerInvariant();
            if (q.Contains("lethal")
                || q.Contains("to the death")
                || q.Contains("death")
                || q.Contains("honor")
                || q.Contains("honour"))
            {
                return "lethal";
            }

            return "training";
        }

        private static bool IsLethalDuelMode(string mode)
        {
            string normalized = (mode ?? string.Empty).Trim().ToLowerInvariant().Replace('-', '_').Replace(' ', '_');
            return normalized == "lethal"
                || normalized == "death"
                || normalized == "to_the_death"
                || normalized == "honor"
                || normalized == "honour";
        }

        private static void AddIfMissing(Dictionary<string, object> target, string key, object value)
        {
            if (target == null || string.IsNullOrWhiteSpace(key) || value == null)
            {
                return;
            }

            if (target.TryGetValue(key, out object existing) && existing != null && !string.IsNullOrWhiteSpace(Convert.ToString(existing)))
            {
                return;
            }

            if (value is string text && string.IsNullOrWhiteSpace(text))
            {
                return;
            }

            target[key] = value;
        }

        private static string FindSettlementIdFromContextBundles(List<Dictionary<string, object>> bundles, string factionId, string mode)
        {
            foreach (Dictionary<string, object> bundle in bundles ?? new List<Dictionary<string, object>>())
            {
                string id = ReadString(bundle, "id", "");
                Dictionary<string, object> data = ReadDictionary(bundle, "data") ?? new Dictionary<string, object>();
                if (string.Equals(id, "current_settlement_facts", StringComparison.OrdinalIgnoreCase))
                {
                    Dictionary<string, object> settlement = ReadDictionary(data, "settlement") ?? new Dictionary<string, object>();
                    string settlementId = ReadString(settlement, "settlementId", "");
                    if (!string.IsNullOrWhiteSpace(settlementId))
                    {
                        return settlementId;
                    }
                }

                if (string.Equals(id, "nearby_settlements", StringComparison.OrdinalIgnoreCase))
                {
                    foreach (Dictionary<string, object> settlement in ReadDictionaryList(data, "items"))
                    {
                        string settlementId = ReadString(settlement, "settlementId", "");
                        string settlementFactionId = ReadString(settlement, "factionId", "");
                        if (!string.IsNullOrWhiteSpace(settlementId)
                            && (string.IsNullOrWhiteSpace(factionId) || string.Equals(settlementFactionId, factionId, StringComparison.OrdinalIgnoreCase)))
                        {
                            return settlementId;
                        }
                    }
                }
            }

            return string.Empty;
        }

        private static string FindThirdKingdomIdFromContextBundles(List<Dictionary<string, object>> bundles, string playerKingdomId, string speakerKingdomId)
        {
            foreach (Dictionary<string, object> bundle in bundles ?? new List<Dictionary<string, object>>())
            {
                if (!string.Equals(ReadString(bundle, "id", ""), "kingdom_diplomacy_status", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                Dictionary<string, object> data = ReadDictionary(bundle, "data") ?? new Dictionary<string, object>();
                foreach (string listKey in new[] { "playerWars", "speakerWars" })
                {
                    foreach (Dictionary<string, object> war in ReadDictionaryList(data, listKey))
                    {
                        string id = ReadString(war, "factionId", "");
                        if (!string.IsNullOrWhiteSpace(id)
                            && !string.Equals(id, playerKingdomId, StringComparison.OrdinalIgnoreCase)
                            && !string.Equals(id, speakerKingdomId, StringComparison.OrdinalIgnoreCase))
                        {
                            return id;
                        }
                    }
                }
            }

            return string.Empty;
        }

        private static IEnumerable<object> ObjectsFromValue(object value)
        {
            if (value == null)
            {
                return Enumerable.Empty<object>();
            }

            if (value is ArrayList array)
            {
                return array.Cast<object>();
            }

            if (value is IEnumerable<object> enumerable)
            {
                return enumerable;
            }

            return new[] { value };
        }

        private static Dictionary<string, object> ProposeAction(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", "default");
            string correlationId = EnsureCorrelationId(payload);
            SaveTestSnapshotFromPayload(campaignId, correlationId, "action", "action.propose", payload);
            List<Dictionary<string, object>> inputs = ReadDictionaryList(payload, "actions");
            Dictionary<string, object> singleAction = ReadDictionary(payload, "action");
            if (singleAction != null)
            {
                inputs.Add(singleAction);
            }

            if (inputs.Count == 0)
            {
                inputs.Add(payload);
            }

            List<Dictionary<string, object>> queued = new List<Dictionary<string, object>>();
            List<string> errors = new List<string>();
            foreach (Dictionary<string, object> input in inputs)
            {
                if (!input.ContainsKey("correlationId"))
                {
                    input["correlationId"] = correlationId;
                }

                Dictionary<string, object> normalized = NormalizeActionCommand(input, campaignId, out List<string> actionErrors, payload);
                if (actionErrors.Count > 0)
                {
                    errors.AddRange(actionErrors);
                    continue;
                }

                queued.Add(QueueAction(campaignId, normalized));
            }

            if (errors.Count > 0)
            {
                LogOperational("action.reject", new Dictionary<string, object> { ["campaignId"] = campaignId, ["correlationId"] = correlationId, ["errors"] = errors });
                WriteAudit(campaignId, correlationId, "server", "action", "action.validation_failed", "", "", "", "failed", 0, "Action proposal failed validation.", new Dictionary<string, object>
                {
                    ["inputs"] = inputs,
                    ["errors"] = errors
                });
                return new Dictionary<string, object>
                {
                    ["ok"] = false,
                    ["errors"] = errors,
                    ["catalog"] = ActionCatalog()
                };
            }

            LogOperational("action.propose", new Dictionary<string, object>
            {
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["count"] = queued.Count
            });
            WriteAudit(campaignId, correlationId, "server", "action", "action.proposed", "", "", "", "queued", 0, "Action proposal queued.", new Dictionary<string, object>
            {
                ["queued"] = queued,
                ["count"] = queued.Count
            });

            return new Dictionary<string, object>
            {
                ["ok"] = true,
                ["correlationId"] = correlationId,
                ["queuedActions"] = queued,
                ["count"] = queued.Count
            };
        }

        private static Dictionary<string, object> DecideActions(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", "default");
            Dictionary<string, object> context = BuildContext(payload);
            object memories = context.ContainsKey("memories") ? context["memories"] : new List<object>();
            object worldState = payload.ContainsKey("worldState") ? payload["worldState"] : payload;
            string requestType = ReadString(payload, "requestType", "strategy");

            Dictionary<string, object> catalog = ActionCatalog();
            List<Dictionary<string, object>> messages = new List<Dictionary<string, object>>
            {
                new Dictionary<string, object>
                {
                    ["role"] = "system",
                    ["content"] = "You are Bannerlord Reign, a Bannerlord AI world director. Return strict JSON only. Use only the supplied action catalog. Prefer believable character and kingdom motives. Never invent IDs; use only IDs present in the world state."
                },
                new Dictionary<string, object>
                {
                    ["role"] = "user",
                    ["content"] = "Action catalog:\n" + Json.Serialize(catalog["commands"]) + "\n\nRelevant memories:\n" + Json.Serialize(memories) + "\n\nWorld state/request:\n" + Json.Serialize(worldState) + "\n\nReturn JSON like {\"actions\":[{\"command\":\"capture_settlement_plan\",\"actorHeroId\":\"...\",\"targetSettlementId\":\"...\",\"reason\":\"...\"}]}"
                }
            };

            Dictionary<string, object> llmPayload = new Dictionary<string, object>
            {
                ["requestType"] = requestType,
                ["messages"] = messages,
                ["response_format"] = new Dictionary<string, object> { ["type"] = "json_object" }
            };

            Dictionary<string, object> llm = ChatWithLlm(llmPayload);
            if (!ReadBool(llm, "ok", false))
            {
                return new Dictionary<string, object> { ["ok"] = false, ["stage"] = "llm", ["llm"] = llm };
            }

            string content = ReadString(llm, "content", "");
            Dictionary<string, object> parsed = TryParseJsonObject(content);
            if (parsed == null)
            {
                return new Dictionary<string, object> { ["ok"] = false, ["stage"] = "parse", ["content"] = content };
            }

            Dictionary<string, object> proposePayload = new Dictionary<string, object>
            {
                ["campaignId"] = campaignId,
                ["actions"] = ReadDictionaryList(parsed, "actions")
            };

            Dictionary<string, object> proposed = ProposeAction(proposePayload);
            proposed["llm"] = new Dictionary<string, object>
            {
                ["requestType"] = requestType,
                ["model"] = ReadString(llm, "model", ""),
                ["content"] = content
            };
            return proposed;
        }

        private static Dictionary<string, object> RetryMalformedStructuredResponse(
            Dictionary<string, object> llm,
            Dictionary<string, object> request,
            string campaignId,
            string correlationId,
            string auditMode,
            string heroId,
            string eventId)
        {
            if (!ReadBool(llm, "ok", false))
                return llm;
            string initialContent = ReadString(llm, "content", "");
            bool initialAccepted = StructuredResponseIsComplete(initialContent, auditMode)
                && ConversationVisibleReplyPassesRequestQualityGate(
                    initialContent, request, auditMode);
            DiagnosticValidation("Check answer structure", initialAccepted,
                DiagnosticStructuredIssues(initialContent, auditMode, request), initialContent);
            if (initialAccepted)
                return llm;

            string normalizedMode = NormalizeLookup(auditMode).Replace(' ', '_');
            Dictionary<string, object> initiallyParsed = TryParseJsonObject(initialContent);
            if (IsConversationStructuredMode(normalizedMode)
                && TryRepairShiftedConversationReplyKeys(initiallyParsed, out Dictionary<string, object> repairedReplyObject)
                && ConversationVisibleReplyPassesRequestQualityGate(
                    Json.Serialize(repairedReplyObject), request, auditMode))
            {
                List<string> repairedFields;
                Dictionary<string, object> completed = CompleteConversationStructuredResponse(
                    repairedReplyObject, normalizedMode, out repairedFields);
                llm["content"] = Json.Serialize(completed);
                llm["deterministicSchemaCompletion"] = new Dictionary<string, object>
                {
                    ["completed"] = true,
                    ["fields"] = repairedFields,
                    ["repairedShiftedReplyKeys"] = true,
                    ["reason"] = "The provider shifted the reply key and value into two whitespace-named JSON properties; the unambiguous visible reply was restored without resending the prompt."
                };
                WriteAudit(campaignId, correlationId, "server", auditMode, "llm.schema_completion", heroId, "", eventId,
                    "completed", 0, "A provider-corrupted reply key was repaired deterministically without resending the full prompt.",
                    ReadDictionary(llm, "deterministicSchemaCompletion"));
                return llm;
            }
            if (IsConversationStructuredMode(normalizedMode)
                && initiallyParsed != null
                && ConversationStructuredObjectHasUsableVisibleReply(initiallyParsed)
                && ConversationVisibleReplyPassesRequestQualityGate(
                    initialContent, request, auditMode))
            {
                List<string> completedFields;
                Dictionary<string, object> completed = CompleteConversationStructuredResponse(initiallyParsed, normalizedMode, out completedFields);
                llm["content"] = Json.Serialize(completed);
                llm["deterministicSchemaCompletion"] = new Dictionary<string, object>
                {
                    ["completed"] = true,
                    ["fields"] = completedFields,
                    ["reason"] = "The provider returned a usable visible reply but omitted private structured metadata; conservative defaults were supplied without another provider call."
                };
                WriteAudit(campaignId, correlationId, "server", auditMode, "llm.schema_completion", heroId, "", eventId,
                    "completed", 0, "Incomplete private response metadata was completed deterministically without resending the prompt.",
                    ReadDictionary(llm, "deterministicSchemaCompletion"));
                return llm;
            }

            if (IsConversationStructuredMode(normalizedMode)
                && initiallyParsed == null
                && TryExtractClosedJsonStringField(ReadString(llm, "content", ""), "reply", out string recoveredReply)
                && !string.IsNullOrWhiteSpace(recoveredReply)
                && ConversationVisibleReplyPassesRequestQualityGate(
                    Json.Serialize(new Dictionary<string, object>
                    {
                        ["reply"] = recoveredReply
                    }), request, auditMode))
            {
                Dictionary<string, object> recovered = new Dictionary<string, object> { ["reply"] = recoveredReply };
                List<string> recoveredFields;
                recovered = CompleteConversationStructuredResponse(recovered, normalizedMode, out recoveredFields);
                llm["content"] = Json.Serialize(recovered);
                llm["deterministicSchemaCompletion"] = new Dictionary<string, object>
                {
                    ["completed"] = true,
                    ["fields"] = recoveredFields,
                    ["recoveredClosedReply"] = true,
                    ["reason"] = "The provider exhausted its completion allowance after closing the visible reply; incomplete private metadata was conservatively completed without resending the full prompt."
                };
                WriteAudit(campaignId, correlationId, "server", auditMode, "llm.schema_completion", heroId, "", eventId,
                    "completed", 0, "A closed visible reply was recovered from truncated JSON without resending the full prompt.",
                    ReadDictionary(llm, "deterministicSchemaCompletion"));
                return llm;
            }

            List<Dictionary<string, object>> attempts = new List<Dictionary<string, object>>();
            Dictionary<string, object> diagnostics = new Dictionary<string, object>
            {
                ["attempted"] = true,
                ["initialContentChars"] = ReadString(llm, "content", "").Length,
                ["attempts"] = attempts
            };
            for (int attempt = 1; attempt <= 2; attempt++)
            {
                Dictionary<string, object> retryRequest = CloneDictionary(request ?? new Dictionary<string, object>());
                List<Dictionary<string, object>> retryMessages = ReadDictionaryList(request, "messages")
                    .Select(CloneDictionary)
                    .ToList();
                if (retryMessages.Count == 0)
                {
                    retryMessages.Add(new Dictionary<string, object>
                    {
                        ["role"] = "system",
                        ["content"] = ReadString(request, "system", "You are Bannerlord Reign. Return strict JSON only.")
                    });
                    retryMessages.Add(new Dictionary<string, object>
                    {
                        ["role"] = "user",
                        ["content"] = ReadString(request, "prompt", ReadString(request, "text", ""))
                    });
                }
                bool correspondenceMode = normalizedMode.Contains("correspondence");
                string structuredFieldGuidance = correspondenceMode
                    ? " Include every required correspondence field: shouldReply, body, reason, actionGate, rebellionDecision, and campaignOrder. The body must contain the complete in-character written reply when shouldReply is true."
                    : " Include every required field, including reply and actionGate when this is dialogue. The reply field must contain a complete in-character reaction; never return only a quoted fragment copied from the latest player message, and never put a participation enum such as speak, agree, disagree, or quiet in reply.";
                // The original messages already include the character context. When the
                // provider returned no usable answer, repeating the context can push a
                // near-capacity prompt over the safety ceiling before either retry runs.
                bool repeatCharacterContext = FormatRetryNeedsCharacterContext(initialContent);
                retryMessages.Add(new Dictionary<string, object>
                {
                    ["role"] = "system",
                    ["content"] = "FORMAT REPAIR ATTEMPT " + attempt.ToString(CultureInfo.InvariantCulture) + ": Correct the rejected response below instead of inventing a replacement. Preserve every usable part of its in-character answer, personality, tone, decisions, and structured effects. Use the original character and scene instructions already supplied above to correct only malformed, missing, or explicitly invalid fields. Return exactly one complete valid JSON object matching the required response schema. Do not return an empty object. Do not use Markdown or code fences." + structuredFieldGuidance
                        + "\n\nREJECTED ORIGINAL RESPONSE TO CORRECT:\n"
                        + LimitText(initialContent, 16000)
                        + (repeatCharacterContext
                            ? "\n\nCOMPACT CHARACTER AND MOTIVE CONTEXT:\n"
                                + Json.Serialize(DialogueValidationRepairCharacterContext(request))
                            : "")
                });
                retryRequest["messages"] = retryMessages;
                retryRequest["promptCacheEligible"] = false;
                retryRequest["reasoningDisabled"] = true;
                retryRequest["temperature"] = attempt == 1 ? 0.05d : 0d;
                retryRequest["maxTokens"] = Math.Max(2200, ReadInt(retryRequest, "maxTokens", 2200));
                Dictionary<string, object> retry = ChatWithLlm(retryRequest);
                bool retryStructurallyUsable = ReadBool(retry, "ok", false)
                    && StructuredResponseIsComplete(
                        ReadString(retry, "content", ""), auditMode);
                bool retryPassedQualityGate = retryStructurallyUsable
                    && ConversationVisibleReplyPassesRequestQualityGate(
                        ReadString(retry, "content", ""), request, auditMode);
                DiagnosticValidation("Recheck repaired answer", retryPassedQualityGate,
                    DiagnosticStructuredIssues(ReadString(retry, "content", ""), auditMode, request), ReadString(retry, "content", ""));
                Dictionary<string, object> retryObject = retryStructurallyUsable
                    ? TryParseJsonObject(ReadString(retry, "content", ""))
                    : null;
                if (retryStructurallyUsable && retryObject != null)
                {
                    MarkRepairedVisibleResponse(
                        retryObject, retryPassedQualityGate);
                    retry["content"] = Json.Serialize(retryObject);
                }
                Dictionary<string, object> attemptDiagnostics = new Dictionary<string, object>
                {
                    ["attempt"] = attempt,
                    ["retryOk"] = ReadBool(retry, "ok", false),
                    ["retryParsed"] = retryStructurallyUsable,
                    ["revalidationCleared"] = retryPassedQualityGate,
                    ["secondAttemptReturned"] = retryStructurallyUsable,
                    ["visibleRepairMarker"] = retryStructurallyUsable
                        ? (retryPassedQualityGate ? ".." : ".,")
                        : "",
                    ["retryContentChars"] = ReadString(retry, "content", "").Length,
                    ["retryError"] = ReadString(retry, "error", ""),
                    ["originalResponseProvided"] = true,
                    ["characterContextProvided"] = repeatCharacterContext
                };
                attempts.Add(attemptDiagnostics);
                WriteAudit(campaignId, correlationId, "server", auditMode, "llm.format_retry", heroId, "", eventId,
                    !retryStructurallyUsable ? "failed"
                        : retryPassedQualityGate ? "completed"
                        : "completed_with_revalidation_override",
                    ReadLong(retry, "durationMs", 0),
                    !retryStructurallyUsable
                        ? "Structured LLM format retry did not produce a complete JSON response."
                        : retryPassedQualityGate
                            ? "Incomplete structured LLM output was repaired by an uncached retry."
                            : "The structurally complete format repair remained quality-gate rejected but was returned without a canned fallback.",
                    attemptDiagnostics);
                if (retryStructurallyUsable)
                {
                    diagnostics["completedAttempt"] = attempt;
                    retry["formatRetry"] = diagnostics;
                    return retry;
                }
            }

            llm["formatRetry"] = diagnostics;
            llm["ok"] = false;
            llm["errorCode"] = "structured_response_incomplete_after_retries";
            llm["error"] = "The provider did not return a complete dialogue response after two bounded format-repair attempts. No transcript or memory was written from the partial output.";
            return llm;
        }

        private static bool FormatRetryNeedsCharacterContext(string rejectedContent)
        {
            string trimmed = (rejectedContent ?? "").Trim();
            return trimmed.Length > 2 && !string.Equals(trimmed, "null", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsConversationStructuredMode(string normalizedMode)
        {
            return normalizedMode == "dialogue"
                || normalizedMode.Contains("social_event")
                || normalizedMode.Contains("party_chat")
                || normalizedMode.Contains("castle_chat");
        }

        private static bool ConversationVisibleReplyPassesRequestQualityGate(
            string content,
            Dictionary<string, object> request,
            string auditMode)
        {
            string normalizedMode = NormalizeLookup(auditMode).Replace(' ', '_');
            if (!IsConversationStructuredMode(normalizedMode)) return true;
            Dictionary<string, object> parsed = TryParseJsonObject(content);
            if (parsed == null) return false;
            bool eventMode = normalizedMode.Contains("social_event")
                || normalizedMode.Contains("party_chat")
                || normalizedMode.Contains("castle_chat");
            string visibleReply = ReadFirstString(
                parsed, "reply", "response", "text", "content");
            if (eventMode
                && NormalizeSocialEventParticipation(parsed) == "quiet"
                && string.IsNullOrWhiteSpace(visibleReply))
                return true;
            if (!ConversationStructuredObjectHasUsableVisibleReply(parsed))
                return false;
            return !IsBareQuotedLatestPlayerEcho(
                visibleReply,
                ReadString(request, "playerText", ""));
        }

        private static bool IsBareQuotedLatestPlayerEcho(
            string visibleReply,
            string latestPlayerText)
        {
            string trimmed = (visibleReply ?? "").Trim();
            if (trimmed.Length < 3 || trimmed.Length > 240
                || string.IsNullOrWhiteSpace(latestPlayerText))
                return false;
            char first = trimmed[0];
            char last = trimmed[trimmed.Length - 1];
            bool quotePair = (first == '\'' && last == '\'')
                || (first == '"' && last == '"')
                || (first == '\u2018' && last == '\u2019')
                || (first == '\u201C' && last == '\u201D');
            if (!quotePair) return false;
            string inner = NormalizeConversationEchoText(
                trimmed.Substring(1, trimmed.Length - 2));
            if (string.IsNullOrWhiteSpace(inner)
                || inner.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries).Length > 24)
                return false;
            string prompt = NormalizeConversationEchoText(latestPlayerText);
            return (" " + prompt + " ").Contains(" " + inner + " ");
        }

        private static string NormalizeConversationEchoText(string value)
        {
            string withoutApostrophes = Regex.Replace(
                (value ?? "").Normalize(NormalizationForm.FormKC),
                @"['\u2018\u2019]",
                "");
            return Regex.Replace(
                    withoutApostrophes,
                    @"[^\p{L}\p{N}]+",
                    " ")
                .Trim()
                .ToLowerInvariant();
        }

        private static bool ConversationStructuredObjectHasUsableVisibleReply(
            Dictionary<string, object> parsed)
        {
            if (parsed == null || parsed.Count == 0) return false;
            string visibleReply = ReadFirstString(
                parsed, "reply", "response", "content");
            if (!string.IsNullOrWhiteSpace(visibleReply))
                return !IsConversationParticipationControlToken(visibleReply);
            string text = ReadString(parsed, "text", "");
            if (string.IsNullOrWhiteSpace(text)) return false;
            if (IsConversationParticipationControlToken(text)) return false;
            bool carriesConversationShape = parsed.ContainsKey("emotion")
                || parsed.ContainsKey("intent")
                || parsed.ContainsKey("relationshipSignal")
                || parsed.ContainsKey("relationship_signal")
                || parsed.ContainsKey("relationshipAssessments")
                || parsed.ContainsKey("relationship_assessments")
                || ReadDictionary(parsed, "actionGate") != null
                || ReadDictionary(parsed, "action_gate") != null
                || ReadDictionary(parsed, "decisionBrief") != null
                || ReadDictionary(parsed, "decision_brief") != null
                || parsed.ContainsKey("participation");
            bool looksLikeNestedMemoryWrite = (parsed.ContainsKey("importance") || parsed.ContainsKey("tags"))
                && !carriesConversationShape;
            return !looksLikeNestedMemoryWrite;
        }

        private static bool IsConversationParticipationControlToken(
            string value)
        {
            string normalized = NormalizeLookup(value).Replace(' ', '_');
            return normalized == "speak"
                || normalized == "agree"
                || normalized == "disagree"
                || normalized == "quiet";
        }

        private static bool TryRepairShiftedConversationReplyKeys(
            Dictionary<string, object> parsed,
            out Dictionary<string, object> repaired)
        {
            repaired = null;
            if (parsed == null || parsed.Count < 3 || ConversationStructuredObjectHasUsableVisibleReply(parsed))
                return false;

            string markerKey = null;
            string contentKey = null;
            string visibleReply = "";
            foreach (KeyValuePair<string, object> pair in parsed)
            {
                if (!string.IsNullOrWhiteSpace(pair.Key) || !(pair.Value is string value))
                    continue;
                if (value.Trim().Equals("reply", StringComparison.OrdinalIgnoreCase))
                {
                    if (markerKey != null) return false;
                    markerKey = pair.Key;
                }
                else if (!string.IsNullOrWhiteSpace(value))
                {
                    if (contentKey != null) return false;
                    contentKey = pair.Key;
                    visibleReply = value;
                }
            }

            bool carriesConversationShape = ReadDictionary(parsed, "actionGate") != null
                || ReadDictionary(parsed, "action_gate") != null
                || ReadDictionary(parsed, "decisionBrief") != null
                || ReadDictionary(parsed, "decision_brief") != null
                || parsed.ContainsKey("relationshipAssessments")
                || parsed.ContainsKey("relationship_assessments");
            if (markerKey == null || contentKey == null || string.IsNullOrWhiteSpace(visibleReply)
                || !carriesConversationShape)
                return false;

            repaired = new Dictionary<string, object>(parsed, StringComparer.OrdinalIgnoreCase);
            repaired.Remove(markerKey);
            repaired.Remove(contentKey);
            repaired["reply"] = visibleReply;
            return true;
        }

        private static Dictionary<string, object> CompleteConversationStructuredResponse(
            Dictionary<string, object> parsed, string normalizedMode, out List<string> completedFields)
        {
            Dictionary<string, object> completed = new Dictionary<string, object>(parsed ?? new Dictionary<string, object>(), StringComparer.OrdinalIgnoreCase);
            List<string> fields = new List<string>();
            Action<string, object> add = (key, value) =>
            {
                if (completed.ContainsKey(key)) return;
                completed[key] = value;
                fields.Add(key);
            };
            Action<string, string[]> normalizeObjectArray = (canonicalKey, aliases) =>
            {
                List<string> keys = new[] { canonicalKey }.Concat(aliases ?? new string[0])
                    .Distinct(StringComparer.OrdinalIgnoreCase).ToList();
                bool found = false;
                bool malformed = false;
                List<Dictionary<string, object>> valid = new List<Dictionary<string, object>>();
                foreach (string key in keys)
                {
                    if (!completed.TryGetValue(key, out object raw))
                        continue;
                    found = true;
                    if (!StructuredCollectionIsDictionaryArray(raw))
                        malformed = true;
                    valid.AddRange(ObjectsFromValue(raw).OfType<Dictionary<string, object>>());
                    if (!key.Equals(canonicalKey, StringComparison.OrdinalIgnoreCase))
                        completed.Remove(key);
                }
                if (!found || malformed || !completed.ContainsKey(canonicalKey))
                {
                    completed[canonicalKey] = valid;
                    if (!fields.Contains(canonicalKey, StringComparer.OrdinalIgnoreCase))
                        fields.Add(canonicalKey);
                }
            };

            if (normalizedMode.Contains("social_event")
                || normalizedMode.Contains("party_chat")
                || normalizedMode.Contains("castle_chat"))
            {
                add("participation", "speak");
                add("reactionTargetHeroStringId", "");
            }
            add("emotion", "guarded");
            add("intent", "respond_in_character");
            add("relationshipSignal", "unchanged");
            normalizeObjectArray("relationshipAssessments", new[] { "relationship_assessments" });
            Dictionary<string, object> decisionBrief = ReadDictionary(completed, "decisionBrief")
                ?? ReadDictionary(completed, "decision_brief");
            if (decisionBrief == null)
            {
                decisionBrief = new Dictionary<string, object>();
                fields.Add("decisionBrief");
            }
            else
            {
                decisionBrief = new Dictionary<string, object>(decisionBrief, StringComparer.OrdinalIgnoreCase);
            }
            foreach (string listField in new[] { "facts", "goals", "constraints", "activeDomains", "appliedEvidenceKeys" })
            {
                if (!decisionBrief.TryGetValue(listField, out object rawList)
                    || !StructuredCollectionIsStringArray(rawList))
                {
                    decisionBrief[listField] = ObjectsFromValue(rawList)
                        .OfType<string>()
                        .Where(x => !string.IsNullOrWhiteSpace(x))
                        .ToList();
                    if (!fields.Contains("decisionBrief." + listField, StringComparer.OrdinalIgnoreCase))
                        fields.Add("decisionBrief." + listField);
                }
            }
            if (string.IsNullOrWhiteSpace(ReadString(decisionBrief, "decision", "")))
                decisionBrief["decision"] = "Respond in character without claiming an unsupported mechanical action.";
            if (!decisionBrief.ContainsKey("confidence"))
                decisionBrief["confidence"] = 0.25d;
            completed.Remove("decision_brief");
            completed["decisionBrief"] = decisionBrief;
            add("actionGate", new Dictionary<string, object>
            {
                ["needed"] = false, ["commitment"] = "roleplay_only", ["intent"] = "", ["confidence"] = 0.5d,
                ["reason"] = "The provider omitted the private action gate, so no native action may be inferred from the visible reply."
            });
            foreach (string arrayField in new[]
            {
                "memoryWrites", "beliefWrites", "relationshipUpdates",
                "obligationWrites", "comprehensionWrites", "dynamicCharacteristicWrites",
                "suggestedActions"
            })
            {
                string snake = Regex.Replace(arrayField, "([a-z0-9])([A-Z])", "$1_$2").ToLowerInvariant();
                normalizeObjectArray(arrayField, new[] { snake });
            }
            Dictionary<string, object> stateUpdates = ReadDictionary(completed, "stateUpdates")
                ?? ReadDictionary(completed, "state_updates");
            if (stateUpdates == null)
            {
                completed["stateUpdates"] = new Dictionary<string, object>();
                if (!fields.Contains("stateUpdates", StringComparer.OrdinalIgnoreCase))
                    fields.Add("stateUpdates");
            }
            completed.Remove("state_updates");
            completedFields = fields;
            return completed;
        }

        private static bool StructuredCollectionIsDictionaryArray(object value)
        {
            if (value is ArrayList array)
                return array.Cast<object>().All(item => item is Dictionary<string, object>);
            if (value is IEnumerable<object> enumerable)
                return enumerable.All(item => item is Dictionary<string, object>);
            return false;
        }

        private static bool StructuredCollectionIsStringArray(object value)
        {
            if (value is ArrayList array)
                return array.Cast<object>().All(item => item is string);
            if (value is IEnumerable<object> enumerable)
                return enumerable.All(item => item is string);
            return false;
        }

        private static bool StructuredObjectArrayFieldsAreValid(
            Dictionary<string, object> parsed,
            bool required,
            params string[] keys)
        {
            bool found = false;
            foreach (string key in keys ?? new string[0])
            {
                if (parsed == null || !parsed.TryGetValue(key, out object value))
                    continue;
                found = true;
                if (!StructuredCollectionIsDictionaryArray(value))
                    return false;
            }
            return found || !required;
        }

        private static bool ConversationStructuredCollectionsAreValid(
            Dictionary<string, object> parsed)
        {
            if (!StructuredObjectArrayFieldsAreValid(parsed, true,
                    "relationshipAssessments", "relationship_assessments"))
                return false;
            foreach (string[] keys in new[]
            {
                new[] { "memoryWrites", "memory_writes" },
                new[] { "beliefWrites", "belief_writes" },
                new[] { "relationshipUpdates", "relationship_updates" },
                new[] { "obligationWrites", "obligation_writes" },
                new[] { "comprehensionWrites", "comprehension_writes" },
                new[] { "continuityWrites" },
                new[] { "dynamicCharacteristicWrites", "dynamic_characteristic_writes" },
                new[] { "suggestedActions", "suggested_actions" }
            })
            {
                if (!StructuredObjectArrayFieldsAreValid(parsed, false, keys))
                    return false;
            }
            Dictionary<string, object> brief = ReadDictionary(parsed, "decisionBrief")
                ?? ReadDictionary(parsed, "decision_brief");
            if (brief == null)
                return false;
            foreach (string key in new[] { "facts", "goals", "constraints", "activeDomains", "appliedEvidenceKeys" })
            {
                if (brief.TryGetValue(key, out object value)
                    && !StructuredCollectionIsStringArray(value))
                    return false;
            }
            return true;
        }

        private static bool StructuredResponseIsComplete(string content, string auditMode)
        {
            Dictionary<string, object> parsed = TryParseJsonObject(content);
            if (parsed == null || parsed.Count == 0)
            {
                return false;
            }

            string mode = NormalizeLookup(auditMode).Replace(' ', '_');
            if (mode == "action_planner")
            {
                return parsed.ContainsKey("actions");
            }
            if (mode == "context_selector")
            {
                return parsed.ContainsKey("selectedPulls") || parsed.ContainsKey("pulls");
            }
            if (mode == "generated_wilderness_event")
            {
                return !string.IsNullOrWhiteSpace(ReadFirstString(parsed, "openingText", "opening_text", "event_opening_text", "opening"));
            }
            if (mode == "diplomacy_decision")
            {
                string decision = NormalizeLookup(ReadString(parsed, "decision", ""));
                return decision == "none" || decision == "unilateral" || decision == "proposal";
            }
            if (mode == "diplomacy_response")
            {
                string response = NormalizeLookup(ReadString(parsed, "response", ""));
                return response == "accept" || response == "refuse" || response == "counter";
            }
            if (mode == "dialogue"
                || mode.Contains("social_event")
                || mode.Contains("party_chat")
                || mode.Contains("castle_chat"))
            {
                bool eventMode = mode.Contains("social_event")
                    || mode.Contains("party_chat")
                    || mode.Contains("castle_chat");
                string eventParticipation = eventMode
                    ? NormalizeSocialEventParticipation(parsed)
                    : "speak";
                bool visibleReplyComplete = eventMode
                    && eventParticipation == "quiet"
                    ? string.IsNullOrWhiteSpace(ReadFirstString(
                        parsed, "reply", "response", "text", "content"))
                    : ConversationStructuredObjectHasUsableVisibleReply(parsed);
                return visibleReplyComplete
                    && (ReadDictionary(parsed, "actionGate") != null || ReadDictionary(parsed, "action_gate") != null)
                    && parsed.ContainsKey("emotion") && parsed.ContainsKey("intent")
                    && (parsed.ContainsKey("relationshipSignal") || parsed.ContainsKey("relationship_signal"))
                    && (parsed.ContainsKey("relationshipAssessments") || parsed.ContainsKey("relationship_assessments"))
                    && (ReadDictionary(parsed, "decisionBrief") != null || ReadDictionary(parsed, "decision_brief") != null)
                    && ConversationStructuredCollectionsAreValid(parsed)
                    && (!eventMode || parsed.ContainsKey("participation"));
            }
            if (mode.Contains("correspondence"))
            {
                if (!parsed.ContainsKey("shouldReply")) return false;
                bool shouldReply = ReadBool(parsed, "shouldReply", false);
                return (!shouldReply || !string.IsNullOrWhiteSpace(ReadFirstString(parsed, "body", "letter", "reply", "response")))
                    && (ReadDictionary(parsed, "actionGate") != null || ReadDictionary(parsed, "action_gate") != null)
                    && parsed.ContainsKey("rebellionDecision")
                    && ReadDictionary(parsed, "campaignOrder") != null;
            }

            return true;
        }

        private static Dictionary<string, object> ChatWithLlm(Dictionary<string, object> payload)
        {
            ThrowIfCampaignRequestReplaced();
            payload = payload ?? new Dictionary<string, object>();
            Dictionary<string, object> settings = LoadSettings();
            bool codexSubscription = UsesCodexSubscription(settings);
            bool namedApiProvider = ReadString(settings, "llmProvider", "") == OpenRouterProvider || ReadString(settings, "llmProvider", "") == NanoGptProvider;
            string apiUrl = namedApiProvider ? LlmApiUrl(settings) : ReadString(payload, "apiUrl", LlmApiUrl(settings));
            if (codexSubscription) apiUrl = "codex-app-server://local";
            string apiKey = namedApiProvider ? LlmApiKey(settings) : ReadString(payload, "apiKey", LlmApiKey(settings));
            string requestType = ReadString(payload, "requestType", "dialogue");
            string model = ReadString(payload, "model", ModelForRequest(settings, requestType));
            string campaignId = ReadString(payload, "campaignId", "default");
            string correlationId = EnsureCorrelationId(payload);
            using var diagnosticCall = BeginDiagnosticLlm(payload, apiKey);
            string heroId = ReadFirstString(payload, "heroStringId", "speakerHeroStringId", "heroId", "characterId");
            string eventId = ReadFirstString(payload, "eventId", "socialEventId");
            string actionId = ReadFirstString(payload, "actionId", "serverActionId");

            if (string.IsNullOrWhiteSpace(apiUrl))
            {
                WriteAudit(campaignId, correlationId, "server", requestType, "llm.request", heroId, actionId, eventId, "failed", 0, "LLM request blocked because API URL is empty.", new Dictionary<string, object>
                {
                    ["requestType"] = requestType,
                    ["model"] = model,
                    ["error"] = "API URL is empty."
                });
                diagnosticCall.End("failed", "API URL is empty. No provider request was sent.");
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "API URL is empty." };
            }

            ReignTraceScope providerTrace = BeginReignSpan("llm.provider", new Dictionary<string, object>
            {
                ["campaignId"] = campaignId, ["correlationId"] = correlationId, ["requestType"] = requestType,
                ["model"] = model, ["heroId"] = heroId, ["eventId"] = eventId
            });

            List<Dictionary<string, object>> messages = ReadDictionaryList(payload, "messages");
            if (codexSubscription) messages = messages.Select(DeepCloneProfileDictionary).ToList();
            if (messages.Count == 0)
            {
                string system = ReadString(payload, "system", "You are Bannerlord Reign, a Bannerlord AI world assistant.");
                string prompt = ReadString(payload, "prompt", ReadString(payload, "text", ""));
                messages.Add(new Dictionary<string, object> { ["role"] = "system", ["content"] = system });
                messages.Add(new Dictionary<string, object> { ["role"] = "user", ["content"] = prompt });
            }
            Dictionary<string, object> codexContext = BuildCodexGenerationContext(settings, payload, requestType, model, correlationId);
            if ((codexSubscription ? ReadString(codexContext, "requestedReasoningEffort", "none") : EffectiveReasoningEffort(settings, payload, requestType)) != "none")
            {
                ApplyPrivateReasoningPolicyToMessages(messages);
                Dictionary<string, object> promptDiagnostics = ReadDictionary(payload, "promptEnvelope");
                Dictionary<string, object> systemMessage = messages.FirstOrDefault(x => ReadString(x, "role", "").Equals("system", StringComparison.OrdinalIgnoreCase));
                if (promptDiagnostics != null && systemMessage != null)
                {
                    string systemContent = ReadString(systemMessage, "content", "");
                    promptDiagnostics["globalPrefixHash"] = PromptHash(systemContent);
                    promptDiagnostics["globalPrefixChars"] = systemContent.Length;
                    promptDiagnostics["reasoningPolicyIncluded"] = true;
                }
            }

            Dictionary<string, object> requestBody = BuildChatRequestBody(settings, payload, messages, model);
            if (codexSubscription) EnrichCodexGenerationContext(settings, payload, requestType, model, codexContext, requestBody);

            Dictionary<string, object> cacheRouting = ConfigurePromptCacheRouting(settings, payload, requestBody, apiUrl, model, requestType);
            Dictionary<string, object> reasoningRouting = ConfigureReasoningRouting(settings, payload, requestBody, apiUrl, model, requestType);
            if (codexSubscription)
            {
                reasoningRouting["mode"] = ReadString(ReadDictionary(settings, "codexOptions"), "reasoningMode", "selective");
                reasoningRouting["effort"] = ReadString(codexContext, "requestedReasoningEffort", "none");
                reasoningRouting["requested"] = ReadString(codexContext, "requestedReasoningEffort", "none") != "none";
                reasoningRouting["adapter"] = "codex_subscription";
            }
            string outboundJson = Json.Serialize(requestBody);
            var continuityPreflight = ReadDictionary(ReadDictionary(payload, "promptEnvelope"), "continuityPreflight") != null
                || requestType.IndexOf("continuity_repair", StringComparison.OrdinalIgnoreCase) >= 0
                ? BuildContinuityProviderPreflight(settings, payload, requestBody, apiUrl, ReadString(requestBody, "model", model)) : null;
            if (continuityPreflight != null) payload["continuityProviderPreflight"] = continuityPreflight;
            int totalRequestChars = outboundJson.Length;
            int messageChars = messages.Sum(message => ReadString(message, "content", "").Length);
            int warningCharacterLimit = ReadInt(settings, "promptWarningCharacterLimit", 100000);
            int hardCharacterLimit = ReadInt(settings, "promptHardCharacterLimit", 240000);
            Dictionary<string, object> promptPreflight = new Dictionary<string, object>
            {
                ["messageCharacters"] = messageChars,
                ["requestCharacters"] = outboundJson.Length,
                ["estimatedPromptTokens"] = continuityPreflight == null ? (int)Math.Ceiling(messageChars / 4d) : ReadInt(continuityPreflight, "inputTokenEstimate", 0),
                ["continuity"] = continuityPreflight,
                ["warningCharacterLimit"] = warningCharacterLimit,
                ["hardCharacterLimit"] = hardCharacterLimit,
                ["warningExceeded"] = outboundJson.Length > warningCharacterLimit,
                ["hardLimitExceeded"] = outboundJson.Length > hardCharacterLimit
            };
            payload["promptPreflight"] = promptPreflight;
            Dictionary<string, object> envelopeDiagnostics = ReadDictionary(payload, "promptEnvelope");
            if (envelopeDiagnostics != null) envelopeDiagnostics["providerPreflight"] = promptPreflight;
            providerTrace.Set("messageCharacters", messageChars);
            providerTrace.Set("requestCharacters", outboundJson.Length);
            providerTrace.Set("estimatedPromptTokens", (int)Math.Ceiling(messageChars / 4d));
            if (outboundJson.Length > warningCharacterLimit)
            {
                LogOperational("prompt.preflight_warning", new Dictionary<string, object>
                {
                    ["campaignId"] = campaignId, ["correlationId"] = correlationId, ["requestType"] = requestType,
                    ["heroId"] = heroId, ["eventId"] = eventId, ["preflight"] = promptPreflight,
                    ["sectionSizes"] = envelopeDiagnostics == null ? new Dictionary<string, object>() : ReadDictionary(envelopeDiagnostics, "sectionSizes")
                });
            }
            if (outboundJson.Length > hardCharacterLimit || (continuityPreflight != null && !ReadBool(continuityPreflight, "fits", false)))
            {
                string error = "Prompt safety ceiling exceeded before the provider call. Reign preserved the evidence and blocked the request instead of silently truncating it.";
                diagnosticCall.End("failed", error, promptPreflight);
                providerTrace.Set("blocked", true);
                providerTrace.Dispose();
                WriteAudit(campaignId, correlationId, "server", requestType, "llm.request", heroId, actionId, eventId, "failed", 0, error,
                    new Dictionary<string, object> { ["model"] = model, ["promptPreflight"] = promptPreflight, ["promptEnvelope"] = envelopeDiagnostics ?? new Dictionary<string, object>() });
                return new Dictionary<string, object>
                {
                    ["ok"] = false, ["error"] = error, ["errorCode"] = "prompt_hard_limit_exceeded",
                    ["requestType"] = requestType, ["model"] = model, ["promptPreflight"] = promptPreflight
                };
            }
            Stopwatch llmTimer = new Stopwatch();
            try
            {
                WriteAudit(campaignId, correlationId, "server", requestType, "llm.request", heroId, actionId, eventId, "started", 0, "LLM request started.", new Dictionary<string, object>
                {
                    ["requestType"] = requestType,
                    ["model"] = model,
                    ["apiUrl"] = apiUrl,
                    ["requestChars"] = outboundJson.Length,
                    ["promptCache"] = cacheRouting,
                    ["reasoningPolicy"] = reasoningRouting,
                    ["request"] = requestBody
                });
                llmTimer.Start();
                string responseText;
                try
                {
                    CapturePromptEvidence(campaignId, correlationId, requestType, model, requestBody, envelopeDiagnostics, apiKey);
                    responseText = PostLlmProviderJson(apiUrl, apiKey, outboundJson, requestBody, settings, cacheRouting, correlationId, requestType, model, codexContext);
                }
                catch (Exception reasoningException) when (ShouldRetryWithoutReasoning(reasoningRouting, reasoningException.Message))
                {
                    StartReasoningFallbackCooldown(settings, apiUrl, model);
                    reasoningRouting["fallbackUsed"] = true;
                    reasoningRouting["attemptCount"] = 2;
                    reasoningRouting["fallbackError"] = LimitText(reasoningException.Message, 1200);
                    reasoningRouting["cooldownUntilUtc"] = ReasoningFallbackCooldownUntil(ReasoningRouteKey(apiUrl, model)).ToString("o");
                    requestBody.Remove("reasoning");
                    requestBody.Remove("reasoning_effort");
                    outboundJson = Json.Serialize(requestBody);
                    totalRequestChars += outboundJson.Length;
                    CapturePromptEvidence(campaignId, correlationId, requestType, model, requestBody, envelopeDiagnostics, apiKey);
                    responseText = PostLlmProviderJson(apiUrl, apiKey, outboundJson, requestBody, settings, cacheRouting, correlationId, requestType, model, codexContext);
                }
                catch (Exception cacheRouteException) when (ShouldRetryWithoutCache(cacheRouting, cacheRouteException.Message))
                {
                    StartPromptCacheCooldown(settings, apiUrl, model);
                    cacheRouting["fallbackUsed"] = true;
                    cacheRouting["attemptCount"] = 2;
                    cacheRouting["cacheRouteError"] = LimitText(cacheRouteException.Message, 1200);
                    cacheRouting["cooldownUntilUtc"] = PromptCacheCooldownUntil(PromptCacheRouteKey(apiUrl, model)).ToString("o");
                    requestBody.Remove("caching");
                    requestBody.Remove("stickyprovider");
                    outboundJson = Json.Serialize(requestBody);
                    totalRequestChars += outboundJson.Length;
                    try
                    {
                        CapturePromptEvidence(campaignId, correlationId, requestType, model, requestBody, envelopeDiagnostics, apiKey);
                        responseText = PostLlmProviderJson(apiUrl, apiKey, outboundJson, requestBody, settings, cacheRouting, correlationId, requestType, model, codexContext);
                    }
                    catch (Exception reasoningException) when (ShouldRetryWithoutReasoning(reasoningRouting, reasoningException.Message))
                    {
                        StartReasoningFallbackCooldown(settings, apiUrl, model);
                        reasoningRouting["fallbackUsed"] = true;
                        reasoningRouting["attemptCount"] = 2;
                        reasoningRouting["fallbackError"] = LimitText(reasoningException.Message, 1200);
                        reasoningRouting["cooldownUntilUtc"] = ReasoningFallbackCooldownUntil(ReasoningRouteKey(apiUrl, model)).ToString("o");
                        requestBody.Remove("reasoning");
                        requestBody.Remove("reasoning_effort");
                        outboundJson = Json.Serialize(requestBody);
                        totalRequestChars += outboundJson.Length;
                            CapturePromptEvidence(campaignId, correlationId, requestType, model, requestBody, envelopeDiagnostics, apiKey);
                            responseText = PostLlmProviderJson(apiUrl, apiKey, outboundJson, requestBody, settings, cacheRouting, correlationId, requestType, model, codexContext);
                    }
                }
                llmTimer.Stop();
                Dictionary<string, object> raw = Json.Deserialize<Dictionary<string, object>>(responseText);
                if (continuityPreflight != null)
                {
                    int actual = ReadInt(ReadDictionary(raw, "usage"), "prompt_tokens", ReadInt(ReadDictionary(raw, "usage"), "input_tokens", 0));
                    continuityPreflight["actualInputTokens"] = actual > 0 ? (object)actual : null;
                    continuityPreflight["estimateErrorTokens"] = actual > 0 ? (object)(ReadInt(continuityPreflight, "inputTokenEstimate", 0) - actual) : null;
                    LogOperational("conversation.continuity_preflight", continuityPreflight);
                }
                string content = SanitizeReasoningContent(ExtractAssistantContent(raw));
                diagnosticCall.Trace?.Record("cleanup", "Extract and clean provider content", "completed",
                    content == ExtractAssistantContent(raw) ? "Assistant content was preserved." : "Reign changed the extracted content. Compare the original and cleaned values below.", 0,
                    new Dictionary<string, object> { ["extracted"] = ExtractAssistantContent(raw), ["cleaned"] = content }, diagnosticCall.Id);
                if (codexSubscription && ReadBool(ReadDictionary(ReadDictionary(raw, "codexDiagnostics"), "request"), "schemaApplied", false))
                {
                    var structuredContent = TryParseJsonObject(content);
                    if (structuredContent != null)
                    {
                        List<string> removedPaths;
                        var normalized = CodexConversationContracts.NormalizeStructuredOptionalNulls(
                            ReadString(codexContext, "schemaId", ""), structuredContent, out removedPaths);
                        if (removedPaths.Count > 0) content = Json.Serialize(normalized);
                        var diagnostics = ReadDictionary(raw, "codexDiagnostics");
                        if (diagnostics != null) diagnostics["schemaOmittedNullPaths"] = removedPaths;
                    }
                }
                Dictionary<string, object> safeRaw = SanitizeLlmResponseForStorage(raw);
                Dictionary<string, object> cacheDiagnostics = BuildPromptCacheDiagnostics(raw, cacheRouting, llmTimer.ElapsedMilliseconds, requestType, model, "");
                cacheDiagnostics["reasoningPolicy"] = reasoningRouting;
                Dictionary<string, object> result = new Dictionary<string, object>
                {
                    ["ok"] = true,
                    ["provider"] = codexSubscription ? CodexSubscriptionProvider : OpenAiCompatibleProvider,
                    ["requestType"] = requestType,
                    ["model"] = model,
                    ["durationMs"] = llmTimer.ElapsedMilliseconds,
                    ["requestChars"] = totalRequestChars,
                    ["responseChars"] = responseText.Length,
                    ["content"] = content,
                    ["finishReason"] = ExtractFinishReason(raw),
                    ["cache"] = cacheDiagnostics,
                    ["reasoning"] = reasoningRouting,
                    ["raw"] = safeRaw
                };
                providerTrace.Set("ok", true);
                if (codexSubscription)
                {
                    result["codexDiagnostics"] = ReadDictionary(raw, "codexDiagnostics") ?? new Dictionary<string, object>();
                    var appliedRequest = ReadDictionary(ReadDictionary(raw, "codexDiagnostics"), "request");
                    reasoningRouting["resolvedEffort"] = ReadString(appliedRequest, "resolvedReasoningEffort", "unknown");
                    reasoningRouting["resolution"] = ReadString(appliedRequest, "reasoningResolution", "unknown");
                    reasoningRouting["providerControlsApplied"] = appliedRequest != null;
                    ActiveCodexConversationScope.Value?.Results.Add(Tuple.Create(DeepCloneProfileDictionary(result), codexContext));
                }
                providerTrace.Set("providerDurationMs", llmTimer.ElapsedMilliseconds);
                providerTrace.Set("requestChars", totalRequestChars);
                providerTrace.Set("responseChars", responseText.Length);

                LogLlm(requestType, model, requestBody, safeRaw, cacheDiagnostics, true, null, llmTimer.ElapsedMilliseconds, totalRequestChars, responseText.Length);
                WriteAudit(campaignId, correlationId, "server", requestType, "llm.response", heroId, actionId, eventId, "completed", llmTimer.ElapsedMilliseconds, "LLM response received.", new Dictionary<string, object>
                {
                    ["requestType"] = requestType,
                    ["model"] = model,
                    ["durationMs"] = llmTimer.ElapsedMilliseconds,
                    ["requestChars"] = totalRequestChars,
                    ["responseChars"] = responseText.Length,
                    ["finishReason"] = ExtractFinishReason(raw),
                    ["content"] = content,
                    ["promptCache"] = cacheDiagnostics,
                    ["reasoningPolicy"] = reasoningRouting,
                    ["raw"] = safeRaw
                });
                providerTrace.Dispose();
                diagnosticCall.End("completed", "Provider output was received and processed; later validation determines whether it is usable.", result);
                return result;
            }
            catch (Exception ex)
            {
                if (llmTimer.IsRunning)
                {
                    llmTimer.Stop();
                }

                if (ex is CampaignRequestReplacedException)
                {
                    providerTrace.Fail(ex);
                    providerTrace.Dispose();
                    throw;
                }
                Dictionary<string, object> cacheDiagnostics = BuildPromptCacheDiagnostics(new Dictionary<string, object>(), cacheRouting, llmTimer.ElapsedMilliseconds, requestType, model, ex.Message);
                cacheDiagnostics["reasoningPolicy"] = reasoningRouting;
                LogLlm(requestType, model, requestBody, new Dictionary<string, object> { ["error"] = ex.Message }, cacheDiagnostics, false, ex.Message, llmTimer.ElapsedMilliseconds, totalRequestChars, 0);
                WriteAudit(campaignId, correlationId, "server", requestType, "llm.response", heroId, actionId, eventId, "failed", llmTimer.ElapsedMilliseconds, "LLM request failed.", new Dictionary<string, object>
                {
                    ["requestType"] = requestType,
                    ["model"] = model,
                    ["durationMs"] = llmTimer.ElapsedMilliseconds,
                    ["requestChars"] = totalRequestChars,
                    ["promptCache"] = cacheDiagnostics,
                    ["reasoningPolicy"] = reasoningRouting,
                    ["error"] = ex.Message
                });
                providerTrace.Fail(ex);
                providerTrace.Set("ok", false);
                providerTrace.Dispose();
                var failedResult = new Dictionary<string, object>
                {
                    ["ok"] = false,
                    ["provider"] = codexSubscription ? CodexSubscriptionProvider : OpenAiCompatibleProvider,
                    ["requestType"] = requestType,
                    ["model"] = model,
                    ["durationMs"] = llmTimer.ElapsedMilliseconds,
                    ["requestChars"] = totalRequestChars,
                    ["cache"] = cacheDiagnostics,
                    ["reasoning"] = reasoningRouting,
                    ["error"] = ex.Message
                };
                if (codexSubscription)
                {
                    failedResult["codexDiagnostics"] = ex.Data["codexDiagnostics"] as Dictionary<string, object> ?? new Dictionary<string, object>();
                    ActiveCodexConversationScope.Value?.Results.Add(Tuple.Create(DeepCloneProfileDictionary(failedResult), codexContext));
                }
                diagnosticCall.End("failed", ex.Message, failedResult);
                return failedResult;
            }
        }

        private static string PostJsonToLlmWithTransientRetry(
            string apiUrl,
            string apiKey,
            string requestJson,
            Dictionary<string, object> settings,
            Dictionary<string, object> diagnostics,
            string correlationId,
            string requestType,
            string model)
        {
            int maxAttempts = Math.Max(1, Math.Min(4, ReadInt(settings, "llmTransientMaxAttempts", 4)));
            if (FinalConversationGauntletProviderBudget
                .IsRegisteredCorrelation(correlationId))
                maxAttempts = Math.Min(maxAttempts, 3);
            List<string> retryErrors = new List<string>();
            for (int attempt = 1; attempt <= maxAttempts; attempt++)
            {
                Dictionary<string, object> reservation =
                    FinalConversationGauntletProviderBudget
                        .TryReserveRegisteredPhysicalDispatch(
                            correlationId, requestType, model, attempt);
                if (ReadBool(reservation, "scoped", false)
                    && !ReadBool(reservation, "allowed", false))
                    throw new FinalGauntletProviderBudgetExceededException(
                        "Final conversation gauntlet exhausted its hard "
                        + ReadInt(reservation, "maximum", 500)
                            .ToString(CultureInfo.InvariantCulture)
                        + "-call external-provider budget.");
                try
                {
                    string response = PostJsonToLlm(apiUrl, apiKey, requestJson, settings);
                    FinalConversationGauntletProviderBudget
                        .CompleteRegisteredPhysicalDispatch(
                            reservation, true, "");
                    if (diagnostics != null)
                    {
                        diagnostics["transientRetryCount"] = retryErrors.Count;
                        diagnostics["transientRetryErrors"] = retryErrors;
                        diagnostics["attemptCount"] = Math.Max(ReadInt(diagnostics, "attemptCount", 1), attempt);
                    }
                    return response;
                }
                catch (Exception ex) when (attempt < maxAttempts && IsTransientLlmFailure(ex.Message))
                {
                    FinalConversationGauntletProviderBudget
                        .CompleteRegisteredPhysicalDispatch(
                            reservation, false, ex.Message);
                    retryErrors.Add(LimitText(ex.Message, 600));
                    if (diagnostics != null)
                    {
                        diagnostics["transientRetryCount"] = retryErrors.Count;
                        diagnostics["transientRetryErrors"] = retryErrors;
                        diagnostics["attemptCount"] = Math.Max(ReadInt(diagnostics, "attemptCount", 1), attempt + 1);
                    }
                    Thread.Sleep(Math.Min(8000, 2000 * attempt));
                }
                catch (Exception ex)
                {
                    FinalConversationGauntletProviderBudget
                        .CompleteRegisteredPhysicalDispatch(
                            reservation, false, ex.Message);
                    throw;
                }
            }
            throw new InvalidOperationException("Transient LLM retry loop exhausted unexpectedly.");
        }

        private static bool IsTransientLlmFailure(string message)
        {
            string value = (message ?? "").ToLowerInvariant();
            return value.Contains("billing reservation failed")
                || value.Contains("async_billing_reservation_failed")
                || value.Contains("status 408") || value.Contains("(408)")
                || value.Contains("status 429") || value.Contains("(429)")
                || value.Contains("status 500") || value.Contains("(500)")
                || value.Contains("status 502") || value.Contains("(502)")
                || value.Contains("status 503") || value.Contains("(503)")
                || value.Contains("status 504") || value.Contains("(504)")
                || (value.Contains("\"type\":\"invalid_request_error\"")
                    && value.Contains("\"code\":\"provider_error\""))
                || value.Contains("temporarily unavailable")
                || value.Contains("timed out") || value.Contains("timeout")
                || value.Contains("connection reset") || value.Contains("connection closed")
                || value.Contains("connection was closed") || value.Contains("underlying connection");
        }

        private static string PostJsonToLlm(string apiUrl, string apiKey, string requestJson, Dictionary<string, object> settings)
        {
            using var diagnosticAttempt = BeginDiagnosticAttempt(apiUrl, requestJson, apiKey);
            HttpWebRequest request = (HttpWebRequest)WebRequest.Create(apiUrl);
            request.Method = "POST";
            request.ContentType = "application/json";
            request.Accept = "application/json";
            int providerRequestTimeoutMs = Math.Max(15000,
                Math.Min(600000, ReadInt(settings, "providerRequestTimeoutMs", 120000)));
            request.Timeout = providerRequestTimeoutMs;
            request.ReadWriteTimeout = providerRequestTimeoutMs;
            if (!string.IsNullOrWhiteSpace(apiKey))
            {
                request.Headers["Authorization"] = "Bearer " + apiKey;
            }

            string siteUrl = ReadString(settings, "siteUrl", "");
            string appTitle = ReadString(settings, "appTitle", "ReignBeta");
            if (!string.IsNullOrWhiteSpace(siteUrl))
            {
                request.Headers["HTTP-Referer"] = siteUrl;
                request.Headers["Referer"] = siteUrl;
            }

            if (!string.IsNullOrWhiteSpace(appTitle))
            {
                request.Headers["X-Title"] = appTitle;
                if (IsOpenRouterApiUrl(apiUrl)) request.Headers["X-OpenRouter-Title"] = appTitle;
            }

            byte[] bytes = Encoding.UTF8.GetBytes(requestJson);
            request.ContentLength = bytes.Length;
            try
            {
                using (Stream requestStream = request.GetRequestStream())
                {
                    requestStream.Write(bytes, 0, bytes.Length);
                }
                using (HttpWebResponse response = (HttpWebResponse)request.GetResponse())
                using (Stream responseStream = response.GetResponseStream())
                using (StreamReader reader = new StreamReader(responseStream ?? Stream.Null, Encoding.UTF8))
                {
                    string responseBody = reader.ReadToEnd();
                    diagnosticAttempt.End("received", "Original HTTP response captured before JSON parsing or reasoning cleanup.",
                        new Dictionary<string, object> { ["httpStatus"] = (int)response.StatusCode, ["responseBody"] = responseBody,
                            ["requestId"] = response.Headers["x-request-id"], ["contentType"] = response.ContentType });
                    return responseBody;
                }
            }
            catch (WebException ex)
            {
                string body = "";
                if (ex.Response != null)
                {
                    using (Stream responseStream = ex.Response.GetResponseStream())
                    using (StreamReader reader = new StreamReader(responseStream ?? Stream.Null, Encoding.UTF8))
                    {
                        body = reader.ReadToEnd();
                    }
                }

                diagnosticAttempt.End("failed", ex.Message, new Dictionary<string, object> { ["responseBody"] = body,
                    ["httpStatus"] = ex.Response is HttpWebResponse failedHttp ? (object)(int)failedHttp.StatusCode : null,
                    ["error"] = ex.Message, ["transportStatus"] = ex.Status.ToString() });
                throw new InvalidOperationException(string.IsNullOrWhiteSpace(body) ? ex.Message : body, ex);
            }
        }

        // Windows and Linux JSON adapters expose different IList implementations.
        private static string ExtractAssistantContent(Dictionary<string, object> raw)
        {
            if (raw == null || !raw.TryGetValue("choices", out object choicesValue) || !(choicesValue is IList choices) || choices.Count == 0)
            {
                return "";
            }

            Dictionary<string, object> first = choices[0] as Dictionary<string, object>;
            if (first == null)
            {
                return "";
            }

            Dictionary<string, object> message = first.ContainsKey("message") ? first["message"] as Dictionary<string, object> : null;
            string content = ReadString(message, "content", "");
            return string.IsNullOrWhiteSpace(content) ? ReadString(first, "text", "") : content;
        }

        private static string ExtractFinishReason(Dictionary<string, object> raw)
        {
            if (raw == null || !raw.TryGetValue("choices", out object choicesValue) || !(choicesValue is IList choices) || choices.Count == 0)
            {
                return "";
            }

            Dictionary<string, object> first = choices[0] as Dictionary<string, object>;
            return ReadString(first, "finish_reason", "");
        }

        private static void LogLlm(string requestType, string model, Dictionary<string, object> requestBody, Dictionary<string, object> responseBody, Dictionary<string, object> cacheDiagnostics, bool ok, string error, long durationMs, int requestChars, int responseChars)
        {
            Dictionary<string, object> settings = LoadSettings();
            if (!ReadBool(settings, "enableLlmLogging", true))
            {
                return;
            }

            Dictionary<string, object> row = new Dictionary<string, object>
            {
                ["ts"] = DateTimeOffset.UtcNow.ToString("o"),
                ["ok"] = ok,
                ["requestType"] = requestType,
                ["model"] = model,
                ["durationMs"] = durationMs,
                ["requestChars"] = requestChars,
                ["responseChars"] = responseChars,
                ["promptCache"] = cacheDiagnostics ?? new Dictionary<string, object>(),
                ["request"] = requestBody,
                ["response"] = responseBody
            };
            if (!string.IsNullOrWhiteSpace(error))
            {
                row["error"] = error;
            }

            lock (FileLock)
            {
                AppendBoundedJsonLineToPathLocked(Path.Combine(LogsDir, "llm-log.jsonl"), row,
                    16L * 1024L * 1024L, 8L * 1024L * 1024L);
            }
        }

        private static Dictionary<string, object> ToCaseInsensitiveDictionary(Dictionary<string, object> source)
        {
            return new Dictionary<string, object>(source ?? new Dictionary<string, object>(), StringComparer.OrdinalIgnoreCase);
        }

        private static void NormalizeChatAiTerms(Dictionary<string, object> raw, Dictionary<string, object> terms)
        {
            if (raw == null || terms == null)
            {
                return;
            }

            CopyTermAlias(raw, terms, "TargetSettlement", "targetSettlement");
            CopyTermAlias(raw, terms, "TargetSettlement", "settlementName");
            CopyTermAlias(raw, terms, "TargetHero", "targetHero");
            CopyTermAlias(raw, terms, "TargetClan", "targetClan");
            CopyTermAlias(raw, terms, "TargetKingdom", "targetKingdom");
            CopyTermAlias(raw, terms, "TargetParty", "targetParty");
            CopyTermAlias(raw, terms, "TargetArmy", "targetArmy");
            CopyTermAlias(raw, terms, "KillerHero", "killerHero");
            CopyTermAlias(raw, terms, "FromHero", "fromHero");
            CopyTermAlias(raw, terms, "ToHero", "toHero");
            CopyTermAlias(raw, terms, "FromClan", "fromClan");
            CopyTermAlias(raw, terms, "ToClan", "toClan");
            CopyTermAlias(raw, terms, "FromKingdom", "fromKingdom");
            CopyTermAlias(raw, terms, "ToKingdom", "toKingdom");
            CopyTermAlias(raw, terms, "Policy", "policy");
            CopyTermAlias(raw, terms, "SocialAction", "socialAction");
            CopyTermAlias(raw, terms, "Claim", "claim");
            CopyTermAlias(raw, terms, "Promise", "promiseText");
            CopyTermAlias(raw, terms, "proposal", "packageText");
            CopyTermAlias(raw, terms, "treatyType", "treatyKind");
            CopyTermAlias(raw, terms, "treaty", "treatyKind");

            string gold = ReadFirstString(raw, "GoldAmount", "goldAmount", "gold");
            if (!string.IsNullOrWhiteSpace(gold))
            {
                AddIfMissing(terms, "gold", gold);
                AddIfMissing(terms, "reparationsGold", gold);
            }

            string item = ReadFirstString(raw, "Item", "item");
            if (!string.IsNullOrWhiteSpace(item))
            {
                AddIfMissing(terms, "item", item);
            }

            string workshop = ReadFirstString(raw, "Workshop", "workshop");
            if (!string.IsNullOrWhiteSpace(workshop))
            {
                AddIfMissing(terms, "workshop", workshop);
            }

            string amount = ReadFirstString(raw, "Amount", "amount");
            if (!string.IsNullOrWhiteSpace(amount))
            {
                AddIfMissing(terms, "amount", amount);
            }

            string prisoner = ReadFirstString(raw, "PrisonerHero", "prisonerHero");
            if (!string.IsNullOrWhiteSpace(prisoner))
            {
                AddIfMissing(terms, "prisonerHero", prisoner);
            }
        }

        private static void CopyTermAlias(Dictionary<string, object> raw, Dictionary<string, object> terms, string rawKey, string termKey)
        {
            if (raw == null || terms == null || string.IsNullOrWhiteSpace(rawKey) || string.IsNullOrWhiteSpace(termKey))
            {
                return;
            }

            string value = ReadString(raw, rawKey, "");
            if (!string.IsNullOrWhiteSpace(value))
            {
                AddIfMissing(terms, termKey, value);
            }
        }

        private static void ResolveActionReferences(Dictionary<string, object> raw, Dictionary<string, object> terms, Dictionary<string, object> payload, string resolutionText, string command, List<string> errors, List<Dictionary<string, object>> trace)
        {
            Dictionary<string, object> index = ReadDictionary(payload, "actionResolutionIndex") ?? new Dictionary<string, object>();
            if (index.Count == 0)
            {
                TraceResolver(trace, "index", "none", "", "missing_index", "", new List<string>());
                return;
            }

            string actorHero = ResolveIndexedEntity(index, "heroes", "hero",
                FirstNonEmpty(ReadFirstString(raw, "actorHeroStringId", "actorHeroId", "leaderHeroId", "heroId", "FromHero"), ReadFirstString(terms, "actorHeroStringId", "actorHeroId", "leaderHeroId", "heroId", "FromHero")),
                "heroStringId", new[] { "name" }, "actor hero", errors, false, trace);
            if (!string.IsNullOrWhiteSpace(actorHero))
            {
                raw["actorHeroStringId"] = actorHero;
                AddIfMissing(terms, "fromHeroStringId", actorHero);
            }

            bool isPrisonerTransfer = string.Equals(command, "transfer_prisoner", StringComparison.OrdinalIgnoreCase);
            bool isAutonomousRansom = string.Equals(command, "ransom_package",
                    StringComparison.OrdinalIgnoreCase)
                && string.Equals(ReadString(raw, "source", ""),
                    "world_diplomacy_director", StringComparison.OrdinalIgnoreCase);
            string targetHeroQuery = isPrisonerTransfer
                ? FirstNonEmpty(ReadFirstString(raw, "targetHeroStringId", "targetHeroId", "TargetHero", "PrisonerHero"), ReadFirstString(terms, "targetHeroStringId", "targetHeroId", "TargetHero", "PrisonerHero", "prisonerHero"))
                : isAutonomousRansom
                    ? FirstNonEmpty(ReadFirstString(raw, "targetHeroStringId",
                            "targetHeroId", "TargetHero", "ToHero"),
                        ReadFirstString(terms, "targetHeroStringId",
                            "targetHeroId", "TargetHero", "ToHero"))
                : FirstNonEmpty(ReadFirstString(raw, "targetHeroStringId", "targetHeroId", "TargetHero", "ToHero", "PrisonerHero"), ReadFirstString(terms, "targetHeroStringId", "targetHeroId", "TargetHero", "ToHero", "PrisonerHero", "prisonerHero"));
            string targetHero = ResolveIndexedEntity(index, "heroes", "hero",
                targetHeroQuery,
                "heroStringId", new[] { "name" }, "target hero", errors, false, trace);
            if (!string.IsNullOrWhiteSpace(targetHero))
            {
                raw["targetHeroStringId"] = targetHero;
                AddIfMissing(terms, "targetHeroStringId", targetHero);
                if (isPrisonerTransfer
                    || (!isAutonomousRansom
                        && (!string.IsNullOrWhiteSpace(ReadFirstString(raw,
                                "PrisonerHero", "prisonerHero"))
                            || !string.IsNullOrWhiteSpace(ReadFirstString(terms,
                                "PrisonerHero", "prisonerHero")))))
                {
                    AddIfMissing(terms, "prisonerHeroStringId", targetHero);
                }
                else
                {
                    AddIfMissing(terms, "toHeroStringId", targetHero);
                }
            }

            if (isAutonomousRansom)
            {
                string prisonerQuery = FirstNonEmpty(
                    ReadFirstString(raw, "PrisonerHero", "prisonerHero",
                        "prisonerHeroStringId"),
                    ReadFirstString(terms, "PrisonerHero", "prisonerHero",
                        "prisonerHeroStringId"));
                string prisonerHero = ResolveIndexedEntity(index, "heroes", "hero",
                    prisonerQuery, "heroStringId", new[] { "name" },
                    "ransom prisoner", errors, false, trace);
                if (!string.IsNullOrWhiteSpace(prisonerHero))
                {
                    raw["PrisonerHero"] = prisonerHero;
                    terms["prisonerHeroStringId"] = prisonerHero;
                }
            }

            if (string.Equals(command, "duel_player", StringComparison.OrdinalIgnoreCase)
                && string.IsNullOrWhiteSpace(ReadFirstString(raw, "actorHeroStringId", "actorHeroId"))
                && !string.IsNullOrWhiteSpace(targetHero))
            {
                raw["actorHeroStringId"] = targetHero;
                AddIfMissing(terms, "fromHeroStringId", targetHero);
                TraceResolver(trace, "duel actor", "hero", "targetHero", "duel_default_actor", targetHero, new List<string> { targetHero });
            }

            string toHero = ResolveIndexedEntity(index, "heroes", "hero",
                FirstNonEmpty(ReadFirstString(raw, "toHeroStringId", "toHeroId", "ToHero"), ReadFirstString(terms, "toHeroStringId", "toHeroId", "ToHero", "toHero")),
                "heroStringId", new[] { "name" }, "receiving hero", errors, false, trace);
            if (!string.IsNullOrWhiteSpace(toHero))
            {
                AddIfMissing(terms, "toHeroStringId", toHero);
            }

            string killerHero = ResolveIndexedEntity(index, "heroes", "hero",
                FirstNonEmpty(ReadFirstString(raw, "killerHeroStringId", "killerHeroId", "KillerHero"), ReadFirstString(terms, "killerHeroStringId", "killerHeroId", "KillerHero", "killerHero")),
                "heroStringId", new[] { "name" }, "killer hero", errors, false, trace);
            if (!string.IsNullOrWhiteSpace(killerHero))
            {
                terms["killerHeroStringId"] = killerHero;
            }

            string actorClan = ResolveIndexedEntity(index, "clans", "clan",
                FirstNonEmpty(ReadFirstString(raw, "actorClanStringId", "actorClanId", "claimantClanId", "FromClan"), ReadFirstString(terms, "actorClanStringId", "actorClanId", "claimantClanId", "FromClan")),
                "clanId", new[] { "name", "leaderName" }, "actor clan", errors, false, trace);
            if (!string.IsNullOrWhiteSpace(actorClan))
            {
                raw["actorClanStringId"] = actorClan;
            }

            string targetClan = ResolveIndexedEntity(index, "clans", "clan",
                FirstNonEmpty(ReadFirstString(raw, "targetClanStringId", "targetClanId", "TargetClan", "ToClan"), ReadFirstString(terms, "targetClanStringId", "targetClanId", "TargetClan", "ToClan")),
                "clanId", new[] { "name", "leaderName" }, "target clan", errors, false, trace);
            if (!string.IsNullOrWhiteSpace(targetClan))
            {
                raw["targetClanStringId"] = targetClan;
            }

            string family = ActionFamilyForId(command);
            bool strictKingdomReferences = string.Equals(family, "diplomacy", StringComparison.OrdinalIgnoreCase)
                || string.Equals(family, "politics", StringComparison.OrdinalIgnoreCase);
            string actorKingdomQuery = NormalizeKingdomQuery(index, payload, raw, terms,
                FirstNonEmpty(ReadFirstString(raw, "actorKingdomStringId", "actorKingdomId", "kingdomId", "FromKingdom"), ReadFirstString(terms, "actorKingdomStringId", "actorKingdomId", "kingdomId", "FromKingdom")),
                true);
            string actorKingdom = ResolveIndexedEntity(index, "kingdoms", "kingdom",
                actorKingdomQuery,
                "kingdomId", new[] { "name", "formalName", "leaderName", "rulingClanName" }, "actor kingdom", errors, strictKingdomReferences, trace);
            if (!strictKingdomReferences && !string.IsNullOrWhiteSpace(actorKingdom) && !IndexContainsEntityId(index, "kingdoms", "kingdomId", actorKingdom))
            {
                actorKingdom = string.Empty;
            }

            if (!string.IsNullOrWhiteSpace(actorKingdom))
            {
                raw["actorKingdomStringId"] = actorKingdom;
            }

            string targetKingdomQuery = NormalizeKingdomQuery(index, payload, raw, terms,
                FirstNonEmpty(ReadFirstString(raw, "targetKingdomStringId", "targetKingdomId", "TargetKingdom", "ToKingdom"), ReadFirstString(terms, "targetKingdomStringId", "targetKingdomId", "TargetKingdom", "ToKingdom")),
                false);
            string targetKingdom = ResolveIndexedEntity(index, "kingdoms", "kingdom",
                targetKingdomQuery,
                "kingdomId", new[] { "name", "formalName", "leaderName", "rulingClanName" }, "target kingdom", errors, strictKingdomReferences, trace);
            if (!strictKingdomReferences && !string.IsNullOrWhiteSpace(targetKingdom) && !IndexContainsEntityId(index, "kingdoms", "kingdomId", targetKingdom))
            {
                targetKingdom = string.Empty;
            }

            if (!string.IsNullOrWhiteSpace(targetKingdom))
            {
                raw["targetKingdomStringId"] = targetKingdom;
            }

            string targetSettlement = ResolveIndexedEntity(index, "settlements", "settlement",
                FirstNonEmpty(ReadFirstString(raw, "targetSettlementStringId", "targetSettlementId", "settlementId", "TargetSettlement", "ToSettlement"), ReadFirstString(terms, "targetSettlementStringId", "targetSettlementId", "settlementId", "TargetSettlement", "ToSettlement", "targetSettlement", "settlementName")),
                "settlementId", new[] { "name" }, "target settlement", errors, true, trace);
            List<string> settlementTerms = ReadStringList(terms, "settlementIds");
            List<string> resolvedSettlementTerms = new List<string>();
            foreach (string settlementTerm in settlementTerms)
            {
                string resolved = ResolveIndexedEntity(index, "settlements", "settlement", settlementTerm, "settlementId", new[] { "name" }, "terms.settlementIds", errors, true, trace);
                if (!string.IsNullOrWhiteSpace(resolved))
                {
                    resolvedSettlementTerms.Add(resolved);
                }
            }

            if (string.IsNullOrWhiteSpace(targetSettlement) && CanInferSettlementFromText(command))
            {
                targetSettlement = ResolveSemanticSettlementFromText(index, resolutionText, command, trace);
                if (string.IsNullOrWhiteSpace(targetSettlement))
                {
                    targetSettlement = ResolveMentionedSettlement(index, resolutionText, ReadFirstString(raw, "targetKingdomStringId", "targetKingdomId"), errors, trace);
                }
            }

            if (!string.IsNullOrWhiteSpace(targetSettlement))
            {
                raw["targetSettlementStringId"] = targetSettlement;
                AddIfMissing(terms, "targetSettlementStringId", targetSettlement);
                if (resolvedSettlementTerms.Count == 0 && (string.Equals(command, "demand_settlement_peace", StringComparison.OrdinalIgnoreCase) || string.Equals(command, "demand_surrender_peace", StringComparison.OrdinalIgnoreCase)))
                {
                    resolvedSettlementTerms.Add(targetSettlement);
                }
            }

            if (resolvedSettlementTerms.Count > 0)
            {
                terms["settlementIds"] = new ArrayList(resolvedSettlementTerms.Distinct(StringComparer.OrdinalIgnoreCase).ToList());
            }

            if (string.Equals(command, "demand_surrender_peace", StringComparison.OrdinalIgnoreCase)
                && resolvedSettlementTerms.Count == 0
                && string.IsNullOrWhiteSpace(targetSettlement))
            {
                terms["allTargetFortifications"] = true;
            }

            string targetParty = ResolveIndexedEntity(index, "parties", "party", FirstNonEmpty(ReadFirstString(raw, "targetPartyId", "TargetParty"), ReadFirstString(terms, "targetPartyId", "TargetParty", "targetParty")), "partyId", new[] { "name", "leaderName" }, "target party", errors, false, trace);
            if (!string.IsNullOrWhiteSpace(targetParty))
            {
                terms["targetPartyId"] = targetParty;
            }

            string targetArmy = ResolveIndexedEntity(index, "armies", "army", FirstNonEmpty(ReadFirstString(raw, "targetArmyId", "TargetArmy"), ReadFirstString(terms, "targetArmyId", "TargetArmy", "targetArmy")), "armyId", new[] { "name", "leaderName" }, "target army", errors, false, trace);
            if (!string.IsNullOrWhiteSpace(targetArmy))
            {
                terms["targetArmyId"] = targetArmy;
            }

            ResolveItemReference(index, raw, terms, trace);
            ResolveWorkshopReference(index, raw, terms, errors, trace);
        }

        private static void ResolveWorkshopReference(Dictionary<string, object> index, Dictionary<string, object> raw, Dictionary<string, object> terms, List<string> errors, List<Dictionary<string, object>> trace)
        {
            string workshopQuery = FirstNonEmpty(ReadFirstString(raw, "Workshop", "workshop", "workshopId"), ReadFirstString(terms, "Workshop", "workshop", "workshopId"));
            if (string.IsNullOrWhiteSpace(workshopQuery))
            {
                return;
            }

            string workshopId = ResolveIndexedEntity(index, "workshops", "workshop", workshopQuery, "workshopId", new[] { "name", "typeName", "settlementName", "tag" }, "workshop", errors, false, trace);
            if (!string.IsNullOrWhiteSpace(workshopId))
            {
                terms["workshopId"] = workshopId;
            }
        }

        private static bool CanInferSettlementFromText(string command)
        {
            switch (CanonicalCommand(command))
            {
                case "trade_package":
                case "demand_settlement_peace":
                case "return_occupied_settlement":
                case "recruit_and_recover":
                case "form_army":
                case "attack_settlement":
                case "capture_settlement_plan":
                case "go_to_settlement":
                case "patrol_around_settlement":
                case "wait_near_settlement":
                case "raid_village":
                case "besiege_settlement":
                    return true;
                default:
                    return false;
            }
        }

        private static string ResolveSemanticSettlementFromText(Dictionary<string, object> index, string text, string command, List<Dictionary<string, object>> trace)
        {
            string query = (text ?? string.Empty).Trim();
            string normalized = NormalizeLookup(query);
            if (string.IsNullOrWhiteSpace(normalized))
            {
                return string.Empty;
            }

            bool hasSemanticShape = normalized.Contains("nearest")
                || normalized.Contains("closest")
                || normalized.Contains("friendly")
                || normalized.Contains("enemy")
                || normalized.Contains("hostile")
                || normalized.Contains("village")
                || normalized.Contains("town")
                || normalized.Contains("city")
                || normalized.Contains("castle")
                || normalized.Contains("hideout");
            if (!hasSemanticShape)
            {
                return string.Empty;
            }

            List<Dictionary<string, object>> settlements = ReadDictionaryList(index, "settlements");
            return ResolveSemanticEntity(index, settlements, "settlements", "settlement", normalized, "settlementId", trace, "semantic settlement", query);
        }

        private static string NormalizeKingdomQuery(Dictionary<string, object> index, Dictionary<string, object> payload, Dictionary<string, object> raw, Dictionary<string, object> terms, string query, bool actorRole)
        {
            string value = (query ?? string.Empty).Trim();
            if (string.IsNullOrWhiteSpace(value) || !LooksLikeClanIdentifier(value))
            {
                return value;
            }

            string clanKingdom = FindKingdomIdForClanReference(index, value);
            if (!string.IsNullOrWhiteSpace(clanKingdom))
            {
                return clanKingdom;
            }

            Dictionary<string, object> hero = ReadDictionary(payload, "hero") ?? new Dictionary<string, object>();
            string playerClanId = FirstNonEmpty(
                ReadFirstString(payload, "playerClanId", "actorClanId", "actorClanStringId"),
                ReadFirstString(raw, "actorClanStringId", "actorClanId"),
                ReadFirstString(terms, "actorClanStringId", "actorClanId"));
            string speakerClanId = FirstNonEmpty(
                ReadFirstString(payload, "speakerClanId", "targetClanId", "targetClanStringId"),
                ReadFirstString(raw, "targetClanStringId", "targetClanId"),
                ReadFirstString(terms, "targetClanStringId", "targetClanId"));
            string playerKingdomId = FirstUsableKingdomReference(index,
                ReadFirstString(payload, "playerKingdomId", "actorKingdomId", "actorKingdomStringId"),
                ReadString(hero, "playerKingdomId", ""));
            string speakerKingdomId = FirstUsableKingdomReference(index,
                ReadFirstString(payload, "speakerKingdomId", "targetKingdomId", "targetKingdomStringId"),
                ReadString(hero, "kingdomId", ""));

            if (!string.IsNullOrWhiteSpace(speakerClanId) && string.Equals(value, speakerClanId, StringComparison.OrdinalIgnoreCase))
            {
                return FirstNonEmpty(speakerKingdomId, value);
            }

            if (!string.IsNullOrWhiteSpace(playerClanId) && string.Equals(value, playerClanId, StringComparison.OrdinalIgnoreCase))
            {
                return FirstNonEmpty(playerKingdomId, value);
            }

            return actorRole ? FirstNonEmpty(playerKingdomId, speakerKingdomId, value) : FirstNonEmpty(speakerKingdomId, playerKingdomId, value);
        }

        private static bool LooksLikeClanIdentifier(string value)
        {
            if (string.IsNullOrWhiteSpace(value))
            {
                return false;
            }

            string q = value.Trim();
            return q.StartsWith("clan_", StringComparison.OrdinalIgnoreCase)
                || q.EndsWith("_clan", StringComparison.OrdinalIgnoreCase)
                || q.IndexOf("clan.", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static string FindKingdomIdForClanReference(Dictionary<string, object> index, string query)
        {
            string normalized = NormalizeLookup(query);
            if (index == null || string.IsNullOrWhiteSpace(normalized))
            {
                return string.Empty;
            }

            foreach (Dictionary<string, object> clan in ReadDictionaryList(index, "clans"))
            {
                string clanId = ReadString(clan, "clanId", "");
                string clanName = ReadString(clan, "name", "");
                string leaderName = ReadString(clan, "leaderName", "");
                if (!string.Equals(clanId, query, StringComparison.OrdinalIgnoreCase)
                    && NormalizeLookup(clanName) != normalized
                    && NormalizeLookup(leaderName) != normalized)
                {
                    continue;
                }

                string kingdom = FirstUsableKingdomReference(index,
                    ReadFirstString(clan, "kingdomId", "kingdomStringId", "factionId", "mapFactionId", "ownerKingdomId"),
                    ReadFirstString(clan, "kingdomName", "factionName"));
                if (!string.IsNullOrWhiteSpace(kingdom))
                {
                    return kingdom;
                }
            }

            return string.Empty;
        }

        private static string FirstUsableKingdomReference(Dictionary<string, object> index, params string[] values)
        {
            if (values == null)
            {
                return string.Empty;
            }

            foreach (string value in values)
            {
                string resolved = ResolveKingdomIdLenient(index, value);
                if (!string.IsNullOrWhiteSpace(resolved))
                {
                    return resolved;
                }
            }

            return string.Empty;
        }

        private static string ResolveKingdomIdLenient(Dictionary<string, object> index, string value)
        {
            string query = (value ?? string.Empty).Trim();
            if (string.IsNullOrWhiteSpace(query) || LooksLikeClanIdentifier(query))
            {
                return string.Empty;
            }

            List<Dictionary<string, object>> kingdoms = ReadDictionaryList(index, "kingdoms");
            if (kingdoms.Count == 0)
            {
                return query;
            }

            Dictionary<string, object> idMatch = kingdoms.FirstOrDefault(x => string.Equals(ReadString(x, "kingdomId", ""), query, StringComparison.OrdinalIgnoreCase));
            if (idMatch != null)
            {
                return ReadString(idMatch, "kingdomId", "");
            }

            string normalized = NormalizeLookup(query);
            List<Dictionary<string, object>> nameMatches = kingdoms
                .Where(x => new[] { "name", "formalName", "leaderName", "rulingClanName" }.Any(key => NormalizeLookup(ReadString(x, key, "")) == normalized))
                .ToList();
            return nameMatches.Count == 1 ? ReadString(nameMatches[0], "kingdomId", "") : string.Empty;
        }

        private static bool IndexContainsEntityId(Dictionary<string, object> index, string collectionKey, string idKey, string id)
        {
            if (string.IsNullOrWhiteSpace(id))
            {
                return false;
            }

            List<Dictionary<string, object>> entries = ReadDictionaryList(index, collectionKey);
            if (entries.Count == 0)
            {
                return true;
            }

            return entries.Any(x => string.Equals(ReadString(x, idKey, ""), id, StringComparison.OrdinalIgnoreCase));
        }

        private static string ResolveIndexedEntity(Dictionary<string, object> index, string collectionKey, string entityType, string rawValue, string idKey, string[] nameKeys, string label, List<string> errors, bool strictWhenIndexed, List<Dictionary<string, object>> trace)
        {
            string query = (rawValue ?? string.Empty).Trim();
            if (string.IsNullOrWhiteSpace(query))
            {
                return string.Empty;
            }

            string alias = ResolveAlias(index, entityType, query);
            if (!string.IsNullOrWhiteSpace(alias))
            {
                TraceResolver(trace, label, entityType, query, "alias", alias, new List<string> { alias });
                return alias;
            }

            List<Dictionary<string, object>> entries = ReadDictionaryList(index, collectionKey);
            if (entries.Count == 0)
            {
                TraceResolver(trace, label, entityType, query, "no_index_entries", query, new List<string>());
                return query;
            }

            Dictionary<string, object> idMatch = entries.FirstOrDefault(x => string.Equals(ReadString(x, idKey, ""), query, StringComparison.OrdinalIgnoreCase));
            if (idMatch != null)
            {
                TraceResolver(trace, label, entityType, query, "id", ReadString(idMatch, idKey, ""), new List<string> { ReadString(idMatch, "name", ReadString(idMatch, idKey, "")) });
                return ReadString(idMatch, idKey, "");
            }

            string normalized = NormalizeLookup(query);
            List<Dictionary<string, object>> exactNameMatches = entries
                .Where(x => nameKeys.Any(key => NormalizeLookup(ReadString(x, key, "")) == normalized))
                .ToList();
            if (exactNameMatches.Count == 1)
            {
                TraceResolver(trace, label, entityType, query, "exact_name", ReadString(exactNameMatches[0], idKey, ""), exactNameMatches.Select(x => ReadString(x, "name", ReadString(x, idKey, ""))).ToList());
                return ReadString(exactNameMatches[0], idKey, "");
            }

            if (exactNameMatches.Count > 1)
            {
                errors.Add("Ambiguous " + label + " '" + query + "': " + string.Join(", ", exactNameMatches.Take(6).Select(x => ReadString(x, "name", ReadString(x, idKey, "")))));
                TraceResolver(trace, label, entityType, query, "ambiguous_exact_name", "", exactNameMatches.Take(12).Select(x => ReadString(x, "name", ReadString(x, idKey, ""))).ToList());
                return string.Empty;
            }

            string semantic = ResolveSemanticEntity(index, entries, collectionKey, entityType, normalized, idKey, trace, label, query);
            if (!string.IsNullOrWhiteSpace(semantic))
            {
                return semantic;
            }

            List<Dictionary<string, object>> partialMatches = entries
                .Where(x => nameKeys.Any(key =>
                {
                    string candidate = NormalizeLookup(ReadString(x, key, ""));
                    return candidate.Length >= 3 && normalized.Length >= 3 && (candidate.Contains(normalized) || normalized.Contains(candidate));
                }))
                .ToList();
            if (partialMatches.Count == 1)
            {
                TraceResolver(trace, label, entityType, query, "partial_name", ReadString(partialMatches[0], idKey, ""), partialMatches.Select(x => ReadString(x, "name", ReadString(x, idKey, ""))).ToList());
                return ReadString(partialMatches[0], idKey, "");
            }

            if (partialMatches.Count > 1)
            {
                errors.Add("Ambiguous " + label + " '" + query + "': " + string.Join(", ", partialMatches.Take(6).Select(x => ReadString(x, "name", ReadString(x, idKey, "")))));
                TraceResolver(trace, label, entityType, query, "ambiguous_partial_name", "", partialMatches.Take(12).Select(x => ReadString(x, "name", ReadString(x, idKey, ""))).ToList());
                return string.Empty;
            }

            if (strictWhenIndexed)
            {
                errors.Add("Could not resolve " + label + " '" + query + "' from the current campaign index.");
                TraceResolver(trace, label, entityType, query, "not_found", "", new List<string>());
                return string.Empty;
            }

            TraceResolver(trace, label, entityType, query, "unresolved_passthrough", query, new List<string>());
            return query;
        }

        private static string ResolveAlias(Dictionary<string, object> index, string entityType, string query)
        {
            string normalized = NormalizeLookup(query);
            foreach (Dictionary<string, object> alias in ReadDictionaryList(index, "aliases"))
            {
                if (string.Equals(ReadString(alias, "entityType", ""), entityType, StringComparison.OrdinalIgnoreCase)
                    && NormalizeLookup(ReadString(alias, "alias", "")) == normalized)
                {
                    return ReadString(alias, "id", "");
                }
            }

            foreach (Dictionary<string, object> recent in ReadDictionaryList(index, "recentContext"))
            {
                if (string.Equals(ReadString(recent, "entityType", ""), entityType, StringComparison.OrdinalIgnoreCase)
                    && (NormalizeLookup(ReadString(recent, "label", "")) == normalized || NormalizeLookup(ReadString(recent, "name", "")) == normalized))
                {
                    return ReadString(recent, "id", "");
                }
            }

            return string.Empty;
        }

        private static string ResolveSemanticEntity(Dictionary<string, object> index, List<Dictionary<string, object>> entries, string collectionKey, string entityType, string normalizedQuery, string idKey, List<Dictionary<string, object>> trace, string label, string rawQuery)
        {
            if (entries == null || entries.Count == 0 || string.IsNullOrWhiteSpace(normalizedQuery))
            {
                return string.Empty;
            }

            if (collectionKey == "settlements")
            {
                bool wantsNearest = normalizedQuery.Contains("nearest") || normalizedQuery.Contains("closest");
                bool wantsFriendly = normalizedQuery.Contains("friendly") || normalizedQuery.Contains("our ");
                bool wantsEnemy = normalizedQuery.Contains("enemy") || normalizedQuery.Contains("hostile");
                string mentionedKingdomId = FindMentionedKingdomId(index, normalizedQuery);
                string wantedType = normalizedQuery.Contains("village") ? "village"
                    : normalizedQuery.Contains("castle") ? "castle"
                    : (normalizedQuery.Contains("town") || normalizedQuery.Contains("city")) ? "town"
                    : normalizedQuery.Contains("hideout") ? "hideout"
                    : string.Empty;

                if (wantsNearest || !string.IsNullOrWhiteSpace(wantedType) || !string.IsNullOrWhiteSpace(mentionedKingdomId))
                {
                    string playerKingdom = ResolveAlias(index, "kingdom", "player_kingdom");
                    IEnumerable<Dictionary<string, object>> filtered = entries;
                    if (!string.IsNullOrWhiteSpace(wantedType))
                    {
                        filtered = filtered.Where(x => string.Equals(ReadString(x, "type", ""), wantedType, StringComparison.OrdinalIgnoreCase));
                    }

                    if (!string.IsNullOrWhiteSpace(mentionedKingdomId))
                    {
                        filtered = filtered.Where(x => string.Equals(ReadString(x, "kingdomId", ""), mentionedKingdomId, StringComparison.OrdinalIgnoreCase)
                            || string.Equals(ReadString(x, "ownerKingdomId", ""), mentionedKingdomId, StringComparison.OrdinalIgnoreCase)
                            || string.Equals(ReadString(x, "mapFactionId", ""), mentionedKingdomId, StringComparison.OrdinalIgnoreCase));
                    }
                    else if (wantsFriendly && !string.IsNullOrWhiteSpace(playerKingdom))
                    {
                        filtered = filtered.Where(x => string.Equals(ReadString(x, "kingdomId", ""), playerKingdom, StringComparison.OrdinalIgnoreCase));
                    }
                    else if (wantsEnemy && !string.IsNullOrWhiteSpace(playerKingdom))
                    {
                        filtered = filtered.Where(x => !string.IsNullOrWhiteSpace(ReadString(x, "kingdomId", "")) && !string.Equals(ReadString(x, "kingdomId", ""), playerKingdom, StringComparison.OrdinalIgnoreCase));
                    }

                    Dictionary<string, object> best = filtered.OrderBy(x => ReadDouble(x, "distance", double.MaxValue)).FirstOrDefault();
                    if (best != null)
                    {
                        string resolved = ReadString(best, idKey, "");
                        TraceResolver(trace, label, entityType, rawQuery, "semantic", resolved, new List<string> { ReadString(best, "name", resolved) });
                        return resolved;
                    }
                }
            }

            if (collectionKey == "clans" && normalizedQuery.Contains("strongest"))
            {
                Dictionary<string, object> best = entries.OrderByDescending(x => ReadInt(x, "tier", 0)).ThenByDescending(x => ReadDouble(x, "renown", 0d)).FirstOrDefault();
                if (best != null)
                {
                    string resolved = ReadString(best, idKey, "");
                    TraceResolver(trace, label, entityType, rawQuery, "semantic", resolved, new List<string> { ReadString(best, "name", resolved) });
                    return resolved;
                }
            }

            return string.Empty;
        }

        private static string FindMentionedKingdomId(Dictionary<string, object> index, string normalizedQuery)
        {
            if (index == null || string.IsNullOrWhiteSpace(normalizedQuery))
            {
                return string.Empty;
            }

            List<string> matches = new List<string>();
            foreach (Dictionary<string, object> kingdom in ReadDictionaryList(index, "kingdoms"))
            {
                string id = ReadString(kingdom, "kingdomId", "");
                foreach (string alias in BuildKingdomLookupAliases(kingdom))
                {
                    if (NormalizedTextContainsPhrase(normalizedQuery, alias))
                    {
                        matches.Add(id);
                        break;
                    }
                }
            }

            List<string> unique = matches.Where(x => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
            return unique.Count == 1 ? unique[0] : string.Empty;
        }

        private static List<string> BuildKingdomLookupAliases(Dictionary<string, object> kingdom)
        {
            List<string> aliases = new List<string>();
            foreach (string key in new[] { "kingdomId", "name", "formalName", "informalName", "leaderName", "rulingClanName" })
            {
                AddKingdomAlias(aliases, ReadString(kingdom, key, ""));
            }

            string name = NormalizeLookup(ReadString(kingdom, "name", ""));
            if (!string.IsNullOrWhiteSpace(name))
            {
                AddKingdomAlias(aliases, name + "s");
                if (name.EndsWith("ia", StringComparison.OrdinalIgnoreCase))
                {
                    AddKingdomAlias(aliases, name + "n");
                    AddKingdomAlias(aliases, name + "ns");
                }
                else if (name.EndsWith("ait", StringComparison.OrdinalIgnoreCase))
                {
                    AddKingdomAlias(aliases, name + "s");
                }
            }

            return aliases.Where(x => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
        }

        private static void AddKingdomAlias(List<string> aliases, string value)
        {
            string normalized = NormalizeLookup(value);
            if (!string.IsNullOrWhiteSpace(normalized))
            {
                aliases.Add(normalized);
            }
        }

        private static bool NormalizedTextContainsPhrase(string normalizedText, string normalizedPhrase)
        {
            if (string.IsNullOrWhiteSpace(normalizedText) || string.IsNullOrWhiteSpace(normalizedPhrase))
            {
                return false;
            }

            if (string.Equals(normalizedText, normalizedPhrase, StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            return (" " + normalizedText + " ").Contains(" " + normalizedPhrase + " ");
        }

        private static void ResolveItemReference(Dictionary<string, object> index, Dictionary<string, object> raw, Dictionary<string, object> terms, List<Dictionary<string, object>> trace)
        {
            string itemQuery = FirstNonEmpty(ReadFirstString(raw, "Item", "item", "targetItem"), ReadFirstString(terms, "Item", "item", "targetItem"));
            if (string.IsNullOrWhiteSpace(itemQuery))
            {
                return;
            }

            List<Dictionary<string, object>> items = new List<Dictionary<string, object>>();
            Dictionary<string, object> assets = ReadDictionary(index, "assets") ?? new Dictionary<string, object>();
            foreach (string side in new[] { "player", "speaker" })
            {
                Dictionary<string, object> holder = ReadDictionary(assets, side) ?? new Dictionary<string, object>();
                Dictionary<string, object> inventory = ReadDictionary(holder, "inventory") ?? new Dictionary<string, object>();
                items.AddRange(ActionInventoryItems(inventory));
                Dictionary<string, object> appearance = ReadDictionary(holder, "appearance") ?? new Dictionary<string, object>();
                items.AddRange(ReadDictionaryList(appearance, "civilianEquipment"));
                items.AddRange(ReadDictionaryList(appearance, "battleEquipment"));
            }

            string normalized = NormalizeLookup(itemQuery);
            var exactMatches = items.Where(x => NormalizeLookup(ReadString(x, "itemId", "")) == normalized || NormalizeLookup(ReadString(x, "name", "")) == normalized).ToList();
            Dictionary<string, object> exact = exactMatches.FirstOrDefault();
            if (exactMatches.Select(x => ReadString(x, "itemId", "")).Distinct(StringComparer.OrdinalIgnoreCase).Count() > 1)
            {
                TraceResolver(trace, "item", "item", itemQuery, "ambiguous_item", "", exactMatches.Select(x => ReadString(x, "itemId", "")).ToList());
                return;
            }
            if (exact != null)
            {
                // Resolve the item type without silently choosing one of several
                // modifiers or equipped copies. Native ownership validates the copy.
                string id = ApplyResolvedItemTerms(terms, exactMatches.Count == 1 ? exact : TestDict("itemId", ReadString(exact, "itemId", "")));
                TraceResolver(trace, "item", "item", itemQuery, "exact_item", id, new List<string> { ReadString(exact, "name", id) });
                return;
            }

            Dictionary<string, object> semantic = ResolveSemanticItemReference(itemQuery, items);
            if (semantic != null)
            {
                string id = ApplyResolvedItemTerms(terms, semantic);
                TraceResolver(trace, "item", "item", itemQuery, "semantic_item", id, new List<string> { ReadString(semantic, "name", id) });
                return;
            }

            List<Dictionary<string, object>> partial = items.Where(x =>
            {
                string name = NormalizeLookup(ReadString(x, "name", ""));
                string id = NormalizeLookup(ReadString(x, "itemId", ""));
                return normalized.Length > 0
                    && ((name.Length > 0 && (name.Contains(normalized) || normalized.Contains(name)))
                        || (id.Length > 0 && (id.Contains(normalized) || normalized.Contains(id))));
            }).ToList();
            if (partial.Count == 1)
            {
                string id = ApplyResolvedItemTerms(terms, partial[0]);
                TraceResolver(trace, "item", "item", itemQuery, "partial_item", id, new List<string> { ReadString(partial[0], "name", id) });
            }
            else if (partial.Count > 1)
            {
                TraceResolver(trace, "item", "item", itemQuery, "ambiguous_item", "", partial.Take(12).Select(x => ReadString(x, "name", ReadString(x, "itemId", ""))).ToList());
            }
            else
            {
                TraceResolver(trace, "item", "item", itemQuery, "not_found", "", new List<string>());
            }
        }

        private static string ApplyResolvedItemTerms(Dictionary<string, object> terms, Dictionary<string, object> item)
        {
            if (item.ContainsKey("itemModifierId")) AddIfMissing(terms, "itemModifierId", ReadString(item, "itemModifierId", ""));
            string id = ReadString(item, "itemId", "");
            if (!string.IsNullOrWhiteSpace(id))
            {
                terms["itemId"] = id;
            }

            string slot = ReadString(item, "slot", "");
            if (!string.IsNullOrWhiteSpace(slot))
            {
                AddIfMissing(terms, "sourceEquipmentSlot", slot);
            }

            string equipmentSet = ReadString(item, "sourceEquipmentSet", "");
            if (!string.IsNullOrWhiteSpace(equipmentSet))
            {
                AddIfMissing(terms, "sourceEquipmentSet", equipmentSet);
            }

            return id;
        }

        private static Dictionary<string, object> ResolveSemanticItemReference(string itemQuery, List<Dictionary<string, object>> items)
        {
            string normalized = NormalizeLookup(itemQuery);
            if (items == null || items.Count == 0 || string.IsNullOrWhiteSpace(normalized))
            {
                return null;
            }

            IEnumerable<Dictionary<string, object>> candidates = Enumerable.Empty<Dictionary<string, object>>();
            if (normalized.Contains("armor") || normalized.Contains("armour") || normalized.Contains("clothing") || normalized.Contains("clothes"))
            {
                candidates = items.Where(x => ReadBool(x, "isArmorOrClothing", false));
            }
            else if (normalized.Contains("helmet") || normalized.Contains("head"))
            {
                candidates = items.Where(x => NormalizeLookup(ReadString(x, "slot", "")).Contains("head") || NormalizeLookup(ReadString(x, "name", "")).Contains("helmet"));
            }
            else if (normalized.Contains("boots") || normalized.Contains("shoe"))
            {
                candidates = items.Where(x => NormalizeLookup(ReadString(x, "slot", "")).Contains("leg") || NormalizeLookup(ReadString(x, "name", "")).Contains("boot"));
            }
            else if (normalized.Contains("gloves"))
            {
                candidates = items.Where(x => NormalizeLookup(ReadString(x, "slot", "")).Contains("glove") || NormalizeLookup(ReadString(x, "name", "")).Contains("glove"));
            }
            else if (normalized.Contains("cloak") || normalized.Contains("cape"))
            {
                candidates = items.Where(x => NormalizeLookup(ReadString(x, "slot", "")).Contains("cape") || NormalizeLookup(ReadString(x, "name", "")).Contains("cloak") || NormalizeLookup(ReadString(x, "name", "")).Contains("cape"));
            }
            else if (normalized.Contains("horse") || normalized.Contains("mount"))
            {
                candidates = items.Where(x => ReadBool(x, "isMount", false) || ReadBool(x, "isMountable", false));
            }
            else if (normalized.Contains("weapon"))
            {
                candidates = items.Where(x => ReadBool(x, "isWeapon", false));
            }
            else if (normalized.Contains("sword") || normalized.Contains("axe") || normalized.Contains("spear") || normalized.Contains("bow") || normalized.Contains("shield"))
            {
                candidates = items.Where(x =>
                {
                    string name = NormalizeLookup(ReadString(x, "name", "") + " " + ReadString(x, "itemId", "") + " " + ReadString(x, "type", ""));
                    return name.Contains(normalized) || normalized.Contains(name);
                });
            }

            var matches = candidates
                .Where(x => !string.IsNullOrWhiteSpace(ReadString(x, "itemId", "")))
                .ToList();
            // A category such as "armor" is not permission to take the most
            // valuable item or select an arbitrary modified/equipped copy.
            return matches.Count == 1 ? matches[0] : null;
        }

        private static string ResolveMentionedSettlement(Dictionary<string, object> index, string text, string targetKingdomId, List<string> errors, List<Dictionary<string, object>> trace)
        {
            string normalizedText = NormalizeLookup(text);
            if (string.IsNullOrWhiteSpace(normalizedText))
            {
                return string.Empty;
            }

            List<Dictionary<string, object>> matches = ReadDictionaryList(index, "settlements")
                .Where(x => string.IsNullOrWhiteSpace(targetKingdomId) || string.Equals(ReadString(x, "kingdomId", ""), targetKingdomId, StringComparison.OrdinalIgnoreCase))
                .Where(x =>
                {
                    string name = NormalizeLookup(ReadString(x, "name", ""));
                    return name.Length >= 3 && ContainsNormalizedPhrase(normalizedText, name);
                })
                .ToList();

            if (matches.Count == 1)
            {
                TraceResolver(trace, "mentioned settlement", "settlement", text, "mentioned_text", ReadString(matches[0], "settlementId", ""), new List<string> { ReadString(matches[0], "name", "") });
                return ReadString(matches[0], "settlementId", "");
            }

            if (matches.Count > 1)
            {
                errors.Add("Ambiguous settlement mention: " + string.Join(", ", matches.Take(6).Select(x => ReadString(x, "name", ReadString(x, "settlementId", "")))));
                TraceResolver(trace, "mentioned settlement", "settlement", text, "ambiguous_mentioned_text", "", matches.Take(12).Select(x => ReadString(x, "name", ReadString(x, "settlementId", ""))).ToList());
            }

            return string.Empty;
        }

        private static string NormalizeLookup(string value)
        {
            if (string.IsNullOrWhiteSpace(value))
            {
                return string.Empty;
            }

            string decomposed = value.Normalize(NormalizationForm.FormD);
            StringBuilder builder = new StringBuilder();
            bool previousSpace = false;
            foreach (char c in decomposed)
            {
                UnicodeCategory category = CharUnicodeInfo.GetUnicodeCategory(c);
                if (category == UnicodeCategory.NonSpacingMark)
                {
                    continue;
                }

                char lower = char.ToLowerInvariant(c);
                if (char.IsLetterOrDigit(lower))
                {
                    builder.Append(lower);
                    previousSpace = false;
                }
                else if (!previousSpace)
                {
                    builder.Append(' ');
                    previousSpace = true;
                }
            }

            return builder.ToString().Trim();
        }

        private static string InferCommandFromNaturalAction(Dictionary<string, object> raw, Dictionary<string, object> terms, Dictionary<string, object> payload, string resolutionText, List<Dictionary<string, object>> trace)
        {
            string text = string.Join(" ", new[]
            {
                ReadFirstString(raw, "proposal", "message_type", "messageType", "treaty", "treatyType", "SocialAction", "socialAction", "Policy", "policy", "Claim", "claim", "Promise", "promise"),
                ReadFirstString(terms, "proposal", "message_type", "messageType", "treaty", "treatyType", "SocialAction", "socialAction", "Policy", "policy", "Claim", "claim", "Promise", "promise"),
                resolutionText ?? string.Empty
            }).Trim();

            string normalized = NormalizeLookup(text);
            string command = string.Empty;
            string lowerText = (text ?? string.Empty).ToLowerInvariant();
            bool namedSettlementTrade = DirectiveHasAny(lowerText, "gold", "denar", "denars", "coin", "coins", "money", "silver", "price")
                && DirectiveHasAny(lowerText, " for ", "price", "trade", "sell", "sold", "buy", "purchase", "deal", "bargain", "in exchange", "pay", "payment")
                && !string.IsNullOrWhiteSpace(FindMentionedSettlementName(payload, text, ""));
            if (LooksLikePaidAssetTradeDirective(text) || namedSettlementTrade || ContainsAnyNormalized(normalized, "gold for", "denars for", "grain for", "horses for", "prisoner for", "settlement for", "town for", "castle for"))
            {
                command = "trade_package";
            }
            else if (ContainsAnyNormalized(normalized, "full surrender", "capitulation", "give all towns", "give all castles", "submit kingdom"))
            {
                command = "demand_surrender_peace";
            }
            else if (LooksLikeNavalAssetDirective(text))
            {
                command = "trade_package";
            }
            else if (LooksLikeSettlementTransferDirective(text) || ContainsAnyNormalized(normalized, "surrender town", "surrender city", "surrender castle"))
            {
                command = "demand_settlement_peace";
            }
            else if (ContainsAnyNormalized(normalized, "non aggression", "nonaggression", "do not attack", "no attack pact"))
            {
                command = "sign_non_aggression_pact";
            }
            else if (ContainsAnyNormalized(normalized, "defensive pact", "defend each other"))
            {
                command = "sign_defensive_pact";
            }
            else if (ContainsAnyNormalized(normalized, "alliance", "ally"))
            {
                command = "sign_alliance";
            }
            else if (ContainsAnyNormalized(normalized, "trade agreement", "trade treaty", "commerce pact"))
            {
                command = "sign_trade_agreement";
            }
            else if (ContainsAnyNormalized(normalized, "ransom", "gold for prisoner", "denars for prisoner"))
            {
                command = "ransom_package";
            }
            else if (ContainsAnyNormalized(normalized, "prisoner exchange", "exchange prisoners", "release prisoners"))
            {
                command = "exchange_prisoners";
            }
            else if (ContainsAnyNormalized(normalized, "reparations", "indemnity", "compensation"))
            {
                command = "demand_reparations_peace";
            }
            else if (ContainsAnyNormalized(normalized, "tribute"))
            {
                command = "offer_tribute_peace";
            }
            else if (ContainsAnyNormalized(normalized, "stop following", "break off the escort", "go your own way", "no need to trail", "trail us any longer"))
            {
                command = "stop_following";
            }
            else if (ContainsAnyNormalized(normalized, "follow on map", "follow in scene", "follow me", "follow us", "follow my party", "follow our party", "escort me", "escort us", "escort my party", "come with me", "walk with me", "stay by my side", "stay close", "walk after me", "stay behind our party", "keep to our route"))
            {
                command = "follow";
            }
            else if (ContainsAnyNormalized(normalized, "go to", "travel to", "ride to"))
            {
                command = "go_to_settlement";
            }
            else if (ContainsAnyNormalized(normalized, "patrol around", "patrol near"))
            {
                command = "patrol_around_settlement";
            }
            else if (ContainsAnyNormalized(normalized, "wait near", "wait outside"))
            {
                command = "wait_near_settlement";
            }
            else if (ContainsAnyNormalized(normalized, "raid village", "raid the village", "burn village") || (ContainsAnyNormalized(normalized, "raid") && ContainsAnyNormalized(normalized, "village")))
            {
                command = "raid_village";
            }
            else if (ContainsAnyNormalized(normalized, "besiege", "lay siege"))
            {
                command = "besiege_settlement";
            }
            else if (ContainsAnyNormalized(normalized, "create party", "raise a party", "make a new party"))
            {
                command = "create_party";
            }
            else if (ContainsAnyNormalized(normalized, "show the way", "guide me"))
            {
                command = "show_the_way";
            }
            else if (ContainsAnyNormalized(normalized, "attack player party", "attack my party"))
            {
                command = "attack_player_party";
            }
            else if (ContainsAnyNormalized(normalized, "attack party", "attack that party"))
            {
                command = "attack_party";
            }
            else if (ContainsAnyNormalized(normalized, "surrender to player", "surrender to me"))
            {
                command = "surrender_to_player";
            }
            else if (ContainsAnyNormalized(normalized, "leave player alone", "leave me alone"))
            {
                command = "leave_player_alone";
            }
            else if (ContainsAnyNormalized(normalized, "kill character", "execute"))
            {
                command = "kill_character";
            }
            else if (ContainsAnyNormalized(normalized, "duel player", "challenge me to a duel"))
            {
                command = "duel_player";
            }
            else if (ContainsAnyNormalized(normalized, "give gold", "give denars"))
            {
                command = "give_gold_to_player";
            }
            else if (ContainsAnyNormalized(normalized, "transfer gold", "transfer denars"))
            {
                command = "transfer_gold";
            }
            else if (ContainsAnyNormalized(normalized, "transfer item", "give item"))
            {
                command = "transfer_item";
            }
            else if (ContainsAnyNormalized(normalized, "transfer workshop", "give workshop"))
            {
                command = "transfer_workshop";
            }
            else if (ContainsAnyNormalized(normalized, "transfer prisoner", "release prisoner"))
            {
                command = "transfer_prisoner";
            }
            else if (ContainsAnyNormalized(normalized, "hire player as mercenary", "hire me as mercenary"))
            {
                command = "hire_player_as_mercenary";
            }
            else if (ContainsAnyNormalized(normalized, "dismiss player mercenary", "dismiss me as mercenary"))
            {
                command = "dismiss_player_mercenary";
            }
            else if (ContainsAnyNormalized(normalized, "offer player vassalage", "make me your vassal"))
            {
                command = "offer_player_vassalage";
            }
            else if (ContainsAnyNormalized(normalized, "dismiss player vassal", "release me from vassalage"))
            {
                command = "dismiss_player_vassal";
            }
            else if (ContainsAnyNormalized(normalized, "join clan"))
            {
                command = "join_clan";
            }
            else if (ContainsAnyNormalized(normalized, "leave clan"))
            {
                command = "leave_clan";
            }
            else if (ContainsAnyNormalized(normalized, "join kingdom", "join my kingdom"))
            {
                command = "join_kingdom";
            }
            else if (ContainsAnyNormalized(normalized, "leave kingdom"))
            {
                command = "leave_kingdom";
            }
            else if (ContainsAnyNormalized(normalized, "hire mercenary clan"))
            {
                command = "hire_mercenary_clan";
            }
            else if (ContainsAnyNormalized(normalized, "peace", "end the war", "settle hostilities", "cease fighting"))
            {
                command = "make_peace";
            }

            TraceResolver(trace, "command", "concept", text, string.IsNullOrWhiteSpace(command) ? "not_inferred" : "inferred", command, string.IsNullOrWhiteSpace(command) ? new List<string>() : new List<string> { command });
            return command;
        }

        private static bool HasDiplomaticPackageTerm(Dictionary<string, object> terms, Dictionary<string, object> record)
        {
            if (terms == null)
            {
                terms = new Dictionary<string, object>();
            }

            return ReadInt(terms, "gold", 0) > 0
                || ReadInt(terms, "GoldAmount", 0) > 0
                || ReadInt(terms, "reparationsGold", 0) > 0
                || ReadInt(terms, "dailyTribute", 0) > 0
                || !string.IsNullOrWhiteSpace(ReadFirstString(terms, "item", "itemId", "asset", "assetClass", "assetName", "prisonerHero", "prisonerHeroStringId", "targetHeroStringId", "treatyKind", "promiseText", "packageText", "targetSettlementStringId"))
                || !string.IsNullOrWhiteSpace(ReadFirstString(record, "targetSettlementStringId", "targetHeroStringId"))
                || ReadDictionaryList(terms, "items").Count > 0
                || ReadDictionaryList(terms, "itemTerms").Count > 0
                || ReadStringList(terms, "settlementIds").Count > 0;
        }

        private static bool HasTradePackageTerm(Dictionary<string, object> terms, Dictionary<string, object> record)
        {
            if (terms == null)
            {
                terms = new Dictionary<string, object>();
            }

            return ReadInt(terms, "gold", 0) > 0
                || ReadInt(terms, "GoldAmount", 0) > 0
                || ReadInt(terms, "shipCount", 0) > 0
                || ReadBool(terms, "allMatchingAssets", false)
                || !string.IsNullOrWhiteSpace(ReadFirstString(terms,
                    "item", "itemId", "asset", "assetClass", "assetName",
                    "prisonerHero", "prisonerHeroStringId",
                    "workshop", "workshopId",
                    "targetSettlementStringId", "packageText"))
                || !string.IsNullOrWhiteSpace(ReadFirstString(record, "targetSettlementStringId", "targetHeroStringId"))
                || ReadDictionaryList(terms, "items").Count > 0
                || ReadDictionaryList(terms, "itemTerms").Count > 0
                || ReadStringList(terms, "settlementIds").Count > 0;
        }

        private static bool ContainsAnyNormalized(string normalized, params string[] phrases)
        {
            if (string.IsNullOrWhiteSpace(normalized))
            {
                return false;
            }

            return phrases.Any(x => normalized.Contains(NormalizeLookup(x)));
        }

        private static void TraceResolver(List<Dictionary<string, object>> trace, string label, string entityType, string query, string status, string resolvedId, List<string> candidates)
        {
            if (trace == null)
            {
                return;
            }

            trace.Add(new Dictionary<string, object>
            {
                ["label"] = label ?? string.Empty,
                ["entityType"] = entityType ?? string.Empty,
                ["query"] = query ?? string.Empty,
                ["status"] = status ?? string.Empty,
                ["resolvedId"] = resolvedId ?? string.Empty,
                ["candidates"] = candidates ?? new List<string>()
            });
        }

        private static void LogResolverTrace(string campaignId, string command, string mappedType, Dictionary<string, object> raw, Dictionary<string, object> record, List<Dictionary<string, object>> trace, List<string> errors)
        {
            LogResolverTrace(campaignId, command, mappedType, raw, record, trace, errors, new List<string>());
        }

        private static void LogResolverTrace(string campaignId, string command, string mappedType, Dictionary<string, object> raw, Dictionary<string, object> record, List<Dictionary<string, object>> trace, List<string> errors, List<string> schemaWarnings)
        {
            string correlationId = FirstNonEmpty(ReadFirstString(record, "correlationId"), ReadFirstString(raw, "correlationId", "requestId", "clientRequestId"));
            string actionId = FirstNonEmpty(ReadFirstString(record, "actionId", "serverActionId"), ReadFirstString(raw, "actionId", "id", "serverActionId"));
            bool failed = errors != null && errors.Count > 0;
            LogOperational("resolver.action_normalize", new Dictionary<string, object>
            {
                ["campaignId"] = campaignId ?? string.Empty,
                ["correlationId"] = correlationId,
                ["command"] = command ?? string.Empty,
                ["mappedType"] = mappedType ?? string.Empty,
                ["rawAction"] = raw ?? new Dictionary<string, object>(),
                ["normalizedRecord"] = record ?? new Dictionary<string, object>(),
                ["trace"] = trace ?? new List<Dictionary<string, object>>(),
                ["errors"] = errors ?? new List<string>(),
                ["failureClass"] = failed ? ClassifyActionFailure(1, errors) : "",
                ["schemaWarnings"] = schemaWarnings ?? new List<string>()
            });
            WriteAudit(campaignId, correlationId, "server", "action", failed ? "action.validation_failed" : "action.normalized", ReadFirstString(record, "actorHeroStringId", "targetHeroStringId"), actionId, "", failed ? "failed" : "completed", 0, failed ? "Action failed schema or world validation." : "Action normalized and validated.", new Dictionary<string, object>
            {
                ["command"] = command ?? string.Empty,
                ["mappedType"] = mappedType ?? string.Empty,
                ["rawAction"] = raw ?? new Dictionary<string, object>(),
                ["normalizedRecord"] = record ?? new Dictionary<string, object>(),
                ["trace"] = trace ?? new List<Dictionary<string, object>>(),
                ["errors"] = errors ?? new List<string>(),
                ["failureClass"] = failed ? ClassifyActionFailure(1, errors) : "",
                ["schemaWarnings"] = schemaWarnings ?? new List<string>()
            });
        }

        private static void ValidateResolverIndexSchema(Dictionary<string, object> payload, List<string> errors, List<string> warnings, List<Dictionary<string, object>> trace)
        {
            Dictionary<string, object> index = ReadDictionary(payload, "actionResolutionIndex");
            if (index == null || index.Count == 0)
            {
                warnings.Add("actionResolutionIndex is missing; only exact IDs already present in the action can be trusted.");
                TraceResolver(trace, "schema.actionResolutionIndex", "schema", "", "missing", "", new List<string>());
                return;
            }

            string version = ReadString(index, "version", "");
            if (string.IsNullOrWhiteSpace(version))
            {
                warnings.Add("actionResolutionIndex.version is missing.");
            }

            ValidateResolverCollectionSchema(index, "settlements", "settlementId", "name", errors, warnings, trace, required: true);
            ValidateResolverCollectionSchema(index, "kingdoms", "kingdomId", "name", errors, warnings, trace, required: true);
            ValidateResolverCollectionSchema(index, "clans", "clanId", "name", errors, warnings, trace, required: true);
            ValidateResolverCollectionSchema(index, "heroes", "heroStringId", "name", errors, warnings, trace, required: false);
            ValidateResolverCollectionSchema(index, "parties", "partyId", "name", errors, warnings, trace, required: false);
            ValidateResolverCollectionSchema(index, "armies", "armyId", "name", errors, warnings, trace, required: false);
            ValidateResolverCollectionSchema(index, "workshops", "workshopId", "name", errors, warnings, trace, required: false);

            int aliasCount = ReadDictionaryList(index, "aliases").Count;
            if (aliasCount == 0)
            {
                warnings.Add("actionResolutionIndex.aliases is empty; context references like player, speaker, this city, and current settlement may not resolve.");
            }

            Dictionary<string, object> assets = ReadDictionary(index, "assets");
            if (assets == null || assets.Count == 0)
            {
                warnings.Add("actionResolutionIndex.assets is missing; item, prisoner, and gold package validation will be limited.");
            }

            TraceResolver(trace, "schema.actionResolutionIndex", "schema", version, errors.Count == 0 ? "checked" : "schema_errors", version, new List<string>
            {
                "settlements=" + ReadDictionaryList(index, "settlements").Count,
                "kingdoms=" + ReadDictionaryList(index, "kingdoms").Count,
                "clans=" + ReadDictionaryList(index, "clans").Count,
                "heroes=" + ReadDictionaryList(index, "heroes").Count,
                "parties=" + ReadDictionaryList(index, "parties").Count,
                "armies=" + ReadDictionaryList(index, "armies").Count,
                "workshops=" + ReadDictionaryList(index, "workshops").Count
            });
        }

        private static void ValidateResolverCollectionSchema(Dictionary<string, object> index, string collectionKey, string idKey, string nameKey, List<string> errors, List<string> warnings, List<Dictionary<string, object>> trace, bool required)
        {
            List<Dictionary<string, object>> rows = ReadDictionaryList(index, collectionKey);
            if (rows.Count == 0)
            {
                string message = "actionResolutionIndex." + collectionKey + " is empty.";
                if (required)
                {
                    errors.Add(message);
                }
                else
                {
                    warnings.Add(message);
                }

                TraceResolver(trace, "schema." + collectionKey, "schema", "", "empty", "", new List<string>());
                return;
            }

            HashSet<string> ids = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            int missingIds = 0;
            int duplicateIds = 0;
            int missingNames = 0;
            foreach (Dictionary<string, object> row in rows)
            {
                string id = ReadString(row, idKey, "");
                if (string.IsNullOrWhiteSpace(id))
                {
                    missingIds++;
                }
                else if (!ids.Add(id))
                {
                    duplicateIds++;
                }

                if (string.IsNullOrWhiteSpace(ReadString(row, nameKey, "")))
                {
                    missingNames++;
                }
            }

            if (missingIds > 0)
            {
                errors.Add("actionResolutionIndex." + collectionKey + " has " + missingIds + " entries missing " + idKey + ".");
            }

            if (duplicateIds > 0)
            {
                warnings.Add("actionResolutionIndex." + collectionKey + " has " + duplicateIds + " duplicate " + idKey + " entries.");
            }

            if (missingNames > 0)
            {
                warnings.Add("actionResolutionIndex." + collectionKey + " has " + missingNames + " entries missing " + nameKey + ".");
            }
        }

        private static void ValidateActionPayloadSchema(Dictionary<string, object> raw, Dictionary<string, object> terms, string mappedType, Dictionary<string, object> record, List<string> errors, List<string> warnings)
        {
            if (record == null)
            {
                errors.Add("Normalized action record is missing.");
                return;
            }

            if (string.IsNullOrWhiteSpace(ReadString(record, "actionId", "")))
            {
                errors.Add("actionId is required after normalization.");
            }

            if (string.IsNullOrWhiteSpace(ReadString(record, "command", "")))
            {
                errors.Add("command is required after normalization.");
            }

            if (string.IsNullOrWhiteSpace(mappedType))
            {
                errors.Add("type mapping is required after normalization.");
            }

            if (ReadString(record, "reason", "").Length > 2000)
            {
                warnings.Add("Action reason is longer than 2000 characters and may be hard to read in logs.");
            }

            if (ReadString(record, "termsJson", "").Length > 12000)
            {
                errors.Add("termsJson is too large for a compact world action.");
            }

            int maxAttempts = ReadInt(record, "maxAttempts", 3);
            if (maxAttempts < 1 || maxAttempts > 72)
            {
                errors.Add("maxAttempts must be between 1 and 72.");
            }

            int desiredStrength = ReadInt(record, "desiredStrength", 350);
            if (desiredStrength < 0 || desiredStrength > 50000)
            {
                errors.Add("desiredStrength is outside the allowed range 0..50000.");
            }

            int minimumTroops = ReadInt(record, "minimumTroops", 40);
            if (minimumTroops < 0 || minimumTroops > 10000)
            {
                errors.Add("minimumTroops is outside the allowed range 0..10000.");
            }

            double executeAfterDays = ReadDouble(record, "executeAfterDays", 0d);
            if (executeAfterDays < 0d || executeAfterDays > 3650d)
            {
                errors.Add("executeAfterDays must be between 0 and 3650.");
            }

            foreach (string key in new[] { "actorHeroStringId", "targetHeroStringId", "actorKingdomStringId", "targetKingdomStringId", "actorClanStringId", "targetClanStringId", "targetSettlementStringId" })
            {
                string value = ReadString(record, key, "");
                if (value.Length > 160)
                {
                    errors.Add(key + " is too long to be a Bannerlord StringId.");
                }
            }

            if (terms != null)
            {
                foreach (string key in terms.Keys.ToList())
                {
                    if (string.IsNullOrWhiteSpace(key))
                    {
                        errors.Add("terms contains an empty key.");
                    }
                    else if (key.Length > 80)
                    {
                        warnings.Add("terms key is unusually long: " + key);
                    }
                }
            }
        }

        private static Dictionary<string, object> NormalizeActionCommand(Dictionary<string, object> raw, string campaignId, out List<string> errors, Dictionary<string, object> payload = null, string resolutionText = "")
        {
            raw = FlattenActionFields(raw ?? new Dictionary<string, object>());
            errors = new List<string>();
            string correlationId = FirstNonEmpty(ReadFirstString(raw, "correlationId", "requestId", "clientRequestId"), ReadFirstString(payload, "correlationId", "requestId", "clientRequestId"));
            if (string.IsNullOrWhiteSpace(correlationId))
            {
                correlationId = "action-" + Guid.NewGuid().ToString("N");
            }

            raw["correlationId"] = correlationId;
            List<string> schemaWarnings = new List<string>();
            Dictionary<string, object> terms = ToCaseInsensitiveDictionary(ReadDictionary(raw, "terms") ?? new Dictionary<string, object>());
            NormalizeChatAiTerms(raw, terms);
            CopyCampaignCommandTerms(raw, terms);
            List<Dictionary<string, object>> resolverTrace = new List<Dictionary<string, object>>();
            ValidateResolverIndexSchema(payload, errors, schemaWarnings, resolverTrace);
            string command = CanonicalCommand(ReadFirstString(raw, "command", "action", "commandType", "intent", "type"));
            if (string.IsNullOrWhiteSpace(command) || string.IsNullOrWhiteSpace(MapCommandToActionType(command)))
            {
                command = CanonicalCommand(InferCommandFromNaturalAction(raw, terms, payload, resolutionText, resolverTrace));
            }

            string mappedType = MapCommandToActionType(command);
            if (string.IsNullOrWhiteSpace(mappedType))
            {
                errors.Add("Unsupported action command: " + (string.IsNullOrWhiteSpace(command) ? "<missing>" : command));
                LogResolverTrace(campaignId, command, mappedType, raw, null, resolverTrace, errors, schemaWarnings);
                return null;
            }

            string actionId = ReadFirstString(raw, "actionId", "id", "serverActionId");
            if (string.IsNullOrWhiteSpace(actionId))
            {
                actionId = Guid.NewGuid().ToString("N");
            }

            if (string.Equals(command, "trade_package", StringComparison.OrdinalIgnoreCase))
            {
                Dictionary<string, object> hero = ReadDictionary(payload, "hero") ?? new Dictionary<string, object>();
                ApplyPaidAssetPackageTerms(raw, terms, payload, hero, resolutionText);
            }

            if (string.Equals(command, "ransom_package", StringComparison.OrdinalIgnoreCase))
            {
                Dictionary<string, object> hero = ReadDictionary(payload, "hero") ?? new Dictionary<string, object>();
                ApplyRansomPackageTerms(raw, terms, payload, hero, resolutionText);
            }

            if (string.Equals(command, "diplomatic_package", StringComparison.OrdinalIgnoreCase))
            {
                Dictionary<string, object> hero = ReadDictionary(payload, "hero") ?? new Dictionary<string, object>();
                ApplyCompoundDiplomaticPackageTerms(raw, terms, payload, hero, resolutionText);
            }

            if (string.Equals(command, "transfer_gold", StringComparison.OrdinalIgnoreCase)
                || string.Equals(command, "transfer_item", StringComparison.OrdinalIgnoreCase)
                || string.Equals(command, "give_gold_to_player", StringComparison.OrdinalIgnoreCase))
            {
                bool needsDirection = string.Equals(command, "give_gold_to_player", StringComparison.OrdinalIgnoreCase)
                    || string.IsNullOrWhiteSpace(FirstNonEmpty(ReadFirstString(raw, "FromHero", "fromHero", "actorHeroStringId", "actorHeroId"), ReadFirstString(terms, "FromHero", "fromHero", "fromHeroStringId", "actorHeroStringId", "actorHeroId")))
                    || string.IsNullOrWhiteSpace(FirstNonEmpty(ReadFirstString(raw, "ToHero", "toHero", "targetHeroStringId", "targetHeroId", "TargetHero"), ReadFirstString(terms, "ToHero", "toHero", "toHeroStringId", "targetHeroStringId", "targetHeroId", "TargetHero")));
                if (needsDirection)
                {
                    Dictionary<string, object> hero = ReadDictionary(payload, "hero") ?? new Dictionary<string, object>();
                    ApplyTransferDirectionDefaults(raw, terms, payload, hero, resolutionText, command);
                }
            }

            ApplyTemporaryPartyGuestActorBinding(raw, terms, payload,
                ReadDictionary(payload, "hero") ?? new Dictionary<string, object>(), command);
            BindAndValidateResidentAgreement(raw, terms, payload, resolutionText, command, errors);
            BindAndValidateClanAccord(raw, terms, payload, resolutionText, command, errors);
            ResolveActionReferences(raw, terms, payload, resolutionText, command, errors, resolverTrace);
            BindDialogueMarriageParticipants(raw, terms, payload, command, errors);
            ValidateGovernmentPaymentOwnership(raw, terms, command, errors);
            string termsJson = terms == null ? ReadString(raw, "termsJson", "") : Json.Serialize(terms);
            Dictionary<string, object> record = new Dictionary<string, object>
            {
                ["actionId"] = actionId,
                ["serverActionId"] = actionId,
                ["correlationId"] = correlationId,
                ["campaignId"] = campaignId,
                ["command"] = command,
                ["type"] = mappedType,
                ["source"] = ReadString(raw, "source", "server_llm_or_manual"),
                ["actorHeroStringId"] = ReadFirstString(raw, "actorHeroStringId", "actorHeroId", "leaderHeroId", "heroId", "FromHero"),
                ["actorKingdomStringId"] = ReadFirstString(raw, "actorKingdomStringId", "actorKingdomId", "kingdomId"),
                ["targetHeroStringId"] = ReadFirstString(raw, "targetHeroStringId", "targetHeroId", "TargetHero", "ToHero", "PrisonerHero"),
                ["actorClanStringId"] = ReadFirstString(raw, "actorClanStringId", "actorClanId", "claimantClanId"),
                ["targetClanStringId"] = ReadFirstString(raw, "targetClanStringId", "targetClanId", "TargetClan"),
                ["supporterClanIdsCsv"] = ReadSupporterClanIds(raw, terms),
                ["targetKingdomStringId"] = ReadFirstString(raw, "targetKingdomStringId", "targetKingdomId", "TargetKingdom"),
                ["targetSettlementStringId"] = ReadFirstString(raw, "targetSettlementStringId", "targetSettlementId", "settlementId", "TargetSettlement"),
                ["reason"] = ReadString(raw, "reason", "AI world action from Bannerlord Reign server."),
                ["termsJson"] = termsJson,
                ["minimumTroops"] = ReadInt(raw, "minimumTroops", 40),
                ["desiredStrength"] = ReadInt(raw, "desiredStrength", 350),
                ["maxAttempts"] = ReadInt(raw, "maxAttempts", mappedType == "StrategyCaptureSettlement" ? 24 : 3),
                ["executeAfterDays"] = ReadDouble(raw, "executeAfterDays", 0d),
                ["requiresAcceptance"] = ReadBool(raw, "requiresAcceptance", false)
                ,["authorizationMode"] = ReadFirstString(raw, "authorizationMode")
                ,["negotiationId"] = ReadFirstString(raw, "negotiationId")
                ,["termsHash"] = ReadFirstString(raw, "termsHash")
                ,["executionPhase"] = ReadString(raw, "executionPhase", "idle")
                ,["executionSnapshotJson"] = ReadString(raw, "executionSnapshotJson", "{}")
                ,["acceptedByHeroStringId"] = ReadFirstString(raw, "acceptedByHeroStringId")
            };

            if (string.Equals(command, "issue_campaign_order", StringComparison.OrdinalIgnoreCase)
                && !ReadBool(raw, "requiresAcceptance", false)
                && (ReadString(raw, "source", "").IndexOf("dialogue", StringComparison.OrdinalIgnoreCase) >= 0
                    || ReadString(raw, "source", "").IndexOf("correspondence", StringComparison.OrdinalIgnoreCase) >= 0))
            {
                record["authorizationMode"] = "accepted_recommendation";
                record["acceptedByHeroStringId"] = ReadString(record, "actorHeroStringId", "");
            }

            if (mappedType.StartsWith("Diplomacy", StringComparison.OrdinalIgnoreCase))
            {
                Require(record, "actorKingdomStringId", errors);
                Require(record, "targetKingdomStringId", errors);
                if ((mappedType == "DiplomacyDemandSettlementPeace" || mappedType == "DiplomacyDemandSurrenderPeace" || mappedType == "DiplomacyReturnOccupiedSettlement") && string.IsNullOrWhiteSpace(ReadString(record, "targetSettlementStringId", "")))
                {
                    string firstSettlement = FirstStringFromTerms(terms, "settlementIds");
                    if (!string.IsNullOrWhiteSpace(firstSettlement))
                    {
                        record["targetSettlementStringId"] = firstSettlement;
                    }
                }

                if (mappedType == "DiplomacyDemandSettlementPeace" && string.IsNullOrWhiteSpace(ReadString(record, "targetSettlementStringId", "")))
                {
                    errors.Add("targetSettlementStringId or terms.settlementIds is required for settlement surrender.");
                }
                if (mappedType == "DiplomacyDemandSurrenderPeace" && string.IsNullOrWhiteSpace(ReadString(record, "targetSettlementStringId", "")) && ReadStringList(terms, "settlementIds").Count == 0 && !ReadBool(terms, "allTargetFortifications", false))
                {
                    terms["allTargetFortifications"] = true;
                    record["termsJson"] = Json.Serialize(terms);
                }
                if (mappedType == "DiplomacyReturnOccupiedSettlement" && string.IsNullOrWhiteSpace(ReadString(record, "targetSettlementStringId", "")))
                {
                    errors.Add("targetSettlementStringId is required for return occupied settlement.");
                }
                if (mappedType == "DiplomacyPayToJoinWar" && string.IsNullOrWhiteSpace(FirstNonEmpty(ReadString(terms, "enemyKingdomId", ""), ReadString(terms, "thirdKingdomId", ""))))
                {
                    errors.Add("terms.enemyKingdomId is required for pay to join war.");
                }
                if (mappedType == "DiplomacyPackage" && !HasDiplomaticPackageTerm(terms, record))
                {
                    errors.Add("Diplomatic package requires at least one resolved term: gold, item, prisoner, settlement, treaty, or promise.");
                }
            }
            else if (mappedType.StartsWith("Politics", StringComparison.OrdinalIgnoreCase))
            {
                Require(record, "actorKingdomStringId", errors);
                if (mappedType == "PoliticsResolveCivilWar")
                {
                    Require(record, "targetKingdomStringId", errors);
                    if (!string.Equals(ReadString(record, "authorizationMode", ""), "negotiated", StringComparison.OrdinalIgnoreCase)) errors.Add("resolve_civil_war requires authorizationMode=negotiated.");
                    Require(record, "negotiationId", errors);
                    Require(record, "termsHash", errors);
                    string politicalResult = ReadString(terms, "politicalResult", "");
                    if (politicalResult == "recognized_independence")
                    {
                        Require(terms, "movementId", errors);
                        Require(terms, "rebelKingdomId", errors);
                        Require(terms, "parentKingdomId", errors);
                        if (!string.Equals(ReadString(record,
                                "actorKingdomStringId", ""),
                                ReadString(terms, "rebelKingdomId", ""),
                                StringComparison.OrdinalIgnoreCase)
                            || !string.Equals(ReadString(record,
                                "targetKingdomStringId", ""),
                                ReadString(terms, "parentKingdomId", ""),
                                StringComparison.OrdinalIgnoreCase))
                            errors.Add("recognized_independence must name the rebel realm as actor and its exact parent realm as target.");
                    }
                    if (politicalResult != "recognized_independence")
                        errors.Add("resolve_civil_war permits only safeguarded recognized_independence; ordinary civil-war peace is disabled.");
                }
                else if (mappedType == "PoliticsConsentGovernmentReduction")
                {
                    Require(record, "actorHeroStringId", errors);
                    Require(record, "targetHeroStringId", errors);
                    if (!ReadBool(terms, "consentConfirmed", false))
                        errors.Add("terms.consentConfirmed must be true for government-reduction consent.");
                }
                else
                {
                    Require(record, "actorClanStringId", errors);
                    if (mappedType == "PoliticsRecruitLordToRebellion" || mappedType == "PoliticsJoinRebellion")
                    {
                        Require(record, "actorHeroStringId", errors);
                        Require(record, "targetHeroStringId", errors);
                    }
                    else if (mappedType == "PoliticsStartRulingClanRebellion")
                    {
                        Require(record, "actorHeroStringId", errors);
                        Require(record, "targetHeroStringId", errors);
                    }
                    else if (mappedType == "PoliticsSurrenderRebellion")
                    {
                        Require(record, "actorHeroStringId", errors);
                    }
                }
            }
            else if (mappedType.StartsWith("Strategy", StringComparison.OrdinalIgnoreCase))
            {
                Require(record, "actorHeroStringId", errors);
                Require(record, "targetSettlementStringId", errors);
            }
            else if (mappedType.StartsWith("Regular", StringComparison.OrdinalIgnoreCase))
            {
                ValidateRegularRecordRequirements(command, record, terms, errors);
            }

            BindDialogueSettlementAuthorization(record, terms, payload, command, mappedType,
                correlationId, errors);
            BindDialogueActionAuthority(record, terms, payload, command, mappedType,
                correlationId, errors, raw);

            if (string.IsNullOrWhiteSpace(ReadString(record, "reason", "")))
            {
                errors.Add("Action reason is required.");
            }

            ValidateActionPayloadSchema(raw, terms, mappedType, record, errors, schemaWarnings);
            LogResolverTrace(campaignId, command, mappedType, raw, record, resolverTrace, errors, schemaWarnings);
            return errors.Count == 0 ? record : null;
        }

        private static void BindDialogueSettlementAuthorization(
            Dictionary<string, object> record,
            Dictionary<string, object> terms,
            Dictionary<string, object> payload,
            string command,
            string mappedType,
            string correlationId,
            List<string> errors)
        {
            string source = ReadString(record, "source", "");
            if (!IsDialogueActionSource(source)
                || !IsSettlementTransferAction(mappedType, record, terms))
            {
                return;
            }

            Dictionary<string, object> hero = ReadDictionary(payload, "hero")
                ?? new Dictionary<string, object>();
            string acceptedByHeroId = FirstNonEmpty(
                ReadFirstString(payload, "speakerHeroStringId", "heroStringId", "heroId"),
                ReadString(hero, "heroStringId", ""));
            string playerHeroId = ReadString(payload, "playerHeroStringId", "");
            Dictionary<string, object> index = ReadDictionary(payload, "actionResolutionIndex")
                ?? new Dictionary<string, object>();
            if (string.IsNullOrWhiteSpace(acceptedByHeroId)
                || string.IsNullOrWhiteSpace(playerHeroId))
            {
                errors.Add("Dialogue settlement transfer requires exact speaker and player hero IDs.");
                return;
            }
            if (index.Count == 0)
            {
                errors.Add("Dialogue settlement transfer requires the live action resolution index.");
                return;
            }

            if (string.Equals(mappedType, "RegularTradePackage", StringComparison.OrdinalIgnoreCase))
            {
                BindDialogueSettlementTradeAuthority(record, terms, index, acceptedByHeroId,
                    playerHeroId, errors);
            }
            else
            {
                BindDialogueKingdomSettlementAuthority(record, terms, index, mappedType,
                    acceptedByHeroId, playerHeroId, errors);
            }

            if (errors.Count > 0)
            {
                return;
            }

            record["acceptedByHeroStringId"] = acceptedByHeroId;
            record["authorizationMode"] = "dialogue_acceptance";
            record["negotiationId"] = correlationId;
            record["termsJson"] = Json.Serialize(terms);
            record["termsHash"] = ComputeActionTermsHash(command, terms);
        }

        private static void BindDialogueSettlementTradeAuthority(
            Dictionary<string, object> record,
            Dictionary<string, object> terms,
            Dictionary<string, object> index,
            string acceptedByHeroId,
            string playerHeroId,
            List<string> errors)
        {
            List<string> settlementIds = ReadStringList(terms, "settlementIds");
            string targetSettlementId = ReadString(record, "targetSettlementStringId", "");
            if (!string.IsNullOrWhiteSpace(targetSettlementId)
                && !settlementIds.Contains(targetSettlementId, StringComparer.OrdinalIgnoreCase))
            {
                settlementIds.Insert(0, targetSettlementId);
            }
            settlementIds = settlementIds.Where(x => !string.IsNullOrWhiteSpace(x))
                .Distinct(StringComparer.OrdinalIgnoreCase).ToList();
            if (settlementIds.Count == 0)
            {
                errors.Add("Dialogue settlement trade requires at least one resolved town or castle.");
                return;
            }

            string recipientHeroId = FirstNonEmpty(
                ReadFirstString(terms, "settlementToHeroStringId", "toHeroStringId"),
                ReadString(record, "targetHeroStringId", ""));
            string ownerHeroId;
            if (string.Equals(recipientHeroId, playerHeroId, StringComparison.OrdinalIgnoreCase))
            {
                ownerHeroId = acceptedByHeroId;
            }
            else if (string.Equals(recipientHeroId, acceptedByHeroId, StringComparison.OrdinalIgnoreCase))
            {
                ownerHeroId = playerHeroId;
            }
            else
            {
                errors.Add("Dialogue settlement trade recipient must be the player or the agreeing NPC.");
                return;
            }

            string ownerClanId = "";
            foreach (string settlementId in settlementIds)
            {
                Dictionary<string, object> settlement = FindIndexedRow(index, "settlements",
                    "settlementId", settlementId);
                string currentOwnerClanId = ReadString(settlement, "ownerClanId", "");
                Dictionary<string, object> ownerClan = FindIndexedRow(index, "clans", "clanId",
                    currentOwnerClanId);
                string currentOwnerLeaderId = ReadString(ownerClan, "leaderHeroStringId", "");
                if (settlement == null || string.IsNullOrWhiteSpace(currentOwnerClanId)
                    || string.IsNullOrWhiteSpace(currentOwnerLeaderId))
                {
                    errors.Add("Settlement authority could not be resolved for " + settlementId + ".");
                    continue;
                }
                if (!string.Equals(currentOwnerLeaderId, ownerHeroId,
                    StringComparison.OrdinalIgnoreCase))
                {
                    errors.Add("Only the current owner-clan leader may transfer settlement "
                        + settlementId + " in a voluntary trade.");
                    continue;
                }
                if (!string.IsNullOrWhiteSpace(ownerClanId)
                    && !string.Equals(ownerClanId, currentOwnerClanId,
                        StringComparison.OrdinalIgnoreCase))
                {
                    errors.Add("A single settlement trade cannot combine fiefs owned by different clans.");
                    continue;
                }
                ownerClanId = currentOwnerClanId;
            }
            if (errors.Count > 0)
            {
                return;
            }

            record["actorHeroStringId"] = ownerHeroId;
            record["actorClanStringId"] = ownerClanId;
            terms["settlementFromHeroStringId"] = ownerHeroId;
            terms["settlementFromClanStringId"] = ownerClanId;
            terms["settlementToHeroStringId"] = recipientHeroId;
            terms["settlementAuthorizingHeroStringId"] = ownerHeroId;
            terms["settlementAuthorityKind"] = "owner_clan_leader";
        }

        private static void BindDialogueKingdomSettlementAuthority(
            Dictionary<string, object> record,
            Dictionary<string, object> terms,
            Dictionary<string, object> index,
            string mappedType,
            string acceptedByHeroId,
            string playerHeroId,
            List<string> errors)
        {
            string actorKingdomId = ReadString(record, "actorKingdomStringId", "");
            string targetKingdomId = ReadString(record, "targetKingdomStringId", "");
            Dictionary<string, object> actorKingdom = FindIndexedRow(index, "kingdoms",
                "kingdomId", actorKingdomId);
            Dictionary<string, object> targetKingdom = FindIndexedRow(index, "kingdoms",
                "kingdomId", targetKingdomId);
            string actorLeaderId = ReadString(actorKingdom, "leaderHeroStringId", "");
            string targetLeaderId = ReadString(targetKingdom, "leaderHeroStringId", "");
            bool exactRulerPair = (string.Equals(actorLeaderId, playerHeroId,
                    StringComparison.OrdinalIgnoreCase)
                    && string.Equals(targetLeaderId, acceptedByHeroId,
                        StringComparison.OrdinalIgnoreCase))
                || (string.Equals(actorLeaderId, acceptedByHeroId,
                    StringComparison.OrdinalIgnoreCase)
                    && string.Equals(targetLeaderId, playerHeroId,
                        StringComparison.OrdinalIgnoreCase));
            if (!exactRulerPair)
            {
                errors.Add("Kingdom settlement transfers require the player and agreeing NPC to be the current rulers of the two realms.");
                return;
            }

            string sourceKingdomId;
            if (string.Equals(mappedType, "DiplomacyReturnOccupiedSettlement",
                StringComparison.OrdinalIgnoreCase))
            {
                sourceKingdomId = actorKingdomId;
            }
            else if (string.Equals(mappedType, "DiplomacyPackage",
                StringComparison.OrdinalIgnoreCase))
            {
                sourceKingdomId = ReadString(terms, "settlementFromKingdomId",
                    targetKingdomId);
            }
            else
            {
                sourceKingdomId = targetKingdomId;
            }
            Dictionary<string, object> sourceKingdom = FindIndexedRow(index, "kingdoms",
                "kingdomId", sourceKingdomId);
            string sourceLeaderId = ReadString(sourceKingdom, "leaderHeroStringId", "");
            if (sourceKingdom == null
                || (!string.Equals(sourceLeaderId, acceptedByHeroId,
                        StringComparison.OrdinalIgnoreCase)
                    && !string.Equals(sourceLeaderId, playerHeroId,
                        StringComparison.OrdinalIgnoreCase)))
            {
                errors.Add("The settlement source kingdom has no participating ruler authority.");
                return;
            }

            terms["settlementFromKingdomId"] = sourceKingdomId;
            terms["settlementAuthorizingHeroStringId"] = sourceLeaderId;
            terms["settlementAuthorityKind"] = "kingdom_ruler";
        }

        private static bool IsSettlementTransferAction(string mappedType,
            Dictionary<string, object> record, Dictionary<string, object> terms)
        {
            if (string.Equals(mappedType, "DiplomacyDemandSettlementPeace",
                    StringComparison.OrdinalIgnoreCase)
                || string.Equals(mappedType, "DiplomacyDemandSurrenderPeace",
                    StringComparison.OrdinalIgnoreCase)
                || string.Equals(mappedType, "DiplomacyReturnOccupiedSettlement",
                    StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
            if (!string.Equals(mappedType, "RegularTradePackage",
                    StringComparison.OrdinalIgnoreCase)
                && !string.Equals(mappedType, "DiplomacyPackage",
                    StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }
            return !string.IsNullOrWhiteSpace(ReadString(record,
                    "targetSettlementStringId", ""))
                || ReadStringList(terms, "settlementIds").Count > 0
                || !string.IsNullOrWhiteSpace(ReadString(terms,
                    "targetSettlementStringId", ""));
        }

        private static bool IsDialogueActionSource(string source)
        {
            source = source ?? "";
            return source.IndexOf("dialogue", StringComparison.OrdinalIgnoreCase) >= 0
                || string.Equals(source, "hidden_action_planner",
                    StringComparison.OrdinalIgnoreCase)
                || string.Equals(source, "test_lab_action_gate",
                    StringComparison.OrdinalIgnoreCase);
        }

        private static Dictionary<string, object> FindIndexedRow(
            Dictionary<string, object> index, string collectionKey, string idKey, string id)
        {
            if (string.IsNullOrWhiteSpace(id))
            {
                return null;
            }
            return ReadDictionaryList(index, collectionKey).FirstOrDefault(row =>
                string.Equals(ReadString(row, idKey, ""), id,
                    StringComparison.OrdinalIgnoreCase));
        }

        private static string ComputeActionTermsHash(string command,
            Dictionary<string, object> terms)
        {
            Dictionary<string, object> hashTerms = new Dictionary<string, object>(
                StringComparer.OrdinalIgnoreCase);
            foreach (KeyValuePair<string, object> pair in terms
                ?? new Dictionary<string, object>())
            {
                if (!string.Equals(pair.Key, "authorizationMode",
                        StringComparison.OrdinalIgnoreCase)
                    && !string.Equals(pair.Key, "negotiationId",
                        StringComparison.OrdinalIgnoreCase)
                    && !string.Equals(pair.Key, "termsHash",
                        StringComparison.OrdinalIgnoreCase))
                {
                    hashTerms[pair.Key] = pair.Value;
                }
            }
            string input = (command ?? "") + "|" + CanonicalActionTerms(hashTerms);
            using (SHA256 sha = SHA256.Create())
            {
                return string.Concat(sha.ComputeHash(Encoding.UTF8.GetBytes(input))
                    .Select(x => x.ToString("x2", CultureInfo.InvariantCulture)));
            }
        }

        private static string CanonicalActionTerms(object value)
        {
            Dictionary<string, object> dictionary = value as Dictionary<string, object>;
            if (dictionary != null)
            {
                return "{" + string.Join(",", dictionary.OrderBy(x => x.Key,
                    StringComparer.Ordinal).Select(x => QuoteCanonicalJsonString(x.Key) + ":"
                    + CanonicalActionTerms(x.Value))) + "}";
            }
            IDictionary genericDictionary = value as IDictionary;
            if (genericDictionary != null)
            {
                List<KeyValuePair<string, object>> pairs = new List<KeyValuePair<string, object>>();
                foreach (DictionaryEntry entry in genericDictionary)
                {
                    pairs.Add(new KeyValuePair<string, object>(Convert.ToString(entry.Key,
                        CultureInfo.InvariantCulture), entry.Value));
                }
                return "{" + string.Join(",", pairs.OrderBy(x => x.Key,
                    StringComparer.Ordinal).Select(x => QuoteCanonicalJsonString(x.Key) + ":"
                    + CanonicalActionTerms(x.Value))) + "}";
            }
            if (value is IEnumerable enumerable && !(value is string))
            {
                List<string> items = new List<string>();
                foreach (object item in enumerable)
                {
                    items.Add(CanonicalActionTerms(item));
                }
                return "[" + string.Join(",", items) + "]";
            }
            if (value is string stringValue)
            {
                return QuoteCanonicalJsonString(stringValue);
            }
            return value == null ? "null" : Json.Serialize(value);
        }

        private static string QuoteCanonicalJsonString(string value)
        {
            StringBuilder result = new StringBuilder((value?.Length ?? 0) + 2);
            result.Append('"');
            foreach (char ch in value ?? "")
            {
                switch (ch)
                {
                    case '"': result.Append("\\\""); break;
                    case '\\': result.Append("\\\\"); break;
                    case '\b': result.Append("\\b"); break;
                    case '\f': result.Append("\\f"); break;
                    case '\n': result.Append("\\n"); break;
                    case '\r': result.Append("\\r"); break;
                    case '\t': result.Append("\\t"); break;
                    default:
                        if (ch < ' ')
                        {
                            result.Append("\\u");
                            result.Append(((int)ch).ToString("x4",
                                CultureInfo.InvariantCulture));
                        }
                        else
                        {
                            result.Append(ch);
                        }
                        break;
                }
            }
            result.Append('"');
            return result.ToString();
        }

        private static void ValidateRegularRecordRequirements(string command, Dictionary<string, object> record, Dictionary<string, object> terms, List<string> errors)
        {
            switch (CanonicalCommand(command))
            {
                case "create_clan_accord":
                case "cancel_clan_accord":
                    Require(record, "actorHeroStringId", errors); Require(record, "targetHeroStringId", errors);
                    if (!ReadBool(terms, "playerConfirmed", false)) errors.Add("Clan Accords require explicit player acceptance.");
                    if (CanonicalCommand(command) == "create_clan_accord")
                    {
                        if (!ReadBool(terms, "consentConfirmed", false)) errors.Add("Clan Accords require explicit NPC acceptance.");
                        if (!Enum.TryParse(ReadString(terms, "accordType", ""), true, out Reign.Core.Contracts.ClanAccords.ClanAccordType accordType)
                            || !Reign.Core.Contracts.ClanAccords.ClanAccordLedger.IsSupportedType(accordType)) errors.Add("Unsupported clan accord type.");
                    }
                    else if (!ValidClanAccordId(ReadString(terms, "accordId", ""))) errors.Add("An active accordId is required.");
                    return;
                case "recruit_encountered_resident":
                    Require(record, "actorHeroStringId", errors);
                    if (!ReadBool(terms, "consentConfirmed", false) || ReadString(terms, "agreementKind", "") != "permanent"
                        || !terms.ContainsKey("agreedGold") || ReadInt(terms, "agreedGold", -1) < 0)
                        errors.Add("Resident recruitment requires permanent agreement, verified consent and exact nonnegative agreedGold.");
                    return;
                case "release_resident_from_duty":
                    Require(record, "actorHeroStringId", errors); Require(record, "targetHeroStringId", errors);
                    if (!ReadBool(terms, "releaseConfirmed", false)) errors.Add("An explicit authorized duty release is required.");
                    return;
                case "issue_campaign_order":
                    Require(record, "actorHeroStringId", errors);
                    if (string.IsNullOrWhiteSpace(ReadString(terms, "objective", ""))
                        && ReadDictionaryList(terms, "steps").Count == 0)
                        errors.Add("terms.steps or terms.objective is required for issue_campaign_order.");
                    return;
                case "revise_campaign_order":
                case "cancel_campaign_order":
                    if (string.IsNullOrWhiteSpace(ReadString(terms, "orderId", "")))
                        errors.Add("terms.orderId is required for " + command + ".");
                    return;
                case "respond_to_order_report":
                    if (string.IsNullOrWhiteSpace(ReadString(terms, "orderId", "")))
                        errors.Add("terms.orderId is required for respond_to_order_report.");
                    if (string.IsNullOrWhiteSpace(ReadString(terms, "response", "")))
                        errors.Add("terms.response is required for respond_to_order_report.");
                    return;
                case "accept_temporary_party_guest":
                case "renew_temporary_party_guest":
                    Require(record, "actorHeroStringId", errors);
                    if (!ReadBool(terms, "consentConfirmed", false))
                        errors.Add("terms.consentConfirmed must be true for a temporary guest agreement or renewal.");
                    if (string.IsNullOrWhiteSpace(ReadString(terms, "purpose", "")))
                        errors.Add("terms.purpose is required for a temporary guest agreement.");
                    NormalizeTemporaryGuestTermKind(terms, errors);
                    ValidateGuestServiceTerms(terms, errors);
                    return;
                case "end_temporary_party_guest":
                    Require(record, "actorHeroStringId", errors);
                    return;
                case "acknowledge_own_faction_combat_risk":
                    Require(record, "actorHeroStringId", errors);
                    if (!ReadBool(terms, "consentConfirmed", false))
                        errors.Add("terms.consentConfirmed must be true to accept own-faction combat banishment risk.");
                    return;
                case "trade_package":
                    if (!HasTradePackageTerm(terms, record))
                    {
                        errors.Add("Trade package requires at least one resolved value term: gold, item, prisoner, settlement, workshop, ship, or package text with asset details.");
                    }
                    return;
                case "follow":
                case "attack_party":
                    Require(record, "actorHeroStringId", errors);
                    if (string.IsNullOrWhiteSpace(ReadString(record, "targetHeroStringId", "")) && string.IsNullOrWhiteSpace(ReadString(terms, "targetPartyId", "")))
                    {
                        errors.Add("TargetHero or terms.targetPartyId is required.");
                    }
                    return;
                case "go_to_settlement":
                case "patrol_around_settlement":
                case "wait_near_settlement":
                case "raid_village":
                case "besiege_settlement":
                    Require(record, "actorHeroStringId", errors);
                    Require(record, "targetSettlementStringId", errors);
                    return;
                case "stop_following":
                case "attack_player_party":
                case "surrender_to_player":
                case "leave_player_alone":
                case "show_the_way":
                case "duel_player":
                case "create_party":
                    Require(record, "actorHeroStringId", errors);
                    return;
                case "prepare_arrest":
                    Require(record, "actorHeroStringId", errors);
                    Require(record, "targetHeroStringId", errors);
                    if (string.IsNullOrWhiteSpace(ReadFirstString(terms, "accusation")))
                        errors.Add("terms.accusation is required for prepare_arrest.");
                    return;
                case "confirm_arrest":
                case "release_arrested_character":
                case "rescind_arrest_accusation":
                case "player_attack_party":
                    Require(record, "actorHeroStringId", errors);
                    Require(record, "targetHeroStringId", errors);
                    if (string.IsNullOrWhiteSpace(ReadFirstString(terms, "caseId")))
                        errors.Add("terms.caseId is required for " + command + ".");
                    return;
                case "kill_character":
                    Require(record, "actorHeroStringId", errors);
                    Require(record, "targetHeroStringId", errors);
                    return;
                case "give_gold_to_player":
                    Require(record, "actorHeroStringId", errors);
                    RequirePositiveTerm(terms, "gold", "GoldAmount", errors);
                    return;
                case "transfer_gold":
                    RequirePositiveTerm(terms, "gold", "GoldAmount", errors);
                    if (string.IsNullOrWhiteSpace(ReadString(terms, "fromHeroStringId", "")) && string.IsNullOrWhiteSpace(ReadString(record, "actorHeroStringId", "")))
                    {
                        errors.Add("FromHero or actorHeroStringId is required for transfer_gold.");
                    }
                    if (string.IsNullOrWhiteSpace(ReadString(terms, "toHeroStringId", "")) && string.IsNullOrWhiteSpace(ReadString(record, "targetHeroStringId", "")))
                    {
                        errors.Add("ToHero or targetHeroStringId is required for transfer_gold.");
                    }
                    return;
                case "transfer_item":
                    if (string.IsNullOrWhiteSpace(ReadString(terms, "fromHeroStringId", "")) && string.IsNullOrWhiteSpace(ReadString(record, "actorHeroStringId", "")))
                    {
                        errors.Add("FromHero or actorHeroStringId is required for transfer_item.");
                    }
                    if (string.IsNullOrWhiteSpace(ReadString(terms, "toHeroStringId", "")) && string.IsNullOrWhiteSpace(ReadString(record, "targetHeroStringId", "")))
                    {
                        errors.Add("ToHero or targetHeroStringId is required for transfer_item.");
                    }
                    if (string.IsNullOrWhiteSpace(ReadFirstString(terms, "itemId", "item")))
                    {
                        errors.Add("Item is required for transfer_item.");
                    }
                    RequirePositiveTerm(terms, "amount", "Amount", errors);
                    return;
                case "transfer_workshop":
                    if (string.IsNullOrWhiteSpace(ReadFirstString(terms, "workshopId", "workshop")))
                    {
                        errors.Add("Workshop is required for transfer_workshop.");
                    }
                    if (string.IsNullOrWhiteSpace(ReadString(terms, "toHeroStringId", "")) && string.IsNullOrWhiteSpace(ReadString(record, "targetHeroStringId", "")))
                    {
                        errors.Add("ToHero or TargetHero is required for transfer_workshop.");
                    }
                    return;
                case "transfer_prisoner":
                    if (string.IsNullOrWhiteSpace(ReadFirstString(terms, "prisonerHeroStringId", "prisonerHero")) && string.IsNullOrWhiteSpace(ReadString(record, "targetHeroStringId", "")))
                    {
                        errors.Add("PrisonerHero is required for transfer_prisoner.");
                    }
                    return;
                case "hire_player_as_mercenary":
                case "offer_player_vassalage":
                    if (string.IsNullOrWhiteSpace(ReadString(record, "targetKingdomStringId", "")) && string.IsNullOrWhiteSpace(ReadString(record, "actorKingdomStringId", "")))
                    {
                        errors.Add("targetKingdomStringId or actorKingdomStringId is required.");
                    }
                    return;
                case "join_kingdom":
                    if (string.IsNullOrWhiteSpace(ReadString(record, "actorClanStringId", "")) && string.IsNullOrWhiteSpace(ReadString(record, "actorHeroStringId", "")))
                    {
                        errors.Add("actorClanStringId or actorHeroStringId is required.");
                    }
                    Require(record, "targetKingdomStringId", errors);
                    return;
                case "leave_kingdom":
                    if (string.IsNullOrWhiteSpace(ReadString(record, "actorClanStringId", "")) && string.IsNullOrWhiteSpace(ReadString(record, "actorHeroStringId", "")))
                    {
                        errors.Add("actorClanStringId or actorHeroStringId is required.");
                    }
                    return;
                case "hire_mercenary_clan":
                    if (string.IsNullOrWhiteSpace(ReadString(record, "targetClanStringId", "")) && string.IsNullOrWhiteSpace(ReadString(record, "actorClanStringId", "")))
                    {
                        errors.Add("targetClanStringId or actorClanStringId is required.");
                    }
                    if (string.IsNullOrWhiteSpace(ReadString(record, "targetKingdomStringId", "")) && string.IsNullOrWhiteSpace(ReadString(record, "actorKingdomStringId", "")))
                    {
                        errors.Add("targetKingdomStringId or actorKingdomStringId is required.");
                    }
                    return;
                case "dismiss_player_mercenary":
                case "dismiss_player_vassal":
                case "join_clan":
                case "leave_clan":
                    return;
            }
        }

        private static void NormalizeTemporaryGuestTermKind(
            Dictionary<string, object> terms, List<string> errors)
        {
            string raw = ReadString(terms, "termKind", string.Empty)
                .Trim().ToLowerInvariant().Replace('-', '_').Replace(' ', '_');
            double duration = ReadDouble(terms, "durationDays", 0d);
            if (raw == "fixed" || raw == "fixed_term")
            {
                terms["termKind"] = "fixed";
                if (double.IsNaN(duration) || double.IsInfinity(duration) || duration < 1d || duration > MaximumGuestTermDays)
                    errors.Add("A fixed temporary guest term must be 1 through 126 campaign days, preserving fractional seasons.");
                return;
            }
            if (raw == "open_ended" || raw == "openended" || raw == "open")
            {
                terms["termKind"] = "open_ended";
                terms["reviewIntervalDays"] = 5;
                terms.Remove("durationDays");
                return;
            }

            // The dialogue model can confuse the noble's social role (for example,
            // "independent ally") with the schedule enum. A bounded explicit day
            // count is authoritative evidence of a fixed term, so canonicalize that
            // narrow mistake without weakening the consent gate.
            bool socialRoleLabel = raw == "independent_ally" || raw == "ally" ||
                raw == "companion" || raw == "retainer" || raw == "partner" || raw == "guest";
            if (socialRoleLabel && duration >= 1d && duration <= MaximumGuestTermDays)
            {
                terms["termKind"] = "fixed";
                return;
            }
            errors.Add("terms.termKind must be fixed or open_ended for a temporary guest agreement.");
        }

        private static void RequirePositiveTerm(Dictionary<string, object> terms, string primaryKey, string aliasKey, List<string> errors)
        {
            int value = Math.Max(ReadInt(terms, primaryKey, 0), ReadInt(terms, aliasKey, 0));
            if (value <= 0)
            {
                errors.Add(primaryKey + " must be positive.");
            }
        }

        private static Dictionary<string, object> QueueAction(string campaignId, Dictionary<string, object> record)
        {
            string id = ReadString(record, "serverActionId", Guid.NewGuid().ToString("N"));
            string correlationId = ReadString(record, "correlationId", "");
            Dictionary<string, object> row = new Dictionary<string, object>
            {
                ["id"] = id,
                ["ts"] = DateTimeOffset.UtcNow.ToUnixTimeSeconds(),
                ["campaignId"] = campaignId,
                ["correlationId"] = correlationId,
                ["status"] = "queued",
                ["command"] = ReadString(record, "command", ""),
                ["record"] = record
            };

            lock (FileLock)
            {
                List<Dictionary<string, object>> queue = ReadActionQueueUnlocked(campaignId);
                queue.RemoveAll(x => ReadString(x, "id", "") == id);
                queue.Add(row);
                if (queue.Count > 500)
                {
                    queue = queue.Skip(queue.Count - 500).ToList();
                }

                WriteActionQueueUnlocked(campaignId, queue);
                AppendJsonLineToPath(CampaignFile(campaignId, "actions", "actions.jsonl"), row);
            }

            WriteAudit(campaignId, correlationId, "server", "action", "action.queued", ReadFirstString(record, "actorHeroStringId", "targetHeroStringId"), id, "", "queued", 0, "Action queued for game execution.", new Dictionary<string, object>
            {
                ["row"] = row
            });
            return row;
        }

        private static Dictionary<string, object> NextActions(Dictionary<string, object> payload, Dictionary<string, string> query)
        {
            payload = payload ?? new Dictionary<string, object>();
            query = query ?? new Dictionary<string, string>();
            string campaignId = query.TryGetValue("campaignId", out string campaignQuery) ? campaignQuery : ReadString(payload, "campaignId", "default");
            int limit = query.TryGetValue("limit", out string limitText) && int.TryParse(limitText, out int parsedLimit) ? parsedLimit : ReadInt(payload, "limit", 10);
            limit = Math.Max(1, Math.Min(50, limit));
            List<Dictionary<string, object>> selected = new List<Dictionary<string, object>>();
            long nowTs = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
            const long deliveryMaxAgeSeconds = 6 * 60 * 60;

            lock (FileLock)
            {
                List<Dictionary<string, object>> queue = ReadActionQueueUnlocked(campaignId);
                foreach (Dictionary<string, object> row in queue)
                {
                    string status = ReadString(row, "status", "queued");
                    if (selected.Count >= limit)
                    {
                        break;
                    }

                    if (!ReadString(row, "campaignId", "default").Equals(campaignId, StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    if (!status.Equals("queued", StringComparison.OrdinalIgnoreCase) && !status.Equals("proposed", StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    long queuedTs = ReadLong(row, "ts", 0);
                    if (queuedTs > 0 && nowTs - queuedTs > deliveryMaxAgeSeconds)
                    {
                        row["status"] = "expired";
                        row["expiredTs"] = nowTs;
                        row["expiryReason"] = "Undelivered action exceeded the six-hour delivery window.";
                        continue;
                    }

                    row["status"] = "delivered";
                    row["deliveredTs"] = nowTs;
                    selected.Add(row);
                }

                WriteActionQueueUnlocked(campaignId, queue);
            }

            List<object> records = selected.Select(x => x.ContainsKey("record") ? x["record"] : x).ToList();
            LogOperational("action.next", new Dictionary<string, object> { ["campaignId"] = campaignId, ["count"] = records.Count });
            foreach (Dictionary<string, object> row in selected)
            {
                Dictionary<string, object> record = ReadDictionary(row, "record") ?? row;
                WriteAudit(campaignId, FirstNonEmpty(ReadString(row, "correlationId", ""), ReadString(record, "correlationId", "")), "server", "action", "action.delivered", ReadFirstString(record, "actorHeroStringId", "targetHeroStringId"), ReadString(row, "id", ReadString(record, "serverActionId", "")), "", "delivered", 0, "Action delivered to game client.", new Dictionary<string, object>
                {
                    ["row"] = row
                });
            }
            return new Dictionary<string, object>
            {
                ["ok"] = true,
                ["campaignId"] = campaignId,
                ["count"] = records.Count,
                ["actions"] = records
            };
        }

        private static Dictionary<string, object> ReportAction(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            string campaignId = ReadString(payload, "campaignId", "default");
            string id = ReadFirstString(payload, "serverActionId", "actionId", "id");
            string reportedStatus = ReadString(payload, "status", "reported");
            string status = reportedStatus;
            string correlationId = ReadFirstString(payload, "correlationId", "requestId", "clientRequestId");
            Dictionary<string, object> matchedRecord = new Dictionary<string, object>();
            if (string.IsNullOrWhiteSpace(id))
            {
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "serverActionId/actionId is required." };
            }

            bool found = false;
            bool ignoredStatusRegression = false;
            string authoritativeStatus = status;
            lock (FileLock)
            {
                List<Dictionary<string, object>> queue = ReadActionQueueUnlocked(campaignId);
                foreach (Dictionary<string, object> row in queue)
                {
                    if (ReadString(row, "id", "") == id)
                    {
                        matchedRecord = ReadDictionary(row, "record") ?? new Dictionary<string, object>();
                        correlationId = FirstNonEmpty(correlationId, ReadString(row, "correlationId", ""), ReadString(matchedRecord, "correlationId", ""));
                        status = NormalizeActionReportStatus(matchedRecord, payload,
                            reportedStatus);
                        authoritativeStatus = status;
                        if (IsResolvedNpcGovernmentRefusal(matchedRecord, payload, reportedStatus))
                        {
                            payload = new Dictionary<string, object>(payload,
                                StringComparer.OrdinalIgnoreCase)
                            {
                                ["status"] = status,
                                ["reportedStatus"] = reportedStatus,
                                ["statusNormalization"] =
                                    "resolved_npc_government_refusal"
                            };
                        }
                        string currentStatus = ReadString(row, "status", "");
                        bool legacyRefusalCorrection = IsLegacyGovernmentRefusalCorrection(
                            row, matchedRecord, payload, reportedStatus);
                        if (legacyRefusalCorrection)
                            payload["statusCorrection"] = "legacy_government_refusal";
                        if (ShouldAcceptActionStatusTransition(currentStatus, status)
                            || legacyRefusalCorrection)
                        {
                            row["status"] = status;
                            row["reportTs"] = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
                            row["report"] = payload;
                        }
                        else
                        {
                            authoritativeStatus = currentStatus;
                            ignoredStatusRegression = true;
                        }
                        found = true;
                        break;
                    }
                }

                WriteActionQueueUnlocked(campaignId, queue);
                AppendJsonLineToPath(CampaignFile(campaignId, "actions", "actions.jsonl"), new Dictionary<string, object>
                {
                    ["id"] = id,
                    ["ts"] = DateTimeOffset.UtcNow.ToUnixTimeSeconds(),
                    ["campaignId"] = campaignId,
                    ["status"] = status,
                    ["report"] = payload
                });
            }

            correlationId = FirstNonEmpty(correlationId, ReadFirstString(ReadDictionary(payload, "result"), "correlationId"));
            LogOperational("action.report", new Dictionary<string, object> { ["campaignId"] = campaignId, ["correlationId"] = correlationId, ["id"] = id, ["status"] = status, ["reportedStatus"] = reportedStatus, ["found"] = found });
            Dictionary<string, object> result = ReadDictionary(payload, "result") ?? new Dictionary<string, object>();
            List<string> reportErrors = new List<string>();
            string debugMessage = ReadFirstString(result, "debugMessage", "DebugMessage", "message", "Message");
            if (!string.IsNullOrWhiteSpace(debugMessage))
            {
                reportErrors.Add(debugMessage);
            }

            WriteAudit(campaignId, correlationId, "game_client", "action", "action.execution_report", ReadFirstString(payload, "actorHeroStringId", "targetHeroStringId"), id, "", status, 0, "Game client reported action execution result.", new Dictionary<string, object>
            {
                ["found"] = found,
                ["authoritativeStatus"] = authoritativeStatus,
                ["reportedStatus"] = reportedStatus,
                ["ignoredStatusRegression"] = ignoredStatusRegression,
                ["record"] = matchedRecord,
                ["report"] = payload,
                ["result"] = result,
                ["failureClass"] = status.Equals("failed", StringComparison.OrdinalIgnoreCase) ? ClassifyActionFailure(1, reportErrors) : ""
            });
            if (ignoredStatusRegression)
            {
                return new Dictionary<string, object>
                {
                    ["ok"] = true,
                    ["campaignId"] = campaignId,
                    ["correlationId"] = correlationId,
                    ["id"] = id,
                    ["status"] = authoritativeStatus,
                    ["reportedStatus"] = reportedStatus,
                    ["found"] = found,
                    ["ignoredStatusRegression"] = true
                };
            }
            Dictionary<string, object> memoryStore = StoreActionResultMemory(payload, "actions_report");
            List<Dictionary<string, object>> nativeRelationChanges = EvaluateCompletedActionRelationships(payload);
            UpdateDiplomaticEventForAction(campaignId, id, status, payload);
            UpdateNegotiationFromActionReport(campaignId, id, status, payload);
            UpdateRebellionBackingFromActionReport(campaignId, id, status, payload);
            Dictionary<string, object> ambassadorReceiptPayload = new Dictionary<string, object>(payload, StringComparer.OrdinalIgnoreCase)
            {
                ["record"] = matchedRecord ?? new Dictionary<string, object>()
            };
            UpdateAmbassadorReferralActionReceipt(campaignId, ambassadorReceiptPayload, status);
            return new Dictionary<string, object> { ["ok"] = true, ["campaignId"] = campaignId, ["correlationId"] = correlationId, ["id"] = id, ["status"] = status, ["reportedStatus"] = reportedStatus, ["found"] = found, ["memoryStore"] = memoryStore, ["nativeRelationChanges"] = nativeRelationChanges };
        }

        private static string NormalizeActionReportStatus(
            Dictionary<string, object> record,
            Dictionary<string, object> payload,
            string reportedStatus)
        {
            return IsResolvedNpcGovernmentRefusal(record, payload, reportedStatus)
                ? "rejected" : reportedStatus;
        }

        private static bool IsResolvedNpcGovernmentRefusal(
            Dictionary<string, object> record,
            Dictionary<string, object> payload,
            string reportedStatus)
        {
            if (!string.Equals(reportedStatus, "failed", StringComparison.OrdinalIgnoreCase)
                && !string.Equals(reportedStatus, "rejected", StringComparison.OrdinalIgnoreCase)) return false;
            string source = FirstNonEmpty(ReadString(record, "source", ""),
                ReadString(payload, "source", ""));
            if (!source.Equals("world_diplomacy_director",
                StringComparison.OrdinalIgnoreCase)) return false;
            Dictionary<string, object> result = ReadDictionary(payload, "result")
                ?? new Dictionary<string, object>();
            string resultCode = ReadFirstString(result, "resultCode", "ResultCode");
            string failureKind = ReadFirstString(result, "failureKind", "FailureKind");
            return failureKind.Equals("government_authority",
                       StringComparison.OrdinalIgnoreCase)
                && result.Keys.Any(key => key.Equals("retryable",
                    StringComparison.OrdinalIgnoreCase))
                && !ReadBool(result, "retryable", true)
                && (IsRecordedGovernmentRefusalResult(result)
                    || resultCode.Equals("government_pressure_prevailed",
                        StringComparison.OrdinalIgnoreCase)
                    || resultCode.Equals("government_level_five_block",
                        StringComparison.OrdinalIgnoreCase));
        }

        private static bool IsRecordedGovernmentRefusalResult(Dictionary<string, object> result)
        {
            var diagnostics = ReadDictionaryList(result, "diagnostics");
            Func<string, string> value = key => ReadString(diagnostics.FirstOrDefault(x =>
                ReadString(x, "key", "").Equals(key, StringComparison.Ordinal)), "value", "");
            return ReadString(result, "resultCode", "") == "government_authorization_refused"
                && !ReadBool(result, "success", true) && ReadBool(result, "completed", false)
                && !ReadBool(result, "retryable", true)
                && ReadDictionaryList(result, "effects").Count == 0
                && ReadDictionaryList(result, "changedEntities").Count == 0
                && !string.IsNullOrWhiteSpace(value("governmentBusinessId"))
                && Reign.Core.Contracts.Government.GovernmentBusinessRules.IsRecordedAuthorizationRefusal(
                    value("governmentStatus"), value("governmentExecutedOptionId"));
        }

        private static bool IsLegacyGovernmentRefusalCorrection(Dictionary<string, object> row,
            Dictionary<string, object> record, Dictionary<string, object> payload, string reportedStatus)
        {
            var oldResult = ReadDictionary(ReadDictionary(row, "report"), "result")
                ?? new Dictionary<string, object>();
            var result = ReadDictionary(payload, "result") ?? new Dictionary<string, object>();
            return ReadString(row, "status", "") == "failed"
                && reportedStatus.Equals("rejected", StringComparison.OrdinalIgnoreCase)
                && ReadString(oldResult, "resultCode", "") == "government_refused"
                && ReadString(oldResult, "failureKind", "") == "government_authority"
                && !ReadBool(oldResult, "success", true) && !ReadBool(oldResult, "completed", true)
                && ReadDictionaryList(oldResult, "effects").Count == 0
                && ReadDictionaryList(oldResult, "changedEntities").Count == 0
                && IsRecordedGovernmentRefusalResult(result)
                && IsResolvedNpcGovernmentRefusal(record, payload, reportedStatus);
        }

        private static bool ShouldAcceptActionStatusTransition(string currentStatus, string incomingStatus)
        {
            string current = NormalizeLookup(currentStatus).Replace(' ', '_');
            string incoming = NormalizeLookup(incomingStatus).Replace(' ', '_');
            if (string.IsNullOrWhiteSpace(current)) return true;
            if (string.Equals(current, incoming, StringComparison.OrdinalIgnoreCase)) return true;
            if (IsTerminalActionReportStatus(current)) return false;
            return ActionReportStatusRank(incoming) >= ActionReportStatusRank(current);
        }

        private static bool IsTerminalActionReportStatus(string status)
        {
            string normalized = NormalizeLookup(status).Replace(' ', '_');
            return new[]
            {
                "completed", "failed", "rejected", "cancelled", "canceled",
                "expired", "blocked", "invalid", "obsolete"
            }.Contains(normalized, StringComparer.OrdinalIgnoreCase);
        }

        private static int ActionReportStatusRank(string status)
        {
            string normalized = NormalizeLookup(status).Replace(' ', '_');
            if (IsTerminalActionReportStatus(normalized)) return 3;
            if (new[] { "executing", "retry", "in_progress" }
                .Contains(normalized, StringComparer.OrdinalIgnoreCase)) return 2;
            if (new[]
                {
                    "accepted", "delivered", "enqueued", "enqueued_immediate",
                    "queued", "pending", "proposed"
                }.Contains(normalized, StringComparer.OrdinalIgnoreCase)) return 1;
            return 0;
        }

        private static Dictionary<string, object> ActionFailures(Dictionary<string, object> payload, Dictionary<string, string> query)
        {
            payload = payload ?? new Dictionary<string, object>();
            query = query ?? new Dictionary<string, string>();
            string campaignId = query.TryGetValue("campaignId", out string campaignQuery) ? campaignQuery : ReadString(payload, "campaignId", LatestCampaignId());
            int limit = query.TryGetValue("limit", out string limitText) && int.TryParse(limitText, out int parsedLimit) ? parsedLimit : ReadInt(payload, "limit", 50);
            limit = Math.Max(1, Math.Min(200, limit));
            List<Dictionary<string, object>> rows = ReadJsonLinesFromPath(CampaignFile(campaignId, "audit", "audit.jsonl"))
                .Where(x =>
                {
                    string phase = ReadString(x, "phase", "");
                    string status = ReadString(x, "status", "");
                    return phase.IndexOf("action.", StringComparison.OrdinalIgnoreCase) >= 0
                        && (status.Equals("failed", StringComparison.OrdinalIgnoreCase)
                            || phase.Equals("action.validation_failed", StringComparison.OrdinalIgnoreCase));
                })
                .Reverse()
                .Take(limit)
                .Select(x =>
                {
                    Dictionary<string, object> data = ReadDictionary(x, "data") ?? new Dictionary<string, object>();
                    List<string> errors = ReadStringList(data, "errors");
                    if (errors.Count == 0)
                    {
                        errors = ReadStringList(ReadDictionary(data, "report"), "errors");
                    }

                    Dictionary<string, object> record = ReadDictionary(data, "normalizedRecord") ?? ReadDictionary(data, "record") ?? new Dictionary<string, object>();
                    string command = FirstNonEmpty(ReadString(data, "command", ""), ReadString(record, "command", ""));
                    return new Dictionary<string, object>
                    {
                        ["timestamp"] = ReadString(x, "timestamp", ""),
                        ["correlationId"] = ReadString(x, "correlationId", ""),
                        ["phase"] = ReadString(x, "phase", ""),
                        ["status"] = ReadString(x, "status", ""),
                        ["command"] = command,
                        ["capability"] = ActionCapabilityForCommand(command),
                        ["failureClass"] = FirstNonEmpty(ReadString(data, "failureClass", ""), ClassifyActionFailure(1, errors)),
                        ["summary"] = ReadString(x, "summary", ""),
                        ["errors"] = errors,
                        ["trace"] = ReadDictionaryList(data, "trace"),
                        ["rawAction"] = ReadDictionary(data, "rawAction") ?? new Dictionary<string, object>(),
                        ["normalizedRecord"] = record
                    };
                })
                .ToList();

            return new Dictionary<string, object>
            {
                ["ok"] = true,
                ["campaignId"] = campaignId,
                ["count"] = rows.Count,
                ["failures"] = rows
            };
        }

        private static List<Dictionary<string, object>> ReadActionQueueUnlocked(string campaignId)
        {
            string path = CampaignFile(campaignId, "actions", "action-queue.json");
            if (!File.Exists(path))
            {
                string legacyPath = Path.Combine(DataDir, "action-queue.json");
                if (!File.Exists(legacyPath))
                {
                    return new List<Dictionary<string, object>>();
                }

                return ReconcileActionQueueTerminalReceiptsUnlocked(campaignId,
                    ReadActionQueueFromPath(legacyPath)
                    .Where(x => ReadString(x, "campaignId", "default").Equals(campaignId, StringComparison.OrdinalIgnoreCase))
                    .ToList(), false);
            }

            return ReconcileActionQueueTerminalReceiptsUnlocked(
                campaignId, ReadActionQueueFromPath(path), true);
        }

        private static List<Dictionary<string, object>> ReconcileActionQueueTerminalReceiptsUnlocked(
            string campaignId,
            List<Dictionary<string, object>> queue,
            bool persistQueue)
        {
            queue = queue ?? new List<Dictionary<string, object>>();
            if (!queue.Any(row => !IsTerminalActionReportStatus(ReadString(row, "status", ""))))
                return queue;

            string historyPath = CampaignFile(campaignId, "actions", "actions.jsonl");
            if (!File.Exists(historyPath)) return queue;
            Dictionary<string, Dictionary<string, object>> terminalById =
                new Dictionary<string, Dictionary<string, object>>(StringComparer.OrdinalIgnoreCase);
            foreach (Dictionary<string, object> historyRow in ReadJsonLinesFromPath(historyPath))
            {
                string historyStatus = ReadString(historyRow, "status", "");
                string historyId = ReadString(historyRow, "id",
                    ReadFirstString(ReadDictionary(historyRow, "report"), "serverActionId", "actionId"));
                if (!string.IsNullOrWhiteSpace(historyId)
                    && IsTerminalActionReportStatus(historyStatus))
                    terminalById[historyId] = historyRow;
            }

            bool changed = false;
            List<Tuple<string, string, Dictionary<string, object>>> healed =
                new List<Tuple<string, string, Dictionary<string, object>>>();
            foreach (Dictionary<string, object> row in queue)
            {
                string id = ReadString(row, "id", "");
                string currentStatus = ReadString(row, "status", "");
                if (IsTerminalActionReportStatus(currentStatus)
                    || !terminalById.TryGetValue(id, out Dictionary<string, object> terminal))
                    continue;
                string terminalStatus = ReadString(terminal, "status", "");
                Dictionary<string, object> terminalReport =
                    ReadDictionary(terminal, "report") ?? new Dictionary<string, object>();
                row["status"] = terminalStatus;
                row["reportTs"] = ReadLong(terminal, "ts", DateTimeOffset.UtcNow.ToUnixTimeSeconds());
                row["report"] = terminalReport;
                healed.Add(Tuple.Create(id, terminalStatus, terminalReport));
                changed = true;
            }
            if (changed && persistQueue)
            {
                WriteActionQueueUnlocked(campaignId, queue);
                foreach (Tuple<string, string, Dictionary<string, object>> item in healed)
                    UpdateDiplomaticEventForAction(campaignId, item.Item1, item.Item2, item.Item3);
            }
            return queue;
        }

        private static List<Dictionary<string, object>> ReadActionQueueFromPath(string path)
        {
            string json = File.ReadAllText(path, Encoding.UTF8);
            try
            {
                List<Dictionary<string, object>> typed = Json.Deserialize<List<Dictionary<string, object>>>(json);
                if (typed != null)
                {
                    return typed;
                }
            }
            catch
            {
            }

            try
            {
                object value = Json.DeserializeObject(json);
                if (value is ArrayList array)
                {
                    return array.Cast<object>().OfType<Dictionary<string, object>>().ToList();
                }

                if (value is IEnumerable<object> enumerable)
                {
                    return enumerable.OfType<Dictionary<string, object>>().ToList();
                }
            }
            catch
            {
            }

            return new List<Dictionary<string, object>>();
        }

        private static void WriteActionQueueUnlocked(string campaignId, List<Dictionary<string, object>> queue)
        {
            string path = CampaignFile(campaignId, "actions", "action-queue.json");
            Directory.CreateDirectory(Path.GetDirectoryName(path));
            File.WriteAllText(path, Json.Serialize(queue ?? new List<Dictionary<string, object>>()), Encoding.UTF8);
        }

        private static string ModelForRequest(Dictionary<string, object> settings, string requestType)
        {
            string key;
            switch ((requestType ?? "").ToLowerInvariant())
            {
                case "diplomacy": key = "diplomacyModel"; break;
                case "events": key = "eventsModel"; break;
                case "event":
                case "social_event": key = "eventsModel"; break;
                case "political_pressure_trait_selector":
                case "political_pressure_narration": key = "fastModel"; break;
                case "memory": key = "memoryModel"; break;
                case "character_construction": key = "characterConstructionModel"; break;
                case "relationship": key = "relationshipModel"; break;
                case "correspondence": key = "correspondenceModel"; break;
                case "context_selector": key = "selectorModel"; break;
                case "action_planner": key = "actionPlannerModel"; break;
                case "action_router": key = "actionRouterModel"; break;
                case "action_repair": key = "actionRouterModel"; break;
                case "strategy":
                case "action":
                case "actions": key = "strategyModel"; break;
                default: key = "dialogueModel"; break;
            }

            string model = ReadString(settings, key, "");
            if (string.IsNullOrWhiteSpace(model)
                && key.Equals("fastModel", StringComparison.OrdinalIgnoreCase))
                model = ReadString(settings, "eventsModel", "");
            return string.IsNullOrWhiteSpace(model) ? ReadString(settings, "dialogueModel", "") : model;
        }

