        private static string ReadSupporterClanIds(Dictionary<string, object> raw, Dictionary<string, object> terms)
        {
            List<string> ids = ReadStringList(raw, "supporterClanIds");
            ids.AddRange(ReadStringList(terms, "supporterClanIds"));
            return string.Join(",", ids.Where(x => !string.IsNullOrWhiteSpace(x)).Distinct());
        }

        private static string FirstStringFromTerms(Dictionary<string, object> terms, string key)
        {
            return ReadStringList(terms, key).FirstOrDefault() ?? string.Empty;
        }

        private static void Require(Dictionary<string, object> record, string key, List<string> errors)
        {
            if (string.IsNullOrWhiteSpace(ReadString(record, key, "")))
            {
                errors.Add(key + " is required.");
            }
        }

        private static void CopyOptional(Dictionary<string, object> source, Dictionary<string, object> target, string key)
        {
            if (source != null && source.TryGetValue(key, out object value) && value != null)
            {
                target[key] = value;
            }
        }

        private static Dictionary<string, object> TryParseJsonObject(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return null;
            }

            string trimmed = text.Trim();
            if (trimmed.StartsWith("```", StringComparison.Ordinal))
            {
                int firstBreak = trimmed.IndexOf('\n');
                int lastFence = trimmed.LastIndexOf("```", StringComparison.Ordinal);
                if (firstBreak >= 0 && lastFence > firstBreak)
                {
                    trimmed = trimmed.Substring(firstBreak + 1, lastFence - firstBreak - 1).Trim();
                }
            }

            int start = trimmed.IndexOf('{');
            int end = trimmed.LastIndexOf('}');
            if (start >= 0 && end > start)
            {
                trimmed = trimmed.Substring(start, end - start + 1);
            }

            try
            {
                return Json.Deserialize<Dictionary<string, object>>(trimmed);
            }
            catch
            {
                // Some providers occasionally emit an abandoned partial object and
                // then restart with a complete JSON object in the same response.
                // The whole string is invalid, but the later object is usable and
                // should win over recovering a clipped visible reply from the
                // abandoned prefix.
                return TryParseBestCompleteJsonObject(trimmed);
            }
        }

        private static Dictionary<string, object> TryParseBestCompleteJsonObject(string text)
        {
            Dictionary<string, object> best = null;
            int bestScore = int.MinValue;
            int bestStart = -1;
            string source = text ?? "";
            for (int start = 0; start < source.Length; start++)
            {
                if (source[start] != '{') continue;
                int depth = 0;
                bool inString = false;
                bool escaped = false;
                for (int index = start; index < source.Length; index++)
                {
                    char ch = source[index];
                    if (inString)
                    {
                        if (escaped) escaped = false;
                        else if (ch == '\\') escaped = true;
                        else if (ch == '"') inString = false;
                        continue;
                    }
                    if (ch == '"')
                    {
                        inString = true;
                        continue;
                    }
                    if (ch == '{') depth++;
                    else if (ch == '}') depth--;
                    if (depth != 0) continue;

                    string candidate = source.Substring(start, index - start + 1);
                    try
                    {
                        Dictionary<string, object> parsed = Json.Deserialize<Dictionary<string, object>>(candidate);
                        if (parsed != null)
                        {
                            int score = CompleteJsonObjectCandidateScore(parsed, candidate.Length);
                            if (score > bestScore || score == bestScore && start > bestStart)
                            {
                                best = parsed;
                                bestScore = score;
                                bestStart = start;
                            }
                        }
                    }
                    catch
                    {
                        // Continue searching at the next opening brace.
                    }
                    break;
                }
            }
            return best;
        }

        private static int CompleteJsonObjectCandidateScore(Dictionary<string, object> value, int length)
        {
            if (value == null) return int.MinValue;
            int score = Math.Min(1000, Math.Max(0, length / 20));
            if (value.ContainsKey("reply")) score += 10000;
            else if (value.ContainsKey("response") || value.ContainsKey("text") || value.ContainsKey("content")) score += 9000;
            if (value.ContainsKey("decisionBrief") || value.ContainsKey("decision_brief")) score += 1000;
            if (value.ContainsKey("actionGate") || value.ContainsKey("action_gate")) score += 1000;
            if (value.ContainsKey("actions")) score += 8000;
            if (value.ContainsKey("summary")) score += 6000;
            score += Math.Min(100, value.Count);
            return score;
        }

        private static string ExtractVisibleReply(string content)
        {
            if (string.IsNullOrWhiteSpace(content))
            {
                return string.Empty;
            }

            string extracted = ExtractJsonStringField(content, "reply");
            if (string.IsNullOrWhiteSpace(extracted))
            {
                extracted = ExtractJsonStringField(content, "response");
            }

            if (string.IsNullOrWhiteSpace(extracted))
            {
                extracted = content;
            }

            return SanitizeVisibleReply(extracted);
        }

        private static string ExtractJsonStringField(string text, string fieldName)
        {
            if (string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(fieldName))
            {
                return string.Empty;
            }

            string needle = "\"" + fieldName + "\"";
            int keyIndex = text.IndexOf(needle, StringComparison.OrdinalIgnoreCase);
            if (keyIndex < 0)
            {
                keyIndex = text.IndexOf(fieldName + ":", StringComparison.OrdinalIgnoreCase);
            }

            if (keyIndex < 0)
            {
                return string.Empty;
            }

            int colon = text.IndexOf(':', keyIndex);
            if (colon < 0)
            {
                return string.Empty;
            }

            int quote = -1;
            for (int i = colon + 1; i < text.Length; i++)
            {
                if (text[i] == '"')
                {
                    quote = i;
                    break;
                }
            }

            if (quote < 0)
            {
                return string.Empty;
            }

            StringBuilder builder = new StringBuilder();
            bool escape = false;
            for (int i = quote + 1; i < text.Length; i++)
            {
                char ch = text[i];
                if (escape)
                {
                    switch (ch)
                    {
                        case 'n':
                            builder.Append('\n');
                            break;
                        case 'r':
                            builder.Append('\r');
                            break;
                        case 't':
                            builder.Append('\t');
                            break;
                        case '"':
                        case '\\':
                        case '/':
                            builder.Append(ch);
                            break;
                        default:
                            builder.Append(ch);
                            break;
                    }
                    escape = false;
                    continue;
                }

                if (ch == '\\')
                {
                    escape = true;
                    continue;
                }

                if (ch == '"')
                {
                    return builder.ToString();
                }

                builder.Append(ch);
            }

            return builder.ToString();
        }

        private static bool TryExtractClosedJsonStringField(string text, string fieldName, out string value)
        {
            value = string.Empty;
            if (string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(fieldName)) return false;
            string needle = "\"" + fieldName + "\"";
            int keyIndex = text.IndexOf(needle, StringComparison.OrdinalIgnoreCase);
            if (keyIndex < 0) return false;
            int colon = text.IndexOf(':', keyIndex + needle.Length);
            if (colon < 0) return false;
            int quote = text.IndexOf('"', colon + 1);
            if (quote < 0) return false;
            StringBuilder builder = new StringBuilder();
            bool escape = false;
            for (int i = quote + 1; i < text.Length; i++)
            {
                char ch = text[i];
                if (escape)
                {
                    switch (ch)
                    {
                        case 'n': builder.Append('\n'); break;
                        case 'r': builder.Append('\r'); break;
                        case 't': builder.Append('\t'); break;
                        case '"':
                        case '\\':
                        case '/': builder.Append(ch); break;
                        default: builder.Append(ch); break;
                    }
                    escape = false;
                    continue;
                }
                if (ch == '\\')
                {
                    escape = true;
                    continue;
                }
                if (ch == '"')
                {
                    value = builder.ToString();
                    return true;
                }
                builder.Append(ch);
            }
            value = string.Empty;
            return false;
        }

        private static string SanitizeVisibleReply(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return string.Empty;
            }

            string cleaned = text.Replace("\\r\\n", "\n").Replace("\\n", "\n").Replace("\\t", " ").Replace("\\\"", "\"").Trim();
            if (cleaned.StartsWith("{", StringComparison.Ordinal))
            {
                string extracted = ExtractJsonStringField(cleaned, "reply");
                if (!string.IsNullOrWhiteSpace(extracted))
                {
                    cleaned = extracted.Trim();
                }
            }

            foreach (string marker in new[]
            {
                "\"internalThoughts\"",
                "\"internal_thoughts\"",
                "internalThoughts:",
                "\"decisionBrief\"",
                "\"decision_brief\"",
                "FACT CHECK:",
                "\"memoryWrites\"",
                "\"beliefWrites\"",
                "\"obligationWrites\"",
                "\"comprehensionWrites\"",
                "\"stateUpdates\"",
                "\"suggestedActions\"",
                "\"relationshipSignal\"",
                "\"relationshipAssessments\"",
                "\"emotion\"",
                "\"intent\""
            })
            {
                int index = cleaned.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
                if (index >= 0)
                {
                    cleaned = cleaned.Substring(0, index);
                }
            }

            cleaned = StripVisibleReplySectionLabels(cleaned);
            bool failedRepairMarker = cleaned.TrimEnd().EndsWith(".,", StringComparison.Ordinal);
            // A leading quote is often the first character of legitimate spoken
            // dialogue while its matching quote ends before trailing narration.
            // Trimming quote characters from the whole payload produced visible
            // fragments such as `Rhovarion, then."`; only structural JSON braces
            // and commas should be removed here.
            cleaned = cleaned.Trim().Trim(',', '{', '}').Trim();
            if (ContainsPrivateReplyLeak(cleaned))
            {
                return "[Bannerlord Reign: the model returned malformed JSON, so the visible reply was hidden. Please try again.]";
            }

            return failedRepairMarker ? MarkRepairedVisibleText(cleaned, false) : cleaned;
        }

        private static string StripVisibleReplySectionLabels(string text)
        {
            string[] lines = (text ?? string.Empty).Replace("\r\n", "\n").Split('\n');
            bool inTimeSection = false;
            bool inActionSection = false;
            List<string> kept = new List<string>();

            foreach (string line in lines)
            {
                string label = VisibleReplySectionLabel(line);
                if (label == "time extraction" || label == "time & place")
                {
                    inTimeSection = true;
                    inActionSection = false;
                    continue;
                }

                if (label == "dialogue")
                {
                    if (inTimeSection && kept.Count > 0 && !string.IsNullOrWhiteSpace(kept[kept.Count - 1]))
                    {
                        kept.Add(string.Empty);
                    }

                    inTimeSection = false;
                    inActionSection = false;
                    continue;
                }

                if (label == "action")
                {
                    if (inTimeSection && kept.Count > 0 && !string.IsNullOrWhiteSpace(kept[kept.Count - 1]))
                    {
                        kept.Add(string.Empty);
                    }

                    inTimeSection = false;
                    inActionSection = true;
                    continue;
                }

                if (inTimeSection)
                {
                    string timeLine = line.Trim();
                    if (!string.IsNullOrWhiteSpace(timeLine) && !IsUnavailableTimeLine(timeLine))
                    {
                        kept.Add(timeLine);
                    }

                    continue;
                }

                if (string.IsNullOrWhiteSpace(line))
                {
                    if (kept.Count > 0 && !string.IsNullOrWhiteSpace(kept[kept.Count - 1]))
                    {
                        kept.Add(string.Empty);
                    }

                    continue;
                }

                string keptLine = line.TrimEnd();
                if (inActionSection && !IsAsteriskWrappedAction(keptLine))
                {
                    keptLine = "*" + keptLine.Trim() + "*";
                }

                kept.Add(keptLine);
            }

            while (kept.Count > 0 && string.IsNullOrWhiteSpace(kept[kept.Count - 1]))
            {
                kept.RemoveAt(kept.Count - 1);
            }

            return EnsureActionParagraphSpacing(kept);
        }

        private static string VisibleReplySectionLabel(string line)
        {
            return (line ?? string.Empty)
                .Trim()
                .Trim('[', ']', ':')
                .Trim()
                .ToLowerInvariant();
        }

        private static bool IsUnavailableTimeLine(string line)
        {
            string normalized = (line ?? string.Empty).Trim().Trim('.', '-', ':').Trim().ToLowerInvariant();
            return normalized == "unknown"
                || normalized == "unavailable"
                || normalized == "not supplied"
                || normalized == "no time data"
                || normalized == "no time & place data";
        }

        private static bool IsAsteriskWrappedAction(string line)
        {
            string trimmed = (line ?? string.Empty).Trim();
            return trimmed.Length >= 2 && trimmed[0] == '*' && trimmed[trimmed.Length - 1] == '*';
        }

        private static string EnsureActionParagraphSpacing(List<string> lines)
        {
            List<string> spaced = new List<string>();
            foreach (string line in lines ?? new List<string>())
            {
                bool isAction = IsAsteriskWrappedAction(line);
                if (isAction && spaced.Count > 0 && !string.IsNullOrWhiteSpace(spaced[spaced.Count - 1]))
                {
                    spaced.Add(string.Empty);
                }

                if (string.IsNullOrWhiteSpace(line))
                {
                    if (spaced.Count > 0 && !string.IsNullOrWhiteSpace(spaced[spaced.Count - 1]))
                    {
                        spaced.Add(string.Empty);
                    }
                    continue;
                }

                spaced.Add(line.TrimEnd());
                if (isAction)
                {
                    spaced.Add(string.Empty);
                }
            }

            while (spaced.Count > 0 && string.IsNullOrWhiteSpace(spaced[spaced.Count - 1]))
            {
                spaced.RemoveAt(spaced.Count - 1);
            }

            return string.Join("\n", spaced);
        }

        private static bool ContainsPrivateReplyLeak(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            string lowered = text.ToLowerInvariant();
            return lowered.Contains("internalthoughts")
                || lowered.Contains("memorywrites")
                || lowered.Contains("stateupdates")
                || lowered.Contains("suggestedactions")
                || lowered.Contains("relationshipsignal")
                || lowered.Contains("relationshipassessments")
                || lowered.Contains("fact check:");
        }

        private static Dictionary<string, object> MergeProfileForConstruction(string campaignId, string heroId, Dictionary<string, object> hero)
        {
            Dictionary<string, object> profile = ReadJsonObject(CharacterFile(campaignId, heroId, "profile.json"));
            foreach (KeyValuePair<string, object> pair in hero ?? new Dictionary<string, object>())
            {
                profile[pair.Key] = pair.Value;
            }

            profile["campaignId"] = campaignId;
            profile["heroStringId"] = heroId;
            return WithNarrativeCampaignVersion(campaignId, profile);
        }

        private static Dictionary<string, object> LoadCharacterTemplate(string heroId, Dictionary<string, object> profile)
        {
            string heroFile = Path.Combine(CharacterTemplatesDir, SafePathSegment(heroId, "unknown") + ".json");
            string heroDirFile = Path.Combine(CharacterTemplatesDir, SafePathSegment(heroId, "unknown"), "template.json");
            Dictionary<string, object> template = ReadJsonObject(heroFile);
            if (template.Count == 0)
            {
                template = ReadJsonObject(heroDirFile);
            }

            if (template.Count == 0)
            {
                template = new Dictionary<string, object>
                {
                    ["version"] = 1,
                    ["source"] = "generated_from_game_profile",
                    ["archetype"] = CharacterArchetype(profile),
                    ["notes"] = "No authored template found. Bannerlord Reign will construct this character from campaign facts, traits, and encyclopedia text."
                };
            }

            return template;
        }

        private static Dictionary<string, object> BuildLegacyTraitDocument(Dictionary<string, object> hero)
        {
            Dictionary<string, object> visible = ReadDictionary(hero, "traits") ?? new Dictionary<string, object>();
            int valor = TraitInt(visible, "valor");
            int generosity = TraitInt(visible, "generosity");
            int honor = TraitInt(visible, "honor");
            int mercy = TraitInt(visible, "mercy");
            int calculating = TraitInt(visible, "calculating");
            bool isLord = ReadBool(hero, "isLord", false);
            bool isNotable = ReadBool(hero, "isNotable", false);
            bool isWanderer = ReadBool(hero, "isWanderer", false);
            int ageBonus = ReadDouble(hero, "age", 0) >= 40 ? 1 : 0;

            Dictionary<string, object> hidden = new Dictionary<string, object>
            {
                ["ambition"] = ClampTrait(calculating + (isLord ? 1 : 0) + (isWanderer ? -1 : 0)),
                ["dominance"] = ClampTrait(valor - mercy + (isLord ? 1 : 0)),
                ["opportunism"] = ClampTrait(calculating - honor - Math.Max(0, generosity) / 2),
                ["patience"] = ClampTrait(calculating + ageBonus),
                ["riskTolerance"] = ClampTrait(valor),
                ["charm"] = ClampTrait(Math.Max(0, generosity) + (isNotable ? 1 : 0) - Math.Max(0, -honor)),
                ["reserve"] = ClampTrait(calculating - Math.Max(0, generosity)),
                ["bluntness"] = ClampTrait(honor + valor - calculating),
                ["empathy"] = ClampTrait(generosity + mercy),
                ["deceit"] = ClampTrait(-honor + Math.Max(0, calculating)),
                ["clanFirst"] = ClampTrait((isLord ? 1 : 0) + Math.Max(0, honor)),
                ["kingdomFaith"] = ClampTrait((isLord ? 1 : 0) + honor - Math.Max(0, -calculating)),
                ["personalLoyalty"] = ClampTrait(honor + generosity),
                ["tradition"] = ClampTrait(honor + ageBonus),
                ["romanticism"] = ClampTrait(generosity + mercy - Math.Max(0, calculating) / 2),
                ["pride"] = ClampTrait(valor + Math.Max(0, calculating)),
                ["vengefulness"] = ClampTrait(-mercy + Math.Max(0, valor)),
                ["paranoia"] = ClampTrait(calculating - valor - Math.Max(0, honor)),
                ["desperation"] = ClampTrait(ReadBool(hero, "isPrisoner", false) ? 1 : 0),
                ["envy"] = ClampTrait(-generosity + Math.Max(0, calculating) / 2),
                ["greed"] = ClampTrait(-generosity + (isNotable ? 1 : 0)),
                ["decadence"] = ClampTrait(-generosity + Math.Max(0, charmish(generosity, mercy))),
                ["zeal"] = ClampTrait(honor + Math.Max(0, -mercy)),
                ["worldliness"] = ClampTrait(calculating + ageBonus + (isNotable || isLord ? 1 : 0)),
                ["needForRecognition"] = ClampTrait(Math.Max(0, calculating) + Math.Max(0, valor) + (isLord ? 1 : 0) - Math.Max(0, generosity)),
                ["appearanceSensitivity"] = ClampTrait(Math.Max(0, generosity) + Math.Max(0, -calculating) + Math.Max(0, -honor) - Math.Max(0, mercy) / 2)
            };

            Dictionary<string, object> attractiveness = BuildAttractiveness(hero);
            return new Dictionary<string, object>
            {
                ["version"] = 1,
                ["scale"] = "-2..2",
                ["scaleMeaning"] = new Dictionary<string, object>
                {
                    ["-2"] = "strongly opposite or defining inverse",
                    ["-1"] = "leans opposite",
                    ["0"] = "ordinary, balanced, or situational",
                    ["1"] = "clearly present",
                    ["2"] = "defining trait"
                },
                ["visibleBannerlordTraits"] = visible,
                ["hiddenReignTraits"] = hidden,
                ["attractiveness"] = attractiveness,
                ["definitions"] = TraitDefinitions()
            };
        }

        private static int charmish(int generosity, int mercy)
        {
            return Math.Max(0, generosity + mercy);
        }

        private static Dictionary<string, object> BuildAttractiveness(Dictionary<string, object> hero)
        {
            double weight = NormalizeBodyPercent(ReadDouble(hero, "bodyWeight", ReadDouble(hero, "weight", 50)));
            double build = NormalizeBodyPercent(ReadDouble(hero, "bodyBuild", ReadDouble(hero, "build", 50)));
            bool isFemale = ReadBool(hero, "isFemale", false);
            int score;
            if (isFemale)
            {
                score = weight <= 25 ? 2 : weight <= 50 ? 1 : weight <= 75 ? 0 : -1;
            }
            else
            {
                int weightScore = weight <= 50 ? 1 : 0;
                int buildScore = build <= 25 ? -1 : build <= 50 ? 0 : 1;
                score = weightScore + buildScore;
            }

            return new Dictionary<string, object>
            {
                ["version"] = 1,
                ["score"] = Clamp(score, -2, 2),
                ["weight"] = Math.Round(weight, 2),
                ["build"] = Math.Round(build, 2),
                ["rule"] = isFemale ? "female_weight_scale" : "male_weight_plus_build_scale"
            };
        }

        private static double NormalizeBodyPercent(double value)
        {
            if (value >= 0 && value <= 1)
            {
                value *= 100d;
            }

            return Math.Max(0d, Math.Min(100d, value));
        }

        private static int TraitInt(Dictionary<string, object> traits, string key)
        {
            return ClampTrait(ReadInt(traits, key, 0));
        }

        private static int ClampTrait(int value)
        {
            return Clamp(value, -2, 2);
        }

        private static int Clamp(int value, int min, int max)
        {
            return Math.Max(min, Math.Min(max, value));
        }

        private static Dictionary<string, object> LegacyTraitDefinitions()
        {
            Dictionary<string, string[]> descriptors = LegacyTraitSentenceDescriptors();
            Dictionary<string, object> definitions = new Dictionary<string, object>();
            foreach (KeyValuePair<string, string[]> pair in descriptors)
            {
                definitions[pair.Key] = "-2: " + pair.Value[0] + " -1: " + pair.Value[1] + " 0: " + pair.Value[2] + " 1: " + pair.Value[3] + " 2: " + pair.Value[4];
            }

            return definitions;
        }

