        private static void EnsureEncyclopediaText(Dictionary<string, object> background, Dictionary<string, object> hero, Dictionary<string, object> traits)
        {
            if (background == null)
            {
                return;
            }

            string nativeText = ReadString(hero, "nativeEncyclopediaText", "").Trim();
            if (!string.IsNullOrWhiteSpace(nativeText))
            {
                string generatedSummary = ReadString(background, "summary", "").Trim();
                string generatedPublic = ReadString(background, "encyclopediaText", "").Trim();
                string priorNative = ReadString(background, "nativeEncyclopediaText", "").Trim();
                generatedSummary = RemoveLeadingNativeBackground(priorNative, generatedSummary);
                generatedPublic = RemoveLeadingNativeBackground(priorNative, generatedPublic);
                background["nativeEncyclopediaText"] = nativeText;
                background["nativeTextPreserved"] = true;
                background["summary"] = BuildAroundNativeBackground(nativeText, generatedSummary);
                background["encyclopediaText"] = BuildAroundNativeBackground(nativeText, generatedPublic);
                return;
            }

            if (!string.IsNullOrWhiteSpace(ReadString(background, "encyclopediaText", "")))
            {
                return;
            }

            background["encyclopediaText"] = ReadString(background, "summary", ReadString(DefaultBackground(hero, traits), "summary", ""));
        }

        private static string BuildAroundNativeBackground(string nativeText, string generatedText)
        {
            nativeText = (nativeText ?? "").Trim();
            generatedText = (generatedText ?? "").Trim();
            if (string.IsNullOrWhiteSpace(nativeText)) return generatedText;
            if (string.IsNullOrWhiteSpace(generatedText) || generatedText.Equals(nativeText, StringComparison.Ordinal)) return nativeText;
            if (generatedText.StartsWith(nativeText, StringComparison.Ordinal)) return generatedText;
            return nativeText + "\n\n" + generatedText;
        }

        private static string RemoveLeadingNativeBackground(string nativeText, string generatedText)
        {
            nativeText = (nativeText ?? "").Trim();
            generatedText = (generatedText ?? "").Trim();
            if (string.IsNullOrWhiteSpace(nativeText) || !generatedText.StartsWith(nativeText, StringComparison.Ordinal)) return generatedText;
            return generatedText.Substring(nativeText.Length).TrimStart('\r', '\n', ' ');
        }

        private static string BuildEncyclopediaBackstoryText(string campaignId, string heroId)
        {
            Dictionary<string, object> background = ReadJsonObject(CharacterFile(campaignId, heroId, "background.json"));
            return ReadString(background, "encyclopediaText", ReadString(background, "summary", ""));
        }

        private static Dictionary<string, object> LoadCharacterStack(string campaignId, string heroId)
        {
            Dictionary<string, object> stack = ReadJsonObject(CharacterFile(campaignId, heroId, "characteristics.json"));
            Dictionary<string, object> profile = ReadJsonObject(CharacterFile(campaignId, heroId, "profile.json"));
            Dictionary<string, object> traits = ReadJsonObject(CharacterFile(campaignId, heroId, "traits.json"));
            if (traits.Count > 0)
            {
                bool changed = EnsureTraitPercentageData(traits, heroId);
                changed = EnsureCourtCharacterData(traits, profile, heroId) || changed;
                if (changed) WriteJsonObject(CharacterFile(campaignId, heroId, "traits.json"), traits);
            }
            stack["traits"] = traits;
            stack["wealth"] = ResolveWealthDocument(campaignId, heroId, profile);
            stack["inventory"] = ReadJsonObject(CharacterFile(campaignId, heroId, "inventory.json"));
            stack["appearance"] = ReadJsonObject(CharacterFile(campaignId, heroId, "appearance.json"));
            stack["background"] = ReadJsonObject(CharacterFile(campaignId, heroId, "background.json"));
            stack["voice"] = ReadJsonObject(CharacterFile(campaignId, heroId, "voice.json"));
            stack["motivations"] = ReadJsonObject(CharacterFile(campaignId, heroId, "motivations.json"));
            stack["saveQuirks"] = ReadJsonObject(CharacterFile(campaignId, heroId, "save_quirks.json"));
            stack["hiddenHistory"] = ReadJsonObject(CharacterFile(campaignId, heroId, "hidden_history.json"));
            stack["secrets"] = ReadJsonObject(CharacterFile(campaignId, heroId, "secrets.json"));
            stack["pressure"] = ReadJsonObject(CharacterFile(campaignId, heroId, "pressure.json"));
            stack["dynamicCharacteristics"] = ReadJsonObject(CharacterFile(campaignId, heroId, "dynamic_characteristics.json"));
            stack["narrative"] = ReadJsonObject(CharacterFile(campaignId, heroId, "narrative.json"));
            ApplyNarrativePromptProjection(stack);
            stack["constructed"] = ReadJsonObject(CharacterFile(campaignId, heroId, "constructed.json"));
            return stack;
        }

        private static string CharacterArchetype(Dictionary<string, object> hero)
        {
            if (ReadBool(hero, "isLord", false))
            {
                return "lord";
            }

            if (ReadBool(hero, "isNotable", false))
            {
                return "notable";
            }

            if (ReadBool(hero, "isWanderer", false))
            {
                return "wanderer";
            }

            return ReadString(hero, "occupation", "person");
        }

