        private static Dictionary<string, object> LoadSettings()
        {
            if (ActiveCodexConversationScope.Value != null) return DeepCloneProfileDictionary(ActiveCodexConversationScope.Value.Settings);
            if (CodexPerformanceSettings.Value != null) return DeepCloneProfileDictionary(CodexPerformanceSettings.Value);
            if (NarrativeAuthoringSettings != null) return DeepCloneProfileDictionary(NarrativeAuthoringSettings);
            Dictionary<string, object> settings = DefaultSettings();
            bool settingsFileExisted = File.Exists(SettingsPath);
            if (File.Exists(SettingsPath))
            {
                try
                {
                    Dictionary<string, object> saved = Json.Deserialize<Dictionary<string, object>>(File.ReadAllText(SettingsPath, Encoding.UTF8));
                    foreach (KeyValuePair<string, object> pair in saved)
                    {
                        settings[pair.Key] = pair.Value;
                    }
                }
                catch (Exception ex)
                {
                    LogOperational("settings.load_failed", new Dictionary<string, object> { ["error"] = ex.Message });
                }
            }
            bool secretsRecovered = RecoverInstalledSettingsSecrets(settings, !settingsFileExisted);
            bool portraitSettingsChanged = NormalizePortraitImageSettings(settings);
            bool constructionBudgetChanged = NormalizeCharacterConstructionBudget(settings);
            bool memorySettingsChanged = NormalizeMemorySettings(settings);
            bool architectureSettingsChanged = NormalizeArchitectureSettings(settings);
            bool llmProviderSettingsChanged = NormalizeLlmProviderSettings(settings);
            bool codexOptionsChanged = NormalizeCodexOptions(settings);
            NormalizePromptCacheSettings(settings);
            NormalizeReasoningSettings(settings);
            if (!settingsFileExisted || secretsRecovered || portraitSettingsChanged || constructionBudgetChanged || memorySettingsChanged || architectureSettingsChanged || llmProviderSettingsChanged || codexOptionsChanged)
            {
                settings["settingsRevision"] = DateTime.UtcNow.ToString("o");
                Directory.CreateDirectory(DataDir);
                File.WriteAllText(SettingsPath, Json.Serialize(settings), Encoding.UTF8);
                LogOperational("settings.normalized", new Dictionary<string, object>
                {
                    ["portraitSettingsChanged"] = portraitSettingsChanged, ["memorySettingsChanged"] = memorySettingsChanged,
                    ["constructionBudgetChanged"] = constructionBudgetChanged,
                    ["architectureSettingsChanged"] = architectureSettingsChanged,
                    ["llmProviderSettingsChanged"] = llmProviderSettingsChanged,
                    ["secretsRecovered"] = secretsRecovered,
                    ["settingsFileExisted"] = settingsFileExisted
                });
            }
            // Reign's local vector worker uses its own loopback port 5102.
            settings["vectorWorkerUrl"] = "http://127.0.0.1:5102";
            PersistInstalledSettingsSecrets(settings);
            return settings;
        }

        private static Dictionary<string, object> SaveSettings(Dictionary<string, object> incoming)
        {
            string xpError = ValidateReignXpOptions(incoming);
            if (!string.IsNullOrEmpty(xpError))
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = xpError };
            string imageProviderError = ValidateCodexImageSettings(incoming);
            if (!string.IsNullOrEmpty(imageProviderError))
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = imageProviderError };
            Dictionary<string, object> settings = DefaultSettings();
            if (File.Exists(SettingsPath))
            {
                try
                {
                    Dictionary<string, object> saved = Json.Deserialize<Dictionary<string, object>>(File.ReadAllText(SettingsPath, Encoding.UTF8));
                    foreach (KeyValuePair<string, object> pair in saved)
                    {
                        settings[pair.Key] = pair.Value;
                    }
                }
                catch (Exception ex)
                {
                    LogOperational("settings.save_load_existing_failed", new Dictionary<string, object> { ["error"] = ex.Message });
                }
            }

            string previousCodexSettingsIdentity = CodexSettingsIdentity(settings);
            List<string> clearKeys = MergeProviderSettings(settings, incoming);
            if (previousCodexSettingsIdentity != CodexSettingsIdentity(settings)) InvalidateCodexThreads("provider_or_codex_settings_changed");

            if (incoming != null && incoming.Keys.Any(key =>
                key.StartsWith("scenery", StringComparison.OrdinalIgnoreCase)
                && !string.Equals(key, "sceneryImageProfileInitialized", StringComparison.OrdinalIgnoreCase)))
            {
                settings["sceneryImageProfileInitialized"] = true;
            }

            NormalizePortraitImageSettings(settings);
            if (incoming != null && incoming.ContainsKey("characterConstructionMaxTokens"))
                settings["characterConstructionBudgetInitialized"] = true;
            NormalizeCharacterConstructionBudget(settings);
            NormalizePromptCacheSettings(settings);
            NormalizeReasoningSettings(settings);
            NormalizeMemorySettings(settings);
            NormalizeArchitectureSettings(settings);
            NormalizeLlmProviderSettings(settings);
            settings["settingsRevision"] = DateTime.UtcNow.ToString("o");
            Directory.CreateDirectory(DataDir);
            File.WriteAllText(SettingsPath, Json.Serialize(settings), Encoding.UTF8);
            PersistInstalledSettingsSecrets(settings, clearKeys.Count > 0);
            LogOperational("settings.save", RedactSensitive(settings));
            if (ActiveListener != null)
            {
                if (ReadBool(settings, "enableSemanticMemory", true)) StartSemanticMemorySubsystem(settings);
                else StopSemanticMemorySubsystem();
            }

            Dictionary<string, object> result = SettingsForUi(settings);
            result["ok"] = true;
            return result;
        }

        private static bool NormalizePortraitImageSettings(Dictionary<string, object> settings)
        {
            if (settings == null)
            {
                return false;
            }

            bool changed = false;
            string nativeSourceMode = ReadString(settings, "portraitNativeSourceMode", "required").Trim().ToLowerInvariant();
            if (nativeSourceMode != "required" && nativeSourceMode != "preferred" && nativeSourceMode != "off")
            {
                nativeSourceMode = "required";
            }
            if (!settings.ContainsKey("portraitNativeSourceMode")
                || !string.Equals(ReadString(settings, "portraitNativeSourceMode", ""), nativeSourceMode, StringComparison.Ordinal))
            {
                settings["portraitNativeSourceMode"] = nativeSourceMode;
                changed = true;
            }
            if (!settings.ContainsKey("portraitNativeSourceGeneratorPath"))
            {
                settings["portraitNativeSourceGeneratorPath"] = "";
                changed = true;
            }
            if (!ReadBool(settings, "sceneryImageProfileInitialized", false))
            {
                string[] profileSuffixes =
                {
                    "Provider", "NanoGptImageModel", "AtlasImageModel", "OpenRouterImageModel", "AtlasWanNegativePrompt",
                    "ImageStrength", "InferenceSteps", "GuidanceScale"
                };
                foreach (string suffix in profileSuffixes)
                {
                    settings["scenery" + suffix] = settings.TryGetValue("portrait" + suffix, out object value)
                        ? value
                        : null;
                }
                settings["sceneryImageProfileInitialized"] = true;
                changed = true;
            }
            if (settings.Remove("portraitNanoGptImageEditsUrl"))
            {
                changed = true;
            }

            foreach (string prefix in ImageProfilePrefixes)
            {
                bool adult = prefix.StartsWith("adult", StringComparison.Ordinal);
                if (adult)
                {
                    var defaults = new Dictionary<string, object> { ["Provider"] = "AtlasCloud",
                        ["NanoGptImageModel"] = "gpt-image-1.5", ["AtlasImageModel"] = AtlasModelSeedreamV5ProEdit,
                        ["AtlasWanNegativePrompt"] = DefaultAtlasWan25NegativePrompt };
                    foreach (var pair in defaults)
                        if (!settings.ContainsKey(prefix + pair.Key)) { settings[prefix + pair.Key] = pair.Value; changed = true; }
                }
                if (IsRetiredImageProvider(ReadString(settings, prefix + "Provider", "")))
                {
                    settings[prefix + "Provider"] = "AtlasCloud";
                    settings[prefix + "AtlasImageModel"] = AtlasModelSeedreamV5ProEdit;
                    changed = true;
                }
                foreach (string retired in new[] { "ReignGeneratorNegativePrompt", "ReignGeneratorSteps", "ReignGeneratorCfg" })
                    changed |= settings.Remove(prefix + retired);
                string modelKey = prefix + "NanoGptImageModel";
                if (string.Equals(ReadString(settings, modelKey, ""), "step-image-edit-2", StringComparison.OrdinalIgnoreCase))
                {
                    settings[modelKey] = "gpt-image-1.5";
                    changed = true;
                }
                HashSet<string> supportedNanoModels = new HashSet<string>(NanoImageModels, StringComparer.OrdinalIgnoreCase);
                if (!supportedNanoModels.Contains(ReadString(settings, modelKey, "")))
                {
                    settings[modelKey] = "gpt-image-1.5";
                    changed = true;
                }

                string openRouterModelKey = prefix + "OpenRouterImageModel";
                if (!OpenRouterImageModels.Contains(ReadString(settings, openRouterModelKey, "")))
                { settings[openRouterModelKey] = DefaultOpenRouterImageModel; changed = true; }

                string atlasModelKey = prefix + "AtlasImageModel";
                HashSet<string> supportedAtlasModels = new HashSet<string>(AtlasImageModels, StringComparer.OrdinalIgnoreCase);
                if (!supportedAtlasModels.Contains(ReadString(settings, atlasModelKey, "")))
                {
                    settings[atlasModelKey] = adult ? AtlasModelSeedreamV5ProEdit : DefaultAtlasImageModel;
                    changed = true;
                }

                string providerKey = prefix + "Provider";
                string normalizedProvider = NormalizeImageProvider(ReadString(settings, providerKey, "NanoGPT"));
                if (!string.Equals(ReadString(settings, providerKey, ""), normalizedProvider, StringComparison.Ordinal))
                {
                    settings[providerKey] = normalizedProvider;
                    changed = true;
                }

                Action<string, int, int, int> normalizeInt = (suffix, fallback, minimum, maximum) =>
                {
                    string key = prefix + suffix;
                    int prior = ReadInt(settings, key, fallback);
                    int value = Math.Max(minimum, Math.Min(maximum, prior));
                    if (!settings.ContainsKey(key) || prior != value || !(settings[key] is int)) changed = true;
                    settings[key] = value;
                };
                Action<string, double, double, double> normalizeDouble = (suffix, fallback, minimum, maximum) =>
                {
                    string key = prefix + suffix;
                    double prior = ReadDouble(settings, key, fallback);
                    double value = ClampDouble(prior, minimum, maximum);
                    if (!settings.ContainsKey(key) || Math.Abs(prior - value) > 0.0001d) changed = true;
                    settings[key] = value;
                };

                normalizeDouble("ImageStrength", 0.75d, 0.4d, 1d);
                normalizeInt("InferenceSteps", 28, 10, 50);
                normalizeDouble("GuidanceScale", 3.5d, 1d, 10d);
            }
            return changed;
        }

        private static bool NormalizeMemorySettings(Dictionary<string, object> settings)
        {
            if (settings == null) return false;
            bool changed = false;
            Action<string, int, int, int> normalizeInt = (key, fallback, minimum, maximum) =>
            {
                int prior = ReadInt(settings, key, fallback);
                int value = Math.Max(minimum, Math.Min(maximum, prior));
                if (!settings.ContainsKey(key) || prior != value || !(settings[key] is int)) changed = true;
                settings[key] = value;
            };
            normalizeInt("maxContextMemories", 12, 1, 100);
            normalizeInt("recentRawConversationTurns", 30, 2, 100);
            normalizeInt("recentRawConversationCharBudget", 48000, 1200, 50000);
            normalizeInt("vectorSearchTopK", 96, 8, 256);
            normalizeInt("vectorQueryTimeoutMs", 10000, 8000, 30000);
            normalizeInt("embeddingBatchSize", 8, 1, 128);
            normalizeInt("memoryConsolidationMinItems", 4, 2, 20);
            normalizeInt("memoryConsolidationWindowMinutes", 30, 5, 240);
            normalizeInt("memoryConsolidationMaxGroups", 3, 1, 10);
            normalizeInt("memoryConsolidationMaxSourceItems", 24, 4, 80);
            normalizeInt("memoryConsolidationMaxSummaryChars", 1800, 500, 5000);
            double priorWeight = ReadDouble(settings, "vectorScoreWeight", 30d);
            double weight = ClampDouble(priorWeight, 0d, 100d);
            if (!settings.ContainsKey("vectorScoreWeight") || Math.Abs(priorWeight - weight) > 0.0001d) changed = true;
            settings["vectorScoreWeight"] = weight;
            return changed;
        }

        private static bool NormalizeArchitectureSettings(Dictionary<string, object> settings)
        {
            if (settings == null) return false;
            bool changed = false;
            Action<string, int, int, int> normalize = (key, fallback, minimum, maximum) =>
            {
                int prior = ReadInt(settings, key, fallback);
                int value = Math.Max(minimum, Math.Min(maximum, prior));
                if (!settings.ContainsKey(key) || prior != value || !(settings[key] is int)) changed = true;
                settings[key] = value;
            };
            normalize("providerMaxConcurrency", 4, 1, 16);
            normalize("providerQueueTimeoutMs", 30000, 1000, 120000);
            normalize("providerRequestTimeoutMs", 120000, 15000, 600000);
            normalize("providerCircuitFailureThreshold", 4, 2, 20);
            normalize("providerCircuitBreakSeconds", 30, 5, 600);
            normalize("llmTransientMaxAttempts", 4, 1, 4);
            normalize("promptWarningCharacterLimit", 100000, 20000, 500000);
            normalize("promptHardCharacterLimit", 240000, 50000, 1000000);
            int warningLimit = ReadInt(settings, "promptWarningCharacterLimit", 100000);
            int hardLimit = ReadInt(settings, "promptHardCharacterLimit", 240000);
            if (hardLimit <= warningLimit)
            {
                settings["promptHardCharacterLimit"] = Math.Min(1000000, warningLimit + 50000);
                changed = true;
            }
            if (!settings.ContainsKey("openTelemetryOtlpEndpoint")) { settings["openTelemetryOtlpEndpoint"] = ""; changed = true; }
            if (!settings.ContainsKey("autoCaptureReplayCorpus")) { settings["autoCaptureReplayCorpus"] = true; changed = true; }
            return changed;
        }

        private static Dictionary<string, object> ClearSettingsKey(Dictionary<string, object> payload)
        {
            string key = ReadString(payload, "key", "");
            if (!SensitiveSettingsKeys().Contains(key))
            {
                return new Dictionary<string, object> { ["ok"] = false, ["error"] = "Unknown or non-sensitive key cannot be cleared." };
            }

            Dictionary<string, object> incoming = new Dictionary<string, object>
            {
                ["clearKeys"] = new List<string> { key }
            };
            Dictionary<string, object> result = SaveSettings(incoming);
            LogOperational("settings.clear_key", new Dictionary<string, object> { ["key"] = key });
            return result;
        }

        private static HashSet<string> SensitiveSettingsKeys()
        {
            return new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "apiKey", "nanoGptApiKey", "openRouterApiKey", "portraitNanoGptApiKey", "portraitAtlasApiKey", "qdrantApiKey" };
        }

        private static bool IsMaskedSecretValue(string value)
        {
            if (string.IsNullOrWhiteSpace(value))
            {
                return false;
            }

            string trimmed = value.Trim();
            return trimmed.Length >= 8 && trimmed.All(ch => ch == '*' || ch == 'x' || ch == 'X' || ch == '•' || ch == '●' || ch == '.' || ch == '|');
        }

        private static Dictionary<string, object> SettingsForUi(Dictionary<string, object> settings)
        {
            Dictionary<string, object> result = new Dictionary<string, object>(settings ?? new Dictionary<string, object>(), StringComparer.OrdinalIgnoreCase);
            foreach (string key in SensitiveSettingsKeys())
            {
                string value = ReadString(settings, key, "");
                bool present = !string.IsNullOrWhiteSpace(value);
                int length = present ? value.Length : 0;
                result[key] = present ? new string('*', Math.Min(Math.Max(length, 12), 32)) : "";
                result[key + "Present"] = present;
                result[key + "Length"] = length;
            }

            result["settingsPath"] = SettingsPath;
            result["dataDir"] = DataDir;
            result["serverProcessFolder"] = AppDomain.CurrentDomain.BaseDirectory;
            result["reasoningPolicy"] = ReasoningPolicyStatus(settings);
            return result;
        }

        private static string SettingsFingerprint(Dictionary<string, object> settings)
        {
            settings = settings ?? LoadSettings();
            string apiKey = LlmApiKey(settings);
            return "llmProvider=" + NormalizeLlmProvider(ReadString(settings, "llmProvider", OpenAiCompatibleProvider))
                + "|apiUrl=" + LlmApiUrl(settings)
                + "|codexExecutable=" + ReadString(settings, "codexExecutable", "codex")
                + "|dialogueModel=" + ModelForRequest(settings, "dialogue")
                + "|constructionModel=" + ModelForRequest(settings, "character_construction")
                + "|constructionMaxTokens=" + ReadInt(settings, "characterConstructionMaxTokens", CharacterConstructionTokenCeiling)
                + "|apiKeyPresent=" + (!string.IsNullOrWhiteSpace(apiKey))
                + "|apiKeyLength=" + apiKey.Length;
        }

        private static Dictionary<string, object> ServerDiagnostics()
        {
            Dictionary<string, object> settings = LoadSettings();
            string apiKey = LlmApiKey(settings);
            string nanoKey = ReadString(settings, "portraitNanoGptApiKey", "");
            string atlasKey = ReadString(settings, "portraitAtlasApiKey", "");
            FileInfo settingsInfo = File.Exists(SettingsPath) ? new FileInfo(SettingsPath) : null;
            Dictionary<string, object> failed = FailedCharacterSummary(ReadString(settings, "latestCampaignId", ""));
            return new Dictionary<string, object>
            {
                ["ok"] = true,
                ["characterSchemaVersion"] = CharacterSchemaVersion,
                ["latestCampaignId"] = LatestCampaignId(),
                ["serverProcessFolder"] = AppDomain.CurrentDomain.BaseDirectory,
                ["dataDir"] = DataDir,
                ["settingsPath"] = SettingsPath,
                ["settingsExists"] = File.Exists(SettingsPath),
                ["settingsLastWriteUtc"] = settingsInfo == null ? "" : settingsInfo.LastWriteTimeUtc.ToString("o"),
                ["settingsRevision"] = ReadString(settings, "settingsRevision", ""),
                ["settingsFingerprint"] = SettingsFingerprint(settings),
                ["llmProvider"] = NormalizeLlmProvider(ReadString(settings, "llmProvider", OpenAiCompatibleProvider)),
                ["codex"] = CodexStatusApi(),
                ["apiUrl"] = LlmApiUrl(settings),
                ["dialogueModel"] = ModelForRequest(settings, "dialogue"),
                ["characterConstructionModel"] = ModelForRequest(settings, "character_construction"),
                ["characterConstructionMaxTokens"] = ReadInt(settings, "characterConstructionMaxTokens", CharacterConstructionTokenCeiling),
                ["apiKeyPresent"] = !string.IsNullOrWhiteSpace(apiKey),
                ["apiKeyLength"] = apiKey.Length,
                ["portraitProvider"] = ReadString(settings, "portraitProvider", "NanoGPT"),
                ["portraitNanoGptImageModel"] = ReadString(settings, "portraitNanoGptImageModel", "gpt-image-1.5"),
                ["portraitAtlasImageModel"] = ReadString(settings, "portraitAtlasImageModel", DefaultAtlasImageModel),
                ["portraitNativeSourceMode"] = ReadString(settings, "portraitNativeSourceMode", "required"),
                ["portraitNativeSourceGeneratorPath"] = ReadString(settings, "portraitNativeSourceGeneratorPath", ""),
                ["sceneryProvider"] = ReadString(settings, "sceneryProvider", "NanoGPT"),
                ["sceneryNanoGptImageModel"] = ReadString(settings, "sceneryNanoGptImageModel", "gpt-image-1.5"),
                ["sceneryAtlasImageModel"] = ReadString(settings, "sceneryAtlasImageModel", DefaultAtlasImageModel),
                ["portraitNanoGptKeyPresent"] = !string.IsNullOrWhiteSpace(nanoKey),
                ["portraitNanoGptKeyLength"] = nanoKey.Length,
                ["portraitAtlasKeyPresent"] = !string.IsNullOrWhiteSpace(atlasKey),
                ["portraitAtlasKeyLength"] = atlasKey.Length,
                ["database"] = ReignPostgreSqlStorage.Diagnostics(),
                ["failedCharacters"] = failed,
                ["characterConstructionPolicy"] = CharacterConstructionPolicyStatus()
            };
        }

        private static Dictionary<string, object> TestLlmKey(Dictionary<string, object> payload)
        {
            Stopwatch timer = Stopwatch.StartNew();
            Dictionary<string, object> settings = LoadSettings();
            string requestType = ReadString(payload, "requestType", "diagnostics");
            Dictionary<string, object> llm = ChatWithLlm(new Dictionary<string, object>
            {
                ["requestType"] = requestType,
                ["maxTokens"] = 24,
                ["temperature"] = 0d,
                ["messages"] = new List<Dictionary<string, object>>
                {
                    new Dictionary<string, object> { ["role"] = "system", ["content"] = "Return strict JSON only." },
                    new Dictionary<string, object> { ["role"] = "user", ["content"] = "Return {\"ok\":true,\"message\":\"diagnostic-ok\"}." }
                },
                ["response_format"] = new Dictionary<string, object> { ["type"] = "json_object" }
            });
            timer.Stop();
            Dictionary<string, object> response = new Dictionary<string, object>
            {
                ["ok"] = ReadBool(llm, "ok", false),
                ["provider"] = ReadString(llm, "provider", NormalizeLlmProvider(ReadString(settings, "llmProvider", OpenAiCompatibleProvider))),
                ["apiUrl"] = LlmApiUrl(settings),
                ["model"] = ReadString(llm, "model", ModelForRequest(settings, requestType)),
                ["apiKeyPresent"] = !string.IsNullOrWhiteSpace(LlmApiKey(settings)),
                ["apiKeyLength"] = LlmApiKey(settings).Length,
                ["providerDurationMs"] = ReadLong(llm, "durationMs", 0),
                ["totalMs"] = timer.ElapsedMilliseconds,
                ["content"] = ReadString(llm, "content", ""),
                ["error"] = ReadString(llm, "error", "")
            };
            LogOperational("diagnostics.test_llm", response);
            return response;
        }

        private static Dictionary<string, object> FailedCharacterSummary(string campaignId)
        {
            campaignId = string.IsNullOrWhiteSpace(campaignId) ? LatestCampaignId() : campaignId;
            string charactersDir = Path.Combine(CampaignDirectory(campaignId), "characters");
            int failedCount = 0;
            List<Dictionary<string, object>> recent = new List<Dictionary<string, object>>();
            if (Directory.Exists(charactersDir))
            {
                foreach (string dir in Directory.GetDirectories(charactersDir))
                {
                    Dictionary<string, object> constructed = ReadJsonObject(Path.Combine(dir, "constructed.json"));
                    if (!string.Equals(ReadString(constructed, "status", ""), "failed", StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    failedCount++;
                    recent.Add(new Dictionary<string, object>
                    {
                        ["heroStringId"] = Path.GetFileName(dir),
                        ["failedUtc"] = ReadString(constructed, "failedUtc", ""),
                        ["failureKind"] = FirstNonEmpty(ReadString(constructed, "failureKind", ""), CharacterFailureKindFromText(ReadString(constructed, "error", ""))),
                        ["settingsRevision"] = ReadString(constructed, "settingsRevision", ""),
                        ["diagnostic"] = LimitText(ReadString(constructed, "diagnostic", ReadString(constructed, "error", "")), 500),
                        ["settingsNewer"] = ShouldRetryFailedConstruction(constructed, LoadSettings())
                    });
                }
            }

            return new Dictionary<string, object>
            {
                ["campaignId"] = campaignId,
                ["failedCount"] = failedCount,
                ["recentFailures"] = recent.OrderByDescending(x => ReadString(x, "failedUtc", "")).Take(20).ToList()
            };
        }

        private static string LatestCampaignId()
        {
            try
            {
				// Registry updated_utc also changes during maintenance and Save Sync,
				// so it is not authoritative for the campaign currently being played.
				// World Test orders real campaigns by their latest native heartbeat.
				Dictionary<string, object> observed = WorldTestCampaignsApi(
					new Dictionary<string, string>());
				string observedId = ReadString(observed, "latestCampaignId", "");
				if (!string.IsNullOrWhiteSpace(observedId)
					&& !observedId.Equals("default", StringComparison.OrdinalIgnoreCase))
					return observedId;
                Dictionary<string, object> latest =
                    ReignPostgreSqlStorage.ListCampaignMetadata().FirstOrDefault(row =>
                    {
                        string campaignId = ReadString(row, "campaignId", "");
                        string directoryPath = CampaignDirectory(campaignId);
                        return Directory.Exists(directoryPath)
                            && IsRealCampaignDirectory(
                                new DirectoryInfo(directoryPath));
                    });
                return latest == null
                    ? "default"
                    : ReadString(latest, "campaignId", "default");
            }
            catch { return "default"; }
        }

        private static Dictionary<string, object> ReadPromptTemplatesApi()
        {
            EnsurePromptTemplates();
            Dictionary<string, object> files = new Dictionary<string, object>();
            List<string> promptNames = ListPromptFileNames();
            foreach (string name in promptNames)
            {
                files[name] = File.ReadAllText(PromptPath(name), Encoding.UTF8);
            }

            return new Dictionary<string, object>
            {
                ["ok"] = true,
                ["promptsDir"] = PromptsDir,
                ["files"] = files,
                ["catalog"] = PromptCatalog(promptNames),
                ["composition"] = PromptCompositionInventory()
            };
        }

        private static Dictionary<string, object> SavePromptTemplatesApi(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            if (ReadBool(payload, "reset", false))
            {
                ResetPromptTemplates();
                LogOperational("prompts.reset", new Dictionary<string, object> { ["promptsDir"] = PromptsDir });
                return ReadPromptTemplatesApi();
            }

            Dictionary<string, object> files = ReadDictionary(payload, "files") ?? payload;
            int saved = 0;
            lock (FileLock)
            {
                Directory.CreateDirectory(PromptsDir);
                foreach (KeyValuePair<string, object> pair in files)
                {
                    string name = Path.GetFileName(pair.Key ?? "");
                    if (!IsPromptFileNameAllowed(name))
                    {
                        continue;
                    }

                    File.WriteAllText(PromptPath(name), Convert.ToString(pair.Value) ?? string.Empty, Encoding.UTF8);
                    saved++;
                }
            }

            LogOperational("prompts.save", new Dictionary<string, object> { ["saved"] = saved, ["promptsDir"] = PromptsDir });
            InvalidatePromptRuntimeCache();
            Dictionary<string, object> response = ReadPromptTemplatesApi();
            response["saved"] = saved;
            return response;
        }

        private static void EnsurePromptTemplates()
        {
            Dictionary<string, string> defaults = DefaultPromptTemplates();
            lock (FileLock)
            {
                Directory.CreateDirectory(PromptsDir);
                RetireLegacyPromptTemplates(PromptsDir);
                MigrateLegacyNoblePromptTemplate();
				MigrateLegacyPortraitIdentity(defaults);
                MigrateLegacyPortraitPromptStyle(defaults);
                foreach (string name in PromptFileNames)
                {
                    string path = PromptPath(name);
                    if (!File.Exists(path))
                    {
                        File.WriteAllText(path, DefaultPromptText(name, defaults), Encoding.UTF8);
                    }
                }
                RemoveSavedPortraitClothingColorGuidance();
            }
        }

        private static void ResetPromptTemplates()
        {
            Dictionary<string, string> defaults = DefaultPromptTemplates();
            lock (FileLock)
            {
                Directory.CreateDirectory(PromptsDir);
                RetireLegacyPromptTemplates(PromptsDir);
                MigrateLegacyNoblePromptTemplate();
                foreach (string name in PromptFileNames)
                {
                    File.WriteAllText(PromptPath(name), DefaultPromptText(name, defaults), Encoding.UTF8);
                }
                InvalidatePromptRuntimeCache();
            }
        }

        private static void MigrateLegacyNoblePromptTemplate()
        {
            string legacyPath = PromptPath("lord_lady_station.txt");
            if (!File.Exists(legacyPath))
            {
                return;
            }

            string noblePath = PromptPath("noble_prompt.txt");
            if (!File.Exists(noblePath))
            {
                File.Move(legacyPath, noblePath);
                LogOperational("prompts.noble_prompt_migrated", new Dictionary<string, object>
                {
                    ["source"] = legacyPath,
                    ["destination"] = noblePath,
                    ["preservedCustomContent"] = true
                });
            }
            else
            {
                string backupPath = noblePath + "." + DateTime.UtcNow.ToString("yyyyMMddHHmmssfff", CultureInfo.InvariantCulture) + ".legacy_backup";
                File.Move(legacyPath, backupPath);
                LogOperational("prompts.noble_prompt_migration_conflict", new Dictionary<string, object>
                {
                    ["source"] = legacyPath,
                    ["destination"] = noblePath,
                    ["legacyBackup"] = backupPath,
                    ["preservedCustomContent"] = true
                });
            }

        }

        private static void MigrateLegacyPortraitPromptStyle(Dictionary<string, string> defaults)
        {
            string path = PromptPath("portrait_prompt_style.txt");
            if (!File.Exists(path) || defaults == null || !defaults.TryGetValue("portrait_prompt_style.txt", out string updated))
            {
                return;
            }

            const string legacy = @"Portrait style is changeable guidance layered around the protected model-specific image request rules.
Keep portraits grounded, human, and believable rather than fantasy illustration.
Preserve the character identity from the source capture: face, age, expression, hair, skin tone, facial structure, and cultural identity.
Prefer chest-up realistic portrait photography, natural skin texture, believable eyes, soft natural light, and culturally appropriate civilian clothing.
Avoid armor, weapons, helmets, chainmail, plastic skin, over-smoothed faces, CGI, cartoon, painterly style, and modern fashion.";
            string current = File.ReadAllText(path, Encoding.UTF8);
            if (string.Equals(current.Trim(), legacy.Trim(), StringComparison.Ordinal))
            {
                File.WriteAllText(path, updated, Encoding.UTF8);
            }
        }

		private static void MigrateLegacyPortraitIdentity(Dictionary<string, string> defaults)
		{
			string path = PromptPath("portrait_identity.txt");
			if (!File.Exists(path) || defaults == null || !defaults.TryGetValue("portrait_identity.txt", out string updated))
			{
				return;
			}

			const string legacy = @"IDENTITY AND SUBJECT
Use the provided source image as the visual identity reference, not as a style reference.
Create a portrait of [CHARACTER NAME], a [GENDER] of [CULTURE] culture who is [AGE] years old.
Preserve the source face, apparent age, expression, eye shape, hair color, hairstyle, skin tone, facial structure, scars, facial hair, and overall identity as closely as possible.
Treat the name, age, gender, and culture as private generation guidance. They describe the subject and must never be printed, captioned, labeled, or otherwise rendered in the image.";
			string current = File.ReadAllText(path, Encoding.UTF8);
			if (string.Equals(current.Trim(), legacy.Trim(), StringComparison.Ordinal))
			{
				File.WriteAllText(path, updated, Encoding.UTF8);
			}
		}

        private static string LoadPromptTemplate(string name)
        {
            return LoadPromptTemplateFromRuntimeCache(name);
        }

        private static string PromptPath(string name)
        {
            return Path.Combine(PromptsDir, Path.GetFileName(name));
        }

        private static List<string> ListPromptFileNames()
        {
            Directory.CreateDirectory(PromptsDir);
            HashSet<string> names = new HashSet<string>(PromptFileNames, StringComparer.OrdinalIgnoreCase);
            foreach (string path in Directory.GetFiles(PromptsDir))
            {
                string name = Path.GetFileName(path);
                if (IsPromptFileNameAllowed(name))
                {
                    names.Add(name);
                }
            }

            return names.OrderBy(x => PromptSortKey(x)).ThenBy(x => x, StringComparer.OrdinalIgnoreCase).ToList();
        }

        private static bool IsPromptFileNameAllowed(string name)
        {
            if (string.IsNullOrWhiteSpace(name) || name.IndexOfAny(Path.GetInvalidFileNameChars()) >= 0)
            {
                return false;
            }

            if (RetiredPromptHashes.ContainsKey(name)) return false;
            string extension = Path.GetExtension(name).ToLowerInvariant();
            return extension == ".txt" || extension == ".json" || extension == ".md";
        }

        private static int PromptSortKey(string name)
        {
            for (int i = 0; i < PromptFileNames.Length; i++)
            {
                if (string.Equals(PromptFileNames[i], name, StringComparison.OrdinalIgnoreCase))
                {
                    return i;
                }
            }

            return 1000;
        }

        private static List<Dictionary<string, object>> PromptCatalog(List<string> promptNames)
        {
            Dictionary<string, Dictionary<string, object>> known = PromptMetadataByName();
            List<Dictionary<string, object>> catalog = new List<Dictionary<string, object>>();
            foreach (string name in promptNames)
            {
                if (known.TryGetValue(name, out Dictionary<string, object> meta))
                {
                    catalog.Add(meta);
                    continue;
                }

                bool hidden = name.EndsWith("_schema.json", StringComparison.OrdinalIgnoreCase) || name.Contains("output_schema");
                bool castleChat = name.StartsWith("castle_chat_", StringComparison.OrdinalIgnoreCase);
                hidden = hidden || castleChat;
                string category = castleChat ? "castle-chat" : name.StartsWith("action_", StringComparison.OrdinalIgnoreCase)
                    ? "action"
                    : (name.StartsWith("relationship_", StringComparison.OrdinalIgnoreCase)
                        ? "relationship"
                        : (name.IndexOf("portrait", StringComparison.OrdinalIgnoreCase) >= 0 || name.IndexOf("image", StringComparison.OrdinalIgnoreCase) >= 0 ? "image" : "general"));
                catalog.Add(PromptMeta(
                    name,
                    HumanizeKey(Path.GetFileNameWithoutExtension(name)),
                    category,
                    !hidden,
                    category == "action"
                        ? "Action-specific selector prompt for " + HumanizeKey(Path.GetFileNameWithoutExtension(name).Replace("action_", "")) + "."
                        : "Additional prompt file found in the server prompts folder."));
            }

            return catalog;
        }

