        private static Dictionary<string, object> TestDict(params object[] pairs)
        {
            Dictionary<string, object> dict = new Dictionary<string, object>();
            AddPairs(dict, pairs);
            return dict;
        }

        private static void AddPairs(Dictionary<string, object> dict, params object[] pairs)
        {
            if (dict == null || pairs == null)
            {
                return;
            }

            for (int i = 0; i + 1 < pairs.Length; i += 2)
            {
                string key = Convert.ToString(pairs[i], CultureInfo.InvariantCulture);
                if (!string.IsNullOrWhiteSpace(key))
                {
                    dict[key] = pairs[i + 1];
                }
            }
        }

        private static ArrayList TestList(params object[] items)
        {
            ArrayList list = new ArrayList();
            if (items != null)
            {
                foreach (object item in items)
                {
                    list.Add(item);
                }
            }

            return list;
        }

        private static string ResolveLogFile(string file, string campaignId)
        {
            string name = Path.GetFileName(string.IsNullOrWhiteSpace(file) ? "server-log.jsonl" : file);
            if (name.Equals("server-log.jsonl", StringComparison.OrdinalIgnoreCase))
            {
                Directory.CreateDirectory(LogsDir);
                return Path.Combine(LogsDir, "server-log.jsonl");
            }

            if (name.Equals("llm-log.jsonl", StringComparison.OrdinalIgnoreCase))
            {
                Directory.CreateDirectory(LogsDir);
                return Path.Combine(LogsDir, name);
            }

            if (name.Equals("events.jsonl", StringComparison.OrdinalIgnoreCase)
                || name.Equals("memories.jsonl", StringComparison.OrdinalIgnoreCase))
            {
                return CampaignFile(ResolveLogCampaignId(campaignId), "world", name);
            }

            if (name.Equals("actions.jsonl", StringComparison.OrdinalIgnoreCase)
                || name.Equals("action-queue.json", StringComparison.OrdinalIgnoreCase))
            {
                return CampaignFile(ResolveLogCampaignId(campaignId), "actions", name);
            }

            if (name.Equals("audit.jsonl", StringComparison.OrdinalIgnoreCase))
            {
                return CampaignFile(ResolveLogCampaignId(campaignId), "audit", "audit.jsonl");
            }

            Directory.CreateDirectory(LogsDir);
            return Path.Combine(LogsDir, "server-log.jsonl");
        }

        private static void LogRequest(HttpRequest request, int status)
        {
            Dictionary<string, object> settings = LoadSettings();
            if (!ReadBool(settings, "enableRequestLogging", true))
            {
                return;
            }

            LogOperational("http.request", new Dictionary<string, object>
            {
                ["method"] = request.Method,
                ["path"] = request.Path,
                ["status"] = status
            });
        }

        private static void LogOperational(string eventType, Dictionary<string, object> data)
        {
            try
            {
                Directory.CreateDirectory(LogsDir);
                Dictionary<string, object> row = new Dictionary<string, object>
                {
                    ["ts"] = DateTimeOffset.UtcNow.ToString("o"),
                    ["eventType"] = eventType,
                    ["data"] = data ?? new Dictionary<string, object>()
                };

                lock (FileLock)
                {
                    AppendBoundedJsonLineToPathLocked(Path.Combine(LogsDir, "server-log.jsonl"), row,
                        16L * 1024L * 1024L, 8L * 1024L * 1024L);
                }
            }
            catch
            {
                // Logging should never interrupt the server.
            }
        }

        private static Dictionary<string, object> RedactSensitive(Dictionary<string, object> source)
        {
            Dictionary<string, object> copy = new Dictionary<string, object>(source ?? new Dictionary<string, object>());
            string[] sensitiveKeys = { "apiKey", "portraitNanoGptApiKey", "portraitAtlasApiKey" };
            foreach (string sensitiveKey in sensitiveKeys)
            {
                if (copy.TryGetValue(sensitiveKey, out object key) && key != null && !string.IsNullOrWhiteSpace(Convert.ToString(key)))
                {
                    copy[sensitiveKey] = "***";
                }
            }

            return copy;
        }

        private static HttpRequest ReadRequest(NetworkStream stream)
        {
            List<byte> bytes = new List<byte>();
            byte[] one = new byte[1];
            while (stream.Read(one, 0, 1) == 1)
            {
                bytes.Add(one[0]);
                int count = bytes.Count;
                if (count >= 4 && bytes[count - 4] == 13 && bytes[count - 3] == 10 && bytes[count - 2] == 13 && bytes[count - 1] == 10)
                {
                    break;
                }
            }

            if (bytes.Count == 0)
            {
                return null;
            }

            string headerText = Encoding.ASCII.GetString(bytes.ToArray());
            string[] lines = headerText.Split(new[] { "\r\n" }, StringSplitOptions.None);
            string[] requestLine = lines[0].Split(' ');
            if (requestLine.Length < 2)
            {
                return null;
            }

            Dictionary<string, string> headers = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            foreach (string line in lines.Skip(1))
            {
                int index = line.IndexOf(':');
                if (index > 0)
                {
                    headers[line.Substring(0, index).Trim()] = line.Substring(index + 1).Trim();
                }
            }

            long length = headers.TryGetValue("Content-Length", out string contentLengthText) && long.TryParse(contentLengthText, out long parsed)
                ? parsed
                : 0;
            string rawTarget = requestLine[1];
            string requestPath = rawTarget.Split('?')[0];
            string contentType = headers.TryGetValue("Content-Type", out string requestedContentType) ? requestedContentType : "";
            string uploadFilePath = "";
            Dictionary<string, object> jsonBody = new Dictionary<string, object>();
            bool binaryCampaignImport = requestPath.Equals("/api/campaigns/import", StringComparison.OrdinalIgnoreCase) && !contentType.StartsWith("application/json", StringComparison.OrdinalIgnoreCase);
            if (binaryCampaignImport && length > 0)
            {
                string uploadRoot = Path.Combine(DataDir, "backups", "uploads");
                Directory.CreateDirectory(uploadRoot);
                uploadFilePath = Path.Combine(uploadRoot, Guid.NewGuid().ToString("N") + ".reignbackup");
                byte[] buffer = new byte[1024 * 1024];
                long remaining = length;
                using (FileStream output = new FileStream(uploadFilePath, FileMode.CreateNew, FileAccess.Write, FileShare.None))
                {
                    while (remaining > 0)
                    {
                        int requestedBytes = (int)Math.Min(buffer.Length, remaining);
                        int n = stream.Read(buffer, 0, requestedBytes);
                        if (n <= 0) break;
                        output.Write(buffer, 0, n);
                        remaining -= n;
                    }
                }
                if (remaining != 0) throw new EndOfStreamException("Campaign backup upload ended before Content-Length bytes were received.");
            }
            else if (length > 0)
            {
                if (requestPath.Equals("/api/support-bundle", StringComparison.OrdinalIgnoreCase) && length > 8 * 1024 * 1024)
                    throw new InvalidDataException("Support report is too large.");
                if (length > int.MaxValue) throw new InvalidDataException("JSON request body is too large.");
                byte[] bodyBytes = new byte[(int)length];
                int read = 0;
                while (read < bodyBytes.Length)
                {
                    int n = stream.Read(bodyBytes, read, bodyBytes.Length - read);
                    if (n <= 0) break;
                    read += n;
                }
                string body = Encoding.UTF8.GetString(bodyBytes, 0, read);
                jsonBody = string.IsNullOrWhiteSpace(body) ? new Dictionary<string, object>() : Json.Deserialize<Dictionary<string, object>>(body);
            }

            return new HttpRequest
            {
                Method = requestLine[0].ToUpperInvariant(),
                ReignProtocol = headers.TryGetValue(Reign.Core.Contracts.Platform.ReignProtocolHandler.HeaderName, out string reignProtocol) ? reignProtocol : "",
                Path = requestPath,
                Query = ParseQuery(rawTarget),
                JsonBody = jsonBody,
                UploadFilePath = uploadFilePath,
                BodyLength = length,
                ContentType = contentType
            };
        }

        private static void WriteFile(NetworkStream stream, string path, string contentType)
        {
            if (!File.Exists(path))
            {
                WriteJson(stream, 404, new Dictionary<string, object> { ["ok"] = false, ["error"] = "File not found." });
                return;
            }

            byte[] body = File.ReadAllBytes(path);
            string header = "HTTP/1.1 200 OK\r\n"
                + "Content-Type: " + contentType + "\r\n"
                + "Content-Length: " + body.Length + "\r\n"
                + "Cache-Control: no-cache\r\n"
                + "Connection: close\r\n\r\n";
            byte[] headerBytes = Encoding.ASCII.GetBytes(header);
            stream.Write(headerBytes, 0, headerBytes.Length);
            stream.Write(body, 0, body.Length);
        }

        private static void WriteJson(NetworkStream stream, int status, object payload)
        {
            string statusText = status == 200 ? "OK" : status == 404 ? "Not Found" : "Server Error";
            byte[] body = Encoding.UTF8.GetBytes(Json.Serialize(payload));
            string header = "HTTP/1.1 " + status + " " + statusText + "\r\n"
                + "Content-Type: application/json; charset=utf-8\r\n"
                + "Content-Length: " + body.Length + "\r\n"
                + "Connection: close\r\n\r\n";
            byte[] headerBytes = Encoding.ASCII.GetBytes(header);
            stream.Write(headerBytes, 0, headerBytes.Length);
            stream.Write(body, 0, body.Length);
        }

        private static void WriteHtml(NetworkStream stream, string html)
        {
            WriteText(stream, 200, "text/html; charset=utf-8", html, null);
        }

        private static void WriteText(NetworkStream stream, int status, string contentType, string text, string downloadName)
        {
            string statusText = status == 200 ? "OK" : status == 404 ? "Not Found" : "Server Error";
            byte[] body = Encoding.UTF8.GetBytes(text ?? string.Empty);
            string header = "HTTP/1.1 " + status + " " + statusText + "\r\n"
                + "Content-Type: " + contentType + "\r\n"
                + "Content-Length: " + body.Length + "\r\n"
                + (string.IsNullOrWhiteSpace(downloadName) ? string.Empty : "Content-Disposition: attachment; filename=\"" + downloadName + "\"\r\n")
                + "Connection: close\r\n\r\n";
            byte[] headerBytes = Encoding.ASCII.GetBytes(header);
            stream.Write(headerBytes, 0, headerBytes.Length);
            stream.Write(body, 0, body.Length);
        }

        private static void AppendJsonLine(string fileName, Dictionary<string, object> row)
        {
            lock (FileLock)
            {
                File.AppendAllText(Path.Combine(DataDir, fileName), Json.Serialize(row) + Environment.NewLine, Encoding.UTF8);
            }
        }

        private static List<Dictionary<string, object>> ReadJsonLines(string fileName)
        {
            string path = Path.Combine(DataDir, fileName);
            return ReadJsonLinesFromPath(path);
        }

        private static List<Dictionary<string, object>> ReadJsonLinesFromPath(string path)
        {
            if (!File.Exists(path))
            {
                return new List<Dictionary<string, object>>();
            }

            lock (FileLock)
            {
                return File.ReadAllLines(path, Encoding.UTF8)
                    .Where(x => !string.IsNullOrWhiteSpace(x))
                    .Select(x => Json.Deserialize<Dictionary<string, object>>(x))
                    .ToList();
            }
        }

        private static Dictionary<string, string> ParseQuery(string rawTarget)
        {
            Dictionary<string, string> result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            int index = rawTarget.IndexOf('?');
            if (index < 0 || index == rawTarget.Length - 1)
            {
                return result;
            }

            string query = rawTarget.Substring(index + 1);
            foreach (string part in query.Split('&'))
            {
                if (string.IsNullOrWhiteSpace(part))
                {
                    continue;
                }

                string[] pieces = part.Split(new[] { '=' }, 2);
                string key = WebUtility.UrlDecode(pieces[0] ?? string.Empty);
                string value = pieces.Length > 1 ? WebUtility.UrlDecode(pieces[1] ?? string.Empty) : string.Empty;
                if (!string.IsNullOrWhiteSpace(key))
                {
                    result[key] = value;
                }
            }

            return result;
        }

        private static string ControlCenterHtml()
        {
            string html = File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "ui", "index.html")).Replace("@IMAGE_PROFILE_CARDS@", ImageProfileCards())
                .Replace("@CHAT_PROVIDER_KEYS@", ChatProviderKeysHtml()).Replace("@CHAT_PROVIDER_SCRIPT@", ChatProviderScript())
                .Replace("@CODEX_PERFORMANCE_CONTROLS@", CodexPerformanceControlCenterHtml())
                .Replace("@CODEX_MODEL_AVAILABILITY@", CodexModelAvailabilityHtml())
                .Replace("@CODEX_PERFORMANCE_SCRIPT@", CodexPerformanceControlCenterScript() + ReignXpOptionsScript())
                .Replace("@REIGN_XP_OPTIONS@", ReignXpOptionsHtml())
                .Replace("@CONVERSATION_DIAGNOSTICS_SCRIPT@", File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "ui", "conversation-diagnostics.js")));
            html = html.Replace("Unified Control Center is always attached", "Managed by ReignServer")
                .Replace("Normal launches always open one dedicated Reign window. Closing it shuts down the server and helper worker; shutting down the server closes it.",
                    "Open this page from the ReignServer launcher. Closing the browser leaves Reign running; use the launcher to manage the service.");
            return html;
        }
        private static string BuildEventJsonForPrompt(Dictionary<string, object> payload)
        {
            payload = payload ?? new Dictionary<string, object>();
            Dictionary<string, object> compact = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
            foreach (string key in new[]
            {
                "eventId", "templateId", "displayName", "settlementId", "hostHeroStringId",
                "speakerHeroStringId", "phaseId", "phaseTitle", "phaseDescription", "eventType",
                "turnId", "isDancePhase", "canInvitePlayerToDance",
                "groupTurnResponses", "groupSpeakerIndex",
                "mustAccountForPriorSpeaker"
            })
            {
                if (payload.ContainsKey(key))
                {
                    compact[key] = payload[key];
                }
            }

            if (payload.ContainsKey("activeHeroIds"))
            {
                compact["activeHeroIds"] = payload["activeHeroIds"];
            }

            HashSet<string> activeHeroIds = new HashSet<string>(ReadStringList(payload, "activeHeroIds"), StringComparer.OrdinalIgnoreCase);
            List<Dictionary<string, object>> promptAttendees = ReadDictionaryList(payload, "attendees")
                .Select((attendee, index) => new { Attendee = attendee, Index = index })
                .OrderByDescending(x => activeHeroIds.Contains(CharacterIdFrom(x.Attendee)))
                .ThenBy(x => x.Index)
                .Select(x => x.Attendee)
                .Take(25)
                .ToList();
            List<Dictionary<string, object>> compactAttendees = new List<Dictionary<string, object>>();
            string currentSpeakerId = ReadFirstString(
                payload, "speakerHeroStringId", "heroStringId");
            Dictionary<string, Dictionary<string, object>>
                participantIdentityViews = ReadDictionaryList(
                        payload,
                        "observerParticipantIdentityViews")
                    .Where(row => !string.IsNullOrWhiteSpace(
                        ReadFirstString(
                            row,
                            "subjectHeroStringId",
                            "subjectId")))
                    .GroupBy(
                        row => ReadFirstString(
                            row,
                            "subjectHeroStringId",
                            "subjectId"),
                        StringComparer.OrdinalIgnoreCase)
                    .ToDictionary(
                        group => group.Key,
                        group => ReadDictionary(
                                group.First(),
                                "identityView")
                            ?? new Dictionary<string, object>(),
                        StringComparer.OrdinalIgnoreCase);
            foreach (Dictionary<string, object> attendee in promptAttendees)
            {
                string attendeeId = CharacterIdFrom(attendee);
                bool self = attendeeId.Equals(
                    currentSpeakerId,
                    StringComparison.OrdinalIgnoreCase);
                Dictionary<string, object> identityView =
                    participantIdentityViews.TryGetValue(
                        attendeeId,
                        out Dictionary<string, object> knownView)
                            ? knownView
                            : new Dictionary<string, object>();
                bool verified = self || ReadBool(
                    identityView,
                    "canonicalNameAllowed", false);
                Dictionary<string, object> compactAttendee =
                    new Dictionary<string, object>
                {
                    ["heroStringId"] = attendeeId,
                    ["observerIdentityState"] = self
                        ? "self"
                        : ReadString(
                            identityView,
                            "identityState",
                            "encountered_unknown"),
                    ["name"] = verified
                        ? ReadString(attendee, "name", "")
                        : FirstNonEmpty(
                            ReadString(
                                identityView,
                                "usableName", ""),
                            ReadString(
                                identityView,
                                "safeLabel", ""),
                            "an unidentified participant")
                };
                if (verified)
                {
                    compactAttendee["clanId"] =
                        ReadString(attendee, "clanId", "");
                    compactAttendee["clanName"] =
                        ReadString(attendee, "clanName", "");
                    compactAttendee["kingdomId"] =
                        ReadString(attendee, "kingdomId", "");
                    compactAttendee["kingdomName"] =
                        ReadString(attendee, "kingdomName", "");
                    compactAttendee["occupation"] =
                        ReadString(attendee, "occupation", "");
                    compactAttendee["isFemale"] =
                        ReadBool(attendee, "isFemale", false);
                    compactAttendee["isRuler"] =
                        ReadBool(attendee, "isRuler", false);
                    compactAttendee["relationToPlayer"] =
                        ReadInt(attendee, "relationToPlayer", 0);
                    compactAttendee["spouseId"] =
                        ReadString(attendee, "spouseId", "");
                    compactAttendee["spouseName"] =
                        ReadString(attendee, "spouseName", "");
                    compactAttendee["fatherId"] =
                        ReadString(attendee, "fatherId", "");
                    compactAttendee["fatherName"] =
                        ReadString(attendee, "fatherName", "");
                    compactAttendee["motherId"] =
                        ReadString(attendee, "motherId", "");
                    compactAttendee["motherName"] =
                        ReadString(attendee, "motherName", "");
                    compactAttendee["childrenIds"] =
                        ReadStringList(attendee, "childrenIds");
                    compactAttendee["childrenNames"] =
                        ReadStringList(attendee, "childrenNames");
                    compactAttendee["sovereignHeroStringId"] =
                        ReadString(attendee, "sovereignHeroStringId", "");
                    compactAttendee["sovereignName"] =
                        ReadString(attendee, "sovereignName", "");
                    compactAttendee["recognizedRoles"] =
                        ReadStringList(
                            ReadDictionary(
                                identityView,
                                "authorityView")
                            ?? new Dictionary<string, object>(),
                            "recognizedRoles");
                }
                compactAttendees.Add(compactAttendee);
            }
            compact["attendees"] = compactAttendees;
            compact["resolverNote"] = "The full action resolution index is intentionally server-side and is not part of the roleplay prompt.";

            string json = Json.Serialize(compact);
            if (json.Length <= 48000)
            {
                return json;
            }

            return Json.Serialize(new Dictionary<string, object>
            {
                ["eventId"] = ReadFirstString(payload, "eventId", "socialEventId"),
                ["templateId"] = ReadString(payload, "templateId", ""),
                ["displayName"] = ReadString(payload, "displayName", ""),
                ["phaseId"] = ReadString(payload, "phaseId", ""),
                ["phaseTitle"] = ReadString(payload, "phaseTitle", ""),
                ["turnId"] = ReadString(payload, "turnId", ""),
                ["attendeeCount"] = compactAttendees.Count,
                ["note"] = "Event metadata was reduced to remain within the prompt budget."
            });
        }

        private static string LlmFailureForDisplay(Dictionary<string, object> llm)
        {
            string raw = ReadString(llm, "error", "");
            if (raw.IndexOf("context_length_exceeded", StringComparison.OrdinalIgnoreCase) >= 0
                || raw.IndexOf("prompt exceeds", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "The AI request contained too much context. Bannerlord Reign stopped the response before any action was taken; check the server logs for the prompt-size breakdown.";
            }

            if (raw.IndexOf("missing_api_key", StringComparison.OrdinalIgnoreCase) >= 0
                || raw.IndexOf("invalid authentication", StringComparison.OrdinalIgnoreCase) >= 0
                || raw.IndexOf("invalid_api_key", StringComparison.OrdinalIgnoreCase) >= 0
                || raw.IndexOf("unauthorized", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "API key missing or rejected. Open Server Diagnostics, save the key, then run Test LLM Key.";
            }

            return "The AI provider request failed. Open Server Diagnostics and the Audit Viewer for details.";
        }

