                ["turnId"] = ReadString(payload, "turnId", ""),
                ["sessionId"] = ReadFirstString(payload, "conversationSessionId", "sessionId"),
                ["exchangeId"] = ReadFirstString(payload, "sceneTurnId", "turnId", "exchangeId")
            };
