                ["version"] = 1,
                ["mood"] = "",
                ["currentPlan"] = "",
                ["currentCrisis"] = "",
                ["politicalAddressConvention"] =
                    new Dictionary<string, object>
                    {
                        ["convention"] = "formal_default",
                        ["sourceExchangeId"] = "",
                        ["worldDay"] = 0d,
                        ["source"] = "default"
                    },
                ["lastKnownSettlementId"] = ReadString(hero, "currentSettlementId", ""),
                ["updatedUtc"] = DateTime.UtcNow.ToString("o")
            };
        }

        private static void UpdateCharacterIndex(string campaignId, Dictionary<string, object> profile)
        {
            UpdateCharacterIndexBatch(campaignId, new[] { profile });
        }

        private static void UpdateCharacterIndexBatch(
            string campaignId,
            IEnumerable<Dictionary<string, object>> profiles)
        {
            string charactersDir = Path.Combine(CampaignDirectory(campaignId), "characters");
            Directory.CreateDirectory(charactersDir);
            string indexPath = Path.Combine(charactersDir, "index.json");
            List<Dictionary<string, object>> incoming = (profiles
                    ?? Enumerable.Empty<Dictionary<string, object>>())
                .Where(x => x != null && !string.IsNullOrWhiteSpace(CharacterIdFrom(x)))
                .GroupBy(CharacterIdFrom, StringComparer.OrdinalIgnoreCase)
                .Select(x => x.Last())
                .ToList();
            if (incoming.Count == 0) return;

            lock (FileLock)
            {
                HashSet<string> replaced = new HashSet<string>(
                    incoming.Select(CharacterIdFrom),
                    StringComparer.OrdinalIgnoreCase);
                ArrayList index = ReadJsonArray(indexPath);
                ArrayList next = new ArrayList();
                foreach (object item in index)
                {
                    Dictionary<string, object> existing = item as Dictionary<string, object>;
                    if (existing == null || !replaced.Contains(CharacterIdFrom(existing)))
                    {
                        next.Add(item);
                    }
                }

                string updatedUtc = DateTime.UtcNow.ToString("o");
                foreach (Dictionary<string, object> profile in incoming)
                {
                    string heroId = CharacterIdFrom(profile);
                    next.Add(new Dictionary<string, object>
                    {
                        ["heroStringId"] = heroId,
                        ["name"] = ReadString(profile, "name", heroId),
                        ["clanId"] = ReadString(profile, "clanId", ""),
                        ["kingdomId"] = ReadString(profile, "kingdomId", ""),
                        ["updatedUtc"] = updatedUtc
                    });
                }
                WriteJsonObject(indexPath, next);
            }
        }

        private static Dictionary<string, object> ReadJsonObject(string path)
        {
            lock (FileLock)
            {
                try
                {
                    if (!File.Exists(path))
                    {
                        return new Dictionary<string, object>();
                    }

                    string text = File.ReadAllText(path, Encoding.UTF8);
                    if (string.IsNullOrWhiteSpace(text))
                    {
                        return new Dictionary<string, object>();
                    }

                    return Json.Deserialize<Dictionary<string, object>>(text) ?? new Dictionary<string, object>();
                }
                catch
                {
                    return new Dictionary<string, object>();
                }
            }
        }

        private static ArrayList ReadJsonArray(string path)
        {
            try
            {
                if (!File.Exists(path))
                {
                    return new ArrayList();
                }

                string text = File.ReadAllText(path, Encoding.UTF8);
                if (string.IsNullOrWhiteSpace(text))
                {
                    return new ArrayList();
                }

                return Json.Deserialize<ArrayList>(text) ?? new ArrayList();
            }
            catch
            {
                return new ArrayList();
            }
        }

        private static void WriteJsonObject(string path, object value)
        {
            ThrowIfCampaignRequestReplaced();
            lock (FileLock)
            {
                string directory = Path.GetDirectoryName(path);
                string serialized = Json.Serialize(value);
                for (int attempt = 0; ; attempt++)
                {
                    Directory.CreateDirectory(directory);
                    // Use a short same-directory name so installed Bannerlord paths
                    // remain below the legacy Win32 path limit.
                    string temp = Path.Combine(
                        directory,
                        "~" + Guid.NewGuid().ToString("N").Substring(0, 8));
                    try
                    {
                        File.WriteAllText(temp, serialized, new UTF8Encoding(false));
                        if (File.Exists(path))
                        {
                            const uint moveFileReplaceExisting = 0x1;
                            const uint moveFileWriteThrough = 0x8;
                            if (!MoveFileEx(temp, path,
                                moveFileReplaceExisting | moveFileWriteThrough))
                                throw new IOException(
                                    "Atomic JSON replacement failed.",
                                    new System.ComponentModel.Win32Exception(
                                        System.Runtime.InteropServices.Marshal.GetLastWin32Error()));
                        }
                        else File.Move(temp, path);
                        break;
                    }
                    catch (DirectoryNotFoundException) when (attempt < 7)
                    {
                        // Save Sync and verification sandboxes replace whole campaign
                        // directories atomically. Retry if the leaf disappears between
                        // the write and replace.
                        Thread.Yield();
                    }
                    catch (IOException) when (attempt < 20)
                    {
                        // Another Reign process (for example a parallel verification
                        // fixture or the vector worker) can briefly have the destination
                        // open. Keep atomic replacement semantics and retry the bounded
                        // transient sharing violation instead of corrupting the profile.
                        Thread.Sleep(Math.Min(100, 5 * (attempt + 1)));
                    }
                    catch (UnauthorizedAccessException) when (attempt < 20)
                    {
                        Thread.Sleep(Math.Min(100, 5 * (attempt + 1)));
                    }
                    finally { TryDeleteFile(temp); }
                }
            }
            MarkSaveSyncActiveStateDirtyForPath(path);
        }

        private static void EnsureJsonObjectFile(string path, Dictionary<string, object> fallback)
        {
            ThrowIfCampaignRequestReplaced();
            lock (FileLock)
            {
                Directory.CreateDirectory(Path.GetDirectoryName(path));
                if (!File.Exists(path))
                {
                    File.WriteAllText(path, Json.Serialize(fallback ?? new Dictionary<string, object>()), Encoding.UTF8);
                }
            }
        }

        private static void EnsureFile(string path)
        {
            ThrowIfCampaignRequestReplaced();
            lock (FileLock)
            {
                Directory.CreateDirectory(Path.GetDirectoryName(path));
                if (!File.Exists(path))
                {
                    File.WriteAllText(path, string.Empty, Encoding.UTF8);
                }
            }
        }

        private static void AppendJsonLineToPath(string path, Dictionary<string, object> row)
        {
            ThrowIfCampaignRequestReplaced();
            lock (FileLock)
            {
                Directory.CreateDirectory(Path.GetDirectoryName(path));
                File.AppendAllText(path, Json.Serialize(row ?? new Dictionary<string, object>()) + Environment.NewLine, Encoding.UTF8);
            }
            MarkSaveSyncActiveStateDirtyForPath(path);
        }

        private static void AppendBoundedJsonLineToPath(
            string path,
            Dictionary<string, object> row,
            long maximumBytes,
            long retainedBytes)
        {
            lock (FileLock)
            {
                AppendBoundedJsonLineToPathLocked(path, row, maximumBytes, retainedBytes);
            }
            MarkSaveSyncActiveStateDirtyForPath(path);
        }

        private static void AppendBoundedJsonLineToPathLocked(
            string path,
            Dictionary<string, object> row,
            long maximumBytes,
            long retainedBytes)
        {
            Directory.CreateDirectory(Path.GetDirectoryName(path));
            CompactTextLogTail(path, maximumBytes, retainedBytes);
            File.AppendAllText(path, Json.Serialize(row ?? new Dictionary<string, object>()) + Environment.NewLine, Encoding.UTF8);
        }

        private static void CompactTextLogTail(string path, long maximumBytes, long retainedBytes)
        {
            if (!File.Exists(path)) return;
            FileInfo info = new FileInfo(path);
            if (info.Length <= Math.Max(1024L, maximumBytes)) return;
            long keep = Math.Max(1024L, Math.Min(retainedBytes, maximumBytes));
            int bufferLength = (int)Math.Min(int.MaxValue, Math.Min(info.Length, keep + 4096L));
            byte[] buffer = new byte[bufferLength];
            using (FileStream stream = new FileStream(path, FileMode.Open, FileAccess.ReadWrite, FileShare.Read))
            {
                stream.Seek(-bufferLength, SeekOrigin.End);
                int read = 0;
                while (read < buffer.Length)
                {
                    int amount = stream.Read(buffer, read, buffer.Length - read);
                    if (amount <= 0) break;
                    read += amount;
                }
                int start = 0;
                if (info.Length > bufferLength)
                {
                    while (start < read && buffer[start] != (byte)'\n') start++;
                    if (start < read) start++;
                }
                stream.SetLength(0);
                stream.Position = 0;
                stream.Write(buffer, start, Math.Max(0, read - start));
                stream.Flush(true);
            }
        }

        private static void CompactOperationalLogsAtStartup()
        {
            lock (FileLock)
            {
                Directory.CreateDirectory(LogsDir);
                CompactTextLogTail(Path.Combine(LogsDir, "server-log.jsonl"),
                    16L * 1024L * 1024L, 8L * 1024L * 1024L);
                CompactTextLogTail(Path.Combine(LogsDir, "llm-log.jsonl"),
                    16L * 1024L * 1024L, 8L * 1024L * 1024L);
            }
        }

        private static List<string> SimpleTags(string text)
        {
            string lowered = (text ?? "").ToLowerInvariant();
            string[] candidates = { "war", "peace", "tribute", "siege", "army", "betrayal", "oath", "marriage", "fief", "ransom", "trade", "recruit" };
            return candidates.Where(lowered.Contains).ToList();
        }

        private static string ReadString(Dictionary<string, object> source, string key, string fallback)
        {
            return source != null && source.TryGetValue(key, out object value) && value != null ? Convert.ToString(value) : fallback;
        }

        private static int ReadInt(Dictionary<string, object> source, string key, int fallback)
        {
            if (source == null || !source.TryGetValue(key, out object value) || value == null)
            {
                return fallback;
            }

            string text = Convert.ToString(value);
            if (int.TryParse(text, NumberStyles.Integer | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out int parsed))
            {
                return parsed;
            }

            if (int.TryParse(text, NumberStyles.Integer | NumberStyles.AllowThousands, CultureInfo.CurrentCulture, out parsed))
            {
                return parsed;
            }

            string digits = new string((text ?? string.Empty).Where(char.IsDigit).ToArray());
            return int.TryParse(digits, out parsed) ? parsed : fallback;
        }

        private static long ReadLong(Dictionary<string, object> source, string key, long fallback)
        {
            return source != null && source.TryGetValue(key, out object value) && value != null && long.TryParse(Convert.ToString(value), out long parsed) ? parsed : fallback;
        }

        private static bool ReadBool(Dictionary<string, object> source, string key, bool fallback)
        {
            if (source == null || !source.TryGetValue(key, out object value) || value == null)
            {
                return fallback;
            }

            if (value is bool boolValue)
            {
                return boolValue;
            }

            return bool.TryParse(Convert.ToString(value), out bool parsed) ? parsed : fallback;
        }

        private static double ReadDouble(Dictionary<string, object> source, string key, double fallback)
        {
            return source != null && source.TryGetValue(key, out object value) && value != null && double.TryParse(Convert.ToString(value), out double parsed) ? parsed : fallback;
        }

        private static string ReadFirstString(Dictionary<string, object> source, params string[] keys)
        {
            if (source == null || keys == null)
            {
                return string.Empty;
            }

            foreach (string key in keys)
            {
                string value = ReadString(source, key, "");
                if (!string.IsNullOrWhiteSpace(value))
                {
                    return value;
                }
            }

            return string.Empty;
        }

        private static List<Dictionary<string, object>> ReadDictionaryList(Dictionary<string, object> source, string key)
        {
            if (source == null || !source.TryGetValue(key, out object value) || value == null)
            {
                return new List<Dictionary<string, object>>();
            }

            if (value is ArrayList array)
            {
                return array.Cast<object>().OfType<Dictionary<string, object>>().ToList();
            }

            if (value is IEnumerable<object> enumerable)
            {
                return enumerable.OfType<Dictionary<string, object>>().ToList();
            }

            Dictionary<string, object> single = value as Dictionary<string, object>;
            return single == null ? new List<Dictionary<string, object>>() : new List<Dictionary<string, object>> { single };
        }
        private static List<string> ReadStringList(Dictionary<string, object> source, string key)
        {
            if (source == null || !source.TryGetValue(key, out object value) || value == null)
            {
                return new List<string>();
            }

            if (value is ArrayList array)
            {
                return array.Cast<object>().Select(Convert.ToString).Where(x => !string.IsNullOrWhiteSpace(x)).ToList();
            }

            if (value is IEnumerable<object> enumerable)
            {
                return enumerable.Select(Convert.ToString).Where(x => !string.IsNullOrWhiteSpace(x)).ToList();
            }

            string text = Convert.ToString(value);
            return string.IsNullOrWhiteSpace(text) ? new List<string>() : new List<string> { text };
        }

        private static Dictionary<string, object> ReadDictionary(Dictionary<string, object> source, string key)
        {
            if (source == null || !source.TryGetValue(key, out object value))
            {
                return null;
            }

            return value as Dictionary<string, object>;
        }

        private sealed class HttpRequest
        {
            public string ReignProtocol;
            public string Method;
            public string Path;
            public Dictionary<string, string> Query;
            public Dictionary<string, object> JsonBody;
            public string UploadFilePath;
            public long BodyLength;
            public string ContentType;
        }
    }
}
